P.entries["quest:719"] = {n="Ein Zwerg und sein Werkzeug",s="Ausgrabungsleiter Roggendol entkam einem Angriff auf seine Ausgrabungsstätte und sucht nun seine Glücksspitzhacke. Überall sind Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln.",h="Ausgrabungsleiter Roggendol entkam einem Angriff auf seine Ausgrabungsstätte und sucht nun seine...",kw={"ödland","dunkeleisen","ausgrabung","hammertoe","glücksspitzhacke","roggendol","shadowforge"},sec={{t="Angreifer an der Ausgrabung",b="Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln, griffen die Ausgrabungsstätte an, an der Roggendol arbeitete. Fast alle starben, darunter auch sein Boss Hammertoe. Roggendol kam nur knapp mit dem Leben davon. Die Stätte liegt nördlich von seinem Warteplatz."},{t="Eine Glücksspitzhacke",b="Ausgrabungsleiter Roggendol versucht, die beim Angriff verlorenen Vorräte zurückzubekommen, besonders seine Glücksspitzhacke. Einer der Dunkeleisenzwerge hat sie, doch Roggendol weiß nicht, welcher. Er hofft, dass Ihr helft, und wartet südlich von Hammertoes Dig Site."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol arbeitete an einer Ausgrabungsstätte, die von Dunkeleisenzwergen angegriffen wurde. Er entkam nur knapp und wartet nun südlich von Hammertoes Dig Site.",al={"wer ist roggendol","ausgrabungsleiter roggendol","wer vergibt ein zwerg und sein werkzeug"}},{q="Wer hat das Ausgrabungslager angegriffen?",a="Dunkeleisenzwerge, die dem Shadowforge-Klan ähneln, griffen die Ausgrabungsstätte an.",al={"wer hat die ausgrabung angegriffen","wer hat hammertoe angegriffen","was hat das lager angegriffen"}},{q="Was ist mit Hammertoe geschehen?",a="Hammertoe war Roggendols Boss und gehörte zu denen, die bei dem Angriff getötet wurden.",al={"wer ist hammertoe","lebt hammertoe noch","was ist mit boss hammertoe geschehen"}},{q="Wo befindet sich die Glücksspitzhacke?",a="Roggendol glaubt, dass einer der Dunkeleisenzwerge die Glücksspitzhacke hat, doch er weiß nicht, welcher.",al={"wo ist roggendols glücksspitzhacke","wie die spitzhacke finden","wer hat roggendols spitzhacke"}}},fp="21,147,18.228.0,12.234.0,25.140.0,33.79.0,27.69.0,32.99.0"}
P.entries["quest:72"] = {n="Die Legende von Stalvan",s="In Sturmwind sucht Ihr unter den Habseligkeiten der Flintridges nach Stalvan Dunstmantel. An den Kanälen bergen versiegelte Kisten die Überreste des Hausstands, bewacht von ruhelosen Geistern, die an das Massaker gebunden sind.",h="In Sturmwind sucht Ihr unter den Habseligkeiten der Flintridges nach Stalvan Dunstmantel.",kw={"canals","verwalter folsom","dämmerwald","flintridge","unglückseliger geist","die legende von stalvan","massaker","versiegelte kiste","sturmwind","tilloa"},ang={["class:Priest"]="Als Priester stellt Ihr Euch dem weinenden Unglückseligen Geist in den Stadtkanälen. Seine Qual ist die unschuldiger Seelen, die vor ihrer Zeit ermordet wurden, und er verlangt Frieden vom Licht.",["faction:Alliance"]="Die Tragödie der Flintridges entfaltet sich in Sturmwind, der Hauptstadt des Königreichs, wo Gewalt selbst die behütetsten Adelsgeschlechter zugrunde richten kann."},sec={{t="Nachhall eines Massakers",b="Ihr folgt Stalvans Spur vom Dämmerwald nach Sturmwind. An den Stadtkanälen bewacht Verwalter Folsom die Überreste des Hausstands der Flintridges. Schon sein Vater diente auf dem Anwesen und musste Blut aufwischen, nachdem ein Massaker den gesamten Haushalt dahingerafft hatte. Irgendwie ist Stalvans Name mit diesem Gemetzel verbunden."},{t="Versteigerung eines ruinierten Hauses",b="Das Treuhandvermögen der Flintridges ist aufgebraucht, und königliche Steuereintreiber setzen das Anwesen unter Druck. Gerettete Erbstücke und verpackte Habseligkeiten warten in versiegelten Versandkisten am Kanalufer auf ihre Versteigerung. Ihr durchsucht sie nach Stalvans Spur, bevor sich der verbliebene Familienbesitz unter Sammlern im ganzen Königreich verteilt."},{t="Ein ruheloser Schatten",b="Ein Unglückseliger Geist greift jeden an, der die Kisten der Flintridges anrührt. Das Trauma der Morde haftet an den geretteten Besitztümern der Familie. Viele glauben, die weinende Erscheinung sei der Schatten der jungen Tilloa Flintridge, noch immer an Relikte ihres jäh beendeten Lebens gebunden."}},faq={{q="Wo finde ich Verwalter Folsom?",a="Verwalter Folsom wacht an den Canals in Sturmwind über die Güter der Flintridges, nahe den am Wasser gestapelten Versandkisten.",al={"verwalter folsom fundort","wo ist folsom","wo ist verwalter folsom in sturmwind"}},{q="Was ist der Familie Flintridge zugestoßen?",a="Ein plötzliches Massaker riss den wohlhabenden Haushalt der Flintridges auseinander. Verwalter Folsom erzählt, sein Vater habe danach das Blut aufwischen müssen. Wer dafür verantwortlich war, bleibt unklar.",al={"massaker an den flintridges","was war das massaker","wer hat die familie flintridge getötet"}},{q="Warum sind die Besitztümer der Familie in Kisten am Kanal verpackt?",a="Das Treuhandvermögen der Flintridges war nach der Tragödie aufgebraucht. Auf Druck der Steuereintreiber des Königreichs wurden ihre verbliebenen Habseligkeiten zur Versteigerung in Kisten an den Kanälen verpackt.",al={"warum flintridge-besitz versteigern","warum stehen kisten an den kanälen","treuhandvermögen der flintridges"}},{q="Warum greift ein Geist an, wenn die Kiste geöffnet wird?",a="Das Trauma des Massakers band die Seelen der Opfer an ihre einstigen Besitztümer. Ein Unglückseliger Geist greift an, um die Kisten zu verteidigen, und viele halten ihn für den Schatten von Tilloa Flintridge, einem der ermordeten Kinder.",al={"unglückseliger geist sturmwind","wer ist der unglückselige geist","warum geist in sturmwinds kanälen"}},{q="Wie hängt das mit dem Dämmerwald zusammen?",a="Die Untersuchung begann in Dunkelhain mit der Suche nach Stalvan Dunstmantel. Seine Vergangenheit führte zu seiner Zeit als Hauslehrer der Familie Flintridge in Elwynn und Sturmwind.",al={"stalvan dämmerwald verbindung","warum sind wir für eine dämmerwald-quest in sturmwind","die legende von stalvan verbindung zur stadt"}},{q="Was findet Ihr in der versiegelten Kiste?",a="Die Kiste birgt muffige Erbstücke zwischen verpackten Möbeln und persönlichen Habseligkeiten. Nahe dem Boden findet Ihr eine herausgerissene Seite aus Stalvans Tagebuch, den nächsten Hinweis.",al={"was ist in der kiste","versiegelte kiste hinweis","inhalt der flintridge-kiste"}}},fx={d6eccd2d={q="Warum lässt Verwalter Folsom Euch die Kisten durchsuchen?",a="Verwalter Folsom hat persönlich nicht mehr viel, um das er sich kümmern müsste. Die Stiftung der Familie Flintridge ist völlig versiegt, was ihr verbleibendes Anwesen in Ruinen hinterlässt und ihren letzten Besitz für das Auktionshaus bestimmt, um Steuereintreiber zu befriedigen. Während seine Familie dem Anwesen über Generationen diente – sein Vater hatte das Blut nach dem grausamen Massaker beseitigt –, hat Folsom selbst keinen Grund, die düstere Wahrheit zu verbergen, und gestattet Eurer Neugier einfach, das zu durchwühlen, was übrig geblieben ist.",al={"beweggrund verwalter folsom","warum hilft folsom","warum kisten durchsuchen lassen"}}},fp="21,200,20.302.0,29.320.0,16.262.1,34.133.0,39.167.0,66.167.0,50.210.0,39.167.0,41.155.0"}
P.entries["quest:720"] = {n="Ein Hoffnungsschimmer",s="Hammertoe Grez lebt, und ein Hilferuf in Kreide auf einer zerknitterten Karte bittet Ausgrabungsleiter Roggendol um Hilfe. Die Notiz besagt, dass sie Hammertoe nach Uldaman bringen.",h="Hammertoe Grez lebt, und ein Hilferuf in Kreide auf einer zerknitterten Karte bittet Ausgrabungsleiter...",kw={"ein hoffnungsschimmer","ödland","kreidenotiz","zerknitterte karte","hammertoe grez","ausgrabungsleiter roggendol","uldaman"},sec={{t="Worte in Kreide",b="Hammertoe hinterlässt auf einer zerknitterten Karte einen kurzen Hilferuf in Kreide für Roggendol. Die Notiz besagt, dass sie Hammertoe nach Uldaman bringen, und bittet um Hilfe. Sagt Ausgrabungsleiter Roggendol, dass Hammertoe Grez lebt."}},faq={{q="Was steht auf der zerknitterten Karte?",a="Hammertoes Kreidenotiz ist an Roggendol gerichtet. Sie besagt, dass sie Hammertoe nach Uldaman bringen, und bittet um Hilfe.",al={"was steht in der notiz","kreidenachricht auf karte","text der zerknitterten karte"}},{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol ist derjenige, an den die Notiz gerichtet ist. Findet ihn und sagt ihm, dass Hammertoe Grez lebt.",al={"wer ist roggendol","wohin die zerknitterte karte bringen"}},{q="Wohin wird Hammertoe Grez laut der Nachricht gebracht?",a="Die Nachricht besagt, dass Hammertoe Grez nach Uldaman gebracht wird.",al={"wohin wird hammertoe gebracht","wohin wird grez gebracht"}}},fp="14,141,14.188.0,36.110.0,25.97.0,57.58.0"}
P.entries["quest:723"] = {n="Ein Funken Hoffnung",s="Im Ödland schickt Euch Hammertoe Grez mit seinem Amulett zu Ausgrabungsleiter Roggendol. Roggendol weiß, dass Hammertoe nach den Ursprüngen ihres Volkes suchte, und will die Schriftrollen vor dem Shadowforge-Clan bewahren.",h="Im Ödland schickt Euch Hammertoe Grez mit seinem Amulett zu Ausgrabungsleiter Roggendol.",kw={"a sign of hope","ödland","hammertoe grez","hammertoes amulett","ursprünge","ausgrabungsleiter roggendol","shadowforge"},sec={{t="Ein Amulett für Roggendol",b="Verwundet im Ödland bittet Euch Hammertoe Grez, sein Amulett zu Roggendol zu bringen. Er vertraut darauf, dass Roggendol weiß, was zu tun ist. Hammertoe suchte nach den Ursprüngen ihres Volkes und wollte die Pläne des Shadowforge-Clans durchkreuzen. Der Clan darf die Schriftrollen nicht bekommen."},{t="In Roggendols Händen",b="Als Roggendol Hammertoes Amulett erhält, sagt er, die Stimmung sei besser gewesen, als Hammertoe noch für tot gehalten wurde. Die Gewissheit vertieft seinen Schmerz nur noch. Roggendol nennt das Amulett Hammertoes Lebenswerk und schwört, dass sein Tod nicht vergebens sein wird."}},faq={{q="Wer ist Ausgrabungsleiter Roggendol?",a="Ausgrabungsleiter Roggendol ist derjenige im Ödland, dem Ihr Hammertoes Amulett bringen sollt. Er weiß, wonach Hammertoe suchte.",al={"ausgrabungsleiter roggendol","wer ist roggendol","wo ist roggendol"}},{q="Was versucht Hammertoe Grez zu verhindern?",a="Hammertoe wollte die Pläne des Shadowforge-Clans durchkreuzen, der die Schriftrollen nicht in die Hände bekommen darf.",al={"hammertoes ziel","shadowforge schriftrollen","warum shadowforge aufhalten"}},{q="Wonach suchte Hammertoe Grez?",a="Hammertoe suchte nach den Ursprüngen ihres Volkes.",al={"hammertoe ursprünge","wonach suchte hammertoe"}},{q="Zu welcher Questreihe gehört dieser Schritt?",a="Dieser Schritt gehört zu der Questreihe, die mit A Sign of Hope begann.",al={"ein funken hoffnung questreihe","a sign of hope questreihe"}}},fp="17,194,20.238.0,17.232.1,25.121.0,38.87.0,32.50.0,33.62.0"}
P.entries["quest:724"] = {n="Ein Funken Hoffnung",s="Im Ödland schickt Euch Ausgrabungsleiter Roggendol mit Hammertoes Amulett nach Eisenschmiede. Historiker Karnik und Hammertoe suchten gemeinsam nach Uldamans verlorenen Artefakten. Roggendol vermutet, dass die Shadowforge herausfanden, dass die beiden mehr wussten, als sie zugaben.",h="Im Ödland schickt Euch Ausgrabungsleiter Roggendol mit Hammertoes Amulett nach Eisenschmiede.",kw={"ödland","hammertoe","hammertoes amulett","historiker karnik","eisenschmiede","ein funken hoffnung","ausgrabungsleiter roggendol","shadowforge","uldaman"},sec={{t="Eine Nachricht für Eisenschmiede",b="Ausgrabungsleiter Roggendol schickt Euch zu Historiker Karnik in Eisenschmiede. Erzählt Karnik, was mit Hammertoe geschehen ist, und legt das Amulett in seine Hände. Karnik wird entscheiden, was als Nächstes zu tun ist."},{t="Karniks Begrüßung",b="Historiker Karnik will sich keine weitere Reisegeschichte anhören, bis er das Amulett sieht. Dann stellt er seine Trauer um Hammertoe zurück und ruft Hammertoes Geist herbei, um Euch den Wert des Amuletts zu zeigen."}},faq={{q="Wer vergibt diese Quest?",a="Ausgrabungsleiter Roggendol im Ödland schickt Euch mit Hammertoes Amulett nach Eisenschmiede.",al={"wer vergibt ein funken hoffnung","ein funken hoffnung questgeber","wo beginnt ein funken hoffnung"}},{q="Wo befindet sich Historiker Karnik?",a="Historiker Karnik befindet sich in Eisenschmiede.",al={"wo ist karnik","historiker karnik standort","karnik eisenschmiede"}},{q="Warum wurde Historiker Karnik ausgewählt?",a="Karnik und Hammertoe suchten gemeinsam nach Uldamans verlorenen Artefakten, daher vertraut Roggendol darauf, dass Karnik weiß, was als Nächstes zu tun ist.",al={"warum das amulett zu karnik schicken","karniks verbindung"}},{q="Was kommt nach dieser Quest?",a="Karniks Geschichte geht mit Passing Word of a Threat weiter.",al={"nächste quest nach ein funken hoffnung","was folgt auf ein funken hoffnung"}}},fp="17,228,23.171.0,16.190.1,22.81.0,34.33.0,32.111.0,28.55.0"}
P.entries["quest:725"] = {n="Kunde über die Bedrohung breitet sich aus",s="Karnik schickt Euch mit einer versiegelten Nachricht zu Berater Belgrum. Berichtet Belgrum, was Ihr mitangesehen habt, und fragt nach dem weiteren Vorgehen, während Karnik bei Hammertoes Geist nach Antworten sucht.",h="Karnik schickt Euch mit einer versiegelten Nachricht zu Berater Belgrum.",kw={"berater belgrum","ödland","hammertoe","historiker karnik","eisenschmiede","kunde über die bedrohung breitet sich aus","shadowforge"},sec={{t="Kunde für Berater Belgrum",b="Historiker Karnik braucht Euch, um Berater Belgrum schnell zu erreichen. Berichtet ihm, was Ihr mitangesehen habt, und fragt, wie er weiter vorgehen möchte. Die versiegelte Nachricht erklärt Näheres.\n\nUnterdessen spricht Karnik mit Hammertoes Geist und hofft zu erfahren, wie sich den Machenschaften der Shadowforge im Ödland ein Ende setzen lässt. Er kann nur beten, dass Hammertoe etwas weiß, das helfen wird."}},faq={{q="Wer schickt Euch zu Berater Belgrum?",a="Historiker Karnik gibt Euch eine versiegelte Nachricht und bittet Euch, Berater Belgrum so schnell wie möglich zu finden.",al={"wer startet kunde über die bedrohung breitet sich aus","wer vergibt kunde über die bedrohung breitet sich aus","karnik quest"}},{q="Was möchte Karnik von Berater Belgrum?",a="Karnik möchte, dass Ihr Belgrum berichtet, was Ihr mitangesehen habt, und fragt, wie er weiter vorgehen möchte. Die Nachricht erklärt Näheres.",al={"warum belgrum aufsuchen","zweck der nachricht für belgrum","warum die nachricht schicken"}},{q="Was tut Historiker Karnik, während Ihr die Nachricht überbringt?",a="Während Ihr die Nachricht überbringt, spricht Karnik mit Hammertoes Geist und hofft zu erfahren, wie sich die Shadowforge im Ödland aufhalten lassen.",al={"was tut karnik","karniks plan","historiker karnik ödland"}},{q="Welche Quest kommt vor Kunde über die Bedrohung breitet sich aus?",a="Kunde über die Bedrohung breitet sich aus folgt auf Prospect of Faith, bei der Ihr Hammertoes Amulett zu Karnik in Eisenschmiede bringt.",al={"kunde über die bedrohung voraussetzung","kunde über die bedrohung breitet sich aus vorherige quest","vorherige quest"}}},fp="24,162,24.336.0,33.100.0,43.108.0,58.124.0,49.109.0"}
P.entries["quest:726"] = {n="Kunde über die Bedrohung breitet sich aus",s="Im Ödland schickt Belgrum Euch mit dem Befehl des Königs zu Karnik zurück, rasch gegen die Schattenschmiede vorzugehen.",h="Im Ödland schickt Belgrum Euch mit dem Befehl des Königs zu Karnik zurück, rasch gegen die Schattenschmiede...",kw={"festung angor","ödland","belgrum","karnik","schattenschmiede","uldaman"},sec={{t="Belgrums Antwort",b="Belgrum liest Karniks Notiz bis zum Ende. Bei der unheilvollen Kunde weiten sich seine Augen. Er schickt Euch mit dem Befehl des Königs zu Karnik zurück: Handelt nach den vorliegenden Erkenntnissen rasch und entschlossen. Die Aktivitäten der Schattenschmiede im Ödland müssen aufhören."},{t="Karniks Erwiderung",b="Karnik versteht die Dringlichkeit als die des Königs selbst und hat einen Plan bereit. Die Schattenschmiede operiert von der Festung Angor aus. Ein Schlag dort kann ihre Arbeit in Uldaman verlangsamen."}},faq={{q="Wer schickt Euch zu Karnik zurück?",a="Berater Belgrum schickt Euch zurück, nachdem er Karniks Notiz gelesen hat. Ihr überbringt den Befehl des Königs, rasch und entschlossen zu handeln.",al={"wer gibt den befehl","belgrums befehle","königliche autorität ödland"}},{q="Was will Belgrum gegen die Schattenschmiede unternehmen lassen?",a="Belgrum will, dass Karnik rasch und entschlossen handelt, um die Aktivitäten der Schattenschmiede im Ödland zu beenden.",al={"was will belgrum","schattenschmiede ödland befehl"}},{q="Was geschah zuvor?",a="Ihr habt Karniks versiegelte Notiz im früheren „Kunde über die Bedrohung breitet sich aus“ zu Berater Belgrum gebracht, nach den Schritten von Prospect of Faith.",al={"vorheriger schritt","quest vor kunde über die bedrohung breitet sich aus","vorgeschichte ödland"}}},fp="24,113,16.229.0,14.154.1,29.119.0,50.99.0,22.127.0"}
P.entries["quest:727"] = {n="Auf nach Eisenschmiede zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede. In einem Laden in der Forlorn Cavern soll Gerrig Knochengriff Euch für einen der Leute halten, vor denen Theldurin floh, damit Ihr ihn nach Yagyins Zusammenstellung fragen könnt.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen nach Eisenschmiede.",kw={"ödland","forlorn cavern","gerrig knochengriff","eisenschmiede","siegelzeichen des hammers","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein vor langer Zeit geschriebenes Buch",b="Die Tafel hat Theldurin viel gelehrt, doch Fragen bleiben offen. Yagyin verfasste vor langer Zeit eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften auf. Ihre Gelehrtesten studieren sie. Theldurin glaubt, dass ihr gewaltiges Wissen Schutz bieten kann, und möchte deshalb, dass Ihr sie zurückbringt."},{t="Der Laden in der Forlorn Cavern",b="Gerrig Knochengriff betreibt einen Laden in der Forlorn Cavern von Eisenschmiede. Theldurin gibt Euch das Siegelzeichen des Hammers, um es Gerrig zu zeigen. Dann sollte Gerrig Euch für einen der Leute halten, vor denen Theldurin floh. Fragt ihn nach Yagyins Zusammenstellung."},{t="Gerrigs Begrüßung",b="Gerrig Knochengriff warnt Euch, darauf zu achten, was Ihr im Laden berührt. Wissen kann tödlich sein. Wenn Ihr das Siegelzeichen zeigt, begrüßt Gerrig Euch als Bruder oder Schwester und preist jene, die in der Tiefe weilen."}},faq={{q="Warum will Theldurin Yagyins Zusammenstellung haben?",a="Die Tafel verrät Theldurin viel, lässt jedoch Fragen offen. Yagyins vor langer Zeit verfasste Zusammenstellung birgt gewaltiges Wissen, das Schutz bieten kann. Theldurin möchte, dass Ihr sie zurückbringt.",al={"warum wird yagyins zusammenstellung gebraucht","was ist yagyins zusammenstellung","zweck von yagyins zusammenstellung"}},{q="Wo ist Gerrig Knochengriff?",a="In der Forlorn Cavern von Eisenschmiede, wo er einen Laden betreibt.",al={"wo ist gerrig knochengriff","gerrig knochengriff standort","wer ist gerrig"}},{q="Wofür wird das Siegelzeichen des Hammers verwendet?",a="Theldurin gibt Euch das Siegelzeichen des Hammers, um es Gerrig Knochengriff zu zeigen. Er möchte, dass Gerrig Euch für einen der Leute hält, vor denen Theldurin floh.",al={"was bewirkt das siegelzeichen","verwendung des siegelzeichens des hammers","warum das siegelzeichen verwenden"}},{q="Wo gehört dies in die Questreihe?",a="Es folgt auf Solution to Doom bei Theldurin dem Verirrten. Die Questreihe geht mit dem nächsten Schritt weiter.",al={"was kommt vor auf nach eisenschmiede zu 'yagyins zusammenstellung'","reihenfolge der questreihe yagyin"}}},fp="32,203,23.272.0,30.214.0,17.185.1,40.186.0,25.53.0,41.134.0,33.92.0"}
P.entries["quest:728"] = {n="Auf nach Unterstadt zu 'Yagyins Zusammenstellung'",s="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen für Bewahrer Bel'dugur in die Unterstadt von Lordaeron. Er will, dass der Bewahrer Euch für einen der Leute hält, vor denen er floh, und bittet Euch, Yagyins Zusammenstellung zu finden.",h="Theldurin der Verirrte schickt Euch mit einem Siegelzeichen für Bewahrer Bel'dugur in die Unterstadt von...",kw={"ödland","bel'dugur","zusammenstellung","hammer","siegelzeichen","theldurin","unterstadt","yagyin"},sec={{t="Ein vor Urzeiten verfasstes Buch",b="Die Tafel hat Theldurin vieles beantwortet, doch Fragen bleiben offen. Yagyin verfasste vor Urzeiten eine Zusammenstellung, und die Leute, vor denen Theldurin floh, bewahren an vielen Orten Abschriften davon auf. Ihre Gelehrtesten studieren die Seiten. Theldurin glaubt, dass das umfassende Wissen darin sie beschützen kann, und will deshalb, dass Ihr die Zusammenstellung zurückbringt."},{t="Der Bewahrer in Unterstadt",b="Bewahrer Bel'dugur wartet in der Unterstadt von Lordaeron. Theldurin gibt Euch das Siegelzeichen des Hammers, damit Ihr es dem Bewahrer zeigt, der Euch für einen der Leute halten soll, vor denen Theldurin floh. Fragt Bel'dugur nach der Zusammenstellung."},{t="Ein Wort der Vorsicht",b="Bewahrer Bel'dugur begrüßt Euch als eifrigen Sucher der Sammlung. Wissen, so warnt der Bewahrer, verleiht den Starken Macht, treibt die Schwachen jedoch in den Wahnsinn. Nachdem Ihr das Siegelzeichen vorgezeigt habt, mahnt Bel'dugur Euch, mit solchen Zeichen diskret umzugehen. Einige zweifeln an der Rechtschaffenheit ihres Gelöbnisses, während andere sie scheitern sehen wollten, wenn sie davon wüssten. Wer das Gelöbnis teilt, muss vorsichtig, wachsam und geduldig sein."}},faq={{q="Wer schickt Euch nach Unterstadt?",a="Theldurin der Verirrte schickt Euch los, um Bewahrer Bel'dugur zu finden, und gibt Euch das Siegelzeichen des Hammers mit.",al={"wer startet diese quest","wer vergibt to the undercity for yagyin's digest","questgeber"}},{q="Wozu dient das Siegelzeichen des Hammers?",a="Theldurin gibt Euch das Siegelzeichen des Hammers, damit Ihr es Bewahrer Bel'dugur zeigt und dieser Euch für einen der Leute hält, vor denen Theldurin floh.",al={"verwendung des siegelzeichens des hammers","warum brauche ich das siegelzeichen","was bewirkt das siegelzeichen"}},{q="Was ist Yagyins Zusammenstellung?",a="Yagyins Zusammenstellung ist ein Buch, das Yagyin vor Urzeiten verfasste. Theldurin sagt, es berge umfassendes Wissen, das die Gelehrtesten unter den Leuten studieren, vor denen er floh.",al={"was ist yagyins zusammenstellung","wer ist yagyin","yagyins buch"}},{q="Wo ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur befindet sich in der Unterstadt von Lordaeron.",al={"bewahrer bel'dugur aufenthaltsort","wo ist bewahrer bel'dugur zu finden","beldugur unterstadt"}},{q="Was kam davor?",a="Solution to Doom kam davor.",al={"vorherige quest","was kommt davor","solution to doom zusammenhang"}}},fp="36,197,23.281.0,27.197.0,17.375.1,31.101.0,36.135.0,24.142.0,26.50.0,22.34.0"}
P.entries["quest:729"] = {n="Der geistesabwesende Ausgrabungsleiter",s="An der südlichen Dunkelküste überrennen feindselige Steingolems eine Ausgrabungsstätte, und Archäologin Hollee sucht in Auberdine Hilfe. Sie fürchtet um Ausgrabungsleiter Wirrbart, ihren älteren Kollegen, dessen Forschung ihn oft blind für tödliche Gefahren macht.",h="An der südlichen Dunkelküste überrennen feindselige Steingolems eine Ausgrabungsstätte, und Archäologin...",kw={"auberdine","dunkelküste","forscherliga","fossil","golems","greywhisker","hollee","wirrbart"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie Forscher aus Eisenschmiede die fremdartigen uralten Länder ihrer Nachtelfenverbündeten in Kalimdor erforschen.",["race:Dwarf"]="Als Zwerg erlebt Ihr Wirrbarts besessene Neugier: Für ein noch nicht katalogisiertes Fossil riskiert er Leib und Leben."},sec={{t="Eine gefährliche Ausgrabung",b="Archäologin Hollee kam mit der Forscherliga über das Meer. Meister Greywhisker schickte sie zu Ausgrabungsleiter Wirrbart in die Lehre, dessen Entdeckungen ihn in den akademischen Kreisen von Eisenschmiede berühmt gemacht hatten. Die Liga entsandte die beiden, um uralte Ruinen entlang der ungezähmten Küste der Dunkelküste zu untersuchen. Als sie die vermeintlichen Überreste einer großen Zivilisation freilegten, brachen gewalttätige Steingolems aus der Erde hervor und überrannten die Stätte."},{t="Blind für das Unheil",b="In Panik floh Hollee durch die Nacht nach Auberdine, dem Hafen der Nachtelfen, um Hilfe zu suchen. Wirrbart bemerkte die Gefahr kaum. In seine Relikte vertieft, blieb der betagte Ausgrabungsleiter zwischen den Trümmern, während schwerfällige Konstrukte sein Lager umringten. Wer ihn südlich von Auberdine erreicht, findet ihn über fehlende Steinbürsten und verlegte Fossilien murrend vor."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein gefeierter zwergischer Forscher der Forscherliga von Eisenschmiede. Seine Entdeckungen machten ihn in zwergischen Gelehrtenkreisen berühmt, doch wertvolle Relikte können ihn blind für Gefahren in seiner Nähe machen.",al={"wirrbart","ausgrabungsleiter wirrbart geschichte","wer ist der ausgrabungsleiter"}},{q="Warum ist Archäologin Hollee in Auberdine?",a="Meister Greywhisker beauftragte Hollee, Wirrbart zu unterstützen. Als gefährliche Golems an ihrer Ausgrabungsstätte aus der Erde stiegen, floh sie in Panik nach Norden nach Auberdine, um Hilfe für eine Rettung zu suchen.",al={"archäologin hollee","hollee auberdine","warum floh hollee"}},{q="Was gruben die Zwerge an der Dunkelküste aus?",a="Die Zwerge legten unter der Dunkelküste die vermeintlichen Überreste einer großen uralten Zivilisation frei. Bevor Golems die Stätte überrannten, hatte Wirrbart ein geheimnisvolles Fossil und steinerne Artefakte entdeckt.",al={"was grub wirrbart aus","dunkelküste ausgrabungsstätte","wirrbart fossil"}},{q="Wo ist Ausgrabungsleiter Wirrbart zu finden?",a="Ausgrabungsleiter Wirrbart befindet sich an der Ausgrabungsstätte an der südlichen Dunkelküste, zwischen uralten Ruinen südlich von Auberdine. Gefährliche Golems umringen sein Lager, während er nach seiner Steinbürste und seinem Fossil sucht.",al={"wo ist wirrbart","wirrbart aufenthaltsort","ausgrabungsleiter wirrbart finden"}},{q="Wer schickte diese Expedition an die Dunkelküste?",a="Die Forscherliga entsandte die Expedition auf Befehl von Meister Greywhisker aus Eisenschmiede. Greywhisker schickte Hollee zu Wirrbart in die Lehre, damit sie die uralten Ruinen der Dunkelküste untersuchte.",al={"wer schickte hollee","meister greywhisker","forscherliga dunkelküste"}},{q="Ist Wirrbart wirklich in Gefahr?",a="Ja. Feindselige Golems durchstreifen die Ruinen um Wirrbart, doch er ist blind für die Gefahr. Er konzentriert sich darauf, seine Funde zu katalogisieren, und fragt sich, wo seine Werkzeuge und seine Gehilfin geblieben sind.",al={"ist wirrbart tot","wirrbart am leben","wirrbart helfen"}}},fx={["90475777"]={q="Warum möchte Archäologin Hollee, dass dies erledigt wird?",a="Hollee war begeistert, unter Ausgrabungsleiter Wirrbart zu lernen, einem berühmten Forscher der Forscherliga von Eisenschmiede. Doch als feindselige Golems aus der Ausgrabungsstätte brachen, ließ ihn seine tiefe Zerstreutheit die Gefahr völlig vergessen. Hollee floh nach Auberdine, um Verstärkung zu holen, in der Angst, dass ihr Mentor getötet wird, wenn ihn niemand aus den Ruinen holt.",al={"warum braucht hollee hilfe","beweggrund hollee","warum nach wirrbart suchen"}},["1b9bcac6"]={q="Warum bittet Hollee Euch, nach Wirrbart zu sehen, anstatt selbst zu gehen?",a="Hollee entkam der Ausgrabungsstätte nur knapp mit dem Leben, als sich die Steingolems erhoben. Verängstigt und ohne die kampferprobten Fähigkeiten, sich allein durch die feindseligen Konstrukte zu kämpfen, muss sie sicher in Auberdine bleiben und sich auf fähige, vorbeikommende Abenteurer verlassen, die sich zurück in das Getümmel wagen und nach ihrem Mentor sehen.",al={"warum ich hollee","warum geht hollee nicht zurück","warum hilft auberdine nicht"}}},fp="28,221,14.427.0,17.354.0,28.215.0,41.166.0,46.205.0,40.191.0,38.186.0,30.178.0"}
P.entries["quest:730"] = {n="Ärger in Dunkelküste?",s="In Darnassus braucht Chefarchäologe Grauflaum Hilfe bei der Suche nach seiner vermissten Mannschaft. Sein Hilferuf führt Euch über das Meer nach Auberdine, wo die Zwergenexpedition an der wilden Küste von Dunkelküste in Schwierigkeiten geriet.",h="In Darnassus braucht Chefarchäologe Grauflaum Hilfe bei der Suche nach seiner vermissten Mannschaft.",kw={"archäologe","auberdine","dunkelküste","darnassus","explorers league","grauflaum","hollee","ärger in dunkelküste"},ang={["faction:Alliance"]="Als Reisender der Allianz seht Ihr, wie die Zusammenarbeit zwischen Eisenschmiede und Darnassus wächst und Teldrassil mit dem Festland Kalimdors verbindet.",["race:Dwarf"]="Als Zwerg seht Ihr, wie die Tradition der Explorer’s League, Titanenwissen und uralte Geschichte zu erforschen, auf neue Kontinente getragen wird.",["race:NightElf"]="Als Nachtelf betrachtet Ihr die Zwergengräber, die in den Küstenruinen Eurer Vorfahren eintreffen, vielleicht mit vorsichtiger Belustigung oder stiller Sorge."},sec={{t="Eine schweigende Expedition",b="Darnassus ist die prächtige Hauptstadt der Nachtelfen und Heimat von Zwergenforschern aus Eisenschmiede, die Kalimdors uralte Geheimnisse erforschen. Chefarchäologe Grauflaum schickte eine Ausgrabungsgruppe über das Wasser nach Dunkelküste, um uralte Artefakte zu bergen. Wochen sind vergangen, ohne eine Nachricht oder einen Fortschrittsbericht. Grauflaum fürchtet, dass seine Mannschaft vor Ort von Gefahren ereilt wurde."},{t="Freigelegte Bedrohungen",b="Grauflaum beklagt, dass viele in der Allianz die Zwergenarchäologie als exzentrisches Hobby abtun. Entdeckungen in Khaz Modan haben seine Kollegen überzeugt, dass eine furchterregende uralte Macht Azeroth von Lordaeron bis Kalimdor bedroht. Deshalb ist die Arbeit in den Ruinen von Dunkelküste mehr als reine Forschung. Die Expedition will historische Kataklysmen und die tief verwurzelten Gefahren verstehen, die unter uralter Erde begraben liegen."},{t="Kontakt in Auberdine",b="Ihr segelt von Teldrassil über die Meerenge nach Auberdine, dem Zufluchtsort an der Küste. Archäologin Hollee wartet in der Stadt, erleichtert darüber, dass Grauflaum Hilfe geschickt hat. Hollee sagt, dass die Expedition in großer Not ist. Weiter die Küste hinunter geriet die Mannschaft bei der Suche nach uralten Relikten in Schwierigkeiten."}},faq={{q="Wer vergibt die Quest „Ärger in Dunkelküste?“?",a="Chefarchäologe Grauflaum bittet in Darnassus um Hilfe und sucht Reisende, die nach seiner vermissten Mannschaft sehen.",al={"wer vergibt ärger in dunkelküste","questgeber ärger in dunkelküste","wo gibt es ärger in dunkelküste"}},{q="Wohin muss ich gehen, um diese Quest abzuschließen?",a="Reist von Darnassus über das Meer nach Auberdine in Dunkelküste, wo Archäologin Hollee wartet.",al={"wohin gehen","abgabeort","bei wem abgeben"}},{q="Warum sind Zwergenarchäologen in Darnassus und Dunkelküste?",a="Nach Entdeckungen in Khaz Modan begannen Zwergenforscher, uralte Stätten in ganz Kalimdor nach Hinweisen auf uralte Mächte zu untersuchen, die Azeroth bedrohen.",al={"warum sind zwerge in darnassus","zwerge in dunkelküste","zwergenarchäologie kalimdor"}},{q="Was geschieht, nachdem ich Archäologin Hollee gefunden habe?",a="Ein Gespräch mit Archäologin Hollee in Auberdine führt zu „The Absent Minded Prospector“. Diese Folgequest fordert Euch auf, in der Wildnis von Dunkelküste nach Ausgrabungsleiter Wirrbart zu suchen.",al={"what comes next","folgequest","nächste quest"}},{q="Warum hat sich die Ausgrabungsmannschaft nicht gemeldet?",a="Die Mannschaft stieß bei ihrer Arbeit in Dunkelküste auf unerwartete Gefahren und Rückschläge. Ihre Mitglieder wurden voneinander getrennt, und die Verbindung nach Darnassus brach ab.",al={"was geschah mit der ausgrabung","warum sind sie verschwunden","mannschaft vermisst"}},{q="Auf welche drohende Gefahr bezieht sich Grauflaum?",a="Grauflaum verweist auf Entdeckungen in Khaz Modan, die auf eine uralte, allgegenwärtige Gefahr tief in Azeroths historischen Ruinen hindeuten.",al={"welche uralte bedrohung","grauflaums warnung","khaz modan bedrohung"}}},fx={["0c1ca2fe"]={q="Warum möchte Chefarchäologe Grauflaum, dass dies erledigt wird?",a="Chefarchäologe Grauflaum hat seit Wochen nichts von seinem Ausgrabungsteam in Dunkelküste gehört. Nach bedrohlichen Entdeckungen in Khaz Modan, die eine große und uralte Macht enthüllen, die ganz Azeroth bedroht, kann er es sich nicht leisten, den Kontakt zu seinen Forschern zu verlieren, insbesondere wenn deren Arbeit entscheidend ist, um diese drohenden Gefahren aufzudecken.",al={"beweggrund grauflaum","warum nach dunkelküste schicken","warum ausgrabungsteam finden"}}},fp="21,205,19.359.0,16.403.0,20.286.1,42.110.0,45.102.0,58.154.0,48.175.0,45.147.0,48.134.0"}
P.entries["quest:731"] = {n="Der geistesabwesende Ausgrabungsleiter",s="In den südlichen Ruinen der Dunkelküste setzt Ausgrabungsleiter Wirrbart seine Grabung fort und hofft auf einen wertvollen Fund für die Forscherliga. Feindselige Troggs und seine Vergesslichkeit machen die Suche gefährlich, und seine Assistentin in Auberdine muss erfahren, dass er in Sicherheit ist.",h="In den südlichen Ruinen der Dunkelküste setzt Ausgrabungsleiter Wirrbart seine Grabung fort und hofft auf...",kw={"auberdine","dunkelküste","eskorte","ausgrabung","forscherliga","fossil","hollee","wirrbart","troggs"},ang={["faction:Alliance"]="Als Mitglied der Allianz stärkt Ihr die wissenschaftlichen und diplomatischen Beziehungen zwischen der zwergischen Forscherliga und den Nachtelfen von Teldrassil, indem Ihr Wirrbart helft und seine Funde bewahrt.",["race:Dwarf"]="Für Zwerge verkörpert Wirrbart die glühende Leidenschaft und den Starrsinn der Forscherliga. Seine Hingabe an das uralte Wissen über die Titanen macht ihn blind für die Gefahren um ihn herum.",["race:NightElf"]="Für Euch als Nachtelf mag die zwergische Grabung in der Dunkelküste die Skepsis Eures Volkes bestätigen: Wirrbarts Ausgrabung legte eine Horde gewalttätiger Troggs unter heiligem Boden frei."},sec={{t="Eine gefährliche Ausgrabung",b="Weit im Süden der Dunkelküste liegt Wirrbarts Grabung inmitten uralter Ruinen. Zwergische Ausgräber stießen dort bei ihrer Suche auf Troggs, die die Arbeiter vertrieben und ihr Lager belagerten. Wirrbart will nicht mit leeren Händen nach Auberdine zurückkehren. Er begibt sich in Gefahr, um ein Fossil zu bergen, und hofft, damit die Kosten der Expedition vor der Forscherliga zu rechtfertigen."},{t="Verworrene Erinnerungen und Troggüberfälle",b="Wirrbart bei der Ausgrabung zu beschützen ist gefährlich und frustrierend. Er zieht seine Kreise über das Gelände, verwechselt Pinsel mit Fossilien und stolpert an Gerüsten und verlassenen Zelten vorbei. Jeder Halt lockt aggressive Troggs aus den schattigen Winkeln des Steinbruchs hervor. Nachdem Reisende Welle um Welle der unterirdischen Unholde bezwungen haben, erinnert sich Wirrbart daran, wo sein wertvoller Fund ist: Er hat das Fossil bereits Hollee gegeben. Er kehrt vergnügt an die Arbeit zurück."}},faq={{q="Wer ist Ausgrabungsleiter Wirrbart?",a="Ausgrabungsleiter Wirrbart ist ein erfahrener Feldforscher der zwergischen Forscherliga. Er ist in der Dunkelküste stationiert und wurde entsandt, um uralte Küstenruinen auszugraben, doch seine extreme Zerstreutheit bringt ihn oft in Lebensgefahr.",al={"wirrbart","wer ist der ausgrabungsleiter","der geistesabwesende ausgrabungsleiter"}},{q="Warum ist Wirrbart noch an der Grabungsstätte?",a="Wirrbart weigert sich, ohne handfesten Beweis für seine Arbeit nach Darnassus zurückzukehren. Er will ein geheimnisvolles Fossil bergen, um es der Forscherliga vorzulegen, bevor er das Lager aufgibt.",al={"warum an der grabung bleiben","warum ist wirrbart dort","warum ist er nicht geflohen"}},{q="Woher kamen die Troggs?",a="Wirrbarts Team grub tief in die Erde und stieß in unterirdische Hohlräume vor, die von Troggs bewohnt waren. Die primitiven Kreaturen strömten nach oben und überrannten die Maschinen, Zelte und Arbeiter.",al={"warum gibt es troggs in der dunkelküste","troggs der dunkelküste","troggs an der grabungsstätte"}},{q="Wer ist Archäologin Hollee?",a="Archäologin Hollee ist Wirrbarts Kollegin und Assistentin in Auberdine. Verzweifelt über die lange Abwesenheit ihres Mentors und mit seiner Vergesslichkeit vertraut, bittet sie Reisende, ihn zu finden und seine sichere Rückkehr zu gewährleisten.",al={"hollee","archäologin hollee","wirrbarts assistentin"}},{q="Was geschieht, nachdem das Fossil gefunden wurde?",a="Nachdem Ihr Wirrbart bei der Suche auf dem Grabungsgelände geholfen habt, berichtet Archäologin Hollee in Auberdine, dass er in Sicherheit ist.",al={"questfortsetzung","was als nächstes","nach wirrbarts eskorte"}}},fx={["6ea255c4"]={q="Warum möchte Ausgrabungsleiter Wirrbart das Fossil finden?",a="Wirrbart steht unter dem Druck des Kapitels der Forscherliga in Darnassus, zu beweisen, dass er tatsächlich Fortschritte bei der Ausgrabungsstätte gemacht hat. Obwohl er schrecklich verwirrt und geistesabwesend ist, weiß er, dass er greifbare Ergebnisse – insbesondere das geheimnisvolle Fossil und schriftliche Funde – vorzeigen muss, um seine Expedition zu rechtfertigen und seine Vorgesetzten zufrieden zu stellen.",al={"beweggrund wirrbart","warum nach fossil suchen","warum fossil wirrbart finden"}},["4634f683"]={q="Warum braucht Wirrbart Eure Hilfe bei der Suche in der Ausgrabung?",a="Die Ausgrabungsstätte wurde von feindseligen Troggs überrannt, und Wirrbart ist ein zerstreuter Forscher, kein erfahrener Krieger. Er ist völlig darauf fixiert, seine verlorenen Artefakte und Notizen zu bergen, was ihn völlig anfällig für Hinterhalte macht, während er ohne jemanden, der bewaffnet ist und ihm den Rücken freihält, durch die Ausgrabungsstätte irrt.",al={"warum braucht wirrbart eine eskortierung","warum braucht wirrbart schutz","warum nicht alleine suchen wirrbart"}}},fp="28,251,21.333.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="Erdbeben",s="Garek bittet Euch um Hilfe, nachdem er von allem gehört hat, was Ihr für Sigrun getan habt. Sein Meister, Krasus von den Kirin Tor, schickte ihn ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut. Zuerst braucht er das gestohlene Zeichen der Erde.",h="Garek bittet Euch um Hilfe, nachdem er von allem gehört hat, was Ihr für Sigrun getan habt.",kw={"festung angor","camp boff","dunkeleisen","deathwing","garek","kirin tor","krasus","die lethlorklamm","zeichen der erde"},sec={{t="Eine vertrauliche Angelegenheit",b="Krasus von den Kirin Tor schickte Garek ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut. Er kann Euch den genauen Auftrag nicht verraten, nur dass er von großer Bedeutung ist. Umherziehende Oger haben das Zeichen der Erde gestohlen, und Garek braucht es zurück, bevor er Euch mehr erzählen kann. Sie werden manchmal in der Nähe von Camp Boff gesehen."},{t="Die umherziehenden Oger",b="Oger ziehen im Ödland von Lager zu Lager. Zunehmende Hitze und wirbelnde Winde erschweren es, ihrer Spur zu folgen. Garek hat gehört, dass sie manchmal Camp Boff durchqueren, also sucht dort, falls Ihr ihre Fährte verliert."},{t="Garek erklärt",b="Wenn Ihr mit dem Zeichen zurückkehrt, erzählt Euch Garek, dass die Dunkeleisenzwerge der Festung Angor es erschaffen haben, um Deathwings Zwillingsleutnants zu binden, die skrupellosen Blacklash und Hematus."}},faq={{q="Für wen arbeitet Garek?",a="Krasus von den Kirin Tor ist Gareks Meister. Er schickte Garek ins Ödland, um das Unheil aufzuhalten, das sich in der Lethlorklamm zusammenbraut.",al={"wer schickte garek","gareks meister","krasus ödland"}},{q="Was ist das Zeichen der Erde?",a="Umherziehende Oger haben das Zeichen der Erde gestohlen, und Garek braucht es zurück, bevor er Euch mehr erzählen wird.",al={"zeichen der erde","was ist das zeichen der erde","zeichen der erde hintergrund"}},{q="Wo sind die umherziehenden Oger zu finden?",a="Die Oger ziehen im Ödland zwischen den Lagern umher. Garek hat gehört, dass sie manchmal Camp Boff durchqueren.",al={"wo sind die oger","oger camp boff","wo ist das zeichen der erde"}},{q="Warum hält Garek den Auftrag geheim?",a="Garek will weder den Auftrag noch die damit verbundenen Aufgaben verraten. Er sagt nur, dass er von großer Bedeutung ist.",al={"warum geheim","garek geheimer auftrag"}}},fp="20,219,19.300.0,19.211.0,14.168.1,25.115.0,30.98.0,39.104.0,42.100.0"}
P.entries["quest:7321"] = {n="Milde Schildkrötensuppe",s="In Tarrens Mühle hofft Christoph Jeffkott, mit Milder Schildkrötensuppe zu beweisen, dass die Verlassenen mit Sorgfalt kochen können. Er braucht Schnappkieferfleisch aus Hillsbrads Wasserläufen und von den Ufern des Lordameresees.",h="In Tarrens Mühle hofft Christoph Jeffkott, mit Milder Schildkrötensuppe zu beweisen, dass die Verlassenen mit...",kw={"christoph jeffkott","kochen","vorgebirge des hügellands","der lordameresee","schnappkiefer","milde schildkrötensuppe","tarrens mühle","schildkrötenfleisch"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Tarrens Mühle gut zu versorgen und die Moral zu stärken, während Ihr seine Grenzen verteidigt.",["profession:Cooking"]="Als Koch könnt Ihr lernen, Milde Schildkrötensuppe mit Schnappkiefern aus dem Lordameresee und Hillsbrads Flüssen zuzubereiten.",["race:Undead"]="Als Untoter könnt Ihr sehen, dass der Tod Christoph Jeffkotts Leidenschaft fürs Kochen nicht gemindert hat."},sec={{t="Kochkunst der Verlassenen",b="Viele glauben, die Verlassenen hätten die Annehmlichkeiten des Lebens aufgegeben, darunter auch die feine Küche. Christoph Jeffkott in Tarrens Mühle sieht das anders. Er prahlt damit, dass seine reichhaltige Schildkrötensuppe Seelen aus dem Jenseits zurücklocken könnte. Mit sorgfältiger Zubereitung will er zeigen, dass untote Hände in einem von Seuche und Krieg gezeichneten Land noch immer ein wärmendes Gericht bereiten können."},{t="Jagd auf die Schnappkiefer",b="Jeffkott sammelte einst Zutaten an Hillsbrads Wasserläufen und am Ostufer des Lordameresees im benachbarten Alterac. Nun halten ihn seine Pflichten in Tarrens Mühle und nahe Streitkräfte der Allianz von der Jagd ab. Also verlässt er sich auf durchreisende Köche der Horde, die Schnappkiefer jagen und ihm ihr Fleisch bringen. Ihre Hilfe hält sein Rezept am Leben."}},faq={{q="Warum liegt einem Koch der Verlassenen daran, heiße Suppe zuzubereiten?",a="Die Verlassenen brauchen Nahrung weniger als lebende Sterbliche, doch Christoph Jeffkott ist stolz auf sein Handwerk. Er will beweisen, dass die Untoten mit Geschick kochen können, und scherzt, seine Brühe könne die Toten wieder zum Leben erwecken.",al={"untote kochkunst","warum suppe kochen","untote essen nahrung"}},{q="Wo findet man Schildkrötenfleisch für dieses Rezept?",a="Schnappkieferfleisch stammt von angriffslustigen Schildkröten an den Flüssen im Vorgebirge des Hügellands, in Alterac und an den Ufern des Lordameresees.",al={"wo sind schildkröten","fundorte von schildkröten","fundorte von schnappkiefern"}},{q="Warum kann Christoph Jeffkott seine Zutaten nicht selbst sammeln?",a="Jeffkotts Pflichten in Tarrens Mühle halten ihn auf Trab, während nahe Streitkräfte der Allianz seine eigenen Jagdausflüge gefährlicher machen.",al={"warum geht christoph nicht","jeffkott sitzt im ort fest"}},{q="Sind Kochkenntnisse erforderlich, um diese Quest anzunehmen?",a="Ja. Christoph Jeffkott teilt sein Rezept nur mit Köchen, und für den Anfang sind keine fortgeschrittenen Kenntnisse nötig.",al={"kochkenntnisse nötig","beruf kochen voraussetzung"}},{q="Welche Bedeutung hat Tarrens Mühle für die Horde in Hillsbrad?",a="Tarrens Mühle ist der wichtigste Stützpunkt der Horde im Vorgebirge des Hügellands. Einst ein Menschendorf, dient der Ort heute den Verlassenen und ihren Verbündeten als befestigte Basis. Häufig kommt es zu Zusammenstößen mit dem nahen Süderstade und der Allianz.",al={"was ist tarrens mühle","geschichte von tarrens mühle"}},{q="Gibt es Schildkrötensuppe nur bei der Horde?",a="Köche der Allianz können von menschlichen Köchen in Süderstade ein Rezept für Schildkrötensuppe lernen, die ebenfalls örtliche Schildkröten verwenden. Christoph Jeffkotts persönliches Anliegen und seine Sichtweise gehören zur Horde.",al={"allianzversion","kann die allianz schildkrötensuppe bekommen"}}},fx={["7509a6d7"]={q="Wofür ist das Schildkrötenfleisch?",a="Christoph Jeffkott benötigt das Schildkrötenfleisch, um seine charakteristische beruhigende Schildkrötenbisque zu brauen. Auch wenn Untote vielleicht nicht die Kälte oder den Hunger wie die Lebenden spüren, ist Jeffkott sehr stolz auf sein kulinarisches Handwerk. Er behauptet, sein Geheimrezept sei so gut, dass die Menschen von den Toten zurückkehren würden, nur um eine heiße Schüssel zu genießen.",al={"verwendung schildkrötenfleisch","warum schildkrötenfleisch","wofür wird schildkrötenfleisch verwendet"}},["5469f6c5"]={q="Was sind die Schnappkiefer, die Ihr für diese Bisque jagt?",a="Schnappkiefer sind bösartige Süßwasserschildkröten mit hartem Panzer, die in den Gewässern von Lordaeron heimisch sind, besonders reichlich entlang der Ufer des Lordameresee und der örtlichen Flussufer. Obwohl sie wild und gefährlich für unvorsichtige Reisende sind, liefert ihr zähes Fleisch das entscheidende, reichhaltige Fleisch, das Christoph für seine Bisque benötigt.",al={"schnappkiefer hillsbrad","lordameresee schnappkiefer","wen jage ich"}}},fp="22,190,19.346.0,20.316.0,54.207.0,47.127.0,56.123.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="Schnorrerei",s="In Sigrun Ironhews Lager hängen Verteidigung und Versorgung vom Altmetall ab. Sie braucht sieben Stücke, und die Oger in der Nähe tragen reichlich davon bei sich.",h="In Sigrun Ironhews Lager hängen Verteidigung und Versorgung vom Altmetall ab.",kw={"ödland","die staubspeiergrotte","explorers' league","eisenschmiede","oger","altmetall","schnorrerei","sigrun ironhew"},sec={{t="Ein Lager ohne Material",b="Sigrun Ironhew braucht Material für die Verteidigung des Lagers und andere Zwecke. Der Prospector sorgt sich um den Zustand des Lagers, deshalb will Sigrun bald mit der Arbeit beginnen. Ihr fehlt Altmetall."},{t="Das Altmetall der Oger",b="Die Oger in der Nähe tragen Altmetall bei sich, was dem Gerede über Belagerungsmaschinen im Ödland mehr Gewicht verleiht. Ihr Hauptlager, die Staubspeiergrotte, liegt einen langen Fußmarsch westlich von Sigruns Lager."}},faq={{q="Wer bittet um das Altmetall?",a="Sigrun Ironhew braucht Altmetall, um Verteidigungsanlagen zu bauen und das Lager zu versorgen.",al={"questgeber","wer vergibt schnorrerei","sigrun"}},{q="Warum braucht das Lager Altmetall?",a="Dem Lager fehlt Material für Verteidigungsanlagen und andere Zwecke. Der Prospector sorgt sich um seinen Zustand.",al={"warum altmetall benötigt","zweck des altmetalls","verteidigungsanlagen"}},{q="Wo ist das Altmetall zu finden?",a="Die Oger in der Nähe tragen Altmetall bei sich. Ihr Hauptlager, die Staubspeiergrotte, liegt einen langen Fußmarsch westlich von Sigruns Lager.",al={"altmetall fundort","wo altmetall bekommen","ogerlager"}},{q="Was kommt davor?",a="Die Quest folgt auf Mirages.",al={"vorherige quest","schnorrerei voraussetzung"}}},fp="10,123,25.189.0,16.162.0,34.71.0,35.98.0,35.106.0,23.19.0"}
P.entries["quest:734"] = {n="Das wird schwierig",s="Im Ödland schickt Euch Lotwil Veriatus zu Lucien Tosselwrench, um ein benötigtes Zahnrad Nr. 5 zu holen. Bringt es zu Lotwil zurück.",h="Im Ödland schickt Euch Lotwil Veriatus zu Lucien Tosselwrench, um ein benötigtes Zahnrad Nr.",kw={"ödland","zahnrad nr. 5","lotwil veriatus","lucien tosselwrench","fesseln"},sec={{t="Zahnrad Nummer fünf",b="Lotwil Veriatus wendet sich den Fesseln zu und schickt Euch dann zu Lucien Tosselwrench. Er braucht ein Zahnrad Nr. 5 und bittet Euch, es ihm zurückzubringen."},{t="Luciens Urteil",b="Als Ihr Zahnrad Nr. 5 erwähnt, klingt Lucien Tosselwrench wenig zuversichtlich, wie die Dinge ausgehen werden."}},faq={{q="Wer vergibt diese Quest?",a="Lotwil Veriatus bittet Euch darum, während er im Ödland an einem Satz Fesseln arbeitet.",al={"wer vergibt diese quest","lotwil veriatus quest","questgeber"}},{q="Was braucht Lotwil?",a="Lotwil braucht ein Zahnrad Nr. 5. Er bittet Euch, es zurückzubringen, nachdem Ihr mit Lucien Tosselwrench gesprochen habt.",al={"was will lotwil","welches zahnrad","zahnrad 5"}},{q="Mit wem spreche ich wegen des Zahnrads?",a="Lotwil schickt Euch zu Lucien Tosselwrench im Ödland.",al={"wo zahnrad 5 finden","wer ist lucien","lucien tosselwrench"}}},fp="24,111,15.147.0,16.86.1,21.76.0,22.92.0,32.56.0"}
P.entries["quest:735"] = {n="Der Stern, die Hand und das Herz",s="In Eisenschmiede bietet Gerrig Knochengriff Yagyins Zusammenstellung für drei Gegenstände der Macht an. Ihre Namen werden vor lauschenden Ohren geheim gehalten und auf einem Zettel festgehalten.",h="In Eisenschmiede bietet Gerrig Knochengriff Yagyins Zusammenstellung für drei Gegenstände der Macht an.",kw={"knochengriffs notiz","gerrig knochengriff","hand von dagun","eisenschmiede","legacy heart","stern von xil'yeh","yagyins zusammenstellung"},sec={{t="Ein Handel mit verschlossenen Lippen",b="Gerrig Knochengriff hört Euch nach Yagyins Zusammenstellung fragen und überlegt, ob Ihr irgendwo eine neue Niederlassung des Ordens gründen wollt. Gerrig beschließt, dass es Gerrig nicht zusteht, danach zu fragen. Gerrig hat ein zusätzliches Exemplar zur Hand und glaubt, dass Angehörige des Ordens einander helfen sollten. Daher bittet Gerrig Euch, drei Gegenstände der Macht zu bringen. Ihre Namen bleiben unausgesprochen, falls jemand lauscht, und Gerrig schreibt sie auf."},{t="Die drei Gegenstände",b="Gerrigs Notiz nennt den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart. Gerrig will alle drei haben, bevor Yagyins Zusammenstellung übergeben wird."},{t="Gerrigs Urteil",b="Mit den Relikten in der Hand nennt Gerrig Euch einfallsreich. Gerrig glaubt, dass Ihr eine neue Niederlassung des Ordens gut leiten werdet, wenn deren Gründung tatsächlich Euer Auftrag ist."}},faq={{q="Wer verlangt die drei Gegenstände?",a="Gerrig Knochengriff in Eisenschmiede verlangt drei Gegenstände und bietet dafür ein zusätzliches Exemplar von Yagyins Zusammenstellung an.",al={"questgeber","wer startet der stern die hand und das herz","gerrig knochengriff quest"}},{q="Welche drei Gegenstände will Gerrig Knochengriff?",a="Gerrig Knochengriffs Notiz nennt den Stern von Xil'yeh, die Hand von Dagun und das Legacy Heart.",al={"benötigte gegenstände","welche relikte braucht er","knochengriffs notiz gegenstände"}},{q="Warum schreibt Gerrig die Gegenstände auf, statt sie auszusprechen?",a="Gerrig schreibt die Namen auf, weil jemand lauschen könnte.",al={"warum die namen aufschreiben","warum die geheime notiz","knochengriff flüstert"}},{q="Was kam davor in der Questreihe?",a="Sie folgt auf „To Eisenschmiede for Yagyins Zusammenstellung“, wo Theldurin der Verirrte Euch zu Gerrig schickte.",al={"vorausgesetzte quest","vorherige quest"}}},fp="32,154,30.392.0,15.140.0,16.158.1,29.104.0,43.89.0,60.62.0,35.89.0"}
P.entries["quest:736"] = {n="Der Stern, die Hand und das Herz",s="In Unterstadt prüft Bewahrer Bel'dugur jene, die ihren eigenen Zirkel leiten wollen. Um eine neue Niederlassung zu gründen, brauchen sie Yagyins Zusammenstellung, doch er verlangt drei unbenannte Gegenstände der Macht.",h="In Unterstadt prüft Bewahrer Bel'dugur jene, die ihren eigenen Zirkel leiten wollen.",kw={"bel'dugurs notiz","bewahrer bel'dugur","orden","der stern die hand und das herz","drei gegenstände der macht","unterstadt","yagyins zusammenstellung"},ang={["class:Warlock"]="Als Hexenmeister sucht Ihr Yagyins Zusammenstellung, um eine neue Schar zu sammeln und die okkulte Meisterschaft Eures Ordens zu erweitern.",["race:Undead"]="Als Untoter findet Ihr Bewahrer Bel'dugur in Unterstadt, wo er Praktizierende der Verlassenen anleitet, die nach verbotenen Riten suchen."},sec={{t="Eine Prüfung der Bruderschaft",b="Praktizierende, die ihren eigenen Zirkel leiten wollen, kommen zu Bewahrer Bel'dugur in Unterstadt. Um eine Niederlassung zu gründen und Anhänger zu sammeln, brauchen sie Yagyins Zusammenstellung, ein Werk rituellen Wissens, das er verwahrt. Bel'dugur hilft einem Bruder, verlangt aber zunächst einen Beweis seiner Würdigkeit, bevor er ihm solches Wissen anvertraut."},{t="Die unausgesprochenen Relikte",b="Bewahrer Bel'dugur verlangt drei Gegenstände der Macht im Austausch für Yagyins Zusammenstellung. Ihre Namen bergen Gefahr oder haben heiliges Gewicht, daher will er sie nicht laut aussprechen. Stattdessen schreibt er sie auf eine vertrauliche Notiz. Wer alle drei findet, erweist sich als würdig, eine eigene Niederlassung zu gründen."}},faq={{q="Wer ist Bewahrer Bel'dugur?",a="Bewahrer Bel'dugur lebt in Unterstadt und hilft Mitgliedern seiner dunklen Bruderschaft. Er hütet mächtiges Wissen und verlangt von Anwärtern einen Beweis ihrer Würdigkeit, bevor er ihnen heilige Schriften anvertraut.",al={"wer ist bewahrer bel'dugur","bel'dugurs rolle","beldugur unterstadt"}},{q="Was ist Yagyins Zusammenstellung?",a="Yagyins Zusammenstellung ist ein Werk rituellen Wissens, das benötigt wird, um innerhalb eines verschwiegenen okkulten Ordens eine neue Niederlassung zu gründen oder Anhänger zu sammeln.",al={"was ist yagyins zusammenstellung","yagyins zusammenstellung zweck","yagyins zusammenstellung buch"}},{q="Welche Gegenstände verlangt Bewahrer Bel'dugur?",a="Bel'dugur verlangt drei Gegenstände der Macht. Er schreibt ihre Namen auf eine vertrauliche Notiz, weil er sie nicht laut aussprechen will.",al={"welche gegenstände braucht bel'dugur","beldugurs notiz gegenstände","drei gegenstände der macht"}},{q="Warum werden die Namen der verlangten Gegenstände nicht laut ausgesprochen?",a="Bel'dugur will die Namen der drei Relikte nicht laut aussprechen. Ihre Gefährlichkeit oder heilige Bedeutung erfordert Verschwiegenheit.",al={"warum kann bel'dugur die gegenstandsnamen nicht aussprechen","namen nicht aussprechen können","unausgesprochene gegenstandsnamen"}},{q="Was bedeutet es, eine weitere Schar zu sammeln?",a="Eine Schar zu sammeln bedeutet, Anhänger anzuwerben und eine unabhängige Niederlassung der Bruderschaft zu gründen, bereit, andere Praktizierende anzuleiten.",al={"was bedeutet eine schar sammeln","eine niederlassung eröffnen","niederlassung unseres ordens"}},{q="Wo liegt der Mittelpunkt dieser Quest?",a="Im Mittelpunkt der Geschichte steht Bewahrer Bel'dugur in Unterstadt, der unterirdischen Hauptstadt der Verlassenen.",al={"wo spielt diese quest","bel'dugurs aufenthaltsort","quest abgabeort"}}},fp="32,178,21.311.0,19.280.0,24.186.0,24.123.0,41.118.0,58.118.0,42.136.0,29.90.0"}
P.entries["quest:737"] = {n="Verbotenes Wissen",s="Yagyins Zusammenstellung ist in Eurer Obhut, für Theldurin den Verirrten bestimmt und vor unfreundlichen Händen geschützt.",h="Yagyins Zusammenstellung ist in Eurer Obhut, für Theldurin den Verirrten bestimmt und vor unfreundlichen...",kw={"ödland","verbotenes wissen","the star the hand and the heart","theldurin der verirrte","yagyins zusammenstellung"},sec={{t="Ein Buch, das brennt",b="Gerrig Knochengriff in Eisenschmiede oder Bewahrer Bel'dugur in Unterstadt übergibt Euch Yagyins Zusammenstellung. Schützt sie vor unfreundlichen Händen, während Ihr sie zu Theldurin dem Verirrten bringt. Sie birgt viele Wahrheiten, und Wahrheit hat die Eigenart, zu brennen."},{t="Theldurins Hoffnung",b="Theldurin ruft aus, dass noch Hoffnung schimmert. Eure Bemühungen könnten sie alle noch retten, sagt er, und Euch ein Denkmal und einen Schrein einbringen, während Euer Name über Generationen gepriesen wird.\n\nDiese Hoffnung besteht nur, solange SIE unter der Oberfläche bleiben. Wenn SIE sich befreien und emporsteigen, werden alle zu Wurmfutter."}},faq={{q="Welcher Gegenstand muss überbracht werden?",a="Yagyins Zusammenstellung muss überbracht werden. Sie birgt viele Wahrheiten und muss vor unfreundlichen Händen geschützt werden.",al={"welches buch ist das","was ist yagyins zusammenstellung","was mitbringen"}},{q="Wer erhält die Zusammenstellung?",a="Theldurin der Verirrte soll Yagyins Zusammenstellung erhalten.",al={"wer bekommt das buch","bei wem abgeben","wohin kommt die zusammenstellung"}},{q="Was ging dem voraus?",a="Davor kam der Schritt, bei dem Ihr drei Gegenstände im Tausch gegen Yagyins Zusammenstellung beschafft habt.",al={"vorherige quest","was führt hierzu","welche quest kommt vor verbotenes wissen"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="Sucht Agmond",s="Seit Wochen gibt es keine Nachricht von Prospector Agmond bei den Ausgrabungen im Ödland. Ausgrabungsleiter Eisenband braucht Euch nun, um Agmond zu finden und seinen Bericht zurückzubringen.",h="Seit Wochen gibt es keine Nachricht von Prospector Agmond bei den Ausgrabungen im Ödland.",kw={"agmond","festung angor","ödland","eisenschmiede","ausgrabungsleiter eisenband"},sec={{t="Ein schweigsamer Ausgrabungsleiter",b="Prospector Agmond leitete die Ausgrabungen im Ödland südwestlich von Eisenband. Eisenband nennt ihn nicht länger einen Ausgrabungsleiter, denn seit Wochen gibt es keine Nachricht von ihm. Er braucht Euch, um Agmond zu finden und den Bericht zu bergen. Von Agmond hörte man zuletzt bei der südlichsten Ausgrabung, einem kleinen Trupp jenseits der Festung Angor. Beginnt dort."},{t="Wo die Spur endet",b="Am Ende Eurer Suche findet Ihr ein Skelett, bei dem es sich um Agmonds Überreste handeln muss. Der Körper ist zertrümmert und zerschlagen, und die Knochen sind vollständig abgenagt."}},faq={{q="Wer ist Prospector Agmond?",a="Prospector Agmond leitete die Ausgrabungen im Ödland, südwestlich von Ausgrabungsleiter Eisenband.",al={"wer ist agmond","wer agmond","agmond geschichte"}},{q="Warum sucht Ausgrabungsleiter Eisenband nach Agmond?",a="Ausgrabungsleiter Eisenband hat seit Wochen nichts von Agmond gehört und braucht seinen Bericht.",al={"warum agmond finden","eisenband sucht agmond"}},{q="Wo hielt sich Prospector Agmond zuletzt auf?",a="Von Agmond hörte man zuletzt bei der südlichsten Ausgrabung im Ödland, einem kleinen Trupp jenseits der Festung Angor.",al={"agmond aufenthaltsort","wo ist agmonds ausgrabungsstätte","wo war agmond"}},{q="Was kommt davor in der Questreihe?",a="Davor kommt Ironband Wants You!",al={"vorherige quest","voraussetzung für sucht agmond"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmond liegt tot im Ödland, und neben seiner Hand ist Murdaloc in den Sandstein geritzt. Tötet seinen Mörder und überbringt Ausgrabungsleiter Eisenband in Loch Modan die Nachricht.",h="Agmond liegt tot im Ödland, und neben seiner Hand ist Murdaloc in den Sandstein geritzt.",kw={"agmond","ödland","loch modan","murdaloc","ausgrabungsleiter eisenband","stonevault bonesnapper","trogg"},sec={{t="Ein Name im Sandstein",b="Blut zeichnet Agmonds Spur von Westen her über Stein und Sand. Es zeigt, wie weit der Zwerg kroch, bevor er starb. Neben seiner reglosen Hand ist ein einziges Wort in den Sandstein des Ödlands geritzt: Murdaloc. Tötet Agmonds Mörder und eine Reihe von Stonevault Bonesnappern und überbringt dann Ausgrabungsleiter Eisenband in Loch Modan die Nachricht."},{t="Eisenbands Antwort",b="Ausgrabungsleiter Eisenband nimmt die Nachricht mit ernstem Gesicht entgegen. Er erinnert sich an Agmond als stark von Arm, grimmig mit dem Hammer und dickköpfig. Eisenband sagt, verfluchte Troggs hätten Agmond getötet. Er glaubt, dass Agmond unterwegs eine ganze Reihe von ihnen mit in den Tod gerissen hat."}},faq={{q="Wer war Agmond?",a="Agmond war ein Zwerg, der für Ausgrabungsleiter Eisenband die Ausgrabungsstätten im Ödland beaufsichtigte. Eure Suche nach ihm endete bei einem Skelett.",al={"wer ist agmond","agmond geschichte"}},{q="Wer ist Murdaloc?",a="Murdaloc ist der Name, der neben Agmonds toter Hand in den Sandstein geritzt ist. Tötet Agmonds Mörder, Murdaloc.",al={"was ist murdaloc","murdaloc geschichte"}},{q="Wohin muss der Bericht gebracht werden?",a="Bringt den Bericht zu Ausgrabungsleiter Eisenband in Loch Modan.",al={"wem von murdaloc berichten","wo ist eisenband"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="Die Legende von Stalvan",s="An Sturmwinds Kanälen findet Ihr in der Kiste der Flintridges einen Hinweis auf Stalvan Dunstmantels Vergangenheit. Ihre zerrissene Tagebuchseite weist auf Marschall Haggard im Wald von Elwynn hin.",h="An Sturmwinds Kanälen findet Ihr in der Kiste der Flintridges einen Hinweis auf Stalvan Dunstmantels...",kw={"dämmerwald","wald von elwynn","unglückseliger geist","marshal haggard","dunstmantel","versiegelte kiste","stalvan","zerrissene tagebuchseite"},ang={["faction:Alliance"]="Als Ermittler der Allianz deckt Ihr auf, wie persönliche Schrecken im Herzen von Elwynn den Marschällen von Sturmwind entgehen können.",["race:Human"]="Als Mensch seht Ihr Marschall Haggard als Teil von Sturmwinds alternder Veteranengeneration. Er bewahrt entscheidende Erinnerungen an das Königreich, bevor First and Second Wars Familien auseinanderrissen."},sec={{t="Die Vergangenheit freilegen",b="Unter einer Keramikvase in der Versiegelten Kiste liegt eine zerrissene Seite aus Stalvan Dunstmantels Tagebuch. Muffige Erbstücke der Flintridges, alte Jagdtrophäen und Familienporträts füllen die Kiste. Stalvans eigene Handschrift gewährt einen Einblick in das Leben des zurückgezogenen Gelehrten, bevor das Unglück zuschlug."},{t="Das schwindende Augenlicht des Marschalls",b="Marschall Haggard müht sich mit seinem schwindenden Augenlicht, das mitgenommene Pergament zu lesen. Die unverwechselbare Handschrift weckt Erinnerungen an Dokumente und Vorfälle aus vergangenen Jahren, bevor die Dunkelheit ihm das Augenlicht nahm."}},faq={{q="Wo befindet sich die Versiegelte Kiste?",a="Die Versiegelte Kiste steht neben den Canals von Sturmwind, direkt hinter Verwalter Folsom. Darin liegen die Habseligkeiten der Familie Flintridge, und die Seite daraus geht an Marschall Haggard im Südosten des Waldes von Elwynn.",al={"fundort der kiste","wo ist die kiste","haggard kiste"}},{q="Was befindet sich in der Versiegelten Kiste?",a="Die Kiste enthält staubige Erbstücke, ein Familienporträt, alte Bücher, Jagdtrophäen und eine Keramikvase. Unter der Vase liegt eine zerrissene Seite aus Stalvans Tagebuch.",al={"inhalt der kiste","was ist in der kiste","zerrissene seite kiste"}},{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist ein betagter Offizier aus Sturmwind im Ruhestand, der allein im Süden des Waldes von Elwynn lebt. Sein Augenlicht schwindet und er ist gebrechlich, doch seine Erinnerungen an alte Aufzeichnungen und Reisende machen ihn zu einem entscheidenden Zeugen vergangener Ereignisse.",al={"wer ist haggard","marshal haggard hintergrundgeschichte","alter marschall elwynn"}},{q="Warum ist diese Tagebuchseite wichtig?",a="Die zerrissene Seite ist ein unmittelbares Beweisstück aus Stalvan Dunstmantels eigener Hand. Ihre unverwechselbare Schrift und die darin nachklingenden Gedanken verbinden Berichte aus dem Dämmerwald und Elwynn mit seinem persönlichen Niedergang.",al={"warum die zerrissene seite wichtig ist","tagebuchseite hinweis","stalvans tagebuch"}},{q="Was geschieht, wenn die Kiste geöffnet wird?",a="Wer die Überreste von Stalvans Vergangenheit aufwühlt, schreckt die ruhelosen Toten auf. Ein rachsüchtiger Unglückseliger Geist erscheint und greift jene an, die das Unglück aufzuklären versuchen.",al={"unglückseliger geist erscheinen","geist nach kiste","warum hat ein geist angegriffen"}},{q="Wohin führt die Ermittlung als Nächstes?",a="Sobald die zerrissene Seite Marschall Haggard erreicht, lenkt seine Erinnerung an die Handschrift die Ermittlung zu weiteren erhaltenen Bruchstücken von Stalvans Geschichte.",al={"nächster schritt","nach der zerrissenen seite","wohin als nächstes"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="Der geistesabwesende Ausgrabungsleiter",s="Von der Dunkelküste schickt Hollee Wirrbarts Fossil nach Darnassus, während sie bleibt, um auf den umherwandernden Ausgrabungsleiter aufzupassen. Chefarchäologe Grauflaum zeigt reges Interesse an dem Fund.",h="Von der Dunkelküste schickt Hollee Wirrbarts Fossil nach Darnassus, während sie bleibt, um auf den...",kw={"archäologe","dunkelküste","darnassus","forscherliga","fossil","grauflaum","hollee","wirrbart"},ang={["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, ihre Völker über große Entfernungen hinweg zu verbinden. Zwergische Forscher verlassen sich auf Reisende, um Funde sicher von den abgelegenen Stränden der Dunkelküste nach Darnassus zu bringen.",["race:Dwarf"]="Als Zwerg dient Ihr mit dem Transport von Wirrbarts Fossil dem wichtigsten Ziel der Forscherliga: die ferne Vergangenheit der Welt zu ergründen und den Wert zwergischer Beharrlichkeit zu zeigen.",["race:NightElf"]="Als Nachtelf kann es Euch befremden, wenn zwergische Ausgräber uralte Überreste aus dem heiligen Boden der Dunkelküste bergen. Die Zusammenarbeit mit der Liga wahrt die Bande der Allianz."},sec={{t="Ein Kurier zur Hauptstadt",b="Ausgrabungsleiter Wirrbart hat an der Küste der Dunkelküste ein merkwürdiges Fossil gefunden. Er gräbt lieber weiter, als sich an Vorschriften zu halten. Deshalb bleibt Archäologin Hollee bei ihm, inmitten der gefährlichen Bestien und feindseligen Kultisten der Küste. Sie bittet Euch, das Exemplar nach Darnassus zu bringen, wo eine wissenschaftliche Delegation der Zwerge untergebracht ist."},{t="Zwergische Interessen in Kalimdor",b="Zwerge aus Eisenschmiede haben unter dem Banner der Forscherliga das große Meer überquert. Sie suchen in Kalimdors Boden nach uralten Relikten und verlorener Geschichte. In Darnassus staunt Chefarchäologe Grauflaum über Wirrbarts Talent, uralte Schätze zu finden. Nachtelfen betrachten ihre Wälder als lebendige Heiligtümer, während die Liga die uralten Lande als Boden sieht, den es zu erforschen und zu entschlüsseln gilt."}},faq={{q="Was ist das Geheimnisvolle Fossil?",a="Ausgrabungsleiter Wirrbart hat an der Küste der Dunkelküste ein unbestimmtes versteinertes Exemplar gefunden. Sein Alter und seine seltsame Beschaffenheit machen es zu einem begehrten Fund für die Gelehrten der Forscherliga in Darnassus.",al={"geheimnisvolles fossil","was ist das für ein fossil","wirrbarts fossil"}},{q="Warum bleibt Hollee an der Dunkelküste zurück?",a="Archäologin Hollee bleibt, um auf Ausgrabungsleiter Wirrbart aufzupassen. Er wandert bei seinen Ausgrabungen umher und missachtet Gefahren, deshalb will sie ihn nicht allein in der Wildnis lassen, während sie seine Entdeckungen nach Darnassus bringt.",al={"warum geht hollee nicht","hollee bleibt","warum hollee bleibt"}},{q="Wer ist Chefarchäologe Grauflaum?",a="Chefarchäologe Grauflaum ist ein hochrangiger Vertreter der Forscherliga von Eisenschmiede. Von Darnassus aus beaufsichtigt er die archäologischen Arbeiten im nördlichen Kalimdor und untersucht dort Relikte, die zwergische Ausgräber mitbringen.",al={"grauflaum","wer ist grauflaum","chefarchäologe grauflaum"}},{q="Warum ist die Forscherliga in Darnassus tätig?",a="König Magni Bronzebart beauftragte die Forscherliga damit, die Ursprünge des Zwergenvolks und die uralte Geschichte in ganz Azeroth zu ergründen. Freundschaftliche Beziehungen zu den Nachtelfen ermöglichen es zwergischen Gelehrten, von Darnassus aus Expeditionen zu unternehmen und Kalimdors vergessene Lande zu erforschen.",al={"zwerge in darnassus","forscherliga darnassus","warum sind zwerge hier"}},{q="Wohin gelangt dieses Fossil nach Darnassus?",a="Chefarchäologe Grauflaum untersucht das Fossil in Darnassus. Funde dieser Bedeutung sollen katalogisiert oder über die Wege der Liga an das große Museum in Eisenschmiede weitergeleitet werden.",al={"wohin kommt das fossil","fossil nächster schritt"}},{q="Wo hat Wirrbart das Exemplar gefunden?",a="Wirrbart legte das Exemplar an der wilden Küste der Dunkelküste frei, zwischen Schiffswracks, uralten Ruinen und versteinerten Meereslebewesen aus der Zeit vor der Great Sundering.",al={"wo wurde das fossil gefunden","wirrbarts ausgrabungsstätte"}}},fx={c70c2c67={q="Warum möchte Archäologin Hollee, dass das Fossil nach Darnassus geliefert wird?",a="Ausgrabungsleiter Wirrbart möchte seinen Fund sofort untersuchen lassen, aber jemand muss ihn zu ihren Vorgesetzten bringen. Hollee ist entschlossen, Dunkelküste nicht zu verlassen, während Wirrbart in der Wildnis zurückbleibt, also verlässt sie sich darauf, dass Ihr den unbezahlbaren Fund in ihrem Namen direkt zu Chefarchäologe Grauflaum nach Darnassus bringt.",al={"warum fossil nach darnassus schicken","beweggrund hollee","warum fossil zustellen"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="Die Jagd im Eschental",s="In Donnerfels schickt die Jagd im Eschental junge Champions der Horde nach Norden, um an den Waldaußenposten zu dienen. Herolde weisen sie an, sich für eine Bewährungsjagd bei Senani Donnerherz am Splitterholzposten zu melden.",h="In Donnerfels schickt die Jagd im Eschental junge Champions der Horde nach Norden, um an den Waldaußenposten...",kw={"eschental","jagd","senani","splitterholz","donnerfels","donnerherz","windschreiter","der zoramstrand"},ang={["class:Hunter"]="Als Jäger könnt Ihr Eure Fährtenlesekunst in Eschentals dichtem Wald verfeinern, wo Raubtiere durch ein Gelände streifen, das sich von den trockenen, offenen Savannen des Südens unterscheidet.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf den Splitterholzposten und den Zoramstrand, um die nördlichen Nachschubwege zu sichern. Neue Rekruten helfen dabei, wilde Tiere und feindselige Einheimische in Schach zu halten.",["race:Tauren"]="Als Tauren, der auf Mulg Ores offenen Ebenen aufgewachsen ist, steht Ihr unter Eschentals dichtem Blätterdach vor einer ungewohnten Herausforderung. Angehörige Eures Volkes wie Senani wachen über die Jagd."},sec={{t="Ein Ruf vom High Rise",b="Kliffläufer Windschreiter trägt eine offene Einladung für bewährte Abenteurer durch Donnerfels. Nördlich des Brachlands hat die Horde in einem uralten Wald Fuß gefasst, und ihre Außenposten brauchen junge Krieger. Wer dem Ruf folgt, wird sich rauerem Land stellen und seine Überlebensfähigkeiten jenseits von Mulgore auf die Probe stellen."},{t="Die nördliche Grenze",b="Eschental bietet der Horde reiche Ressourcen und große Gefahren. Der Splitterholzposten liegt an der Hauptstraße, während ein abgelegener Außenposten an der Westküste am Zoramstrand steht. Am Splitterholzposten organisiert Senani Donnerherz, eine erfahrene Wildniskundige, eine große Jagd. Dort zähmen Rekruten die Wildnis und erringen Ruhm für die Horde."}},faq={{q="Wer bietet diese Quest in Donnerfels an?",a="Kliffläufer Windschreiter überbringt vorbeiziehenden Abenteurern in Donnerfels den Ruf. Er macht fähige Kämpfer auf die Expansionsbestrebungen der Horde aufmerksam und weist ihnen den Weg zu Außenposten, die Hilfe brauchen.",al={"wer startet ashenvale hunt","questgeber ashenvale hunt","kliffläufer windschreiter"}},{q="Wo liegt der Splitterholzposten?",a="Der Splitterholzposten ist eine befestigte Siedlung der Horde im Osten von Eschental. Reist nach Norden über die Grenze des Brachlands und folgt dann dem östlichen Waldpfad tiefer in den Wald.",al={"splitterholzposten lage","wie zum splitterholzposten gelangen","wo ist splitterholz"}},{q="Wer ist Senani Donnerherz?",a="Senani Donnerherz ist eine erfahrene Fährtenleserin der Tauren, die am Splitterholzposten stationiert ist. Sie organisiert Jagden in Eschental und stellt Rekruten der Horde im Kampf gegen die örtlichen Raubtiere auf die Probe.",al={"senani donnerherz","wer ist senani","donnerherz npc"}},{q="Warum jagt die Horde in Eschental?",a="Die Horde jagt in Eschental, um Holz zu beschaffen und ihr Gebiet zu sichern. Die Jagd verringert die Zahl der wilden Tiere, die ihre Lager bedrohen, und lässt junge Abenteurer sich in unbekanntem Gelände beweisen.",al={"warum in eschental jagen","ashenvale hunt zweck","horde eschental ziele"}},{q="Was ist der Zoramstrand, der in der Einweisung erwähnt wird?",a="Der Zoramstrand ist ein Lager der Horde an der äußersten Westküste von Eschental, dem Meer zugewandt. Er ist ein zweiter Marinestützpunkt und ein Bollwerk gegen Naga und feindselige Waldbewohner.",al={"was ist der zoramstrand","zoramstrand außenposten","zoram außenposten"}},{q="Was geschieht, nachdem Ihr Euch bei Senani gemeldet habt?",a="Wenn Ihr Euch bei Senani Donnerherz meldet, heißt sie Euch am Außenposten willkommen und schickt Euch auf die umfassendere Jagd. Sie weist Euch an, Eschentals wildesten Bestien nachzustellen und sie zu bezwingen.",al={"was folgt auf ashenvale hunt","nächste quest nach senani","fortsetzung der jagd"}}},fx={af70e220={q="Warum möchte Kliffläufer Windschreiter, dass Ihr ins Eschental geht?",a="Kliffläufer Windschreiter dient als Herold für die Horde und weist fähige junge Champions den Weg dorthin, wo sie am dringendsten gebraucht werden. Die Horde sichert aggressiv ihre Grenzposten in den ungezähmten Wäldern nördlich des Brachlands, und Jäger wie Senani Donnerherz benötigen frische Rekruten, um ihre Präsenz zu verstärken und in der Wildnis Ruhm zu erlangen.",al={"warum ins eschental schicken","beweggrund von kliffläufer windschreiter","warum will windschreiter das"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="Windfuriengefahr",s="Ruul Adlerklaue prüft Eure Kampfbereitschaft gegen die Windfurienharpyien in Mulgore. Ihr Tempo und ihre Klauen werden Euch an den südöstlichen Klippen fordern, bevor Ihr die Heimat der Tauren verlasst.",h="Ruul Adlerklaue prüft Eure Kampfbereitschaft gegen die Windfurienharpyien in Mulgore.",kw={"dorf der bluthufe","windfuriengefahr","harpyien","mulgore","ruul adlerklaue","taurenprüfung","windfurien","windfury talons"},ang={["class:Warrior"]="Als Krieger lernt Ihr durch Ruul Adlerklaues Herausforderung, schnelle Sturzangriffe zu parieren. Sie schult Euch darin, wilden Angreifern aus der Luft mit festem Stand und Disziplin zu begegnen.",["faction:Horde"]="Als Verbündeter der Tauren zeigt Ihr durch Ruuls Prüfung Euren Einsatz für den Schutz des Kernlands der Horde. Sie kann Euch den Respekt des Dorfes der Bluthufe einbringen.",["race:Tauren"]="Als junger Tauren helft Ihr durch das Ausräumen der Windfuriennester, die Ebenen zu verteidigen. Unter den wachsamen Augen der Dorfältesten markiert dies Euren Übergang ins anerkannte Erwachsenenalter."},sec={{t="Das Urteil eines Lehrers",b="Ruul Adlerklaue beobachtet vom Dorf der Bluthufe aus Reisende, die Mulgore durchqueren. Er fordert jene, die erwachsen werden oder sich auf weitere Reisen vorbereiten, dazu auf, ihre Kampfinstinkte zu beweisen. Jenseits der geschützten Täler von Mulgore verlangt das Überleben nach Besonnenheit im Kampf gegen gerissene Feinde. Ruul misst Eure Stärke an den wildesten heimischen Raubtieren des Landes."},{t="Die Bedrohung der Windfurien",b="Die Windfurienharpyien nisten am südöstlichen Gebirgsrand von Mulgore, fernab der ausgetretenen Pfade. Sie bedrohen umherstreifende Wildtiere und allein reisende Wanderer. Auf der Jagd nach frischem Fleisch stürzen sie sich blitzschnell herab und schlagen mit rasiermesserscharfen Klauen zu. Besiegt sie und bringt ihre Krallen zurück, um zu beweisen, dass Ihr eine fest verwurzelte Bedrohung bezwingen und einen Angriff aus der Luft abwehren könnt."}},faq={{q="Wer ist Ruul Adlerklaue?",a="Ruul Adlerklaue ist ein erfahrener Taurenkrieger und Lehrer im Dorf der Bluthufe. Er prüft junge Abenteurer, bevor sie in die gefährlicheren Regionen Kalimdors reisen.",al={"ruul adlerklaue","wer vergibt windfuriengefahr","ruul"}},{q="Wo findet man die Windfurienharpyien in Mulgore?",a="Die Windfurienharpyien nisten entlang der südöstlichen Berge von Mulgore, in einfachen Nestern hoch auf Felsen und an den Hängen der Ausläufer. Ihre Nester liegen abseits der Hauptstraße durch das Tal.",al={"windfurienharpyien fundort","wo sind windfurienharpyien","windfuriennester fundort"}},{q="Warum gelten die Windfurienharpyien als natürliche Feinde der Tauren?",a="Die Windfurienharpyien sind angriffslustige Aasfresser, die ihr Revier verteidigen und jeden angreifen, der sich ihren Nistplätzen nähert. Ihr Hunger nach frischem Fleisch und ihre Angriffe auf Reisende und Weidetiere machen sie zu einer ständigen Bedrohung für die Ebenen.",al={"warum bekämpfen tauren harpyien","harpyienbedrohung mulgore","windfurien hintergrundgeschichte"}},{q="Welchen Beweis verlangt Ruul Adlerklaue von der Jagd?",a="Ruul fordert Euch auf, acht Windfury Talons von erlegten Harpyien zurückzubringen. Die Krallen sind ihre wichtigsten natürlichen Waffen.",al={"windfuriengefahr beweis","was für ruul sammeln","windfurien questziel"}},{q="Warum müssen sich Abenteurer dieser Prüfung stellen, bevor sie Mulgore verlassen?",a="Ruul betrachtet die Windfurienharpyien als Prüfung der Kampfbereitschaft. Ihr Tempo, ihre Wildheit und ihre Klauen fordern jene, die sich auf Gefahren jenseits der schützenden Steilhänge von Mulgore vorbereiten.",al={"zweck der prüfung","warum windfuriengefahr absolvieren","ruuls prüfung"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen von Mulgore nahe dem Stonebullsee, südlich des Great Gate und von Donnerfels. Reisende Tauren finden dort Kultur, Handel und Ausbildung.",al={"dorf der bluthufe lage","wo liegt das dorf der bluthufe","ruul standort"}}},fx={d8522cbd={q="Warum möchte Ruul Adlerklaue, dass die Windfury-Harpyien gejagt werden?",a="Ruul Adlerklaue ist ein Krieger und Mentor, der damit beauftragt ist, junge Abenteurer auf das Leben jenseits der sicheren Grenzen von Mulgore vorzubereiten. Er sieht die grausamen Windfury-Harpyien als natürliche Prüfung an – ein wahrer Maßstab für Euer kriegerisches Können und Eure Bereitschaft, Euch den härteren Bedrohungen der weiteren Welt zu stellen.",al={"warum harpyien jagen","ruuls beweggrund","grund von ruul adlerklaue"}},["1789ad72"]={q="Wer sind die Windfury-Harpyien?",a="Die Windfury-Harpyien sind wilde, vogelartige Aasfresser, die entlang der Bergvorsprünge südöstlich des Dorfes der Bluthufe nisten. Bösartig und gerissen, haben sie lange Zeit Reisende und die Tierwelt in ganz Mulgore gejagt, getrieben von einem unersättlichen Hunger nach frischem Fleisch und einer natürlichen Feindseligkeit gegenüber den Tauren.",al={"windfury-harpyien","wer sind die windfury","windfury-harpyien in mulgore"}},["29c303b8"]={q="Warum jagt Ruul Adlerklaue die Harpyien nicht selbst?",a="Ruul ist ein Lehrer, dessen Aufgabe im Dorf der Bluthufe darin besteht, die nächste Generation von Verteidigern zu fördern, nicht ihre Schlachten für sie zu schlagen. Diese Aufgabe ist ausdrücklich ein Initiationsritus: Ihr müsst Eure eigene Stärke gegen die Raubtiere von Mulgore beweisen, bevor Ihr als geeignet angesehen werdet, jenseits der Ebenen zu reisen.",al={"warum ich","warum mich schicken","warum macht ruul es nicht selbst"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="Vorbereitungen auf die Zeremonie",s="Eyahn Eagletalon fertigt einen Kopfschmuck für seinen Bruder, der bald vor Oberhäuptling Cairne Bluthuf treten wird. Er bittet Euch, die leuchtenden Federn von Harpyien jenseits von Donnerfels zu sammeln, während er die Lederbänder gerbt.",h="Eyahn Eagletalon fertigt einen Kopfschmuck für seinen Bruder, der bald vor Oberhäuptling Cairne Bluthuf...",kw={"cairne bluthuf","zeremonie","federn","harpyie","kopfschmuck","mulgore","vorbereitungen auf die zeremonie","tauren","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde ehrt Ihr die Bräuche Eurer Taurenverbündeten auf den Tafelbergen von Donnerfels, wenn Ihr ihnen bei ihren zeremoniellen Pflichten helft.",["race:Tauren"]="Als Tauren wisst Ihr, dass Kopfschmuck aus Naturmaterialien mit Ehre und Übergangsriten vor dem Oberhäuptling verbunden ist. Bei der Herstellung eines solchen Ornats zu helfen, zeigt den gemeinsamen Stolz und Geist der Stämme."},sec={{t="Dem Häuptling zu Ehren",b="Unter den Tauren erfüllt es einen mit Stolz und Ehrfurcht, vor Oberhäuptling Cairne Bluthuf zu treten. Familien ehren diesen Anlass, indem sie angemessene Kleidung vorbereiten. Der traditionelle Kopfschmuck besteht aus behandeltem Leder und symbolträchtigem Gefieder, wobei jeder Bestandteil Würde und Respekt vor dem Anführer der vereinten Stämme zeigen soll."},{t="Federn der Felsen",b="Ein zeremonieller Kopfschmuck braucht ein Lederband und Federn für seine Krone. Während die Lederriemen gegerbt werden, müssen lange, makellose Federn gesammelt werden. Harpyien nisten in den zerklüfteten Hügeln nördlich und nordwestlich von Donnerfels, also müsst Ihr Euch in ihre feindseligen Nester wagen, um Federn der benötigten Größe und Farbe zu finden."}},faq={{q="Welche Zeremonie wird vorbereitet?",a="Die Zeremonie gilt dem Auftritt eines Tauren vor Oberhäuptling Cairne Bluthuf. Sein Bruder fertigt für diesen Anlass einen Kopfschmuck aus gegerbtem Leder und leuchtenden Federn.",al={"was ist das für eine zeremonie","was ist die zeremonie","wer tritt vor bluthuf"}},{q="Wer ist Oberhäuptling Bluthuf?",a="Oberhäuptling Cairne Bluthuf führt die vereinten Taurenstämme von Donnerfels aus. Vor ihn zu treten, ist für jeden Tauren eine Ehre.",al={"wer ist oberhäuptling bluthuf","cairne bluthuf","wer ist bluthuf"}},{q="Warum werden Harpyienfedern für den Kopfschmuck benötigt?",a="Der Kopfschmuck benötigt Federn einer bestimmten Größe und Farbe. Sein Entwurf sieht azurblaues und bronzefarbenes Gefieder vor, während die Lederriemen gegerbt werden.",al={"warum werden harpyienfedern benötigt","warum harpyienfedern","warum federn"}},{q="Wo befinden sich die Harpyien?",a="Die Harpyien leben im zerklüfteten Gelände nördlich und nordwestlich von Donnerfels in Mulgore.",al={"wo leben harpyien","wo sind harpyien zu finden","wo sind azurblaue und bronzefarbene federn"}},{q="Welche Rolle spielen Harpyien in Mulgore?",a="Harpyien sind bösartige, vogelartige humanoide Wesen, die in Mulgores zerklüfteten Felsen nisten. Sie bedrohen Reisende und die Stämme, während ihr großes, farbenprächtiges Gefieder Material für zeremoniellen Schmuck liefert.",al={"warum werden harpyien gejagt","was sind harpyien"}},{q="Wer fertigt den zeremoniellen Kopfschmuck?",a="Eyahn Eagletalon gerbt die Lederriemen und fertigt den Kopfschmuck für seinen Bruder, der sich darauf vorbereitet, vor den Häuptling zu treten.",al={"wer macht den kopfschmuck","wer fertigt den kopfschmuck"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="Gemeinsame Nutzung des Landes",s="In Mulgore bittet Euch Baine Bluthuf, die Bleichmähnengnolle davon abzuhalten, die Wildtiere der Ebenen zu töten. Ihr helft, die Herden und die Lebensweise der Tauren im Einklang mit der Erdenmutter zu schützen.",h="In Mulgore bittet Euch Baine Bluthuf, die Bleichmähnengnolle davon abzuhalten, die Wildtiere der Ebenen zu...",kw={"baine bluthuf","dorf der bluthufe","gnolle","mulgore","bleichmähnen","poachers","gemeinsame nutzung des landes","kürschner","gerber"},ang={["class:Druid"]="Als Druide wisst Ihr, dass ungezügelte Wilderei dem Geist der Ebenen schadet. Die Harmonie des Landes braucht Eure Hilfe.",["class:Hunter"]="Die Kürschner und Wilderer der Bleichmähnen jagen grausam und verschwenderisch. Ihnen fehlt der Respekt eines wahren Jägers vor wilden Geschöpfen.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr Eure Verbindung zu den Anführern der jungen Taurennation, indem Ihr Baine Bluthuf helft.",["race:Tauren"]="Als junger Tauren folgt Ihr Baines Ruf, Mulgore zu verteidigen und das Gleichgewicht der Erdenmutter zu ehren."},sec={{t="Ein Land im Ungleichgewicht",b="Die Tauren nehmen vom Land nur das, was sie brauchen, und ehren die Erdenmutter in allen Dingen. Bleichmähnengnolle haben sich südlich des Dorfes der Bluthufe und in einer Höhle im Westen niedergelassen. Überall auf den Ebenen schlachten sie Wildtiere ab und lassen Kadaver zurück. Ihre verschwenderischen Jagden schaden dem Gleichgewicht des Graslandes und bedrohen die friedliche Heimat, die sich die Tauren in Mulgore aufbauen."},{t="Wenn Worte versagen",b="Baine Bluthuf versuchte, die Angelegenheit friedlich beizulegen, indem er mit den Bleichmähnengnollen sprach. Sie wiesen jeden Versuch zurück und töteten weiter Wildtiere. Nun schickt er junge Krieger in ihre Jagdlager, um die Wilderer, Gerber und Kürschner aufzuhalten, bevor das Grasland dauerhaften Schaden nimmt."},{t="Der Kreislauf von Leben und Tod",b="Bei Eurer Rückkehr lehrt Baine, dass Leben niemals aus Bosheit genommen werden darf, auch wenn es nötig sein kann, um die Harmonie zu bewahren. Leben und Tod bilden einen Kreislauf. Jeder Beschützer von Mulgore muss diese Wahrheit in sich tragen."}},faq={{q="Wer vergibt diese Quest?",a="Baine Bluthuf, Sohn des Oberhäuptlings Cairne Bluthuf, gibt Euch diese Aufgabe im Dorf der Bluthufe im Herzen von Mulgore.",al={"questgeber","wer startet gemeinsame nutzung des landes","baines quest"}},{q="Warum gehen die Tauren gegen die Bleichmähnengnolle vor?",a="Die Bleichmähnengnolle jagen Mulgores Wildtiere rücksichtslos und dezimieren die Herden. Außerdem wiesen sie die Versuche der Tauren zurück, friedlich mit ihnen zu sprechen.",al={"warum gnolle töten","bleichmähnenproblem","was haben die gnolle getan"}},{q="Wo befinden sich diese Gnolle?",a="Die Bleichmähnen lagern südlich des Dorfes der Bluthufe und leben im Höhlensystem des Bleichmähnenfelsens im Westen.",al={"standorte der gnolle","lager der bleichmähnen","wo sind bleichmähnen zu finden"}},{q="Haben die Tauren zuerst versucht, Frieden zu schließen?",a="Ja. Baine sagt, die Tauren hätten mehrmals versucht, mit den Gnollen zu sprechen und das Land zu teilen, doch die Bleichmähnen lehnten ihre friedlichen Angebote ab.",al={"haben tauren mit gnollen gesprochen","diplomatie mit den bleichmähnen"}},{q="Welche Lehre will Baine hier vermitteln?",a="Baine möchte, dass junge Verteidiger verstehen, dass Leben und Tod einen unzerbrechlichen Kreislauf bilden. Leben zu nehmen kann nötig sein, um das Gleichgewicht zu schützen, doch es muss mit Respekt vor der Erdenmutter geschehen.",al={"baines lehre","bedeutung von gemeinsame nutzung des landes"}},{q="Wer sind die Bleichmähnengnolle?",a="Die Bleichmähnengnolle sind ein primitiver, hyänenartiger Stamm, der in Mulgore heimisch ist. Sie haben blasses Fell, verteidigen ihr Gebiet aggressiv und missachten die Harmonie der Ebenen.",al={"wer sind die bleichmähnen","stamm der bleichmähnen"}}},fx={["901e0c5d"]={q="Gegen wen werdet Ihr bei Sharing the Land ausgesandt?",a="Baine sendet Euch gegen die Palemane-Gnolle, die auf die Ebenen südlich des Dorfes der Bluthufe übergegriffen haben und in einer westlichen Höhle Schutz suchen. Diese Wilderer, Abfleischer und Gerber haben rücksichtslos die Tierwelt von Mulgore abgeschlachtet, ohne Ehrfurcht vor dem Gleichgewicht oder der Erdenmutter. Da sie jedes friedliche Angebot der Tauren gewaltsam zurückgewiesen haben, ist Gewalt das einzige Mittel, das bleibt, um ihre Wilderei zu stoppen.",al={"ziele von sharing the land","wen töte ich bei sharing the land","palemane-gnolle bei sharing the land"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="Zwergenbuddelei",s="Im Dorf der Bluthufe fürchtet Baine Bluthuf, dass die Prospektoren Mulgore entstellen und seine Tiere erzürnen. Er bittet junge Verteidiger der Horde, ihre Spitzhacken zu zerbrechen und die Grabungen aufzuhalten.",h="Im Dorf der Bluthufe fürchtet Baine Bluthuf, dass die Prospektoren Mulgore entstellen und seine Tiere...",kw={"baine bluthuf","dorf der bluthufe","zwerg","schmiede","kodo","mulgore","spitzhacken","prospektor"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass unbedachte Grabungen das Grundgestein erschüttern, die Elemente aufwühlen und unter den Geistern und Geschöpfen des Landes Unruhe stiften.",["faction:Horde"]="Als Mitglied der Horde seht Ihr in Allianzzwergen, die in Hordengebiete eindringen, eine Bedrohung für den brüchigen Frieden seit dem Dritten Krieg. Sie missachten die Stammesgrenzen.",["profession:Mining"]="Als Bergarbeiter schätzt Ihr vielleicht, was im Gestein liegt, doch die Arbeit der Zwerge in Mulgore opfert Respekt und Harmonie rücksichtsloser Zerstörung.",["race:Tauren"]="Als Tauren wisst Ihr, dass der Leib der Earth Mother heilig ist. Fremde, die Mulg ores Steppen durchbohren, verlangen nach einer entschlossenen Antwort."},sec={{t="Eindringlinge in den Hügeln",b="Nordwestlich des Dorfes der Bluthufe haben zwergische Prospektoren eine Ausgrabungsstätte in Mulgore abgesteckt. Die Forscherliga durchsucht Kalimdor nach Titanenrelikten und Geheimnissen der Irdenen. Oft nehmen sie wenig Rücksicht auf die Ländereien oder Bräuche der dortigen Bewohner. Für die Tauren ist die Erde eine lebendige Mutter, die Verehrung verdient, statt nach Stein und Metall durchgraben zu werden."},{t="Die heilige Erde verteidigen",b="Baine Bluthuf sieht in den Maschinen und Sprengungen der Zwerge eine Bedrohung für das empfindliche Gleichgewicht der Ebenen. Ihr Lärm versetzt die einheimischen Tiere in Aufruhr und treibt die Kodos in Raserei. Deshalb wollen die Tauren die Spitzhacken der Prospektoren an den Schmieden zerschlagen. Die zerbrochenen Werkzeuge sollen die Zwerge warnen und die Grabungen aufhalten, bevor bleibender Schaden entsteht."}},faq={{q="Warum graben Zwerge in Mulgore?",a="Zwergische Prospektoren suchen unter Mulgore nach verborgenen Geheimnissen und Artefakten. Ihr Bergbau missachtet das Gebiet und die Bräuche der Tauren und bringt sie mit ihnen in Konflikt.",al={"zwerge in mulgore","warum sind prospektoren hier","zwergische ausgrabung mulgore"}},{q="Wer vergibt die Quest Zwergenbuddelei?",a="Baine Bluthuf erteilt den Auftrag im Dorf der Bluthufe im Herzen von Mulgore. Er ist der junge Sohn von Oberhäuptling Cairne Bluthuf.",al={"questgeber zwergenbuddelei","wer startet zwergenbuddelei"}},{q="Warum will Baine die Werkzeuge zerschlagen lassen, statt sie nur zu stehlen?",a="Baine will die Spitzhacken zerbrechen lassen, damit die Ausgrabung sofort zum Stillstand kommt. Ihre Zerstörung an den Schmieden warnt die Zwerge, dass sich die Geheimnisse des Landes nicht mit roher Gewalt gewinnen lassen.",al={"warum die spitzhacken zerbrechen","zwergenwerkzeuge zerschlagen"}},{q="Wie wirken sich die Grabungen auf Mulg ores Tierwelt aus?",a="Die Grabungen und die Wunden in der Erde versetzen Mulg ores einheimische Geschöpfe in Aufruhr, besonders die Kodos, die durch die Hügel streifen. Friedliche Herden werden reizbar und angriffslustig.",al={"wütende kodos","warum sind die tiere wütend"}},{q="Wo lassen sich die Spitzhacken zerschlagen?",a="Ihr könnt die Spitzhacken an einer funktionierenden Schmiede zerschlagen. Im Ausgrabungslager der Zwerge gibt es eine, und die Schmiede in Donnerfels haben eine weitere.",al={"wo ist die schmiede","prospektorenspitzhacken an schmiede zerschlagen"}},{q="Hängt diese Quest mit der weiteren Präsenz der Forscherliga in Kalimdor zusammen?",a="Ja. Zwergische Expeditionen aus Eisenschmiede unterhalten Außenposten in ganz Kalimdor, darunter in Mulgore, im Brachland und in Southern Kalimdor. Ihre Ansprüche auf Land und heiligen Boden führen oft zu Scharmützeln mit den Völkern der Horde.",al={"forscherliga mulgore","eisenschmiede in kalimdor"}}},fx={["755e231a"]={q="Wozu dienen die Zerbrochene Werkzeuge?",a="Die Zerbrochene Werkzeuge dienen als greifbarer Beweis dafür, dass Ihr die Operationen der Zwerge gestoppt habt. Anstatt die Goldsucher einfach zu vertreiben oder ihre Ausrüstung zu nehmen, möchte Baine Bluthuf, dass ihre Spitzhacken in einer Schmiede zerschlagen und zu ihm zurückgebracht werden, um sicherzustellen, dass ihre Arbeit eingestellt wird und ein deutliches Zeichen gegen die Entweihung der heiligen Erde gesetzt wird.",al={"zerbrochene werkzeuge","warum zerbrochene werkzeuge","zweck der zerbrochenen werkzeuge"}},["95107d94"]={q="Wer sind die Zwerge, die in Mulgore graben?",a="Es sind Zwergen-Goldsucher, die ein Ausgrabungslager in den nordwestlichen Hügeln von Mulgore errichtet haben. Angetrieben von Gerüchten, dass uralte Geheimnisse unter den Ebenen begraben liegen, suchen sie nach historischen Relikten und Titanenwissen, ohne sich um die spirituelle Entweihung zu scheren, die ihre Steinbrüche dem Land und seiner Tierwelt zufügen.",al={"zwerge in mulgore","wer sind die zwergengräber","goldsucher in mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="Die Jagd beginnt",s="In Camp Narache sammeln junge Jäger Nahrung und Federn für ihr Volk. Grull Falkenwind schickt Euch auf die Hochwolkenebene, um Ebenenschreiter zu jagen, denn das Dorf ist auf die Versorgung durch seine Jugend angewiesen.",h="In Camp Narache sammeln junge Jäger Nahrung und Federn für ihr Volk.",kw={"camp narache","häuptling falkenwind","federn","grull falkenwind","jagd beginnt","mulgore","ebenenschreiter","die hochwolkenebene"},ang={["class:Hunter"]="Als Jäger übt Ihr Treffsicherheit und Fährtenlesen, während Ihr die flinken Ebenenschreiter der Hochwolkenebene jagt. Ihr lernt auch, die Tiere zu ehren, die Euch ernähren.",["race:Tauren"]="Als junger shu'halo verbindet Euch Eure erste Jagd auf Ebenenschreiter auf der Hochebene mit dem Land und Eurer Pflicht, Camp Narache zu ernähren."},sec={{t="Der Unterhalt eines Stammes",b="Tauren jagen auf der Hochwolkenebene, um ihr Volk zu ernähren und zu kleiden. Sie schätzen das Pirschen und die Hetzjagd als Disziplinproben und als Sport. Wenn die Vorräte von Camp Narache knapp werden, sammeln junge Jäger Ebenenschreiterfleisch zum Kochen und Federn für Stammestrachten."},{t="Anerkennung verdienen",b="Grull Falkenwind beurteilt Neuankömmlinge, die hoffen, die Hochwolkenebene zu verlassen und in die weiten Ebenen von Mulgore aufzubrechen. Bevor sie seinen Vater, Häuptling Falkenwind, treffen dürfen, verlangt er von ihnen, ihr Können zu beweisen. Eine erfolgreiche Jagd zeugt von Eigenständigkeit und hilft, den Stamm zu versorgen."}},faq={{q="Wer vergibt diese Quest?",a="Grull Falkenwind gibt Euch diese Aufgabe in Camp Narache. Als Sohn von Häuptling Falkenwind leitet er junge Jäger auf der Hochwolkenebene an.",al={"questgeber","wer startet die jagd beginnt","grull falkenwind"}},{q="Warum werden Ebenenschreiter statt anderer Tiere gejagt?",a="Ebenenschreiter sind auf der Hochebene zahlreich. Ihr Fleisch füllt die knappen Nahrungsvorräte auf, und ihre Federn werden für traditionelle Kleidung und Schmuck der Tauren verwendet.",al={"warum ebenenschreiter","ebenenschreiterfleisch und federn","ebenenschreiter jagen"}},{q="Warum muss ich mich beweisen, bevor ich Häuptling Falkenwind treffe?",a="Grull Falkenwind verlangt von Euch grundlegende Überlebensfertigkeiten und Treue zum Dorf, bevor Ihr Häuptling Falkenwind trefft und größere Verantwortung übernehmt.",al={"warum sich vor häuptling falkenwind beweisen","häuptling falkenwinds anerkennung","warum zuerst jagen"}},{q="Was ist das übergeordnete Ziel dieser Prüfungen auf der Hochwolkenebene?",a="Die Hochwolkenebene prüft junge Tauren, bevor sie in die weiten Ebenen von Mulgore hinabsteigen und die Hauptstadt Donnerfels betreten.",al={"zweck der prüfungen auf der hochebene","warum bin ich auf der hochwolkenebene","die hochwolkenebene verlassen"}},{q="Was folgt nach dieser Jagd?",a="Nachdem Ihr Fleisch und Federn zurückgebracht habt, erkennt Grull Eure Jagd an und schickt Euch los, größeres, schwerer auffindbares Wild auf der Hochebene aufzuspüren.",al={"nächste quest","folgequest","was folgt nach die jagd beginnt"}},{q="Jagen Tauren nur zum Überleben?",a="Tauren jagen, um Nahrung und Materialien wie Leder, Knochen und Federn zu gewinnen. Sie jagen auch aus sportlichem Ehrgeiz und für spirituelle Verbundenheit. Die Jagd schärft die Instinkte, die ihre Stämme wachsam und stark halten.",al={"jagdphilosophie der tauren","jagd als sport","warum jagen tauren"}}},fx={["395288c5"]={q="Warum möchte Grull Falkenwind, dass dies erledigt wird?",a="Grull Falkenwind sieht Potenzial in Euch und möchte, dass Ihr Euren Wert vor dem Stamm und seinem Vater, Häuptling Falkenwind, beweist. Die Fleischvorräte von Camp Narache sind zur Neige gegangen und das Lager benötigt frische Federn. Indem er Euch aussendet, um sie zu ernten, testet er Euren Jagdinstinkt, während er gleichzeitig die lebensnotwendigen Vorräte des Dorfes wieder auffüllt.",al={"warum will grull ebenenschreiter jagen","beweggrund von grull falkenwind","warum ebenenschreiter für grull jagen"}},f26a5c4f={q="Wozu dient das Ebenenschreiterfleisch?",a="Das Fleisch wird gesammelt, um die schwindenden Nahrungsvorräte von Camp Narache wieder aufzufüllen. Das Überleben auf der Hochwolkenebene erfordert verlässliche Nahrung, und die Jagd auf Ebenenschreiter liefert das frische Fleisch, das benötigt wird, um die jungen Jäger und Ältesten im Lager zu ernähren.",al={"wofür wird ebenenschreiterfleisch benutzt","warum ebenenschreiterfleisch sammeln","nutzen von ebenenschreiterfleisch"}},fb1052a7={q="Wozu dient die Ebenenschreiterfeder?",a="Ebenenschreiterfedern werden von den Tauren von Camp Narache verwendet, um Kleidung und Schmuck herzustellen. Der Stamm verlässt sich auf jeden Teil der Tiere, die sie jagen, und verarbeitet robustes Gefieder zu praktischer Kleidung und Festtagsgewändern, die für das Leben auf der Mesa geeignet sind.",al={"wofür werden ebenenschreiterfedern benutzt","warum ebenenschreiterfedern sammeln","nutzen von ebenenschreiterfedern"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="Vergiftetes Wasser",s="Verseuchte Brunnen in Mulgore bedrohen das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält. Mull Donnerhorn im Dorf der Bluthufe bittet junge Verteidiger der Horde, Bestandteile für ein Läuterungstotem zu sammeln.",h="Verseuchte Brunnen in Mulgore bedrohen das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält.",kw={"dorf der bluthufe","läuterungstotem","mulgore","mull donnerhorn","ebenenschreiter","vergiftetes wasser","präriewolf","brunnen der winterhufe"},ang={["class:Druid"]="Als Druide wisst Ihr, dass Goblins durch das Vergiften frischer Quellen das natürliche Gleichgewicht von Mulgore bedrohen. Ihr schützt seine empfindliche Pflanzen- und Tierwelt.",["class:Shaman"]="Als Schamane reinigt Ihr verschmutztes Wasser mit einem Totem aus Tierbestandteilen und ehrt damit den Schamanismus der Tauren und seine Verbundenheit mit der heimischen Tierwelt.",["race:Tauren"]="Als Tauren wisst Ihr, dass vergiftetes Süßwasser die Gaben der Earth Mother entweiht. Die Läuterung der Brunnen ist eine Pflicht, während Ihr in Mulgore erwachsen werdet."},sec={{t="Ein entweihtes Land",b="Goblin-Eindringlinge und ihre Handlanger haben die Brunnen von Mulgore verseucht. Die Verschmutzung bedroht das Wasser, das die Taurenstämme und die heimische Tierwelt am Leben erhält. Mull Donnerhorn, ein Ältester im Dorf der Bluthufe, hat den Schaden entdeckt. Die Tauren haben sich erst kürzlich hier niedergelassen, und diese Brunnen sind lebenswichtig für das Leben auf ihren heiligen Ebenen."},{t="Die Essenz der Natur sammeln",b="Mull greift auf den Schamanismus der Tauren zurück, um den Brunnen der Winterhufe zu läutern. Er braucht ein Ritualtotem, das mit der Kraft der heimischen Tiere von Mulgore gefertigt wird. Ihr sammelt Pfoten von Präriewölfen und Krallen von ausgewachsenen Ebenenschreitern auf den südwestlichen Ebenen. Die Kraft des Landes selbst soll gegen die Verschmutzung eingesetzt werden."}},faq={{q="Wer hat die Wasserbrunnen in Mulgore vergiftet?",a="Goblin-Eindringlinge und ihre Handlanger haben die heiligen Brunnen von Mulgore verseucht und bedrohen damit das Wasser, das die Tauren und die heimische Tierwelt am Leben erhält.",al={"wer hat die brunnen verseucht","wer hat mulgore vergiftet","wer hat das wasser verschmutzt"}},{q="Warum braucht Mull Donnerhorn Wolfspfoten und Ebenenschreiterkrallen?",a="Mull verwendet Präriewolfpfoten und Ebenenschreiterkrallen, um ein Läuterungstotem herzustellen, das in der Kraft der heimischen Tiere von Mulgore verwurzelt ist.",al={"warum wolfspfoten","warum ebenenschreiterkrallen","totemmaterialien"}},{q="Die Läuterung welches Brunnens wird mit dieser Quest vorbereitet?",a="Aus den gesammelten Bestandteilen wird ein Läuterungstotem für den Brunnen der Winterhufe hergestellt.",al={"für welchen brunnen ist das","welcher wasserbrunnen"}},{q="Wo befindet sich Mull Donnerhorn?",a="Mull Donnerhorn befindet sich im Dorf der Bluthufe, der Hauptsiedlung der Tauren im Herzen von Mulgore, nahe dem Stonebullsee.",al={"mull donnerhorn standort","wo ist mull","wo vergiftetes wasser abgeben"}},{q="Wo sind die benötigten Wölfe und Ebenenschreiter zu finden?",a="Präriewölfe und ausgewachsene Ebenenschreiter durchstreifen die Ebenen südwestlich vom Dorf der Bluthufe.",al={"wo präriewölfe finden","ebenenschreiter standort","jagdgebiete"}},{q="Was geschieht, nachdem Mull die Pfoten und Krallen erhalten hat?",a="Mull bindet die Pfoten und Krallen zu einem Läuterungstotem der Winterhufe zusammen und schickt Euch dann zum Brunnen der Winterhufe, um das Läuterungsritual durchzuführen.",al={"nächste quest nach vergiftetes wasser","was ist als nächstes zu tun"}}},fx={["50414ce1"]={q="Warum möchte Mull Donnerhorn, dass dies erledigt wird?",a="Goblins und ihre Handlanger haben die heiligen Wasserbrunnen in ganz Mulgore vergiftet und treffen damit die Lebensader der Heimat der Tauren. Für Mull Donnerhorn und die Bewohner des Dorfes der Bluthufe lädt das Belassen der Brunnen in diesem Zustand Krankheit ein und entweiht das heilige Gleichgewicht der Erde. Sie zu reinigen ist eine dringende spirituelle und praktische Pflicht.",al={"beweggrund von mull donnerhorn","warum wasserbrunnen reinigen","warum quest poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="Die Überfallene Karawane",s="Nahe dem Stonebullsee zieht die Überfallene Karawane noch immer Bergungsarbeiter der Venture Company an. Taurenkrieger brannten den Konvoi nieder, nachdem sie bei einem Scharmützel Gefährten verloren hatten. Intakte Kisten zeigen das Ausmaß der Unternehmungen der Venture Company in Mulgore.",h="Nahe dem Stonebullsee zieht die Überfallene Karawane noch immer Bergungsarbeiter der Venture Company an.",kw={"morin wolkenpirscher","mulgore","überfallene karawane","stonebullsee","vorratskiste","venture company"},ang={["faction:Horde"]="Die ungehinderte Expansion des Unternehmens nach Mulgore bedroht die Stabilität von Donnerfels, weshalb Späher der Horde die Logistik der Venture Company stören müssen.",["profession:Mining"]="Die robusten Kisten und Logistikaufzeichnungen zeigen, wie die Venture Company in ganz Mulgore rücksichtslos nach mineralischen Rohstoffen sucht und sie abbaut.",["race:Tauren"]="Die Maschinen der Venture Company schänden die Ebenen, und ihre Rodungen treffen Eure angestammte Heimat unmittelbar. Ihre Vorräte zu bergen und zu zerstören hilft, Mulgore zu verteidigen."},sec={{t="Vergeltung am See",b="Taurenkrieger brannten einen Konvoi der Venture Company nieder, nachdem ein früheres Scharmützel sie zwei Gefährten gekostet hatte. Morin Wolkenpirscher und seine Krieger schlugen rasch zu und setzten dann die Wagen in Brand, um die bewaffneten Eindringlinge zu vertreiben. Sie ließen die Trümmer zurück und glaubten, das Feuer würde alles verzehren, was die Goblins hatten abtransportieren wollen."},{t="Unerledigte Angelegenheiten",b="Bergungsarbeiter der Venture Company sind zu den geschwärzten Trümmern zurückgekehrt, was darauf hindeutet, dass das Feuer nicht die gesamte Fracht vernichtet hat. Morin schickt Späher aus, um die Überreste zu untersuchen, statt blind weitere Leben zu riskieren. Intakte Kisten inmitten der rußgeschwärzten Trümmer tragen die Insignien der Venture Company Mining Division. Sie sind für den Transport zu zentralen Verarbeitungsanlagen gepackt."}},faq={{q="Warum wurde die Karawane zerstört?",a="Morin Wolkenpirscher und seine Taurenkrieger überfielen die Karawane und brannten sie als Vergeltung nieder, nachdem zwei ihrer Späher bei einem früheren Scharmützel mit der Venture Company getötet worden waren.",al={"wer hat die karawane zerstört","warum ist die karawane niedergebrannt","angriff auf die karawane"}},{q="Wo liegt die Überfallene Karawane?",a="Die ausgebrannten Wagen liegen am Nordufer des Stonebullsees, östlich vom Dorf der Bluthufe in Mulgore.",al={"standort der karawane","wo ist die karawane","standort der überfallenen karawane"}},{q="Warum kehren die Goblins zu den Trümmern zurück?",a="Die Venture Company schickte Bergungsarbeiter, weil das Feuer nicht ihre gesamte Fracht vernichtet hatte. Sie wollen robuste Vorratskisten bergen, die für den Transport zu ihren zentralen Verarbeitungsbetrieben gekennzeichnet sind.",al={"warum sind bergungsarbeiter hier","bergungsarbeiter der venture company","was wollen die goblins"}},{q="Was befindet sich in den Vorratskisten?",a="Die Kisten tragen die Insignien der Venture Company Mining Division und enthalten mineralische Rohstoffe, die zur Veredelung und Verarbeitung in den wichtigsten Industrieanlagen des Unternehmens bestimmt sind.",al={"kisteninhalt","was ist in der kiste","versiegelte vorratskiste"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Späher und Fährtenleser der Tauren, der östlich vom Dorf der Bluthufe stationiert ist. Er überwacht feindliche Vorstöße im gesamten zentralen Mulgore, insbesondere jene der Venture Company.",al={"wer ist morin","morin wolkenpirschers rolle"}},{q="Was verrät diese Karawane über die Venture Company?",a="Die Karawane zeigt, dass die Präsenz der Venture Company in Mulgore über einen bloßen Erkundungstrupp hinausgeht. Dahinter steht ein organisiertes industrielles Abbauvorhaben mit bewaffneten Nachschublinien und zentralisierten Veredelungsnetzwerken.",al={"präsenz der venture company in mulgore","warum sind goblins in mulgore"}}},fx={["89fc7cfd"]={q="Warum möchte Morin Wolkenpirscher, dass die Karawanenkisten untersucht werden?",a="Morin und seine Krieger haben den Karawanen-Konvoi der Venture Company beim Stonebullsee überfallen, um gefallene Kameraden zu rächen, die Wagen verbrannt und angenommen, dass das Feuer alles Nützliche vernichten würde. Dass Goblins als Plünderer in den Trümmern wühlten, machte ihn darauf aufmerksam, dass etwas Wertvolles oder Gefährliches die Flammen überlebt haben musste. Er braucht Euch, damit Ihr die Kisten untersucht und erfahrt, was die Venture Company durch Mulgore transportierte und warum sie so begierig darauf ist, es zurückzuholen.",al={"warum karawane untersuchen","beweggrund von morin wolkenpirscher","warum lieferkisten durchsuchen"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="Die Reise beginnt erst",s="In Orgrimmar lernen erfahrene Lederverarbeiter, wie Onyxias Schuppen vor dem Schwarzen Drachenschwarm schützen können. Oberanführer Runthak lehrt sie eine seltene Technik zur Herstellung von Umhängen gegen die Flammen der Schwarzfelsspitze.",h="In Orgrimmar lernen erfahrene Lederverarbeiter, wie Onyxias Schuppen vor dem Schwarzen Drachenschwarm...",kw={"blackrock","brutmutter","umhang","lederverarbeitung","runthak","nefarian","onyxia","schuppe"},ang={["faction:Horde"]="Für die Horde ist Schutzausrüstung aus gefallenen Feinden unerlässlich, um ihre Streitkräfte vor weiteren Verwüstungen durch Drachen zu bewahren."},sec={{t="Das Vermächtnis einer Brutmutter",b="Onyxias Fall ist ein Triumph für die Horde, doch der Schwarze Drachenschwarm bleibt eine Bedrohung. Ihre geschuppte Haut widersteht Drachenflammen. Deshalb suchen die Anführer der Horde Handwerker, die die Überreste des Drachen zu schützender Rüstung verarbeiten können, statt sie verkommen zu lassen."},{t="Schutz vor Schattenflammen",b="Oberanführer Runthak lehrt begabte Lederverarbeiter, den Onyxiaschuppenumhang zu nähen. Seine Unterweisung dient weder bloß der Zurschaustellung noch als Zeichen von Prestige. Tief im Schwarzfels speit Onyxias Bruder Nefarian verheerendes Feuer. Ohne den verzauberten Schutz der Schuppen ihrer Brutmutter würde jede Vorhut, die sich dem Lord of Blackrock stellt, zu Asche verbrennen."}},faq={{q="Wer bietet diese Quest an und wo ist diese Person zu finden?",a="Oberanführer Runthak bietet diese Quest in Orgrimmar an. Er würdigt die Champions der Horde, die meisterhafte Lederverarbeitung beherrschen und zu Onyxias Niederlage beigetragen haben.",al={"runthak questgeber","wo ist oberanführer runthak","questbeginn"}},{q="Welche Voraussetzung muss erfüllt sein, um diese Quest zu erhalten?",a="Nur erfahrene Lederverarbeiter, die die Ereignisse nach Onyxias Niederlage abgeschlossen haben, können diese Quest erhalten, etwa nach Abschluss von 'Victory for the Horde' oder 'A Most Puzzling Circumstance'.",al={"lederverarbeitung voraussetzung","wie die quest erhalten","voraussetzungen"}},{q="Was lehrt Oberanführer Runthak?",a="Oberanführer Runthak lehrt Lederverarbeiter, den Onyxiaschuppenumhang aus Schuppen der gefallenen Brutmutter herzustellen.",al={"questbelohnung rezept","onyxia umhang muster","was wird erlernt"}},{q="Warum ist der Onyxiaschuppenumhang wichtig?",a="Der Umhang schützt seinen Träger vor Nefarians tödlichem, sengendem Atem. Ohne seinen einzigartigen Schutz wäre eine Begegnung mit dem Meister der Brut tödlich.",al={"warum den umhang herstellen","zweck des umhangs","nefarian umhang"}},{q="Wer ist der Lord of Blackrock?",a="Nefarian ist der Lord of Blackrock, ein mächtiger schwarzer Drache und Onyxias Bruder. Von den Höhen des Schwarzfels aus schmiedet er Pläne, die sterblichen Völker zu unterwerfen.",al={"wer ist der lord of blackrock","nefarian identität","lord of blackrock"}},{q="Warum heißt es in der Quest, dass die Reise erst begonnen hat?",a="Onyxia wurde erschlagen, doch der größere Krieg gegen den Schwarzen Drachenschwarm und Nefarians Machenschaften im Schwarzfels hat sich nur verschärft.",al={"bedeutung des titels","warum die reise erst beginnt"}}},fx={cb1b5404={q="Warum möchte Oberanführer Runthak dies erledigt haben?",a="Oberanführer Runthak strebt die vollständige Vernichtung des Schwarzen Drachenschwarms an. Zwar war Onyxias Niederlage ein gewaltiger Triumph, doch ihre Brut sucht das Reich unter dem Befehl ihres Bruders Nefarian noch immer heim. Indem er die uralte Technik lehrt, schützende Umhänge aus den Schuppen der Brutpflegerin zu schmieden, stellt Runthak sicher, dass die Streiter der Horde über die lebenswichtige Verteidigung verfügen, die erforderlich ist, um Nefarians tödlicher Schattenglamme standzuhalten und den Krieg zu beenden.",al={"warum gibt runthak diese quest","oberanfuehrer runthak motiv","runthak ziel"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="Die Reise beginnt erst",s="In Sturmwind ehrt Major Mattingly den Handwerker, der Onyxia zu Fall brachte. Er lehrt ihn, aus ihren Schuppen einen Umhang zu fertigen.",h="In Sturmwind ehrt Major Mattingly den Handwerker, der Onyxia zu Fall brachte.",kw={"schwarzer drachenschwarm","blackrock","lederverarbeitung","major mattingly","nefarian","onyxia","onyxiaschuppenumhang","sturmwind"},ang={["faction:Alliance"]="Als Held der Allianz tragt Ihr Sturmwinds Sieg über Onyxia in die bevorstehende Offensive gegen ihren Bruder Nefarian am Schwarzfels."},sec={{t="Seltene Meisterschaft",b="Nur wenige, die halfen, Onyxia zu Fall zu bringen, können ihre Haut verarbeiten. Wenn ein Meister der Lederverarbeitung zu Major Mattingly nach Sturmwind kommt, erkennt der Offizier, wie wichtig diese Fertigkeit in kommenden Schlachten sein könnte."},{t="Schutz vor dem Schwarzen Drachenschwarm",b="Auch nach Onyxias Tod bleibt der Schwarze Drachenschwarm eine Bedrohung. Major Mattingly lehrt den Handwerker, ihre Schuppen zu behandeln und zu einem Onyxiaschuppenumhang zu vernähen. Er schützt vor dem feurigen Atem ihres Bruders Nefarian, dem Lord of Blackrock."}},faq={{q="Wer bietet die Quest Die Reise beginnt erst an?",a="Major Mattingly in Sturmwind bietet dieses Wissen Helden der Allianz an, die im Feldzug gegen Onyxia gekämpft haben und die Lederverarbeitung meistern.",al={"wer vergibt die reise beginnt erst","wo gibt es die reise beginnt erst","questgeber die reise beginnt erst"}},{q="Was lehrt diese Quest?",a="Major Mattingly lehrt Meister der Lederverarbeitung, aus Onyxias Schuppen einen Onyxiaschuppenumhang herzustellen.",al={"welches rezept gibt es","onyxia umhang rezept","belohnung für die reise beginnt erst"}},{q="Warum ist der Onyxiaschuppenumhang notwendig?",a="Der Onyxiaschuppenumhang schützt seinen Träger vor dem feurigen Atem von Nefarian, dem Lord of Blackrock.",al={"warum wird der onyxia umhang benötigt","wofür ist der onyxiaschuppenumhang","schutz vor schattenflammen"}},{q="Wer ist der Lord of Blackrock, den Major Mattingly erwähnt?",a="Nefarian ist der Lord of Blackrock, ein mächtiger schwarzer Drache und Onyxias Bruder. Er herrscht über die Schwarzfelsspitze und führt die Ränke des Schwarzen Drachenschwarms fort.",al={"wer ist lord of blackrock","wer ist nefarian","mattinglys drachenwarnung"}},{q="Warum muss der Held Lederverarbeiter sein, um dieses Wissen zu erhalten?",a="Ein Meister der Lederverarbeitung besitzt die nötigen fortgeschrittenen Fertigkeiten, um Drachenschuppen zu bearbeiten, ohne ihre magische Schutzwirkung zu zerstören.",al={"warum nur lederverarbeitung","kann jeder diese quest erhalten","voraussetzung lederverarbeiter"}},{q="Beendet Onyxias Tod die Bedrohung durch schwarze Drachen in Sturmwind?",a="Nein. Onyxia ist tot, doch ihr Bruder Nefarian herrscht weiterhin über den Schwarzfels und schmiedet Pläne gegen die Allianz und die sterblichen Völker.",al={"ist sturmwind jetzt sicher","onyxia tot was nun","schwarzer drachenschwarm nach onyxia"}}},fx={b42a6800={q="Warum bietet Euch Major Mattingly dieses Wissen an?",a="Major Mattingly weiß, dass das Töten von Onyxia nur der erste Schlag war. Die Brutmutter ist tot, aber ihre Verwandten bedrohen Azeroth immer noch von den Höhen des Schwarzfels. Um den verbleibenden Schwarzer Drachenschwarm zu eliminieren, müssen Champions die sengenden Flammen von Nefarian selbst überleben. Mattingly teilt diese spezielle Technik, damit die Helden der Allianz schützende Umhänge aus Onyxias Schuppen anfertigen und den Krieg beenden können.",al={"warum bringt mattingly es euch bei","beweggrund von major mattingly","grund von mattingly"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="Die Legende von Stalvan",s="In Elwynn führt Euch die Suche nach der Legende von Stalvan zum Haus von Marschall Haggard. Wegen seiner nachlassenden Sehkraft blieben die Papiere in einer Truhe im Obergeschoss ungelesen.",h="In Elwynn führt Euch die Suche nach der Legende von Stalvan zum Haus von Marschall Haggard.",kw={"dämmerwald","wald von elwynn","verblasste tagebuchseite","unglückseliger geist","marshal haggard","stalvan"},ang={["faction:Alliance"]="Die Suche nach Stalvans Vergangenheit führt Euch in die düstere Geschichte, die sich in Elwynns friedlichem Ackerland verbirgt.",["race:Human"]="Als Mensch folgt Ihr Stalvan durch vertraute Siedlungen und seht, wie sich Einsamkeit und Bosheit vor aller Augen verbergen können."},sec={{t="Der Dachboden eines Veteranen",b="Marschall Haggard lebt nahe dem südöstlichen Rand des Waldes von Elwynn, unweit vom Dämmerwald und dem Rotkammgebirge. Im Obergeschoss steht eine alte Truhe mit Pergamenten, die er beim Einzug in sein abgelegenes Heim fand. Seine nachlassende Sehkraft hinderte ihn daran, sie zu lesen, und sie blieben unberührt, bis Ihr nach Stalvan fragt."},{t="Verweilende Schatten",b="Die Papiere in Haggards Truhe im Obergeschoss wecken eine ruhelose Macht, die mit Stalvans Vergangenheit verbunden ist. Wenn Ihr seine Habseligkeiten aufwühlt, erscheint ein Unglückseliger Geist. Unter den Papieren trägt eine Tagebuchseite Stalvans eigene Worte und zeigt, dass der zurückgezogen lebende Gelehrte vor seinem Verschwinden Spuren in Elwynn hinterließ."}},faq={{q="Wer ist Marschall Haggard?",a="Marschall Haggard ist ein alternder Veteran, der in einer abgelegenen Hütte im Südosten des Waldes von Elwynn lebt. In seinem Heim liegen alte Papiere, die Stalvan Dunstmantel gehörten.",al={"marshal haggard","haggard elwynn","wer ist haggard"}},{q="Warum führte die Spur zurück in den Wald von Elwynn?",a="Hinweise aus Dunkelhain und Mondbruch zeichnen Stalvans Reisen durch das südliche Gebiet von Sturmwind nach. In Haggards Heim liegen Papiere, die Stalvan zurückließ.",al={"warum wald von elwynn","stalvan elwynn","warum zu haggard gehen"}},{q="Was befindet sich in der Truhe im Obergeschoss?",a="Die Truhe im Obergeschoss enthält eine verblasste Tagebuchseite von Stalvan Dunstmantel, zwischen Pergamenten, die Haggard nie richtig untersuchen konnte.",al={"truhe im obergeschoss","verblasste tagebuchseite","was ist in der truhe"}},{q="Warum greift ein Geist an, wenn die Truhe geöffnet wird?",a="Ein Unglückseliger Geist sucht Relikte aus Stalvans Vergangenheit heim. Er greift an, wenn ein Außenstehender seine Schriften und Erinnerungen aufwühlt.",al={"unglückseliger geist","warum greift der geist an","geist in haggards haus"}},{q="Wie bringt dies die Ermittlungen zu Stalvan voran?",a="Die verblasste Seite liefert Beweise aus erster Hand in Stalvans eigener Handschrift und hilft Euch, seine Vergangenheit zusammenzusetzen.",al={"stalvans geheimnis","was enthüllt die seite","schritt der stalvan-questreihe"}},{q="Warum konnte Marschall Haggard die Papiere nicht selbst lesen?",a="Das Alter hat Haggards Sehkraft geschwächt und seinen Blick getrübt. Er konnte die kleine, verwitterte Schrift auf den verblassten Papieren nicht lesen.",al={"haggard blind","warum braucht haggard hilfe"}}},fx={["7284e072"]={q="Warum möchte Marschall Haggard, dass dies erledigt wird?",a="Marschall Haggard ist ein alter Soldat, der im ruhigen Ruhestand lebt, aber er trägt immer noch die Instinkte eines Offiziers des Reiches in sich. Als Ihr kommt, um die Wahrheit über Stalvan Dunstmantel zu erfahren, erinnert er sich an die weggeworfenen Pergamente, die in der Truhe lagen, als er das Haus übernahm. Obwohl er kein persönliches Interesse an dem dunklen Geheimnis hat, möchte er Eure Ermittlungen so gut er kann unterstützen – auch wenn sein nachlassendes Augenlicht ihn daran hindert, die Papiere selbst zu untersuchen.",al={"warum haggard helfen","beweggrund von marshal haggard","warum will haggard das journal"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="Die Jagd geht weiter",s="Grull Falkenwind schickt junge Jäger in die südlichen Hügel der Hochwolkenebene, um Bergcougarpelze zu beschaffen. Die Felle sollen die Kinder des Stammes kleiden und helfen, seine Zelte auszubessern.",h="Grull Falkenwind schickt junge Jäger in die südlichen Hügel der Hochwolkenebene, um Bergcougarpelze zu...",kw={"camp narache","häuptling falkenwind","grull falkenwind","bergcougarpelze","die hochwolkenebene","jagd der tauren","die jagd geht weiter"},ang={["class:Hunter"]="Als Jäger lernt Ihr die Jagdweise der Ebenen: Pirscht Euch mit Bedacht an Tiere heran, nehmt nur das Nötige und betrachtet sie niemals als Zeitvertreib oder Trophäen.",["race:Tauren"]="Als junger Taure, der auf der Hochwolkenebene erwachsen wird, lernt Ihr, jeden Teil eines Tieres für den Stamm zu nutzen, von Nahrung über Kleidung bis zur Unterkunft. Dies ist ein wesentlicher Übergangsritus."},sec={{t="Der Zweck der Jagd",b="In Camp Narache schickt Grull Falkenwind junge Jäger nach Süden in die Hügel der Hochwolkenebene, um Bergcougars zu jagen. Hier geht es nicht um Trophäen. Die Jagd lehrt junge Jäger, für ihre Gemeinschaft zu sorgen."},{t="Schutz für den Stamm",b="Camp Narache braucht die Pelze, um Kleidung für die Kinder des Stammes herzustellen und abgenutzte Fellzelte auszubessern. Wenn Ihr sie zurückbringt, werden die Ältesten Euch für Euren Beitrag dankbar sein. Grull verspricht, seinem Vater, Häuptling Falkenwind, von Euren Taten zu berichten."}},faq={{q="Warum braucht der Stamm Bergcougarpelze?",a="Der Stamm braucht Bergcougarpelze, um Kleidung für seine Kinder herzustellen und die Dorfzelte in Camp Narache auszubessern. Grull Falkenwind sagt, dass die Felle für beides gebraucht werden.",al={"warum cougars jagen","wofür sind cougarpelze","verwendung von bergcougarpelzen"}},{q="Wer vergibt diese Quest?",a="Grull Falkenwind vergibt die Jagd in Camp Narache. Er ist ein angesehener Jäger und der Sohn von Häuptling Falkenwind, und er leitet junge Jäger dazu an, die Siedlung zu unterstützen.",al={"wer vergibt die jagd geht weiter","questgeber camp narache"}},{q="Wo sind die Bergcougars zu finden?",a="Bergcougars durchstreifen die Hügel südlich von Camp Narache auf der Hochwolkenebene.",al={"wo sind die cougars","bergcougars fundort","wo bergcougars finden"}},{q="In welcher Beziehung steht Grull Falkenwind zu Häuptling Falkenwind?",a="Grull Falkenwind ist der Sohn von Häuptling Falkenwind, dem Stammesführer in Camp Narache. Grull verspricht, mit seinem Vater über Eure Taten zu sprechen, wenn Ihr die benötigten Pelze bringt.",al={"wie häuptling falkenwind beeindrucken","häuptling falkenwinds sohn"}},{q="Was lehrt diese Jagd über die Tradition der Tauren?",a="Bei den Tauren ist die Jagd weder Zeitvertreib noch eine Suche nach Trophäen. Fell, Fleisch und Knochen eines Tieres zum Wohl der Gemeinschaft zu nutzen, ehrt die Ebenen und hilft dem Stamm zu überleben.",al={"jagdphilosophie der tauren","warum in mulgore jagen"}},{q="Warum gelten Bergcougarpelze als besonders wertvoll?",a="Bergcougarpelze sind dick und strapazierfähig und trotzen den Elementen auf den Ebenen. Sie wärmen die Kinder und helfen, Behausungen auszubessern, weshalb die Dorfältesten sie schätzen.",al={"sind cougarpelze wertvoll","warum werden cougarpelze geschätzt"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="Die Überfallene Karawane",s="In Mulgore liefert die Überfallene Karawane den Spähern der Bluthufe Beweise für einen illegalen Stützpunkt im Gebiet der Tauren. Die Venture Company plündert die Bodenschätze des Landes, und die Späher bereiten sich darauf vor, ihre angestammten Ebenen zu verteidigen.",h="In Mulgore liefert die Überfallene Karawane den Spähern der Bluthufe Beweise für einen illegalen Stützpunkt...",kw={"dorf der bluthufe","morin wolkenpirscher","mulgore","späher","überfallene karawane","vorratskiste","venture company","dokumente der venture company"},ang={["class:Druid"]="Als Druide ist Euch das Gleichgewicht des Landes heilig. Der zerstörerische, raucherfüllte Tagebau der Venture Company ist eine Entweihung, deren Spuren getilgt werden müssen.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass ihre Sicherheit von Mulg ores Treue und Stabilität abhängt. Fremde Handelskartelle, die seine Hügel verwüsten, bedrohen Donnerfels selbst.",["profession:Mining"]="Als Bergmann erkennt Ihr, dass die hochwertigen Erze in der Kiste reiche unterirdische Adern unter Mulg ores östlichen Hügeln belegen, die Fremde zur Ausbeutung anlocken.",["race:Tauren"]="Als Tauren mögt Ihr die groben Maschinen, die Mulg ores angestammte Ebenen aufreißen, als Frevel an der Earth Mother und Kriegserklärung gegen Euren neu gewonnenen Frieden ansehen."},sec={{t="Beweise der Ausbeutung",b="Östlich vom Dorf der Bluthufe liegt eine überfallene Karawane am Straßenrand. In einer versiegelten Vorratskiste befinden sich abgebautes Erz und Mineralien sowie ein zusammengebundenes Bündel Dokumente der Venture Company. Die Papiere beweisen, dass die Firma ohne Erlaubnis tief in den friedlichen Tälern von Mulgore mit dem Bergbau begonnen hat."},{t="Die Wacht der Späher",b="Morin Wolkenpirscher und seine Spähergefährten bewachen Mulg ores Grenzen mit großer Sorgfalt. Sie fürchten, dass fremde Fraktionen ihre friedliche Heimat ausbeuten werden. Als Morin die geborgenen Dokumente erhält, bestätigen sie seine schlimmsten Befürchtungen. Rauch über den östlichen Ausläufern kündet von einer sich ausweitenden Handelsinvasion. Die Tauren müssen die Schänder zurückdrängen, bevor ihre Hügel vollständig ausgehöhlt sind."}},faq={{q="Was befindet sich in der versiegelten Vorratskiste?",a="Die versiegelte Vorratskiste enthält abgebautes Erz und rohe Mineralien neben einem zusammengebundenen Bündel Dokumente der Venture Company, die ihre Tätigkeiten beschreiben.",al={"beute der vorratskiste","was ist in der kiste","kisteninhalt"}},{q="Wer ist Morin Wolkenpirscher?",a="Morin Wolkenpirscher ist ein Taurenspäher, der an der Straße östlich vom Dorf der Bluthufe in Richtung der Grenze zum Brachland stationiert ist. Er patrouilliert durch Mulgore und spürt Bedrohungen von außen auf.",al={"wer ist morin","morin wolkenpirschers aufgabe","späher morin"}},{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company will Mulg ores natürliche Ressourcen und Erzadern ausbeuten und gräbt sich ohne Rücksicht auf die Erde oder ihre Bewohner in die Hügel.",al={"warum sind goblins hier","venture company ziel mulgore","was wollen die goblins"}},{q="Woher kam die Karawane?",a="Die Karawane gehörte der Venture Company. Sie transportierte abgebautes Erz und Betriebsunterlagen von den Anlagen der Firma in den Ausläufern ab, bevor sie auf dem Weg zerstört wurde.",al={"wem gehörte die karawane","herkunft der karawane","wer hat die karawane angegriffen"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Mit den Dokumenten in der Hand schickt Morin Wolkenpirscher Krieger los, um die Führung der Venture Company zu stellen und ihren Bergbaubetrieb in den östlichen Ausläufern stillzulegen.",al={"what comes next","nächste quest nach überfallene karawane","weitere untersuchung der karawane"}},{q="Warum bedroht das die Tauren?",a="Den Tauren ist das Land heilig, und sie verehren die Earth Mother. Der rücksichtslose Tagebau und die industrielle Verschmutzung durch die Venture Company entweihen Mulg ores unberührte Landschaft.",al={"warum kümmert das die tauren","bedrohung durch die venture company","bedrohung für mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="Eine bescheidene Bitte",s="Auf der Hochwolkenebene bittet Häuptling Falkenwind einen jungen Abenteurer, nach seiner Mutter zu sehen. Dringende Stammesangelegenheiten halten ihn in Camp Narache fest, also schickt er Euch nach Südosten zu dem Brunnen, wo Großmutter Falkenwind Wasser holen wollte.",h="Auf der Hochwolkenebene bittet Häuptling Falkenwind einen jungen Abenteurer, nach seiner Mutter zu sehen.",kw={"eine bescheidene bitte","camp narache","häuptling falkenwind","großmutter falkenwind","mulgore","die hochwolkenebene","wasserbrunnen"},ang={["faction:Horde"]="Naraches ruhige, ländliche Pflichten zeigen die gemeinschaftliche Lebensweise der Tauren vor dem Hintergrund des härteren Überlebenskampfes innerhalb der noch jungen Horde.",["race:Tauren"]="Für junge Taurenkrieger zeigt das Befolgen des Häuptlingsrufs Respekt vor den Ältesten und Einsatz für das gemeinsame Wohlergehen des Stammes, wie es die Earth Mother lehrt."},sec={{t="Gemeinschaftliche Harmonie und Pflicht",b="Von jedem Stammesmitglied wird erwartet, zur Harmonie beizutragen und seinen Teil zu leisten. Für junge Tauren beginnt die Pflicht mit der Fürsorge für die Gemeinschaft, nicht allein mit dem Kampfgeschick gegen Borstennacken oder Raubtiere. Häuptling Falkenwind ist durch die Führung und Verteidigung des Lagers an seinen Posten gebunden. Deshalb vertraut er darauf, dass junge Abenteurer über die Ältesten wachen."},{t="Der Brunnen südöstlich von Narache",b="Die Brunnen außerhalb des Lagers versorgen die Hochwolkenebene mit Wasser. Großmutter Falkenwind verließ Camp Narache früh am Morgen, um frisches Wasser aus einer Quelle südöstlich des Lagers zu holen. Revierverteidigende Wildtiere und Bristleback-Borstennacken durchstreifen das Land. Wenn eine Älteste stundenlang fortbleibt, wird Häuptling Falkenwind besorgt und schickt Euch los, um sicherzugehen, dass sie unversehrt ist."}},faq={{q="Wer vergibt diese Quest und wo finde ich diese Person?",a="Häuptling Falkenwind, der Anführer von Camp Narache auf der Hochwolkenebene in Mulgore, vergibt die Aufgabe. Er befindet sich im zentralen Pavillon des Lagers und kümmert sich um die örtlichen Angelegenheiten.",al={"wer vergibt eine bescheidene bitte","wo quest annehmen","häuptling falkenwind standort"}},{q="Wo befindet sich Großmutter Falkenwind?",a="Großmutter Falkenwind befindet sich am Wasserbrunnen direkt südöstlich von Camp Narache, im tiefer gelegenen Teil der Hochebene.",al={"großmutter falkenwind standort","wo ist die mutter","wasserbrunnen standort"}},{q="Warum sieht Häuptling Falkenwind nicht selbst nach seiner Mutter?",a="Häuptling Falkenwind muss in Camp Narache bleiben, um dringende Stammesangelegenheiten zu regeln und junge Kämpfer anzuleiten. Als Häuptling vertraut er darauf, dass der Stamm für seine Mitglieder sorgt, und verlässt sich auf junge Abenteurer, die sich an seiner Stelle um Dorfangelegenheiten kümmern.",al={"warum kann der häuptling nicht gehen","warum sieht falkenwind nicht nach","häuptling falkenwind beschäftigt"}},{q="Ist Großmutter Falkenwind am Brunnen in Gefahr?",a="Aggressive Bergpumas und Schreiter durchstreifen die umliegenden Ebenen, doch Großmutter Falkenwind ist neben dem Brunnen in Sicherheit. Sie ist angenehm überrascht, dass jemand den Weg auf sich genommen hat, um nach einer Ältesten zu sehen.",al={"ist sie in sicherheit","wird großmutter angegriffen","gefahr am wasserbrunnen"}},{q="Welche kulturelle Bedeutung hat diese Quest für die Tauren?",a="Die Kultur der Tauren schätzt Familie, eine enge Gemeinschaft und Respekt vor den Ältesten. Junge Helden lernen, dass Stärke im bescheidenen Dienst und im Schutz ihrer Angehörigen liegt, nicht im Streben nach persönlichem Ruhm.",al={"taurenkultur eine bescheidene bitte","warum ist dies eine bescheidene bitte","älteste der tauren"}},{q="Was geschieht, nachdem ich Großmutter Falkenwind gefunden habe?",a="Nachdem Ihr mit Großmutter Falkenwind gesprochen habt, bittet sie Euch um weitere Hilfe dabei, die gefüllte Wasserkanne zurück ins Lager zu tragen.",al={"nächste quest","eine bescheidene bitte folgequest","was tun nachdem die mutter gefunden wurde"}}},fx={b1d313d3={q="Warum möchte Häuptling Falkenwind, dass Ihr nach seiner Mutter seht?",a="Seine betagte Mutter verließ Camp Narache früh am Morgen, um Wasser aus dem Brunnen im Südosten zu holen, und sie ist schon sehr lange fort. Das Leben der Tauren beruht auf gemeinschaftlicher Verantwortung und gegenseitiger Fürsorge, und obwohl sich Falkenwind um ihr Wohlergehen sorgt, halten ihn seine Pflichten als Häuptling im Lager fest.",al={"warum will falkenwind das erledigt haben","beweggrund von häuptling falkenwind","warum nach großmutter falkenwind sehen"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="Eine bescheidene Bitte",s="Auf der Hochwolkenebene tragen junge Tauren auf Großmutter Falkenwinds Bitte Brunnenwasser nach Camp Narache. Die Arbeit lehrt Demut und Fürsorge für den Stamm.",h="Auf der Hochwolkenebene tragen junge Tauren auf Großmutter Falkenwinds Bitte Brunnenwasser nach Camp Narache.",kw={"camp narache","häuptling falkenwind","großmutter falkenwind","eine bescheidene bitte","mulgore","die hochwolkenebene","rites of the earthmother","wasserkanne"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr, wie die Familie Falkenwind den Tauren Zusammenhalt und Überleben in Mulgore vermittelt, einem friedlichen, doch standhaften Teil von Thralls Horde.",["race:Tauren"]="Als Tauren zeigt Ihr durch das Wassertragen für Eure Ältesten Fürsorge für die Gemeinschaft und Bereitschaft, den Pfad der Erdenmutter zu beschreiten."},sec={{t="Die Lebenskraft der Jugend",b="Großmutter Falkenwind geht ihren Pflichten am Brunnen am südlichen Rand der Hochwolkenebene nach. Das Alter hat sie langsamer werden lassen, doch sie ist viele Pfade durch die Ebenen gewandert. Wenn junge Tauren, die ihr Volk verteidigen wollen, ihr begegnen, lenkt sie deren Tatkraft auf die Bedürfnisse der Gemeinschaft. Im Dienst können sie sich beweisen, indem sie für andere sorgen."},{t="Dienst am Stamm",b="Ihr tragt eine gefüllte Kanne nach Nordwesten zu Camp Narache und übergebt sie Häuptling Falkenwind, dem Anführer der Siedlung und Sohn von Großmutter Falkenwind. In den trockenen Ebenen von Mulgore hängt das Leben von gemeinsamer Arbeit und einer stetigen Versorgung mit frischem Wasser ab. Einem älteren Stammesmitglied eine Last abzunehmen, zeigt Respekt vor jenen, deren Fürsorge den Stamm zusammenhält."},{t="Ein Pfad nach Donnerfels",b="Wenn Ihr das Wasser seiner Mutter nach Camp Narache bringt, sieht Häuptling Falkenwind darin mehr als eine erledigte Pflicht. Der Brauch der Tauren verlangt von jenen, die in fernen Ländern für ihr Volk eintreten wollen, mit Demut und Hilfsbereitschaft zu beginnen. Eure stille Disziplin fällt dem Häuptling auf. Er empfiehlt Euch für die Rites of the Earthmother, spirituelle Prüfungen, die die Tore nach Donnerfels öffnen."}},faq={{q="Wer ist Großmutter Falkenwind?",a="Großmutter Falkenwind ist eine Älteste der Familie Falkenwind, die den Brunnen auf der Hochwolkenebene betreut. Sie ist die Mutter von Häuptling Falkenwind und lehrt junge Tauren Demut und Fürsorge für ihren Stamm.",al={"großmutter falkenwind","wer vergibt eine bescheidene bitte","älteste falkenwind"}},{q="Wo befindet sich der Brunnen?",a="Der Brunnen liegt südöstlich von Camp Narache auf den grasbewachsenen Ebenen der Hochwolkenebene. Daneben stehen Kannen mit frischem Wasser bereit, die Reisende und jene, die das Lager versorgen, zurücktragen können.",al={"standort des brunnens","wo ist der brunnen","wasserkanne finden"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind führt Camp Narache auf der Hochwolkenebene. Er leitet die Ausbildung und die spirituellen Riten junger Tauren, die sich darauf vorbereiten, dem gesamten Stamm in Mulgore zu dienen.",al={"häuptling falkenwind","wer ist der häuptling","anführer von camp narache"}},{q="Warum gilt diese Pflicht als wichtige Prüfung?",a="Tauren schätzen Demut, Fürsorge für die Gemeinschaft und Respekt vor den Ältesten. Alltägliche Pflichten zeigen, dass Euch Euer Volk ebenso am Herzen liegt wie Euer eigener Ruhm im Kampf.",al={"warum wasser tragen","warum eine bescheidene bitte","ist diese quest wichtig"}},{q="Was folgt nach dem Abschluss von Eine bescheidene Bitte?",a="Nachdem Ihr das Wasser getragen habt, verweist Häuptling Falkenwind Euch auf die Rites of the Earthmother, traditionelle Herausforderungen für heranwachsende Tauren.",al={"what comes next","nächste quest","nach einer bescheidenen bitte"}},{q="Wohin führt dieser Pfad schließlich?",a="Der Respekt der Ältesten bereitet Euch darauf vor, die Hochwolkenebene zu verlassen und durch Mulgore nach Donnerfels zu reisen, zu den hohen Tafelbergen der Hauptstadt.",al={"späteres reiseziel","wohin geht es","ziel donnerfels"}}},fx={["57bce500"]={q="Warum möchte Großmutter Falkenwind, dass dies erledigt wird?",a="Großmutter Falkenwind gibt zu, dass ihren alternden Beinen die frühere Kraft fehlt, was einfache tägliche Aufgaben rund um die Hochwolkenebene langsam und ermüdend macht. Wichtiger noch, sie betrachtet diesen routinemäßigen Botengang als eine wichtige moralische Lektion für Euch. Das Liefern von lebensnotwendigem Trinkwasser an ihren Sohn, Häuptling Falkenwind, dient als erste Prüfung, um zu sehen, ob Ihr die Bescheidenheit, Geduld und den Gemeinschaftsgeist besitzt, die von einem wahren Diener des Stammes erwartet werden.",al={"beweggrund von großmutter falkenwind","warum wasser zu häuptling falkenwind bringen","warum eine demütige aufgabe"}},b511fd77={q="Wozu dient die Wasserkanne?",a="Die Wasserkanne ist ein einfaches Tongefäß, das frisch aus dem Brunnen auf der Hochwolkenebene geschöpft wurde, um Camp Narache mit sauberem Wasser zu versorgen. Der Transport testet Eure Hingabe zu gemeinschaftlichen Aufgaben und stellt sicher, dass selbst angehende Abenteurer den Wert der Unterstützung ihrer Verwandten lernen, bevor sie nach größerem militärischen Ruhm streben.",al={"zweck der wasserkanne","warum wasserkanne","was ist die kanne"}},["19ad5d96"]={q="Warum bittet Großmutter Falkenwind Euch, anstatt es selbst zu tun?",a="Großmutter Falkenwind ist alt und gibt zu, dass ihre Beine nicht mehr die frühere Kraft haben, was bedeutet, dass das Tragen schwerer Kannen sie weitaus mehr Zeit kostet als früher. Wenn ein körperlich fähiger Neuling wie Ihr sich ihr nähert, ergreift sie die Gelegenheit, sowohl ihre eigene Last zu erleichtern als auch Eure Bereitschaft zu testen, unglamouröse, alltägliche Arbeit für das Lager zu verrichten.",al={"warum nicht großmutter","warum mich um wasser bitten","warum kann falkenwind kein wasser holen"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="Winterhufsäuberung",s="Der Brunnen der Winterhufe in Mulgore wurde verunreinigt. Mull Donnerhorn gibt Euch im Dorf der Bluthufe ein geweihtes Totem, um ihn zu reinigen. Die Arbeiten der Goblins haben die nahen Quellen verseucht, und die Reinigung dieses Brunnens ist der erste Schritt zur Heilung der Gewässer im zentralen Mulgore.",h="Der Brunnen der Winterhufe in Mulgore wurde verunreinigt.",kw={"dorf der bluthufe","säuberung","mulgore","mull donnerhorn","gift","totem","venture company","wasserbrunnen","winterhuf"},ang={["class:Druid"]="Als Druide seht Ihr, wie durstige Wildtiere zur gereinigten Quelle zurückkehren. Ihre Rückkehr zeigt, warum die Natur überall dort Heilung braucht, wo die Zivilisation sie bedroht.",["class:Shaman"]="Als Schamane leitet Ihr Geister durch Totems, um industrielle Verderbnis zu reinigen und Euren Bund mit den elementaren Wassern zu ehren.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Frischwasserversorgung des Taurenherzlands zu sichern, eines südlichen Pfeilers der jungen Horde.",["race:Tauren"]="Als Taure kennt Ihr Mulg ores Brunnen als heilige, lebensspendende Gaben der Erdenmutter. Sie vor der Gier der Goblins zu schützen, ist sowohl eine Pflicht gegenüber Eurem Volk als auch eine heilige Verpflichtung."},sec={{t="Ein geschändetes Land",b="Mulg ores grasbewachsene Ebenen sind auf die Brunnen der Ahnen angewiesen, um Wild und verstreute Taurenstämme zu versorgen. Die Venture Company hat kürzlich ihre Industriesöldner in die Hügel südöstlich des Dorfes der Bluthufe gebracht. Ihre Arbeiten haben das örtliche Grundwasser verseucht und den Brunnen der Winterhufe vergiftet. Wilde Tiere meiden sein Wasser, und den nahen Lagern droht Gefahr, wenn sich die Verderbnis durch das Erdreich ausbreitet."},{t="Das Ritual der Wasserreinigung",b="Mull Donnerhorn schnitzt ein Reinigungstotem und segnet es im Namen der Erdenmutter. Bewaffnete Schläger der Venture Company haben die Quelle besetzt, also müsst Ihr Euch ihnen stellen, um den Brunnen zu erreichen. Stellt das Totem an seiner Fassung auf, und es wird die verseuchten Abwässer vertreiben. Dann kann sauberes Wasser aus den Tiefen der Erde aufsteigen."}},faq={{q="Wo liegt der Brunnen der Winterhufe?",a="Der Brunnen der Winterhufe liegt in den Hügeln südöstlich des Dorfes der Bluthufe in Mulgore. Goblinarbeiter und Söldner der Venture Company patrouillieren in der Nähe.",al={"brunnen der winterhufe standort","wo ist der brunnen der winterhufe","brunnen der winterhufe finden"}},{q="Warum wurde der Brunnen vergiftet?",a="Die Venture Company begann in der Nähe mit Bergbau und Grabungen. Giftige Abwässer und Abfälle sickerten ins Grundwasser, sodass die Quelle für heimische Wildtiere und Tauren nicht mehr als Trinkwasserquelle geeignet war.",al={"wer hat das wasser vergiftet","warum ist der brunnen verschmutzt","venture company brunnen"}},{q="Wer ist Mull Donnerhorn?",a="Mull Donnerhorn ist ein spiritueller Ältester im Dorf der Bluthufe, der ein tiefes Gespür für die Gesundheit der Erde hat. Er fertigt zeremonielle Totems, um die Schäden durch fremde Eindringlinge zu heilen.",al={"wer ist mull","mull donnerhorn rolle"}},{q="Was geschieht nach der Reinigung des Brunnens?",a="Sobald der Brunnen der Winterhufe wieder klares Wasser führt und Wildtiere gefahrlos trinken können, schickt Mull Donnerhorn Euch zu weiteren gefährdeten Brunnen in Mulgore, beginnend mit dem Thunderhorn Totem.",al={"what comes next","nach der winterhufsäuberung","was tut mull als nächstes"}},{q="Wer bewacht den Brunnen?",a="Arbeiter und Mietlinge im Dienst der Venture Company halten den Brunnen besetzt. Dieses von Goblins geführte Syndikat beutet die natürlichen Rohstoffe des Landes aus, ohne Rücksicht auf das örtliche Ökosystem.",al={"wer bewacht den brunnen der winterhufe","welche feinde sind am brunnen"}},{q="Wie wirkt das Reinigungstotem?",a="Mit heiligen Riten und Schutzzeichen der Tauren geschnitzt, nutzt das Totem Naturgeister und den Segen der Erdenmutter, um die Quelle von unnatürlichen chemischen Schadstoffen zu reinigen.",al={"reinigungstotem hintergrund","wie wirkt mulls totem"}}},fx={["16ee77f0"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Winterhufe gereinigt wird?",a="Der Brunnen der Winterhufe ist lebenswichtig für das Gleichgewicht und das Überleben von Mulgore. Sein Wasser wurde verschmutzt, was sowohl die örtliche Tierwelt als auch die Stämme, die davon abhängen, bedroht. Mull Donnerhorn hat ein geweihtes Reinigungstotem vorbereitet, aber seine Kraft muss direkt zum Ort des Geschehens gebracht werden, um das Wasser zu heilen und die Harmonie im Land wiederherzustellen.",al={"warum den brunnen von winterhoof reinigen","beweggrund von mull donnerhorn","warum wasser von winterhoof reinigen"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Dienst an der Horde",s="In Orgrimmar hat Zor Einbaum den mit Juwelen besetzten Anhänger erhalten und hat Euch mehr über Euren Dienst an der Horde zu erzählen.",h="In Orgrimmar hat Zor Einbaum den mit Juwelen besetzten Anhänger erhalten und hat Euch mehr über Euren Dienst...",kw={"düstermarschen","anhänger","bericht an zor","dienst an der horde","zor einbaum"},sec={{t="Zor Einbaum in Orgrimmar",b="Der mit Juwelen besetzte Anhänger befindet sich nun bei Zor Einbaum in Orgrimmar. Kehrt zu ihm zurück, um mehr über Euren Dienst an der Horde zu erfahren."},{t="Zors letztes Wort",b="Zor sagt, die Gelehrten brauchen Zeit, um den Anhänger zu studieren. Er bietet Euch ein kleines Zeichen der Anerkennung für Euren Dienst an der Horde an. Eure Taten bringen Euch und der Horde Ehre."}},faq={{q="Wer hat den Anhänger jetzt?",a="Zor Einbaum in Orgrimmar hat den Anhänger. Ihr habt ihn von Nazeer Bloodpike in Brackenwall dorthin gebracht.",al={"wer nimmt den anhänger","wer gibt diese quest","zor einbaums rolle"}},{q="Was kommt vor dieser Quest?",a="„Bericht an Zor“ kommt zuerst. Ihr habt den mit Juwelen besetzten Anhänger zu Zor Einbaum gebracht.",al={"welche quest kam davor","dienst an der horde voraussetzung","vorherige quest"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Riten der Erdenmutter",s="Auf der Hochwolkenebene beginnen junge Tauren ihre spirituelle Reise unter der Obhut von Häuptling Falkenwind. Er schickt sie südlich von Camp Narache zu Seher Grauzunge, der ihre ersten Schritte auf dem Weg zu den Prüfungen begleitet.",h="Auf der Hochwolkenebene beginnen junge Tauren ihre spirituelle Reise unter der Obhut von Häuptling Falkenwind.",kw={"camp narache","häuptling falkenwind","erdenmutter","die hochwolkenebene","rites of the earthmother","seher grauzunge","tauren"},ang={["class:Druid"]="Als Druide beginnt Ihr Euren Weg zur Harmonie mit der Natur, indem Ihr die heilige Führung der Stammesältesten und Seher ehrt.",["class:Shaman"]="Als angehender Schamane beginnt Ihr mit Riten, die von den Sehern des Stammes gesegnet wurden. Sie sind ein unerlässlicher erster Schritt zur Gemeinschaft mit den Elementen und den Geistern Mulg ores.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr in diesen heiligen Prüfungen das spirituelle Herz Eurer taurenischen Verbündeten erkennen, die sich kürzlich der Horde angeschlossen haben.",["race:Tauren"]="Als Taure beginnt Ihr mit den Rites of the Earthmother eine spirituelle Reise. Sie prüfen Eure Bereitschaft, Eurem Stamm zu dienen und die Erdenmutter zu verehren."},sec={{t="An der Schwelle der Prüfungen",b="Auf der Hochwolkenebene schickt Häuptling Falkenwind junge Tauren zu Seher Grauzunge in den Hügeln südlich von Camp Narache. Der Seher begleitet die Jugend zu Beginn ihres spirituellen Weges. Diese Reise führt sie über den Lageralltag hinaus und hin zu den Pflichten, die ihre Stammesbräuche verlangen."},{t="Der Erdenmutter zugewandt",b="Die Erdenmutter prägt die Glaubensvorstellungen der Tauren über die Schöpfung und das tägliche Leben. Ihre Riten prüfen Reife, Widerstandskraft und spirituelle Tiefe. Seher Grauzunge warnt jene, die seine Zuflucht erreichen, dass die Prüfungen völlige Hingabe an die Traditionen der Hochebene verlangen."}},faq={{q="Wer vergibt die Quest Rites of the Earthmother?",a="Häuptling Falkenwind weist junge Tauren aus Camp Narache an, Seher Grauzunge in den umliegenden Hügeln aufzusuchen.",al={"wer startet rites of the earthmother","questgeber"}},{q="Wo kann ich Seher Grauzunge finden?",a="Seher Grauzunge lebt in den Hügeln unmittelbar südlich von Camp Narache, auf der Hochwolkenebene in Mulgore.",al={"wo ist seher grauzunge","grauzunge standort","grauzunge finden"}},{q="Was sind die Rites of the Earthmother?",a="Die Rites of the Earthmother sind heilige traditionelle Prüfungen, in denen junge Tauren ihre Weisheit, Stärke und Hingabe an ihr Volk und ihren Glauben beweisen.",al={"was sind rites of the earthmother","erdenmutter prüfungen hintergrund"}},{q="Wer ist Seher Grauzunge?",a="Seher Grauzunge ist ein angesehener spiritueller Ältester, der südlich von Camp Narache lebt und Initianden durch die heiligen Prüfungen der Erdenmutter führt.",al={"wer ist seher grauzunge","grauzunge rolle"}},{q="Wer ist Häuptling Falkenwind?",a="Häuptling Falkenwind führt Camp Narache auf der Hochwolkenebene und bereitet junge Tauren vor, bevor er sie zu den Sehern schickt.",al={"wer ist häuptling falkenwind","falkenwind rolle"}},{q="Was ist nötig, um diese Aufgabe abzuschließen?",a="Ihr reist von Camp Narache aus nach Süden in die Hügel und sprecht mit Seher Grauzunge, um Eure Bereitschaft für die Prüfungen zu bekunden.",al={"was ist zu tun","wie quest abschließen"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Totem der Donnerhörner",s="Im Dorf der Bluthufe bittet Mull Donnerhorn junge Streiter der Horde, ein heiliges Reinigungstotem zu fertigen. Die Verschmutzung durch die Venture Company breitet sich in Mulg ores Brunnen aus, und Raubtierklauen sollen die ursprüngliche Kraft der Ebenen in sein Holz binden.",h="Im Dorf der Bluthufe bittet Mull Donnerhorn junge Streiter der Horde, ein heiliges Reinigungstotem zu...",kw={"dorf der bluthufe","reinigung","pumaklauen","flachlandberglöwe","mulgore","mull donnerhorn","präriepirscher","pirscherklauen","totem der donnerhörner","wasserbrunnen"},ang={["class:Hunter"]="Als Jäger lernt Ihr die heimischen Raubtiere der Ebenen kennen und ehrt die erlegte Beute, während Ihr ihre Klauen sammelt, um das Ökosystem zu bewahren.",["class:Shaman"]="Als Schamane ruft Ihr die lebendigen Geister des Landes an, um Wasser zu reinigen, das durch unnatürliche, rücksichtslose Unternehmungen verdorben wurde.",["race:Tauren"]="Als Tauren ist es Eure heilige Stammespflicht, die Grundwasserleiter Mulg ores vor fremder Ausbeutung zu schützen. Der Auftrag der Earth Mother verlangt ein Leben im Gleichgewicht statt Plünderung."},sec={{t="Jagd auf die Raubtiere der Ebenen",b="Mull Donnerhorn braucht natürliche Klauen für ein Reinigungstotem. Die Venture Company vergiftet Mulg ores Wasser, während sie das Land ausbeutet, und Mull arbeitet an einem Gegenmittel. Präriepirscher und Flachlandberglöwen streifen östlich und westlich des Dorfes der Bluthufe umher. Ihre Klauen tragen die natürliche Essenz der Raubtiere und leiten deren rohe, unverdorbene Lebenskraft in das Totem."},{t="Das Wesen der Jagd",b="Die Tradition der Tauren unterscheidet die Jagd nach Nahrung oder für das spirituelle Gleichgewicht von der maßlosen Plünderung durch die Goblins. Mull glaubt, dass die reine Jagdweise einheimischer Raubtiere helfen kann, verdorbene Erde zu reinigen. Die Maschinen der Goblins verschmutzen die Quellen mit Öl und Industrieabfällen. Die natürliche Stärke der Tiere kann die spirituelle Kraft liefern, um den Brunnen der Donnerhörner wiederherzustellen."}},faq={{q="Warum braucht Mull Donnerhorn Raubtierklauen?",a="Mull nutzt die Klauen von Präriepirschern und Flachlandberglöwen, um den reinen, ursprünglichen Raubtiergeist der Ebenen in ein Reinigungstotem zu leiten. Er glaubt, dass der Geist natürlicher Jäger der künstlichen Verschmutzung durch die Industrie entgegenwirken kann.",al={"warum klauen","zweck der pirscherklauen","zweck der pumaklauen"}},{q="Wer verdirbt das Wasser in Mulgore?",a="Die in Mulgore tätigen Goblins der Venture Company verschmutzen das Land und das Wasser. Ihr rücksichtsloser Rohstoffabbau und ihre Bohranlagen leiten giftigen Schlamm in die Grundwasserleiter, die die Brunnen der Stämme speisen.",al={"wer hat den brunnen verseucht","warum ist der brunnen vergiftet","was hat mulgore vergiftet"}},{q="Wo findet man Präriepirscher und Flachlandberglöwen?",a="Präriepirscher und Flachlandberglöwen durchstreifen die offenen Ebenen im Herzen Mulg ores, vor allem die hügeligen Savannen östlich und westlich des Dorfes der Bluthufe.",al={"präriepirscher fundort","wo flachlandberglöwen finden","pumaklauen fundorte"}},{q="Was geschieht nach der Herstellung des Totems der Donnerhörner?",a="Nachdem Mull das Totem geschnitzt und mit den Klauen verzaubert hat, schickt er Euch zum verseuchten Brunnen der Donnerhörner. Dort vollzieht Ihr das Reinigungsritual und vertreibt das Gift.",al={"was kommt als nächstes","nach dem totem der donnerhörner","totem folgequest"}},{q="Wie hängt das mit der vorherigen Reinigung am Brunnen der Winterhufe zusammen?",a="Die Tauren bemühen sich, die heiligen Gewässer Mulg ores zu bewahren. Der Brunnen der Winterhufe wurde zuerst gereinigt, und nun bedroht die Verschmutzung den weiter nördlich gelegenen Brunnen der Donnerhörner.",al={"verbindung zu den winterhufen","vorherige totemquest"}},{q="Warum verwenden die Tauren nicht einfach Heilkräuter statt Tierklauen?",a="Die Ritualkunst der Tauren schöpft aus den elementaren und körperlichen Aspekten der Natur. Die scharfe Reinheit von Spitzenraubtieren liefert eine aktive, kämpferische spirituelle Kraft, die die aggressiven Industriegifte der Goblins durchdringen kann.",al={"warum keine kräuter","schamanische totemmaterialien"}}},fx={cb047e40={q="Warum möchte Mull Donnerhorn, dass dies getan wird?",a="Der Brunnen der Donnerhörner wird stündlich stärker verseucht, vergiftet durch rücksichtslose Goblin-Operationen in der Nähe. Mull Donnerhorn muss ein heiliges Läuterungstotem herstellen, um den Brunnen zu reinigen, bevor sich die Verderbnis weiter durch die Erde ausbreitet und seinem Volk schadet.",al={"warum mull dies möchte","mull donnerhorns motiv","warum thunderhorn totem fertigen"}},["43953f1d"]={q="Gegen welche Kreaturen werdet Ihr wegen der Krallen ausgesandt?",a="Ihr werdet ausgesandt, um die wilden Raubtiere zu jagen, die durch die Ebenen von Mulgore streifen: die Präriepirscher und Flachlandpumas. Diese Bestien durchstreifen die Gebiete östlich und westlich des Dorfes der Bluthufe auf natürliche Weise und leben und jagen als Teil des natürlichen Gleichgewichts des Landes.",al={"was jage ich","wer sind die ziele","beute für thunderhorn totem"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Ritus der Kraft",s="In Camp Narache stellen sich junge Tauren im Ritus der Kraft den Stachelebern der Bristleback. Sie bringen Häuptling Falkenwind Gürtel, um ihren Mut zu beweisen und den Stamm zu verteidigen.",h="In Camp Narache stellen sich junge Tauren im Ritus der Kraft den Stachelebern der Bristleback.",kw={"dornrankenklamm","bristleback","camp narache","häuptling falkenwind","erdenmutter","mulgore","stacheleber","ritus der kraft","seher grauzunge"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Hochwolkenebene zu verteidigen, eines ihrer wichtigsten Gebiete zur Rekrutierung neuer Mitglieder. Dort können junge Krieger und Schamanen sicher heranreifen und dem neuen Bündnis helfen.",["race:Tauren"]="Als junger Tauren beginnt Ihr die uralten Riten, indem Ihr beweist, dass Ihr Euer Volk vor den Stachelebern verteidigen könnt, bevor Ihr die Hochwolkenebene verlasst."},sec={{t="Die erste Prüfung",b="Seher Grauzunge ruft junge Tauren dazu auf, die Rites of the Earthmother mit dem Ritus der Kraft zu beginnen. Um die Anerkennung der Stammesältesten und Aufnahme in Donnerfels zu erlangen, muss sich jeder Initiand dieser Pflicht stellen. Die Prüfung zeigt, ob sie den Todfeinden des Stammes mutig entgegentreten und die Hochwolkenebene verteidigen können."},{t="Die Bedrohung durch Bristleback",b="Östlich von Camp Narache liegt die Dornrankenklamm, die Heimat der Stacheleber der Bristleback. Sie dringen in das Land der Ahnen ein, überfallen Jagdtrupps aus dem Hinterhalt und plündern im Schutz der Dunkelheit die Lagervorräte. Ihr werdet aufgefordert, sie zu erschlagen und ihre Gürtel zurückzubringen. Die Gürtel beweisen Eure Tapferkeit und tragen zur Sicherheit der Siedlung bei."}},faq={{q="Welchem Zweck dient der Ritus der Kraft?",a="Der Ritus der Kraft prüft den Mut eines jungen Tauren im Kampf und leitet die Rites of the Earthmother ein. Wer Bedrohungen für das Lager bezwingt, erwirbt als Initiand das Recht, weiter auf Anerkennung in Donnerfels hinzuarbeiten.",al={"warum den ritus der kraft absolvieren","geschichte des ritus der kraft","zweck des ritus der kraft"}},{q="Wer erteilt den Auftrag zu dieser Prüfung und beurteilt sie?",a="Seher Grauzunge erteilt den Auftrag und erklärt dessen geistige und praktische Anforderungen. Bringt Häuptling Falkenwind in Camp Narache zwölf Gürtel der Bristleback als Beweis Eurer Tapferkeit.",al={"wer erteilt den ritus der kraft","bei wem den ritus der kraft abgeben"}},{q="Wo liegt die Dornrankenklamm?",a="Die Dornrankenklamm liegt östlich von Camp Narache auf der Hochwolkenebene. Feindselige Stacheleber der Bristleback leben in ihrer dornigen Schlucht.",al={"wo liegt die dornrankenklamm","lage der dornrankenklamm"}},{q="Warum werden die Bristleback bekämpft?",a="Die Bristleback dringen in die angestammten Jagdgründe des Stammes ein. Sie überfallen Taurenjäger aus dem Hinterhalt und stehlen nachts Vorräte aus Camp Narache, wodurch sie zu Feinden des Stammes werden.",al={"warum bristleback töten","was haben die stacheleber getan"}},{q="Warum werden Gürtel statt anderer Trophäen gesammelt?",a="Die Gürtel beweisen, dass ein Initiand sich den Stachelebern gestellt und ihre erwachsenen Krieger im Nahkampf besiegt hat, statt aus der Ferne Beute aufzusammeln.",al={"warum gürtel der bristleback","warum gürtel"}},{q="Was folgt auf den Abschluss des Ritus der Kraft?",a="Das Bestehen des Ritus der Kraft beweist die Tapferkeit eines Initianden und befähigt ihn zu den nächsten Prüfungen der Erdenmutter. Diese Prüfungen setzen den förmlichen Weg zum Erwachsensein und zu geistigem Ansehen innerhalb des Stammes fort.",al={"was folgt auf den ritus der kraft","nächster ritus der erdenmutter"}}},fx={f38315d5={q="Warum schickt Euch Seher Grauzunge zu den Borstennacken?",a="Seer Grauzunge führt die Jugend von Camp Narache durch die heiligen Rites of the Earthmother. Für Eure erste Prüfung muss er Eure kämpferische Entschlossenheit gegen eine reale und dringende Gefahr für den Stamm testen. Die Borstennacken-Stacheleber dringen in die Ländereien der Tauren ein, überfallen Jäger und stehlen im Schutz der Dunkelheit. Indem er Euch schickt, um sie zu konfrontieren, stellt Grauzunge sicher, dass Ihr Euer Volk beschützt, während Ihr Eure Stärke beweist und Euch den Respekt des Stammes verdient.",al={"warum möchte grauzunge dies","seher grauzunges motiv","warum rite of strength"}},e0dd8e68={q="Warum werdet Ihr ausgesandt, diese Prüfung allein zu absolvieren?",a="Die Rite of Strength ist ein persönlicher Initiationsritus, keine einfache Aufgabe für die Garnison. Während Stammeskrieger den Außenposten bewachen, muss jeder junge Tauren unabhängig Tapferkeit und kämpferische Fähigkeiten demonstrieren, bevor er in Donnerfels als Erwachsener anerkannt wird. Die Prüfung verlangt, dass Ihr Euch den Feinden Eures Volkes selbst stellt, damit die Ältesten wissen, dass Ihr den Stamm verteidigen könnt, wenn Ihr dazu gerufen werdet.",al={"warum ich rite of strength","warum keine wachen zu borstennacken","warum muss ich gegen borstennacken kämpfen"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="Donnerhornsäuberung",s="In Mulgore ruft Euch die Donnerhornsäuberung dazu auf, den Brunnen der Donnerhörner zu reinigen. Mull Donnerhorn bereitet ein Totem für den Ritus vor, und die Ahnen von Thunderhorn danken Euch, wenn die Quelle rein ist.",h="In Mulgore ruft Euch die Donnerhornsäuberung dazu auf, den Brunnen der Donnerhörner zu reinigen.",kw={"ahnengeister","dorf der bluthufe","säuberungstotem","earth mother","mulgore","mull donnerhorn","donnerhornsäuberung","brunnen der donnerhörner"},ang={["class:Druid"]="Als Druide reinigt Ihr vergiftete Gewässer, um die Verderbnis im lebendigen Land von Mulgore aufzuhalten und die natürliche Harmonie der Ebenen zu bewahren.",["class:Shaman"]="Als Schamane leitet Ihr die Energie der Ahnen durch Totems, um verdorbene Quellen zu heilen. Das ist der Kern Eurer Berufung.",["faction:Horde"]="Als Mitglied der Horde stärkt Ihr ihren Bund mit den stolzen Shu'halo, indem Ihr den Tauren helft, ihre heiligen Quellen zu schützen.",["race:Tauren"]="Als Tauren ehrt Ihr die Earth Mother und schützt die Euren, während sie sich in Mulgore eine dauerhafte, friedliche Heimat schaffen."},sec={{t="Eine verseuchte Lebensader",b="Wasserbrunnen versorgen die Taurenstämme, die sich im Grasland von Mulgore niedergelassen haben. Wenn Gift eine unterirdische Quelle verseucht, leiden die Tierwelt und die nahen Siedlungen. Der Brunnen der Donnerhörner liegt nördlich vom Dorf der Bluthufe, und sein Wasser bedarf einer spirituellen Reinigung."},{t="Reinigung durch die Ahnen",b="Mull Donnerhorn fertigt ein Säuberungstotem für den Ritus an. Tragt es zur vergifteten Quelle und leitet die Macht der Ahnen hindurch, um die Giftstoffe zu vertreiben. Wenn die Reinigung gelingt, besuchen die Ahnen von Thunderhorn Mull im Traum und sprechen ihren Dank aus."}},faq={{q="Wo liegt der Brunnen der Donnerhörner?",a="Der Brunnen der Donnerhörner liegt in den Ebenen nördlich vom Dorf der Bluthufe in Mulgore. Er ist eine von mehreren Wasserstellen, die die örtlichen Taurenclans versorgen.",al={"standort des brunnens der donnerhörner","wo ist der brunnen","wo das totem benutzen"}},{q="Wer leitet dieses Reinigungsritual ein?",a="Mull Donnerhorn beginnt den Ritus. Er lebt im Dorf der Bluthufe und fertigt Totems an, um das leidende Land von Mulgore zu heilen.",al={"wer gibt die quest","mull donnerhorn standort","questgeber"}},{q="Warum müssen die Wasserbrunnen in Mulgore gereinigt werden?",a="Gift und Verderbnis bedrohen die Ebenen und die Taurenstämme, die auf sauberes Wasser angewiesen sind.",al={"warum brunnen reinigen","was ist mit dem wasser passiert","warum ist der brunnen vergiftet"}},{q="Woher weiß Mull, dass das Ritual erfolgreich war?",a="Nach dem erfolgreichen Ritus besuchen die Ahnen von Thunderhorn Mull im Traum und danken Euch für Eure Tat.",al={"traum von den ahnen","woher mull es weiß","ergebnis der brunnenreinigung"}},{q="Was folgt auf die Reinigung des Brunnens der Donnerhörner?",a="Nachdem der Brunnen der Donnerhörner gereinigt ist, schickt Mull Euch los, um mit der Herstellung des Wildmane Totems einer weiteren leidenden Region zu helfen.",al={"was kommt als nächstes","nächste quest nach donnerhornsäuberung","wildmane totem als nächstes"}},{q="Was ist das Läuterungstotem der Donnerhörner?",a="Das Läuterungstotem der Donnerhörner ist ein spiritueller Fokus, den Mull Donnerhorn herstellt, um das verdorbene Wasser des Ahnenbrunnens seines Clans zu reinigen.",al={"säuberungstotem","was ist der totemgegenstand","mulls totem"}}},fx={da3030fe={q="Warum benötigt Mull Donnerhorn Euch, um den Brunnen zu reinigen?",a="Mull Donnerhorn hat den rituellen Fokus gefertigt, doch die Reinigung heiligen Bodens ist ein Ritus des Dienstes und der Ehre für aufstrebende Champions unter den Tauren und ihren Verbündeten. Indem Ihr das Läuterungstotem der Donnerhörner selbst zum verseuchten Brunnen tragt, beweist Ihr Eure Hingabe an die Erdenmutter und die Ahnengeister seines Clans und verdient Euch die Gunst und Führung der Ahnen, die über die Gewässer wachen.",al={"warum ich für mull donnerhorn","warum schickt mull euch","warum läuterungsritual durchführen"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Totem der Wildmähnen",s="Am Wildmane-Brunnen will Mull Donnerhorn Mulgores letzte vergiftete Gewässer heilen. Er braucht Zähne von Präriewolfalphatieren für ein Totem, das sie reinigen kann.",h="Am Wildmane-Brunnen will Mull Donnerhorn Mulgores letzte vergiftete Gewässer heilen.",kw={"dorf der bluthufe","mulgore","mull donnerhorn","präriewolfalphatier","donnerfels","totem","wasserbrunnen","wildmane"},ang={["class:Hunter"]="Als Jäger stellt Ihr Euren Respekt vor der Wildnis und ihren wildesten Raubtieren auf die Probe, während Ihr gerissene Alphawölfe rund um die hohen Klippen aufspürt.",["class:Shaman"]="Als Schamane wisst Ihr, welche Sorgfalt nötig ist, um Raubtiertotems und elementares Wasser im Kampf gegen giftige Verderbnis in Einklang zu bringen.",["race:Tauren"]="Als Tauren erbt Ihr die Pflicht, die Brunnen der Ahnen zu heilen und zu ehren, was die Erdenmutter dem Land abverlangt."},sec={{t="Der letzte Brunnen",b="Der Wildmane-Brunnen ist die letzte vergiftete Wasserquelle im Herzen Mulgores. Mull Donnerhorn hat alles Nötige für die Brunnen der Winterhufe und der Thunderhorn gesammelt, doch vergiftetes Wasser schadet weiterhin wandernden Wildtieren und Siedlungen überall in den Ebenen. Mächtige Zutaten aus dem Land werden gebraucht, um sein Gleichgewicht wiederherzustellen."},{t="Die Stärke des Raubtiers",b="Präriewolfalphatiere durchstreifen Mulgores Grasland, besonders am Fuß der hohen Klippen unterhalb von Donnerfels. Mull Donnerhorn braucht ihre Zähne für ein reinigendes Totem, das für die nördlichen Gewässer bestimmt ist. Ihre Stärke und Ausdauer werden dem Totem die Macht dieser wilden Jäger verleihen."},{t="Opfer und Gleichgewicht",b="Für Tauren ist es eine ernste Angelegenheit, den Geschöpfen des Landes etwas zu nehmen. Mull Donnerhorn betrachtet die Alphazähne als Notwendigkeit, nicht als Eroberung. Das Opfer der Raubtiere könnte helfen, die vergifteten Gewässer der Erdenmutter zu heilen."}},faq={{q="Wofür wird das Totem der Wildmähnen gebraucht?",a="Mull Donnerhorn fertigt das Totem an, um den Wildmane-Brunnen zu reinigen, die letzte verseuchte Wasserquelle, die Mulgores Tauren bedroht.",al={"warum das totem der wildmähnen herstellen","zweck des totems der wildmähnen"}},{q="Warum werden gerade Zähne von Präriewolfalphatieren benötigt?",a="Die tiefe Verderbnis des Wildmane-Brunnens verlangt nach der wilden Stärke eines Spitzenjägers. Alphazähne bringen diese ursprüngliche Kraft in das Totem ein.",al={"warum wolfszähne","zweck der präriewolfalphazähne"}},{q="Wo findet man Präriewolfalphatiere in Mulgore?",a="Präriewolfalphatiere durchstreifen Mulgores nördliche Ebenen, besonders das Grasland am Fuß von Donnerfels.",al={"fundort der präriewolfalphatiere","wo präriewolfalphatiere finden"}},{q="Wer fertigt das Totem an?",a="Mull Donnerhorn, ein spiritueller Ältester im Dorf der Bluthufe, fertigt jedes reinigende Totem an, nachdem ein Initiand die Opfergaben gesammelt hat.",al={"wer stellt das totem her","totem questgeber"}},{q="Was folgt auf die Herstellung des Totems der Wildmähnen?",a="Nachdem Mull Donnerhorn aus den Alphazähnen ein Totem gefertigt hat, tragt Ihr es nach Norden, um den Wildmane-Brunnen zu reinigen.",al={"what comes next","totem der wildmähnen nächste quest"}},{q="Wie spiegelt dieses Ritual den Glauben der Tauren wider?",a="Tauren betrachten das Töten eines Tieres als einen feierlichen Austausch mit der Natur. Mull trauert um die getöteten Wölfe und ehrt ihren Beitrag zur Heilung der Erde.",al={"tauren philosophie totem","mull donnerhorn glaube"}}},fx={["054e923c"]={q="Warum möchte Mull Donnerhorn, dass das Wildmane Totem hergestellt wird?",a="In Mulgore muss nur noch ein korrumpierter Brunnen gereinigt werden – derjenige, der zum Wildmähnen-Clan gehört. Mull Donnerhorn hat sich der Reinigung der heiligen Brunnen der Erdenmutter verschrieben, und die Herstellung dieses letzten Läuterungstotems unter Verwendung des Raubtiergeistes des Landes ist wesentlich für den Abschluss des heiligen Ritus und die Wiederherstellung von reinem Wasser für den Stamm.",al={"warum mull wildmane totem will","mull donnerhorns motiv","warum wildmane totem herstellen"}},["2aa23a29"]={q="Wofür wird der Präriealphazahn verwendet?",a="Die Zähne des Präriewolf-Alphas repräsentieren das Opfer und die wilde Vitalität der Spitzenprädatoren von Mulgore. Mull Donnerhorn bindet acht dieser Reißzähne in das Wildmane Totem, damit dessen Geist die natürliche Ordnung besänftigen und das Ritual stärken kann, das benötigt wird, um die Verderbnis aus dem Brunnen der Wildmähnen zu tilgen.",al={"nutzung präriealphazahn","wofür sind präriealphazähne","zähne für wildmane totem"}},eb5f4bd0={q="Warum jagt Ihr Präriewolf-Alphas?",a="Ihr werdet ausgesandt, um Präriewolf-Alphas zu jagen, die dominanten Rudelführer, die die Ebenen rund um die Basis von Donnerfels durchstreifen. Ihre Stärke und Wildheit verkörpern das natürliche Gleichgewicht der Ebenen und liefern die wirkungsvolle Essenz, die Mull Donnerhorn für das letzte Wasser-Reinigungsritual benötigt.",al={"warum präriewolf-alphas töten","ziel präriewolf-alpha","hinter wem seid ihr her"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="Die Jaspismine",s="Späher sind zur Jaspismine im Osten Elwynns unterwegs, wohin sich Kobolde ausgebreitet haben könnten. Marschall Dughan muss wissen, wie weit sie vorgedrungen sind.",h="Späher sind zur Jaspismine im Osten Elwynns unterwegs, wohin sich Kobolde ausgebreitet haben könnten.",kw={"azora","dughan","elwynn","tiefenschachtmine","goldhain","jaspismine","kobold","mine","späher"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie verwundbar Sturmwinds Kerngebiete ohne zentrale königliche Unterstützung geworden sind, nachdem sowohl die Tiefenschachtmine als auch die Jaspismine verloren gingen.",["profession:Mining"]="Als Bergarbeiter seht Ihr wertvolle Vorkommen in den Tunneln der Jaspismine, doch revierverteidigende Kobolde stehen zwischen Euch und dem Erz.",["race:Human"]="Als Mensch erlebt Ihr, wie Elwynns ländliche Infrastruktur ins Wanken gerät, während grenznahe Rohstoffquellen unweit der Hauptstadt verloren gehen."},sec={{t="Ein zweiter Einfall",b="Nachdem Kobolde die Tunnel der Tiefenschachtmine südlich von Goldhain überrannt hatten, fürchtete Marschall Dughan, sie hätten weitere Minen erreicht. Die Jaspismine liegt in den felsigen Ausläufern nordöstlich des Turms von Azora. Ihr Stein und Metall versorgen das Königreich. Da die Wachen von Sturmwind für Patrouillen in der Stadt gebraucht werden, schickt Dughan unabhängige Abenteurer nach Osten, um herauszufinden, ob Kobolde auch diese Mine eingenommen haben."},{t="Überlastete Verteidigung",b="Späher, die die Kammern der Jaspismine erreichen, stellen fest, dass Kobolde die menschlichen Bergleute vertrieben und die dunklen Gänge befestigt haben. Marschall Dughan trifft ein weiterer Schlag, während sich die Krise verschärft. König Varian Wrynn ist verschollen, und königliche Truppen werden weiterhin von den entlegenen Gebieten ferngehalten. Die örtliche Garnison hat zu wenige Soldaten, um die Mine zu räumen. Dem Herzen des Königreichs fehlen Rohstoffe, und Bedrohungen engen es ein."}},faq={{q="Wo liegt die Jaspismine?",a="Die Jaspismine liegt in den nördlichen Ausläufern im Osten des Waldes von Elwynn. Reist von Goldhain auf der Hauptstraße nach Osten, passiert den Turm von Azora und wendet Euch dann nach Norden in die Hügel.",al={"wo ist die jaspismine","lage der jaspismine","wie die jaspismine finden"}},{q="Warum braucht Marschall Dughan einen Späher, statt Wachen zu schicken?",a="Marschall Dughan kann zu wenige Wachen entbehren. König Varian Wrynn ist verschollen, und der politische Stillstand in der Hauptstadt hat die örtlichen Truppen beim Schutz von Höfen und Ortschaften vor Banditen und Gnollen überlastet. Deshalb verlässt sich Dughan auf zivile Späher.",al={"warum abenteurer schicken","warum keine wache von sturmwind","wo sind die wachen"}},{q="Warum besetzen Kobolde die Minen Elwynns?",a="Kobolde graben Tunnel zu Erzadern und feuchten Höhlen. Als Sturmwinds militärische Präsenz nachließ, wurden sie kühner und drangen in menschliche Minen wie die Tiefenschachtmine und die Jaspismine vor, um Gold, Erz und Gebiete zu beanspruchen.",al={"warum kobolde in der jaspismine","was wollen kobolde","grund für koboldbefall"}},{q="Was geschieht nach der Erkundung der Jaspismine?",a="Nachdem Ihr den Fall der Jaspismine gemeldet habt, steht Marschall Dughan vor dem Verlust der Minen im Osten und Bedrohungen an mehreren Fronten. Er richtet seine Aufmerksamkeit auf den Westen Elwynns, wo Riverpaw-Gnolle die Weststromgarnison stark unter Druck setzen.",al={"was kommt nach der jaspismine","fortsetzung nach der jaspismine"}},{q="Warum ist der Verlust der Jaspismine für Sturmwind bedeutend?",a="Elwynns Minen liefern Erz und Stein, die Sturmwind für seine Wirtschaft und zum Schmieden von Waffen und Rüstungen braucht. Der Verlust der Tiefenschachtmine und der Jaspismine bringt den Rohstoffabbau zum Erliegen und schwächt die Erholung des Königreichs.",al={"warum die jaspismine wichtig ist","bedeutung der jaspismine"}},{q="Wem gehört der nahe gelegene Turm von Azora?",a="Der Turm von Azora ist ein kleiner Magierturm an der östlichen Straße des Waldes von Elwynn. Theocritus, der Erzmagier von Azora, hat dort den Vorsitz, und Azoras Diener kümmern sich um den Turm. Reisende nutzen ihn als Orientierungspunkt auf dem Weg zu den östlichen Ausläufern.",al={"was ist der turm von azora","wer lebt im turm von azora"}}},fx={a973508b={q="Warum möchte Marschall Dughan, dass die Jaspismine erkundet wird?",a="Nachdem bereits bestätigt wurde, dass Kobolde die The Fargodeep Mine überrannt haben, fürchtet Marschall Dughan, dass der Befall kein isolierter Vorfall ist. Er muss wissen, ob sich die Bedrohung auch nach Osten zur Jaspismine ausgebreitet hat. Die Sicherung der Ressourcenversorgung von Elwynn und das Verständnis des vollen Ausmaßes der heraufziehenden Gefahr sind entscheidend für die Verteidigung der Ortschaft Goldhain und den Schutz der wichtigen Handelsrouten von Sturmwind.",al={"dughans motiv jaspismine","warum jaspismine auskundschaften","warum muss dughan jaspismine untersucht haben"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmähnensäuberung",s="In Mulgore erreicht die Läuterung durch die Tauren den letzten Brunnen. Mull Donnerhorn im Dorf der Bluthufe schickt Euch mit dem fertigen Wildmane Totem nach Norden, um das vergiftete Wasser zu läutern und die Lebensweise der Tauren zu schützen.",h="In Mulgore erreicht die Läuterung durch die Tauren den letzten Brunnen.",kw={"dorf der bluthufe","läuterung","earth mother","mulgore","mull donnerhorn","totem","venture company","wasserbrunnen","wildmähnen"},ang={["class:Druid"]="Als Druide helft Ihr, die Zerstörung durch die Goblins rückgängig zu machen, indem Ihr verseuchte Ökosysteme heilt und Mulg ores Weiden schützt.",["class:Shaman"]="Als Schamane nutzt Ihr rituelle Totems, um maschinell verursachte Verschmutzung zu beseitigen und die Harmonie zwischen den Naturelementen und den lebenden Gemeinschaften zu bewahren.",["race:Tauren"]="Als Taure ist die Wiederherstellung der drei angestammten Brunnen Mulg ores für Euch ein Übergangsritus. Er beweist Eure Hingabe an die Bewahrung der Gaben der Earth Mother."},sec={{t="Die Gabe der Earth Mother läutern",b="Mulg ores Brunnen versorgen die Herden, den Boden und die Taurenstämme, die sich um Donnerfels versammelt haben. Die Venture Company und vordringende Goblins haben sie mit giftigen Industrieabwässern verseucht. Die Ältesten der Tauren erkennen die Gefahr für ihr Volk und ihr Land.\n\nDer Brunnen der Winterhufe und der Brunnen der Donnerhörner sind geläutert. Nun bleibt der Brunnen der Wildmähnen, die dritte und letzte verderbte Stätte. Sein Wasser bedarf noch der spirituellen Läuterung."},{t="Das Wildmane Totem",b="Das Läuterungstotem der Wildmähnen wird aus Elementen gefertigt, die in der ganzen Region gesammelt wurden. Es schöpft aus der heilenden Kraft der Ahnengeister und der elementaren Erde. Stellt es neben dem verseuchten Wasser nördlich von Donnerfels auf. Das Ritual zerstreut Chemikalien, zieht Giftstoffe heraus und belebt den natürlichen Wasserfluss.\n\nDie Läuterung schützt die Tauren vor Krankheiten. Sie macht auch deutlich, dass sie die Schändung ihres heiligen Landes nicht dulden werden."}},faq={{q="Warum wurde der Brunnen der Wildmähnen vergiftet?",a="Von industrieller Gier getriebene Goblinbetriebe und Holzunternehmen vergifteten Mulg ores Grundwasser mit chemischen Abfällen. Die Abfälle bedrohen die Tierwelt und die Stammessiedlungen.",al={"wer hat den brunnen vergiftet","warum ist der brunnen schmutzig","goblingift"}},{q="Wo liegt der Brunnen der Wildmähnen?",a="Der Brunnen der Wildmähnen liegt auf den Ebenen direkt nördlich der hoch aufragenden Tafelberge von Donnerfels.",al={"standort des brunnens der wildmähnen","wo ist der brunnen der wildmähnen","brunnen der wildmähnen finden"}},{q="Wer leitet dieses Läuterungsritual ein?",a="Mull Donnerhorn, ein Ältester im Dorf der Bluthufe, leitet Euch bei der Herstellung der Totems an und schickt Euch aus, die Brunnen zu läutern.",al={"wer vergibt wildmähnensäuberung","questgeber","mull donnerhorn standort"}},{q="Welche anderen Brunnen gehören zu dieser Läuterung?",a="Der Brunnen der Wildmähnen ist die dritte von drei lebenswichtigen Wasserquellen. Der Brunnen der Winterhufe und der Brunnen der Donnerhörner, beide im Süden, kamen zuerst.",al={"andere brunnen","brunnen in mulgore","brunnen der winterhufe und donnerhörner"}},{q="Wie wirkt das Läuterungstotem?",a="Das mit Ahnenmagie und geläuterten Naturelementen gefertigte Totem leitet heilende spirituelle Kraft ins Grundwasser, um die Schadstoffe der Goblins zu neutralisieren.",al={"funktionsweise des läuterungstotems","wie reinigt das totem wasser"}},{q="Was bedeutet der Abschluss dieses Rituals für das Dorf der Bluthufe?",a="Die Läuterung aller drei Brunnen sichert den Stämmen im Herzen Mulg ores sauberes Trinkwasser. Sie ehrt die Pflicht der Tauren, die Earth Mother von den Schäden industrieller Ausbeutung zu heilen.",al={"ergebnis der quest","warum die brunnen läutern","bedeutung für die geschichte der tauren"}}},fx={["119d5a48"]={q="Warum möchte Mull Donnerhorn, dass der Brunnen der Wildmähnen gereinigt wird?",a="Mull Donnerhorn wacht über das spirituelle Gleichgewicht und die lebenswichtigen Ressourcen von Mulgore. Die üblen Operationen der Venture Company vergifteten die kostbaren Wasserquellen des Landes und bedrohten das Überleben der Stämme und ihrer Herden. Der Brunnen der Wildmähnen ist der letzte der drei alten Brunnen, die noch verseucht sind, und seine Reinigung ist unerlässlich, um die Erdenmutter zu heilen und sicheres Trinkwasser für das Dorf der Bluthufe und Donnerfels zu sichern.",al={"mull donnerhorns motiv","warum brunnen der wildmähnen reinigen","warum liegen mull die brunnen am herzen"}},b4cee6a1={q="Was ist das Läuterungstotem der Wildmähnen?",a="Das Läuterungstotem der Wildmähnen ist ein rituell vorbereitetes Hilfsmittel, das von Mull Donnerhorn gefertigt wurde, um Ahnen- und Erdgeister zu kanalisieren. Wenn es am verseuchten Brunnen der Wildmähnen nördlich von Donnerfels aktiviert wird, stößt das Totem den giftigen Schlamm aus, der von Goblin-Umweltverschmutzern hinterlassen wurde, reinigt den Grundwasserleiter und versetzt die Quelle in ihren natürlichen, ursprünglichen Zustand zurück.",al={"nutzung läuterungstotem der wildmähnen","was ist das wildmane totem","zweck läuterungstotem"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="Sturzfliegerjagd",s="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen. Ihre Kielfedern stellen Geduld, Schläue und Treffsicherheit auf die Probe und ehren die Prüfungen der Erdenmutter.",h="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen.",kw={"dorf der bluthufe","harken windtotem","mulgore","sturzflieger","sturzfliegerjagd","tauren prüfung","trophäensturzfliegerkiel"},ang={["class:Druid"]="Als Druide kommt Ihr beim Verfolgen von Sturzfliegern über die Tafelberge von Mulgore den Raubvögeln näher, die das Gleichgewicht am Himmel wahren helfen.",["class:Hunter"]="Als Jäger lernt Ihr beim Verfolgen von Sturzfliegern, fliegender Beute nachzustellen, ihr Verhalten zu deuten und wachsame Raubvögel mit präzisen Angriffen zu treffen.",["race:Tauren"]="Als Taure ist die Jagd auf Mulg ores flinke Sturzflieger für Euch ein Übergangsritus. Sie schärft Eure Fähigkeiten im Fährtenlesen und bewahrt die Bräuche der Ahnen."},sec={{t="Eine Prüfung scharfer Augen",b="Im offenen Grasland von Mulgore stellen Sturzflieger das Auge eines Jägers auf die Probe. Diese großen Vögel verschmelzen mit Himmel und Ebene, kreisen hoch oben oder gleiten tief durch das hohe Gras. Sie verlangen Konzentration und flinke Füße, anders als schwerfällige Ebenenschreiter oder grasende Kodos. Junge Jäger stellen ihnen nach, um ihr Können zu beweisen und sich Ansehen unter den Stämmen zu verdienen."},{t="Zeichen der Jagd",b="Harken Windtotem verlangt Trophäenkielfedern, um Disziplin zu lehren, nicht um die Tierwelt auszudünnen. Tauren tragen Andenken an eine hart erkämpfte Pirsch als Zeichen von Schläue und Ausdauer. Makellose Kielfedern, den Ältesten im Dorf der Bluthufe überreicht, zeigen, dass ein Jäger die Gemeinschaft ernähren und verteidigen kann. Flinke Hufe und scharfe Sinne bereiten sie auf die weite Welt vor."}},faq={{q="Welchen Zweck hat die Jagd auf Sturzflieger für Harken Windtotem?",a="Harken Windtotem bittet Euch, Sturzfliegern in ganz Mulgore nachzustellen und Eure Schläue, Schnelligkeit und Hingabe auf die Probe zu stellen. Unversehrte Trophäenkielfedern bezeugen Euer Können und bringen Euch Ehre unter den Tauren im Dorf der Bluthufe.",al={"warum sturzflieger jagen","harken windtotem quest zweck","sturzfliegerjagd zweck"}},{q="Wo begegnet man Sturzfliegern gewöhnlich?",a="Sturzflieger durchstreifen die offenen Ebenen von Mulgore, segeln über dem Gras oder suchen außerhalb von Siedlungen wie dem Dorf der Bluthufe nach Beute.",al={"wo sind sturzflieger","sturzflieger fundorte mulgore","sturzflieger finden"}},{q="Warum gelten Sturzflieger als schwierige Jagdbeute?",a="Sturzflieger sind schnelle, wachsame Raubvögel, die über die Ebenen verstreut leben. Ihr braucht scharfe Augen, um sie zu erspähen, und schnelle Schritte, um sie einzuholen, bevor sie entkommen.",al={"warum sind sturzflieger schwer zu fangen","sturzflieger verhalten"}},{q="Was bedeuten die Trophäenkielfedern für die Tauren?",a="Trophäensturzfliegerkiele stehen für Geduld, einen scharfen Blick und eine erfolgreiche Jagd. Sie zeigen, dass Ihr die Instinkte besitzt, um den Stamm zu versorgen und zu beschützen.",al={"trophäensturzfliegerkiel bedeutung","bedeutung der kielfedern"}},{q="Wer ist Harken Windtotem?",a="Harken Windtotem ist ein angesehener Taure aus dem Dorf der Bluthufe. Er beobachtet Neuankömmlinge und angehende Jäger und beurteilt ihren Einfallsreichtum durch traditionelle Prüfungen in den Ebenen.",al={"wer vergibt sturzfliegerjagd","harken windtotem hintergrundgeschichte"}},{q="Beeinflusst diese Jagd das Gleichgewicht der Natur in Mulgore?",a="Die Tauren betrachten die Jagd als heiligen Austausch mit der Erdenmutter, nicht als mutwilliges Abschlachten. Das Sammeln von Kielfedern prüft Disziplin und ehrt gewitzte Beute, während es das Gleichgewicht des Stammes wahrt.",al={"ist sturzfliegerjagd überjagung","sturzflieger gleichgewicht mulgore"}}},fx={["0d785fcd"]={q="Warum schickt Harken Windtotem einen Außenstehenden, anstatt selbst Swoops zu jagen?",a="Harken Windtotem schickt Euch nicht, weil er nicht jagen kann, sondern um Euren Wert zu testen. Für Tauren erfordert das Verfolgen der listigen Swoops über die Ebenen scharfe Augen, Geduld und schnelle Hufe. Indem er Euch die Aufgabe überträgt, ihre Federn zurückzubringen, gibt Harken Euch die Gelegenheit, Euer Können und Eure Entschlossenheit im Dorf der Bluthufe unter Beweis zu stellen und zu zeigen, dass Ihr ein Jäger von echtem Wert seid.",al={"warum schickt man mich swoop jagen","warum braucht harken mich","warum kann harken keine swoops jagen"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem erkennt Euer Talent für unauffälliges Vorgehen und bittet Euch, die Mine der Venture Company zu betreten. Er möchte, dass Ihr Seaforium Mining Charges aus den Vorratskarren der Mine holt.",h="Boarton Shadetotem erkennt Euer Talent für unauffälliges Vorgehen und bittet Euch, die Mine der Venture...",kw={"sprengmaterial","boarton shadetotem","maske","mine","seaforium mining charges","unauffälliges vorgehen","donnerfels","venture company"},ang={["class:Rogue"]="Boarton glaubt, dass Ihr als Schurke ein Talent für unauffälliges Vorgehen habt, und bittet Euch, die Mine der Venture Company zu betreten."},sec={{t="Ein unauffälliges Vorgehen",b="Boarton Shadetotem in Donnerfels glaubt, dass Ihr unauffällig vorgehen könnt. Er gibt Euch eine Maske und bittet Euch, die nahe gelegene Mine der Venture Company zu betreten. Dort sollt Ihr Seaforium Mining Charges aus Karren mit Sprengmaterial nehmen und sie ihm bringen."}},faq={{q="Wer bittet mich, die Mine zu betreten?",a="Boarton Shadetotem in Donnerfels bittet Euch, die Mine der Venture Company zu betreten.",al={"wer ist boarton","boarton shadetotem","wer hat das gegeben"}},{q="Wonach suche ich in der Mine?",a="Ihr sollt Seaforium Mining Charges aus Karren mit Sprengmaterial nehmen.",al={"was stehlen","minenvorräte","seaforium charges"}},{q="Warum gibt Boarton mir eine Maske?",a="Boarton gibt Euch eine Maske, damit Ihr die nahe gelegene Mine der Venture Company betreten könnt.",al={"maske verkleidung","warum die maske","mine infiltrieren"}},{q="Wo ist die Mine der Venture Company?",a="Die Mine liegt südöstlich von Donnerfels.",al={"standort der mine","wo ist die mine","mine der venture company"}},{q="Wem werden die Vorräte weggenommen?",a="Die Vorräte befinden sich in der Mine der Venture Company.",al={"wem gehören die vorräte","vorräte der venture company","mine der gesellschaft"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem bittet Euch, aus Windfury Cones nördlich von Donnerfels eine Salbe herzustellen. Er hofft, dass sie die Wunden einer Klinge mit bitterer Kraft brennen lässt.",h="Boarton Shadetotem bittet Euch, aus Windfury Cones nördlich von Donnerfels eine Salbe herzustellen.",kw={"boarton shadetotem","harpyien","mörser und stößel","salbe","stalk with the earthmother","donnerfels","windfury cones"},sec={{t="Eine bittere Salbe",b="Boarton Shadetotem in Donnerfels möchte eine giftige Salbe aus Zapfen, die nahe den Harpyiennestern im Norden gesammelt werden. Ihr sollt die Windfury Cones mit Mörser und Stößel zerstoßen und ihm dann das Ergebnis bringen. Er warnt, dass die fertige Salbe selbst auf der Haut schmerzen könnte."}},faq={{q="Wer bittet um die Salbe?",a="Boarton Shadetotem in Donnerfels bittet Euch, eine Salbe aus Windfury Cones zuzubereiten.",al={"wer will die salbe","boarton shadetotems bitte"}},{q="Wo wachsen die Windfury Cones?",a="Die Harpyien nördlich von Donnerfels nisten in einem Baum, der das giftige Harz erzeugt. Herabgefallene Zapfen liegen um ihre Nester herum.",al={"wo zapfen finden","windfury cone fundort"}},{q="Was soll die Salbe bewirken?",a="Auf eine Klinge aufgetragen, soll die Salbe die Wunden eines Gegners brennen lassen und sein Blut in Salz verwandeln.",al={"was bewirkt die salbe","giftige klingensalbe"}},{q="Warum warnt Boarton davor, sie zu berühren?",a="Boarton sagt, dass selbst Hautkontakt mit der fertigen Salbe schmerzhaft sein könnte.",al={"salbe hautkontakt warnung","ist die salbe gefährlich"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="Ein Botschafter des Bösen",s="Im Ödland schickt Euch Historiker Karnik los, um Botschafter Infernus zu töten. Ihr sollt Berater Belgrum in Eisenschmiede einen Beweis für die Tötung überbringen.",h="Im Ödland schickt Euch Historiker Karnik los, um Botschafter Infernus zu töten.",kw={"berater belgrum","botschafter infernus","festung angor","ödland","historiker karnik","eisenschmiede","ragnaros","shadowforge","uldaman"},sec={{t="Der Botschafter in der Festung Angor",b="Ragnaros entsandte Botschafter Infernus zur Festung Angor, um die Suche der Shadowforge nach verlorenen Artefakten in Uldaman zu beaufsichtigen. Die Suche hat bereits viele Zwergenleben gekostet, und weitere Zwerge sterben. Karnik fürchtet, die Shadowforge könnten die Artefakte gegen Eisenschmiede einsetzen. Deshalb schickt er Euch zurück ins Ödland, um Infernus zu vernichten und Belgrum einen Beweis Eures Sieges zu überbringen. Die Zeit drängt. Ragnaros wird nicht warten, bis die Shadowforge bereit sind."},{t="Belgrums Dank",b="Berater Belgrum lobt Eure Hingabe an Eisenschmiede und seine Bewohner. Er wird Karnik von Eurem Erfolg berichten, und Hilfe wird ins Ödland geschickt, um die Ausgrabungsstätte zurückzuerobern. Im Namen von König Bronzebeard hat Belgrum noch eine weitere Bitte an Euch."}},faq={{q="Wer ist Botschafter Infernus?",a="Ragnaros entsandte Infernus zur Festung Angor, um die Suche der Shadowforge nach verlorenen Artefakten in Uldaman zu beaufsichtigen.",al={"wer ist infernus","infernus geschichte","botschafter infernus hintergrund"}},{q="Wo ist Botschafter Infernus?",a="Botschafter Infernus befindet sich in der Festung Angor im Ödland.",al={"wo botschafter infernus finden","botschafter infernus aufenthaltsort","wo ist infernus"}},{q="Warum will Karnik Botschafter Infernus vernichten lassen?",a="Die Suche der Shadowforge in Uldaman hat bereits viele Zwergenleben gekostet. Karnik fürchtet, dass die gefundenen Artefakte gegen Eisenschmiede eingesetzt werden könnten.",al={"warum botschafter infernus töten","was macht infernus in uldaman","eisenschmiede bedrohung ödland"}},{q="Bei wem beginnt und endet diese Quest?",a="Historiker Karnik in Eisenschmiede schickt Euch los, um Infernus zu töten. Ihr überbringt Berater Belgrum in Eisenschmiede einen Beweis Eures Sieges.",al={"wer startet ein botschafter des bösen","bei wem ein botschafter des bösen abgeben","ein botschafter des bösen questgeber"}},{q="Welcher Beweis wird verlangt?",a="Berater Belgrum verlangt Botschafter Infernus' Armschienen als Beweis Eures Sieges.",al={"was wird von infernus benötigt","botschafter infernus beweis","infernus armschienen"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem bittet Euch, in Donnerfels einen Raw Brilliant Smallfish zu filetieren. Er hofft, dass die Übung eine Begabung für subtile Künste offenbart.",h="Boarton Shadetotem bittet Euch, in Donnerfels einen Raw Brilliant Smallfish zu filetieren.",kw={"boarton shadetotem","knife set","raw brilliant smallfish","stalk with the earthmother","subtile künste","donnerfels"},sec={{t="Eine letzte Prüfung",b="Boarton Shadetotem in Donnerfels bittet Euch, mit seinem Knife Set zu zeigen, was Euch von Natur aus liegt. Bringt ihm einen Raw Brilliant Smallfish und filetiert ihn vor seinen Augen. Er hofft, dass diese weniger direkte Prüfung eine verborgene Begabung aufdeckt."},{t="Worte zum Abschied",b="Boarton Shadetotem erkennt, dass Euch die gesuchte schurkenhafte Präzision fehlt. Er überreicht Euch ein Abschiedsgeschenk und schickt Euch auf die Reise, wobei er der Horde Helden wie Euch wünscht."}},faq={{q="Wer bittet mich, einen Fisch zu filetieren?",a="Boarton Shadetotem in Donnerfels bittet Euch, mit seinem Knife Set einen Raw Brilliant Smallfish zu filetieren.",al={"wer ist boarton","boarton shadetotem","fisch messer quest"}},{q="Warum möchte Boarton, dass ich einen Fisch filetiere?",a="Boarton hofft, dass die Übung eine verborgene Begabung für subtile Künste zum Vorschein bringt.",al={"warum fisch filetieren","was prüft boarton","kleinfisch prüfung"}},{q="Welchen Fisch verlangt Boarton?",a="Boarton verlangt einen Raw Brilliant Smallfish.",al={"welcher fisch","roher kleinfisch","glänzender fisch"}},{q="Wo filetiere ich den Fisch?",a="Filetiert den Raw Brilliant Smallfish vor Boarton Shadetotem in Donnerfels.",al={"wo fischaufgabe","donnerfels fisch","wo knife set benutzen"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="Riten der Erdenmutter",s="In Camp Narache schickt Euch Häuptling Falkenwind über die Hochwolkenebene hinaus, um die Riten der Erdenmutter fortzusetzen. Nach den ersten Prüfungen tragt Ihr ein geschnitztes Totem nach Norden ins Dorf der Bluthufe zu Baine Bluthuf.",h="In Camp Narache schickt Euch Häuptling Falkenwind über die Hochwolkenebene hinaus, um die Riten der...",kw={"baine bluthuf","dorf der bluthufe","cairne bluthuf","camp narache","häuptling falkenwind","mulgore","riten der erdenmutter","falkenwinds totem"},ang={["faction:Horde"]="Als Mitglied der Horde nehmt Ihr an Traditionen teil, die den Zusammenhalt der Stämme in ganz Mulgore stärken und neue Verteidiger mit Kampfgeschick und geistigem Halt vorbereiten.",["race:Tauren"]="Als junger Taure beschreitet Ihr den Pfad der Erdenmutter, um den Ältesten Euren Wert zu beweisen und Euren Platz unter den vereinten Stämmen zu finden."},sec={{t="Abschied von der Hochebene",b="Seit Generationen erproben junge Tauren ihre Stärke in Camp Narache auf der Hochwolkenebene. Die ersten Prüfungen lehren Disziplin und Entschlossenheit. Doch die heiligen Riten der Erdenmutter verlangen mehr, als inmitten der Tierwelt der Hochebene zu überleben. Häuptling Falkenwind erkennt, wann ein Initiand bereit ist, die geschützten Jagdgründe zu verlassen und sich der größeren Gemeinschaft anzuschließen."},{t="Ein Zeichen für Baine",b="Häuptling Falkenwind gibt Euch ein handgeschnitztes Totem, das Euch auf dem Weg von Narache zu den zentralen Siedlungen als Empfehlung dient. Tragt es den gewundenen Pfad hinab ins Dorf der Bluthufe und stellt Euch Baine Bluthuf vor, dem jungen Häuptling und Sohn des Obersten Häuptlings Cairne Bluthuf. Das Totem ist Euer Beglaubigungsschreiben und Zeichen der Anerkennung. Es bezeugt Eure Bereitschaft für die bevorstehenden Riten des Geistes und der Weisheit."}},faq={{q="Welchen Zweck hat diese Quest?",a="Die Riten führen Euch von Camp Narache in die größere Gemeinschaft der Tauren im Dorf der Bluthufe, wo die nächsten Prüfungen beginnen.",al={"warum die riten der erdenmutter durchlaufen","was bewirkt diese quest","zweck der quest"}},{q="Wer ist Baine Bluthuf?",a="Baine Bluthuf ist der Sohn des Obersten Häuptlings Cairne Bluthuf und der junge Häuptling des Dorfes der Bluthufe. Er beaufsichtigt die geistigen und kämpferischen Prüfungen junger Tauren.",al={"wer ist baine","baines geschichte","sohn von cairne"}},{q="Was ist Falkenwinds Totem?",a="Falkenwinds Totem ist ein hölzernes Zeichen, das Häuptling Falkenwind aus Camp Narache von Hand geschnitzt hat. Es dient als offizielles Beglaubigungsschreiben und Zeichen der Anerkennung und zeigt Baine Bluthuf, dass Ihr Falkenwinds Segen habt, weitere Riten zu durchlaufen.",al={"falkenwinds totem","geschnitztes totem"}},{q="Welche Riten folgen danach?",a="Im Dorf der Bluthufe betraut Euch Baine mit Rite of Vision. Dabei wird Eure geistige Verbundenheit durch heilige Visionen der Ahnen geprüft.",al={"nächste riten","was kommt danach","nächste quest"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt nördlich von Camp Narache am Ufer des Stonebullsees im Herzen von Mulgore. Folgt der Hauptstraße von der Hochebene hinab und geht nach Norden.",al={"wo liegt das dorf der bluthufe","wie das dorf der bluthufe finden","weg zum dorf der bluthufe"}},{q="Warum müssen die Riten der Erdenmutter vollendet werden?",a="Die Riten der Erdenmutter sind heilige Traditionen der Tauren. Wer ihre Stufen besteht, beweist körperliche Ausdauer, geistige Verbundenheit und Weisheit und erlangt die Anerkennung der Ältesten von Donnerfels.",al={"warum riten der erdenmutter","zweck der taurenprüfungen","geschichte der riten der erdenmutter"}}},fx={["4a33bb81"]={q="Warum schickt Euch Häuptling Falkenwind ins Dorf der Bluthufe?",a="Häuptling Falkenwind hat Euch durch die Einführungsprüfungen der Hochwolkenebene geführt, doch Camp Narache kann Euch nichts mehr lehren. Um die heiligen Rites of the Earthmother abzuschließen und die Anerkennung der Ältesten von Donnerfels zu gewinnen, müsst Ihr Eure Erfahrungen in den weiteren Ebenen von Mulgore erweitern. Indem er Euch mit seinem geschnitzten Totem zu Baine Bluthuf schickt, überträgt Falkenwind die Verantwortung für Euer spirituelles und körperliches Wachstum an einen Anführer, der Eure Bereitschaft für das wahre Erwachsenenalter testen kann.",al={"warum nach bloodhoof schicken","häuptling falkenwinds motiv","warum rites of the earthmother"}},["9c980781"]={q="Warum müsst Ihr das Totem selbst überbringen?",a="Die Reise ist kein Botengang, sondern ein wesentlicher Bestandteil Eures Initiationsritus. Die geschützten Grenzen der Hochwolkenebene zu verlassen und der offenen Straße nach Mulgore zu folgen, beweist Eure Unabhängigkeit und Ausdauer. Indem Ihr das Falkenwinds Totem mit Euren eigenen Händen überreicht, ermöglicht Ihr es Baine Bluthuf, Euch anzusehen, Falkenwinds persönliche Empfehlung, die in das Holz geschnitzt ist, zu erkennen und Euren Charakter aus erster Hand zu beurteilen.",al={"warum nehme ich das totem","warum kann falkenwind keinen boten schicken","warum ich für rites of the earthmother"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="Die Venture Company",s="In Mulgores östlichen Hügeln graben Goblins trotz der Weigerung der Tauren. Die Venture Company lässt sie in großer Zahl anrücken, um den Boden der Erdenmutter abzutragen, und Morin Wolkenpirscher fordert eine tödliche Antwort.",h="In Mulgores östlichen Hügeln graben Goblins trotz der Weigerung der Tauren.",kw={"goblin","schürfrechte","morin wolkenpirscher","mulgore","überfallene karawane","venture co.","mine von venture co.","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, Mulgore gegen kommerzielle Ausbeutung zu verteidigen und Cairne Bluthufs Volk zu schützen, während es seine neue Heimat sichert.",["profession:Mining"]="Die Venture Company betreibt Bergbau mit roher Gewalt, spart an allen Ecken und untergräbt die Stabilität des Landes, ohne Rücksicht auf sein natürliches Gleichgewicht oder sichere Abbauverfahren.",["race:Tauren"]="Für die Tauren ist die Erdenmutter heilig. Der Bergbau der Venture Company entweiht ihre angestammte Heimat, und sie wollen die Goblins mit Gewalt vertreiben."},sec={{t="Industrielles Vordringen",b="Die Tauren ehren Mulgore als Teil der Erdenmutter. Sie schätzen seine weiten Ebenen und das Gleichgewicht seiner Tierwelt. Als die Venture Company darum bittet, in den Hügeln nach Erz zu graben und zu sprengen, lehnen die Stämme ab. Die Gesellschaft ignoriert sie und bringt Maschinen, Arbeiter und Aufseher in die östlichen Bergkämme, um dort ohne Erlaubnis Bergbau zu betreiben."},{t="Eine unmissverständliche Botschaft",b="Morin Wolkenpirscher und die anderen Taurenkundschafter sehen keinen Sinn in weiteren Appellen, sobald der Bergbau beginnt. Dokumente aus einer überfallenen Karawane der Venture Company bestätigen den Bergbaubetrieb. Morin schickt Euch gegen die Aufseher, die ihre Peitschen knallen lassen, und die Arbeiter, die die Bohrer bedienen. Die Gesellschaft soll für ihr unbefugtes Eindringen teuer bezahlen."}},faq={{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company gräbt in Mulgores östlichen Hügeln nach Erz und anderen Rohstoffen. Die Tauren lehnten ihren Antrag auf Schürfrechte ab, doch die Gesellschaft nahm den Betrieb trotzdem auf.",al={"warum sind goblins in mulgore","venture co. mulgore beweggrund","was will venture co."}},{q="Wer gab den Befehl zum Angriff auf die Bergarbeiter?",a="Morin Wolkenpirscher gibt den Befehl. Er hält nahe dem Dorf der Bluthufe Wache und sieht die Missachtung der Entscheidung der Tauren als einen Verstoß, der Gewalt erfordert.",al={"wer vergibt diese quest","morin wolkenpirschers rolle","questgeber"}},{q="Wo liegt die Mine der Venture Company?",a="Die zentrale Venture Company Mine liegt in den Ausläufern der Berge östlich der Überfallenen Karawane und des Dorfs der Bluthufe. Angehörige der Gesellschaft sammeln sich auch an einem kleineren Außenposten auf den Anhöhen nordöstlich der nördlichen Aufzüge von Donnerfels.",al={"standort der mine von venture co.","wo sind die aufseher","wo ist venture co. zu finden"}},{q="Haben die Tauren je versucht, mit den Goblins zu verhandeln?",a="Ja. Die Venture Company bat die Tauren um Schürfrechte in Mulgore, und die Stammesführer verweigerten die Erlaubnis, ihr angestammtes Land im Tagebau abzutragen. Die Goblins gruben trotzdem ohne Erlaubnis.",al={"haben tauren den bergbau erlaubt","schürfrechte mulgore","haben goblins um erlaubnis gebeten"}},{q="Gehören diese Goblins zum Steamwheedle Cartel?",a="Nein. Die Venture Company ist ein unabhängiges, ausbeuterisches Industriekartell und gehört keiner neutralen Handelsgruppe wie dem Steamwheedle Cartel an. Überall, wo sie Rohstoffe ausbeutet, steht sie der örtlichen Bevölkerung feindlich gegenüber.",al={"sind das goblins aus ratschet","ist venture co. freundlich","venture company fraktion"}},{q="Wie hängt das mit den überfallenen Karawanen zusammen?",a="Die überfallene Karawane war ein Konvoi der Venture Company, den die Tauren zerstörten. Kisten und Dokumente ihrer Bergbauabteilung enthüllten den Betrieb der Gesellschaft in Mulgore und gaben den Anstoß zum Angriff auf ihre Mine.",al={"verbindung zur karawane","hat venture co. karawanen angegriffen","verbindung zur überfallenen karawane"}}},fx={f6df914e={q="Warum möchte Morin Wolkenpirscher, dass die Venture Company angegriffen wird?",a="Der Venture Company wurden offiziell die Bergbaurechte in Mulgore verweigert, doch sie ignorierten die Ablehnung und begannen ungeachtet dessen, Ausrüstung aufzubauen und Arbeiter einzusetzen. Morin Wolkenpirscher kann es nicht zulassen, dass sie das Land verwüsten und seine natürlichen Ressourcen ungehindert plündern. Da Diplomatie und direkte Ablehnungen ihre Gier nicht beeinflussen konnten, glaubt er, dass die Tauren eine unmissverständliche, nachdrückliche Botschaft übermitteln müssen, dass Hausfriedensbruch und Diebstahl nicht toleriert werden.",al={"morin wolkenpirschers motiv","warum venture company angreifen","warum will morin, dass venture company getötet wird"}},eda5096c={q="Gegen wen werdet Ihr ausgesandt, um in der Mine zu kämpfen?",a="Ihr werdet gegen die Aufseher und Arbeiter der Venture Company ausgesandt, die bei ihrer Bergbauoperation im östlichen Mulgore stationiert sind. Diese Goblins und angeheuerten Arbeiter graben tief in die heiligen Hügel, um die Erde ohne Erlaubnis des Stammes von Mineralien zu befreien, angeführt von profitorientierten Vorarbeitern, die die aggressive, illegale Expansion des Unternehmens durchsetzen.",al={"ziele der venture company quest","wer sind die arbeiter der venture company","gegen wen kämpfe ich in der mine"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="Vorsteher Zischelspross",s="In Mulgore bittet Morin Wolkenpirscher um Hilfe gegen die Mine der Venture Company. Dokumente aus einer zerstörten Karawane offenbaren einen Plan, die Tauren aus ihrer Heimat zu vertreiben, und Morin braucht das Klemmbrett von Vorsteher Zischelspross.",h="In Mulgore bittet Morin Wolkenpirscher um Hilfe gegen die Mine der Venture Company.",kw={"klemmbrett","zischelspross","mine","morin wolkenpirscher","mulgore","vorsteher","venture company"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr den Tauren, sich dem Vormarsch der Venture Company zu widersetzen. Ihr verteidigt die Kernlande der Horde in Kalimdor.",["race:Tauren"]="Als Tauren verteidigt Ihr Euer Volk und Euer Land, wenn Ihr gegen Zischelspross vorgeht. Sein Unternehmen plant, Euren Stamm aus Mulgore zu vertreiben und dessen Erde auszuplündern."},sec={{t="Ein Komplott gegen die Ebenen",b="Eine Karawane der Venture Company liegt zerstört da, und ihre Dokumente enthüllen einen Plan, die Tauren aus Mulgore zu vertreiben. Das Unternehmen will die Ebenen und die Erzadern darunter für sich allein. Es will ihre Ressourcen ausbeuten, ohne dass die Tauren ihm im Weg stehen."},{t="Schlag gegen den Vorsteher",b="Morin Wolkenpirscher schickt Recken zur Mine der Venture Company östlich der Überfallenen Karawane. Vorsteher Zischelspross leitet die Mine tief in ihren rechten Stollen, umgeben von Arbeitern und Unterbossen. Morin will Zischelspross' Klemmbrett haben, weil es die nächsten Pläne des Unternehmens enthüllen könnte."}},faq={{q="Wer ist Vorsteher Zischelspross?",a="Vorsteher Zischelspross leitet die Unternehmungen der Venture Company in der Mine im Osten von Mulgore. Er beaufsichtigt die Arbeiter, die sich in die Erde graben, und setzt die Pläne des Unternehmens in der Region um.",al={"zischelspross","wer ist zischelspross","zischelspross geschichte"}},{q="Warum will Morin Wolkenpirscher Zischelspross tot sehen?",a="Dokumente aus einer überfallenen Karawane zeigen, dass die Venture Company plant, die Tauren aus Profitgier aus Mulgore zu vertreiben. Morin Wolkenpirscher will Zischelspross tot sehen, weil er diese Machenschaften leitet.",al={"warum zischelspross töten","morin wolkenpirscher beweggründe"}},{q="Wo befindet sich Vorsteher Zischelspross?",a="Zischelspross befindet sich in der Mine der Venture Company östlich der Überfallenen Karawane in Mulgore. Folgt dem rechten Stollen bis zu einer Kammer mit Arbeitern und Aufsehern.",al={"wo ist zischelspross","zischelspross mine standort","zischelspross karte"}},{q="Welchen Beweis verlangt Morin für Zischelspross' Niederlage?",a="Morin Wolkenpirscher will Zischelspross' persönliches Klemmbrett haben. Seine Aufzeichnungen könnten die weiteren Pläne der Venture Company in Mulgore enthüllen.",al={"todesnachweis","zischelspross klemmbrett"}},{q="Warum ist die Venture Company in Mulgore?",a="Die Venture Company ist in Mulgore, um dessen Holz, Mineralien und unterirdische Reichtümer auszubeuten. Sie nimmt weder Rücksicht auf die Menschen, die dort leben, noch auf das Land, das sie ausplündert.",al={"venture company mulgore","warum sind goblins in mulgore"}},{q="Vertreibt Zischelspross' Tod die Venture Company vollständig?",a="Nein. Zischelspross' Tod stört die örtliche Führung und verschafft Morin Wolkenpirscher Aufzeichnungen über die Pläne des Unternehmens. Die Venture Company bleibt eine Bedrohung in den Hügeln von Mulgore.",al={"ist die venture company fort","nach zischelspross' tod"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="Mazzranach",s="Im Dorf der Bluthufe liegt Maur Regenrufer nach Mazzranaches Biss fiebernd dem Tode nahe. Schon vor einer Generation geisterte der Ebenenschreiter durch die Erzählungen seines Großvaters. Nun leidet Maur unter fiebrigen Albträumen, während das Gift sein Leben bedroht.",h="Im Dorf der Bluthufe liegt Maur Regenrufer nach Mazzranaches Biss fiebernd dem Tode nahe.",kw={"dorf der bluthufe","flachlandpuma","maur regenrufer","mazzranache","mulgore","ebenenschreiter","präriewolf","sturzflieger"},ang={["class:Hunter"]="Als Jäger könnt Ihr die Ebenen lesen, indem Ihr Präriewölfe, Pumas, Ebenenschreiter und Sturzflieger in ganz Mulgore aufspürt.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, das Dorf der Bluthufe gegen Mulgores Gefahren zu sichern und Frieden und Stabilität in der Heimat der Tauren zu bewahren.",["race:Tauren"]="Als Taure erkennt Ihr, dass Maurs Heilmittel einer alten Tradition folgt: Heilung aus der Pflanzen- und Tierwelt der Earth Mother zu schöpfen."},sec={{t="Ein Vermächtnis der Ebenen",b="Maur Regenrufer kannte Mazzranache nur aus den Erzählungen seines Großvaters. Der alte Taure sprach von einem wilden Ebenenschreiter mit glühend roten Augen, rasiermesserscharfen Krallen und einem giftigen Biss, wie ihn die meisten Wildtiere Mulgores nicht haben. Dann begegnete Maur dem Untier auf dem offenen Grasland. Die Warnung seines Großvaters bewahrheitete sich, und der Biss verwundete ihn schwer, während er versuchte, sich in Sicherheit zu bringen."},{t="Wettlauf gegen die Infektion",b="Mazzranaches Gift verursacht bei Maur hohes Fieber und albtraumhafte Wahnvorstellungen. Er braucht ein Heilmittel, bevor die Infektion tödlich endet. Die traditionelle Medizin der Tauren schöpft aus der Lebenskraft einheimischer Tiere, daher braucht Maur ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers. Zusammen lassen sich diese Teile zu einem Gebräu verarbeiten, das die Ausbreitung der Nekrose aufhält und ihn wieder gesund pflegt."}},faq={{q="Was ist Mazzranache?",a="Mazzranache ist ein wilder Ebenenschreiter, der durch Mulgores Grasland streift. Sein leuchtendes Gefieder, seine dämonischen roten Augen, seine gefährlichen Krallen und sein giftiger Biss versetzen Reisende seit Generationen in Angst und Schrecken.",al={"wer ist mazzranache","was für ein tier ist mazzranache","mazzranache hintergrundgeschichte"}},{q="Wer ist Maur Regenrufer?",a="Maur Regenrufer lebt im Dorf der Bluthufe. Mazzranache überfiel ihn und biss ihm in die Schulter, als er Mulgore durchquerte, sodass ihn eine lebensbedrohliche Infektion ans Bett fesselte.",al={"maur regenrufer","wer hat mir diese quest gegeben","wer ist der kranke taure"}},{q="Warum braucht Maur Teile von vier verschiedenen Tieren?",a="Heilmittel der Tauren nutzen die Stärken und geistigen Essenzen der Tiere der Ebenen, um starke Gifte zu bekämpfen. Ein Wolfsherz, das Mark eines Pumaoberschenkelknochens, eine Ebenenschreiterschuppe und ein Sturzfliegermuskelmagen ergeben zusammen ein Gegengift, das stark genug ist, Mazzranaches Gift zu bekämpfen.",al={"warum wolfsherz und pumaknochen","warum tierische zutaten","mazzranache heilmittel zutaten"}},{q="Hat Maurs Großvater Mazzranache getötet?",a="Nein. Maurs Großvater kämpfte vor Jahren gegen Mazzranache, konnte den wilden Ebenenschreiter aber nicht besiegen. Er überlebte und warnte seine Nachkommen vor dessen leuchtenden Farben und grausamen Angriffen.",al={"hat großvater mazzranache besiegt","maur großvater mazzranache","wer hat früher gegen mazzranache gekämpft"}},{q="Soll ich bei dieser Quest Mazzranache selbst jagen?",a="Nein. Maur muss das Fieber überleben, daher gilt es zunächst, die Teile für sein Heilmittel zu sammeln.",al={"soll ich mazzranache töten","wo ist mazzranache","mazzranache jagen"}},{q="Wo liegt das Dorf der Bluthufe?",a="Das Dorf der Bluthufe liegt im Herzen Mulgores, südlich von Donnerfels und östlich des Stonebullsees. Von dieser Siedlung aus beginnen junge tapfere Tauren ihre Reisen durch die Ebenen.",al={"wo liegt das dorf der bluthufe","dorf der bluthufe lage"}}},fx={["3b88d77e"]={q="Warum möchte Maur Regenrufer, dass dies getan wird?",a="Maurs Leben steht unmittelbar auf dem Spiel. Während er die Ebenen von Mulgore bereiste, kreuzte er den Weg von Mazzranache, einem legendären Prärieläufer, der bekanntermaßen seinen Großvater terrorisierte. Die Kreatur fügte Maur einen wilden, giftigen Biss in die Schulter zu. Ein schwächendes Fieber hat eingesetzt, das wahnsinnige Albträume verursacht und sich stetig in seinem Körper ausbreitet. Ohne die tierischen Zutaten, die für die Herstellung eines medizinischen Heilmittels benötigt werden, wird ihn die wütende Infektion bald töten.",al={"maur regenrufers motiv","warum maur regenrufer helfen","was ist mit maur passiert"}},ce37bf7e={q="Warum braucht Maur einen Außenstehenden, anstatt sich selbst zu heilen?",a="Maur ist zu schwer verletzt und fiebrig, um selbst die Bestien von Mulgore zu jagen. Mazzranaches giftiger Biss hat ihn mit Delirium und Erschöpfung außer Gefecht gesetzt und ihn an das Dorf der Bluthufe gefesselt. Da die Zeit knapp wird, bevor die Infektion tödlich endet, muss er sich auf vorbeiziehende Reisende verlassen, um die schnellen Pumas, Swoops, Wölfe und Prärieläufer aufzuspüren, die für sein Heilmittel benötigt werden.",al={"warum kann maur die teile nicht holen","warum braucht maur euch","warum ich für mazzranache"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="Ritus der Vision",s="Baine Bluthuf schickt Reisende vor dem Ritus der Vision durch Mulgore, um Zarlman Zwillingsmond aufzusuchen. Die Prüfung gehört zu den Rites of the Earthmother, und die Ältesten auf den Anhöhen von Donnerfels betrachten sie als Zeichen spiritueller Reife.",h="Baine Bluthuf schickt Reisende vor dem Ritus der Vision durch Mulgore, um Zarlman Zwillingsmond aufzusuchen.",kw={"baine bluthuf","dorf der bluthufe","mulgore","ritus der vision","rites of the earthmother","taurenprüfung","donnerfels","zarlman zwillingsmond"},ang={["class:Druid"]="Als Druide vertieft die Zwiesprache mit den Visionen der Erdenmutter Eure Berufung, die Weisheit und das Flüstern der lebendigen Welt zu vernehmen.",["class:Shaman"]="Als Schamane entspricht es Eurer Pflicht, weltliche Belange mit dem Willen der Ahnen in Einklang zu bringen, Zarlman Zwillingsmond aufzusuchen und den Pfad der Visionen zu beschreiten.",["faction:Horde"]="Als Mitglied der Horde zeigt Ihr durch das Befolgen dieser heiligen Traditionen Eure Treue und Euren Respekt gegenüber den Taurenältesten, die die Horde mitführen.",["race:Tauren"]="Als Tauren erreicht Ihr mit dem Ritus der Vision einen wesentlichen Meilenstein Eurer Kultur. Er markiert Euren Weg zu einem vertrauenswürdigen Verteidiger und Geisterwandler der Stämme."},sec={{t="Ein heiliger Schritt",b="Seit Generationen folgen die nomadischen Tauren der Führung der Erdenmutter über die Ebenen Kalimdors. Nun haben sie sich innerhalb der sicheren Grenzen Mulg ores versammelt, wo spirituelle Traditionen weiterhin das Herz ihrer Gesellschaft bilden. Frühere Prüfungen erproben die Stärke eines Initianten und seine Verbindung zur Jagd. Der Ritus der Vision richtet den Blick nach innen und ruft junge Tauren und geehrte Verbündete dazu auf, mit den Geistern Zwiesprache zu halten."},{t="Der Rat des Sehers",b="Bevor ein Initiant eine Vision sucht, braucht er Unterweisung in den alten Wegen. Im Dorf der Bluthufe bietet der verehrte Schamane Zarlman Zwillingsmond diesen Rat. Baine Bluthuf vertraut ihm Reisende an. Zarlman erkennt jene, die auf dem Pfad der Ahnen wandeln, und vermittelt ihnen die ersten Riten und heiligen Vorbereitungen, um über die physische Welt hinauszublicken."}},faq={{q="Was ist der Ritus der Vision?",a="Der Ritus der Vision ist ein heiliger Ritus der Erdenmutter. Er öffnet den spirituellen Blick eines Abenteurers, damit dieser mit den Ahnengeistern Zwiesprache halten und den Ältesten von Donnerfels seine spirituelle Reife zeigen kann.",al={"ritus der vision quest","was ist der ritus der vision","ritus der vision hintergrund"}},{q="Wer beginnt diese Quest?",a="Baine Bluthuf schickt Reisende aus, um den Ritus der Vision zu vollziehen. Der Sohn von Oberhäuptling Cairne Bluthuf wacht über das Dorf der Bluthufe und verweist würdige Reisende an dessen spirituelle Älteste.",al={"wer vergibt ritus der vision","ritus der vision questgeber"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein erfahrener Taurenschamane und der spirituelle Anführer des Dorfes der Bluthufe. Er bereitet Reisende und Initianten auf heilige Prüfungen wie den Ritus der Vision vor.",al={"wer ist zarlman","zarlman zwillingsmond hintergrund"}},{q="Warum sind die Rites of the Earthmother für die Tauren wichtig?",a="Die Rites of the Earthmother markieren für Tauren den traditionellen Übergang ins Erwachsenenalter. Wer sie vollendet, beweist körperliches Können, spirituellen Einklang und beständigen Respekt vor dem Land und erlangt damit die Anerkennung der hohen Ältesten.",al={"riten der erdenmutter bedeutung","warum rites of the earthmother vollziehen"}},{q="Können Nichttauren den Ritus der Vision vollziehen?",a="Ja. Verbündete der Horde, die durch Mulgore reisen, dürfen dem Pfad der Erdenmutter folgen, wenn sie das Vertrauen des Stammes Bloodhoof gewinnen. Sie ehren die Tradition der Tauren und hoffen, die Gunst der Ältesten zu erlangen.",al={"können orcs den ritus der vision vollziehen","nichttauren erdenmutter"}},{q="Wo findet diese Prüfung statt?",a="Die Prüfung beginnt im Dorf der Bluthufe, nahe dem Ufer des Stonebullsees im Herzen Mulg ores. Das Dorf liegt südlich von Donnerfels.",al={"wo ist der ritus der vision","ritus der vision ort"}}},fx={["1fa313da"]={q="Warum möchte Baine Bluthuf, dass Ihr die Rite of Vision unternehmt?",a="Baine Bluthuf bereitet Euch darauf vor, den Pfad Eurer Vorfahren zu beschreiten und Euren Wert für das Volk der Tauren zu beweisen. Wenn Ihr in Mulgore erwachsen werdet, müsst Ihr die heiligen Rites of the Earthmother unternehmen, um mit den Geistern zu kommunizieren, Ehrfurcht vor dem Land zu lernen und letztlich den Respekt der Ältesten in Donnerfels zu verdienen. Baine weist Euch an den Dorfmystiker Zarlman Zwillingsmond, damit Ihr die spirituelle Prüfung ordnungsgemäß beginnen könnt.",al={"warum schickt baine euch zur rite of vision","baine bluthufs motiv rite of vision","warum die rite of vision durchführen"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="Leder sammeln",s="In Donnerfels bittet Veren Tallstrider Jäger, Leichtes Leder für die Hauptstadt zu bringen. Er tauscht gefertigte Waren gegen die Häute und folgt damit dem Brauch der Tauren, aus der Jagdbeute der Ebenen Kleidung und Rüstung herzustellen.",h="In Donnerfels bittet Veren Tallstrider Jäger, Leichtes Leder für die Hauptstadt zu bringen.",kw={"leder sammeln","lederverarbeitung","leichtes leder","mulgore","tauren jagd","donnerfels","veren tallstrider"},ang={["class:Hunter"]="Als Jäger seid Ihr bestens geeignet, Beute durch die Ebenen von Mulgore zu verfolgen und die leichten Häute zu sammeln, die Veren braucht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Handwerker von Donnerfels zu versorgen, während die junge Hauptstadt ihre Verteidigung und ihre Handelsnetze stärkt.",["race:Tauren"]="Als Taurenjäger ehrt Ihr ein erlegtes Tier, indem Ihr seine Haut zu nützlichen Waren verarbeitet. Diese Fertigkeit wurde über Generationen weitergegeben."},sec={{t="Donnerfels versorgen",b="Donnerfels braucht geschickte Hände, die Kleidung und Rüstung für seine wachsende Bevölkerung herstellen. Veren Tallstrider verarbeitet Häute zu nützlichen Waren und bittet junge Jäger, die aus den Ebenen zurückkehren, ihm ihre Beute zu bringen. Ihre Jagd hilft, die Hauptstadt zu versorgen und den Stamm zu ernähren."},{t="Der Weg der Jagd",b="Tauren jagen in den Graslanden, um den Stamm zu ernähren, zu kleiden und ihm Schutz zu bieten. Veren Tallstrider bittet Jäger, die ihrem Clan Ehre erweisen wollen, um Leichtes Leder von heimischen Wildtieren. Dafür tauscht er gefertigte Waren gegen zwölf gut erhaltene Häute und erhält so die Bande, die die Gesellschaft der Tauren zusammenhalten."}},faq={{q="Wer ist Veren Tallstrider?",a="Veren Tallstrider ist ein Lederverarbeiter in Donnerfels. Er fertigt Kleidung und Rüstung für die Tauren und tauscht seine Arbeiten gegen Häute aus den Ebenen.",al={"veren tallstrider","wer vergibt leder sammeln","leder questgeber donnerfels"}},{q="Was braucht Veren Tallstrider?",a="Veren braucht zwölf Stücke Leichtes Leder von Wildtieren in Mulgore und den benachbarten Gebieten. Er verwendet die Häute, um Waren für Donnerfels herzustellen.",al={"leder sammeln voraussetzungen","was veren bringen","leder sammeln materialien"}},{q="Wo findet diese Quest statt?",a="Ihr trefft Veren Tallstrider oben auf Donnerfels. Um ihm zu bringen, was er braucht, jagt wilde Tiere in den Graslanden unterhalb der Stadt.",al={"wo ist veren tallstrider","leder sammeln ort"}},{q="Warum ist die Jagd auf Wildtiere für die Tauren so wichtig?",a="Die Jagd der Tauren ehrt das Gleichgewicht mit der Earth Mother. Der Stamm nutzt jeden Teil eines erlegten Tieres: sein Fleisch als Nahrung und seine Knochen und gegerbten Häute für Werkzeuge, Zelte und Rüstung.",al={"jagdkultur der tauren","warum für leder jagen","tauren leder hintergrund"}},{q="Kann jeder Abenteurer der Horde diese Aufgabe übernehmen?",a="Ja. Jeder Reisende, der der Horde treu ist, kann beim Ledersammeln helfen, wenn Veren glaubt, dass er sich in den Ebenen beweisen möchte.",al={"wer kann leder sammeln erledigen","leder sammeln nur für die horde"}},{q="Was geschieht, sobald das Leder abgeliefert ist?",a="Nachdem Ihr die Häute abgeliefert habt, prüft Veren ihre Qualität und lobt Eure Arbeit. Als fairen Gegenwert gibt er Euch ein gefertigtes Ausrüstungsteil.",al={"leder sammeln abgeben","veren tallstrider belohnung"}}},fx={cd30155e={q="Wofür wird Leichtes Leder verwendet?",a="Das Leder wird zu unverzichtbaren Kleidungsstücken, schützender Rüstung und nützlichen Waren für die Tauren verarbeitet, die hoch oben auf den Plateaus von Donnerfels leben, sowie zu Ausrüstung, die im Handel für reisende Jäger hergestellt wird.",al={"verwendung von leichtem leder","gebrauch von leichtem leder","wie nutzt veren leichtes leder"}},["1249c214"]={q="Warum möchte Veren Tallstrider Leichtes Leder?",a="Veren Tallstrider ist ein Lederer, der Kleidung und Rüstungen für die Bewohner von Donnerfels fertigt. Um die Stadt zu versorgen und sein Handwerk aufrechtzuerhalten, ist er darauf angewiesen, dass Jäger hochwertige Felle aus den Ebenen von Mulgore bringen.",al={"warum veren leder braucht","veren tallstriders motiv","warum leichtes leder für veren"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="Kodobalgtasche",s="Veren Tallstrider lehrt Donnerfels' Lederverarbeitungslehrlinge ein Handwerk aus den Ebenen. Er verlangt gegerbtes Leichtes Leder und robusten Faden.",h="Veren Tallstrider lehrt Donnerfels' Lederverarbeitungslehrlinge ein Handwerk aus den Ebenen.",kw={"grober faden","kodo","kodobalgtasche","lederverarbeitung","leichtes leder","mulgore","donnerfels","veren tallstrider"},ang={["faction:Horde"]="Als Mitglied der Horde verlasst Ihr Euch auf Donnerfels' Handwerker, deren Waren Jäger, Späher und Krieger im zentralen Kalimdor ausrüsten.",["race:Tauren"]="Als Shu'halo ehrt Ihr die Gaben der Earth Mother und bewahrt die Wege Eurer Ahnen, indem Ihr lernt, zuverlässige Ausrüstung aus dem mächtigen Kodo zu fertigen."},sec={{t="Eine Lektion auf der Mesa",b="Veren Tallstrider lehrt Lederverarbeitung auf den Handwerksebenen von Donnerfels. Er folgt der nomadischen Lebensweise, bei der nichts von der Jagd verschwendet wird. Bringt gegerbtes Leichtes Leder und robusten Faden, und er wird Euch unterweisen. Mit diesen grundlegenden Materialien zeigen Lehrlinge, dass sie Waren fertigen können, um Überlebensausrüstung durch Kalimdors raue Weiten zu tragen."},{t="Geist des Kodos",b="Für die Tauren ist der Kodo ein Sinnbild für Ausdauer, Stärke und unerschütterliche Entschlossenheit. Seine dicke Haut schützt vor Dornen, beißendem Wind und Tierkrallen. Taschen und Kleidungsstücke aus Kodohaut zu fertigen ist nützliche Arbeit und ehrt das Tier, das die Shu'halo seit Generationen durch Mulg ores Ebenen ernährt und getragen hat."}},faq={{q="Wer bietet die Quest „Kodobalgtasche“ an?",a="Veren Tallstrider, ein Lederverarbeitungslehrer und Händler der Tauren in Donnerfels, bietet die Unterweisung an.",al={"questgeber","wo gibt es die quest kodobalgtasche","veren tallstrider standort"}},{q="Wer kann diese Aufgabe übernehmen?",a="Lederverarbeiter mit einer Lehrlingsfertigkeit von mindestens zehn können diese Unterweisung von Veren Tallstrider erhalten.",al={"wer kann diese quest annehmen","questvoraussetzungen","berufsvoraussetzung"}},{q="Welche Materialien benötigt Veren Tallstrider?",a="Veren Tallstrider verlangt vier Stücke Leichtes Leder und vier Spulen Groben Faden, um seine Handwerksvorräte aufzufüllen, bevor er sein Muster weitergibt.",al={"welche gegenstände werden benötigt","kodobalgtasche materialien","gegenstände zur questabgabe"}},{q="Warum ist Kodohaut für die Handwerker der Tauren bedeutsam?",a="Kodos verkörpern Widerstandskraft und körperliche Stärke, Eigenschaften, die die Tauren schätzen. Ausrüstung aus ihren Häuten ehrt den Geist des Tieres und rüstet Reisende für die Durchquerung der Ebenen.",al={"warum kodohaut","bedeutung des kodos für tauren","bedeutung des kodos"}},{q="Was lehrt Veren Tallstrider nach Abschluss?",a="Nachdem er die Vorräte erhalten hat, lehrt Veren den Handwerker, eine Kodobalgtasche zu nähen.",al={"questbelohnung","was gibt es als belohnung","taschenmuster"}},{q="Wo lassen sich die benötigten Materialien beschaffen?",a="Ihr könnt niedrigstufige Wildtiere in ganz Mulgore und den umliegenden Gebieten häuten, um Leichtes Leder zu erhalten. Händler für Handwerks- und Schneidereibedarf verkaufen Groben Faden.",al={"wo gibt es leichtes leder","wo gibt es groben faden"}}},fx={c94273ea={q="Warum möchte Veren Tallstrider, dass dies erledigt wird?",a="Veren Tallstrider ist stolz darauf, die nächste Generation von Tauren-Lederern auszubilden. Mulgores Kodo-Bestien werden für ihre Stärke und Ausdauer verehrt, und die Herstellung einer traditionellen Tasche aus ihren Häuten ist eine grundlegende Fertigkeit. Indem er Euch bittet, Arbeitsmaterialien für sein Handwerk zu sammeln, stellt Veren Eure Hingabe und Euren Einfallsreichtum auf die Probe, bevor er die Techniken des Handwerks weitergibt.",al={"warum möchte veren tallstrider leder","motiv von veren tallstrider","grund für kodo hide bag aufgabe"}},["1f62e959"]={q="Wozu dient das Leichte Leder?",a="Leichtes Leder dient als grundlegendes Handelsgut, das Veren Tallstrider als Gegenleistung für seinen Unterricht benötigt. Das Arbeiten mit gegerbten Häuten ist der Kern der Tauren-Lederverarbeitung, und die Bereitstellung von hochwertigem Leder beweist, dass Ihr die Grundlagen der Tierhautbehandlung beherrscht, bevor Ihr lernt, wie man spezialisierte Behältnisse wie Kodo Hide Bags näht.",al={"wofür wird leichtes leder verwendet","warum leichtes leder bringen","zweck von leichtem leder"}},["7d0f7d7f"]={q="Wozu dient der Grobe Faden?",a="Grober Faden ist ein wesentlicher Bestandteil der Schneiderei und Lederverarbeitung, der dazu verwendet wird, dicke Häute zusammenzubinden. Um langlebige Rucksäcke zu konstruieren, die den Ebenen von Mulgore standhalten, benötigt ein Handwerker robustes Garn, das bei starker Belastung oder rauem Wetter nicht reißt.",al={"warum grober faden","zweck von grobem faden","wofür ist grober faden"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="Eine schwierige Situation",s="Dran Droffers sucht die Originalverpackung für die Hinterland-Honigwelle. Gilveradin Sunchaser hat sie und verlangt zwei zusätzliche Flaschen; zehn Flaschen warten in Kisten rund um die verlassene Basis der Horde nahe Skulk Rock.",h="Dran Droffers sucht die Originalverpackung für die Hinterland-Honigwelle.",kw={"dran droffers","gilveradin sunchaser","hinterland","hinterland-honigwelle","schlicke","skulk rock","schleime"},sec={{t="Eine Frage der Verpackung",b="Dran Droffers sucht Hinterland-Honigwelle, und Gilveradin Sunchaser hat die Originalverpackung dafür. Gilveradin bietet seine Hilfe im Gegenzug für zwei zusätzliche Flaschen an. Sammelt zehn Flaschen und bringt sie ins Lager zurück."},{t="Ruinen von Skulk Rock",b="Kisten mit Hinterland-Honigwelle stehen verstreut rund um die verlassene Basis der Horde nahe Skulk Rock. Üble Schleime und Schlicke klammern sich an die Ruinen. Gerüchten zufolge führt ein Meisterschlick sie an."}},faq={{q="Wer möchte die Hinterland-Honigwelle verpackt haben?",a="Dran Droffers sucht Hinterland-Honigwelle. Gilveradin Sunchaser hat die Originalverpackung dafür, die für Maltons Vater bestimmt ist.",al={"wer braucht die honigwelle","dran droffers honigwelle","für wen ist die verpackung"}},{q="Was verlangt Gilveradin für die Verpackung?",a="Gilveradin verlangt als Gebühr zwei zusätzliche Flaschen der Honigwelle. Zehn Flaschen befinden sich in den Kisten.",al={"warum zehn flaschen","gilveradins gebühr","warum so viel honigwelle"}},{q="Wo werden die Kisten mit Hinterland-Honigwelle aufbewahrt?",a="Die Kisten stehen rund um die verlassene Basis der Horde nahe Skulk Rock im Hinterland.",al={"honigwelle fundort","wo ist die honigwelle","skulk rock kisten"}},{q="Was befindet sich im verlassenen Lager bei Skulk Rock?",a="Üble Schleime und Schlicke klammern sich an die Ruinen, und Gerüchten zufolge führt ein Meisterschlick sie an.",al={"skulk rock monster","was gibt es bei skulk rock","skulk rock schlicke"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="Der Dämonennarbenumhang",s="In Mulgore trägt der Dämonennarbenumhang die Wunden von Ghost Howls Qualen. Der Pelz stammt von einem legendären weißen Wolf, den die Brennende Legion mit Narben zeichnete. Seine Ankunft im Dorf der Bluthufe bringt die leidvolle Geschichte der Bestie zum Abschluss.",h="In Mulgore trägt der Dämonennarbenumhang die Wunden von Ghost Howls Qualen.",kw={"brennende legion","dämonennarben-umhang","ghost howl","mulgore","skorn wolkenweiß","weißer wolf"},ang={["class:Druid"]="Als Druide seht Ihr den dämonenvernarbten Pelz als düstere Mahnung, dass das Land und seine wilden Bewohner noch immer unverheilte Wunden von der dämonischen Invasion Kalimdors tragen.",["class:Hunter"]="Als Jäger wisst Ihr, dass es ein Initiationsritus ist, einen einsamen, narbengezeichneten Leitwolf wie Ghost Howl aufzuspüren. Der Älteste Skorn Wolkenweiß lobt das Geschick und überreicht das Geschenk eines Meisterjägers.",["race:Tauren"]="Als Shu'halo könnt Ihr die Jagd auf Ghost Howl als düsteren Ritus sehen, der ein gepeinigtes Geschöpf vom fortwirkenden Makel der Brennenden Legion befreit."},sec={{t="Ein Relikt teuflischer Wunden",b="Ghost Howl ist ein legendärer weißer Wolf, dessen klagendes Heulen durch Mulgore hallt. Der Pelz, den die Bestie hinterließ, trägt die Narben dämonischer Verderbnis. Diese Male stammen aus verzweifelten Kämpfen gegen die einfallenden Dämonen der Brennenden Legion. Die Wunden blieben noch lange nach dem Dritten Krieg in Ghost Howls Fleisch und Geist bestehen."},{t="Frieden für einen gequälten Geist",b="Die Tauren von Mulgore verehren die wilden Tiere ihrer Heimat als Kinder der Erdenmutter. Im Dorf der Bluthufe nimmt Skorn Wolkenweiß den narbengezeichneten Umhang als Beweis entgegen, dass das gequälte Raubtier tot ist. Er erkennt das Geschick an, das nötig war, um Ghost Howl aufzuspüren und zu besiegen. Schwermütig hofft er, dass der gepeinigte Geist des Wolfes Frieden gefunden hat."}},faq={{q="Was ist der Dämonennarben-Umhang?",a="Der Dämonennarbenumhang ist der zerfetzte Pelz, den Ghost Howl hinterließ, ein legendärer weißer Wolf in Mulgore. Teufelsenergien zeichneten ihn in einem einstigen Kampf gegen die Brennende Legion mit Narben.",al={"was ist der dämonennarben-umhang","dämonennarben-umhang gegenstand","ghost howl pelz"}},{q="Woher stammen die Dämonennarben auf dem Umhang?",a="Ghost Howl wurde im Dritten Krieg bei Zusammenstößen mit den einfallenden Dämonen der Brennenden Legion verwundet, als diese durch Kalimdor vordrangen.",al={"warum hat ghost howl narben","wie bekam ghost howl seine narben","ghost howl legion"}},{q="Zu wem soll ich den Umhang bringen?",a="Bringt den Umhang zu Skorn Wolkenweiß, einem betagten Taurenjäger, der im Dorf der Bluthufe in Mulgore lebt.",al={"wo dämonennarben-umhang abgeben","wer will den dämonennarben-umhang","skorn wolkenweiß abgabe"}},{q="Warum liegt Skorn Wolkenweiß etwas an Ghost Howl?",a="Skorn Wolkenweiß ist ein Jäger im Ruhestand, der weiß, wie sehr Ghost Howl unter dämonischer Verderbnis litt. Er achtet das Geschick, das nötig war, um die Bestie zu erlegen, und hofft, dass ihr Geist endlich ruhen kann.",al={"skorn wolkenweiß hintergrundgeschichte","warum will skorn ghost howl"}},{q="Wo ist Ghost Howl zu finden?",a="Ghost Howl durchstreift die wogenden Ebenen von Mulgore, meist die nördlichen oder mittleren offenen Grasflächen zwischen der Hochwolkenebene und Donnerfels.",al={"wo ghost howl finden","ghost howl fundort","ghost howl erscheinen"}},{q="Warum hoffen die Tauren, dass der Geist des Wolfes Frieden findet?",a="Tauren verehren die Geister der Wildnis und suchen Einklang mit der Natur. Dämonische Verderbnis quälte Ghost Howl, weshalb die Tauren den Sieg über den Wolf als barmherzige Erlösung und Rückkehr zur Erdenmutter betrachten.",al={"taurenglaube ghost howl","ghost howl geist"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="GESUCHT: Vorarbeiter Maltorius",s="Im Kessel ist ein Kopfgeld für den Tod von Aufseher Maltorius ausgesetzt. Der Steckbrief nennt ihn einen abtrünnigen Agenten der Thoriumbruderschaft und den neu angeworbenen Kommandanten der Dunkeleisen-Besatzung der Schlackengrube. Aufseher Oilfist befiehlt, seinen Kopf als Beweis zu Ausguck Captain Lolo Longstriker zu bringen.",h="Im Kessel ist ein Kopfgeld für den Tod von Aufseher Maltorius ausgesetzt.",kw={"kopfgeld","kessel","lolo longstriker","aufseher maltorius","aufseher oilfist","sengende schlucht","die schlackengrube","thoriumbruderschaft"},sec={{t="Kopfgeld auf einen Verräter",b="Ihr werdet in die Schlackengrube im Kessel geschickt, um Aufseher Maltorius zu finden und zu erschlagen. Der Steckbrief bezeichnet ihn als verräterischen Dunkeleisenzwerg. Bringt seinen Kopf zu Ausguck Captain Lolo Longstriker, um das Kopfgeld zu erhalten."}},faq={{q="Wer ist Aufseher Maltorius?",a="Aufseher Maltorius ist ein verräterischer Dunkeleisenzwerg. Der Steckbrief nennt ihn einen abtrünnigen Agenten der Thoriumbruderschaft und den neu angeworbenen Kommandanten der Dunkeleisen-Besatzung der Schlackengrube im Kessel.",al={"maltorius geschichte","wer ist maltorius","aufseher maltorius hintergrundgeschichte"}},{q="Wo ist Aufseher Maltorius zu finden?",a="Aufseher Maltorius ist in der Schlackengrube im Kessel zu finden.",al={"maltorius aufenthaltsort","wo ist maltorius","wie aufseher maltorius finden"}},{q="Wer hat den Tod von Aufseher Maltorius befohlen?",a="Aufseher Oilfist hat den Tod von Aufseher Maltorius befohlen.",al={"wer hat das kopfgeld ausgesetzt","wer will maltorius tot sehen","wer hat die tötung befohlen"}},{q="Wer erhält den Beweis für Maltorius' Tod?",a="Ausguck Captain Lolo Longstriker in der Sengenden Schlucht erhält den Beweis für Maltorius' Tod: seinen Kopf.",al={"bei wem maltorius' kopf abgeben","wohin maltorius' kopf bringen","lolo longstriker aufenthaltsort"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="In der Sengenden Schlucht besitzt Ihr ein riesiges, verziertes Kissen, das einst Chambermaid Pillaclencher verwahrte. Evonice Sootsmoker wird es sicher haben wollen.",h="In der Sengenden Schlucht besitzt Ihr ein riesiges, verziertes Kissen, das einst Chambermaid Pillaclencher...",kw={"chambermaid pillaclencher","evonice sootsmoker","look at the size of it","kissen","sengende schlucht"},sec={{t="Ein Kissen für Evonice",b="Evonice Sootsmoker wird Chambermaid Pillaclenchers riesiges, verziertes Kissen sicher haben wollen. Bringt es ihr in die Sengende Schlucht und seht, was sie Euch für Eure Mühen anbietet."}},faq={{q="Wer will Chambermaid Pillaclenchers Kissen haben?",a="Evonice Sootsmoker in der Sengenden Schlucht wird Chambermaid Pillaclenchers Kissen sicher haben wollen.",al={"wem das kissen bringen","evonice sootsmoker kissen","wohin gehört das kissen"}},{q="Woher stammt dieses Kissen?",a="Das riesige, verzierte Kissen gehörte einst Chambermaid Pillaclencher.",al={"kissen beute","wer lässt das kissen fallen","chambermaid kissen"}},{q="Wo ist Evonice Sootsmoker zu finden?",a="Evonice Sootsmoker ist in der Sengenden Schlucht.",al={"evonice standort","wo ist evonice sootsmoker","evonice sengende schlucht"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="Ritus der Vision",s="Überall in Mulgore sammeln junge Tauren Gaben für den Ritus der Vision. Im Dorf der Bluthufe leitet Zarlman Zwillingsmond sie an, während sie das Wasser der Seher brauen und Rat bei den Geistern ihrer Ahnen suchen.",h="Überall in Mulgore sammeln junge Tauren Gaben für den Ritus der Vision.",kw={"bernsteinkorn","dorf der bluthufe","erdenmutter","mulgore","ritus der vision","wasser der seher","brunnensteine","zarlman zwillingsmond"},ang={["class:Druid"]="Als Druide verehrt Ihr Bernsteinkorn und Brunnensteine als Zeichen der Pflanzen und lebensspendenden Wasserläufe, die Mulgores Gleichgewicht erhalten.",["class:Shaman"]="Als Schamane erkennt Ihr im Wasser der Seher ein traditionelles Ritual der Erdung. Es stimmt Euren Geist darauf ein, unsichtbare Elemente zu deuten, bevor Ihr direkt mit Geistern sprecht.",["race:Tauren"]="Als Tauren erreicht Ihr einen kulturellen Meilenstein, der Euch mit dem spirituellen Erbe der Erdenmutter und der Ahnen verbindet, ob Ihr Krieger, Jäger oder Mystiker seid."},sec={{t="Die Reagenzien des Landes",b="Zarlman Zwillingsmond schickt Euch durch Mulgore, um Brunnensteine und Bernsteinkorn zu sammeln. Die Steine liegen nahe heiligen Gemeinschaftsbrunnen, während Bernsteinkorn unter die Wurzeln uralter Bäume fällt. Für die Tauren sind dies mehr als Gaben des Landes. Sie bergen die schlummernde Magie und das Lebensblut der Erdenmutter, bereit für den Ritus."},{t="Das Wasser der Seher brauen",b="Zarlman verbindet die Brunnensteine und das Bernsteinkorn, um das Wasser der Seher zu brauen. Ihr trinkt es neben der Stammesflamme des Dorfes. Der Trank klärt Euren Geist und beschwört einen ätherischen Führer herauf. Dann folgt Ihr dem Führer über die Ebenen und prüft, ob Ihr zwischen der physischen Welt und dem spirituellen Flüstern des Landes wandeln könnt."}},faq={{q="Welchen Zweck hat der Ritus der Vision?",a="Der Ritus der Vision prüft heranwachsende Tauren, die ihren Weg suchen. Ihr bereitet das Wasser der Seher zu und trinkt es, um dann zu lernen, mit Geistern zu sprechen und den Vorzeichen der Ahnen über Mulgores Ebenen zu folgen.",al={"was ist der ritus der vision","warum den ritus der vision vollziehen","zweck des ritus der vision"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein Schamane und Seher der Tauren im Dorf der Bluthufe. Er beaufsichtigt spirituelle Prüfungen für junge Abenteurer, bereitet rituelle Tränke wie das Wasser der Seher zu und deutet Zeichen der Erdenmutter.",al={"wer ist zarlman","zarlman zwillingsmond rolle","questgeber zarlman"}},{q="Wo findet man Brunnensteine und Bernsteinkorn?",a="Brunnensteine liegen nahe den Süßwasserbrunnen, die über Mulgore verstreut sind. Bernsteinkorn fällt am Fuß großer Bäume im umliegenden Grasland zu Boden.",al={"wo bernsteinkorn finden","brunnensteine fundort","reagenzien für den ritus der vision"}},{q="Was geschieht, nachdem man das Wasser der Seher getrunken hat?",a="Nahe dem Stammesfeuer öffnet das Trinken des Wassers der Seher Euren spirituellen Blick und offenbart einen geisterhaften Tierführer. Ihr folgt dem Geist über die Ebenen, um die nächste Etappe Eurer heiligen Reise zu finden.",al={"wie geht der ritus der vision weiter","wasser der seher wirkung","visionsquest fortsetzung"}},{q="Warum verehren die Tauren Wasserbrunnen so sehr?",a="Wasser ist Mulgores Lebensblut und eine kostbare Gabe der Erdenmutter. Die Tauren verehren die Brunnen als heilige Mittelpunkte der Gemeinschaft, die das Land und seine Herden nähren. Die daneben gesammelten Steine bergen spirituelle Kraft.",al={"tauren wasserbrunnen","warum sind brunnen heilig","mulgore wasser"}},{q="Führt diese Quest zu weiteren Riten?",a="Ja. Die Zeremonie hat mehrere Etappen. Nachdem Zarlman das Wasser der Seher zubereitet hat, trinkt Ihr es, folgt der erscheinenden Vision und stellt Euch den Ältesten in ganz Mulgore vor.",al={"nächste quest im ritus der vision","ist der ritus der vision eine questreihe","tauren riten questreihe"}}},fx={["6b13f1a7"]={q="Warum möchte Zarlman Zwillingsmond, dass dies erledigt wird?",a="Als Stammschamane ist Zarlman Zwillingsmond dafür verantwortlich, vielversprechende junge Abenteurer durch die heiligen Traditionen der Tauren zu führen. Er kann Euch nicht einfach spirituelle Weisheit verleihen; Ihr müsst Euch die Gunst der Erdenmutter und Eurer Vorfahren verdienen, indem Ihr direkt am Ritual teilnehmt, angefangen damit, die heiligen Elemente des Landes selbst zu sammeln.",al={"motiv von zarlman zwillingsmond","warum schickt euch zarlman","grund für zarlmans rite of vision"}},cc7474fb={q="Wozu dienen die Quellsteine?",a="Quellsteine werden aus den heiligen Wasserquellen in ganz Mulgore gesammelt. Durchdrungen von der natürlichen Magie der reinsten Quellen der Erdenmutter, dienen sie als eine der wichtigsten Reagenzien, die Zarlman Zwillingsmond benötigt, um das mystische Wasser der Seher zu brauen.",al={"zweck der quellsteine","warum quellsteine nötig","verwendung von quellsteinen"}},["4efb8f2d"]={q="Wozu dient das Bernsteinkorn?",a="Das von den mächtigen Bäumen in ganz Mulgore gefallene Bernsteinkorn trägt die natürliche Essenz der Flora des Landes in sich. Kombiniert mit Quellsteinen und von Zarlman Zwillingsmond aufgebrüht, liefert es die magischen Eigenschaften, die erforderlich sind, um das Wasser der Seher zu brauen, wodurch Ihr Visionen der Vorfahren erhaltet.",al={"zweck von bernsteinkorn","wofür wird bernsteinkorn verwendet","warum bernsteinkorn sammeln"}},["761f0189"]={q="Warum müsst Ihr die Reagenzien sammeln und nicht Zarlman Zwillingsmond?",a="Die Rite of Vision ist eine individuelle Prüfung spirituellen Wachstums, keine routinemäßige Aufgabe. Um mit den Geistern zu kommunizieren, müsst Ihr Ehrfurcht und Harmonie mit dem Land demonstrieren, indem Ihr seine natürlichen Segnungen mit Euren eigenen Händen sucht. Jemand anderen die Reagenzien sammeln zu lassen, würde den heiligen Zweck der Prüfung zunichtemachen.",al={"warum muss ich bernsteinkorn sammeln","warum sammelt zarlman keine quellsteine","warum ich rite of vision"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="Ritus der Vision",s="Im Dorf der Bluthufe trinken junge Tauren das Wasser der Seher und erblicken den Weg, der vor ihnen liegt. Ein geisterhafter Führer erhebt sich neben dem Stammesfeuer.",h="Im Dorf der Bluthufe trinken junge Tauren das Wasser der Seher und erblicken den Weg, der vor ihnen liegt.",kw={"dorf der bluthufe","geisterwolf","mulgore","ritus der vision","seher wiserunner","stammesfeuer","wasser der seher","zarlman zwillingsmond"},ang={["class:Druid"]="Als Druide vertieft Ihr Eure Ehrfurcht vor der Natur und Eure spirituelle Demut gegenüber der Führung durch Tiergestalten.",["class:Shaman"]="Als Schamane lernt Ihr früh, zwischen den Welten zu wandeln, indem Ihr einem Geisterwolf der Vorfahren folgt. Der Ritus festigt Eure Verbindung zu den Geistern, die die Horde führen.",["race:Tauren"]="Als junger Taure tretet Ihr durch den heiligen Ritus der Vision ins Erwachsenenalter ein. Er zeigt Eure Verbundenheit mit Euren Vorfahren und Euren Gehorsam gegenüber spiritueller Führung."},sec={{t="Das Wasser der Seher",b="Nachdem Ihr die Ritualkräuter gesammelt und die ersten Glaubensprüfungen bestanden habt, erhaltet Ihr von Zarlman Zwillingsmond das Wasser der Seher. Ihr trinkt es vor dem Stammesfeuer im Herzen des Dorfes der Bluthufe. Bleibt konzentriert und ehrerbietig, und das heilige Wasser öffnet Euren Blick über die körperliche Welt hinaus. Es verbindet die materielle Welt mit dem Geisterreich."},{t="Dem Geisterwolf folgen",b="Sobald Ihr das Gebräu trinkt, erscheint ein Geisterwolf der Vorfahren in den Flammen. Er spricht nicht und kämpft nicht, sondern trabt nach Nordwesten über die wogenden Ebenen von Mulgore. Folgt seinem stillen Pfad fort vom Dorf und hinein in die felsigen Hügel. Dort wartet der Einsiedler Seher Wiserunner in abgeschiedener Meditation."},{t="Ein Weg zur Weisheit",b="Die Vision endet, wenn Ihr Seher Wiserunner am Eingang seiner Berghöhle erreicht. Der Weg über grasbewachsene Hügel prüft Eure Geduld, Euer Vertrauen in die Führung der Vorfahren und Eure Einstimmung auf die Erdenmutter. Besteht den Ritus, und Ihr erlangt das Recht, Euch dem Rite of Wisdom zu stellen, der höchsten Prüfung des Erwachsenwerdens."}},faq={{q="Was geschieht, wenn ich das Wasser der Seher trinke?",a="Wenn Ihr das Wasser der Seher nahe dem Stammesfeuer im Dorf der Bluthufe trinkt, öffnen sich Eure spirituellen Sinne. Bald erscheint vor den Flammen ein Geisterwolf, um Euch zu führen.",al={"wie wirkt das wasser der seher","wasser der seher trinken","was bewirkt das wasser"}},{q="Wohin führt mich der Geisterführer?",a="Der geisterhafte Wolf führt Euch vom Dorf der Bluthufe nach Nordwesten, über die Hügel von Mulgore zu einer Felshöhle, in der Seher Wiserunner wohnt.",al={"wohin geht der geisterwolf","zu wem führt der wolf","ziel des wolfes"}},{q="Wer ist Zarlman Zwillingsmond?",a="Zarlman Zwillingsmond ist ein Taurenschamane im Dorf der Bluthufe, der Initianden durch Ahnenriten und heilige Gebräue auf ihre spirituelle Reife vorbereitet.",al={"wer gibt den ritus der vision","zarlman zwillingsmonds rolle"}},{q="Wer ist Seher Wiserunner?",a="Seher Wiserunner ist ein betagter Mystiker der Tauren, der in stiller Einkehr zwischen den Klippen nordwestlich des Dorfes der Bluthufe lebt. Initianden, die ihrer Geistervision folgen, finden ihn und schließen die Prüfung ab.",al={"wer ist wiserunner","seher in höhle mulgore"}},{q="Warum muss das Wasser nahe dem Stammesfeuer getrunken werden?",a="Das Stammesfeuer im Dorf der Bluthufe verankert die Geister seiner Vorfahren. Seine geweihten Flammen und das heilige Wasser lassen die Vision gemeinsam in die wache Welt übertreten.",al={"warum stammesfeuer","stammesfeuer ritus der vision"}},{q="Welcher Ritus folgt auf den Ritus der Vision?",a="Nachdem Ihr den Ritus der Vision bei Seher Wiserunner abgeschlossen habt, stellt Ihr Euch dem Rite of Wisdom, der letzten spirituellen Prüfung Eurer frühen Reise in Mulgore.",al={"nächste quest nach ritus der vision","what comes next"}}},fx={["659b3713"]={q="Warum möchte Zarlman Zwillingsmond, dass ich die Rite of Vision durchlaufe?",a="Als Schamane des Dorfes der Bluthufe führt Zarlman Zwillingsmond junge Tauren auf den heiligen Pfaden ihrer Vorfahren. Nachdem Ihr die Komponenten für das Wasser der Seher gesammelt habt, präsentiert er nun den Trank, damit Ihr direkt mit den Geistern kommunizieren, Eure Vision erleben und den nächsten Schritt auf dem Weg zur Entdeckung Eures Schicksals innerhalb des Stammes tun könnt.",al={"warum rite of vision","motiv von zarlman zwillingsmond","zweck der rite of vision"}},b8c8221c={q="Warum muss ich dieses Ritual selbst durchführen?",a="Die Rites of the Earthmother sind zutiefst persönliche Prüfungen der Reife und des spirituellen Erwachens. Kein Wächter oder Ältester kann den Pfad der Geister für Euch beschreiten; nur Euer eigener Geist kann die Führung erhalten, die dazu bestimmt ist, Euren Platz und Zweck unter dem Volk der Tauren zu enthüllen.",al={"warum muss ich die rite durchführen","warum ich für die rite of vision","warum kann niemand anderes die rite durchführen"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="Treibstoff fürs Schrumpfen",s="An der Vergessenen Küste betreibt Zorbin Fandazzle seine Ingenieurswerkstatt an einem ungünstigen Ort. Die Elementare machen ihm zu schaffen, doch ihre Wasserkerne können die Energie zur Verfeinerung des Ultra-Shrinker liefern.",h="An der Vergessenen Küste betreibt Zorbin Fandazzle seine Ingenieurswerkstatt an einem ungünstigen Ort.",kw={"feralas","die vergessene küste","sea elemental","sea spray","ultra-shrinker","wasserelementarkern","zorbin fandazzle"},sec={{t="Energie aus der Brandung",b="Zorbin Fandazzle verflucht die unkontrollierte Macht des Elementarismus und nennt die Elementare der Küste Plagegeister. Dennoch sieht er ihre Wasserelementarkerne als rohe Energie zur Verfeinerung des Ultra-Shrinker. Er bittet Euch, die Sea Elementals und Sea Sprays entlang der Küste zu bekämpfen. Behaltet ihre Kerne und bringt sie ihm zur Anlegestelle."},{t="Zorbins Dank",b="Zorbin ist von den Kernen begeistert. Sie werden seine Arbeit noch einige Zeit am Laufen halten, und nun streifen weniger Elementare an der Küste umher. Er gibt zu, dass die Eröffnung seiner Werkstatt am wohl denkbar schlechtesten Ort ihm Anlass gab, nachts zu weinen. Die Bezahlung strapaziert seine Finanzen, doch er bietet sie aus Dankbarkeit an."}},faq={{q="Wer bittet um die Elementarkerne?",a="Zorbin Fandazzle bittet um die Elementarkerne. Seine Ingenieurswerkstatt liegt bei der Anlegestelle an der Vergessenen Küste von Feralas.",al={"wer vergibt treibstoff fürs schrumpfen","zorbin fandazzle questgeber","wer startet treibstoff fürs schrumpfen"}},{q="Warum braucht Zorbin Fandazzle Wasserelementarkerne?",a="Zorbin Fandazzle braucht Wasserelementarkerne als rohe Energie zur Verfeinerung des Ultra-Shrinker. Er hält die örtlichen Elementare für eine ideale Quelle.",al={"warum wasserelementarkerne","wofür werden kerne verwendet","ultra-shrinker treibstoff"}},{q="Wo werden die Elementarkerne gesammelt?",a="Sammelt die Kerne von Sea Elementals und Sea Sprays entlang der Vergessenen Küste von Feralas.",al={"wo kerne finden","sea elemental fundort","wo sind sea sprays"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="Was zum Fluxus?!",s="Meisterschmied Burninate sucht die Pläne für Feurigen Fluxus in der Schlackengrube. Maltorius verließ ihren Clan mit dem Rezept, das Burninate höher schätzt als einen makellosen Arkankristall, und glaubt, die Pläne seien in seiner Nähe.",h="Meisterschmied Burninate sucht die Pläne für Feurigen Fluxus in der Schlackengrube.",kw={"burninate","kessel","feuriger fluxus","maltorius","pläne","sengende schlucht","die schlackengrube"},sec={{t="Das gestohlene Rezept",b="Meisterschmied Burninate sagt, Maltorius habe ihren Clan verraten, als er ihn mit dem Rezept für Feurigen Fluxus verließ. Burninate vermutet, dass dieses Rezept Maltorius zu seiner jüngsten Beförderung bei den Dunkeleisenzwergen verhalf. Nun will Burninate die Geheimpläne zurück."},{t="In die Schlackengrube",b="Meisterschmied Burninate glaubt, dass die Pläne in Maltorius' Nähe liegen, tief in der Schlackengrube. Er möchte, dass Ihr ihm die Geheimpläne: Feuriger Fluxus zurückbringt."}},faq={{q="Wer hat das Rezept für Feurigen Fluxus gestohlen?",a="Laut Meisterschmied Burninate hat Maltorius das Rezept für Feurigen Fluxus gestohlen. Burninate nennt ihn einen Verräter an ihrem Clan.",al={"wer hat das rezept gestohlen","wer hat die pläne genommen","was zum fluxus?! verräter"}},{q="Wo sind die Geheimpläne?",a="Burninate glaubt, dass die Geheimpläne nahe bei Maltorius liegen, tief in der Schlackengrube im Kessel.",al={"wo sind die pläne","geheimpläne feuriger fluxus fundort","wo sind die pläne für feurigen fluxus"}},{q="Wer bittet darum, die Pläne zurückzuholen?",a="Meisterschmied Burninate, ein Schmied, will die Pläne zurück.",al={"wer vergibt was zum fluxus?!","was zum fluxus?! questgeber"}},{q="Warum sind die Pläne für Burninate wichtig?",a="Burninate sagt, das geheime Rezept des Clans für Feurigen Fluxus sei mehr wert als ein makelloser Arkankristall.",al={"warum ist feuriger fluxus wichtig","bedeutung des rezepts für feurigen fluxus"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="Verdammt seien diese fetten Finger",s="In der Sengenden Schlucht kann Hansel Bleihand nicht mehr wie früher Prügel austeilen. Wegen geschwollener Finger bittet Hansel Euch, stattdessen die schweren Kriegsgolems zu verprügeln.",h="In der Sengenden Schlucht kann Hansel Bleihand nicht mehr wie früher Prügel austeilen.",kw={"kessel","fette finger","hansel bleihand","schwere kriegsgolems","sengende schlucht","thelsamar blood sausages"},sec={{t="Finger wie Würste",b="Hansel Bleihand macht das Klima und die dünne Luft der Sengenden Schlucht für die geschwollenen Finger verantwortlich. Sie ähneln riesigen Thelsamar Blood Sausages. Mit solchen Fingern kann Hansel nicht mehr wie früher Prügel austeilen und braucht Euch deshalb, um sich um Hansels Angelegenheiten zu kümmern."},{t="Als Erstes dran",b="Hansel will, dass Ihr die schweren Kriegsgolems der Schlucht ordentlich verprügelt. Zwanzig müssen zerstört werden. Sie durchstreifen die Gebiete um den Kessel, und Ihr kehrt zu Hansel zurück, sobald genug gefallen sind."}},faq={{q="Wer ist Hansel Bleihand?",a="Hansel Bleihand befindet sich in der Sengenden Schlucht, wo geschwollene Finger das Kämpfen verhindern. Hansel bittet Euch, stattdessen die Prügel auszuteilen.",al={"hansel bleihand","wer vergibt verdammt seien diese fetten finger","wer ist der questgeber"}},{q="Warum kann Hansel die Golems nicht selbst bekämpfen?",a="Hansel macht das Klima und die dünne Luft der Sengenden Schlucht für die geschwollenen Finger verantwortlich. Hansel vergleicht sie mit riesigen Thelsamar Blood Sausages.",al={"warum sind hansels finger dick","geschichte der fetten finger","hansels geschwollene hände"}},{q="Welche Feinde müssen erledigt werden?",a="Ihr müsst zwanzig schwere Kriegsgolems zerstören.",al={"welche gegner bekämpfen","wen will hansel tot sehen"}},{q="Wo befinden sich die schweren Kriegsgolems?",a="Die schweren Kriegsgolems durchstreifen die Gebiete um den Kessel in der Sengenden Schlucht.",al={"wo sind die golems","standort der schweren kriegsgolems"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="Feurige Bedrohung!",s="Hansel Bleihand hat einen weiteren Auftrag für Euch in der Sengenden Schlucht. Große Lavaspinnen machen Ärger.",h="Hansel Bleihand hat einen weiteren Auftrag für Euch in der Sengenden Schlucht.",kw={"feurige bedrohung","große lavaspinnen","hansel bleihand","oilfist","sengende schlucht","spinnen"},sec={{t="Ein weiterer Auftrag für Hansel",b="Hansel Bleihand hat wenig Zeit, sich auszuruhen oder über sein Leben nachzudenken. Die Obrigkeit gibt ihm ständig mehr Arbeit. Große Lavaspinnen sorgen für Aufruhr, deshalb wäre es Hansel lieber, wenn Ihr Euch um sie kümmert."},{t="Die Großen Lavaspinnen",b="Oilfist sagt, die Großen Lavaspinnen verschießen Feuer aus einer unangenehmen Stelle. Ihre Flammen verstören die Kinder. Hansel will, dass Ihr zwanzig Spinnen auf den Hochebenen und an den Lavaseen der Sengenden Schlucht tötet."}},faq={{q="Wer schickt Euch auf die Jagd nach den Spinnen?",a="Hansel Bleihand schickt Euch auf die Jagd nach den Spinnen in der Sengenden Schlucht. Er hatte auf einen ruhigen Moment gehofft.",al={"questgeber","wer gibt die quest","hansel"}},{q="Warum müssen die Spinnen getötet werden?",a="Große Lavaspinnen sorgen für Aufruhr. Oilfist sagt, die Art, wie sie Feuer verschießen, verstört die Kinder.",al={"warum spinnen töten","was haben die spinnen getan","spinnenproblem"}},{q="Wer hat Hansel von den Spinnen erzählt?",a="Oilfist hat Hansel erzählt, dass die Spinnen Feuer aus einer unangenehmen Stelle verschießen.",al={"wer hat sich über spinnen beschwert","oilfist"}},{q="Wie viele Große Lavaspinnen müssen getötet werden?",a="Hansel bittet Euch, zwanzig Große Lavaspinnen zu töten.",al={"wie viele spinnen","spinnenanzahl"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="Und wieder unter den geschrumpften Riesen",s="An den Docks der Vergessenen Küste hat Zorbin Fandazzle ein weiteres Angebot für Euch. Bringt ihm mehr Rückstände von Riesen aus Feralas, die mit dem Ultra-Schrumpfer geschrumpft wurden. Er kann diesmal weit weniger zahlen, verspricht aber, Eure Dienste bekannt zu machen.",h="An den Docks der Vergessenen Küste hat Zorbin Fandazzle ein weiteres Angebot für Euch.",kw={"feralas","die vergessene küste","riesen","miniaturisierungsrückstände","steamwheedle cartel","ultra-schrumpfer","zorbin fandazzle"},sec={{t="Eine Zugabe für den Ultra-Schrumpfer",b="Zorbin Fandazzle bittet Euch, erneut Riesen in Feralas zu schrumpfen und zehn Miniaturisierungsrückstände zu den Docks der Vergessenen Küste zu bringen. Es ist immer Platz für mehr, selbst nach Eurer ersten Ausbeute.\n\nEr kann diesmal bei Weitem nicht so viel bieten. Stattdessen verspricht er, Eure Dienste unter seinen Goblinfreunden zu preisen, die ziemlich große Ohren haben."},{t="Zorbins Dank",b="Zorbin Fandazzle ist überglücklich, dass Ihr erneut geholfen habt, auch wenn die Bezahlung geringer ausfällt, als Ihr es gewohnt seid. Er sagt, die Kunde von Euren großen Taten für das Goblindom halle bereits durch die Machtzentren des Steamwheedle Cartels."}},faq={{q="Wer bittet um mehr Rückstände?",a="Zorbin Fandazzle wartet an den Docks der Vergessenen Küste in Feralas und bittet Euch um mehr Rückstände.",al={"questgeber","zorbins standort","wer vergibt und wieder unter den geschrumpften riesen"}},{q="Was ging dem voraus?",a="Dies folgt auf Zapped Giants, Eure erste Runde beim Sammeln von Rückständen für Zorbin Fandazzle.",al={"voraussetzung","vorherige quest","was zuerst tun"}},{q="Wie werden die Rückstände gesammelt?",a="Setzt Zorbins Ultra-Schrumpfer bei einer beliebigen Art von Riesen in Feralas ein, um sie zu schrumpfen. Sucht dann bei den geschrumpften Riesen nach den Rückständen.",al={"wie rückstände erhalten","miniaturisierungsrückstände","wie riesen schrumpfen"}},{q="Wo sind die Riesen zu finden?",a="Die Riesen befinden sich entlang der Westküste von Feralas.",al={"standort der riesen","wo sind die riesen in feralas","riesen der vergessenen küste"}},{q="Nimmt Zorbin später weitere Rückstände an?",a="Zorbin sagt, er könne immer mehr Rückstände gebrauchen, also könnt Ihr mit weiteren zehn zurückkehren.",al={"ist dies wiederholbar","ist und wieder unter den geschrumpften riesen wiederholbar","wiederholbare riesenquest"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="Neuer Treibstoff fürs Schrumpfen",s="An der Vergessenen Küste benötigt Zorbin Fandazzle weitere Wasserelementarkerne. Der Laden lässt sich nur schwer aufbauen, daher ist die Bezahlung gering. Dennoch verspricht Zorbin, den Leuten in der Nähe von Eurer Hilfe zu erzählen, und sagt, es gebe Freunde im Cartel.",h="An der Vergessenen Küste benötigt Zorbin Fandazzle weitere Wasserelementarkerne.",kw={"feralas","die vergessene küste","sea elemental","sea spray","steamwheedle cartel","wasserelementarkern","zorbin fandazzle"},sec={{t="Mehr vom Selben",b="Zorbin Fandazzle macht sich über die heldenhafte Arbeit lustig, Schleim von elementaren Wesen zu sammeln. Dann fragt Zorbin, ob Ihr mehr vom Selben wollt. Hinter dem Scherz steckt Zorbins Bedarf an weiteren Wasserelementarkernen.\n\nEinen Laden an der Vergessenen Küste aufzubauen, ist ein verzweifeltes Unterfangen, daher kann es nur wenig als Gegenleistung geben. Zorbin verspricht, allen in der Nähe von Eurer Hilfe zu erzählen, und sagt, das Versprechen sei vertrauenswürdig, weil Zorbin Leute im Cartel kennt. Bringt sechs Kerne von Sea Elementals und Sea Sprays an der Vergessenen Küste zu Zorbin nahe der Anlegestelle."},{t="Zorbins Dank",b="Zorbin ist mit Eurer Arbeit zufrieden, auch wenn Ihr dafür vielleicht anderswo mehr Münzen erhalten werdet. Zorbin wird den Kameraden im Steamwheedle Cartel von Euren Bemühungen berichten. Wenn Ihr wollt, gibt es noch mehr zu tun: Zorbin benötigt weiterhin weitere Kerne und ähnliche Dinge."}},faq={{q="Wer verlangt die Wasserelementarkerne?",a="Zorbin Fandazzle wartet nahe der Anlegestelle an der Vergessenen Küste von Feralas.",al={"wer vergibt diese quest","wer ist zorbin fandazzle","wo ist zorbin"}},{q="Woher stammen die Wasserelementarkerne?",a="Die Kerne stammen von Sea Elementals und Sea Sprays an der Vergessenen Küste von Feralas.",al={"wo werden kerne erbeutet","fundort der wasserelementarkerne","welche gegner lassen kerne fallen"}},{q="Warum benötigt Zorbin Fandazzle weitere Kerne?",a="Zorbin sagt, dass weitere Wasserelementarkerne benötigt werden, während der Aufbau eines Ladens an der Küste Schwierigkeiten bereitet.",al={"warum will zorbin kerne","zorbin fandazzles beweggrund","wofür sind die kerne"}},{q="Was ging dem voraus?",a="Dem ging Fuel for the Zapping voraus, als Ihr zum ersten Mal Elementarkerne für Zorbin gesammelt habt.",al={"vorherige quest","vorausgesetzte quest","welche quest kommt zuerst"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurier? Was-auch-immer-Saurier?",s="Hansel Bleihand kann mit seinen Füßen in solch einem Zustand nicht kämpfen. Also schickt er Euch, um zwanzig Incendosaurier in der Schlackengrube zu erschlagen, wo Scrange und Burninate die Lavateiche für Expeditionsteams räumen lassen wollen.",h="Hansel Bleihand kann mit seinen Füßen in solch einem Zustand nicht kämpfen.",kw={"burninate","kessel","hansel bleihand","incendosaurier","scrange","sengende schlucht","die schlackengrube"},sec={{t="Ballenzehen über Ballenzehen",b="Hansel Bleihand kann nicht kämpfen, solange seine Ballenzehen in solch einem Zustand sind. Scrange und Burninate haben ihm aufgetragen, die Incendosaurier zu töten, damit Expeditionsteams die Lavateiche der Schlackengrube erkunden können. Nun schickt er Euch an seiner Stelle."},{t="Die Lavateiche",b="Die Incendosaurier bevölkern die Lavateiche in der Schlackengrube, innerhalb des Kessels. Hansel will, dass zwanzig erschlagen werden, bevor Ihr zurückkehrt."}},faq={{q="Wer ist Hansel Bleihand?",a="Hansel Bleihand gibt Euch Arbeit in der Sengenden Schlucht. Scrange und Burninate haben ihm aufgetragen, sich um die Incendosaurier zu kümmern, doch seine Ballenzehen halten ihn vom Kämpfen ab.",al={"hansel bleihand","wer ist der questgeber","wer gibt diese quest"}},{q="Warum müssen die Incendosaurier beseitigt werden?",a="Scrange und Burninate wollen, dass Expeditionsteams die Lavateiche der Schlackengrube erkunden. Die Incendosaurier dort sollen allerlei Probleme verursachen.",al={"warum incendosaurier töten","incendosaurier zweck","warum die schlackengrube räumen"}},{q="Wo sind die Incendosaurier zu finden?",a="Die Incendosaurier leben in den Lavateichen der Schlackengrube, innerhalb des Kessels.",al={"incendosaurier fundort","wo ist die schlackengrube","wo sind die lavateiche"}},{q="Warum jagt Hansel sie nicht selbst?",a="Hansel sagt, seine Ballenzehen hätten Ballenzehen. Seine Füße sind in einem zu schlechten Zustand, als dass er irgendetwas töten könnte.",al={"warum kämpft hansel nicht","hansels füße","hansels ballenzehen"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="GESTOHLEN: Schmiedewindform und ein Ausguck-Handfernrohr",s="In der Sengenden Schlucht sucht die Thoriumbruderschaft zwei gestohlene Werkzeuge: eine Windform und ein Ausguck-Handfernrohr. Die Bruderschaft ist sich sicher, dass neidische, skrupellose Dunkeleisenzwerge sie gestohlen haben, und bittet darum, dass jeder, der sie findet, sie gegen Bezahlung zu Zuchtmeister Scrange bringt.",h="In der Sengenden Schlucht sucht die Thoriumbruderschaft zwei gestohlene Werkzeuge: eine Windform und ein...",kw={"dunkeleisen","scrange","sengende schlucht","schmieden","fernrohr","thoriumbruderschaft","windform"},sec={{t="Gestohlene Waren",b="Die Thoriumbruderschaft sucht ein Ausguck-Handfernrohr und eine Windform, die beide gestohlen wurden. Das Fernrohr ist ein feines Werkzeug für Ausgucker, und die Windform ist ein Schmiedewerkzeug, das nicht ersetzt werden kann. Die Bruderschaft ist sich sicher, dass Dunkeleisenzwerge sie gestohlen haben. Wer die Werkzeuge findet, soll sie zu Zuchtmeister Scrange bringen."}},faq={{q="Wer hat den Aushang angebracht?",a="Der Aushang spricht für die Thoriumbruderschaft, die sich sicher ist, dass Dunkeleisenzwerge die Gegenstände gestohlen haben.",al={"wer will die gestohlenen gegenstände","wer hat diese quest vergeben","gestohlene schmiedewindform questgeber"}},{q="Wer hat die Werkzeuge gestohlen?",a="Die Thoriumbruderschaft ist sich sicher, dass skrupellose, neidische Dunkeleisenzwerge der Sengenden Schlucht die Werkzeuge gestohlen haben.",al={"wer hat die windform genommen","wer hat das fernrohr gestohlen","wer hat die gestohlenen gegenstände"}},{q="Wer erhält die wiedergefundenen Gegenstände?",a="Zuchtmeister Scrange erhält die wiedergefundenen Gegenstände.",al={"wo wird die quest abgegeben","wer ist zuchtmeister scrange","wer bekommt das fernrohr"}},{q="Wozu dienen die gestohlenen Gegenstände?",a="Die Windform ist ein unersetzliches Schmiedewerkzeug, und das Fernrohr hilft Ausguckern, Wache zu halten.",al={"was ist eine schmiedewindform","warum will die bruderschaft die windform","was macht das fernrohr"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="STELLE ZU VERGEBEN: Erledige die Konkurrenz",s="In der Sengenden Schlucht will Zuchtmeister Scrange, dass Ihr die Konkurrenz durch blutige Arbeit ausdünnt.",h="In der Sengenden Schlucht will Zuchtmeister Scrange, dass Ihr die Konkurrenz durch blutige Arbeit ausdünnt.",kw={"konkurrenz erledigen","dunkeleisen-slaver","dunkeleisen-taskmaster","stelle zu vergeben","sengende schlucht","zuchtmeister scrange"},sec={{t="Eine offene Stelle",b="Zuchtmeister Scrange schickt Euch durch die Schlucht, um fünfzehn Dunkeleisen-Taskmasters und fünfzehn Dunkeleisen-Slavers zu töten. Kehrt zurück, wenn Eure Kleidung blutig genug ist. Ihr werdet wissen, wann das der Fall ist, und Ihr sollt nicht fragen."}},faq={{q="Wer bietet diese Stelle an?",a="Zuchtmeister Scrange in der Sengenden Schlucht sucht Hilfe, um die Konkurrenz auszudünnen.",al={"wer bietet diese quest an","wer will die taskmasters töten lassen","wer ist zuchtmeister scrange"}},{q="Welche Feinde müssen getötet werden?",a="Tötet fünfzehn Dunkeleisen-Taskmasters und fünfzehn Dunkeleisen-Slavers.",al={"welche gegner töten","ziele für stelle zu vergeben","wer ist die konkurrenz"}},{q="Woran erkennt Scrange, dass die Arbeit erledigt ist?",a="Scrange urteilt nach dem Zustand Eurer Kleidung und wiegt Euch zur Sicherheit mit und ohne sie.",al={"wie tötungen nachweisen","blutige kleidung als voraussetzung","wie prüft scrange"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="Ritus der Weisheit",s="An den Teufelsfelsen führt der Ritus der Weisheit die Rites of the Earthmother zur letzten Prüfung. Nachdem der Rite of Vision Euren Blick geklärt hat, reist Ihr weiter, um mit einem Vorfahrengeist Zwiesprache zu halten und den Segen der Toten zu suchen.",h="An den Teufelsfelsen führt der Ritus der Weisheit die Rites of the Earthmother zur letzten Prüfung.",kw={"vorfahrengeist","mulgore","teufelsfelsen","ritus der weisheit","rites of the earthmother","seher wiserunner","donnerfels","wasser der seher"},ang={["class:Druid"]="Als Druide erkennt Ihr das Gleichgewicht zwischen der Welt der Lebenden und dem ewigen Kreislauf, über den die Erdenmutter wacht. Eure Pflicht gilt dem Land.",["class:Shaman"]="Als Schamane ehrt Ihr die Toten, indem Ihr mit einem Vorfahrengeist Zwiesprache haltet. Ihr haltet den Geistern die Treue, die über Mulgore wachen.",["race:Tauren"]="Als shu'halo vollzieht Ihr mit der Übernahme des Erbes der Ahnen an den Teufelsfelsen den Übergang zum vollwertigen Erwachsenen und findet Anerkennung unter den Stammesältesten."},sec={{t="Die Prüfung der Teufelsfelsen",b="Nachdem der Rite of Vision Euren Blick geklärt hat, reist Ihr östlich von Donnerfels zu den Teufelsfelsen. Die hier Begrabenen kämpften und starben, damit Mulgore Frieden finden konnte, und ihre Geister verweilen noch immer. Nähert Euch ihrer Ruhestätte mit Ehrfurcht und sucht die Zwiesprache. Bedrohliche Wesen bewachen die Hügel, während Ihr den Rat der geehrten Toten sucht."},{t="Das Erbe weitergeben",b="Auf dem Gipfel der Teufelsfelsen haltet Ihr Zwiesprache mit einem Vorfahrengeist. Die Begegnung prüft Eure spirituelle Bereitschaft und Euren Platz in der Folge der Generationen, nicht Eure Stärke im Kampf. Diese Geister kämpften an der Seite von Cairne Bluthuf, um Donnerfels zu gründen und die Stämme zu schützen. Ihr Segen zeichnet Euch als Erwachsenen und Verteidiger aus. Euch wird aufgetragen, die Stadt zu beschützen, und Ihr dürft Donnerfels mit Stolz betreten."}},faq={{q="Welchen Zweck hat der Ritus der Weisheit?",a="Der Ritus der Weisheit ist die letzte Prüfung der Rites of the Earthmother. Der Segen der Ahnen verbindet die Vision der Jugend mit den Pflichten des Erwachsenseins und kennzeichnet Euch als bereit, Donnerfels zu verteidigen.",al={"warum ritus der weisheit absolvieren","was bewirkt der ritus der weisheit","ritus der weisheit zweck"}},{q="Wer schickt Euch auf den Ritus der Weisheit?",a="Seher Wiserunner schickt Euch aus seiner Höhle nordwestlich vom Dorf der Bluthufe los, nachdem Ihr den Rite of Vision abgeschlossen und vom Wasser der Seher getrunken habt.",al={"wer vergibt den ritus der weisheit","wo beginnt der ritus der weisheit"}},{q="Wo findet Ihr den Vorfahrengeist?",a="Ihr findet den Vorfahrengeist an den Teufelsfelsen, einer uralten Begräbnisstätte der Tauren in den felsigen Höhen direkt östlich von Donnerfels.",al={"vorfahrengeist fundort","wo ist der geist","wo vorfahrengeist finden"}},{q="Warum muss zuerst der Rite of Vision abgeschlossen werden?",a="Der Rite of Vision reinigt Euren spirituellen Blick mit dem Wasser der Seher. Dadurch könnt Ihr die uralten Geister an den Teufelsfelsen wahrnehmen und ihren Segen empfangen.",al={"warum zuerst rite of vision","rite of vision voraussetzung","wasser der seher voraussetzung"}},{q="Was geschieht nach dem Abschluss des Ritus der Weisheit?",a="Nachdem Ihr die Anerkennung der Ahnen erlangt habt, werdet Ihr angewiesen, zu den hohen Erhebungen von Donnerfels zu reisen.",al={"was folgt nach dem ritus der weisheit","nächste quest nach dem ritus der weisheit"}},{q="Welche Kreaturen bedrohen das Gebiet der Teufelsfelsen?",a="Aggressive Palemane-Gnolle sind auf den heiligen Friedhof der Teufelsfelsen vorgedrungen. Sie lauern entlang der felsigen Pfade zur uralten Begräbnisstätte.",al={"feinde an den teufelsfelsen","was bewacht die teufelsfelsen","gnolle an den teufelsfelsen"}}},fx={["740e2883"]={q="Warum schickt Euch Seher Wiserunner auf die Rite of Wisdom?",a="Seher Wiserunner führt vielversprechende junge Tauren durch die traditionellen Rites of the Earthmother. Nachdem er gesehen hat, wie Ihr die durch das Wasser der Seher gewährte Vision überstanden habt, schickt er Euch zu den Teufelsfelsen, damit Ihr den Segen der Vorfahren empfangen könnt. Für Wiserunner und die Ältesten stellt dieses Ritual sicher, dass nur diejenigen, die spirituell vorbereitet und von den Vorfahren anerkannt sind, in Donnerfels als Beschützer des Stammes willkommen geheißen werden.",al={"motiv von seher wiserunner","warum rite of wisdom","warum schickt ihr mich zur rite of wisdom"}},["8728f84f"]={q="Warum müsst Ihr gehen, anstatt dass Seher Wiserunner selbst geht?",a="Die Rite of Wisdom ist eine persönliche Prüfung des Übergangs, keine Besorgung, die jemand anderes für Euch erledigen kann. Um unter den Ältesten Akzeptanz zu finden und das Recht zu erlangen, Donnerfels zu betreten, müsst Ihr persönlich den Vorfahrengeist an den Teufelsfelsen aufsuchen und die spirituelle Klarheit demonstrieren, die Ihr durch das Wasser der Seher gewonnen habt. Die Pflicht, die Stadt zu schützen, kann nur direkt Euch übertragen werden.",al={"warum ich zur rite of wisdom","warum geht seher wiserunner nicht selbst","warum muss ich den vorfahrengeist aufsuchen"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="Zukk'ash-Plage",s="In Camp Mojache vermutet Hadoken Swiftstrider, dass die Zukk'ash südlich der Gnolle diese in Raserei treiben. Er schickt Euch in die Gewundene Tiefe, um ihre Reihen zu lichten und mit zwanzig Chitinpanzern zurückzukehren.",h="In Camp Mojache vermutet Hadoken Swiftstrider, dass die Zukk'ash südlich der Gnolle diese in Raserei treiben.",kw={"camp mojache","chitinpanzer","feralas","gnolle","hadoken swiftstrider","insekten","die gewundene tiefe","zukk'ash"},sec={{t="Der Feind südlich der Gnolle",b="Hadoken Swiftstrider glaubt, dass südlich der Gnolle insektenartige Kreaturen leben. Ob sie denken können, spielt für ihn kaum eine Rolle. Wenn sie die Gnolle gegen Camp Mojache in Raserei treiben, bedrohen sie das Lager ebenso sehr wie die Gnolle selbst. Also betretet Ihr ihre Heimat, die Gewundene Tiefe, um ihre Reihen zu lichten. Bringt zwanzig Chitinpanzer der Zukk'ash als Beweis zurück und berichtet Hadoken, was Ihr vorfindet."},{t="Hadokens Urteil",b="Hadoken Swiftstrider ist erfreut, als Ihr zurückkehrt. Nur eine groß angelegte Invasion kann die Präsenz der Zukk'ash beenden, doch Eure Arbeit hat Camp Mojache Zeit verschafft, eine angemessene Strategie zu entwickeln. Das Lager wird die Chitinpanzer untersuchen und alles über diese Kreaturen in Erfahrung bringen, was es kann. Die Gefahr ist weit über das hinausgewachsen, was irgendjemand erwartet hatte."}},faq={{q="Wer schickt Euch gegen die Zukk'ash?",a="Hadoken Swiftstrider schickt Euch von Camp Mojache in Feralas aus los.",al={"questgeber","hadoken swiftstrider","wer startet zukk'ash-plage"}},{q="Was sind die Zukk'ash?",a="Hadoken glaubt, dass die Zukk'ash insektenartige Kreaturen südlich der Gnolle sind. Ob sie denken können, spielt für ihn kaum eine Rolle; er fürchtet, dass sie die Gnolle in Raserei treiben könnten.",al={"was sind zukkash","zukkash insekten","gewundene tiefe insekten"}},{q="Wo liegt die Gewundene Tiefe?",a="Die Gewundene Tiefe, die Heimat der Zukk'ash, liegt südlich der Gnolle.",al={"gewundene tiefe lage","wo liegt die gewundene tiefe","wo sind die insekten"}},{q="Warum will Hadoken Chitinpanzer der Zukk'ash?",a="Hadoken will die Chitinpanzer als Beweis für Eure Arbeit gegen die Zukk'ash.",al={"warum chitinpanzer","zukkash chitinpanzer verwendung","zweck der chitinpanzer"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="Zornstachel",s="In der Gewundenen Tiefe hat Hadoken Swiftstriders Späher ein Insekt entdeckt, das weit größer ist als die anderen.",h="In der Gewundenen Tiefe hat Hadoken Swiftstriders Späher ein Insekt entdeckt, das weit größer ist als die...",kw={"camp mojache","feralas","drüsen","hadoken swiftstrider","insekt","stinglasher","die gewundene tiefe","zukk'ash"},sec={{t="Ein Riese unter den Insekten",b="Ein Späher hat ein riesiges Insekt entdeckt, das durch das verworrene Gelände der Gewundenen Tiefe streift. Es scheint eine andere Aura als die übrigen Insekten auszustrahlen, und Hadoken Swiftstrider hat es Stinglasher genannt. Hadoken will, dass seine Sekretdrüsen direkt nach Camp Mojache gebracht werden. Durch die Untersuchung der Innereien des Insekts hofft Hadoken zu erfahren, wie sich dieser neuen Bedrohung begegnen lässt."},{t="Hadokens Dank",b="Hadoken Swiftstrider ist von Eurer Arbeit beeindruckt. Wenn Stinglasher zu den stärksten Insekten gehört, könnte sich seine Untersuchung als wertvoll erweisen. Hadoken muss das Lager lange genug verteidigen, um davon profitieren zu können. Als Dank des ganzen Lagers gibt Hadoken Euch eine Belohnung in Münzen."}},faq={{q="Wer schickt Euch hinter Stinglasher her?",a="Hadoken Swiftstrider in Camp Mojache in Feralas schickt Euch los, um Stinglasher zu jagen.",al={"questgeber","wer vergibt stinglasher","hadoken swiftstrider"}},{q="Wo ist Stinglasher zu finden?",a="Stinglasher streift durch das verworrene Gelände der Gewundenen Tiefe.",al={"stinglasher aufenthaltsort","wo ist stinglasher","aufenthaltsort der gewundenen tiefe"}},{q="Was unterscheidet Stinglasher von den anderen Insekten?",a="Ein Späher berichtet, dass Stinglasher weit größer ist als die anderen Insekten und eine Aura auszustrahlen scheint, die ihnen fehlt.",al={"warum stinglasher","was ist stinglasher","stinglasher aura"}},{q="Warum möchte Hadoken Stinglashers Drüsen?",a="Hadoken will Stinglashers Drüsen, damit seine Innereien untersucht werden können, während ein Plan gegen diese neue Bedrohung ausgearbeitet wird.",al={"warum drüsen sammeln","zweck von stinglashers drüsen"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="Bericht über die Zukk'ash",s="In Camp Mojache sagt Hadoken Swiftstrider, Eure Arbeit gegen die Zukk'ash sei doppelt erfolgreich gewesen, doch die Gefahr bleibt. Er bittet Euch, den Bericht des Lagers zu Zilzibin Drumlore in Orgrimmar zu bringen.",h="In Camp Mojache sagt Hadoken Swiftstrider, Eure Arbeit gegen die Zukk'ash sei doppelt erfolgreich gewesen...",kw={"camp mojache","gasse","feralas","hadoken swiftstrider","orgrimmar","silithiden","zilzibin drumlore","bericht über die zukk'ash"},sec={{t="Ein Dokument für die Gasse",b="Hadoken Swiftstrider hat ein Dokument darüber, was Camp Mojache über die Zukk'ash-Insekten erfahren hat. Sie bleiben eine Bedrohung, daher bittet er Euch, den Bericht nach Orgrimmar zu bringen. Zilzibin Drumlore lebt in der Gasse und kennt sich mit fremdartigen Kreaturen wie diesen aus. Hadoken hofft, dass die Erkenntnisse des Lagers nützlich sein werden."},{t="Das Urteil des Experten",b="Zilzibin Drumlore hat den Bericht bereits erwartet. Er nennt die Kreaturen, denen Ihr gegenüberstandet, eine uralte Bedrohung, die die Horde immer wieder bewusst ignoriert. Hadoken war weise, sowohl das Dokument als auch Euch zu schicken. Zilzibin bezeichnet die Zukk'ash als Silithiden. Manche tun sie als geistloses Ärgernis ab, doch er sagt, sie bedrohen die Horde mehr, als die Allianz es könnte."}},faq={{q="Wer schickt den Bericht nach Orgrimmar?",a="Hadoken Swiftstrider gibt Euch das Dokument in Camp Mojache in Feralas.",al={"wer gibt bericht über die zukk'ash","wer startet bericht über die zukk'ash","questgeber"}},{q="Wem wird der Bericht überbracht?",a="Ihr überbringt den Bericht Zilzibin Drumlore, der in der Gasse von Orgrimmar lebt.",al={"wohin geht der bericht","wer erhält bericht über die zukk'ash","drumlore standort"}},{q="Warum wird das Dokument nach Orgrimmar gebracht?",a="Hadoken hofft, dass Zilzibin Drumlore die Erkenntnisse des Lagers nutzen kann. Zilzibin ist ein Experte für fremdartige Kreaturen wie die Zukk'ash.",al={"warum nach orgrimmar schicken","zweck des berichts"}},{q="Was ging dieser Lieferung voraus?",a="Die Lieferung folgt auf Eure Bemühungen gegen die Zukk'ash-Insekten in Zukk'ash Infestation und Stinglasher.",al={"vorherige quests","voraussetzungen"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="Beste Qualität",s="Im Norden von Feralas sucht Pratt McGrubben zähere Yetihäute aus der Wutschrammfeste. Er bittet Euch, zehn zur Mondfederfeste zu bringen.",h="Im Norden von Feralas sucht Pratt McGrubben zähere Yetihäute aus der Wutschrammfeste.",kw={"mondfederfeste","feralas","beste qualität","pratt mcgrubben","wutschrammfeste","thorium","yetihaut","yetis"},sec={{t="Eine zähere Schar Yetis",b="Nach dem Zeichen der Qualität hat Pratt McGrubben feinere Häute gefunden. Eine zähere Schar Yetis lebt in der Wutschrammfeste im Norden von Feralas. Bringt Pratt zehn Häute zur Mondfederfeste, und er wird Euch fürstlich bezahlen. Wenn diese Häute den Feralnarbenhäuten ebenbürtig sind, könnten sie sich als so widerstandsfähig wie Thorium erweisen."},{t="Pratts Dank",b="Die Rage Scar-Häute sind besser, als Pratt McGrubben gehofft hatte. Er erkennt, dass sie nach dem fachgerechten Gerben noch viel härter werden. Zum Dank gibt er Euch eine seiner neuesten Schöpfungen."}},faq={{q="Wer bittet um die Häute der Rage Scar-Yetis?",a="Pratt McGrubben bittet Euch in der Mondfederfeste in Feralas um Häute der Rage Scar-Yetis.",al={"wer vergibt beste qualität","beste qualität questgeber","pratt mcgrubben"}},{q="Wo leben die Rage Scar-Yetis?",a="Die Rage Scar-Yetis leben in der Wutschrammfeste im Norden von Feralas.",al={"rage scar-yetis fundort","wo ist die wutschrammfeste","wo gibt es rage scar-häute"}},{q="Wie viele Häute werden gesucht?",a="Pratt McGrubben möchte zehn Häute der Rage Scar-Yetis.",al={"wie viele yetihäute","beste qualität benötigte gegenstände"}},{q="Was ging dem voraus?",a="Dies folgt auf Das Zeichen der Qualität, als Ihr Euch mit der ersten Schar Yetis befasst habt.",al={"vorausgesetzte quest","welche quest führt zu bester qualität","vorherige quest"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="Beste Qualität",s="In Camp Mojache sucht Jangdor Swiftstrider nun feinere Bälge von den zäheren Yetis in der Wutschrammfeste.",h="In Camp Mojache sucht Jangdor Swiftstrider nun feinere Bälge von den zäheren Yetis in der Wutschrammfeste.",kw={"camp mojache","feralas","beste qualität","jangdor swiftstrider","wutschrammfeste","rage scar-yeti","yetibälge"},sec={{t="Eine zähere Schar Yetis",b="Nach The Mark of Quality hat Jangdor Swiftstrider eine bessere Quelle für Bälge gefunden. Zähere Yetis streifen im Inneren der Wutschrammfeste im Norden von Feralas umher. Bringt zehn Bälge nach Camp Mojache, und Jangdor wird Euch fürstlich entlohnen. Wenn sie den Bälgen der Feral Scar ebenbürtig sind, könnten sie sich als so widerstandsfähig wie Thorium erweisen."},{t="Jangdors Dank",b="Jangdor Swiftstrider findet die Bälge besser als erhofft. Er erkennt, dass sie nach ordentlichem Gerben viel härter werden. Zum Dank überreicht er Euch eine seiner neuesten Schöpfungen."}},faq={{q="Wer bittet um die Bälge der Rage Scar-Yetis?",a="Jangdor Swiftstrider bittet in Camp Mojache in Feralas um zehn Bälge der Rage Scar-Yetis.",al={"wer vergibt beste qualität","beste qualität questgeber","jangdor swiftstrider"}},{q="Wo leben die Rage Scar-Yetis?",a="Die Rage Scar-Yetis leben im Inneren der Wutschrammfeste im Norden von Feralas.",al={"rage scar-yetis fundort","wo ist die wutschrammfeste","wo gibt es rage scar-bälge"}},{q="Wie viele Bälge werden gesucht?",a="Jangdor Swiftstrider möchte zehn Bälge der Rage Scar-Yetis.",al={"wie viele yetibälge","beste qualität benötigte gegenstände"}},{q="Was ging dem voraus?",a="Dies folgt auf The Mark of Quality, als Ihr Euch mit der ersten Schar Yetis befasst habt.",al={"vorausgesetzte quest","welche quest führt zu beste qualität","vorherige quest"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Makelloser Yetibalg",s="In Feralas könnte ein Balg von den Yetis von Rage Scar Pratt McGrubbens Aufmerksamkeit erregen. Er ist ungewöhnlich dick und zäh, und Pratt möchte Yetibälge kaufen.",h="In Feralas könnte ein Balg von den Yetis von Rage Scar Pratt McGrubbens Aufmerksamkeit erregen.",kw={"mondfederfeste","feralas","pratt mcgrubben","makelloser yetibalg","rage scar","yetibalg"},sec={{t="Ein außergewöhnlicher Balg",b="Unter den Bälgen von den Yetis von Rage Scar ist dieser ungewöhnlich dick und robust. Pratt McGrubben möchte in der Mondfederfeste in Feralas Yetibälge kaufen, also könnte ihn dieser Balg interessieren."},{t="Pratts Reaktion",b="Pratt ist von dem Balg verblüfft und fragt sich, ob irgendein Yetibalg noch großartiger sein könnte. Er bietet mehr, als ein einzelner Balg gewöhnlich einbringt, und glaubt, dass sich daraus etwas Besonderes herstellen lässt."}},faq={{q="Wer möchte den makellosen Yetibalg haben?",a="Pratt McGrubben möchte in der Mondfederfeste in Feralas Yetibälge kaufen.",al={"wer nimmt den makellosen yetibalg","wohin den yetibalg bringen","pratt mcgrubben yetibalg"}},{q="Was macht diesen Balg besonders?",a="Verglichen mit Bälgen von den Yetis von Rage Scar ist dieser ungewöhnlich dick und zäh.",al={"makelloser yetibalg herkunft","was macht den balg besonders","feralas yetibalg"}},{q="Wo ist Pratt McGrubben?",a="Pratt McGrubben ist in der Mondfederfeste in Feralas.",al={"wo ist pratt mcgrubben","wohin den makellosen yetibalg bringen"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="Nachschub an feurigem Fluxus: Königsblut",s="In der Sengenden Schlucht braucht Meisterschmied Burninate nach What the Flux? mehr Feurigen Fluxus. Er bittet Euch um Incendosaurierschuppen, Königsblut und Kohle und nimmt alles an, was Ihr anbieten könnt.",h="In der Sengenden Schlucht braucht Meisterschmied Burninate nach What the Flux?",kw={"burninate","kohle","feuriger fluxus","incendosaurier","königsblut","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate hat wenig Zeit zum Reden. Sein Feuriger Fluxus geht zur Neige, also bittet er Euch um zwei Incendosaurierschuppen, vier Königsblut und Kohle. Er nimmt alles an, was Ihr anbieten könnt."}},faq={{q="Wer bittet um diese Waren?",a="Meisterschmied Burninate bittet in der Sengenden Schlucht um die Waren und nimmt sie persönlich entgegen.",al={"wer gibt diese quest","burninate feuriger fluxus","wo abgeben"}},{q="Welche Materialien will Burninate?",a="Burninate will zwei Incendosaurierschuppen, vier Königsblut und Kohle.",al={"welche gegenstände werden benötigt","materialien für feurigen fluxus","gegenstände bei burninate abgeben"}},{q="Was ging dieser Bitte voraus?",a="What the Flux? ging dieser Bitte voraus, und Burninate gab Euch diese Quest.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum will Burninate diese Waren?",a="Burninate sagt, dass der Vorrat an Feurigem Fluxus schwindet, und will ihn wieder auffüllen lassen.",al={"warum feuriger fluxus","burninates beweggrund"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="Perfekter Yetibalg",s="In Camp Mojache kauft Jangdor Swiftstrider Yetibälge, und einer, den Ihr gefunden habt, könnte perfekt sein. Er ist dicker und zäher als die Bälge der Yetis von Rage Scar.",h="In Camp Mojache kauft Jangdor Swiftstrider Yetibälge, und einer, den Ihr gefunden habt, könnte perfekt sein.",kw={"camp mojache","feralas","jangdor swiftstrider","perfekter yetibalg","rage scar","yetibalg"},sec={{t="Ein Balg zum Vorzeigen",b="Der Balg fühlt sich dicker und robuster an als die Bälge der Yetis von Rage Scar. Jangdor Swiftstrider in Camp Mojache in Feralas kauft Yetibälge. Es lohnt sich, ihm diesen zu bringen."},{t="Jangdors Urteil",b="Jangdor Swiftstrider ist von dem Balg begeistert und nennt ihn den besten, den er je gesehen hat. Er bietet mehr, als er gewöhnlich für einen Balg bezahlt, und ist sicher, dass er daraus etwas Besonderes herstellen kann."}},faq={{q="Wer interessiert sich für den Perfekten Yetibalg?",a="Jangdor Swiftstrider in Camp Mojache in Feralas möchte Yetibälge kaufen.",al={"wer will den balg","wer gibt den perfekten yetibalg ab","jangdor yetibalg"}},{q="Warum gilt dieser Balg als etwas Besonderes?",a="Seine ungewöhnliche Dicke und Zähigkeit heben ihn von den Bälgen der Yetis von Rage Scar ab.",al={"warum ist er perfekt","was macht den balg besonders"}},{q="Wo ist Jangdor Swiftstrider?",a="Jangdor Swiftstrider ist in Camp Mojache in Feralas.",al={"wo ist jangdor swiftstrider","wohin den perfekten yetibalg bringen"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="Reise nach Donnerfels",s="Die Geister senden Euch nach den Rites of the Earthmother von Mulgore nach Donnerfels. Cairne Bluthuf, High Chieftain der Tauren, erwartet Euch dort.",h="Die Geister senden Euch nach den Rites of the Earthmother von Mulgore nach Donnerfels.",kw={"vorfahrengeist","cairne bluthuf","high rise","reise nach donnerfels","mulgore","rites of the earthmother","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde erlebt Ihr den gegenseitigen Respekt ihrer Völker, wenn die Tauren verbündete Völker willkommen heißen, die ihre heiligen Traditionen vollenden.",["race:Tauren"]="Als junger Tauren markiert Euer Erscheinen vor Cairne Bluthuf nach den Riten der Erdenmutter Euren Übergang ins Erwachsenenalter und bringt Euch Ehre im Stamm ein."},sec={{t="Ein vollendeter Übergangsritus",b="In ganz Mulgore prüfen die Rites of the Earthmother Eure Stärke, Weitsicht und Weisheit. Die Prüfungen führen über die Ebenen und durch die Ahnenstätten des Landes. Wenn der Vorfahrengeist Euren letzten Ritus anerkennt, habt Ihr Euch als würdig erwiesen, Donnerfels als Verteidiger des Volkes der Tauren zu betreten."},{t="Aufstieg zum High Rise",b="Vom heiligen Boden, auf dem Geister wandeln, führt Euer Weg hinauf nach Donnerfels. Die Stadt krönt rote Tafelberge, die durch Seilbrücken und gewaltige Holzaufzüge verbunden sind. Cairne Bluthuf, High Chieftain der Tauren, erwartet Euch auf dem High Rise, bereit, jene zu begrüßen, die dem Pfad der Ahnen gefolgt sind."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Ein Vorfahrengeist schickt Euch, nachdem Ihr den Rite of Wisdom vollendet habt, den letzten Schritt der traditionellen Rites of the Earthmother.",al={"wer vergibt die quest","vorfahrengeist quest","questgeber"}},{q="Wo finde ich Cairne Bluthuf?",a="Cairne Bluthuf erwartet Euch auf dem High Rise, dem zentralen Tafelberg von Donnerfels über den roten Hochebenen und den Ebenen.",al={"cairnes standort","wo ist cairne","anführer von donnerfels"}},{q="Welche Bedeutung hat der Abschluss dieser Quest?",a="Mit Eurer Ankunft bei Cairne schließt Ihr Eure ersten Abenteuer in Mulgore offiziell ab. Die Führung der Tauren erkennt Euch an, und Ihr seid bereit, überall in der Horde Aufgaben zu übernehmen.",al={"warum cairne besuchen","bedeutung der riten","bedeutung der reise nach donnerfels"}},{q="Treten nur Tauren diese Reise an?",a="Die Reise ist ein traditioneller Übergangsritus der Tauren. Jedes Mitglied der Horde, das durch die Rites of the Earthmother seine Hingabe beweist, erhält dieselbe Ehre und wird zum High Chieftain geschickt.",al={"können orcs das machen","wer kann die reise nach donnerfels antreten","völker"}},{q="Was geschieht nach dem Gespräch mit Cairne?",a="Cairne heißt Euch in seinem Heim willkommen und würdigt Eure Taten. Er weist Euch auf die größeren Konflikte hin, denen sich die Horde in ganz Kalimdor stellen muss.",al={"nächste quest","was kommt nach cairne","nach reise nach donnerfels"}},{q="Wie erreicht man den High Rise in Donnerfels?",a="Nehmt die großen mechanischen Aufzüge von den Ebenen unterhalb der Stadt hinauf zu den Tafelbergen. Überquert dann die Brücken aus Seilen und Holz zur zentralen Plattform des High Rise, wo die Behausung des Häuptlings steht.",al={"weg zum high rise","wie kommt man zu cairne","aufzüge von donnerfels"}}},fx={["74afb15b"]={q="Warum schickt Euch der Vorfahrengeist nach Donnerfels?",a="Indem Ihr die Prüfungen in ganz Mulgore überlebt und mit den Geistern kommuniziert habt, habt Ihr Eure Weisheit, Stärke und Hingabe durch die Rites of the Earthmother bewiesen. Der Vorfahrengeist schickt Euch nach Donnerfels, damit Eure Taten vom Volk der Tauren und ihrem höchsten Anführer, Cairne Bluthuf, anerkannt werden können. Vor dem Hochhäuptling zu stehen markiert Eure formelle Aufnahme in ihre Gesellschaft als geehrter Champion.",al={"warum schickt euch der vorfahrengeist","motiv des vorfahrengeists","warum zu cairne gehen"}},c86a41a9={q="Warum müsst Ihr die Nachricht selbst an Cairne Bluthuf überbringen?",a="Die Rites of the Earthmother sind eine heilige persönliche Prüfung. Der Vorfahrengeist ist ein jenseitiger Führer, der an die heiligen Stätten von Mulgore gebunden ist und nicht in der Lage oder gewillt ist, irdische Berichte zu überbringen. Da es Euer Geist und Eure Entschlossenheit waren, die getestet wurden, gebührt die Ehre, Euch selbst bei Hochhäuptling Cairne Bluthuf vorzustellen, allein Euch.",al={"warum ich zu cairne","warum muss ich cairne besuchen","warum muss ich cairne bluthuf sehen"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="Riten der Erdenmutter",s="Oberhäuptling Cairne Bluthuf schickt Euch durch Mulgore, um den großen Kodo Arra'chea aufzuspüren. Selbst nach den alten Riten verlangt er von seinem Volk, Stärke, Fährtenlesekunst und Hingabe erneut zu beweisen. Arra'cheas Horn zeigt Cairne, dass Ihr bereit seid, der Horde auch jenseits Eurer Heimat zu dienen.",h="Oberhäuptling Cairne Bluthuf schickt Euch durch Mulgore, um den großen Kodo Arra'chea aufzuspüren.",kw={"arra'chea","arrachea","bluthuf","cairne","erdenmutter","horn","jagd","kodo","mulgore","donnerfels"},ang={["class:Hunter"]="Als Jäger pirscht Ihr einem gewaltigen Einzelgänger nach, der durch die Goldenen Ebenen wandert. Die Fährtenmeister der Tauren geben diese uralte Jagdweise über Generationen hinweg weiter.",["faction:Horde"]="Als Mitglied der Horde helft Ihr durch das Erlegen Arra'cheas, Donnerfels mit Nahrung, Leder und Materialien zu versorgen. Die Jagd spiegelt den gemeinsamen Überlebenskampf wider, der die junge Horde trägt.",["race:Tauren"]="Als junger shu'halo steht Ihr vor Cairne Bluthuf, um ihm Arra'cheas Horn zu bringen. Der Ritus beweist, dass Euer Können Eure Ahnen und Mulg ores Herden ehrt."},sec={{t="Der Maßstab eines Häuptlings",b="In Donnerfels weicht die Kindheit eines jungen Tauren der Pflicht. Oberhäuptling Cairne Bluthuf fordert junge Jäger auf, sich weiterhin zu beweisen. Mit dem Erreichen der hohen Klippen beginnt ein Leben im Dienst der Vereinten Taurenstämme. Cairne verlangt mehr als eine Jagd auf kleines Ungeziefer: Er will einen Beweis jagdlichen Geschicks, erbracht durch das Aufspüren und saubere Erlegen einer der berühmten wandernden Bestien Mulg ores."},{t="Die Jagd auf Arra'chea",b="Arra'chea ist ein gewaltiger, legendärer Kodo, dessen Rundweg durch das goldene Gras nordöstlich von Donnerfels führt. Diese große Bestie zu erlegen, erfordert geduldiges Pirschen durch die offene Savanne, nicht allein rohe Gewalt. Bringt Arra'cheas Horn zur High Rise zurück, und Cairne schickt Kürschner und Sammler los, um jeden Teil der heiligen Bestie für die Versorgung der Stadt zu nutzen."}},faq={{q="Wer vergibt diese Quest?",a="Oberhäuptling Cairne Bluthuf erteilt Euch diesen Jagdauftrag von seinem Sitz auf der High Rise in Donnerfels aus.",al={"questgeber","wer vergibt riten der erdenmutter","cairne quest"}},{q="Was ist Arra'chea?",a="Arra'chea ist ein berühmter Kodo, der durch Mulg ores Ebenen streift. Sein großes Horn beweist die Fährtenlesekunst und das Kampfgeschick eines Jägers.",al={"wer ist arrachea","was ist arrachea","arrachea geschichte"}},{q="Wo kann ich Arra'chea finden?",a="Arra'chea zieht auf einem weiten Rundweg nordöstlich der Klippen von Donnerfels umher und umrundet die offenen Ebenen im Uhrzeigersinn.",al={"wo ist arrachea","arrachea aufenthaltsort","arrachea route"}},{q="Warum verlangt Cairne diese Jagd, obwohl ich die früheren Riten bereits abgeschlossen habe?",a="Für die Tauren ist es nur der Beginn ihrer Pflicht, sich einen ersten Platz zu verdienen. Cairne fordert Euch auf, Eure Stärke, Demut und Jagdkunst weiterhin für den Stamm unter Beweis zu stellen.",al={"warum diese quest machen","warum arrachea töten","sinn der riten"}},{q="Was geschieht mit Arra'cheas Körper, nachdem das Horn genommen wurde?",a="Cairne schickt einen Sammeltrupp los, um Arra'cheas Fleisch und Haut zu bergen. Die erlegte Beute nährt und kleidet Donnerfels, denn die Tradition der Tauren lehrt sie, ihre Beute zu ehren.",al={"arrachea fleisch","was geschieht mit dem kodo","kadaver geschichte"}},{q="Ist dies dieselbe Quest wie die frühen Einführungsriten?",a="Nein. Die frühen Prüfungen in Camp Narache lehren einen Initianten die grundlegenden Riten der Erdenmutter. Mit dieser Jagd in Donnerfels prüft Cairne persönlich, ob Ihr Euch als Jäger weiterhin als würdig erweist.",al={"riten der erdenmutter unterschiede","welche ritenquest","camp narache riten"}}},fx={d7a516d7={q="Wozu dient das Horn von Arra'chea?",a="Das Horn dient als physischer Beweis Eurer erfolgreichen Jagd. Die Tradition der Tauren legt großen Wert auf die Fähigkeiten, mächtige Bestien aufzuspüren und zu erlegen, und das direkte Überreichen von Arra'cheas Horn an Hochhäuptling Cairne Bluthuf beweist, dass Ihr über die nötigen Fähigkeiten verfügt, um für Euer Volk zu sorgen und es zu beschützen.",al={"gebrauch des horns von arra'chea","warum das horn von arra'chea nehmen","zweck des horns von arra'chea"}},a7e696eb={q="Warum schickt Cairne Bluthuf Euch und nicht die Stadtwachen?",a="Diese Jagd ist keine Aufgabe der Verteidigung oder des einfachen Ressourcensammelns – es ist eine traditionelle Prüfung. Obwohl Ihr die anfänglichen Rites of the Earthmother bestanden haben mögt, um Donnerfels zu erreichen, erwartet Cairne von jedem Jäger des Stammes, dass er seinen Wert und seine Eigenständigkeit kontinuierlich durch große Taten beweist, anstatt sich auf vergangenen Leistungen auszuruhen.",al={"warum schickt ihr mich","warum keine wachen für arra'chea schicken","warum braucht cairne mich"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="Das wird schwierig",s="Lucien Tosselwrench wartet in Deckung, während Ihr Zahnrad Nummer fünf zu Lotwil Veriatus bringt.",h="Lucien Tosselwrench wartet in Deckung, während Ihr Zahnrad Nummer fünf zu Lotwil Veriatus bringt.",kw={"ödland","zahnrad fünf","lotwil veriatus","lucien tosselwrench","fesseln","das wird schwierig"},sec={{t="In Deckung",b="Lucien Tosselwrench gibt Euch das Zahnrad für Lotwil Veriatus. Dann wartet er in Deckung und lädt Euch ein, Euch ihm anzuschließen. Lotwil ist noch immer über die Fesseln gebeugt, als Ihr ankommt. Ohne aufzusehen, streckt er die Hand aus und wackelt mit den Fingern, um das Zahnrad zu verlangen."},{t="Geschichte schreiben",b="Lotwil nimmt das Zahnrad und nennt es perfekt. Er fordert Euch auf, zurückzutreten, während er sich anschickt, erneut Geschichte zu schreiben. Dann arbeitet er fieberhaft weiter."}},faq={{q="Wer übergibt das Zahnrad für Lotwil?",a="Lucien Tosselwrench gibt Euch Zahnrad Nummer fünf, damit Ihr es zu Lotwil Veriatus bringt.",al={"wer gibt das zahnrad","wo gibt es zahnrad fünf","lucien zahnrad"}},{q="Wohin geht Lucien?",a="Lucien geht in Deckung und lädt Euch ein, Euch ihm anzuschließen.",al={"warum versteckt sich lucien","lucien deckung"}},{q="Was macht Lotwil, als Ihr das Zahnrad bringt?",a="Lotwil arbeitet an einem Satz Fesseln. Ohne aufzusehen, streckt er die Hand aus und wackelt ungeduldig mit den Fingern, um das Zahnrad zu verlangen.",al={"was macht lotwil","lotwil fesseln","lotwil fortschritt"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="Das wird schwierig",s="Im Ödland ist Lotwil Veriatus bereit, einen mächtigen Elementar zu beschwören.",h="Im Ödland ist Lotwil Veriatus bereit, einen mächtigen Elementar zu beschwören.",kw={"ödland","elementar","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},sec={{t="Ein bahnbrechender Tag",b="Lotwil ruft aus, dass die Fesseln fertig sind. Die Zeit ist gekommen. Er bittet Lucien und Servo, zusammen mit Euch der Beschwörung beizuwohnen. Alchemie, Ingenieurskunst und das Arkane vereinen sich in den Fesseln, und Lotwil erwartet, dass an diesem bahnbrechenden Tag ein mächtiger Elementar seinem Ruf folgt."},{t="Nach der Beschwörung",b="Die Beschwörung endet anders, als Lotwil erwartet hat. Nachdem Ihr den Fam'retor Guardian besiegt habt, bittet Lotwil Euch, die Shackles of Elemental Binding zurückzubringen. Er kann nicht sagen, was schiefgelaufen ist. Dennoch ist er froh, dass die Magie bereitstand, um die Kreatur auf ihre eigene Ebene zurückzuschicken."}},faq={{q="Wer ist Lotwil Veriatus?",a="Lotwil Veriatus erschuf die Shackles of Elemental Binding, indem er Alchemie, Ingenieurskunst und das Arkane vereinte. Lucien und Servo sind bei ihm im Ödland.",al={"wer ist lotwil","lotwil veriatus"}},{q="Was sind die Shackles of Elemental Binding?",a="Die Shackles of Elemental Binding vereinen Alchemie, Ingenieurskunst und das Arkane. Lotwil hat sie gerade für den mächtigen Elementar fertiggestellt, den er beschwören will.",al={"was sind die fesseln","shackles of elemental binding"}},{q="Wen ruft Lotwil als Zeugen herbei?",a="Lotwil ruft Lucien und Servo herbei, damit sie zusammen mit Euch der Beschwörung beiwohnen.",al={"wer ist lucien","wer ist servo"}},{q="Was geschieht vor diesem Schritt?",a="Zuvor habt Ihr Lotwil Zahnrad Nummer fünf gebracht.",al={"vorherige quest","was führte dazu"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="Der Herrscher des Schwarzfels",s="Nefarians abgetrennter Kopf erreicht nach seiner Niederlage im Pechschwingenhort die Burg Sturmwind. Hochlord Bolvar Fordragon nimmt ihn als Beweis entgegen, dass der Herr des Schwarzfels gefallen ist. Der Sieg zählt zu den größten militärischen Triumphen der Allianz in jüngster Zeit.",h="Nefarians abgetrennter Kopf erreicht nach seiner Niederlage im Pechschwingenhort die Burg Sturmwind.",kw={"der schwarzfels","pechschwingenhort","hochlord bolvar fordragon","kopf von nefarian","der herrscher des schwarzfels","nefarian","burg sturmwind"},ang={["faction:Alliance"]="Für die Allianz ist die Übergabe von Nefarians Kopf eine krönende militärische Leistung. Sie zerschlägt die Pläne des Drachenschwarms gegen die Menschenlande.",["race:Human"]="Als Mensch wisst Ihr, dass vom Schwarzfels unzählige Einfälle und Intrigen gegen Sturmwind ausgegangen sind. Die Niederlage seines Herrn bringt dem Reich lang ersehnte Vergeltung und Erleichterung."},sec={{t="Ein Denkmal des Sieges",b="Nefarian, Brutmeister des Schwarzen Drachenschwarms und Herrscher der Oberen Schwarzfelsspitze, bedroht seit Langem die umliegenden Menschenkönigreiche. Seine Niederlage beendet seine verdrehten Experimente und Intrigen. Sein kampfgezeichneter Kopf wird nach Sturmwind zurückgebracht, als Beweis dafür, dass die größten Helden der Allianz den Herrscher des Schwarzfels bezwungen haben."},{t="Audienz in Burg Sturmwind",b="Hochlord Bolvar Fordragon regiert das Königreich vom Thronsaal der Burg Sturmwind aus. Der abgetrennte Kopf des Drachen erschüttert den königlichen Hof und flößt Ehrfurcht ein. Das Königreich kämpft mit inneren politischen Zwistigkeiten und Bedrohungen von außen. Dieser Sieg hebt die Moral und sichert sich einen Platz in der Geschichte der Allianz."}},faq={{q="Worum geht es in der Quest „Der Herrscher des Schwarzfels“?",a="Ihr erbeutet Nefarians abgetrennten Kopf im Pechschwingenhort und bringt ihn nach Sturmwind. Dort überreicht Ihr die Trophäe im Namen des Königreichs an Hochlord Bolvar Fordragon.",al={"der herrscher des schwarzfels quest","nefarian kopf quest allianz","kopf von nefarian sturmwind"}},{q="Wer ist Nefarian?",a="Nefarian ist ein mächtiger schwarzer Drache und der Sohn von Deathwing. Er herrscht vom Pechschwingenhort im Schwarzfels aus, befehligt die Schwarzfelsorcs und führt finstere Experimente durch, um den chromatic dragonflight zu erschaffen.",al={"wer ist nefarian","der herrscher des schwarzfels","nefarian geschichte"}},{q="Wer ist Hochlord Bolvar Fordragon?",a="Hochlord Bolvar Fordragon ist der Paladin, der während der Abwesenheit von König Varian Wrynn als Regent über Sturmwind herrscht. Er hält im Thronsaal der Burg Sturmwind Hof und wacht über den jungen Prinzen Anduin Wrynn.",al={"bolvar fordragon","wer ist bolvar","hochlord bolvar"}},{q="Warum wird diese Trophäe zur Burg Sturmwind gebracht?",a="Nefarians Herrschaft im Schwarzfels bedroht Sturmwind und den gesamten südlichen Kontinent. Seinen Kopf zur militärischen Führung des Königreichs zu bringen, bestätigt seine Niederlage und gibt dem Reich einen Sieg, der es eint.",al={"warum sturmwind","warum kopf zur burg bringen","warum bolvar"}},{q="Was geschieht nach der Übergabe des Kopfes an Bolvar?",a="Hochlord Bolvar Fordragon ist verblüfft und verkündet, dass der Triumph in die Geschichte eingehen wird. Der Kopf wird anschließend öffentlich aufgestellt, damit ganz Sturmwind ihn sehen kann.",al={"was geschieht danach","der herrscher des schwarzfels teil zwei","nefarian kopf abgeben"}},{q="Wirkt sich die Abgabe dieses Kopfes auf die ganze Stadt aus?",a="Ja. Nefarians Kopf wird in die Hauptstadt gebracht und über den Stadttoren aufgerichtet. Er verkündet Bürgern und Soldaten den Tod des Drachen und stärkt die Entschlossenheit der Verteidiger Sturmwinds.",al={"stadt stärkungszauber","schlachtruf","kopf von nefarian stärkungszauber"}}},fx={["150c64a2"]={q="Warum ist es wichtig, den Kopf von Nefarian nach Sturmwind zu bringen?",a="Nefarian war der schwarze Drache, der die Bedrohungen aus der Schwarzfelsspitze orchestrierte, sterbliche Königreiche manipulierte und direkt vor Sturmwinds Haustür monströse Armeen erschuf. Die Ablieferung seines abgetrennten Kopfes an Hochlord Bolvar Fordragon ist der unwiderlegbare Beweis dafür, dass der Schrecken der Brut gebrochen ist, was der Allianz einen monumentalen Sieg beschert, der gefeiert und dem gesamten Reich präsentiert werden kann.",al={"warum kopf von nefarian nach sturmwind bringen","motiv kopf von nefarian","warum nefarian-kopf abliefern"}},["7e2ee731"]={q="Warum müsst Ihr den Kopf nach Sturmwind bringen und nicht die königlichen Wachen?",a="Ihr und Eure Gefährten habt Euch durch den Pechschwingenhort gekämpft und den Drachenfürsten höchstpersönlich erschlagen. Diese grausige Trophäe in die Burg Sturmwind zu tragen, ist Euer Recht als die Champions, die ihn besiegt haben. So stellt Ihr sicher, dass Hochlord Bolvar Fordragon die Nachricht aus erster Hand von den Helden erhält, die das Biest tatsächlich zur Strecke gebracht haben.",al={"warum muss ich nefarians kopf abliefern","warum nicht königliche wachen nefarian-kopf","warum ich nefarian-trophäe"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="Der Herrscher des Schwarzfels",s="An Sturmwinds Toren versammelt sich die Allianz, um ihren Sieg über Blackrock zu ehren. Nachdem Ihr Grand Admiral Jes-Tereth in Burg Sturmwind Bericht erstattet habt, ziehen die Helden zum Tal der Helden. Feldmarschall Steinsteg steht bereit, die öffentliche Gedenkfeier der Stadt zu leiten.",h="An Sturmwinds Toren versammelt sich die Allianz, um ihren Sieg über Blackrock zu ehren.",kw={"blackrock","drachentöter","nefarian","rallying cry","steinsteg","sturmwind","das tal der helden"},ang={["class:Warrior"]="Der Rallying Cry of the Dragonslayer verleiht Kämpfern Kraft, die ausziehen, um das Reich zu verteidigen.",["faction:Alliance"]="Nefarians Kopf im Tal der Helden vereint die Völker der Allianz. Bürger aus Eisenschmiede, Darnassus und Gnomeregan sehen, dass die dunklen Mächte, die die Östlichen Königreiche heimsuchen, gebrochen werden können.",["race:Human"]="Für das Königreich Sturmwind beseitigt der Sieg über Blackrocks Gebieter eine ernste Bedrohung durch Drachen an seiner Nordgrenze."},sec={{t="Der Triumph einer Stadt",b="Der Feldzug gegen den Schwarzfelsklan und die Brut des Schwarzen Drachenschwarms findet seinen öffentlichen Abschluss. Nefarians abgetrennter Kopf wird in Burg Sturmwind präsentiert. Dann schickt Hochlord Bolvar Fordragon die Champions quer durch die Stadt zum Tal der Helden. Feldmarschall Steinsteg wartet dort, um die Trophäe entgegenzunehmen und die Feierlichkeiten einzuleiten."},{t="Die Allianz mobilisieren",b="Feldmarschall Steinsteg hisst Nefarians abgetrennten Kopf über den großen Bögen an Sturmwinds Haupteingang. Der Anblick ist in der ganzen Stadt zu sehen, und der Rallying Cry of the Dragonslayer begeistert Verteidiger, angereiste Würdenträger und Bürger. Sie wissen, dass Deathwings Brut einen vernichtenden Schlag erlitten hat."}},faq={{q="Was geschieht, wenn Ihr diese Quest abschließt?",a="Feldmarschall Steinsteg hängt Nefarians abgetrennten Kopf hoch an den steinernen Torbogen im Tal der Helden. Dann stärkt der Rallying Cry of the Dragonslayer verbündete Kämpfer und Wachen in ganz Sturmwind.",al={"nefarians kopf quest abgeben","was macht steinsteg","rallying cry auslösen"}},{q="Wer ist Feldmarschall Steinsteg?",a="Feldmarschall Steinsteg ist eine ranghohe Offizierin in Sturmwinds Armee, die im Tal der Helden nahe dem Stadteingang stationiert ist. Sie organisiert öffentliche Gedenkfeiern für militärische Siege, darunter die Zurschaustellung der Köpfe besiegter Drachenfeinde.",al={"steinsteg","feldmarschall steinsteg"}},{q="Warum schickt Hochlord Bolvar Fordragon Euch hierher?",a="Nachdem Hochlord Bolvar Fordragon im Thronsaal von Nefarians Niederlage erfahren hat, schickt er Euch zu den Stadttoren. Dort kann das Militär der Allianz den Sieg öffentlich zur Schau stellen und die Moral in der gesamten Hauptstadt heben.",al={"bolvar","warum zum tal der helden"}},{q="Wirkt sich diese Questabgabe auf die ganze Stadt aus?",a="Ja. Wenn Steinsteg die Trophäe entgegennimmt, erschallt eine Verkündung durch Sturmwind, und der Rallying Cry of the Dragonslayer erreicht alle innerhalb der Stadtgrenzen.",al={"weltbuff nefarian","erhält sturmwind einen buff"}},{q="Wo liegt das Tal der Helden?",a="Das Tal der Helden ist der prächtige Dammweg, der nach Sturmwind führt. Hoch aufragende Statuen säumen ihn und ehren die Helden des Zweiten Krieges, die das Dunkle Portal betraten.",al={"tal der helden lage","wo ist steinsteg"}},{q="Wer war der „Herrscher des Schwarzfels“?",a="Der schwarze Drache Nefarian war der Herrscher des Schwarzfels. Er ist Deathwings Sohn und herrscht über die oberen Spitzen des Schwarzfels.",al={"wer ist der herrscher des schwarzfels","nefarians identität"}}},fx={["3a42f3f3"]={q="Warum schickt Bolvar Euch, anstatt selbst zu gehen?",a="Ihr und Eure Gefährten wart die Champions, die den Höhen des Pechschwingenhorts getrotzt und Nefarian besiegt haben. Als Sieger gebührt Euch die Ehre, den abgetrennten Kopf des Drachen der militärischen Führung von Sturmwind zu präsentieren und den stadtweiten Triumph auszulösen.",al={"warum schickt ihr mich","warum nicht bolvar","warum muss ich den kopf überbringen"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="Der Herrscher des Schwarzfels",s="In Orgrimmar wird Nefarians abgetrennter Kopf Thrall als Beweis des Sieges vorgelegt. Seine Ankunft besiegelt den Fall eines großen Feindes der Horde.",h="In Orgrimmar wird Nefarians abgetrennter Kopf Thrall als Beweis des Sieges vorgelegt.",kw={"schwarzfels","pechschwingenhort","deathwing","drachentöter","thrall","nefarian","orgrimmar","rallying cry"},ang={["class:Warrior"]="Als Krieger erlangt Ihr großen Kriegsruhm, indem Ihr den gewaltigen abgetrennten Schädel eines Drachenfürsten zum Kriegshäuptling tragt.",["faction:Horde"]="Nefarians Fall stellt die Ehre der Horde wieder her und befreit die Schwarzfelsregion von dem Drachen, der die abtrünnige Dunkle Horde versklavte.",["race:Orc"]="Als Orc übt Ihr Vergeltung an der Bestie, die Rend Schwarzfaust lenkte und Orcclans für ihre Experimente versklavte, wenn Ihr Thrall Nefarians Kopf überreicht."},sec={{t="Eine Trophäe des Untergangs",b="Nefarian ist endlich gefallen. Er war der Drahtzieher im Pechschwingenhort und führte die schwarze Drachenbrut in den Östlichen Königreichen an. Sein von Kämpfen gezeichneter Kopf beweist seinen Tod. Für Krieger der Horde bringt es große Ehre, diese Beute von den brennenden Höhen des Schwarzfels über das große Meer nach Durotar zu tragen."},{t="Das Urteil des Kriegshäuptlings",b="Die Trophäe wird Kriegshäuptling Thrall vorgelegt, der die Verderbnis des Schwarzfels gut kennt. Er befreite sein Volk aus den Internierungslagern und führte es fort vom dämonischen Blutrausch der alten Horde. Nun ist der Sohn von Deathwing gefallen, und die Schwarzfelsorcs sind frei von der grausamen Herrschaft des dunklen Drachen."},{t="Schatten des Vaters",b="Nefarians Tod beendet die entarteten Experimente des Schwarzen Drachenschwarms, doch die Gefahr bleibt. Als Thrall den abgetrennten Kopf sieht, sagt er, Deathwing rege sich gewiss bei der Nachricht von der Vernichtung seines Sohnes. Der Sieg ist wahrhaftig errungen, doch größere Schrecken schlafen noch unter der Welt."}},faq={{q="Wer ist Nefarian?",a="Nefarian ist ein großer schwarzer Drache und der Sohn von Deathwing. In seinem Hort auf dem Gipfel des Schwarzfels führte er entartete Experimente durch, um den chromatic dragonflight zu erschaffen. Er manipulierte auch sterbliche Völker, insbesondere die Dunkle Horde, damit sie seinen Willen ausführten.",al={"nefarians hintergrundgeschichte","wer ist nefarian","schwarzer drachenfürst"}},{q="Warum wird die Trophäe Thrall überbracht?",a="Thrall ist der Kriegshäuptling der Horde. Er führte die Orcs aus den Internierungslagern und fort vom dämonischen Blutrausch der alten Horde. Der Beweis für den Fall des Drachen, der die Schwarzfelsorcs und die Dunkle Horde versklavte, gehört in seine Hände.",al={"warum thrall","wer erhält den kopf"}},{q="Was geschieht in Orgrimmar, wenn der Kopf abgegeben wird?",a="Wenn Nefarians Kopf zurückgebracht und in Orgrimmar zur Schau gestellt wird, feiert die Stadt. Mitglieder der Horde in der Nähe erhalten Rallying Cry of the Dragonslayer, was ihre Kampfkraft steigert.",al={"kopf-stärkungszauber","orgrimmar-weltstärkungszauber","rallying cry-stärkungszauber"}},{q="Hat diese Quest ein Gegenstück bei der Allianz?",a="Ja. Helden der Allianz bringen Nefarians Kopf zu Hochlord Bolvar Fordragon in Burg Sturmwind und gewähren ihrer Stadt damit denselben Segen.",al={"allianzversion","allianzgegenstück"}},{q="Warum gibt Deathwing Anlass zur Sorge?",a="Deathwing ist Nefarians Vater und der Patriarch des Schwarzen Drachenschwarms. Der Sieg über seinen Sohn beseitigt nicht die Gefahr, die vom Drachenvater ausgeht.",al={"der böse regt sich","wer ist der böse"}},{q="Woher stammt der Kopf?",a="Der Kopf von Nefarian stammt von Nefarians Leichnam auf dem Gipfel des Pechschwingenhorts, nachdem er besiegt wurde.",al={"wie erhält man den kopf von nefarian","queststartgegenstand"}}},fx={d14146dc={q="Warum muss der Kopf von Nefarian nach Orgrimmar gebracht werden?",a="Das gewaltige, von Kämpfen gezeichnete Haupt des gefallenen Drachen zu bergen, liefert den unbestreitbaren Beweis, dass der Meister der Schwarzfelsspitze besiegt wurde. Eine solch monströse Trophäe zurück nach Orgrimmar zu bringen, demonstriert die überlegene Macht der Horde, feiert einen monumentalen Sieg über den Schwarzen Drachenschwarm und ermöglicht es dem Rat des Kriegshäuptlings zu bestätigen, dass Nefarians verdrehte Experimente im Berg endlich ein Ende gefunden haben.",al={"warum den kopf von nefarian bringen","motiv für kopf von nefarian","warum kopf an etrigg geben"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="Der Herrscher des Schwarzfels",s="Vor der Horde in Orgrimmar zeugt Nefarians abgetrennter Kopf von seiner Niederlage. Thrall bestätigt den Tod des schwarzen Drachen und schickt Euch dann zu Hochfürst Saurfang ins Tal der Stärke, um allen die Trophäe zu zeigen.",h="Vor der Horde in Orgrimmar zeugt Nefarians abgetrennter Kopf von seiner Niederlage.",kw={"pechschwingenhort","thrall","kopf von nefarian","saurfang","orgrimmar","nefarian","tal der stärke"},ang={["faction:Horde"]="Für die Horde beweist die öffentliche Zurschaustellung Nefarians die Macht der erneuerten Horde gegen den schwarzen Drachen, der die Orcs des Schwarzfels manipulierte. Sie stärkt Thralls neue Ordnung.",["race:Orc"]="Als Orc empfindet Ihr vielleicht tiefe Erleichterung über den Fall des Drachen, der den Schwarzfelsklan unter seinem Joch hielt. Seine Niederlage nimmt einen Schatten der Schande von Eurem Volk."},sec={{t="Eine Trophäe für die Horde",b="Nefarians Kopf gelangt nach Orgrimmar, nachdem der schwarze Drache auf dem Pechschwingenhort gefallen ist. Kriegshäuptling Thrall bestätigt, dass Deathwings Sohn tot ist, und schickt Euch dann zu Hochfürst Saurfang ins Tal der Stärke. Dort werden die Überreste so hergerichtet, dass alle sie sehen können. Die Trophäe warnt die Feinde der Horde und schart die wahre Horde zusammen."},{t="Das Erbe beanspruchen",b="Nefarian herrschte über die Höhen des Schwarzfels und unterwarf die Schwarzfelsorcs und die Dunkle Horde seinem Willen. Indem Thralls Horde ihn niederstreckt und seinen Kopf im Tal der Stärke emporhebt, versetzt sie dem Schwarzen Drachenschwarm einen mächtigen Schlag. Saurfang ruft ganz Orgrimmar dazu auf, im Rallying Cry of the Dragonslayer zu jubeln."}},faq={{q="Welchen Zweck hat diese Quest?",a="Nachdem Ihr Thrall Nefarians Tod bewiesen habt, meldet Ihr Euch bei Hochfürst Saurfang im Tal der Stärke von Orgrimmar. Der abgetrennte Kopf wird öffentlich zur Schau gestellt, und Ihr werdet geehrt.",al={"was bewirkt diese quest","der herrscher des schwarzfels abgeben","warum zu saurfang gehen"}},{q="Wer ist Hochfürst Saurfang?",a="Hochfürst Saurfang ist ein erfahrener Orckrieger und einer der größten Streiter der Horde. Er ist im Tal der Stärke von Orgrimmar stationiert, wo er den Kopf entgegennimmt und für alle sichtbar aufstellen lässt.",al={"wer ist saurfang","rolle von hochfürst saurfang"}},{q="Warum wird Nefarians Kopf zur Schau gestellt?",a="Nefarians aufgestellter Kopf beweist, dass der Herr des Schwarzfels gefallen ist. Sein Anblick stärkt die Moral der Verteidiger Orgrimmars, und alle in der Stadt erhalten den Rallying Cry of the Dragonslayer.",al={"warum nefarians kopf aufstellen","nefarians kopf zurschaustellung orgrimmar"}},{q="Wer war Nefarian?",a="Nefarian war ein großer schwarzer Drache und ein Sohn von Deathwing. Vom Pechschwingenhort auf dem Schwarzfels aus befehligte er die Schwarzfelsorcs und die Dunkle Horde und züchtete die chromatic dragonflight.",al={"wer war nefarian","nefarians geschichte"}},{q="Wo befindet sich Hochfürst Saurfang?",a="Saurfang befindet sich im Tal der Stärke, dem zentralen Eingangsviertel von Orgrimmar.",al={"wo ist saurfang","saurfang standort"}},{q="Welche Rolle spielt Thrall dabei?",a="Kriegshäuptling Thrall nimmt Nefarians Kopf als Erster entgegen. Nachdem er den Tod des Drachen bestätigt hat, schickt er Euch zu Saurfang, damit die Trophäe offiziell aufgestellt wird.",al={"warum thrall","thralls beteiligung"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="Spendet Wolle",s="In Darnassus wird Wollstoff gesammelt, um die Vorräte der Stadt aufzustocken. Eure sechzig Stück bringen Euch Anerkennung für Eure Großzügigkeit ein.",h="In Darnassus wird Wollstoff gesammelt, um die Vorräte der Stadt aufzustocken.",kw={"darnassus","spende","anerkennung","vorräte","wolle","wollstoff"},sec={{t="Wollvorräte",b="Darnassus benötigt sechzig Stück Wollstoff von Euch. Den Rest der Vorräte sollen andere im Reich beisteuern. Eure Spende bringt Euch volle Anerkennung für Eure Großzügigkeit ein."}},faq={{q="Was benötigt Darnassus?",a="Darnassus benötigt Wollstoff, um seine Vorräte aufzustocken.",al={"wollspende","welchen stoff will darnassus"}},{q="Wie viel Wolle muss ich spenden?",a="Ihr müsst sechzig Stück Wollstoff spenden.",al={"wie viel wolle","sechzig wolle"}},{q="Warum sammelt Darnassus Wolle?",a="Darnassus sammelt Wollstoff, um seine Vorräte aufzustocken.",al={"warum wolle","wollsammelaktion"}},{q="Was bekomme ich für eine Wollspende?",a="Eure Spende von sechzig Stück bringt Euch die volle Anerkennung von Darnassus für Eure Großzügigkeit ein.",al={"wollspende anerkennung","wolle spenden belohnung"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="Die Legende von Stalvan",s="Marschall Haggard schickt Euch zu Schankwart Smitts, der vielleicht die Handschrift auf einer Seite aus Stalvans Tagebuch kennt.",h="Marschall Haggard schickt Euch zu Schankwart Smitts, der vielleicht die Handschrift auf einer Seite aus...",kw={"dunkelhain","dämmerwald","elwynn","tagebuch","marshal haggard","dunstmantel","scarlet raven tavern","stalvan","schankwart smitts"},ang={["faction:Alliance"]="Als Verteidiger der Allianz seht Ihr die Bande zwischen ehemaligen Soldaten der Sturmwindwache und Hütern örtlicher Geschichte im ganzen Königreich Sturmwind.",["race:Human"]="Als Mensch seht Ihr, wie Tragödien in Elwynn und Dunkelhain in der Erinnerung der Siedlungen weiterleben."},sec={{t="Eine Spur vom Marshal",b="Marschall Haggard kann die verblasste Schrift auf der zerrissenen Tagebuchseite nicht lesen, die Ihr aus seiner Truhe im Wald von Elwynn geborgen habt. Sein schwindendes Augenlicht lässt ihn die Worte nicht mehr erkennen. Er erinnert sich an seinen Dienst bei der Sturmwindwache und an Abende in der Scarlet Raven Tavern in Dunkelhain. Also schickt er Euch über den Fluss zu Schankwart Smitts, den seine Jahre hinter der Theke zu einem Hüter örtlicher Geschichte und Gerüchte gemacht haben."},{t="Rückkehr zur Scarlet Raven",b="Ihr durchquert die düsteren Wälder des Dämmerwalds und zeigt Smitts hinter der Theke die verblasste Seite. Er freut sich, von seinem alten Bekannten Haggard zu hören, auch wenn ihn die schwindende Gesundheit des Veteranen betrübt. Dann sieht Smitts das Pergament, und seine gelassene Art weicht Bestürzung. Er erkennt die unverwechselbare Handschrift ohne jeden Zweifel und bringt die Suche damit der Wahrheit über Stalvans Wahnsinn näher."}},faq={{q="Warum schickt Marschall Haggard mich zurück nach Dunkelhain?",a="Marschall Haggard ist alt und beinahe blind, weshalb er die geborgene Tagebuchseite nicht untersuchen kann. Aus seiner Zeit bei der Sturmwindwache erinnert er sich an Schankwart Smitts als Hüter örtlicher Überlieferungen und schickt Euch zu ihm, um nach der Schrift zu fragen.",al={"warum nach dunkelhain","haggard nach dunkelhain","warum smitts"}},{q="Wo befindet sich Schankwart Smitts?",a="Schankwart Smitts steht hinter der Theke in der Scarlet Raven Tavern im Osten von Dunkelhain im Dämmerwald.",al={"wo ist smitts","smitts standort","scarlet raven tavern standort"}},{q="Welchen Gegenstand bringt Ihr zu Schankwart Smitts?",a="Ihr bringt eine verblasste Tagebuchseite, einen Auszug aus Stalvan Dunstmantels verschollenem Tagebuch, der sicher verwahrt in Marshal Haggards Fußtruhe lag.",al={"welcher gegenstand","eine verblasste tagebuchseite","stalvan tagebuchseite"}},{q="Erkennt Schankwart Smitts die Handschrift?",a="Ja. Smitts erkennt die Handschrift, sobald er die verblasste Seite sieht, und seine Bestürzung liefert die nächste Spur bei der Suche nach Stalvan.",al={"kennt smitts die schrift","smitts reaktion auf tagebuch"}},{q="Woher kennt Smitts Marschall Haggard?",a="Smitts bewirtete Haggard vor Jahren, als dieser Patrouillen der Sturmwindwache in den Dämmerwald führte und zum Trinken in die Scarlet Raven Tavern einkehrte.",al={"smitts haggard beziehung","woher smitts haggard kennt"}},{q="Wie geht die Suche nach Stalvan weiter?",a="Bringt die verblasste Tagebuchseite zu Smitts in der Scarlet Raven Tavern und folgt der Spur, die er Euch weist.",al={"wie geht es weiter","nächster schritt stalvan","stalvan questreihe fortsetzen"}}},fx={bf062962={q="Warum möchte Marschall Haggard, dass dies erledigt wird?",a="Marschall Haggard kann die verblasste Tagebuchseite nicht lesen, weil sein Augenlicht nachlässt. Er erinnert sich an Schankwart Smitts als einen alten Bekannten mit fundiertem Wissen über die lokale Geschichte und bittet Euch, ihm die Seite in Dunkelhain zu überbringen.",al={"warum möchte haggard dies erledigt haben","motiv von marshal haggard","warum helfen stalvan zu finden"}},c297959a={q="Warum schickt Marschall Haggard Euch, anstatt selbst zu gehen?",a="Haggard ist ein alter, pensionierter Marshal, der in Isolation lebt und rapide sein Augenlicht verliert. Die Wege durch den Wald sind gefährlich, und ihm fehlen einfach die Jugend und die körperliche Ausdauer, um zurück über die Grenze in den Dämmerwald zu wandern. Er verlässt sich auf einen fähigen Reisenden wie Euch, um seine Besorgung zu erledigen und die Tagebuchseite seinem alten Bekannten zu zeigen.",al={"warum kann haggard nicht gehen","warum braucht haggard mich","warum besucht haggard smitts nicht"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="Die Kampfeber",s="Im Camp Narache jagen junge Tauren Kampfeber, um ihr Land zu schützen und die Jugend des Stammes zu ernähren.",h="Im Camp Narache jagen junge Tauren Kampfeber, um ihr Land zu schützen und die Jugend des Stammes zu ernähren.",kw={"kampfeber","dornrankenklamm","bristleback","camp narache","grull falkenwind","mulgore","quilboar","die hochwolkenebene"},ang={["class:Hunter"]="Als Jäger lernt Ihr, den Unterschied zwischen natürlicher Tierwelt und Bestien zu erkennen, die die Stacheleber zu Kriegswaffen verdreht haben.",["profession:Cooking"]="Als Koch wisst Ihr, dass selbst grobes, zähes Fleisch zu einem kräftigen Eintopf werden kann, der den Stamm stärkt.",["race:Tauren"]="Als Tauren verteidigt Ihr die Gebiete der Erdenmutter und verschwendet nichts, was Ihr im Kampf erbeutet. Aus den Kriegsbestien der Stacheleber wird Nahrung für die Kälber des Lagers."},sec={{t="Eine Bedrohung an der Grenze",b="Östlich der Hochwolkenebene liegt die Dornrankenklamm in den Händen der Stacheleberquilboar. Die Spannungen zwischen den Shu'halo und den Quilboar sind zu einem offenen Krieg eskaliert. Die Stacheleber züchten bösartige Kampfeber, um die Grenzen der Tauren auf die Probe zu stellen und ihre alten Jagdgründe unsicher zu machen. Wenn man die Tiere nicht aufhält, gefährden sie sowohl die Wildwechsel als auch Camp Narache."},{t="Den Stamm ernähren",b="Die Jagd schützt die Tauren und ernährt den Stamm. Grull Falkenwind bittet die jungen Jäger, die Schnauzen und Flanken der Kampfeber zurückzubringen. Selbst diese von den Quilboar abgerichteten Bestien werden verwertet. Ihr Fleisch und Knorpel kommen in einen Eintopf für die Jugend des Stammes. So wird aus einer Waffe der Quilboar Nahrung für die nächste Generation von Verteidigern der Tauren."}},faq={{q="Warum greifen die Kampfeber die Hochebene an?",a="Die Stacheleberquilboar aus der Dornrankenklamm haben die Kampfeber gezüchtet und abgerichtet. Sie setzen die Tiere ein, um die Tauren zu schikanieren und in die Stammesjagdgründe der Hochwolkenebene vorzudringen.",al={"kampfeber aggression","warum kampfeber feindselig sind","angreifende kampfeber"}},{q="Wer schickt Spieler auf diese Jagd?",a="Grull Falkenwind, ein Jäger und Ältester in Camp Narache, leitet junge Tauren durch die abschließenden Prüfungen ihrer ersten Ausbildung.",al={"questgeber die kampfeber","wer gibt die quest die kampfeber","rolle von grull falkenwind"}},{q="Wo sind die Kampfeber zu finden?",a="Kampfeber streifen nahe der Dornrankenklamm und in ihr umher. Sie liegt östlich von Camp Narache am östlichen Rand der Hochwolkenebene.",al={"kampfeber fundort","wo sind kampfeber","eber der dornrankenklamm"}},{q="Was geschieht mit dem von den Ebern gesammelten Fleisch?",a="Die Flanken und Schnauzen der Kampfeber werden nach Camp Narache gebracht und dort für einen Eintopf für die Kinder und Ältesten der Siedlung verwendet. Die Tauren verwerten, was sie jagen.",al={"verwendung von kampfeberflanken","wofür ist eberfleisch","ebereintopf"}},{q="Wie fügt sich diese Quest in den lokalen Quilboar-Konflikt ein?",a="Die Jagd führt in den offenen Krieg zwischen den Tauren und dem Stamm der Stacheleber ein. Wenn Ihr ihre Kriegstiere dezimiert, werden die Bestien, die die Jagdgründe der Tauren heimsuchen, weniger. Zugleich sendet Ihr den Stachelebern der Dornrankenklamm eine klare Botschaft.",al={"krieg zwischen tauren und quilboar","bristleback-konflikt","quilboar-lore"}},{q="Welche Quest geht Die Kampfeber voraus?",a="Zuerst kommt Die Jagd geht weiter. Grull Falkenwind schickt junge Jäger los, damit sie die Jagdgründe der Hochwolkenebene kennenlernen.",al={"die kampfeber voraussetzung","vorherige quest die kampfeber","the hunt continues questreihe"}}},fx={b70ec92c={q="Warum will Grull Falkenwind, dass die The Battleboars getötet werden?",a="Die The Battleboars sind aus der Dornrankenklamm vorgedrungen und direkt in die angestammten Jagdgründe des Stammes der Hochwolkenebene eingedrungen. Von den Bristleback-Quilboar darauf gezüchtet und trainiert, bösartig zu sein, bedroht ihre wachsende Aggression direkt Camp Narache. Grull Falkenwind beabsichtigt, den Bristlebacks eine deutliche Nachricht zu senden, indem er ihre Kriegstiere dezimiert und die Jagdbeute gleichzeitig als Nahrung für die Stammesjugend verwendet.",al={"warum sollen the battleboars sterben","grull falkenwind the battleboars motiv","warum the battleboars mulgore töten"}},["58a19c3f"]={q="Was sind The Battleboars?",a="The Battleboars sind wilde Bestien, die von den Bristleback-Quilboar aus der Dornrankenklamm aufgezogen und trainiert werden. Im Gegensatz zu den wilden Bergpumas und Ebenenschreitern, die in der Hochwolkenebene heimisch sind, wurden diese Eber gezielt auf Krieg und Bosheit abgerichtet und dienen als lebende Waffen im fortwährenden Kampf der Bristlebacks gegen die Tauren.",al={"wer sind die the battleboars","was sind the battleboars","the battleboars hintergrundwissen"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="Spendet Wolle",s="In Eisenschmiede helfen Wollspenden, die Vorräte aufzustocken. Für sechzig Stück wird Eure Großzügigkeit voll anerkannt.",h="In Eisenschmiede helfen Wollspenden, die Vorräte aufzustocken.",kw={"spende","eisenschmiede","anerkennung","sechzig stück","vorräte","wolle","wollstoff"},ang={["faction:Alliance"]="Als Reisender der Allianz erhaltet Ihr für Eure Wollspende Anerkennung von Eisenschmiede."},sec={{t="Wollvorräte",b="Eisenschmiede bittet Euch um sechzig Stück Wollstoff. Für ihre Vorräte braucht die Stadt nur diese Menge von Euch. Von anderen wird erwartet, genug zur Unterstützung der Sammelaktion beizutragen."}},faq={{q="Wie viel Wolle braucht Eisenschmiede von mir?",a="Sechzig Stück Wollstoff für Eisenschmiede.",al={"menge der wollspende","wie viel wolle","sechzig wolle"}},{q="Was bekomme ich für eine Wollspende?",a="Gebt Eisenschmiede sechzig Stück Wollstoff, und Eure Großzügigkeit wird voll anerkannt.",al={"belohnung für wollspende","was für wolle","anerkennung von eisenschmiede"}},{q="Warum sammelt Eisenschmiede Wolle?",a="Eisenschmiede sammelt Wollstoff, um ihre Vorräte aufzustocken.",al={"wollsammelaktion","warum wollspende","eisenschmiede wolle"}}},fp="18,110,11.148.0,42.42.0,32.93.0,33.51.0"}
P.entries["quest:7807"] = {n="Spendet Wolle",s="Im ganzen Reich ruft A Donation of Wool zur Hilfe für die Gnomeregangnome auf. Aus Gnomeregan vertrieben, brauchen sie Wollstoff, um ihr entwurzeltes Volk zu versorgen. Sechzig Stück bringen formelle Anerkennung unter den Gnomen ein.",h="Im ganzen Reich ruft A Donation of Wool zur Hilfe für die Gnomeregangnome auf.",kw={"stoffsammlung","wollspende","gnom","gnomeregan","gnomeregangnome","textilien","wollstoff"},ang={["faction:Alliance"]="Rohstoffspenden stärken den Zusammenhalt der Allianz und helfen, einen wichtigen Verbündeten zu versorgen, der aus seiner Heimat in den Bergen vertrieben wurde.",["profession:Tailoring"]="Schneider, die Wollstoff sammeln oder weben, verfügen über reichlich Textilien, die Flüchtlinge für einfache Kleidung und Versorgungsgüter benötigen.",["race:Gnome"]="Für Gnome im Exil hilft das Sammeln von Wolle, Eure vertriebenen Verwandten erneut zu versorgen, während sie außerhalb von Gnomeregan überleben und wiederaufbauen."},sec={{t="Ein vertriebenes Volk in Not",b="Der Fall von Gnomeregan durch eindringende Troggs und radioaktive Verseuchung vertrieb die überlebenden Gnome aus ihrer hochtechnisierten Stadt. Nun leben sie als Flüchtlinge, die vor allem ihre zwergischen Vettern in Eisenschmiede aufgenommen haben.\n\nFern ihrer angestammten Hallen stehen die Gnomeregangnome bei der Versorgung ihres Volkes unter großem Druck. Regelmäßige Sammlungen von Stoff und anderen Grundbedarfsgütern helfen ihnen, ihr Volk zu kleiden, zu versorgen und zu organisieren."},{t="Die Stoffsammlung",b="Bei der Sammlung wird jeder Freiwillige um genau sechzig Stück Wollstoff gebeten. Durch bescheidene Beiträge aus dem ganzen Reich sammeln die Vertriebenen die nötigen Textilien für Bettzeug, Verbände und Kleidung, ohne einzelne Lieferanten zu überlasten. Wer ihnen hilft, sich zu erholen, erhält formelle Anerkennung unter ihrem Volk."}},faq={{q="Warum brauchen die Gnomeregangnome Wollstoff?",a="Die Gnomeregangnome sammeln Textilien für den Grundbedarf. Aus ihrer Heimatstadt vertrieben, brauchen die Flüchtlinge Wollstoff, um ihr Volk zu versorgen und ihre laufenden Unternehmungen aufrechtzuerhalten.",al={"warum wolle","wofür ist die wolle","zweck der wollspende"}},{q="Wie viel Wollstoff wird benötigt?",a="Bei der Sammlung wird jeder Spender um sechzig Stück Wollstoff gebeten. Die Organisatoren zählen auf Beiträge aus dem ganzen Reich, um ihren Versorgungsbedarf zu decken.",al={"wie viel wolle","spendenmenge","benötigte wolle"}},{q="Wer organisiert diese Spendenaktion?",a="Vertreter der Gnomeregangnome organisieren die Sammlung und nehmen Spenden für die vertriebenen Gnome entgegen, die bei ihren Verbündeten Zuflucht gefunden haben.",al={"wer nimmt die spende","wer nimmt wolle an","spendenempfänger"}},{q="Könnt Ihr mehr als einmal Wollstoff spenden?",a="Jeder Spender wird um einen einmaligen Beitrag von sechzig Stück gebeten. Die Vertriebenen brauchen diese feste Menge von Euch und verlassen sich auf Spender aus dem ganzen Reich, um ihre Vorgabe zu erfüllen.",al={"erneut spenden","ist es wiederholbar","weitere wollspenden"}},{q="Welche Anerkennung bieten die Gnomeregangnome?",a="Eine Spende von sechzig Stück bringt Euch Anerkennung und Dankbarkeit der Gnomeregangnome ein. Sie zeigt Eure Treue und Unterstützung für ihr vertriebenes Volk in einer Zeit der Krise.",al={"ansehen bei den gnomeregangnomen","ruf bei gnomen","anerkennung der vertriebenen"}},{q="Warum leben die Gnome derzeit im Exil?",a="Die Gnome flohen nach einer verheerenden Katastrophe und einer Invasion der Troggs aus ihrer unterirdischen Heimat in Gnomeregan. Als Flüchtlinge sind sie auf provisorische Lager, die Hilfe ihrer Verbündeten und Materialsammlungen angewiesen.",al={"warum sind gnome im exil","wo liegt gnomeregan","flüchtlingskrise der gnome"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:78091"] = {n="Earning Your Salt",s="Ursula Deline in Sturmwind untersucht für Euch eine Kugel, verlangt dafür jedoch einen Dienst. Um zu erfahren, was sie herausfindet, müsst Ihr ins Rotkammgebirge reisen und dem Schwarzfelsklan vorbereitete Beschwörungssalze entreißen.",h="Ursula Deline in Sturmwind untersucht für Euch eine Kugel, verlangt dafür jedoch einen Dienst.",kw={"schwarzfelsklan","schwarzfelsbeschwörer","sich sein salz verdienen","rotkammgebirge","sturmwind","beschwörersalz","ursula deline"},ang={["class:Warlock"]="Ursula Deline untersucht eine Kugel für Euch, aber nur, wenn Ihr ihr die vorbereiteten Salze bringt, mit denen Schwarzfelsbeschwörer ihre Rituale stärken."},sec={{t="Ritual Salt",b="Schwarzfelsbeschwörer im Rotkammgebirge tragen speziell behandelte Salze bei sich, um ihre dunklen Rituale zu stärken. Ursula Deline weigert sich, eine Kugel für Euch zu untersuchen, bis Ihr aus diesen Lagern Vorräte beschafft. Sobald Ihr mit dem Salz in Sturmwind zurückkehrt, will sie Euch verraten, was ihre Studien ergeben."}},faq={{q="Wer ist Ursula Deline?",a="Ursula Deline ist eine Forscherin in Sturmwind, die sich bereit erklärt, eine Kugel für Euch zu untersuchen, wenn Ihr ihr Ritualzutaten beschafft.",al={"wer will beschwörersalz","wer vergibt earning your salt","wer ist ursula deline"}},{q="Warum braucht Ursula Beschwörersalz?",a="Hexenmeister des Schwarzfelsklans verwenden speziell zubereitete Salze, um ihre Beschwörungsrituale zu stärken. Ursula verlangt Vorräte davon, bevor sie ihre Forschungsergebnisse teilt.",al={"warum will ursula salz","wozu dient beschwörersalz","warum salz sammeln"}},{q="Wo findet man Beschwörersalz?",a="Das Salz tragen Schwarzfelsbeschwörer bei sich, die im Rotkammgebirge lagern.",al={"wo findet man beschwörersalz","wo sind schwarzfelsbeschwörer","wo bekomme ich das salz"}},{q="Was bietet Ursula im Gegenzug?",a="Ursula verspricht, eine Kugel zu untersuchen und Euch die Ergebnisse ihrer Forschung mitzuteilen, sobald Ihr mit dem Salz zurückkehrt.",al={"was verspricht ursula","was untersucht ursula","was bekommt man im gegenzug"}}},fp="17,233,11.314.0,21.114.0,37.145.0,35.82.0,33.101.0"}
P.entries["quest:781"] = {n="Angriff auf Camp Narache",s="In Camp Narache überbringt Ihr eine Warnung, die den Tauren Zeit verschaffen könnte, Hilfe zu rufen. Die Borstennackenstacheleber planen eine Belagerung, und Häuptling Falkenwind muss davon erfahren.",h="In Camp Narache überbringt Ihr eine Warnung, die den Tauren Zeit verschaffen könnte, Hilfe zu rufen.",kw={"angriffspläne","dorf der bluthufe","dornrankenklamm","borstennacken","camp narache","häuptling falkenwind","schmutzbefleckte karte","stacheleber","die hochwolkenebene"},ang={["faction:Horde"]="Indem Ihr den Stützpunkt der Tauren in Mulgore bewahrt, helft Ihr der Horde, ihren lebenswichtigen südlichen Anker im Zentrum Kalimdors zu halten.",["race:Tauren"]="Als junger Taurenkrieger, der seine ersten Riten auf der Hochwolkenebene beginnt, beweist Ihr Eure Treue, indem Ihr die Karte abfangt und Euer Volk vor einem plötzlichen Massaker schützt."},sec={{t="Ein Komplott im Dornengestrüpp",b="In der Dornrankenklamm findet Ihr eine grobe Karte auf dem Höhlenboden. Ihre schmutzbefleckten Markierungen verraten, dass die Borstennackenstacheleber eine lange Belagerung von Camp Narache planen. Das ist mehr als eine Reihe vereinzelter Angriffe."},{t="Warnung an den Häuptling",b="Ihr bringt die Angriffspläne zu Häuptling Falkenwind in Camp Narache. Nur wenige Verteidiger bewachen das Lager, das jungen Initianden Zuflucht bietet, weshalb Falkenwind eine Nachricht ins Dorf der Bluthufe vorbereitet, um Verstärkung anzufordern. Eure Warnung gibt dem Lager Zeit, sich auf die Belagerung vorzubereiten."}},faq={{q="Wo sind die Angriffspläne der Borstennacken zu finden?",a="Die Pläne der Borstennacken stehen auf einer schmutzbefleckten Karte in einer Höhle in der Dornrankenklamm, ein kurzes Stück den Pfad rechts von Chief Sharptusks Hütte hinauf.",al={"fundort der karte","wo ist die schmutzbefleckte karte","pläne finden"}},{q="Wer erhält die Angriffspläne der Borstennacken?",a="Häuptling Falkenwind erhält die Angriffspläne der Borstennacken im Zentrum von Camp Narache.",al={"bei wem abgeben","wer bekommt die karte","questabgabe"}},{q="Warum greifen die Borstennackenstacheleber Camp Narache an?",a="Der Stamm der Borstennacken will die Tauren von der Hochwolkenebene vertreiben und Mulgores Jagdgründe und heilige Ebenen für seinesgleichen zurückerobern.",al={"warum camp narache angreifen","beweggründe der stacheleber in mulgore","belagerung der borstennacken"}},{q="Wie will Häuptling Falkenwind der Belagerung begegnen?",a="Durch die Karte gewarnt, will Häuptling Falkenwind seine Brüder im Dorf der Bluthufe um Hilfe bitten, um die Hochwolkenebene zu verstärken und den Angriff abzuwehren.",al={"falkenwinds plan","verstärkung für camp narache"}},{q="Muss man für diese Quest mit jemandem sprechen, bevor man die Karte aufhebt?",a="Nein. Ihr findet die Schmutzbefleckte Karte auf dem Boden einer Höhle in der Dornrankenklamm. Sobald Ihr sie aufhebt, wird sie zu den Schlachtplänen.",al={"queststart","schmutzbefleckte karte queststart","wie beginnt angriff auf camp narache"}},{q="Was geschieht, wenn Camp Narache fällt?",a="Camp Narache ist die wichtigste Zuflucht für junge Taurenkrieger und ihre Übergangsriten. Sein Verlust würde die Sicherheit der Hochwolkenebene bedrohen und Mulgores spirituelle Ausbildungsstätten abschneiden.",al={"was für camp narache auf dem spiel steht","warum narache verteidigen"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="Meister der Arena",s="In der Stranglethorn Arena weiß Short John Mithril vielleicht, was es noch braucht, um ihre Wettkämpfe zu meistern.",h="In der Stranglethorn Arena weiß Short John Mithril vielleicht, was es noch braucht, um ihre Wettkämpfe zu...",kw={"meister der arena","gurubashi","pirat","short john mithril","stranglethorn arena","schlingendorntal"},sec={{t="Auf der Suche nach dem Piraten",b="Ihr habt bei Gurubashi etwas erlangt, doch die Arena zu meistern verlangt mehr. Short John Mithril organisiert die Wettkämpfe und weiß vielleicht, was nötig ist. Sucht ihn in der Stranglethorn Arena."},{t="Short Johns Wort",b="Short John Mithril sagt Euch, dass ein einzelnes Schmuckstück nicht genügt, um die Arena zu meistern. Die wahre Prüfung Eures Stahls beginnt jetzt."}},faq={{q="Mit wem muss ich sprechen?",a="Sprecht mit Short John Mithril, dem Piraten hinter dem Wettkampf bei Gurubashi.",al={"mit wem sprechen","meister der arena abgeben","wohin gehen"}},{q="Wo ist Short John Mithril?",a="Sucht Short John Mithril in der Stranglethorn Arena bei Gurubashi im Schlingendorntal.",al={"gurubashi standort","wo ist die stranglethorn arena","arena standort"}},{q="Was wird darüber angedeutet, Meister der Arena zu sein?",a="Ihr habt bei Gurubashi etwas vollbracht, doch die Arena zu meistern scheint mehr zu verlangen. Short John Mithril, der Pirat hinter dem Wettkampf, weiß vielleicht, was nötig ist.",al={"wie meister der arena werden","schon meister der arena"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Gelehrte suchen den Nar'thalas Almanac, um uralte magische Studien zu bewahren. Seine Bergung bringt vergessenes Wissen in eine Library, wo Forscher es studieren können.",h="Gelehrte suchen den Nar'thalas Almanac, um uralte magische Studien zu bewahren.",kw={"almanach","arkan","buch","library","magische werke","nar'thalas","narthalas","foliant"},ang={["class:Mage"]="Als Magier kennt Ihr den wissenschaftlichen Wert von Texten über uralte arkane Traditionen. Die magische Sammlung einer Library um geborgene Werke zu erweitern, ist von großer Bedeutung.",["faction:Alliance"]="Als Abenteurer der Allianz könnt Ihr Gelehrten und Kuratoren in Archiven der Allianz helfen, seltene Manuskripte zu suchen und das gesammelte Wissen des Reiches zu erweitern.",["race:NightElf"]="Als Nachtelf kennt Ihr Nar'thalas als uraltes Zentrum arkaner Gelehrsamkeit der Kaldorei, bevor die Zerschlagung die alte Welt zerriss. Ein Almanach, der seinen Namen trägt, verbindet Euch mit der uralten Geschichte der Nachtelfen."},sec={{t="Ein Relikt uralter Studien",b="Der Nar'thalas Almanac ist ein seltenes Werk arkaner Studien aus den alten Gelehrtentraditionen der Nachtelfen vor der Zerschlagung. Für die Hüter großer Archive rettet die Sicherung des Bandes jahrhundertealtes Wissen vor der Vergessenheit und bereichert ihre Regale um ein wichtiges Stück Geschichte. Wer vernachlässigte Werke entdeckt, hilft, vergessene Vorzeit und moderne Gelehrsamkeit miteinander zu verbinden."},{t="Die Archive erweitern",b="In ganz Azeroth suchen Archivare und Forscher nach verlorenen Abhandlungen, Feldnotizen und Chroniken. Wird der Nar'thalas Almanac in eine eigens dafür eingerichtete Library gebracht, können ihre Hüter ihn schützen, katalogisieren und studieren, statt ihn in Ruinen verrotten oder in achtlose Hände fallen zu lassen. Jeder geborgene Band eröffnet neue Einblicke in die arkanen Künste vergangener Zeitalter."}},faq={{q="Was ist der Nar'thalas Almanac?",a="Der Nar'thalas Almanac ist ein seltenes, uraltes Manuskript magischer Gelehrsamkeit, das Kuratoren für ihre historischen Archive suchen. Wer ihn birgt, übergibt seine Erkenntnisse in die Obhut von Gelehrten, wo sie bewahrt und katalogisiert werden können.",al={"was ist der narthalas almanac","narthalas almanac quest","almanach infos"}},{q="Wer sammelt den Nar'thalas Almanac?",a="Gelehrte der Library, die sich für uralte magische Texte und historische Archive interessieren, sammeln den Almanach. Kuratoren suchen gezielt nach Ergänzungen, um ihr gemeinsames Wissen über das arkane Erbe der Welt zu erweitern.",al={"wer will den almanach","wohin gehört der almanach","almanach abgeben"}},{q="Worauf bezieht sich der Name Nar'thalas?",a="Nar'thalas war vor der großen Zerschlagung ein uraltes Zentrum der Bildung und magischen Studien der Kaldorei. Texte, die seinen Namen tragen, bewahren Bruchstücke arkaner Künste und elfischen Wissens aus der Zeit vor der Zerschlagung.",al={"was ist narthalas","narthalas hintergrund","wo liegt narthalas"}},{q="Warum werden magische Texte für die Library gesammelt?",a="Historische Aufzeichnungen und magische Abhandlungen wurden in ganz Azeroth verstreut, gingen verloren oder wurden in Ruinen verschüttet. Gelehrte studieren geborgene Schriften, um ihr Verständnis arkaner Strömungen zu vertiefen und empfindliche Aufzeichnungen vor dem völligen Verlust zu bewahren.",al={"warum magische werke sammeln","zweck der library","warum bücher wichtig sind"}},{q="Können weitere magische Werke in die Library gebracht werden?",a="Abhandlungen, Folianten und vergessene Manuskripte können Licht auf arkane Theorie und uralte Geschichte werfen. Gelehrte suchen fortwährend nach Ergänzungen, um ihre Regale zu bereichern.",al={"weitere magische bücher","andere folianten","weitere texte"}},{q="Ist der Umgang mit dem Nar'thalas Almanac gefährlich?",a="Der Almanach ist eine Sammlung wissenschaftlicher Aufzeichnungen, kein unberechenbares verbotenes Artefakt. Historiker und Magiekundige können ihn als wertvolles Nachschlagewerk zur Magie vergangener Zeiten nutzen.",al={"ist der almanach gefährlich","enthält der almanach dunkle magie","gefahrlos lesen"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="Der Bibliothekar bittet Euch, magische Werke für die Sammlung zu bringen. Jedes Buch erweitert das Wissen der Bibliothek.",h="Der Bibliothekar bittet Euch, magische Werke für die Sammlung zu bringen.",kw={"sammlung","dalaran digest","wissen","bibliothekar","library","magische werke"},sec={{t="Die Sammlung",b="Der Bibliothekar nimmt gerne magische Werke entgegen, die der Bibliothek nützen könnten. Ihr bringt ein Buch für die Sammlung und helft damit, ihr Wissen zu mehren."}},faq={{q="Was möchte der Bibliothekar?",a="Der Bibliothekar bittet Euch, magische Werke zu bringen, die der Sammlung nützen könnten.",al={"was mitbringen","bibliotheksbuch","magische werke"}},{q="Wohin bringe ich das Buch?",a="Bringt das Buch zu dem Bibliothekar, der Euch gebeten hat, es der Sammlung hinzuzufügen.",al={"wo ist der bibliothekar","standort der bibliothek"}},{q="Warum sammelt der Bibliothekar magische Werke?",a="Euer Beitrag erweitert das Wissen der Sammlung.",al={"warum bücher sammeln","zweck der bibliothek"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Betörungen und Verzauberungen",s="In Eisenschmiede sucht die Bibliothek magische Werke für ihre Regale. Ihr könnt ihren Hütern helfen, ihr Wissen zu erweitern, indem Ihr Bücher bringt, die der Sammlung nützen könnten.",h="In Eisenschmiede sucht die Bibliothek magische Werke für ihre Regale.",kw={"bewitchments and glamours","bücher","sammlung","eisenschmiede","library","magische werke"},sec={{t="Eine wachsende Sammlung",b="Bringt magische Werke zur Bibliothek in Eisenschmiede, wo jeder Neuzugang das Wissen ihrer Hüter erweitern kann."}},faq={{q="Was sucht die Bibliothek?",a="Die Bibliothek sucht magische Werke, die ihrer Sammlung nützen könnten.",al={"was suchen sie","bibliotheksbücher","magische werke"}},{q="Wohin bringe ich die magischen Werke?",a="Bringt die magischen Werke zur Bibliothek.",al={"wohin bücher bringen","wo ist die bibliothek","bibliothek in eisenschmiede"}},{q="Warum sammeln sie magische Werke?",a="Die Bibliothek sagt, dass die Werke ihr Wissen erweitern werden.",al={"warum magische bücher sammeln","wozu dient die sammlung"}}},fp="25,168,20.103.0,27.64.0,35.39.0,38.53.0"}
P.entries["quest:78143"] = {n="Geheimnisse der Träumer",s="Die Gelehrten einer Bibliothek suchen Schriften über die Dreamers und anderes magisches Wissen. Reisende bringen vergessene Werke aus dem ganzen Reich, damit sie dort studiert und in den Archiven aufbewahrt werden können.",h="Die Gelehrten einer Bibliothek suchen Schriften über die Dreamers und anderes magisches Wissen.",kw={"arkan","dreamers","library","magische werke","gelehrte","secrets of the dreamers","folianten"},ang={["class:Druid"]="Für Euch als Druiden haben Schriften über Naturmagie und den Smaragdgrünen Traum eine tiefe Bedeutung in den Künsten des Cenarion.",["class:Mage"]="Als Magier könnt Ihr nach wenig bekannten Folianten und magischen Texten suchen, um die Archive der Gelehrten zu bereichern.",["faction:Alliance"]="Gelehrte der Allianz, besonders jene, die große Wissensspeicher betreuen, sind auf Champions angewiesen, um verlorenes Wissen aus gefährlichen Orten zu bergen."},sec={{t="Vergessenes Wissen bergen",b="Gelehrte im ganzen Reich sind auf Reisende angewiesen, um seltene magische Texte und historische Abhandlungen zu bergen. Diese Werke liegen in uralten Ruinen oder privaten Horten, weit entfernt von den Archiven. So bringen Abenteurer sie sicher zu jenen, die Azeroths arkane Geheimnisse erforschen und sein Wissen bewahren."},{t="Die Archive erweitern",b="Wenn Reisende Abhandlungen bringen, nehmen Archivare sie in die dauerhafte Sammlung der Bibliothek auf. Forscher suchen wenig bekannte Schriften über den Smaragdgrünen Traum und arkane Theorie. Ihre Arbeit geht weiter, und sie heißen weitere magische Texte willkommen, die draußen gefunden werden."}},faq={{q="Was ist das Ziel der Quest Secrets of the Dreamers?",a="Reisende bergen magische Schriften und wenig bekanntes Wissen und bringen sie dann zu den Gelehrten einer Bibliothek, um die Archive zu bereichern.",al={"was ist secrets of the dreamers","quest secrets of the dreamers","was ist in dieser quest zu tun"}},{q="Wer sammelt diese magischen Texte?",a="Ein Gelehrter, der die Sammlung einer Bibliothek betreut, sammelt die Texte und bittet Reisende, magische Werke zu bringen.",al={"wer will secrets of the dreamers","wer vergibt diese quest","wo secrets of the dreamers abgeben"}},{q="Wo werden die geborgenen Werke aufbewahrt?",a="Die Schriften gelangen in die wachsenden Archive einer institutionellen Bibliothek, wo Gelehrte und Forscher der Allianz seltenes Wissen und magische Entdeckungen katalogisieren und bewahren können.",al={"was ist die sammlung","für welche bibliothek ist das","wohin kommen die bücher"}},{q="Worauf bezieht sich „the Dreamers“ im Titel?",a="Dreamers bezeichnet Druiden, die auf den Smaragdgrünen Traum eingestimmt sind, oder uralte schlafende Wesen, die an den Schlummer der Natur gebunden sind. Schriften, die ihre Geheimnisse enthalten, bewahren rätselhafte urtümliche Macht.",al={"wer sind die dreamers","hintergrundwissen zu den dreamers","warum heißt es dreamers"}},{q="Könnt Ihr nach Abschluss der Quest weitere magische Werke bringen?",a="Die Archivare heißen weitere Beiträge willkommen. Wenn Ihr magische Schriften findet, die der Sammlung dienen könnten, könnt Ihr sie für die weitere Forschung bringen.",al={"weitere bücher abgeben","ist das wiederholbar","weitere magische werke"}},{q="Warum ist das Sammeln dieser magischen Schriften für Gelehrte wichtig?",a="Gelehrte wollen ihr Verständnis von arkanem, natürlichem und wenig bekanntem Wissen erweitern. Verlorene oder verstreute Abhandlungen könnten Einblicke in die tiefere Geschichte und die Geheimnisse der Welt gewähren.",al={"warum magische bücher sammeln","warum braucht die bibliothek magische folianten"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="Handbuch arkanischer Systeme",s="Das Arcanic Systems Manual ist ein magisches Werk, das für die Sammlung einer Bibliothek gesucht wird. Seine Aufnahme hilft der Bibliothek, ihr Wissen zu erweitern.",h="Das Arcanic Systems Manual ist ein magisches Werk, das für die Sammlung einer Bibliothek gesucht wird.",kw={"arcanic","arcanic systems manual","sammlung","eisenschmiede","library","magische werke","handbuch"},sec={{t="Ein Platz in der Library",b="Die Bibliothek heißt magische Werke willkommen, die ihre Sammlung bereichern können. Ihr bringt eines zur Aufnahme mit, und Euer Beitrag hilft, ihr Wissen zu erweitern."}},faq={{q="Was ist das Arcanic Systems Manual?",a="Es ist ein magisches Werk, das für die Sammlung einer Bibliothek gesucht wird.",al={"arcanic handbuch","welches handbuch"}},{q="Wer möchte das Handbuch haben?",a="Ein Bibliothekar bittet Euch, magische Werke zu bringen, die die Sammlung bereichern könnten.",al={"wer hat darum gebeten","handbuch für wen"}},{q="Warum das Handbuch in die Bibliothek bringen?",a="Das Wissen der Bibliothek wächst durch Beiträge in Form magischer Werke.",al={"warum es spenden","wozu dient es"}}},fp="22,129,22.137.0,35.55.0,21.76.0,36.69.0"}
P.entries["quest:78146"] = {n="Goaz' Schriftrollen",s="Der Bibliothekar bittet Euch, Goaz Scrolls für die Sammlung zu bringen. Euer Beitrag erweitert das Wissen der Bibliothek.",h="Der Bibliothekar bittet Euch, Goaz Scrolls für die Sammlung zu bringen.",kw={"sammlung","goaz scrolls","wissen","library","magische werke","schriftrollen"},sec={{t="Eine wachsende Sammlung",b="Der Bibliothekar dankt Euch dafür, dass Ihr Goaz Scrolls beigesteuert habt. Weitere magische Werke könnten der Bibliothek ebenfalls helfen, und der Bibliothekar nimmt sie gerne entgegen."}},faq={{q="Wozu dienen Goaz Scrolls?",a="Goaz Scrolls erweitern die Sammlung und das Wissen der Bibliothek.",al={"goaz scrolls zweck","warum schriftrollen bringen","schriftrollen bibliothek"}},{q="Wer bittet um die Goaz Scrolls?",a="Ein Bibliothekar bittet Euch, Goaz Scrolls für die Sammlung zu bringen.",al={"wer will goaz scrolls","schriftrollen auftraggeber","person in der bibliothek"}},{q="Wohin kommen die Schriftrollen?",a="Die Goaz Scrolls sind für die Sammlung der Bibliothek bestimmt.",al={"wohin schriftrollen bringen","goaz scrolls ort","bibliothek schriftrollen"}},{q="Was würde der Bibliothek sonst noch helfen?",a="Der Bibliothekar nimmt gerne weitere magische Werke entgegen, die der Bibliothek zugutekommen könnten.",al={"weitere magische werke","mehr bücher für die bibliothek","was sonst noch bringen"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="Ein Bibliothekar bittet Euch, magische Werke zur Sammlung einer Bibliothek hinzuzufügen. Eure Entdeckungen helfen, das Wissen der Bibliothek zu erweitern.",h="Ein Bibliothekar bittet Euch, magische Werke zur Sammlung einer Bibliothek hinzuzufügen.",kw={"sammlung","crimes against anatomy","eisenschmiede","bibliothekar","library","magische werke"},sec={{t="Für die Sammlung",b="Jedes magische Werk, das der Bibliothek dienen könnte, ist dort willkommen. Ihr könnt Eure Entdeckungen zum Bibliothekar bringen, dessen Wissen durch diese Beiträge wächst. Weitere Werke könnten der Bibliothek noch von Nutzen sein."}},faq={{q="Wer bittet um magische Werke?",a="Ein Bibliothekar bittet Euch, magische Werke zu bringen, die der Sammlung nützen könnten.",al={"wer will bücher","bitte der bibliothek"}},{q="Wohin bringe ich die Werke?",a="Bringt sie zum Bibliothekar. Bibliothekare sammeln solche Werke in Sturmwind und in der Unterstadt.",al={"wo ist die bibliothek","bücher wohin bringen"}},{q="Warum magische Werke sammeln?",a="Die Werke erweitern das Wissen der Bibliothek.",al={"warum bücher","wozu magische werke"}}},fp="22,124,18.204.0,27.78.0,27.92.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="Eine Bibliothek nimmt magische Werke in ihre Sammlung auf. Eure Entdeckungen helfen, ihr Wissen zu erweitern.",h="Eine Bibliothek nimmt magische Werke in ihre Sammlung auf.",kw={"sammlung","eisenschmiede","wissen","library","magische werke","runen","sorcerer-kings"},sec={{t="Die Sammlung",b="Der Hüter der Library dankt Euch, denn durch Eure Bemühungen wächst ihre Sammlung. Weitere magische Werke könnten ihr Wissen erweitern, und der Hüter nimmt sie gern für die Library entgegen."}},faq={{q="Was sucht die Library?",a="Die Library nimmt magische Werke, die ihre Sammlung bereichern könnten, gern entgegen.",al={"was wollen sie","bücher der library","magische werke"}},{q="Wo ist die Library?",a="Bibliothekare sammeln solche Werke in Sturmwind und in der Unterstadt.",al={"standort der library","wo ist die library","library in eisenschmiede"}},{q="Warum magische Werke bringen?",a="Eure Bemühungen erweitern das Wissen der Library.",al={"warum bücher","wofür","der library helfen"}}},fp="27,96,14.168.0,27.67.0,21.63.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="Eine Bibliothek sucht magische Werke für ihre Sammlung. Eure Funde erweitern ihr Wissen.",h="Eine Bibliothek sucht magische Werke für ihre Sammlung.",kw={"sammlung","fury of the land","eisenschmiede","wissen","library","magische werke"},sec={{t="Ein Ort des Wissens",b="Der Bibliothekar fragt, ob Ihr etwas zum Ergänzen mitgebracht habt. Er freut sich über Eure Funde und lädt Euch ein, weitere zu bringen, wenn Ihr welche entdeckt."}},faq={{q="Was möchte die Library?",a="Die Library sucht magische Werke, die ihre Sammlung bereichern könnten.",al={"was brauchen sie","bücher der library","magische werke"}},{q="Wohin soll ich magische Werke bringen?",a="Bringt sie zum Bibliothekar. Bibliothekare sammeln solche Werke in Sturmwind und in der Unterstadt.",al={"wohin bücher bringen","standort der library","werke bringen"}},{q="Warum sammeln sie magische Werke?",a="Der Bibliothekar sagt, dass jeder Beitrag ihr Wissen erweitert.",al={"warum magische bücher sammeln","sammlung der library","wofür"}}},fp="16,90,21.153.0,27.64.0,35.92.0,38.61.0"}
P.entries["quest:7815"] = {n="Schnappkiefer, Alter!",s="In Revantusk bittet Euch Katoom der Angler, Euch um die Salzwasserschnappkiefer zu kümmern, die ihm das Angeln vermiesen. Er will fünfzehn Schildkröten getötet sehen.",h="In Revantusk bittet Euch Katoom der Angler, Euch um die Salzwasserschnappkiefer zu kümmern, die ihm das...",kw={"angler","köder","angeln","hinterland","katoom","revantusk","schnappkiefer","schildkröten"},sec={{t="Ärger an der Angelschnur",b="Katoom der Angler bittet Euch, ihm und seinen Nachbarn in Revantusk zu helfen. Salzwasserschnappkiefer mögen harmlos aussehen, doch sie erschweren das Angeln. Einer zerreißt seine Schnur und stiehlt seinen Köder, bevor er auch nur fünf Minuten angeln kann. Katoom will, dass Ihr fünfzehn der Schildkröten tötet."}},faq={{q="Wer bittet Euch, die Schildkröten zu jagen?",a="Katoom der Angler, ein Fischer aus Revantusk im Hinterland, bittet Euch, die Schildkröten zu jagen.",al={"wer vergibt schnappkiefer alter","schnappkiefer alter questgeber","katoom der angler"}},{q="Warum will Katoom die Salzwasserschnappkiefer getötet sehen?",a="Katoom sagt, dass die Salzwasserschnappkiefer seine Angelschnur zerreißen und seinen Köder stehlen. Er kann kaum fünf Minuten angeln, bevor einer ihn stört.",al={"warum schnappkiefer töten","schildkrötenplage","warum schildkröten in revantusk töten"}},{q="Wie viele Schnappkiefer müssen getötet werden?",a="Ihr müsst fünfzehn Salzwasserschnappkiefer töten.",al={"wie viele schildkröten","schnappkiefer anzahl","schnappkiefer alter anzahl"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="Gammerita, Alter!",s="In Revantusk will Katoom der Angler seinen besten Köder von Gammerita, Alter! zurück, die die Salzwasserschnappkiefer anführt. Findet sie und holt ihn zurück.",h="In Revantusk will Katoom der Angler seinen besten Köder von Gammerita, Alter!",kw={"angler","gammerita","hinterland","katoom","köder","revantusk","schnappkiefer","schildkröte"},sec={{t="Eine Diebin unter Schildkröten",b="Katoom sagt, Gammerita, Alter! sei keine gewöhnliche Schildkröte. Sie führt die Salzwasserschnappkiefer an, und er nennt sie eine Diebin. Sie biss seinen besten Köder von der Angelschnur ab. Seitdem beißen die Fische nicht mehr so an wie früher."},{t="Den Köder zurückholen",b="Katoom möchte, dass Ihr Gammerita, Alter! findet und seinen Köder aus ihrem Magen zurückholt. Sie hält sich an der Küste unter den anderen Schildkröten auf."},{t="Katooms Hoffnungen",b="Wenn er seinen Köder zurückhat und weniger Schnappkiefer in der Nähe sind, erwartet Katoom, dass die Fische haufenweise anbeißen."}},faq={{q="Wer ist Katoom der Angler?",a="Katoom der Angler fischt in Revantusk im Hinterland. Er bittet Euch, Gammerita zu jagen.",al={"wer ist katoom","katoom revantusk","katoom aufenthaltsort"}},{q="Was ist Gammerita?",a="Gammerita ist keine gewöhnliche Schildkröte. Sie führt die Salzwasserschnappkiefer an, und Katoom nennt sie eine Diebin.",al={"wer ist gammerita","was ist gammerita","gammerita schildkröte"}},{q="Warum will Katoom Gammerita tot sehen?",a="Gammerita biss Katooms besten Köder von seiner Angelschnur ab, und die Fische beißen nicht mehr so an wie früher. Er will ihn aus ihrem Magen zurückhaben.",al={"warum gammerita töten","was hat gammerita gestohlen","katooms beweggrund"}},{q="Wo ist Gammerita zu finden?",a="Gammerita hält sich an der Küste unter den anderen Salzwasserschnappkiefern auf.",al={"wo ist gammerita","gammerita aufenthaltsort","gammerita finden"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.96.0,18.96.0,36.132.0,29.71.0"}
P.entries["quest:782"] = {n="Zerbrochene Allianzen",s="Gorn schickt Euch von Kargath aus los, um zurückzuholen, was die Oger genommen haben. Er will die Ehre der Horde nach ihrem Bündnis mit Deathwing wiederherstellen. Boss Tho'grun, der angeheuert wurde, um das Zeichen der Erde zu finden, verriet die Horde und behielt es.",h="Gorn schickt Euch von Kargath aus los, um zurückzuholen, was die Oger genommen haben.",kw={"ödland","blacklash","camp boff","deathwing","gorn","hematus","kargath","die lethlorklamm","zeichen der erde","tho'grun"},sec={{t="Eine Söldnertruppe wendet sich ab",b="Während des Zweiten Krieges kämpfte die Horde an der Seite von Deathwing. Seine Leutnante Blacklash und Hematus wurden später weit im Osten in der Lethlorklamm eingesperrt. Gorn glaubt, dass diese verdorbenen Verbündeten von einst zum Schweigen gebracht werden müssen, um die Ehre der Horde wiederherzustellen.\n\nDie Horde brauchte das Zeichen der Erde, um das Gefängnis der Drakes zu öffnen, und heuerte deshalb Ogermöldner unter Boss Tho'grun an, um das Zeichen zu finden. Tho'grun wandte sich gegen die Horde, überwältigte ihre Streitkräfte und behielt es."},{t="Camp Boff",b="Gorn schickt Euch südöstlich von Kargath nach Camp Boff. Tötet Tho'grun und bringt das Zeichen der Erde zurück. Gorn wird froh sein, Tho'grun tot zu sehen. Die Oger gehören nicht mehr zur Horde."},{t="Was das Zeichen öffnet",b="Gorn erwartet, dass die Oger nach Tho'gruns Tod in Unordnung geraten. Das wird ein kleiner Sieg sein und könnte zu einem größeren führen.\n\nMit dem Zeichen der Erde in den Händen der Horde kann das Gefängnis der schwarzen Drakes in Lethlor geöffnet werden. Sie werden aus ihrer endlosen Gefangenschaft befreit, nur um ihrem Untergang entgegenzugehen."}},faq={{q="Wer ist Gorn?",a="Gorn ist eine Persönlichkeit der Horde in Kargath, die Euch losschickt, um das Zeichen der Erde zu holen. Er will die Ehre der Horde wiederherstellen, indem er ihre verdorbenen Verbündeten von einst zum Schweigen bringt.",al={"wer vergibt zerbrochene allianzen","gorn kargath","gorn geschichte"}},{q="Warum will Gorn Boss Tho'grun tot sehen?",a="Die Horde heuerte Boss Tho'grun und seine Ogermöldner an, um das Zeichen der Erde zu beschaffen. Tho'grun verriet sie, überwältigte sie und behielt das Zeichen.",al={"warum thogrun töten","thogruns verrat","boss thogrun geschichte"}},{q="Wo liegt Camp Boff?",a="Camp Boff liegt südöstlich von Kargath.",al={"camp boff standort","wo ist thogrun","boss thogrun finden"}},{q="Was ist das Zeichen der Erde?",a="Das Zeichen der Erde ist ein Schlüssel, der benötigt wird, um das Gefängnis der Drakes in der Lethlorklamm zu öffnen.",al={"zeichen der erde","was bewirkt das zeichen der erde"}},{q="Welche Drachen sind in der Lethlorklamm eingesperrt?",a="Blacklash und Hematus sind zwei von Deathwings Leutnanten. Sie wurden in der Lethlorklamm eingesperrt, nachdem die Horde während des Zweiten Krieges an der Seite von Deathwing gekämpft hatte.",al={"wer ist in der lethlorklamm","blacklash und hematus","deathwings leutnante"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="Spendet Wolle",s="Donnerfels sucht Wollstoff, und Ihr könnt Euch mit sechzig Stück seine volle Anerkennung verdienen. Von anderen Spendern wird erwartet, dass sie genügend Vorräte beisteuern, um die Spendenaktion zu unterstützen.",h="Donnerfels sucht Wollstoff, und Ihr könnt Euch mit sechzig Stück seine volle Anerkennung verdienen.",kw={"stoffspendenaktion","spende","anerkennung","sechzig stück","donnerfels","wolle","wollstoff"},sec={{t="Eine Stoffspende",b="Donnerfels sammelt Wollstoff. Spendet sechzig Stück, um volle Anerkennung für Eure Großzügigkeit zu erhalten. Von anderen Spendern im Reich wird erwartet, dass sie genug beisteuern, um die Spendenaktion zu unterstützen."}},faq={{q="Welche Spenden möchte Donnerfels erhalten?",a="Donnerfels nimmt Wollstoffspenden an.",al={"wollspende","welchen stoff brauchen sie","wolle spenden"}},{q="Wie viel Wollstoff sollte ich spenden?",a="Spendet sechzig Stück Wollstoff, um die volle Anerkennung von Donnerfels zu erhalten.",al={"wie viel wolle","sechzig stoff","spendenmenge"}},{q="Was bekomme ich für eine Wollspende?",a="Eure Spende von sechzig Stück Wollstoff bringt Euch die volle Anerkennung von Donnerfels ein.",al={"anerkennung für wollspende","welche anerkennung gibt es","spendenbelohnung"}},{q="Warum sammelt Donnerfels Wolle?",a="Donnerfels erwartet, dass andere Spender im Reich genügend Wollstoff bereitstellen, um die Spendenaktion zu unterstützen.",al={"warum wollspendenaktion","wofür ist wolle","warum stoff sammeln"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="Spendet Wolle",s="In Orgrimmar bittet A Donation of Wool um Hilfe beim Sammeln von Stoff. Die Stadt hat Wolle in ihren Lagern und erwartet, dass weitere Spender genug für die Sammelaktion bringen.",h="In Orgrimmar bittet A Donation of Wool um Hilfe beim Sammeln von Stoff.",kw={"a donation of wool","spende","orgrimmar","anerkennung","sechzig stück","wolle","wollstoff"},sec={{t="Wolle für Orgrimmar",b="Orgrimmar bittet Euch, sechzig Stück Wollstoff zu spenden. Im Gegenzug verspricht die Stadt Anerkennung. In ihren Lagern liegt bereits etwas Wolle, und weitere Spender sollen die Sammelaktion unterstützen."}},faq={{q="Worum bittet Orgrimmar?",a="Orgrimmar nimmt Wollstoffspenden entgegen.",al={"was wollen sie","wollspende"}},{q="Wie viel Wolle muss ich spenden?",a="Orgrimmar bittet um sechzig Stück Wollstoff.",al={"wie viel wolle","sechzig wolle"}},{q="Was bekomme ich für eine Wollspende?",a="Ihr erhaltet die volle Anerkennung Orgrimmars, wenn Ihr sechzig Stück Wollstoff spendet.",al={"anerkennung für spenden","belohnung für wolle"}},{q="Warum sammelt Orgrimmar Wolle?",a="Orgrimmar sammelt Wolle, um seine Spendenaktion zu unterstützen.",al={"wollsammelaktion","warum wolle"}},{q="Hat Orgrimmar bereits Wolle?",a="Ja. Orgrimmar hat Wolle in seinen Lagern und erwartet, dass weitere Spender genug für die Sammelaktion bringen.",al={"wollvorräte","wie viel wolle"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="Eine Notiz von C bittet Euch, das Horn of Xelthos allein aus Burg Shadowfang zu holen. Veenix im Steinkrallengebirge könnte Euch helfen, durch das Hoftor zu gelangen.",h="Eine Notiz von C bittet Euch, das Horn of Xelthos allein aus Burg Shadowfang zu holen.",kw={"c","toter briefkasten","horn of xelthos","lohenscheit","burg shadowfang","steinkrallengebirge","veenix","xelthos"},sec={{t="Unauffälliges Vorgehen",b="C hinterlässt die Notiz nahe Lohenscheit und nennt Veenix als Kontaktperson im Steinkrallengebirge. Das Horn of Xelthos liegt irgendwo in Burg Shadowfang, für deren Betreten man gewöhnlich Verstärkung braucht. C will, dass die Sache unauffällig bleibt, also sollt Ihr allein gehen und das Horn zum toten Briefkasten zurückbringen."}},faq={{q="Wer bittet um das Horn of Xelthos?",a="C hinterlässt eine Notiz mit der Bitte, das Horn of Xelthos zu holen und zum toten Briefkasten nahe Lohenscheit zurückzubringen.",al={"wer ist c","wer will das horn","c horn auftrag"}},{q="Wo ist das Horn of Xelthos?",a="Das Horn of Xelthos befindet sich irgendwo in Burg Shadowfang.",al={"wo ist das horn","fundort des horns","xelthos finden"}},{q="Warum muss ich allein gehen?",a="C sagt, dass die Arbeit unauffällig erledigt werden muss, also sollt Ihr Burg Shadowfang allein betreten.",al={"warum allein","warum allein gehen","keine verstärkung"}},{q="Wer ist Veenix?",a="Veenix ist Cs Kontaktperson im Steinkrallengebirge und könnte Euch helfen, durch das Hoftor von Burg Shadowfang zu gelangen.",al={"veenix hilfe","wer ist veenix","kontaktperson am tor"}},{q="Wohin bringe ich das Horn zurück?",a="Bringt das Horn zu Cs totem Briefkasten nahe Lohenscheit zurück.",al={"wohin das horn zurückbringen","standort des toten briefkastens","horn abgeben"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="Ein Kontakt der Venture Co. bietet Sprengstoff an, damit Ihr durch Shadowfangs Tor kommt, verlangt aber zuerst einen Arbeitsauftrag. Ein anderer Arbeiter der Venture Co. in der Nähe sollte einen bei sich tragen.",h="Ein Kontakt der Venture Co.",kw={"sprengstoff","tor","goblin-dietriche","shadowfang","venture co.","arbeitsauftrag"},sec={{t="Ein Arbeitsauftrag",b="Ein Kontakt der Venture Co. erfährt, dass Ihr allein nach Shadowfang wollt. Sprengstoff könnte Euch durch das Tor bringen, doch der Kontakt braucht einen Arbeitsauftrag, damit die Vorräte in den Firmenbüchern ordnungsgemäß aussehen. Einer der anderen Arbeiter der Venture Co. in der Nähe sollte das Dokument bei sich tragen."}},faq={{q="Warum brauchen sie einen Arbeitsauftrag?",a="Der Kontakt der Venture Co. braucht einen Arbeitsauftrag, damit der Sprengstoff in den Firmenbüchern rechtmäßig aussieht.",al={"warum arbeitsauftrag","warum papierkram","goblin-dietriche"}},{q="Wofür ist der Sprengstoff gedacht?",a="Der Sprengstoff soll Euch durch Shadowfangs Tor bringen.",al={"wofür sprengstoff","shadowfang-tor","durchs tor kommen"}},{q="Wer könnte den Arbeitsauftrag haben?",a="Ein anderer Arbeiter der Venture Co. in der Nähe sollte einen Arbeitsauftrag bei sich tragen.",al={"wer hat arbeitsauftrag","papiere finden","venture-co.-arbeitsauftrag"}},{q="Gehe ich allein nach Shadowfang?",a="Der Kontakt der Venture Co. weiß, dass Ihr allein nach Shadowfang wollt.",al={"allein nach shadowfang","allein hineingehen","shadowfang betreten"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="Die Pirsch auf die Pirscher",s="In Revantusk benennt Jäger Markhor die Wölfe, die die Jäger des Dorfes bedrohen. Er bittet Euch, nun Jagd auf sie zu machen.",h="In Revantusk benennt Jäger Markhor die Wölfe, die die Jäger des Dorfes bedrohen.",kw={"wölfe im hinterland","jäger markhor","revantusk","silvermane howler","silvermane stalker","die pirsch auf die pirscher"},sec={{t="Wölfe im Verborgenen",b="Die Wildnis des Hinterlands hat bereits viele Trolle das Leben gekostet. Markhor zählt die Silvermane-Wölfe zu den größten Gefahren für Revantusks Jäger. Sie verstecken sich im Gebüsch und im Schutz des Geländes und springen hervor, wenn der richtige Augenblick gekommen ist. Er drängt Euch, wie ein Silvermane zu denken und die Jäger zu jagen. Jeder einzelne muss zur Strecke gebracht werden."},{t="Was Markhor verlangt",b="Markhor bittet Euch, fünfzehn Silvermane Stalker und fünfzehn Silvermane Howler zu töten. Sie lauern in der Wildnis des Hinterlands."},{t="Der Dank der Revantusk",b="Wenn die Jagd vorüber ist, dankt Markhor Euch für das, was Ihr den Revantusk gegeben habt."}},faq={{q="Wer bittet darum, die Wölfe zu jagen?",a="Jäger Markhor von den Revantusk im Hinterland bittet Euch, die Wölfe zu jagen.",al={"wer vergibt die pirsch auf die pirscher","questgeber die pirsch auf die pirscher","markhor quest"}},{q="Warum sind die Silvermane-Wölfe eine solche Bedrohung?",a="Silvermane-Wölfe verstecken sich im Gebüsch und im Schutz des Geländes und schlagen zu, sobald sich eine Gelegenheit bietet. Markhor zählt sie zu den größten Gefahren für Revantusks Jäger, und viele Trolle haben in der Wildnis bereits ihr Leben verloren.",al={"warum silvermane-wölfe töten","bedrohung durch silvermane-wölfe","warum wölfe im hinterland dezimieren"}},{q="Welche Wölfe müssen zur Strecke gebracht werden?",a="Ihr werdet gebeten, fünfzehn Silvermane Stalker und fünfzehn Silvermane Howler zu jagen.",al={"welche wölfe töten","ziele die pirsch auf die pirscher","wolfsarten im hinterland"}},{q="Wo sind diese Wölfe zu finden?",a="Die Wölfe lauern in der Wildnis des Hinterlands.",al={"wo sind silvermane-wölfe","silvermane stalker fundort","silvermane howler fundort"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="Jagt die Wilden",s="Im Hinterland schickt Jäger Markhor Euch auf die Jagd nach wilden Eulenbestien. Er bittet Euch, zwanzig zu erlegen.",h="Im Hinterland schickt Jäger Markhor Euch auf die Jagd nach wilden Eulenbestien.",kw={"hinterland","jagt die wilden","jäger markhor","eulenbestien","revantusk","wilde eulenbestie"},sec={{t="Klauen und Schnäbel",b="Jäger Markhor warnt, dass wilde Eulenbestien zu den widerspenstigsten Kreaturen des Hinterlands zählen. Ihre Klauen und Schnäbel haben Revantusk viele gute Krieger gekostet. Er will, dass Ihr jede Eulenbestie tötet, die Ihr seht, bis Ihr kein Blutvergießen mehr ertragen könnt. Dann wird er Euren Beitrag abwägen und beurteilen. Zwanzig müssen fallen."},{t="Den Geist klären",b="Markhor rät Euch, Euren Geist von unreinen Gedanken zu befreien und eins mit der Wildnis zu werden. Wilde Eulenbestien durchstreifen die Wildnis des Hinterlands."},{t="Markhors Urteil",b="Nach der Jagd erklärt Jäger Markhor Euch zu einem würdigen Freund der Revantusk."}},faq={{q="Wer bietet diese Jagd an?",a="Jäger Markhor, ein Jäger aus dem Dorf Revantusk im Hinterland, bietet die Jagd an.",al={"wer vergibt jagt die wilden","jagt die wilden questgeber","jäger markhor quest"}},{q="Warum will Markhor die wilden Eulenbestien töten lassen?",a="Markhor bezeichnet wilde Eulenbestien als widerspenstig. Ihre Klauen und Schnäbel haben Revantusk viele gute Krieger gekostet.",al={"warum wilde eulenbestien töten","grund für die jagd auf eulenbestien","warum jagt die wilden"}},{q="Wo sind die wilden Eulenbestien zu finden?",a="Markhor sagt, dass wilde Eulenbestien die Wildnis des Hinterlands durchstreifen.",al={"wilde eulenbestie fundort","wo sind wilde eulenbestien","eulenbestien im hinterland"}},{q="Wie viele wilde Eulenbestien müssen getötet werden?",a="Zwanzig wilde Eulenbestien müssen fallen.",al={"wie viele eulenbestien töten","jagt die wilden anforderung"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="Die Bedrohung von innen",s="Im Nordhaintal folgen Freiwillige dem Ruf von Sturmwind, während die örtliche Verteidigung ins Wanken gerät. In der Abtei von Nordhain leitet Marschall McBride die Gegenwehr, und Ihr beginnt Euren Dienst auf dem bedrohten Gelände.",h="Im Nordhaintal folgen Freiwillige dem Ruf von Sturmwind, während die örtliche Verteidigung ins Wanken gerät.",kw={"die bedrohung von innen","abtei","wald von elwynn","marschall mcbride","nordhain","rekrutierung","wache von sturmwind","freiwillige"},ang={["faction:Alliance"]="Als Mitglied der Allianz seht Ihr, wie ihre Verpflichtungen in fernen Ländern selbst ihr Kernland inneren Bedrohungen ausliefern.",["race:Human"]="Als menschlicher Verteidiger aus Nordhain gebt Ihr mit Eurer Antwort auf Marschall McBrides Ruf Euer erstes offizielles Versprechen, Eure Heimat und das Königreich Sturmwind zu schützen."},sec={{t="Ein Königreich am Limit",b="Das Nordhaintal bot den Menschen einst Ruhe für Gebet, Landwirtschaft und klösterliche Studien. Heute ist es die erste Verteidigungslinie des Waldes von Elwynn gegen innere Unruhen. Nur wenige Wachen sind noch in der Nähe, deshalb ruft die Wache von Sturmwind jeden bereitwilligen Freiwilligen auf, der die Abtei erreicht. Unheil breitet sich im Umland aus."},{t="Der Ruf des Marschalls",b="Von der Abtei von Nordhain aus leitet Marschall McBride die Verteidigung des Tals, während die Gefahr wächst. Banditen, Ungeziefer und Plagen aus dem Untergrund bedrohen die Menschen in der Umgebung. Ihr beginnt damit, das Gelände um die Abtei zu sichern, wo diese Bedrohungen den Verteidigern des Tals und dem Ort, den sie schützen, gefährlich nahekommen."}},faq={{q="Was ist das Ziel dieser Quest?",a="Marschall McBride ruft Neuankömmlinge im Nordhaintal dazu auf, bei dessen Verteidigung zu helfen. Ihr betretet die Abtei von Nordhain und meldet Euch bei ihm.",al={"bedrohung von innen quest","was ist diese quest","nordhain einstiegsquest"}},{q="Wer ist Marschall McBride?",a="Marschall McBride ist der ranghöchste Offizier der Wache von Sturmwind in der Abtei von Nordhain. Er leitet die Verteidigung des Tals und schickt Rekruten gegen Bedrohungen im Umland aus.",al={"marschall mcbride","wer ist mcbride","kommandant der abtei"}},{q="Warum wirbt Sturmwind Freiwillige an, statt reguläre Soldaten zu schicken?",a="Sturmwinds reguläre Streitkräfte dienen im Ausland, um die Allianz zu schützen. Da den Garnisonen im Kernland Soldaten fehlen, verlassen sich örtliche Befehlshaber auf Freiwillige, um ihre Heimat zu verteidigen.",al={"warum freiwillige","wo sind die wachen","warum ist sturmwind unterbesetzt"}},{q="Welche Bedrohungen plagen derzeit das Nordhaintal?",a="Kobolde haben die nahen Minen und Hügel bevölkert, während krankes oder räuberisches Ungeziefer die Weinberge heimsucht. Auch Wegelagerer und Gesetzlose nutzen die geschwächte Garnison des Tals aus.",al={"bedrohungen im tal","was greift nordhain an","probleme in nordhain"}},{q="Wohin führt dieser Auftrag als Nächstes?",a="Nachdem Ihr Euch bei Marschall McBride gemeldet habt, werdet Ihr ausgeschickt, um die Hügel von Kobolden zu befreien, örtlichen Bauern und Arbeitern zu helfen und der wachsenden Präsenz organisierter Banditen nachzugehen.",al={"nächste quest","was kommt nach bedrohung von innen","mcbride folgequest"}},{q="Warum dient die Abtei von Nordhain als militärischer Kommandoposten?",a="Die Abtei von Nordhain ist ein heiliger Ort des Studiums und des Glaubens, doch ihre Steinmauern und ihre zentrale Lage machen sie zu einem zweckmäßigen Stützpunkt für das Tal. Da die örtliche Obrigkeit unter Druck steht, hat die Wache von Sturmwind ihre Kommandostelle in der Abtei eingerichtet.",al={"warum militär in der abtei","nordhain kirche militär","heilige abtei soldaten"}}},fx={["2039075b"]={q="Warum schickt Euch Deputy Willem zu Marschall McBride?",a="Deputy Willem ist vor der Abtei von Nordhain stationiert, um kampffähige Neuankömmlinge so schnell wie möglich zu überprüfen. Da das Militär des Königreichs überlastet ist und mehrere Krisen die Grenzen von Nordhain bedrohen, muss er jeden fähigen Freiwilligen ordnungsgemäß zum Dienst einberufen. Anstatt selbst Missionen zuzuweisen, schickt Willem Euch direkt zu seinem befehlshabenden Offizier, Marschall McBride, damit Ihr formell eingewiesen und dort eingesetzt werden könnt, wo die Verteidigung des Tals am meisten wackelt.",al={"warum mit mcbride sprechen","willem motiv","warum mit mcbride reden"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="Die Gefallenen rächen",s="In Revantusk richtet Markhor seinen Zorn gegen die Skylords. Er bittet Euch, einen Razorbeak Skylord zu töten und ihm dessen Feder zu bringen.",h="In Revantusk richtet Markhor seinen Zorn gegen die Skylords.",kw={"die gefallenen rächen","greif","hinterland","jäger markhor","razorbeak skylord","revantusk","skylord feder","wildhammer"},sec={{t="Die Skylords töten",b="Jäger Markhor aus Revantusk grollt den Wildhammer, weil sie Greifen dazu abrichten, Trolle zu töten. Er verspricht den Trollen Gerechtigkeit, doch zuerst sollt Ihr gegen die Skylords vorgehen, die älteren Greifen des Hinterlands.\n\nTötet einen Razorbeak Skylord und bringt seine Feder zu Markhor zurück. Diese seltene Art lebt in der Wildnis des Hinterlands. Markhor gibt ihr die Schuld daran, mörderischen Nachwuchs heranzuzüchten."},{t="Die Feder untersuchen",b="Markhor betrachtet die Feder und fragt sich, wie viele Jäger die Bestie verschlungen hat, bevor sie durch Eure Hand ihre gerechte Strafe fand."}},faq={{q="Wer bietet diese Jagd an?",a="Jäger Markhor bietet die Jagd in Revantusk im Hinterland an.",al={"questgeber","wer vergibt die gefallenen rächen","markhor standort"}},{q="Warum will Jäger Markhor einen Skylord töten lassen?",a="Markhor sagt, die Wildhammer richten Greifen dazu ab, Trolle zu töten. Er will die älteren Greifen der Region, die Skylords, ausrotten lassen und gibt dem seltenen Razorbeak Skylord die Schuld daran, mörderischen Nachwuchs heranzuzüchten.",al={"warum razorbeak skylord töten","warum skylord töten","warum greifen jagen"}},{q="Wo ist ein Razorbeak Skylord zu finden?",a="Markhor sagt, der seltene Razorbeak Skylord hält sich in der Wildnis des Hinterlands auf.",al={"skylord standort","wo ist razorbeak skylord","skylord feder fundort"}},{q="Was muss zu Markhor zurückgebracht werden?",a="Die Feder eines Razorbeak Skylord, wofür zuerst einer getötet werden muss.",al={"welcher gegenstand wird benötigt","die gefallenen rächen questziel","skylord beute"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="Spendet Wolle",s="Ein Dunkelspeertroll sammelt Wollspenden, und Eure sechzig Stück Wollstoff werden Teil einer größeren Sammlung.",h="Ein Dunkelspeertroll sammelt Wollspenden, und Eure sechzig Stück Wollstoff werden Teil einer größeren...",kw={"sammlung","dunkelspeer","spende","vorräte","trolle","wolle","wollstoff"},sec={{t="Eine gemeinsame Sammlung",b="Die Dunkelspeertrolle sammeln Wollstoff, um ihre Vorräte aufzufüllen. Der Sammler kann Eure sechzig Stück jetzt annehmen, während die Hilfe anderer die Sammlung vervollständigen soll."}},faq={{q="Was wird gesammelt?",a="Die Dunkelspeertrolle sammeln Wollstoff.",al={"was brauchen sie","wollspende"}},{q="Wie viel Wollstoff brauchen sie von mir?",a="Der Sammler braucht sechzig Stück Wollstoff von Euch.",al={"wie viel wolle","sechzig stück stoff"}},{q="Warum sammeln die Trolle Wolle?",a="Die Trolle sammeln Wolle, um ihre Vorräte aufzufüllen.",al={"warum wolle","wofür"}},{q="Kann ich den Stoff jetzt abgeben?",a="Ja. Der Sammler kann Eure sechzig Stück Wollstoff jetzt annehmen.",al={"wo wolle abgeben","jetzt spenden"}}},fp="18,103,19.181.0,24.46.0,41.56.0,35.56.0,25.66.0"}
P.entries["quest:7839"] = {n="Schläger der Vilebranch",s="In Revantusk sucht Schmied Slagtree nach Werkzeugen, die Vilebranch-Trolle gestohlen haben. Ein gutherziger Gnom schenkte ihm den Satz, nachdem er ihm als jungem Orc das Leben gerettet hatte.",h="In Revantusk sucht Schmied Slagtree nach Werkzeugen, die Vilebranch-Trolle gestohlen haben.",kw={"agol'watha","hinterland","markhor","revantusk","shaol'watha","skulk rock","slagtrees verlorene werkzeuge","schmied slagtree","vilebranch"},sec={{t="Ein Geschenk eines Gnoms",b="Vilebranch-Trolle stahlen Schmied Slagtrees Werkzeuge, als sie Revantusk überfielen. Er hat Ersatzwerkzeuge, doch der gestohlene Satz stammt von einem gutherzigen Gnom, der ihm als jungem Orc das Leben rettete. Das Geschenk bedeutet Slagtree die Welt, daher bittet er Euch, es zurückzuholen."},{t="Wo die Werkzeuge gesichtet wurden",b="Markhor sah die Werkzeuge nahe den Tempeln von Agol'watha und Shaol'watha im Nordosten des Hinterlands. Slagtree sagt außerdem, Ihr sollt Skulk Rock absuchen. Die Vilebranch-Trolle dort sind skrupellos und mörderisch."}},faq={{q="Warum sind diese gestohlenen Werkzeuge für Schmied Slagtree so wichtig?",a="Ein gutherziger Gnom schenkte Slagtree die Werkzeuge, nachdem er ihm als jungem Orc das Leben gerettet hatte. Slagtree hat Ersatzwerkzeuge, sagt aber, dass ihm der geschenkte Satz die Welt bedeutet.",al={"warum sind slagtree seine werkzeuge so wichtig","geschichte von slagtrees verlorenen werkzeugen","warum sind slagtrees werkzeuge besonders"}},{q="Wer hat die Werkzeuge aus Revantusk gestohlen?",a="Vilebranch-Trolle stahlen Schmied Slagtrees Werkzeuge bei ihrem Überfall auf Revantusk.",al={"wer nahm die werkzeuge","wer stahl slagtrees werkzeuge"}},{q="Wohin wurden die vermissten Werkzeuge gebracht?",a="In die Nähe der Tempel von Agol'watha und Shaol'watha im Nordosten des Hinterlands, wo Markhor sie sah. Slagtree verweist außerdem auf Skulk Rock.",al={"wo sind slagtrees werkzeuge","wo die werkzeuge finden","fundort von slagtrees werkzeugen"}},{q="Wer berichtete, die Werkzeuge nach dem Überfall gesehen zu haben?",a="Markhor berichtete Schmied Slagtree, wo die Werkzeuge gesehen worden waren.",al={"wer sah die werkzeuge","wer berichtete von den gestohlenen werkzeugen"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="Vernichtet die Verräter",s="Bei Burg Tiragarde halten Streitkräfte der Kul Tiraner noch immer einen Brückenkopf an Durotars Küste. Gar'Thok ruft die Horde zum Angriff auf Lieutenant Benedicts Garnison auf, deren Anwesenheit den brüchigen Frieden mit Theramore gebrochen hat.",h="Bei Burg Tiragarde halten Streitkräfte der Kul Tiraner noch immer einen Brückenkopf an Durotars Küste.",kw={"daelin prachtmeer","durotar","gar'thok","kul tiras","lieutenant benedict","marinesoldaten","klingenhügel","matrosen","burg tiragarde","vernichtet die verräter"},ang={["faction:Horde"]="Streitkräfte der Kul Tiraner besetzen noch immer Burg Tiragarde an Durotars Schwelle. Benedicts Truppen zu vertreiben zeigt, dass die Horde ihre neu besiedelte Heimat gegen fremde Flotten verteidigen kann.",["race:Orc"]="Die Orcs achten den am Hyjal mit Jaina geschlossenen Waffenstillstand, doch Kul Tiras weckt bittere Erinnerungen an den Zweiten Krieg. Der Kampf gegen Benedicts Marinesoldaten ist eine Frage des Überlebens und des Stolzes auf die Ahnen.",["race:Troll"]="Burg Tiragarde liegt beunruhigend nahe bei Sen'jin, der Siedlung der Dunkelspeer. Die feindseligen Matrosen von dort zu vertreiben hilft, die verwundbare neue Heimat der Trolle zu schützen."},sec={{t="Ein zerbrochener Waffenstillstand",b="Thrall führte die Horde über das große Meer nach Kalimdor. Dort kämpften er und Lady Jaina Prachtmeer am Hyjal gegen die Brennende Legion. Der Frieden zerbrach, als Jainas entfremdeter Vater, Großadmiral Daelin Prachtmeer, die Flotte von Kul Tiras nach Durotar brachte. Er gab jedem Orc die Schuld an den Gräueltaten der Alten Horde und besetzte Küstenfestungen, darunter Burg Tiragarde. Daelin starb bei Theramore, doch die Überreste seiner Flotte lehnen noch immer jeden Pakt ab und halten an ihrem Hass fest."},{t="Benedicts Wiedererstarken",b="Burg Tiragarde fiel nach der Niederlage des Großadmirals für einige Zeit. Dann eroberten Reservisten von Kul Tiras unter Lieutenant Benedict sie zurück. Die Festung liegt zwischen Klingenhügel und Sen'jin. Von dort aus bedrängen Matrosen und Marinesoldaten Reisende und bedrohen die Seezugänge zu Durotars Ostküste. Gar'Thok sieht ihre Anwesenheit als unmittelbare Gefahr für Durotars Sicherheit. Deshalb ruft er die Krieger der Horde auf, gegen Benedicts Kommando vorzugehen."}},faq={{q="Warum greifen die Menschen der Kul Tiraner Durotar an?",a="Sie sind Überreste der Expeditionsflotte von Großadmiral Daelin Prachtmeer. Daelin lehnte den Frieden zwischen Menschen und Orcs ab und wollte Durotar vernichten. Selbst nach seinem Tod halten seine Getreuen Küstenfestungen wie Burg Tiragarde und trotzen der Horde.",al={"warum sind menschen in durotar","kul tiras greift an","burg tiragarde menschen hintergrund"}},{q="Wer ist Lieutenant Benedict?",a="Lieutenant Benedict befehligt die Reservisten der Kul Tiraner, die Burg Tiragarde halten. Nach der Niederlage von Großadmiral Prachtmeer sammelte Benedict die überlebenden Marinesoldaten und Matrosen um sich. Er eroberte die Küstenfestung zurück und begann anhaltende Einsätze gegen die Orcs.",al={"wer ist benedict","lieutenant benedict hintergrund","anführer burg tiragarde"}},{q="Unterstützt Jaina Prachtmeer diese Menschen?",a="Nein. Jaina schloss mit Kriegshäuptling Thrall einen Pakt für ihr beider Überleben und widersetzte sich dem aggressiven Kreuzzug ihres Vaters, um den Frieden zu bewahren. Die Truppen in Burg Tiragarde sind Überreste der Streitkräfte von Kul Tiras, die Theramores Diplomatie ablehnen und Jainas Waffenstillstand als Verrat betrachten.",al={"unterstützt jaina sie","theramore kul tiras bündnis","jaina prachtmeer tiragarde"}},{q="Warum werden sie „Verräter“ genannt?",a="Gar'Thok nennt sie Verräter, weil ihre Invasion die Übereinkunft brach, die Thrall und Jaina Prachtmeer schlossen, um Archimonde im Dritten Krieg zu besiegen. Ihre fortdauernde militärische Präsenz im Gebiet der Horde missachtet die nach dem Krieg auf Kalimdor festgelegten Grenzen.",al={"warum verräter","wer hat wen verraten","verräter bedeutung"}},{q="Wo liegt Burg Tiragarde?",a="Burg Tiragarde liegt an Durotars Ostküste, südlich von Klingenhügel und unmittelbar nordöstlich von Sen'jin. Ihre hohen Steinmauern überblicken die Küstengewässer und bieten den Invasoren einen strategischen Stützpunkt nahe den Siedlungen der Horde.",al={"burg tiragarde lage","wo liegt burg tiragarde","wo ist benedict zu finden"}}},fx={["6a077d02"]={q="Warum will Gar'Thok, dass Burg Tiragarde geräumt wird?",a="Gar'Thok überwacht die Verteidigung von Klingenhügel und dem östlichen Durotar. Die Wiederbesetzung von Burg Tiragarde durch feindselige Kräfte der Kul Tiraner bedroht direkt die Sicherheit der Heimat der Orcs und missachtet den Frieden, der zwischen Thrall und Jaina Prachtmeer geschlossen wurde. Wenn man zulässt, dass eine bewaffnete menschliche Festung an der Küste von Durotar weiterbesteht, setzt man nahegelegene Siedlungen und Nachschubwege einer unmittelbaren Invasionsgefahr aus.",al={"gar'thok motiv","warum burg tiragarde räumen","gar thok warum menschen angreifen"}},["902328ad"]={q="Wen sollt Ihr in Burg Tiragarde ausschalten?",a="Ihr habt den Auftrag, die überlebenden Seestreitkräfte der Kul Tiraner zu zerschlagen, die Burg Tiragarde besetzt halten: Seeleute, Marinesoldaten und ihren befehlshabenden Offizier, Lieutenant Benedict. Diese Soldaten stellen die Überreste der Flotte von Großadmiral Daelin Prachtmeer dar und halten einen nicht genehmigten, bewaffneten Brückenkopf tief im souveränen Gebiet der Horde.",al={"wer in burg tiragarde töten","wer sind die ziele","ziele bezwingen"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="Lards vergessene Brotzeit",s="Im Hinterland ist Lard nach Revantusk geflohen und hat das Picknickessen zurückgelassen. Ein Vilebranch schlug Lard bei einem privaten Picknick, und nun bittet Lard Euch, das Essen von einer Insel im Norden zu holen.",h="Im Hinterland ist Lard nach Revantusk geflohen und hat das Picknickessen zurückgelassen.",kw={"hinterland","insel","lard","mittagessen","picknick","revantusk","vilebranch"},sec={{t="Ein unterbrochenes Picknick",b="Ein Vilebranch schlug Lard an einem geheimen Picknickplatz mit einem großen Stock. Lards Erzählung nach war der Troll hässlich und gemein. Lard floh nach Revantusk, ließ das Mittagessen zurück und fürchtete sich vor einer Rückkehr."},{t="Die Insel im Norden",b="Lards Picknickplatz liegt auf einer Insel im Norden. Lard hofft, dass Ihr das Mittagessen findet und zurückbringt. Nehmt Euch vor den Vilebranch-Trollen in Acht."},{t="Lards Dank",b="Lards Mittagessen ist eine riesige Fleischkeule. Lard schlingt sie hinunter, dankt Euch und verspricht Euch einen besonderen Picknickkorb für Eure Hilfe."}},faq={{q="Wer ist Lard?",a="Lard lebt in Revantusk im Hinterland. Hungrig und verängstigt floh Lard, nachdem ein Vilebranch Lard mit einem großen Stock geschlagen hatte.",al={"lard hinterland","wer ist lard","lard revantusk"}},{q="Wo hat Lard sein Mittagessen verloren?",a="Lard ließ das Mittagessen an einem geheimen Picknickplatz auf einer Insel im Norden zurück.",al={"wo ist lards mittagessen","lards picknickplatz","lards geheimer ort"}},{q="Warum ließ Lard sein Essen zurück?",a="Ein Vilebranch schlug Lard während des Picknicks mit einem großen Stock. Lard rannte ohne das Mittagessen nach Revantusk zurück.",al={"warum floh lard","wer griff lard an"}},{q="Wovor solltet Ihr Euch auf der Insel in Acht nehmen?",a="Lard nennt die Vilebranch-Trolle als Gefahr auf der Insel.",al={"vilebranch auf der insel","gefahren auf lards insel"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="Eine Botschaft an die Wildhämmer",s="In Revantusk will Otho Moji'ko den Wildhammerzwergen eine Botschaft überbringen lassen. Zu ihren neuen Verbündeten gehören die Hochelfen, und Otho will seine Warnung im Blut der Highvale-Hochelfen an der Quel'Danil-Hütte schreiben lassen.",h="In Revantusk will Otho Moji'ko den Wildhammerzwergen eine Botschaft überbringen lassen.",kw={"highvale","hinterland","botschaft an die wildhämmer","otho mojiko","die quel'danil-hütte","revantusk","wildhammer"},sec={{t="Eine Botschaft in Blut",b="Die Wildhammer schließen Bündnisse mit den Feinden der Trolle, und nun stehen die Hochelfen an ihrer Seite. Otho Moji'ko spuckt bei diesem Gedanken aus. Er will die Zwerge mit dem Blut ihrer neuen Freunde warnen. Schlachtet jeden Highvale-Hochelfen ab, dem Ihr begegnet, und hinterlasst die Leichen als Warnung.\n\nHighvale Outrunners, Scouts, Marksmen und Rangers versammeln sich an der Quel'Danil-Hütte im Nordwesten des Hinterlands."},{t="Kunde aus Revantusk",b="Wenn Ihr nach Revantusk zurückkehrt, verkündet Otho, dass auch die Revantusk neue Bündnisse schließen. Er lobt Eure Arbeit."}},faq={{q="Wer vergibt diese Quest?",a="Otho Moji'ko vergibt sie in Revantusk.",al={"wer vergibt eine botschaft an die wildhämmer","otho mojiko quest"}},{q="Wo befinden sich die Highvale-Hochelfen?",a="Die Highvale-Hochelfen versammeln sich an der Quel'Danil-Hütte im Nordwesten des Hinterlands.",al={"quel'danil-hütte standort","wo sind highvale-elfen","wo highvale scouts finden"}},{q="Warum will Otho Moji'ko die Hochelfen angreifen lassen?",a="Otho sagt, die Wildhammer schließen Pakte mit den Feinden der Trolle, und nun arbeiten sie mit den Hochelfen zusammen. Er will den Wildhammerzwergen eine Botschaft überbringen lassen, geschrieben im Blut der Hochelfen.",al={"warum quel'danil angreifen","warum hochelfen im hinterland töten"}},{q="Welche Highvale-Elfen will Otho abschlachten lassen?",a="Otho will die Highvale Outrunners, Scouts, Marksmen und Rangers an der Quel'Danil-Hütte abschlachten lassen.",al={"welche highvale-elfen","highvale marksman","highvale ranger"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="Eine weitere Botschaft an die Wildhämmer",s="In Revantusk schickt Otho Moji'ko den Wildhammer eine weitere Botschaft. Er sieht ihre Bindung zu Greifen als ebenso eng wie die zwischen einem Troll und einer Gefährtin und will sie gegen sie verwenden.",h="In Revantusk schickt Otho Moji'ko den Wildhammer eine weitere Botschaft.",kw={"greif","hinterland","long elegant feather","otho moji'ko","revantusk","wildhammer"},sec={{t="Eine Botschaft aus Federn",b="Nach den Hochelfen von Highvale hat Otho Moji'ko eine weitere Botschaft für die Wildhammer. Ihre Nähe zu Greifen ekelt ihn an, doch er sieht einen Nutzen darin. Tötet die Greifen, denen Ihr im Hinterland begegnet, und sammelt ihre Long Elegant Feathers. Greifen leben dort in jeder Region. Otho wird aus den Federn seine letzte Botschaft fertigen."},{t="Othos Vergnügen",b="Otho erwartet, dass seine letzte Botschaft die Wildhammer vertreibt oder sie wütend macht. Er freut sich, dass nur noch ein Schritt bleibt, bevor sie erfahren, dass man sich mit Trollen nicht anlegen darf."}},faq={{q="Wer vergibt diese Quest?",a="Otho Moji'ko überbringt die Botschaft aus Revantusk.",al={"wer vergibt eine weitere botschaft an die wildhämmer","weitere botschaft questgeber","otho mojiko"}},{q="Warum will Otho Moji'ko Greifenfedern?",a="Otho sagt, die Wildhammer und ihre Greifen stehen einander so nahe wie ein Troll und eine Gefährtin. Er will diese Bindung gegen sie verwenden und aus den Federn seine letzte Botschaft fertigen.",al={"warum greifenfedern","warum greifen im hinterland töten"}},{q="Wo findet man Greifen?",a="Greifen leben in jeder Region des Hinterlands.",al={"greifenfundorte hinterland","wo sind greifen im hinterland"}},{q="Was ging dieser Botschaft voraus?",a="Zuvor kam Message to the Wildhammer, bei der Otho Hochelfen von Highvale als Warnung an die Zwerge abschlachten ließ.",al={"was kommt vor einer weiteren botschaft an die wildhämmer","message to the wildhammer questreihe"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="Die letzte Botschaft an die Wildhämmer",s="In Revantusk schickt Euch Otho Moji'ko mit einem blutgetränkten, mit Greifenfedern umwickelten Speer nach Westen. Die Wildhammerzwerge werden ihn neben dem Brunnen im Herzen von Nistgipfel in der Erde stecken sehen.",h="In Revantusk schickt Euch Otho Moji'ko mit einem blutgetränkten, mit Greifenfedern umwickelten Speer nach...",kw={"nistgipfel","greifenfedern","hinterland","otho moji'ko","revantusk","speer","wildhämmer"},sec={{t="Ein Speer für Nistgipfel",b="Nach Another Message to the Wildhammer gibt Euch Otho Moji'ko einen blutgetränkten und mit Greifenfedern umwickelten Speer. Tragt ihn nach Westen zu Nistgipfel und rammt ihn neben dem Brunnen im Herzen der Stadt in die Erde. Die Wildhammerzwerge werden sehen, dass die Trolle es ernst meinen. Wütende Zwerge und rauflustiges Allianzvolk erwarten Euch dort, und Otho hofft, dass Ihr lebend zurückkehrt."},{t="Othos Hoffnung",b="Otho fragt sich, wie die Zwerge reagieren werden, wenn sie den Speer sehen. Er wünscht, er hätte ihre Gesichter sehen können. Packen sie ihre Taschen, um die Stadt zu verlassen? Für die Ausführung der Tat verspricht Otho Euch das große Mojo."}},faq={{q="Wer schickt Euch los, um den Speer in die Erde zu rammen?",a="Otho Moji'ko schickt Euch von Revantusk aus los.",al={"questgeber","wer gibt die quest","otho mojiko"}},{q="Wo muss der Speer in die Erde gerammt werden?",a="Rammt den Speer neben dem Brunnen im Herzen von Nistgipfel im Westen des Hinterlands in die Erde.",al={"standort des speers","wo den speer platzieren","nistgipfel brunnen"}},{q="Woraus besteht die letzte Botschaft?",a="Die letzte Botschaft ist ein blutgetränkter und mit Greifenfedern umwickelter Speer.",al={"was ist der speer","greifenfedern speer","letzte botschaft gegenstand"}},{q="Was kam zuvor in dieser Questreihe?",a="Another Message to the Wildhammer kam zuerst. Otho verlangte Greifenfedern, um diese letzte Botschaft anzufertigen.",al={"vorherige quest","voraussetzungen","wildhämmer botschaft questreihe"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="Kannibalistische Vettern",s="Im Hinterland bittet Mystikerin Yayo'jin Euch, die Vilebranch nahe ihren Tempeln anzugreifen. Sie nennt sie ein verkommenes Pack, das andere Trolle und Humanoide jagt. Da Zul'jin fort ist, sind die Revantusk auf sich allein gestellt.",h="Im Hinterland bittet Mystikerin Yayo'jin Euch, die Vilebranch nahe ihren Tempeln anzugreifen.",kw={"agol'watha","kannibalistische vettern","mystikerin yayo'jin","revantusk","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},sec={{t="Drei Stämme, ein Land",b="Drei Trollstämme teilen sich das Hinterland, doch laut Mystikerin Yayo'jin verbindet sie wenig. Die Vilebranch jagen andere Trolle und Humanoide. Zul'jin könnte sie mit Leichtigkeit auslöschen, doch er ist fort. So sind die Revantusk auf sich allein gestellt."},{t="Wo sich die Vilebranch sammeln",b="Yayo'jin bittet Euch, die Scalper und Soothsayer der Vilebranch nahe den Tempeln von Shaol'watha und Agol'watha zu vernichten. Die Tempel liegen im Nord-Nordosten des Hinterlands."},{t="Yayo'jins Lob",b="Bei Eurer Rückkehr sagt Yayo'jin, dass selbst Zul'jin es nicht hätte besser machen können."}},faq={{q="Wer vergibt diese Quest?",a="Mystikerin Yayo'jin vergibt sie in Revantusk.",al={"kannibalistische vettern questgeber","wer vergibt kannibalistische vettern","mystikerin yayojin"}},{q="Warum will Yayo'jin die Vilebranch vernichten lassen?",a="Yayo'jin nennt die Vilebranch ein verkommenes Pack, das andere Trolle und Humanoide jagt. Sie sagt, es liege an Euch, den Abschaum der Region zu vernichten.",al={"warum kämpfen revantusk gegen vilebranch","vilebranch kannibalismus","revantusk vilebranch konflikt"}},{q="Wo sind die Trolle der Vilebranch zu finden?",a="Die Vilebranch sammeln sich um die Tempel von Shaol'watha und Agol'watha im Nord-Nordosten des Hinterlands.",al={"shaolwatha standort","agolwatha standort","wo sind die soothsayer der vilebranch"}},{q="Welche Vilebranch will Yayo'jin vernichten lassen?",a="Yayo'jin will die Scalper und Soothsayer der Vilebranch vernichten lassen.",al={"kannibalistische vettern ziele","wen für kannibalistische vettern töten"}},{q="Wo ist Zul'jin?",a="Zul'jin ist nicht im Hinterland. Yayo'jin sagt, er könnte die Vilebranch mit Leichtigkeit auslöschen, doch er ist fort, und die Revantusk sind auf sich allein gestellt.",al={"ist zuljin hier","wo ist zuljin im hinterland","zul'jin status"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="Die Entführung des Älteren Torntusk",s="In Revantusk bittet Euch Primal Torntusk, ihren Gefährten nach einem kühnen mitternächtlichen Überfall zu retten. Ihre Spione berichten, dass der Ältere Torntusk oben auf Jintha'Alor noch lebt.",h="In Revantusk bittet Euch Primal Torntusk, ihren Gefährten nach einem kühnen mitternächtlichen Überfall zu...",kw={"älterer torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},sec={{t="Ein mitternächtlicher Überfall",b="Vilebranch-Wilde überfielen Revantusk um Mitternacht und ergriffen den Älteren Torntusk, den Gefährten von Primal Torntusk. Ihre Spione berichten, dass er noch lebt und oben auf Jintha'Alor gefangen gehalten wird, der Hauptstadt der Vilebranch im südlichen Hinterlands. Primal Torntusk fürchtet, dass das Dorf seinen Verlust nicht verkraften könnte."},{t="Der gesichtslose Blutgott",b="Es heißt, dass Vile Priestess Hexx den Älteren Torntusk auf die Opferung an Hakkar, den gesichtslosen Blutgott, vorbereitet."},{t="Sobald Ihr ihn erreicht",b="Der Ältere Torntusk ist in Reichweite, doch die Wachen wissen sicher schon von Eurer Ankunft. Beeilt Euch."}},faq={{q="Wer hat den Älteren Torntusk entführt?",a="Vilebranch-Wilde entführten den Älteren Torntusk bei einem kühnen mitternächtlichen Überfall auf Revantusk.",al={"wer hat den älteren torntusk entführt","wer hat torntusk verschleppt","entführer von torntusk"}},{q="Wo wird der Ältere Torntusk gefangen gehalten?",a="Primal Torntusks Spione berichten, dass der Ältere Torntusk oben auf Jintha'Alor gefangen gehalten wird, der Hauptstadt der Vilebranch im südlichen Hinterlands.",al={"aufenthaltsort des älteren torntusk","wo ist der ältere torntusk","wo ist torntusk gefangen"}},{q="Welches Schicksal erwartet den Älteren Torntusk oben auf Jintha'Alor?",a="Die Opferung. Es heißt, dass Vile Priestess Hexx den Älteren Torntusk als Opfergabe für Hakkar, den gesichtslosen Blutgott, vorbereitet.",al={"warum wurde torntusk gefangen genommen","was wollen die vilebranch von torntusk","hexx opferung torntusk"}},{q="Wer ist Primal Torntusk?",a="Primal Torntusk ist die Gefährtin des Älteren Torntusk und bittet Euch, ihn zu retten.",al={"wer ist primal torntusk","primal torntusk gefährte"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="Erlangt den Schlüssel!",s="In Jintha'Alor liegt Älterer Torntusk in Ketten und bittet Euch, ihn zu befreien. Hitah'ya the Keeper hat seinen Schlüssel in einer bewachten Höhle in der Nähe.",h="In Jintha'Alor liegt Älterer Torntusk in Ketten und bittet Euch, ihn zu befreien.",kw={"älterer torntusk","hinterlands","hitah'ya the keeper","jintha'alor","erlangt den schlüssel","revantusk","fesselschlüssel"},sec={{t="Die Höhle der Hüterin",b="Nach Kidnapped Elder Torntusk! findet Ihr Älteren Torntusk in Jintha'Alor in Ketten. Hitah'ya the Keeper verwahrt den Schlüssel zu seinen Fesseln in einer nahen Höhle, wo sie gut bewacht wird. Älterer Torntusk bittet Euch, sie zu töten und den Schlüssel zurückzubringen. Dann kann er seine Fesseln lösen und nach Hause zurückkehren."},{t="Älteren Torntusks Dank",b="Mit dem Schlüssel erhebt sich Älterer Torntusk. Er dankt Euch und sagt, die Revantusk werden von Euren Taten erfahren."}},faq={{q="Wer hat den Schlüssel zu den Fesseln des Älteren Torntusk?",a="Hitah'ya the Keeper hat den Schlüssel zu den Fesseln des Älteren Torntusk. Er sagt, sie sei in einer nahen Höhle, wo sie gut bewacht wird.",al={"wer hat den schlüssel","hitahya the keeper","wo ist der fesselschlüssel"}},{q="Wo wird Älterer Torntusk gefangen gehalten?",a="Älterer Torntusk wird in Jintha'Alor gefangen gehalten.",al={"wo ist älterer torntusk","torntusks standort","jintha'alor torntusk"}},{q="Warum braucht Älterer Torntusk den Schlüssel?",a="Der Schlüssel öffnet die Fesseln des Älteren Torntusk. Er sagt, er könne nach Hause zurückkehren, sobald er frei sei.",al={"warum der fesselschlüssel","wofür ist der schlüssel"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="Rückkehr zu Primal Torntusk",s="Älterer Torntusk ist frei und schickt Euch mit Nachricht für seine Gefährtin Primal Torntusk nach Revantusk.",h="Älterer Torntusk ist frei und schickt Euch mit Nachricht für seine Gefährtin Primal Torntusk nach Revantusk.",kw={"älterer torntusk","hinterland","jintha'alor","primal torntusk","revantusk"},sec={{t="Nachricht für seine Gefährtin",b="Älterer Torntusk ist von seinen Fesseln befreit und bittet Euch, nach Revantusk zurückzukehren. Sagt seiner Gefährtin Primal Torntusk, dass er nach Hause kommt."},{t="Das Dorf ist dankbar",b="Primal Torntusk dankt Euch für Eure Dienste für die Revantusk. Das Dorf ist Euch zu tiefem Dank verpflichtet."}},faq={{q="Wer schickt Euch auf diese Reise?",a="Älterer Torntusk schickt Euch, um seiner Gefährtin die Nachricht von seiner Rettung zu überbringen.",al={"wer startet rückkehr zu primal torntusk","älterer torntusk questgeber"}},{q="Wo befindet sich Primal Torntusk?",a="Primal Torntusk ist in Revantusk im Hinterland.",al={"wo ist primal torntusk","primal torntusk standort","wo rückkehr zu primal torntusk abgeben"}},{q="Was soll ich Primal Torntusk sagen?",a="Sagt Primal Torntusk, dass Älterer Torntusk nach Hause kommt.",al={"was primal torntusk sagen","torntusk nachricht"}},{q="Was ging dieser Reise voraus?",a="Dies folgt auf Recover the Key!, nach den früheren Bemühungen, die mit Kidnapped Elder Torntusk! begannen.",al={"vorherige quest","primal torntusk questreihe"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="Die getrennten Brüder",s="Jäger Markhor trauert in Revantusk um seinen Zwilling Malkhor. Die Vilebranch verschleppten Malkhor bei dem Überfall, bei dem sie auch Torntusks Gefährtin entführten. Markhor glaubt, dass Malkhors Seele noch gerettet werden kann, obwohl sein Leben nicht mehr zu retten ist. Deshalb bittet er Euch, die sterblichen Überreste zu bergen.",h="Jäger Markhor trauert in Revantusk um seinen Zwilling Malkhor.",kw={"knochen","hinterlands","jintha'alor","malkhor","markhor","revantusk","schädel","vilebranch","yayo'jin"},sec={{t="Der Verlust eines Zwillings",b="Viele in Revantusk haben geliebte Menschen an die Wildnis verloren, sagt Markhor. Er selbst trauert um seinen Zwillingsbruder Malkhor. Die Vilebranch verschleppten Malkhor bei dem Überfall, bei dem sie auch Torntusks Gefährtin entführten. Seine Entführer töteten ihn schnell und brutal; ihm war es nicht bestimmt, weiterzuleben."},{t="Wo die Überreste liegen",b="Die Vilebranch verfütterten Malkhors sterbliche Überreste an ihre Schlämme und Wölfe. Nahe der Spitze des Tempels von Jintha'Alor liegen eine mit Schlämmen gefüllte Abfallgrube und ein Wolfsbau. Seine Knochen ruhen in einer Schlammgrube nahe der obersten Ebene, während sein Schädel auf der Ebene selbst liegt. Markhor will die sterblichen Überreste zu Yayo'jin bringen, die sie für ein ordentliches Begräbnis vorbereiten wird."}},faq={{q="Wer war Jäger Malkhor?",a="Malkhor war der Zwillingsbruder von Jäger Markhor. Die Vilebranch verschleppten ihn bei dem Überfall, bei dem sie auch Torntusks Gefährtin entführten, und töteten ihn dann schnell und brutal.",al={"wer ist malkhor","markhors bruder","malkhors geschichte"}},{q="Wohin wurden Malkhors sterbliche Überreste gebracht?",a="Die Vilebranch verfütterten Malkhors sterbliche Überreste an ihre Schlämme und Wölfe. Sein Schädel liegt auf der obersten Ebene von Jintha'Alor, während seine Knochen in einer Schlammgrube nahe dieser Ebene ruhen.",al={"wo sind die knochen","wo ist malkhors schädel","jintha'alor überreste"}},{q="Wer wird Malkhor für das Begräbnis vorbereiten?",a="Markhor wird Malkhors sterbliche Überreste zu Yayo'jin bringen, die sie für ein ordentliches Begräbnis vorbereiten wird.",al={"begräbnis für malkhor","wer ist yayojin","yayo'jin"}},{q="Warum braucht Markhor die Knochen zurück?",a="Markhor sagt, dass Malkhors Leben nicht mehr zu retten ist, seine Seele aber noch gerettet werden kann. Er möchte die sterblichen Überreste bergen lassen, damit Malkhors Seele gerettet werden kann.",al={"warum überreste bergen","malkhors seele retten","seine seele retten"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="Dunkle Gefäße",s="In Revantusk berichtet Primal Torntusk, dass die Vilebranch mit einer übernatürlichen Wildheit kämpfen. Er macht die finstere Magie von Vile Priestess Hexx dafür verantwortlich und bittet Euch, die Gefäße mit verdorbenem Blut aus Jintha'alor zu holen, damit er sie reinigen kann.",h="In Revantusk berichtet Primal Torntusk, dass die Vilebranch mit einer übernatürlichen Wildheit kämpfen.",kw={"blutgott","dunkle gefäße","jintha'alor","primal torntusk","revantusk","verdorbenes blut","vile priestess hexx","vilebranch"},sec={{t="Die Wildheit der Vilebranch",b="In ganz Jintha'alor bergen Gefäße mit verdorbenem Blut die Macht des gesichtslosen Blutgottes. Diese Macht stärkt die Vilebranch und treibt sie in den Wahnsinn. Torntusk glaubt, dass das Entfernen und Reinigen der Gefäße den Griff des Blutgottes auf die Trolle lockern wird."},{t="Nach Rückkehr der Gefäße",b="Die Rückgabe der Gefäße beseitigt die dunkle Energie, die die Vilebranch antreibt, wenn auch nur vorerst. Torntusk mahnt Euch, nach dem Bösen Ausschau zu halten, denn eine gefallene Priesterin wird bald durch eine andere ersetzt."}},faq={{q="Wer vergibt die Quest Dunkle Gefäße?",a="Primal Torntusk bittet Euch in Revantusk im Hinterland darum.",al={"wer vergibt dunkle gefäße","dunkle gefäße questgeber"}},{q="Wo befinden sich die Gefäße mit verdorbenem Blut?",a="Die Gefäße mit verdorbenem Blut liegen in ganz Jintha'alor im Hinterland.",al={"wo sind dunkle gefäße","gefäße mit verdorbenem blut fundort","verdorbenes blut finden"}},{q="Warum sind die Trolle der Vilebranch so wild?",a="Primal Torntusk macht die finstere Magie von Vile Priestess Hexx dafür verantwortlich. Die Gefäße mit verdorbenem Blut bergen auch die Macht des gesichtslosen Blutgottes, die die Vilebranch stärkt und in den Wahnsinn treibt.",al={"warum sind vilebranch wahnsinnig","wahnsinn der vilebranch","wildheit der vilebranch"}},{q="Was hat Primal Torntusk mit den Gefäßen vor?",a="Torntusk will die Gefäße reinigen und den Griff des gesichtslosen Blutgottes auf die Vilebranch lockern.",al={"warum die gefäße sammeln","was geschieht mit den blutgefäßen"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
P.entries["quest:786"] = {n="Vereitelung der Kolkaraggression",s="Vereitelung der Kolkaraggression ist eine wichtige Verteidigungsmission der Horde, die vom Späher Lar Lauerzahn nahe Sen'jin vergeben wird. Spieler erhalten den Auftrag, die Kolkarklippe zu infiltrieren, um drei Sätze koordinierter Invasionspläne zu vernichten, bevor der Zentaurenklan die jungen Siedlungen von Durotar überfallen kann.",h="Vereitelung der Kolkaraggression ist eine wichtige Verteidigungsmission der Horde, die vom Späher Lar...",kw={"durotar","kolkar","kolkarklippe","lar lauerzahn","orgrimmar","sen'jin","vereitelung der kolkaraggression","das tal der prüfungen"},ang={["faction:Horde"]="Das Stoppen der Kolkar-Offensive bewahrt die junge Horde davor, direkt vor der Schwelle ihrer neuen Heimat einen zermürbenden Gebietskrieg an mehreren Fronten führen zu müssen.",["race:Orc"]="Im Tal der Prüfungen vollziehen junge Orcs ihre Riten des Erwachsenwerdens, weshalb eine Zentaurenaggression dort eine existenzielle Beleidigung der orcischen Kriegerkultur darstellt.",["race:Troll"]="Nachdem sie bereits ihre uralte Inselheimat verloren haben, können es sich die Dunkelspeere nicht leisten, dass Sen'jin von marodierenden Zentauren überrannt wird."},sec={{t="Eine drohende Invasion",b="Beim Auskundschaften des westlichen Durotar schlich sich der Trollfährtenleser Lar Lauerzahn im Schutz der Nacht in die Kolkarklippe. Was er entdeckte, war alarmierend: Die Kolkar-Zentauren führten nicht bloß unorganisierte Überfälle an der Küste durch, sondern koordinierten eine ehrgeizige, dreigliedrige Invasion, die direkt auf die Heimat der Orcs und Dunkelspeere abzielte. Die Kriegsfürsten der Zentauren teilten ihre Schlachtstrategien unter drei verschiedenen Anführern auf, um das Tal der Prüfungen, Sen'jin und die Gates of Orgrimmar selbst anzugreifen."},{t="Schlag in die Schluchten",b="Um katastrophale Kämpfe in den trockenen roten Schluchten von Durotar abzuwenden, werden Rekruten tief in die Kolkarklippe geschickt, um der Schlange den Kopf abzuschlagen. Das Infiltrieren des staubigen Lagers und das Verbrennen der drei Angriffsschriftrollen zerschlägt die Befehlskette der Zentauren. Während Lar Lauerzahn zuversichtlich bleibt, dass die Horde jede Großinvasion unweigerlich zerschmettern würde, erspart die Zerstörung dieser Dokumente den Verteidigern Durotars ein kostspieliges Blutvergießen, solange ihre junge Nation noch um Halt ringt."}},faq={{q="Wer bietet die Quest Vereitelung der Kolkaraggression an?",a="Die Quest wird von Lar Lauerzahn vergeben, einem Späher der Dunkelspeer, der direkt außerhalb von Sen'jin an den südlichen Klippen von Durotar stationiert ist.",al={"questgeber","wer gibt die quest","lar lauerzahn aufenthaltsort"}},{q="Welche Ziele planen die Kolkar-Zentauren anzugreifen?",a="Die Schlachtpläne der Kolkar skizzieren eine koordinierte, dreistufige Offensive, die auf das Tal der Prüfungen, Sen'jin und die Hordehauptstadt Orgrimmar abzielt.",al={"zentauren ziele","was sind die angriffspläne","drei ziele"}},{q="Wo befindet sich die Kolkarklippe?",a="Die Kolkarklippe ist ein sonnendurchfluteter Schluchtenkomplex, der westlich über den felsigen Kämmen von Sen'jin im südlichen Durotar liegt.",al={"kolkarklippe standort","wo ist die klippe","zentaurendorf durotar"}},{q="Wo sind die Angriffspläne in der Klippe zu finden?",a="Die drei Schriftrollen mit den Invasionsplänen befinden sich im Besitz von drei verschiedenen Anführern der Kolkar, die unterschiedliche Lagerplätze in der Klippe bewachen.",al={"fundorte der angriffspläne","wo sind die schriftrollen","anführer der kolkar"}},{q="Warum wollen die Kolkar in Durotar einmarschieren?",a="Die Kolkar sind ein aggressiver, expansiver Zentaurenklan, der in den trockenen Gebieten von Kalimdor beheimatet ist. Sie betrachten die ankommenden Orcs und Dunkelspeer als Eindringlinge, die ihr Territorium und ihre Jagdgründe verletzen.",al={"warum greifen zentauren an","zentauren motiv","kolkar hintergrund"}},{q="Was geschieht, nachdem die Pläne zerstört wurden?",a="Die Zerstörung der Dokumente verhindert eine koordinierte Belagerung, stürzt die taktische Offensive der Kolkar ins Chaos und bewahrt Durotars zerbrechliche Siedlungen vor plötzlicher Verwüstung.",al={"quest nachwirkungen","stoppt der zentaurenangriff"}}},fx={a839716d={q="Warum will Lar Lauerzahn, dass die Angriffspläne zerstört werden?",a="Lar Lauerzahn hat die Kolkarklippe ausgekundschaftet und herausgefunden, dass die Zentauren eine dreizackige Invasion planen, die auf Sen'jin, das Tal der Prüfungen und Orgrimmar selbst abzielt. Obwohl die Horde einen solchen Angriff letztendlich zerschlagen würde, will Lauerzahn ihre Operationspläne verbrennen lassen, um die Invasion zu stoppen, bevor sie beginnt, und den Verteidigern von Durotar unnötiges Blutvergießen und Störungen ersparen.",al={"warum angriffspläne zerstören","lar lauerzahn motiv","warum kolkar-aggressionen vereiteln"}},["4d134dbe"]={q="Wer sind die Kolkar-Zentauren in der Kolkarklippe?",a="Die Kolkar sind ein brutaler Zentaurenclan, der eine Festung in den Klippen entlang des westlichen Bergrückens von Durotar errichtet hat. Sie sind wild und territorial, hegen tiefen Hass auf die neu angekommenen Orcs und Dunkelspeertrolle, starten regelmäßig Überfälle aus ihrem Lager und schmieden Pläne, um die Horde vollständig aus der Region zu vertreiben.",al={"wer sind die kolkar hier","kolkarklippe zentauren","warum sind kolkar in durotar"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="GESUCHT: Üble Priesterin Hexx und ihre Diener",s="Primal Torntusk hat Euch nach Jintha'Alor geschickt, um die Üble Priesterin Hexx und ihre Diener ihrer gerechten Strafe zuzuführen. Er bietet eine stattliche Belohnung dafür, Hexx und ihre elitäre Aman'zasi-Garde zu erschlagen.",h="Primal Torntusk hat Euch nach Jintha'Alor geschickt, um die Üble Priesterin Hexx und ihre Diener ihrer...",kw={"aman'zasi","hexx","hinterland","jintha'alor","primal torntusk","revantusk","üble priesterin hexx","vilebranch"},sec={{t="Ein Schlag gegen Jintha'Alor",b="Primal Torntusk schickt Euch gegen die Üble Priesterin Hexx und ihre Diener aus. Sie befinden sich auf den Höhen von Jintha'Alor im Hinterland, wo Hexx' elitäre Aman'zasi-Wachen ihr zur Seite stehen. Erschlagt sie und erstattet dann Torntusk in Revantusk Bericht."}},faq={{q="Wer hat das Kopfgeld auf die Üble Priesterin Hexx ausgesetzt?",a="Primal Torntusk hat das Kopfgeld ausgesetzt und bietet eine stattliche Belohnung dafür, die Priesterin und ihre Garde zu erschlagen.",al={"wer will hexx tot sehen","wer hat dieses kopfgeld ausgesetzt","priesterin hexx questgeber"}},{q="Wo sind die Üble Priesterin Hexx und ihre Wachen zu finden?",a="Die Üble Priesterin Hexx und ihre Wachen befinden sich auf den Höhen von Jintha'Alor im Hinterland.",al={"wo ist hexx","üble priesterin hexx fundort","amanzasi-wachen fundort"}},{q="Wer muss für das Kopfgeld erschlagen werden?",a="Erschlagt Priesterin Hexx und ihre elitäre Aman'zasi-Garde der Vilebranch.",al={"hexx kopfgeld ziele","wen für hexx töten"}},{q="Wo wird das Kopfgeld abgeholt?",a="Nachdem Ihr die Priesterin und ihre Garde erschlagen habt, erstattet Primal Torntusk in Revantusk Bericht.",al={"wo hexx kopfgeld abholen","primal torntusk standort"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="Offener Posten: Wachbefehlshaber von Revantusk",s="Revantusk braucht einen neuen Anführer für seine Wache. Bewerber müssen sich gegen vier Arten der Vilebranch beweisen und Primal Torntusk eine Bewerbung überbringen.",h="Revantusk braucht einen neuen Anführer für seine Wache.",kw={"berserker","blood drinker","wachbefehlshaber","malkhor","revantusk","shadow hunter","soul eater","torntusk","vilebranch"},sec={{t="Ein unbesetzter Posten",b="Guard Captain Malkhor ist verschollen, und damit steht die Wache von Revantusk erneut ohne Hauptmann da. Der Aushang ruft alle, die die Wache anführen wollen, dazu auf, die beschriebene Arbeit zu erledigen und Primal Torntusk eine Bewerbung zu schicken."},{t="Die Eignung beweisen",b="Um Euch um den Hauptmannsposten zu bewerben, besiegt Berserker, Shadow Hunter, Blood Drinker und Soul Eater der Vilebranch. Kehrt dann zu Primal Torntusk in Revantusk zurück."}},faq={{q="Warum ist der Posten des Wachbefehlshabers frei?",a="Guard Captain Malkhor ist verschollen, wodurch der Hauptmannsposten erneut unbesetzt ist.",al={"warum ist der posten des wachbefehlshabers frei","was ist mit malkhor passiert","wer war der vorherige hauptmann"}},{q="Wer erhält die Bewerbung, sobald die Feinde erschlagen sind?",a="Bringt die Bewerbung zu Primal Torntusk in Revantusk.",al={"bei wem abgeben","wo bewerbung einreichen","wer beurteilt die bewerber"}},{q="Welche Feinde müssen besiegt werden, um sich zu qualifizieren?",a="Bewerber müssen Berserker, Shadow Hunter, Blood Drinker und Soul Eater der Vilebranch besiegen.",al={"welche vilebranch töten","ziele der stellenausschreibung","wen für den posten des wachbefehlshabers töten"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:78676"] = {n="The Eye of Bhossca",s="C schickt Euch auf die Suche nach dem Eye of Bhossca, das im Scharlachroten Kloster liegen soll. Das Artefakt soll zu einem toten Briefkasten nahe Lohenscheit gebracht werden.",h="C schickt Euch auf die Suche nach dem Eye of Bhossca, das im Scharlachroten Kloster liegen soll.",kw={"artefakt","bhossca","c","toter briefkasten","verkleidung","eye of bhossca","lohenscheit","das scharlachrote kloster"},sec={{t="Der Auftrag von C",b="Eine Notiz in der Truhe enthält einen neuen Auftrag von C nahe Lohenscheit. Das Eye of Bhossca soll sich irgendwo im Scharlachroten Kloster befinden, und C will, dass Ihr es zurückbringt. Wie in Burg Shadowfang sollt Ihr allein hineingehen. Eine Verkleidung auf dem Klostergelände könnte Euch den Weg erleichtern."}},faq={{q="Wer verlangt nach dem Eye?",a="C bittet Euch, das Eye of Bhossca zu holen und zu einem toten Briefkasten nahe Lohenscheit zu bringen.",al={"wer will es","wer ist c","cs auftrag zum eye"}},{q="Wo befindet sich das Eye of Bhossca?",a="Laut Cs Quellen befindet sich das Eye of Bhossca irgendwo im Scharlachroten Kloster.",al={"wo ist das eye","fundort des eye","bhossca finden"}},{q="Warum will C das Eye?",a="C bezeichnet das Eye of Bhossca als Artefakt und sagt, es sei das neueste Objekt der Begierde.",al={"warum das eye","wofür will c es","warum es holen"}},{q="Wohin soll ich das Eye bringen?",a="Ihr sollt das Eye zu Cs totem Briefkasten nahe Lohenscheit zurückbringen.",al={"wohin zurückbringen","ort des toten briefkastens","wo ist die truhe"}},{q="Muss ich allein gehen?",a="C verlangt, dass Ihr allein ins Scharlachrote Kloster geht und den Auftrag allein erledigt.",al={"allein?","kann ich hilfe mitbringen","eye allein holen"}},{q="Würde eine Verkleidung helfen?",a="C sagt, eine Verkleidung könnte Euch die Fortbewegung erleichtern und schlägt vor, auf dem Klostergelände danach zu suchen.",al={"verkleidung für das eye","verkleidung nötig","wo ist die verkleidung"}}},fp="18,145,11.282.0,26.92.0,28.76.0,24.82.0,24.65.0,22.79.0,22.105.0"}
P.entries["quest:78699"] = {n="The Eye of Bhossca",s="Eine Notiz für Euch liegt in einer Truhe. Der Verfasser unterschreibt nur mit dem Anfangsbuchstaben C.",h="Eine Notiz für Euch liegt in einer Truhe.",kw={"bhossca","c","truhe","eye of bhossca","ausschau halten","notiz"},sec={{t="Die Notiz",b="In einer Truhe liegt eine Notiz an Euch. Darin steht, man werde nach Euch Ausschau halten. Unterschrieben ist sie mit dem Buchstaben C."}},faq={{q="Wer hat die Notiz hinterlassen?",a="Die Notiz ist mit dem Anfangsbuchstaben C unterschrieben; ein vollständiger Name steht nicht darin.",al={"wer ist c","wer hat es geschrieben","notiz von c"}},{q="Was steht in der Notiz?",a="Der Verfasser schreibt, man werde nach Euch Ausschau halten, und unterschreibt mit dem Anfangsbuchstaben C.",al={"was ist in der truhe","notiz zu eye of bhossca","was hat c geschrieben"}},{q="Wo ist die Notiz?",a="Die Notiz liegt in einer Truhe.",al={"wo ist die notiz","notiz in der truhe"}}},fp="18,74,8.119.0,18.61.0,23.84.0,18.25.0"}
P.entries["quest:787"] = {n="Die neue Horde",s="Im Tal der Prüfungen ruft Etrigg die neuesten Rekruten der Horde zum Den. Er schickt Euch zur Ausbildung zu Gornek und erklärt, warum er zur Horde zurückkehrte und was sie nach Thralls Hoffnung werden kann.",h="Im Tal der Prüfungen ruft Etrigg die neuesten Rekruten der Horde zum Den.",kw={"brennende legion","durotar","etrigg","gornek","neue horde","the den","thrall","das tal der prüfungen"},ang={["faction:Horde"]="Für die Horde bedeutet Thralls Herrschaft die Abkehr von dämonischer Knechtschaft und die Rückkehr zu Ehre, Überleben und der Identität ihrer Ahnen.",["race:Orc"]="Als Orc begegnet Ihr beim Betreten des Tals der Prüfungen Etrigg, der sich an die tragische Vergangenheit Eures Volkes und seine Erlösung unter Thrall erinnert.",["race:Troll"]="Als Troll der Dunkelspeer werdet Ihr im Tal der Prüfungen an der Seite der Orcs ausgebildet und teilt Thralls Vision von Überleben und Ehre."},sec={{t="Die Rückkehr eines Veteranen",b="Auf Befehl von Kriegshäuptling Thrall wacht Etrigg im Tal der Prüfungen über die neuesten Hoffnungsträger. Nach dem Zweiten Krieg verließ er die Alte Horde, angewidert von ihrer Verderbnis unter der Brennenden Legion. Er lebte im stillen Exil, bis Menschen ihn gefangen nahmen. Thrall rettete Etrigg, und der Veteran kehrte zurück, als er vom Traum des jungen Kriegshäuptlings erfuhr: eine ehrenhafte Horde, verwurzelt im Schamanismus der Ahnen und frei von dämonischen Meistern."},{t="Meldung im Den",b="Bevor Ihr die rauen Schluchten des Tals der Prüfungen verlasst, schickt Etrigg Euch in die schattige Höhle namens Den, um mit Gornek zu sprechen. Gornek spricht unverblümt darüber, wie ungeschliffen neue Anwärter sind. Er wacht über ihre Ausbildung, damit nur jene die weiteren Gebiete von Durotar erreichen, die Disziplin und Überleben meistern."}},faq={{q="Wer ist Etrigg?",a="Etrigg ist ein alternder Orcveteran, der miterlebte, wie die Alte Horde der Verderbnis der Brennenden Legion verfiel. Desillusioniert zog er sich ins stille Exil in Lordaeron zurück. Menschen nahmen ihn gefangen, und Thrall befreite ihn später. Etrigg schwor Thralls erneuerter Horde die Treue und hilft nun bei der Ausbildung von Rekruten im Tal der Prüfungen.",al={"wer ist etrigg","etriggs vorgeschichte","etriggs geschichte"}},{q="Warum spricht Etrigg von der „neuen Horde“?",a="Die ursprüngliche Horde verfiel dämonischem Blutdurst und dem Einfluss der Brennenden Legion. Thralls neue Horde lehnte dämonische Kontrolle ab, stellte die alten schamanischen Bräuche wieder her und strebte eine ehrenhafte, unabhängige Zukunft für Orcs und ihre Verbündeten in Kalimdor an.",al={"was ist die neue horde","unterschied zwischen alter und neuer horde","bedeutung der neuen horde"}},{q="Wo befindet sich Gornek?",a="Gornek wartet gleich hinter dem Eingang zum Den, einer markanten Höhle in der nördlichen Felswand des Tals der Prüfungen.",al={"wo ist gornek","gornek finden","gorneks standort"}},{q="Was geschieht nach der Meldung bei Gornek?",a="Nachdem Ihr Euch bei Gornek gemeldet habt, nimmt er Euch als einen von Etriggs Lehrlingen an und gibt Euch Eure ersten Aufträge im Gelände. Ihr verteidigt das Tal und beweist, dass Ihr bereit seid, der Horde zu dienen.",al={"nächste quest nach die neue horde","was macht gornek","gorneks quest"}},{q="Warum lebte Etrigg im Exil?",a="Etrigg verließ die Horde aus Abscheu vor ihrer dämonischen Verderbnis und dem sinnlosen Gemetzel, das Hexenmeister im Dienst der Brennenden Legion während der früheren Kriege vorantrieben.",al={"warum ging etrigg fort","grund für etriggs exil","etrigg dämonische verderbnis"}},{q="Warum werden Rekruten im Tal der Prüfungen ausgebildet?",a="Das Tal der Prüfungen bietet jungen Orcs und verbündeten Neuankömmlingen einen abgeschiedenen, rauen Ort in Durotar, um sich unter der Aufsicht erfahrener Ausbilder gefährlichen Bestien und Skorpiden zu stellen, bevor sie in die weite Welt aufbrechen.",al={"warum tal der prüfungen","zweck des tals der prüfungen","ausbildung im tal der prüfungen"}}},fx={["42eb0b46"]={q="Warum schickt Euch Etrigg zu Gornek?",a="Kriegshäuptling Thrall hat Etrigg damit beauftragt, die Ausbildung aller neuen Rekruten zu beaufsichtigen, die im Tal der Prüfungen ankommen. Während Etrigg Neuankömmlinge begrüßt und ihnen die Ideale einer von dämonischer Verderbnis befreiten Horde vermittelt, kümmert sich Gornek um die praktischen, handfesten Aufgaben, die notwendig sind, um Euch zu prüfen und abzuhärten. Etrigg schickt Euch zu ihm, damit Eure Prüfung und Ausbildung offiziell beginnen kann.",al={"warum gornek aufsuchen","etrigg motiv","warum bei gornek melden"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:7881"] = {n="Carnival Boots",s="Die Arbeiter des Dunkelmond-Jahrmarkts suchen bei geschickten Handwerkern robustes Schuhwerk. Für erstklassige Stiefel geben die Jahrmarktsmitarbeiter begehrte Jahrmarktscheine heraus.",h="Die Arbeiter des Dunkelmond-Jahrmarkts suchen bei geschickten Handwerkern robustes Schuhwerk.",kw={"jahrmarkt","jahrmarktstiefel","handwerkskunst","dunkelmond-jahrmarkt","schein des dunkelmond-jahrmarkts"},sec={{t="Schuhwerk für den Jahrmarkt",b="Sammler und Handwerker bringen robuste Jahrmarktstiefel zum Dunkelmond-Jahrmarkt, wo die Mitarbeiter des Jahrmarkts begehrte Scheine gegen erstklassige Arbeit eintauschen. Jedes Paar hilft dem reisenden Jahrmarkt, auf den Beinen zu bleiben."}},faq={{q="Warum braucht der Dunkelmond-Jahrmarkt Stiefel?",a="Der Dunkelmond-Jahrmarkt nimmt robustes, gut verarbeitetes Schuhwerk an, um seine Mitarbeiter und das Jahrmarktgelände zu unterstützen, und bietet im Tausch Preisscheine an.",al={"zweck der jahrmarktstiefel","warum stiefel für den dunkelmond-jahrmarkt"}},{q="Wofür werden die Scheine des Dunkelmond-Jahrmarkts verwendet?",a="Die auf dem Jahrmarkt verdienten Scheine lassen sich sammeln und gegen verschiedene Preise und Kuriositäten des Dunkelmond-Jahrmarkts eintauschen.",al={"was gibt es für scheine des dunkelmond-jahrmarkts","zweck der jahrmarktscheine"}},{q="Welche Art von Stiefeln nimmt der Jahrmarkt an?",a="Die Mitarbeiter des Jahrmarkts prüfen die Stiefel auf erstklassige Verarbeitung und Haltbarkeit, bevor sie Scheine herausgeben.",al={"stiefeltausch beim dunkelmond-jahrmarkt","anforderungen an jahrmarktstiefel"}}},fp="14,153,22.199.0,39.134.0,41.110.0,44.106.0"}
P.entries["quest:78823"] = {n="Terror of the Desert Skies",s="Eine grobe Zeichnung zeigt einen großen Greifvogel, der Furcht und Ehrfurcht einflößte. Hemet Nesingwary im Schlingendorntal weiß vielleicht mehr über ihn.",h="Eine grobe Zeichnung zeigt einen großen Greifvogel, der Furcht und Ehrfurcht einflößte.",kw={"greifvogel","hemet nesingwary","primitive drawing","schlingendorntal","schrecken des wüstenhimmels"},sec={{t="Ein furchterregendes Bild",b="Die Primitive Drawing erreicht Euch mit der Bitte, sie zu Hemet Nesingwary ins Schlingendorntal zu bringen. Ihre breiten Striche zeigen einen großen Greifvogel, und die Furcht und Ehrfurcht des Künstlers sind im Bild deutlich zu erkennen. Hemet soll beurteilen, was darauf abgebildet ist."}},faq={{q="Was zeigt die Zeichnung?",a="Die Primitive Drawing zeigt einen großen Greifvogel.",al={"vogelzeichnung","was ist auf dem bild"}},{q="Wer kann mir etwas über den Vogel erzählen?",a="Hemet Nesingwary im Schlingendorntal kann Euch vielleicht mehr über das Tier erzählen.",al={"wer weiß etwas darüber","vogelexperte"}},{q="Wohin soll ich die Zeichnung bringen?",a="Bringt die Primitive Drawing zu Hemet Nesingwary ins Schlingendorntal.",al={"wohin die zeichnung bringen","hemet zeichnung"}}},fp="26,133,15.242.0,27.51.0,31.87.0,28.70.0"}
P.entries["quest:78830"] = {n="Terror of the Desert Skies",s="Hemet Nesingwary hat von Gharrik gehört, einem großen Vogel, der im Ödland jagt. Er leiht Euch einen Käfig für lebende Köder und hofft auf eine ihrer Federn.",h="Hemet Nesingwary hat von Gharrik gehört, einem großen Vogel, der im Ödland jagt.",kw={"ödland","camp cagg","rote trophäenfeder","gharrik","großer vogel","hemet nesingwary","lebende köder"},sec={{t="Ein Wüstenjäger",b="Eine Zeichnung erinnert Hemet Nesingwary an Gharrik, von der er auf einer früheren Expedition gehört hat. Der große Vogel soll als Spitzenprädatorin über das Ödland herrschen. Ihr sollt nordöstlich von Camp Cagg nach ihr suchen, wo sie zuletzt gesichtet wurde, und sie mit lebenden Ködern hervorlocken. Im Ödland gibt es nur wenige Kleintiere, deshalb leiht Hemet Euch einen Käfig, damit Ihr anderswo Köder fangen könnt. Er hofft auf eine von Gharriks Federn."}},faq={{q="Wer ist Gharrik?",a="Gharrik ist ein großer Vogel, der als Spitzenprädatorin im Ödland gilt.",al={"gharrik vogel","wüstenvogel","wer ist gharrik"}},{q="Wo wurde Gharrik zuletzt gesehen?",a="Gharrik wurde zuletzt nordöstlich von Camp Cagg im Ödland gesichtet.",al={"gharriks aufenthaltsort","wo ist gharrik","nordöstlich von camp cagg"}},{q="Warum möchte Hemet eine Feder?",a="Hemet sagt, eine Feder von Gharrik wäre ein schöner Preis und würde Euch im Lager zum Gesprächsthema machen.",al={"gharriks feder","feder als preis","warum eine feder"}},{q="Wo findet Ihr Köder?",a="Im Ödland gibt es nur wenige Kleintiere. Hemet sagt, Ihr sollt anderswo lebende Köder finden, und leiht Euch einen Käfig, damit Ihr welche fangen könnt.",al={"lebende köder","köder für gharrik","köderkäfig"}},{q="Wer hat mich auf Gharrik angesetzt?",a="Hemet Nesingwary bittet Euch, Gharrik zu suchen und eine ihrer Federn zurückzubringen.",al={"gharriks questgeber","hemet gharrik","wer möchte die feder"}}},fp="26,142,15.407.0,15.68.0,28.64.0,28.90.0,24.119.0,26.75.0"}
P.entries["quest:789"] = {n="Stich des Skorpiden",s="Im Den im Tal der Prüfungen schickt Gornek neue Rekruten der Horde gegen Skorpide nordwestlich des Lagers aus. Zehn Schwänze sollen beweisen, dass sie sich im Kampf der Gefahr stellen können.",h="Im Den im Tal der Prüfungen schickt Gornek neue Rekruten der Horde gegen Skorpide nordwestlich des Lagers aus.",kw={"gegengift","durotar","gornek","skorpid","skorpidarbeiter","stich des skorpiden","the den","das tal der prüfungen","gift"},ang={["class:Warrior"]="Als Krieger lernt Ihr von Gornek, dass entschlossene Schläge harte Panzer überwinden können. Hochmut gegenüber kleineren Feinden führt zur Niederlage.",["race:Orc"]="Als junger Orc, der im Tal der Prüfungen erwachsen wird, stellt Ihr Euch unter Gorneks Aufsicht einer grundlegenden Prüfung Eurer Ausdauer und Wachsamkeit im Kampf.",["race:Troll"]="Als Dunkelspeertroll, der an der Seite der Horde im Tal der Prüfungen ausgebildet wird, beweist Ihr Euer Können gegen heimische Skorpide, bevor Ihr tiefer nach Durotar vordringt."},sec={{t="Prüfung des Stachels",b="Gornek stellt unerfahrene Rekruten der Horde gegen die Tierwelt im Tal der Prüfungen auf die Probe. Skorpidarbeiter streifen zwischen den Felsen nordwestlich des Den umher. Ihr Gift hat erfahrene Krieger ebenso wie ungeschickte Anfänger Demut gelehrt. Rekruten müssen sich ihnen stellen und zehn Schwänze als Beweis ihres Könnens zurückbringen."},{t="Gift und Wachsamkeit",b="Skorpide sind gefährlich, doch ihr Gift hilft auch, verletzte Anfänger zu retten. Im Den wird Gegengift aus gewonnenem Skorpidgift gebraut und vorrätig gehalten, um niedergestreckte Neulinge zu behandeln. Gornek lehrt Rekruten, im Kampf wachsam zu bleiben. Selbst ein kleiner Feind kann genug Gift besitzen, um einen mächtigen Krieger zu Fall zu bringen."}},faq={{q="Wer vergibt Stich des Skorpiden?",a="Gornek beaufsichtigt die Ausbildung der Neulinge im Den im Tal der Prüfungen. Er beauftragt junge Krieger und Abenteurer mit der Jagd.",al={"wer vergibt stich des skorpiden","skorpid questgeber","gornek quest"}},{q="Wo sind die Skorpide zu finden?",a="Skorpidarbeiter streifen nordwestlich des Den im Tal der Prüfungen umher.",al={"wo skorpide finden","skorpid fundort","skorpide im tal der prüfungen"}},{q="Was verlangt Gornek von der Jagd?",a="Gornek verlangt zehn Scorpid Worker Tails als Beweis dafür, dass ein Rekrut sich den giftigen Bestien gestellt und gesiegt hat.",al={"was lassen skorpide fallen","skorpid questgegenstand","skorpidschwänze"}},{q="Wie wird das Gegengift gegen Skorpidgift hergestellt?",a="Im Den wird Gegengift aus dem Gift gebraut, das aus Skorpidstacheln gewonnen wird. Dort werden Vorräte bereitgehalten, um Neulinge zu behandeln, die ihre Beute unterschätzen.",al={"heilmittel gegen skorpidgift","gegengift hintergrundgeschichte","wie wird skorpid-gegengift hergestellt"}},{q="Welche Lektion sollen die Rekruten von Gornek lernen?",a="Gornek lehrt Rekruten, dass jeder Gegner tödlich sein kann, ob groß oder klein. Überheblichkeit gegenüber einem scheinbar unbedeutenden Feind kann tödlich enden.",al={"gorneks lektion","warum skorpide jagen","zweck der skorpidprüfung"}},{q="Bietet Gornek nach dieser Jagd weitere Ausbildung an?",a="Nachdem Ihr die Schwänze abgeliefert habt, sagt Gornek, dass er Euch im Den nichts mehr beibringen kann. Er schickt Euch weiter nach Durotar, um der Horde zu dienen.",al={"was kommt nach stich des skorpiden","gornek nächste quest","lehrt gornek noch mehr"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:7890"] = {n="Heavy Grinding Stone",s="Ein Helfer der Faire bittet Euch, Heavy Grinding Stones zu bringen. Für Eure Lieferung erhaltet Ihr Tickets für die Faire.",h="Ein Helfer der Faire bittet Euch, Heavy Grinding Stones zu bringen.",kw={"faire","schleifsteine","heavy grinding stone","süßigkeiten","tickets"},sec={{t="Auf der Faire",b="Der Helfer der Faire dankt Euch und sagt, dass die Steine ihre Muskeln bereits wachsen lassen. Dafür erhaltet Ihr Tickets und die Warnung, nicht zu viele Süßigkeiten zu essen. Der Helfer möchte, dass Ihr stark und kampfbereit bleibt."}},faq={{q="Was möchte der Helfer?",a="Der Helfer möchte Heavy Grinding Stones.",al={"was ist heavy grinding stone","steine für die faire"}},{q="Was bekomme ich, wenn ich die Steine bringe?",a="Der Helfer gibt Euch Tickets für die Faire.",al={"steintickets","tickets für die faire"}},{q="Warum erwähnt der Helfer Süßigkeiten?",a="Der Helfer warnt Euch davor, zu viele Süßigkeiten zu essen, und sagt, dass Ihr in Form bleiben müsst, um zu kämpfen.",al={"zu viele süßigkeiten","süßigkeiten auf der faire"}}},fp="20,101,12.221.0,29.42.0,38.46.0,38.95.0"}
P.entries["quest:79"] = {n="Die Legende von Stalvan",s="In Dunkelhain beruht die Legende von Stalvan auf schlammigen Seiten und neuen Beweisen. Schankwart Smitts gibt Euch die Seiten und schickt Euch zu Kommandantin Althea Schwarzhaupt.",h="In Dunkelhain beruht die Legende von Stalvan auf schlammigen Seiten und neuen Beweisen.",kw={"dunkelhain","dämmerwald","schwarzhaupt","ermittlung","dunstmantel","schlammverschmiertes tagebuch","night watch","smitts","stalvan"},ang={["class:Paladin"]="Als Paladin bringt Ihr lange verborgene Morde ans Licht und fordert Rechenschaft für unschuldige Leben, die in den Schatten des Dämmerwalds ausgelöscht wurden.",["class:Rogue"]="Als Schurke fügt Ihr Handschriftproben aus Schenken und staubigen Truhen zusammen und spürt mit geduldiger Detektivarbeit schwer fassbare Beute auf.",["faction:Alliance"]="Als Held der Allianz helft Ihr den südlichen Gebieten, für Gerechtigkeit zu sorgen, wenn die offizielle Unterstützung aus Sturmwind ausbleibt."},sec={{t="Ein Durchbruch in Dunkelhain",b="Schankwart Smitts und Marschall Haggard untersuchten einst das Massaker an einer durchreisenden Adelsfamilie im Dämmerwald. Haggard führte damals die Wache von Sturmwind an. Am Tatort fanden sie zerrissene, schlammverschmierte Tagebuchseiten, hatten aber keine Handschriftproben oder anderen Unterlagen, um festzustellen, wer sie geschrieben hatte. So konnten die Notizen den Einsiedler, der Gerüchten zufolge in der Wildnis lebte, nicht offiziell belasten.\n\nNun verbinden Beweise aus Elwynn, Westfall und dem Dämmerwald die Handschrift mit Stalvan Dunstmantel. Aus den alten Gerüchten sind Mordbeweise geworden."},{t="Zur Night Watch",b="Kommandantin Althea Schwarzhaupt führt die Nachtwache an, während Dunkelhain Untoten, wilden Bestien und noch schlimmeren Schrecken im Wald gegenübersteht. Da das Überleben der Stadt auf dem Spiel steht, hat sie wenig Zeit für Schauermärchen oder Verdächtigungen ohne Beweise. Ihr bringt ihr Smitts' schlammverschmierte Seiten und macht damit einen alten, ungelösten Fall zur Angelegenheit der Nachtwache. Die Seiten dokumentieren ein Massaker auf dem Boden des Dämmerwalds und geben der Nachtwache Anlass, Stalvan Dunstmantel als gefährlichen Flüchtigen zu behandeln, der sich der Gerechtigkeit stellen muss."}},faq={{q="Welche Beweise hatte Schankwart Smitts die ganze Zeit?",a="Vor Jahren fanden Schankwart Smitts und Marschall Haggard zerrissene, schlammverschmierte Tagebuchseiten am Schauplatz eines Massakers an durchreisenden Adligen. Bis jetzt fehlten ihnen Handschriftproben, um zu beweisen, dass Stalvan Dunstmantel sie geschrieben hatte.",al={"smitts tagebuchseiten","schlammverschmierte tagebuchseiten","was fand smitts"}},{q="Warum hat Smitts Kommandantin Schwarzhaupt nicht früher davon berichtet?",a="Smitts und Haggard hatten keinen Beweis, der die Handschrift auf den schlammigen Seiten mit dem zurückgezogen lebenden Hauslehrer verband. Ohne diese Verbindung hatten sie nur bruchstückhafte Indizien, die sie Kommandantin Schwarzhaupt vorlegen konnten.",al={"warum so lange warten","warum die seiten geheim halten","warum sagte smitts der wache nichts"}},{q="Wer ist Kommandantin Althea Schwarzhaupt?",a="Kommandantin Althea Schwarzhaupt führt die Nachtwache an, Dunkelhains Miliz. Ihre Wachleute bewachen die Stadt und patrouillieren auf den Straßen des Dämmerwalds, um Untote und Raubtiere des Waldes abzuwehren.",al={"wer ist schwarzhaupt","althea schwarzhaupt aufgabe","kommandantin von dunkelhain"}},{q="Welches Massaker ereignete sich im Dämmerwald?",a="Vor mehreren Jahren wurde eine durchreisende Adelsfamilie im Dämmerwald niedergemetzelt. Obwohl Gerüchte ihren ehemaligen Hauslehrer Stalvan Dunstmantel beschuldigten, fehlten den örtlichen Ermittlern Beweise, um ihn anzuklagen.",al={"welches massaker","massaker an adligen","wer wurde ermordet"}},{q="Wo steht dieser Schritt innerhalb der gesamten Ermittlung?",a="Nachdem Ihr Register, Schulunterlagen und Familienkisten in drei Gebieten durchsucht habt, bringt Ihr die Beweise zu den örtlichen Behörden. Damit wird die Ermittlung zur Sache der Justiz, und die Behörden erhalten eine Grundlage, gegen Stalvan vorzugehen.",al={"stalvan questreihenabschnitt","wie weit ist die ermittlung","ist dies das ende der quest"}},{q="Warum untersucht die Nachtwache alte Verbrechen so zögerlich?",a="Dunkelhain wird täglich von umherstreifenden Monstrositäten, Worgenrudeln und Spinnen bedroht. Kommandantin Schwarzhaupt muss ihre Wachleute zur Verteidigung der Stadt einsetzen, daher braucht sie unwiderlegbare Beweise für alte Verbrechen, bevor sie jemanden dafür abstellen kann.",al={"warum ist schwarzhaupt beschäftigt","dunkelhain verteidigungspriorität","night watch prioritäten"}}},fx={["3928db26"]={q="Warum will Schankwart Smitts, dass Ihr mit Kommandantin Schwarzhaupt sprecht?",a="Smitts verfolgt die Legende von Stalvan Dunstmantel schon seit Jahren im Stillen, seitdem besuchende Adlige vor Dunkelhain abgeschlachtet wurden. Als er und Haggard damals den grausamen Tatort untersuchten, fanden sie schlammverschmierte Tagebuchseiten, konnten sie aber mangels Handschriftproben nicht mit dem Einsiedler im Wald in Verbindung bringen. Jetzt, da Eure Nachforschungen Proben zutage gefördert haben, die Stalvans Urheberschaft beweisen, besitzt Smitts endlich unwiderlegbare Beweise für die Identität des Mörders. Er möchte, dass Ihr die Wahrheit unverzüglich präsentiert, damit die Verteidiger der Stadt den Mörder offiziell zur Rechenschaft ziehen können.",al={"warum schickt smitts mich zu ebonlocke","schankwart smitts motiv","warum jetzt ebonlocke informieren"}},["225fd2ad"]={q="Warum schickt Smitts Euch, anstatt dies selbst zu melden?",a="Smitts führt die Bar in der Scarlet Raven Tavern und besaß nur ein paar lose Fragmente des ursprünglichen Gemetzels. Ihr seid die Person, die tatsächlich die Spur durch den Wald von Elwynn, Westfall und den Dämmerwald verfolgt und die Briefe und Tagebücher geborgen hat, die die Handschrift mit Stalvan Dunstmantel in Verbindung bringen. Weil Ihr die entscheidenden Hinweise entdeckt habt, die das gesamte Puzzle zusammenfügen, muss Kommandantin Schwarzhaupt den vollständigen Bericht aus erster Hand von der Person hören, die ihn bewiesen hat.",al={"warum spricht smitts nicht mit ebonlocke","warum stalvan-bericht durch mich","warum berichte ich ebonlocke"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:7900"] = {n="Torn Bear Pelts",s="Ihr bringt zerrissene Bärenfelle zu jemandem, der sie zu Plüschtieren nähen lassen will. Als Bezahlung gibt es Lose.",h="Ihr bringt zerrissene Bärenfelle zu jemandem, der sie zu Plüschtieren nähen lassen will.",kw={"bärenfelle","farbe","plüschtiere","füllung","lose","zerrissene bärenfelle"},sec={{t="Eine neue Verwendung",b="Der Empfänger will die Bärenfelle mit Füllung und Farbe zu Plüschtieren nähen lassen. Als Bezahlung bietet er Euch Lose an."}},faq={{q="Wofür sind die Bärenfelle gedacht?",a="Sie sollen mit Füllung und Farbe zu Plüschtieren genäht werden.",al={"zweck zerrissener bärenfelle","was aus fellen wird"}},{q="Was bekomme ich für die Felle?",a="Der Empfänger bietet Euch Lose als Bezahlung an.",al={"bezahlung für felle","felle lose"}},{q="Wer wird die Spielzeuge nähen?",a="Der Empfänger sagt, jemand werde die Felle zu Plüschtieren nähen.",al={"wer stellt plüschtiere her","wer näht die bären"}}},fp="15,113,9.124.0,28.69.0,28.44.0,22.62.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="An einem kürzlich genutzten Lagerplatz sind nur abkühlende Glut und verstreute Vorräte geblieben. Ein versengtes Pergament trägt ein Rätsel über die Suche nach einem Zwillingsland, den einzigen verbliebenen Hinweis.",h="An einem kürzlich genutzten Lagerplatz sind nur abkühlende Glut und verstreute Vorräte geblieben.",kw={"und der gefundene zettel","von der hitze gewellter zettel","verkohlter zettel","glut","kürzlich entzündetes feuer","verstreuter proviant","zwillingsland"},sec={{t="Glut in der Wildnis",b="Ein vor Kurzem entzündetes Lagerfeuer erlischt neben verstreutem Proviant und einem von der Hitze gewellten Stück Papier. Wer hier lagerte, ist erst kürzlich aufgebrochen, und das Pergament ist den Flammen nur knapp entgangen. Die Vorräte liegen ungeschützt da, als wäre der Reisende hastig aufgebrochen oder unterbrochen worden."},{t="Ein rätselhaftes Schriftstück",b="Der erhaltene Fetzen trägt eine einzige Anweisung: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ Weder Unterschrift noch Koordinaten oder weitere Angaben haben das Feuer überstanden. Das Rätsel ist die einzige verbliebene Spur für jeden, der es findet."}},faq={{q="Was steht auf dem Zettel, der am Lagerplatz gefunden wurde?",a="Auf dem verkohlten, von der Hitze gewellten Zettel steht: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ Er ist der einzige Hinweis, der am verlassenen Lagerplatz zurückblieb.",al={"was steht auf dem zettel","zetteltext","von der hitze gewellter zettel"}},{q="Wer hat den Zettel hinterlassen?",a="Der Verfasser des Zettels ist unbekannt. Er wurde zwischen verstreutem Proviant neben der erlöschenden Glut eines kürzlich entzündeten Lagerfeuers gefunden, was auf einen kürzlichen oder erzwungenen hastigen Aufbruch seines Verfassers oder Überbringers hindeutet.",al={"woher stammt der zettel","wer schrieb den zettel","wer machte das feuer"}},{q="Worauf bezieht sich das „Zwillingsland“?",a="Das „Zwillingsland“ auf dem Zettel bezeichnet einen übereinstimmenden oder spiegelbildlichen Ort. Der verkohlte Fetzen liefert keine weitere Erklärung, sodass Reisende seine Bedeutung selbst enträtseln müssen.",al={"was ist das zwillingsland","hinweis zum zwillingsland"}},{q="Wie folgt man den Hinweisen auf dem Zettel?",a="Der verkohlte Zettel ist Euer einziger Wegweiser, ohne dass ein Ziel auf einer Karte verzeichnet wäre. Sein Rätsel fordert Euch auf, ein Land oder einen Ort zu suchen, der seiner Beschreibung entspricht.",al={"was mit dem zettel tun","wohin führt diese quest"}},{q="Warum wurde der Lagerplatz verlassen?",a="Der Lagerplatz weist Spuren eines plötzlichen Aufbruchs oder einer Störung auf. Verstreuter Proviant liegt neben erlöschender Glut, und außer dem gewellten Fetzen sind weder Ausrüstungsgegenstände noch andere Spuren geblieben, die Aufschluss über den Reisenden geben.",al={"wer ließ den proviant zurück","verstreuter proviant am lagerplatz"}},{q="Gibt es am Feuer noch weitere Hinweise?",a="Am Lagerfeuer sind keine weiteren Schriftstücke oder Markierungen unversehrt geblieben. Die Flammen haben fast alles zerstört, sodass nur das von der Hitze gewellte Papier von demjenigen zeugt, der dort rastete.",al={"verrät das feuer noch mehr","hinweise am lagerplatz"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="Eine versengte Notiz liegt neben einem erlöschenden Lagerfeuer in Westfall. Ihre kurze Botschaft weist auf einen Ort namens Zwillingsland hin.",h="Eine versengte Notiz liegt neben einem erlöschenden Lagerfeuer in Westfall.",kw={"versengte notiz","lagerfeuer","verkohlte notiz","glut","notiz","zwillingsland","westfall"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie man rätselhafte Hinweise entschlüsselt, die an verborgenen Lagerplätzen zurückgelassen wurden. Solche Arbeit liegt jenen im Blut, die von Geflüster, Geheimnissen und versteckten Botschaften leben.",["faction:Alliance"]="Als Abenteurer der Allianz versucht Ihr, die Ordnung in Westfall wiederherzustellen, und steht vor einem weiteren Rätsel an der Grenze des Königreichs: einem Lager unbekannter Herkunft und einer rätselhaften Geheimschrift."},sec={{t="Ein erlöschendes Feuer",b="Reisende durchqueren Westfalls verlassene Felder und windgepeitschte Ebenen und finden Lager, die Landstreicher, Gesetzlose oder verzweifelte Wanderer zurückgelassen haben. Dieses kleine Lager wurde in Eile oder im Verborgenen verlassen. Die Vorräte liegen verlassen da, die Glut glimmt noch, und zwischen den verstreuten Überresten ruht ein versengter Pergamentfetzen."},{t="Die rätselhafte Botschaft",b="Die versengte Notiz trägt zwei kurze Sätze: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ Ihre Worte weisen von Westfall fort, geben aber keine klare Richtung vor. Welcher Ort teilt mit diesem Land einen Namen, seine geografische Beschaffenheit oder sein Schicksal?"}},faq={{q="Was steht auf der Notiz?",a="Auf der versengten Notiz steht: „Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.“ Sie ist der einzige Hinweis am verlassenen Lagerplatz.",al={"text der notiz","was steht auf der notiz","wortlaut der versengten notiz"}},{q="Wo ist diese Notiz zu finden?",a="Die Notiz liegt zwischen den Resten eines Feuers und verstreuten Vorräten in der Wildnis von Westfall.",al={"fundort der notiz","wo ist die notiz","standort des lagerfeuers"}},{q="Wer hat das Lagerfeuer zurückgelassen?",a="Niemand weiß, wer das Lager verlassen hat. Wer auch immer das Feuer entzündet hat, ist erst vor Kurzem aufgebrochen und hat verstreute Vorräte und die versengte Botschaft in der Glut zurückgelassen.",al={"wer hat die notiz hinterlassen","besitzer des lagerfeuers","verfasser der notiz"}},{q="Worauf bezieht sich „das Zwillingsland“?",a="„Das Zwillingsland“ deutet auf eine andere Region hin, die mit dem Land verbunden ist, in dem die Notiz gefunden wurde, doch die verkohlte Botschaft erklärt nichts Näheres.",al={"bedeutung von zwillingsland","was ist das zwillingsland","wo ist das zwillingsland"}},{q="Warum wurde die Notiz verbrannt?",a="Die Notiz wurde in der Glut versengt und verkohlt. Vielleicht hat jemand versucht, sie in Eile zu vernichten, oder sie achtlos zurückgelassen, als die Flammen erloschen.",al={"warum wurde sie verbrannt","hat jemand versucht die notiz zu verbrennen","verkohlte notiz"}},{q="Hat dies mit der Bruderschaft der Defias zu tun?",a="Westfall wird von der Bruderschaft der Defias und mittellosen Landbesetzern überrannt, doch die rätselhafte Botschaft deutet auf etwas Geheimnisvolleres als gewöhnliche Banditennachrichten hin.",al={"defias-notiz","ist es von den defias","lagerfeuer der bruderschaft"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7901"] = {n="Soft Bushy Tails",s="Auf dem Dunkelmond-Jahrmarkt hilft eine Bitte um buschige Schwänze dabei, Preise für die Besucher bereitzustellen. Der Jahrmarkt hofft, dass zufriedene Besucher andere mitbringen.",h="Auf dem Dunkelmond-Jahrmarkt hilft eine Bitte um buschige Schwänze dabei, Preise für die Besucher...",kw={"dunkelmond-jahrmarkt","preise","weiche buschige schwänze","schwänze","eintrittskarten","besucher"},sec={{t="Preise vom Jahrmarkt",b="Zufriedene Besucher bedeuten mehr für den Dunkelmond-Jahrmarkt. Die Schwänze, die Ihr mitbringt, werden zu Preisen für die Besucher, und zufriedene Gäste erzählen vielleicht ihren Freunden davon. Der Jahrmarkt gibt Euch Eintrittskarten und heißt Euch willkommen, damit Ihr Eure Zeit dort genießen könnt."}},faq={{q="Wozu dienen die buschigen Schwänze?",a="Der Dunkelmond-Jahrmarkt wird sie als Preise für seine Besucher verwenden.",al={"warum schwänze","buschige schwänze verwendung","schwänze für den jahrmarkt"}},{q="Warum möchte der Jahrmarkt zufriedene Besucher?",a="Zufriedene Besucher erzählen ihren Freunden vielleicht vom Jahrmarkt und bringen mehr Besucher herbei.",al={"warum zufriedene besucher","besucher des jahrmarkts","mehr leute auf dem jahrmarkt"}},{q="Was gibt Euch der Jahrmarkt?",a="Der Jahrmarkt gibt Euch Eintrittskarten.",al={"jahrmarkt-eintrittskarten","was bekomme ich","eintrittskarten für schwänze"}}},fp="16,143,12.228.0,29.60.0,39.78.0,29.28.0"}
P.entries["quest:7905"] = {n="The Darkmoon Faire",s="Ihr tragt einen Free Ticket Voucher zu Gelvas Grimgate auf dem Jahrmarkt der Darkmoon Faire. Der Gutschein ist für ihn bestimmt.",h="Ihr tragt einen Free Ticket Voucher zu Gelvas Grimgate auf dem Jahrmarkt der Darkmoon Faire.",kw={"jahrmarkt","darkmoon faire","free ticket voucher","gelvas grimgate","gutschein"},sec={{t="Ein Gutschein für Gelvas",b="Gelvas Grimgate ist auf dem Jahrmarkt der Darkmoon Faire, und Ihr habt einen Free Ticket Voucher für ihn bei Euch. Der Gutschein wartet auf seine Übergabe."}},faq={{q="Für wen ist der Gutschein?",a="Der Free Ticket Voucher ist für Gelvas Grimgate, der sich auf dem Jahrmarkt der Darkmoon Faire befindet.",al={"gutschein für wen","gelvas gutschein"}},{q="Wo ist Gelvas Grimgate?",a="Gelvas Grimgate ist auf dem Jahrmarkt der Darkmoon Faire.",al={"wo ist gelvas","gelvas aufenthaltsort"}},{q="Was bringe ich Gelvas?",a="Bringt den Free Ticket Voucher zu Gelvas Grimgate.",al={"welcher gutschein","ticketgutschein"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Erzmagier Antonidas: Die ungekürzte Autobiografie",s="In Eisenschmiede sucht Ihr Archmage Antonidas: The Unabridged Autobiography. Der seltene Band enthält den eigenen Bericht des verstorbenen Anführers der Kirin Tor und gewährt Einblicke in Dalarans Geschichte und hohe arkane Gelehrsamkeit.",h="In Eisenschmiede sucht Ihr Archmage Antonidas: The Unabridged Autobiography.",kw={"antonidas","arkan","erzmagier antonidas","autobiografie","dalaran","hall of explorers","eisenschmiede","kirin tor","library","magier"},ang={["class:Mage"]="Erzmagier Antonidas war einer der größten Anführer der Kirin Tor und ein Vorbild arkaner Gelehrsamkeit. Sein Leben und seine persönlichen Schriften bieten jedem Praktizierenden der arkanen Künste wesentliche Einblicke.",["faction:Alliance"]="Antonidas war eine Stütze der Allianz von Lordaeron im Kampf gegen die orkische Horde und die Geißel. Seine persönlichen Memoiren sind in allen Ländern der Allianz ein geschätztes historisches Zeugnis.",["race:Dwarf"]="Der Foliant stammt aus der großen Bibliothek in Eisenschmiedes Hall of Explorers. Die Gelehrten, die ihn erhalten, scheinen keine Bedenken zu haben, den zwergischen Archivaren einen so seltenen Band zu entziehen.",["race:Human"]="Antonidas war ein verehrter menschlicher Erzmagier, der die Kirin Tor und Dalaran durch den Zweiten und Dritten Krieg führte. Seine ungekürzte Autobiografie ist ein kostbares Stück menschlicher Geschichte."},sec={{t="Die Worte des Großmagus",b="Erzmagier Antonidas führte die Kirin Tor jahrzehntelang an und herrschte über Dalaran. Als einer der brillantesten Köpfe Azeroths stieg er in den Rängen der Violetten Zitadelle auf und meisterte das Arkane. Seine ungekürzte Autobiografie schildert seine Führung während des Zweiten und Dritten Krieges. Gelehrten und Praktizierenden der Magie bietet sie aus erster Hand Einblicke in Dalarans innere Abläufe und die arkanen Künste."},{t="Aus Eisenschmiedes großer Bibliothek",b="Bevor es seine neue Heimat erreichte, ruhte das seltene Manuskript in Eisenschmiedes großer Bibliothek. In der Hall of Explorers bewahrten zwergische Archivare es neben uralten Titanenrelikten und zwergischen Geschichtswerken auf. Ihre gewaltigen Sammlungen enthalten Texte aus Ruinen und fremden Königreichen in ganz Azeroth. Doch arkane Gelehrte andernorts suchen solche Werke für ihre eigenen Sammlungen, überzeugt, dass die vielbeschäftigten Archivare einen einzelnen fehlenden Band niemals bemerken werden."}},faq={{q="Wer war Erzmagier Antonidas?",a="Erzmagier Antonidas führte die Kirin Tor viele Jahre lang an und herrschte über den magischen Stadtstaat Dalaran. Als legendärer Meister des Arkanen war er während des Zweiten Krieges ein wichtiger Berater der Allianz von Lordaeron. Er warnte König Terenas vor der Seuche, ehe er während des Dritten Krieges bei der Verteidigung Dalarans fiel.",al={"wer war antonidas","erzmagier antonidas geschichte","antonidas vorgeschichte"}},{q="Was ist die ungekürzte Autobiografie?",a="Erzmagier Antonidas verfasste die umfassende Autobiografie selbst und schilderte darin sein Leben, seine Studien und seine Führung in Dalaran. Seine Schriften als Oberhaupt der Kirin Tor sind ein unschätzbares Zeugnis der Geschichte und Magie.",al={"was ist dieses buch","ungekürzte autobiografie buch","antonidas foliant"}},{q="Woher stammt dieses Buch?",a="Der Band stammt aus der Bibliothek in Eisenschmiedes Hall of Explorers. Zwergische Forscher und Archivare sammeln oft historische und magische Texte aus allen Teilen der östlichen Kontinente.",al={"woher stammt das buch","stammt das aus eisenschmiede","eisenschmiede bibliothek buch"}},{q="Warum wird dieses Buch gesucht?",a="Gelehrte und Bibliothekare suchen mächtige oder geschichtsträchtige magische Texte, um ihre Archive zu erweitern und arkanes Wissen zu bewahren. Werke legendärer Magier sind besonders begehrt, damit sie nicht verloren gehen oder in fremden Sammlungen verborgen bleiben.",al={"warum magische bücher sammeln","wer will antonidas' buch","warum will die bibliothek das"}},{q="Was geschah mit Erzmagier Antonidas?",a="Erzmagier Antonidas kam während des Dritten Krieges ums Leben, als der gefallene Prinz Arthas Menethil und die Geißel in Dalaran einfielen. Antonidas errichtete eine mächtige magische Barriere, um die Stadt und ihre Geheimnisse zu schützen. Arthas durchbrach die Verteidigung und streckte ihn nieder, um das Book of Medivh an sich zu nehmen.",al={"ist antonidas gestorben","wie starb antonidas","was geschah mit antonidas"}},{q="Wird Eisenschmiedes Bibliothek das Fehlen des Buches bemerken?",a="Der Empfänger tut die Sorge ab, die Zwerge könnten das Fehlen des Buches bemerken. Die Archive von Eisenschmiede sind so gewaltig, dass ein einzelner fehlender Foliant wahrscheinlich unbemerkt bleibt.",al={"wird eisenschmiede das buch vermissen","diebstahl aus eisenschmiedes bibliothek"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Forschungsaufzeichnungen von Erzmagier Theocritus",s="Im Turm von Azora führt Erzmagier Theocritus ein Tagebuch über seine Untersuchungen. Nun bringt Ihr seine magischen Erkenntnisse den Gelehrten der Library von Eisenschmiede, wo sie ins Zwergenarchiv aufgenommen werden können.",h="Im Turm von Azora führt Erzmagier Theocritus ein Tagebuch über seine Untersuchungen.",kw={"arkanes wissen","erzmagier theocritus","eisenschmiede","library von eisenschmiede","forschungstagebuch","theocritus","turm von azora"},ang={["class:Mage"]="Als Magier wisst Ihr, dass Notizen bedeutender Persönlichkeiten wie Erzmagier Theocritus helfen, historische magische Werke in Eisenschmiedes Archiven zu bewahren.",["faction:Alliance"]="Als Mitglied der Allianz helft Ihr, Eisenschmiedes große Wissenssammlung für die Gelehrten der Allianz zu bereichern."},sec={{t="Feldnotizen eines Meisters",b="Erzmagier Theocritus ist ein angesehener Zauberkundiger, der in der gesamten Allianz bekannt ist. Er ist im Turm von Azora im östlichen Wald von Elwynn stationiert, wo er seit Jahren allein forscht. Seine Untersuchungen reichen von seltsamen Artefakten und Anomalien der Leylinien bis hin zu magischen Bedrohungen in der Nähe.\n\nEr hält seine Erkenntnisse in ausführlichen Tagebüchern fest. Dieser Band bietet eine seltene Gelegenheit, die persönlichen Beobachtungen eines hochrangigen Erzmagiers der Kirin Tor zu studieren."},{t="Eisenschmiedes Archive erweitern",b="Die Explorers' League und die Hüter der Library von Eisenschmiede unterhalten eines der größten Archive des Kontinents. Ihr bringt ihnen Archmage Theocritus' Research Journal und helft dabei, seine arkanen Erkenntnisse neben den historischen Bänden von Khaz Modan zu bewahren und zu katalogisieren. Die Bibliothekare begrüßen weitere magische Entdeckungen, die ihr gemeinsames Wissen erweitern können."}},faq={{q="Was ist Archmage Theocritus' Research Journal?",a="Archmage Theocritus' Research Journal ist eine wissenschaftliche Aufzeichnung seiner Forschungen. Ihr bringt es zur Library von Eisenschmiede, um arkanes Wissen zu bewahren und ihre Archive zu bereichern.",al={"theocritus tagebuch abgeben","was ist theocritus tagebuch"}},{q="Wer ist Erzmagier Theocritus?",a="Erzmagier Theocritus ist ein angesehener menschlicher Magier, der im Turm von Azora im Wald von Elwynn stationiert ist. Er erforscht uralte magische Störungen und Artefakte.",al={"wer ist theocritus","erzmagier theocritus hintergrundgeschichte"}},{q="Wohin wird dieses Tagebuch gebracht?",a="Ihr bringt das Tagebuch zu den Archivaren der Library in Eisenschmiede. Sie sammeln seltene Dokumente und magische Manuskripte.",al={"wo theocritus tagebuch abgeben","wer möchte theocritus tagebuch"}},{q="Warum möchte die Bibliothek dieses Tagebuch haben?",a="Die Gelehrten der Library von Eisenschmiede wollen arkanes Wissen bewahren und seltene Werke meisterhafter Zauberkundiger studieren. Diese Werke erweitern ihre historischen Aufzeichnungen.",al={"warum magische tagebücher sammeln","zweck von theocritus tagebuch"}},{q="Können weitere magische Werke zur Bibliothek gebracht werden?",a="Ja. Die Kuratoren ermutigen Euch, weitere magische Werke und historische Texte für ihre Archive zu suchen.",al={"weitere tagebücher abgeben","gibt es weitere bücher für die library"}},{q="Welche Art von Forschung enthält das Tagebuch?",a="Das Tagebuch enthält Notizen und Beobachtungen aus Erzmagier Theocritus' umfangreichen Untersuchungen zu magischen Phänomenen und arkanem Wissen.",al={"was steht in theocritus tagebuch","inhalt von theocritus tagebuch"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi von Gnomeregan: Die gesammelten Werke",s="Ein Sammelwerk von Rumi of Gnomeregan wird für den Bestand einer Bibliothek gesucht. Seine Seiten bewahren gnomische Schriften und Wissen, das sonst verloren gehen könnte.",h="Ein Sammelwerk von Rumi of Gnomeregan wird für den Bestand einer Bibliothek gesucht.",kw={"gesammelte werke","gnomeregan hintergrundgeschichte","gnomische schriften","library","magische werke","rumi of gnomeregan"},ang={["class:Mage"]="Als Magier schätzt Ihr seltene Schriften aus ganz Azeroth, die das Verständnis magischer Theorie und Geschichte vertiefen.",["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr Gelehrten und Kuratoren helfen, wertvolle Literatur und magische Texte für den gemeinsamen Wissensschatz der Allianz zu schützen.",["race:Gnome"]="Als Gnom helft Ihr durch die Bewahrung der gesammelten Schriften von Denkern wie Rumi, Eure Kultur und Euer geistiges Erbe nach Gnomeregans Fall lebendig zu halten."},sec={{t="Gnomisches Gedankengut bewahren",b="Gnomische Schriften wurden verstreut, verschüttet oder blieben gefährdet zurück, als Troggs Gnomeregan überrannten. Nun suchen Gelehrte und Archivare nach erhaltenen Manuskripten, Abhandlungen und Sammelwerken. Sie hoffen, die Weisheit und den Erfindungsreichtum gnomischer Denker lebendig zu halten."},{t="Bergung für die Archive",b="Wenn Reisende unterwegs gesammelte Werke finden und in die Archive bringen, nehmen Kuratoren sie in ihre wachsenden Sammlungen auf. Jedes geborgene Manuskript erweitert die Forschungsmöglichkeiten der Gelehrten. Archivare heißen weitere magische und historische Texte willkommen und halten sie für Gelehrte, Magier und Historiker zugänglich, die Azeroths Wissen bewahren."}},faq={{q="Was ist Rumi of Gnomeregan: The Collected Works?",a="Rumi of Gnomeregan: The Collected Works ist eine Zusammenstellung gnomischer Schriften, die für eine Bibliothek gesucht wird. Ein Abenteurer bringt sie einem Gelehrten, damit ihr Wissen bewahrt und erforscht werden kann.",al={"rumi of gnomeregan quest","was ist rumi of gnomeregan","wer ist rumi"}},{q="Wohin werden diese gesammelten Werke gebracht?",a="Die gesammelten Werke gehen an einen Kurator oder Gelehrten, der den Bestand einer Bibliothek betreut. Diese suchen bedeutende Schriften und magische Abhandlungen für die Archive.",al={"wo rumis werke abgeben","wer nimmt rumis bücher an","rumis sammlung abgeben"}},{q="Warum möchte die Bibliothek diese gesammelten Werke haben?",a="Die Bibliothek möchte die Werke haben, um wichtige wissenschaftliche Erkenntnisse zu bewahren. Gelehrte und Archivare sammeln seltene Texte, historische Abhandlungen und magische Manuskripte, besonders Schriften aus Gnomeregan.",al={"warum rumis bücher sammeln","zweck von rumi of gnomeregan","warum die bibliothek rumi möchte"}},{q="Wer ist Rumi of Gnomeregan?",a="Rumi of Gnomeregan ist ein Verfasser gelehrter oder magischer Texte, dessen gesammelte Schriften von Archivaren gesucht werden. Da Gnomeregan größtenteils überrannt wurde, bewahren erhaltene Werke die wissenschaftlichen Traditionen der Gnome.",al={"wer war rumi of gnomeregan","rumis hintergrundgeschichte","rumi autor"}},{q="Können danach weitere Bücher zur Bibliothek gebracht werden?",a="Ja. Archivare heißen weitere Funde willkommen, und Kuratoren ermutigen Reisende, seltene magische Abhandlungen und historische Werke für die Sammlung zu bringen.",al={"gibt es weitere bücher zu finden","weitere texte bringen","weitere magische werke bibliothek"}},{q="Wer kann diese Aufgabe erfüllen?",a="Abenteurer der Allianz können Gelehrten helfen, historische und arkane Schriften zu bewahren. Jeder, der diese Texte birgt, kann sie in die Archive bringen, um die Forschung zu unterstützen.",al={"rumi quest voraussetzungen","wer kann rumis werke abgeben","rumi nur allianz"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="Ein Bibliothekar bittet Euch, magische Werke wie The Lessons of Ta'zo in die Bibliothek zu bringen. Jeder Neuzugang erweitert ihre Sammlung und ihr Wissen.",h="Ein Bibliothekar bittet Euch, magische Werke wie The Lessons of Ta'zo in die Bibliothek zu bringen.",kw={"sammlung","eisenschmiede","wissen","lektionen","library","magische werke","ta'zo"},sec={{t="Die Sammlung einer Library",b="Ein Bibliothekar fragt, ob Ihr etwas für die Sammlung der Bibliothek mitgebracht habt. Magische Werke, die der Bibliothek nützen könnten, sind willkommen, und durch Eure Mühen wächst ihr Wissen."}},faq={{q="Wer bittet um magische Werke?",a="Ein Bibliothekar bittet Euch, magische Werke in die Bibliothek zu bringen, die ihr nützen könnten. The Lessons of Ta'zo ist ein solches Werk.",al={"wer ist ta'zo","ta'zo bibliothek","ta'zo"}},{q="Was möchte der Bibliothekar in die Bibliothek gebracht haben?",a="Der Bibliothekar bittet um magische Werke, die der Sammlung der Bibliothek nützen könnten.",al={"was ta'zo bringen","magische bücher","bibliothekssammlung"}},{q="Wo wird die Sammlung aufbewahrt?",a="Bibliothekare sammeln solche Werke in Sturmwind und in der Unterstadt.",al={"wo ist ta'zo","eisenschmiede bibliothek","standort der bibliothek"}},{q="Warum bittet der Bibliothekar um magische Werke?",a="Der Bibliothekar sagt, dass das Wissen der Bibliothek durch Eure Mühen wächst.",al={"warum magische werke","wissen erweitern","bibliothek helfen"}}},fp="20,145,22.183.0,32.114.0,52.81.0,29.63.0,45.72.0"}
P.entries["quest:79095"] = {n="Metaphysische Fibel des Apothekers",s="Kuratoren suchen The Apothecary's Metaphysical Primer, um ihre Archive zu bereichern. Die Abgabe hilft, seltene alchemistische und arkane Theorie für Forscher und Zauberwirker zu bewahren.",h="Kuratoren suchen The Apothecary's Metaphysical Primer, um ihre Archive zu bereichern.",kw={"alchemie","apotheker","unterstadt","library","magische werke","metaphysische fibel","foliant"},ang={["class:Mage"]="Als Magier schätzt Ihr metaphysische Fibeln wegen ihrer Einblicke in magische Theorie, alchemistische Wechselwirkungen und die Grundlagen der Zauberkunst.",["faction:Horde"]="Als Mitglied der Horde könnt Ihr Owen Thadd in Unterstadt helfen, seltene Abhandlungen für die arkanen Sammlungen der Bibliothek wiederzubeschaffen."},sec={{t="Der Erwerb eines Gelehrten",b="Kuratoren schätzen The Apothecary's Metaphysical Primer wegen seiner Untersuchung esoterischer und magischer Prinzipien. Owen Thadd nimmt den Text direkt in seine Sammlung magischer Nachschlagewerke auf, mit der er arbeitet."},{t="Die Erweiterung der Archive",b="Owen Thadds Sammlung in Unterstadt bewahrt spezialisierte Abhandlungen. Indem Ihr ihm seltene Fibeln über arkane und alchemistische Theorie bringt, helft Ihr, metaphysische Erkenntnisse sicher in den Archiven und für Forscher zugänglich zu halten, statt sie in der Wildnis verloren gehen zu lassen."}},faq={{q="Was ist The Apothecary's Metaphysical Primer?",a="Kuratoren suchen The Apothecary's Metaphysical Primer als seltenen wissenschaftlichen Text für ihre Sammlung magischer Literatur und ihr Studium der metaphysischen Wissenschaften.",al={"was ist the apothecaries metaphysical primer","quest zur metaphysischen fibel","was ist dieses buch"}},{q="Wer möchte diese Fibel erhalten?",a="Owen Thadd in Unterstadt möchte die Fibel erhalten. Er sucht magische Werke und arkane Abhandlungen, um Wissen für Forscher und Zauberwirker zu bewahren.",al={"wer möchte dieses buch","wo die fibel abgeben","wer nimmt die fibel an"}},{q="Warum sammelt die Bibliothek solche Werke?",a="Bibliotheken und Archive sammeln metaphysische und magische Werke, um ihr Wissen zu erweitern. Diese Werke helfen Gelehrten, Alchemisten und Arkanisten beim Studium arkaner Prinzipien.",al={"warum möchte die bibliothek die fibel","zweck des sammelns von fibeln","warum magische bücher sammeln"}},{q="Könnt Ihr der Bibliothek weitere magische Werke bringen?",a="Gelehrte, die magische Literatur katalogisieren, begrüßen weitere arkane und wissenschaftliche Entdeckungen, die Ihr für ihre Archive findet.",al={"gibt es weitere bücher zum abgeben","andere bücher bringen","weitere bibliotheksbücher"}},{q="Welches Wissen enthält eine metaphysische Fibel?",a="In der magischen Wissenschaft befasst sich die Metaphysik mit dem Wesen magischer Energien, den unsichtbaren Kräften, die die Wirklichkeit bestimmen, und dem Zusammenspiel stofflicher Reagenzien mit arkanen Kräften.",al={"was bedeutet metaphysisch wotlk classic","metaphysik hintergrundwissen wow","was ist apothekermetaphysik"}},{q="Wer hat The Apothecary's Metaphysical Primer verfasst?",a="Die Aufzeichnungen nennen den Apotheker, der die Fibel verfasst hat, nicht beim Namen. Apotheker und Gelehrte stellen häufig Fibeln über praktische Alchemie, Kräutermischungen und mystische Formeln zusammen.",al={"wer hat die apothekerfibel verfasst","verfasser der apothekerfibel","wer ist der apotheker"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric: Arkane Merkwürdigkeiten",s="Ataeric sucht seltene magische Schriften, um die Sammlung einer Bibliothek zu erweitern. Gelehrte hoffen, damit ihre arkanen Studien zu vertiefen und das Wissen darüber zu bewahren.",h="Ataeric sucht seltene magische Schriften, um die Sammlung einer Bibliothek zu erweitern.",kw={"arkan","arkane kuriositäten","ataeric","library","magische werke","gelehrte"},ang={["class:Mage"]="Als Magier habt Ihr ein natürliches Interesse an arkanen Studien. Magische Abhandlungen zu bergen und Gelehrtenbibliotheken zu unterstützen, entspricht Eurer Kunst.",["race:Dwarf"]="Als Zwerg kennt Ihr den Wert schriftlicher Aufzeichnungen, von Artefakten und verborgenem Wissen. Zwergische Gelehrte und die Explorers' League schätzen sie."},sec={{t="Arkanes Wissen bewahren",b="In ganz Azeroth verlassen sich Gelehrte auf Reisende, um seltene Wälzer und Abhandlungen aus gefährlichen Gegenden zu bergen. Ataeric sucht magische Schriften, um die arkanen Studien einer Institution zu erweitern. Jeder Band kann Gelehrten helfen, Praktiken zu rekonstruieren, die andernfalls verstreut oder verloren sein könnten."},{t="Ein wachsendes Archiv",b="Der Kurator nimmt jede Kuriosität ins Archiv auf. Die Bibliothek ist weiterhin an weiteren magischen Schriften aus aller Welt interessiert, damit ihre Sammlung mit der fortschreitenden Forschung wachsen kann."}},faq={{q="Welchen Zweck hat diese Quest?",a="Ataeric sucht magische Schriften, um die Sammlung arkanen Wissens einer Bibliothek zu erweitern.",al={"was ist diese quest","ataeric quest","arkane kuriositäten abgeben"}},{q="Wer sammelt diese arkanen Schriften?",a="Ataeric hat die Abhandlung verfasst. Ein Forscher oder Kurator sammelt magische Werke und seltene Bände für das Archiv einer Bibliothek.",al={"wer will das","wer bekommt das buch","wer ist ataeric"}},{q="Welcher Bibliothek kommen diese Kuriositäten zugute?",a="Die Kuriositäten werden für eine wissenschaftliche Sammlung in einer Gelehrtenbibliothek gesucht.",al={"welche bibliothek ist das","wohin kommen diese bücher"}},{q="Gibt es weitere magische Werke zu sammeln?",a="Ja. Der Gelehrte nimmt gerne alle weiteren magischen Werke an, die Ihr auf Euren Reisen findet, um den Wissensbestand der Bibliothek zu erweitern.",al={"mehr abgeben möglich","wiederholbare magische werke","mehr bücher für die bibliothek"}},{q="Warum sucht die Bibliothek arkane Kuriositäten?",a="Die Bibliothek sucht seltene Abhandlungen, um die arkanen Studien zu vertiefen und mystisches Wissen zu bewahren.",al={"was erforscht die bibliothek","warum arkane bücher sammeln"}},{q="Warum ist es wichtig, arkane Werke zu bergen?",a="Die Bergung arkaner Werke bringt verborgenes Wissen in eine Bibliothek, wo es bewahrt und erforscht werden kann, statt draußen verschollen zu bleiben.",al={"ist das gefährlich","risiko arkaner magie"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan: Über zerstörerische Magie",s="In der Library ergänzt Baxtan: On Destructive Magics die Werke, die Gelehrte sammeln, um gefährliche arkane Macht zu verstehen.",h="In der Library ergänzt Baxtan: On Destructive Magics die Werke, die Gelehrte sammeln, um gefährliche arkane...",kw={"arkan","baxtan","buch","zerstörerische magie","library","magie","foliant"},ang={["class:Mage"]="Als Magier wisst Ihr Abhandlungen über zerstörerische Magie womöglich zu schätzen, wenn Ihr arkane Macht und ihre Gefahren erforscht.",["class:Warlock"]="Als Hexenmeister erkennt Ihr vielleicht, warum Gelehrte unbeständige oder verbotene Mächte verstehen wollen.",["faction:Alliance"]="Als Mitglied der Allianz profitiert Ihr davon, wenn die Bibliotheken der Allianz das für alle bewahrte Wissen erweitern."},sec={{t="Ein Foliant verderblicher Künste",b="Gelehrte wollen das überlieferte arkane Wissen bewahren. Wenn Ihr einen Text über zerstörerische Magie findet, gehört er in sorgfältige wissenschaftliche Obhut. Dort lassen sich seine Macht und seine Gefahren verstehen, statt in Vergessenheit zu geraten."},{t="Das Wissen der Library bewahren",b="Die Library beherbergt Werke über Geschichte, Wissenschaft und das Arkane. Ihr Gelehrter heißt Reisende willkommen, die vergessene Abhandlungen aus gefährlichen Winkeln der Welt bergen. Jeder Band erweitert das Wissen der Library."}},faq={{q="Was ist die Quest „Baxtan: On Destructive Magics“?",a="Ihr bringt Baxtans Abhandlung über zerstörerische Magie zu einem Gelehrten der Library und fügt der Sammlung ein Werk über Magie hinzu.",al={"was ist baxtan: on destructive magics","was ist diese quest","baxtan quest"}},{q="Wer ist Baxtan?",a="Baxtan schrieb On Destructive Magics. Der Gelehrte, der das Werk entgegennimmt, sammelt wichtige Folianten und magische Abhandlungen für die Library.",al={"wer ist baxtan","baxtan npc","wo ist baxtan"}},{q="Welche Arten von Büchern sucht Baxtan?",a="Der Gelehrte der Library sucht wissenschaftliche und magische Werke für die Sammlung, darunter Abhandlungen, die Ihr überall auf der Welt findet.",al={"welche bücher sucht baxtan","baxtan büchersammlung","mehr bücher für baxtan"}},{q="Wohin gelangt dieses magische Wissen?",a="Die zusammengetragenen Texte gelangen in die Sammlung der Library, wo Gelehrte sie zum Studium des Arkanen und seiner Gefahren bewahren.",al={"wohin kommt das buch","welche library","ironforge library sammlung"}},{q="Warum sammelt die Library Werke über zerstörerische Magie?",a="Gelehrte katalogisieren zerstörerische Magie, um die Gefahren, die Wirkungsweise und die Formen mächtiger arkaner Energien zu verstehen.",al={"warum zerstörerische magie erforschen","wissen über zerstörerische magie"}},{q="Könnt Ihr Baxtan weitere magische Werke bringen?",a="Ja. Der Gelehrte nimmt weitere magische Werke, die Ihr entdeckt, gerne entgegen, um die Sammlung des Wissens fortzuführen.",al={"gibt es weitere quests für baxtan","weitere bücher abgeben"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="Akzeptiert Euer Schicksal",s="Akzeptiert Euer Schicksal ist eine einführende Aufgabe, die von Furl Hohnbraue auf dem Wachturm von Klingenhügel mit Blick auf Klingenhügel angeboten wird. Zu alt, um an vorderster Front zu kämpfen, bittet der vernarbte Veteran junge Abenteurer der Horde darum, Segeltuch von den örtlichen menschlichen und zentaurenhaften Feinden zu erbeuten, damit er Ausrüstung herstellen kann, die ihnen auf ihrer Reise hilft.",h="Akzeptiert Euer Schicksal ist eine einführende Aufgabe, die von Furl Hohnbraue auf dem Wachturm von...",kw={"segeltuchreste","akzeptiert euer schicksal","durotar","furl hohnbraue","kolkar","klingenhügel","wachturm von klingenhügel","tiragarde"},ang={["faction:Horde"]="Jeder junge Soldat in Durotar verlässt sich auf erfahrene Veteranen wie Furl Hohnbraue, die Neuankömmlinge daran erinnern, dass es bedeutet, die Horde zu ehren, jede Pflicht zu erfüllen, die die Heimat erfordert – sei es das Bewachen eines Außenpostens oder das Nähen von Segeltuch.",["profession:Tailoring"]="Furl demonstriert praktische, robuste Grenzland-Schneiderei, indem er weggeworfenes schweres Segeltuch von menschlichen Invasoren und Zentauren-Plünderern in langlebige Wildnis-Überlebensausrüstung verwandelt.",["race:Orc"]="Furl verkörpert die ältere Generation von Orcs, die sich von der dämonischen Verderbnis befreiten, mit Thrall das Meer überquerten und nun ihre letzten Jahre dem Heranwachsen der Zukunft ihrer jungen Nation widmen."},sec={{t="Die Berufung eines Veteranen",b="Furl Hohnbraue ist ein Veteran des Dritten Krieges, der während der Erschließung von Durotar und der verzweifelten Verteidigung am Hyjal an der Seite von Kriegshäuptling Thrall marschierte. Mittlerweile durch Alter und alte Verletzungen verlangsamt, führt er seine Axt nicht mehr im Kampf. Stattdessen hält er vom Wachturm von Klingenhügel aus stetige Wache, schlägt bei Übergriffen Alarm und unterstützt die nächste Generation von Verteidigern."},{t="Erbeutetes Segeltuch",b="Da Alarmrufe mit dem Signalhorn seltener werden, während der Zugriff der Horde auf die Region erstarkt, verbringt Furl seine Stunden damit, praktische Ausrüstung herzustellen. Robustes Segeltuch ist in den trockenen Canyons von Durotar schwer zu finden, wird jedoch sowohl von den Kul Tiranern an der Ostküste als auch von den nomadischen Kolkar-Zentauren, die die Ebenen durchstreifen, im Überfluss mitgeführt. Das Erbeuten von Stoffetzen dieser feindlichen Streitkräfte liefert Furl den nötigen Stoff, um nützliche Taschen für aktive Späher zu nähen."}},faq={{q="Wer ist Furl Hohnbraue?",a="Furl Hohnbraue ist ein alternder Orc-Veteran, der im Wachturm über Klingenhügel stationiert ist. Er kämpfte während der Gründung von Durotar an der Seite von Thrall und stand in den vereinten Reihen, die Archimonde am Hyjal zu Fall brachten. Da er nicht mehr an vorderster Front kämpfen kann, dient er als Ausguck und nutzt seine freie Zeit, um Feldausrüstung für junge Krieger der Horde herzustellen.",al={"wer ist furl","furl hohnbraue hintergrundgeschichte","wer vergibt akzeptiert euer schicksal"}},{q="Wo kann man Segeltuchfetzen in Durotar finden?",a="Segeltuchfetzen werden von den Kul Tiranern gesammelt, die Burg Tiragarde an Durotars Küste besetzen, sowie von den Kolkar-Zentauren, die in den Ebenen lagern. Beide Fraktionen führen schwere gewebte Materialien mit sich, die aus ihren Lagern und Besitztümern geborgen werden können.",al={"wo gibt es segeltuchfetzen","wer droppt segeltuchfetzen","fundorte segeltuchfetzen"}},{q="Wo befindet sich der Wachturm, an dem Furl steht?",a="Furls Wachturm thront auf den hohen felsigen Klippen direkt nordwestlich von Klingenhügel. Ein gewundener Pfad hinter der Siedlung führt hinauf zum Gipfel, auf dem der hölzerne Ausguck steht.",al={"wo ist furl hohnbraue","wachturm von klingenhügel standort","wachturm von klingenhügel finden"}},{q="Was stellt Furl aus den Segeltuchfetzen her?",a="Furl näht die gesammelten Segeltuchfetzen zu einer robusten Mehrzwecktasche zusammen. Für junge Abenteurer, die durch Durotar reisen, ist zusätzlicher Stauraum für Proviant, Rationen und erbeutete Waffen unerlässlich, um in der rauen Wildnis zu überleben.",al={"was stellt furl her","wofür wird das segeltuch gebraucht","belohnung segeltuchfetzen"}},{q="Warum stellt ein alter Krieger Taschen her, anstatt zu kämpfen?",a="Jahrzehnte unerbittlicher Kämpfe haben Furls Körper gezeichnet, sodass er der im Feld geforderten Schnelligkeit und Stärke nicht mehr gewachsen ist. Anstatt seinen Ruhestand zu beklagen, findet er Ehre darin, über Klingenhügel zu wachen und Ausrüstung herzustellen, die jüngere Kämpfer direkt befähigt, das Reich zu verteidigen.",al={"warum schneidert furl","warum bleibt furl im turm","warum kämpft furl nicht"}},{q="In welchem Krieg hat Furl gekämpft?",a="Furl kämpfte während des Dritten Krieges unter Kriegshäuptling Thrall und nahm an der Besiedlung von Durotar sowie der entscheidenden Schlacht um den Hyjal gegen die Brennende Legion teil. Stolz erinnert er sich daran, dem Kriegsschrei während des vorübergehenden, notwendigen Waffenstillstands zwischen der Horde, den Nachtelfen und der Allianz gefolgt zu sein, um Archimonde zu besiegen.",al={"furls schlachtengeschichte","was hat furl früher getan","archimonde furl"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="In einem abgelegenen Lager im Brachland weist eine verwitterte Notiz auf Stepping Stones hin, eine Bergzuflucht nahe Desolace. Sie besagt, dass zwei Kuriere Lieferungen für die New Plague überbrachten, und bezeichnet ihren plötzlichen Tod als einfache Apothekerunfälle.",h="In einem abgelegenen Lager im Brachland weist eine verwitterte Notiz auf Stepping Stones hin, eine...",kw={"desolace","mercenaries","berge","new plague","notiz","royal apothecary society","stepping stones","brachland"},ang={["class:Rogue"]="Als Schurke wisst Ihr, wie man anonyme Informanten aufspürt und geheime Nachrichten beurteilt, die zwischen Desolace und dem Brachland hinterlassen werden.",["faction:Horde"]="Als Wanderer der Horde im Brachland wägt Ihr ab, ob Berichte über tödliche Seuchenlieferungen auf Kalimdors Boden Eure Lande und Bündnisse bedrohen.",["race:Undead"]="Für Reisende der Verlassenen kann eine unbefugte Erwähnung der Royal Apothecary Society und ihrer Seuchenforschung eine dringende Sicherheitsangelegenheit oder eine gefährliche Verschwörung aus den eigenen Reihen sein."},sec={{t="Eine Notiz in der Wildnis",b="Eine zerrissene Nachricht hängt an einer Holzplanke in einem abgelegenen Lager im Brachland. Mercenaries, Halsabschneider und Herumtreiber suchen in solchen Lagern kurzzeitig Schutz, fern der Blicke vom Wegekreuz oder aus Ratschet. Zwischen den gewöhnlichen Spuren der Wildnis gibt Euch die Notiz Anlass, über das Lager hinaus in Richtung der Berge zu blicken."},{t="Gerüchte über die New Plague",b="Der anonyme Verfasser berichtet, dass zwei Agenten Lieferungen für die New Plague überbrachten, und bezeichnet ihren plötzlichen Tod als einfache Apothekerunfälle. Die Notiz lädt Euch zu einem Treffen in einer Bergzuflucht zwischen dem Brachland und Desolace ein, wo Ihr die Angelegenheit in Sicherheit besprechen könnt."}},faq={{q="Wovon handelt die Notiz, die in Stepping Stones gefunden wurde?",a="Die Notiz besagt, dass zwei Kuriere, die Lieferungen für die New Plague überbrachten, plötzlich starben, was der Verfasser als einfache Apothekerunfälle bezeichnet. Der Verfasser bietet einen Treffpunkt in den Bergen an, um die Geschehnisse zu besprechen.",al={"stepping stones notiz","wovon handelt die notiz","stepping stones questtext"}},{q="Wohin schickt Euch die Notiz?",a="Der Verfasser weist Euch den Weg zu einer abgeschiedenen Zuflucht in den Bergen zwischen dem Brachland und Desolace.",al={"wohin bei stepping stones","lauschiges plätzchen in den bergen","stepping stones standort"}},{q="Was ist die im Brief erwähnte New Plague?",a="Die New Plague ist ein tödliches Gemisch, das die Royal Apothecary Society der Verlassenen in Unterstadt entwickelt hat. Es soll sowohl die Geißel als auch lebende Feinde vernichten. Seine Erprobung und die Kurierfahrten über die Kontinente hinweg bringen Geheimhaltung und tödliche Gefahr mit sich.",al={"was ist die new plague","royal apothecary seuche","apothekerlieferungen"}},{q="Wer hat die an die Planke geheftete Notiz geschrieben?",a="Die Notiz ist anonym und an eine grobe Holzplanke in einem abgelegenen Lager geheftet. Ihr Verfasser bietet einen Treffpunkt in den Bergen zwischen dem Brachland und Desolace an.",al={"wer schrieb die notiz","stepping stones verfasser","wer wartet in den bergen"}},{q="Warum sollten Kuriere der Verlassenen in Kalimdor sein?",a="Apotheker der Verlassenen sammeln exotische Gifte, Sporen und Reagenzien aus Kalimdors Pflanzen- und Tierwelt. Sie koordinieren Lieferungen über Außenposten der Horde und Wege durch die Wildnis.",al={"verlassene im brachland","warum new plague in kalimdor","apotheker im brachland"}},{q="Warum werden abgelegene Lager für solche Notizen genutzt?",a="Das Brachland erstreckt sich weit über größere Siedlungen hinaus und wird nur lose verwaltet. Neutrale Wegstationen, Rastplätze von Söldnern und Schurkenlager bieten Reisenden, Schmugglern und Informanten einen diskreten Ort für Nachrichten, fern der Horde und regionaler Wachposten.",al={"hintergrund abgelegener lager","söldnerlager im brachland"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="Üble Familiare",s="Im Tal der Prüfungen strömen Üble Familiare aus einer nahen Höhle. Zureetha Fernblick entdeckte einen verborgenen Koven der Brennenden Klinge, während sie über die Prüfungen wachte. Nun jagen Rekruten die Familiare, die sich über Durotars rote Erde ausbreiten.",h="Im Tal der Prüfungen strömen Üble Familiare aus einer nahen Höhle.",kw={"burning blade","koven der brennenden klinge","durotar","wichtel","the den","das tal der prüfungen","üble familiare","zureetha fernblick"},ang={["class:Warlock"]="Als Hexenmeister der Orcs oder Trolle stellt Ihr Euch abtrünnigen Schattenwirkern, die dämonische Pakte zur Zerstörung nutzen. Ihr lenkt Teufelsenergien, um das Überleben der Horde zu sichern.",["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch dem Versuch der Burning Blade entgegen, Durotar von innen heraus zu verderben. Die junge Horde muss ihre Herrschaft fest verankern.",["race:Orc"]="Als Orc begegnet Ihr auf Eurem heiligen Übungsgelände der Teufelsverderbnis. Es ist eine bittere Erinnerung daran, dass das Erbe des Shadow Council weiter schwärt, obwohl Thrall die dämonische Knechtschaft abgelehnt hat."},sec={{t="Ein Schatten im Tal",b="Junge Orcs und Dunkelspeertrolle stellen im Tal der Prüfungen ihre Stärke, Disziplin und Treue zu Thralls Horde unter Beweis. Sie sollten sich Skorpiden und Ebern stellen, nicht dämonischer Verderbnis. Doch eine Höhle im Nordosten bietet Agenten der Burning Blade Unterschlupf. Unter den Augen der Aufseher des Tals haben sie einen geheimen Koven gebildet."},{t="Die Wichtel dezimieren",b="Zureetha Fernblick leitet Neuankömmlinge nahe dem Den an. Sie bemerkte die Verderbnis, bevor sie die Schlucht überwuchern konnte. Nun strömen Üble Familiare aus dem Höhleneingang und schleudern Feuer auf jeden, der sich zu nahe heranwagt. Bevor die Horde die verborgenen Meister ausmerzen kann, werden junge Rekruten ausgesandt, um diese niederen Diener niederzustrecken und das Tal zu sichern."}},faq={{q="Wer vergibt die Quest Üble Familiare?",a="Zureetha Fernblick erteilt die Aufgabe. Sie wartet direkt vor dem Eingang des Den in der Mitte des Tals der Prüfungen.",al={"üble familiare questgeber","wer vergibt üble familiare","wo üble familiare annehmen"}},{q="Was sind Üble Familiare?",a="Üble Familiare sind kleine, wichtelartige Dämonen, die von Kultisten der Burning Blade beschworen und gebunden werden. Diese niederen Diener und Begleiter setzen Feuer gegen Eindringlinge ein.",al={"was sind üble familiare","geschichte der üblen familiare","üble familiare gegnertyp"}},{q="Wo befindet sich der Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge verbirgt sich in einer Höhle im Nordosten des Tals der Prüfungen. Sie liegt hinter den umherstreifenden Mottled Boars und Scorpid Workers.",al={"koven der brennenden klinge standort","wo ist der koven der brennenden klinge","höhle im tal der prüfungen"}},{q="Warum ist die Burning Blade im Tal der Prüfungen?",a="Die Burning Blade ist ein geheimer Kult, der Thralls neue Horde untergraben und dämonische Verderbnis verbreiten will. Im Tal der Prüfungen können sich ihre Mitglieder verbergen und die neuesten Kämpfer der Horde bedrohen, während die Horde ihre Herrschaft festigt.",al={"warum ist die burning blade hier","beweggründe der burning blade","was will die burning blade"}},{q="Was geschieht nach Abschluss von Üble Familiare?",a="Sobald die Familiare vor der Höhle dezimiert sind, schickt Zureetha Fernblick Euch hinein. Dort stellt Ihr Euch dem Anführer der Kultisten und erbeutet ein Medaillon der Brennenden Klinge.",al={"üble familiare folgequest","was kommt nach üble familiare","medaillon der brennenden klinge quest"}},{q="Muss ich tief in die Höhle vordringen, um die Familiare zu finden?",a="Nein. Üble Familiare hausen in der Höhle, doch viele tummeln sich um den Eingang und auf dem Schluchtboden vor der Höhlenöffnung.",al={"sind üble familiare in der höhle","wo üble familiare töten","üble familiare farmen"}}},fx={edfaf791={q="Warum will Zureetha Fernblick, dass die Vile Familiars getötet werden?",a="Zureetha Fernblick kam in das Tal der Prüfungen, um neue Rekruten anzuleiten, entdeckte aber eine wachsende Verderbnis direkt vor der Haustür der Horde. Der geheime Koven der Brennenden Klinge hat in den nahegelegenen Höhlen einen versteckten Koven errichtet, und ihre beschworenen Wichtel breiten sich über das ganze Tal aus. Um die Prüfungsgründe zu schützen und die dämonische Verderbnis zu tilgen, bevor sie sich weiter ausbreitet, muss sie deren Vorhut beseitigen.",al={"warum vile familiars töten","zureetha fernblick motivation","warum will zureetha die vile familiars tot sehen"}},["67a24c10"]={q="Warum schickt Euch Zureetha, anstatt sich selbst um die Vertrauten zu kümmern?",a="Ihr seid im Tal der Prüfungen, um Euch als würdig zu erweisen, der Horde zu dienen. Während Zureetha die Reaktion gegen die geheimen Kultisten koordiniert und außerhalb von The Den Wache hält, dient Euer Entsenden einem doppelten Zweck: Es schränkt den dämonischen Befall ein, der das Tal bedroht, und dient gleichzeitig als wichtige Feuertaufe gegen die dunkleren Mächte, die Euer Volk untergraben.",al={"warum schickt sie mich","warum kämpft zureetha nicht selbst","warum muss ich die familiars töten"}}},fp="14,220,22.318.0,16.332.0,35.113.0,24.147.0,41.137.0,49.243.0,45.170.1,57.130.0"}
P.entries["quest:79229"] = {n="Highway Robbery",s="In Desolace birgt ein geplündertes Lager Hinweise auf einen brutalen Angriff. Ihr sucht jemanden, der erklären kann, was geschehen ist.",h="In Desolace birgt ein geplündertes Lager Hinweise auf einen brutalen Angriff.",kw={"angriff","lager","zentaur","desolace","zwerg","wegelagerei","mensch","geplündertes lager","plünderer"},sec={{t="Ein verwüstetes Lager",b="Zwischen den Überresten eines Lagers in Desolace liegen zwei Menschen und ein Zwerg. Die Spuren an ihren Knochen deuten auf einen brutalen Angriff hin, während die gestohlenen Vorräte zeigen, dass kein Tier dafür verantwortlich war. Auch ihre Wunden stammen nicht von Zentaurenwaffen. Ihr sollt in Desolace jemanden finden, der sich in diesen Landen auskennt und die Zeichen deuten kann."}},faq={{q="Wer wurde im Lager angegriffen?",a="Die Überreste deuten darauf hin, dass zwei Menschen und ein Zwerg angegriffen wurden.",al={"wer starb im lager","opfer im lager","menschen und zwerg"}},{q="Was geschah im Lager?",a="Das Lager wurde geplündert, und die Überreste weisen Spuren eines brutalen Angriffs auf.",al={"was hier geschah","geplündertes lager","angriff auf das lager"}},{q="War ein Tier dafür verantwortlich?",a="Die geplünderten Vorräte legen nahe, dass kein Tier den Angriff verübt hat.",al={"tierangriff","war es ein tier","wer griff sie an"}},{q="Stammen die Wunden von Zentauren?",a="Die Wunden passen nicht zu Zentaurenwaffen.",al={"zentaurenangriff","zentaurenwaffen","waren es die zentauren"}},{q="Wer kann den Angriff erklären?",a="Ihr sollt jemanden in Desolace finden, der Erfahrung damit hat, diese Lande nach Brauchbarem zu durchsuchen.",al={"wer kennt sich im lager aus","plünderer fragen","wen finden"}}},fp="15,119,16.330.0,33.63.0,30.73.0,26.65.0,33.41.0,27.80.0"}
P.entries["quest:79235"] = {n="On the Lam",s="Ein Gerücht aus einem Karawanenlager weist auf Horde-Plünderer hin, die nach Angriffen auf Lager von Menschen und Zwergen aus Desolace flohen. Ihr sollt nach Beutebucht reisen und einen von ihnen finden.",h="Ein Gerücht aus einem Karawanenlager weist auf Horde-Plünderer hin, die nach Angriffen auf Lager von Menschen...",kw={"marschall der allianz","beutebucht","karawanen","desolace","horde","plünderer","auf der flucht"},sec={{t="Eine Spur nach Beutebucht",b="Ein Kontakt bei einer Karawane berichtet von Angriffen auf Lager von Menschen und Zwergen in Desolace und weist Euch dann den Weg nach Beutebucht. Die Opfer und die Gewalt haben Karawanen dazu gebracht, Horde-Plünderer zu verdächtigen. Ein Marschall der Allianz verfolgte die Banditen, und sie verließen Desolace. Nun sollt Ihr einen von ihnen finden."}},faq={{q="Wer griff die Lager an?",a="Laut einem Karawanengerücht ist eine Gruppe Horde-Plünderer für die Angriffe auf Lager von Menschen und Zwergen in Desolace verantwortlich.",al={"wer war es","angreifer auf die lager"}},{q="Wohin flohen die Plünderer?",a="Die Banditen flohen aus Desolace, nachdem ein Marschall der Allianz sie verfolgt hatte. Beutebucht wird als möglicher Ort genannt, um einen von ihnen aufzuspüren.",al={"wohin flohen sie","aufenthaltsort der plünderer"}},{q="Warum in Beutebucht suchen?",a="Der Kontakt empfiehlt Beutebucht, weil der Hafen von zwielichtigen Gestalten besucht wird und ein Plünderer vielleicht ein Boot sucht.",al={"warum beutebucht","wo einen plünderer finden"}},{q="Wonach suche ich?",a="Ihr sucht einen der Plünderer aus Desolace.",al={"ziel von auf der flucht","einen finden"}}},fp="10,150,20.286.0,23.97.0,27.116.0,22.130.0,22.55.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="In Beutebucht bietet Tokal ein Getränk für die Wahrheit über Angriffe auf Außenposten von Menschen und Zwergen. Gerüchte geben der Horde die Schuld, doch ihre Bande erfüllte einen privaten Söldnervertrag.",h="In Beutebucht bietet Tokal ein Getränk für die Wahrheit über Angriffe auf Außenposten von Menschen und...",kw={"beutebucht","cherry for your thoughts","kirschgrog","marschall","söldner","plünderung","privater vertrag","tokal"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr erfahren, dass ein privater Geldgeber die Räuber anheuerte, die Lager von Menschen und Zwergen überfielen. Die Horde hat sie nicht angeheuert.",["faction:Horde"]="Als Abenteurer der Horde könnt Ihr von Tokal erfahren, dass private Söldnerverträge zu den Angriffen auf Lager der Allianz führten. Sie waren keine offiziellen Angriffe der Horde."},sec={{t="Das Flüstern in Beutebucht",b="Tokal hält sich in Beutebucht versteckt und hält nach Gesetzeshütern Ausschau. Jüngste Überfälle verwüsteten Lager von Menschen und Zwergen, und Gerüchte geben der Horde die Schuld. Wenn Reisende kommen, die eindeutig nicht für den ermittelnden Marschall arbeiten, erzählt Tokal eine andere Geschichte. Sie bietet an, diese im Austausch für ein Getränk zu erzählen."},{t="Private Söldner",b="Tokal gibt zu, an der Plünderung von Außenposten von Menschen und Zwergen beteiligt gewesen zu sein, sagt aber, die Horde habe die Überfälle nicht verübt. Ihre Bande arbeitete im Rahmen eines privaten Vertrags für einen ungenannten Dritten. Tokal besteht auf einem Kirschgrog, bevor sie verrät, wer den Einsatz bezahlt hat und warum."}},faq={{q="Wer ist Tokal?",a="Tokal ist eine Söldnerin, die sich in Beutebucht versteckt. Ein Marschall untersucht Überfälle auf Siedlungen von Menschen und Zwergen, und Tokal bietet an, für einen Kirschgrog zu verraten, wer sie angeheuert hat.",al={"wer ist tokal","tokal beutebucht","kirschgrog questgeber"}},{q="Warum will Tokal einen Kirschgrog?",a="Tokal will einen Kirschgrog, bevor sie über ihre früheren Aufträge spricht. Dann wird sie erklären, wer die Überfälle auf Lager der Allianz privat finanziert hat.",al={"warum kirschgrog kaufen","kirschgrog tokal","was will tokal"}},{q="War die Horde für die Plünderung der Lager von Menschen und Zwergen verantwortlich?",a="Tokal sagt, die Horde habe die Überfälle auf Lager von Menschen und Zwergen nicht angeordnet. Gerüchte geben der Horde die Schuld, doch ihre Gruppe arbeitete im Rahmen eines privaten Söldnervertrags.",al={"wer hat tokal angeheuert","hat die horde lager der allianz angegriffen","steckte die horde hinter den überfällen"}},{q="Warum macht sich Tokal wegen eines Marschalls Sorgen?",a="Tokal fürchtet einen Marschall, der die Plünderung von Siedlungen von Menschen und Zwergen untersucht. Sie vergewissert sich, dass niemand, der sich ihr in Beutebucht nähert, geschickt wurde, um sie vor Gericht zu bringen.",al={"wer ist der marschall","versteckt sich tokal vor dem marschall","marschall sucht tokal"}},{q="Wo bekommt Ihr Kirschgrog für Tokal?",a="Gastwirte und Schankwirte in Beutebucht verkaufen Kirschgrog. Wenn Ihr Tokal einen Krug bringt, erfüllt Ihr ihre Forderung und bringt sie dazu, ihre Geschichte zu erzählen.",al={"wo gibt es kirschgrog","kirschgrog fundort","beutebucht grog"}},{q="Warum bleibt Tokal in Beutebucht?",a="Beutebucht ist ein Freibeuterhafen außerhalb der strengen Gerichtsbarkeit von Allianz und Horde. Er bietet einer Söldnerin, die sich nach Überfällen auf Lager von Menschen und Zwergen versteckt, einen Ort zum Untertauchen.",al={"warum ist tokal in beutebucht","tokals versteck"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:79242"] = {n="No Honor Among Thieves",s="Ein ehemaliger Dieb nennt Illari Duskfeather als die Nachtelfe, die die Bande anführte und zurückließ. Ihr erfahrt von ihrem Versteck an der Küste des Arathihochlands und ihrem Lager gestohlener Waren.",h="Ein ehemaliger Dieb nennt Illari Duskfeather als die Nachtelfe, die die Bande anführte und zurückließ.",kw={"arathihochland","lager","versteck","illari duskfeather","marschall","nachtelf","keine ehre unter dieben","gestohlene beute","diebe"},ang={["race:NightElf"]="Als Nachtelfe erfahrt Ihr, dass Illari Duskfeather eine Diebesbande anführte und sie zurückließ, als der Marschall sie verfolgte."},sec={{t="Eine verratene Bande",b="Der Marschall ist der Bande auf der Spur, als Illari Duskfeather sie im Stich lässt. Ein überlebender Dieb glaubt, sie seien als Sündenböcke benutzt worden, weiß aber nicht, warum. Er überlässt die Verfolgung allen, die ihr nachgehen wollen. Illari erwähnte einst ein Versteck an der Küste des Arathihochlands, wo ihre gestohlenen Waren noch liegen."}},faq={{q="Wer ist Illari Duskfeather?",a="Illari Duskfeather ist eine Nachtelfe, die eine Diebesbande anführte. Sie versorgte sie mit Informationen über die Lager und behielt nur einige ihrer selteneren Funde.",al={"illari","wer ist illari","hintergrund zu illari duskfeather"}},{q="Warum verließ Illari die Bande?",a="Der überlebende Dieb weiß nicht, warum Illari die Bande im Stich ließ, als der Marschall ihnen auf der Spur war.",al={"warum ging sie","illaris motive","warum die diebe zurücklassen"}},{q="Wo finde ich Illari?",a="Illari erwähnte einst ein Versteck an der Küste des Arathihochlands.",al={"illaris aufenthaltsort","wo ist illari","versteck im arathihochland"}},{q="Was will die Bande von Illari?",a="Ein ehemaliges Mitglied der Bande weist Euch auf Illaris Versteck und ihr Lager gestohlener Waren hin.",al={"illaris lager","gestohlene waren","was ist in ihrem versteck"}},{q="Wer war der Anführer der Bande?",a="Illari Duskfeather, eine Nachtelfe, war die Anführerin der Bande.",al={"diebesboss","bandenanführer","wer führte die diebe an"}}},fp="22,194,15.303.0,26.140.0,30.100.0,24.65.0,36.90.0,24.53.0"}
P.entries["quest:793"] = {n="Zerbrochene Allianzen",s="Gorn schickt Euch nach Osten in die Lethlorklamm, um zwei schwarze Drakes zu befreien, die das Seal of the Earth bindet. Dies folgt auf das erste Zerbrochene Allianzen.",h="Gorn schickt Euch nach Osten in die Lethlorklamm, um zwei schwarze Drakes zu befreien, die das Seal of the...",kw={"schwarzer drachenschwarm","blacklash","schwarzfelsorcs","gorn","hematus","die lethlorklamm","seal of the earth","zeichen der erde"},sec={{t="Drei Runensteine",b="Drei Runensteine halten das Seal of the Earth verschlossen, je einer in den Säulen Diamant, Opal und Amethyst der Lethlorklamm. Gorn gibt Euch das Zeichen der Erde, das die Steine hervorzieht und das Siegel öffnet.\n\nZahllose Drakes leben in der Klamm, und Blacklash und Hematus sind furchterregende Gegner. Gorn will beide tot sehen und ihre Fesseln zurückgebracht haben."},{t="Gorns Sicht der Dinge",b="Gorn sagt, der Schwarze Drachenschwarm sei weiterhin mit den abtrünnigen Schwarzfelsorcs verbündet. Er glaubt, Drachen wie Orcs müssten gezügelt oder vertrieben werden. Wenn Blacklash und Hematus tot sind, kann die Horde ihren Blick nach Westen zur Schwarzfelsspitze richten."}},faq={{q="Wer vergibt diese Quest?",a="Gorn schickt Euch in die Lethlorklamm, als nächsten Schritt nach dem ersten Zerbrochene Allianzen.",al={"zerbrochene allianzen questgeber","gorn standort","wer vergibt zerbrochene allianzen"}},{q="Wo liegt die Lethlorklamm?",a="Die Lethlorklamm liegt im äußersten Osten des Ödlands, wo zahllose Drakes ihr Zuhause haben.",al={"lethlorklamm lage","weg zur lethlorklamm","wo liegt die lethlorklamm"}},{q="Wie befreit Ihr Blacklash und Hematus?",a="Benutzt das Zeichen der Erde, um aus jeder der drei Säulen einen Runenstein hervorzuziehen. Setzt die Steine in das Seal of the Earth ein, um beide Drakes zu befreien.",al={"blacklash beschwören","seal of the earth","säulen diamant opal amethyst"}},{q="Was muss zu Gorn zurückgebracht werden?",a="Sobald beide Drakes tot sind, bringt Gorn die Fesseln von Blacklash, die Ketten von Hematus und das Zeichen der Erde.",al={"zerbrochene allianzen abzugebende gegenstände","was will gorn zurück","fesseln von blacklash"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79358"] = {n="Storm, Earth, and Fire",s="Veyric Thunderhame bittet Euch, verdrehte Elementartotems im Arathihochland zu sammeln. Er hofft, zu erfahren, wie andere Völker Schamanismus praktizieren und wie sich die Elementarmagie der quilboar bekämpfen lässt.",h="Veyric Thunderhame bittet Euch, verdrehte Elementartotems im Arathihochland zu sammeln.",kw={"arathihochland","gegenritual","quilboar","schamanismus","sturm erde und feuer","tausend nadeln","verdrehte totems","veyric thunderhame"},ang={["class:Shaman"]="Als Schamane sollt Ihr Veyric helfen, zu erfahren, wie Völker in ganz Azeroth Schamanismus praktizieren, und die verdrehten Elemente zu verstehen."},sec={{t="Ein Gegenritual",b="Veyric Thunderhame im Arathihochland braucht Eure Hilfe, nachdem die quilboar Tausend Nadeln überflutet haben. Er sagt, ihr Umgang mit den Elementen habe Empörung ausgelöst, und für ein Gegenritual brauche er bessere Kenntnisse dieser verdrehten Kräfte. Ein Buch beschreibt, wie die vielen Völker Azeroths Schamanismus praktizieren. Veyric bittet Euch, ihm verdrehte Totems aus Feuer, Erde, Luft und Wasser zu bringen, damit er von ihnen lernen kann."}},faq={{q="Wer bittet um die Totems?",a="Veyric Thunderhame im Arathihochland bittet Euch, verdrehte Totems aus Feuer, Erde, Luft und Wasser zu sammeln.",al={"wer möchte die totems","veyric bittet darum"}},{q="Warum braucht Veyric die Totems?",a="Veyric möchte die verdrehten Elemente verstehen, während er an einem Gegenritual gegen die Elementarmagie der quilboar arbeitet.",al={"warum totems","wozu sind sie da"}},{q="Was geschah in Tausend Nadeln?",a="Die quilboar überfluteten Tausend Nadeln, und Veyric sagt, ihr Umgang mit den Elementen habe Empörung ausgelöst.",al={"überflutung von tausend nadeln","was haben die quilboar getan"}},{q="Was beschreibt das Buch?",a="Das Buch beschreibt die vielen Völker Azeroths und wie sie Schamanismus praktizieren.",al={"buch über schamanismus","was steht im buch"}},{q="Um welche Totems bittet Veyric?",a="Er bittet um verdrehte Totems aus Feuer, Erde, Luft und Wasser.",al={"totemarten","feuer erde luft wasser"}}},fp="22,198,16.393.0,29.102.0,32.125.0,34.101.0,28.79.0,33.55.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="Ein Ruf, den Elementen ihre Hilfe zu vergelten, führt Euch in den Kral der Klingenhauer. Die quilboar verdrehen elementare Macht, und ihre Pläne bedrohen diese Lande.",h="Ein Ruf, den Elementen ihre Hilfe zu vergelten, führt Euch in den Kral der Klingenhauer.",kw={"charlga klingenflanke","elemental aid","elemente","quilboar","pläne der quilboar","kral der klingenhauer"},ang={["class:Shaman"]="Als Schamane habt Ihr die Elemente gemeistert und sollt Euch für ihre Hilfe erkenntlich zeigen, indem Ihr sie vor den Machenschaften der quilboar schützt."},sec={{t="Ein Ruf an die Elemente",b="Die Elemente haben Euch geholfen, und nun sollt Ihr Euch dafür erkenntlich zeigen. Die quilboar verdrehen ihre Macht für eigene Zwecke und scheinen ihren Einfluss innerhalb dieser Grenzen auszuweiten. Ihr werdet in den Kral der Klingenhauer geschickt, um ihre Machenschaften zu vereiteln und die Lande zu schützen."}},faq={{q="Warum soll ich in den Kral der Klingenhauer gehen?",a="Die quilboar verdrehen die Elemente für eigene Zwecke und scheinen ihren Einfluss auszuweiten. Ihr sollt ihre Machenschaften vereiteln und die Lande schützen.",al={"kral der klingenhauer warum","warum in den kral gehen","grund für elementare hilfe"}},{q="Wer ist Charlga Klingenflanke?",a="Charlga Klingenflanke ist die quilboar, die Ihr im Kral der Klingenhauer besiegen sollt.",al={"charlga wer","charlga klingenflanke","klingenflanke"}},{q="Welche Informationen soll ich sammeln?",a="Ihr sollt Informationen über die Pläne der quilboar sammeln.",al={"pläne der quilboar","welche informationen","informationen zu den plänen"}},{q="Warum sollte ich den Elementen helfen?",a="Die Elemente haben Euch geholfen, und nun sollt Ihr Euch dafür erkenntlich zeigen, indem Ihr die Lande vor den Machenschaften der quilboar schützt.",al={"warum elementare hilfe","den elementen helfen","den elementen vergelten"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="Prate Cloudseer bittet Euch, die Stacheleber daran zu hindern, Tausend Nadeln durch verderbten Schamanismus zu überfluten. Ein Foliant für Eure Ausbildung könnte helfen, den nahenden Sturm zu zerstreuen.",h="Prate Cloudseer bittet Euch, die Stacheleber daran zu hindern, Tausend Nadeln durch verderbten Schamanismus...",kw={"prate cloudseer","stacheleber","sturm erde und feuer","tausend nadeln","foliant","verderbter schamanismus","verderbte totems"},sec={{t="Ein Sturm zieht auf",b="Prate Cloudseer wollte Eure Ausbildung fortsetzen, doch die Bedrohung in Tausend Nadeln duldet keinen Aufschub. Ihr habt gesehen, dass die Stacheleber nicht zu unterschätzen sind. Prate gibt Euch einen Folianten, der zum Studium gedacht war, und bittet Euch, verderbte Feuer-, Erd-, Luft- und Wassertotems zu sammeln. Der Foliant könnte einen Weg aufzeigen, den Sturm zu zerstreuen, den sie heraufbeschwören."}},faq={{q="Wer bittet um Hilfe?",a="Prate Cloudseer bittet Euch, verderbte Totems in Tausend Nadeln zu sammeln.",al={"wer ist prate","prate cloudseer","cloudseer"}},{q="Was haben die Stacheleber vor?",a="Prate sagt, dass die Stacheleber Tausend Nadeln durch verderbten Schamanismus überfluten wollen.",al={"plan der stacheleber","warum die totems","sturm der stacheleber"}},{q="Was gibt Prate mir?",a="Prate gibt Euch einen Folianten, der zum Studium gedacht war und helfen könnte, den nahenden Sturm zu zerstreuen.",al={"foliant","was ist das buch","foliant zum studium"}},{q="Welche Totems braucht Prate?",a="Prate bittet Euch, verderbte Feuer-, Erd-, Luft- und Wassertotems zu sammeln.",al={"totemarten","feuer erde luft wasser","welche totems"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Grant's Shield",s="Sirra Von’Indie sucht Grant Valors Streitkolben auf dem Friedhof von Rabenflucht, wo sein Geist noch immer gegen die Untoten kämpft. Die Waffen könnten ihr helfen, mehr über den stolzen Helden zu erfahren.",h="Sirra Von’Indie sucht Grant Valors Streitkolben auf dem Friedhof von Rabenflucht, wo sein Geist noch immer...",kw={"dunkelhain","grant valor","grants streitkolben","grants schild","friedhof von rabenflucht","sirra von'indie","untoter","valor family"},sec={{t="Ein gefallener Held",b="Sirra Von’Indie in Dunkelhain bittet Euch, Grant Valors Streitkolben unter den Skeletten auf dem Friedhof von Rabenflucht zu finden. Grants Schild wurde von seinem Gespenst zurückgelassen, und sein Geist kämpft dort noch immer gegen die Untoten. Der Streitkolben könnte auf die Kreatur hinweisen, die ihn verletzt hat, und Sirra möchte die Waffen untersuchen."},{t="Die Waffen",b="In Dunkelhain denkt Sirra Von’Indie darüber nach, wie eine einfache Kreatur Grant Valor zu Fall brachte. Sie sagt, ein einziger Fehltritt könne einen Menschen fürs Leben zum Krüppel machen. Die Waffen verraten ihrer Ansicht nach viel über ihren Besitzer, und sie nimmt sich Zeit, sie zu untersuchen."}},faq={{q="Wer war Grant Valor?",a="Grant Valor war der Vater der Valor Family und ein Held von Rabenflucht. Sein Gespenst kämpft noch immer gegen die Untoten.",al={"grant valor","wer ist grant","grants vorgeschichte"}},{q="Wo ist Grants Streitkolben?",a="Grants Streitkolben befindet sich bei einem der Skelette auf dem Friedhof von Rabenflucht.",al={"grants streitkolben","grants streitkolben finden","fundort des streitkolbens"}},{q="Warum suche ich Grants Streitkolben?",a="Sirra Von’Indie bittet Euch, den Streitkolben zu finden, damit sie mehr aus Grants Waffen erfahren kann.",al={"warum den streitkolben finden","grants schild quest","was will sirra"}},{q="Wohin bringe ich den Streitkolben?",a="Bringt Grants Streitkolben zu Sirra Von’Indie in Dunkelhain zurück.",al={"streitkolben zurückbringen","sirras aufenthaltsort","wo ist von'indie"}},{q="Was ist Grant zugestoßen?",a="Grant wurde von einer Kreatur auf dem Friedhof von Rabenflucht verletzt. Sein Geist kämpft dort noch immer gegen die Untoten.",al={"grant verletzt","wie wurde grant verletzt","grant valors schild"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="Silvias Schwert",s="Silvia Valors Schwert, von ihrem Geist zurückgelassen, weist Euch zu den Defias bei Rabenflucht. Die Klinge gehörte einer Wache, die Zivilisten und ihre Häuser schützte.",h="Silvia Valors Schwert, von ihrem Geist zurückgelassen, weist Euch zu den Defias bei Rabenflucht.",kw={"addles siedlung","dunkelhain","defias","wächterin","rabenflucht","silvia valor","silvias schwert","sirra von'indi","unerledigte angelegenheiten"},sec={{t="Die Klinge einer Wächterin",b="Der Geist von Silvia Valor, der Wache von Rabenflucht, hat ihr Schwert zurückgelassen. Silvia verbrachte ihr Leben damit, Zivilisten und ihre Häuser zu verteidigen. Ihr Geist besucht noch immer Gehöfte, und die Defias haben sich in Addles Siedlung südlich von Rabenflucht niedergelassen. Sie zu vertreiben, könnte ihre unerledigte Aufgabe sein, und Sirra Von'Indi in Dunkelhain wartet darauf, zu hören, was daraus wird."},{t="Die Untersuchung der Klinge",b="In Addles Siedlung sind die Defias die erste Spur zu Silvia Valors unerledigten Angelegenheiten. Als Ihr zu Sirra Von'Indi in Dunkelhain zurückkehrt, würdigt sie Silvia als vortreffliche Kriegerin und Verteidigerin, die allerdings enge Vorstellungen davon hatte, wer Schutz verdiente. Sirra kann nicht erkennen, was Silvia von dem Schwert will, also untersucht sie die Klinge weiter."}},faq={{q="Wer war Silvia Valor?",a="Silvia Valor war eine Wächterin in Rabenflucht, die ihr Leben damit verbrachte, Zivilisten und ihre Häuser zu beschützen.",al={"silvia valor hintergrundgeschichte","wer ist silvia","rabenflucht wächterin silvia"}},{q="Warum sucht Silvias Geist Gehöfte auf?",a="Silvias Geist besucht noch immer Gehöfte, und ihre unerledigte Aufgabe könnte mit den Defias in Addles Siedlung zu tun haben.",al={"silvia geist warum","warum sucht sie bauernhöfe heim","silvia unerledigte angelegenheiten"}},{q="Wer fragt nach Silvias Schwert?",a="Sirra Von'Indi in Dunkelhain greift die Geschichte des Schwertes auf. Ihr kehrt zu ihr zurück, um mehr über Silvia Valor zu erfahren, sobald die Defias in Addles Siedlung bezwungen sind.",al={"wer gab silvias schwert","sirra von'indi schwert","dunkelhain schwert questgeber"}},{q="Wo haben sich die Defias niedergelassen?",a="Die Defias haben sich in Addles Siedlung südlich von Rabenflucht niedergelassen.",al={"defias addles siedlung","wo sind die defias","rabenflucht defias"}},{q="Was hält Sirra von Silvia?",a="Sirra nennt Silvia eine vortreffliche Kriegerin und Verteidigerin, sagt jedoch, Silvia habe enge Vorstellungen davon gehabt, wer Schutz verdiente.",al={"sirras meinung über silvia","silvia kriegerin","was für eine wächterin war silvia"}},{q="Was macht Sirra mit dem Schwert?",a="Sirra untersucht Silvia Valors Klinge weiter.",al={"was geschieht mit der klinge","sirra untersucht schwert","silvia schwert nächster schritt"}}},fp="14,154,15.360.0,17.332.1,21.95.0,43.109.0,30.150.0,41.73.0,32.116.0,34.43.0"}
P.entries["quest:79364"] = {n="Eyes on the Sky",s="Eine Notiz warnt, dass die Razormane in Tausend Nadeln ein verborgenes Ritual vollziehen. Ihr sollt eine Antwort auf die Bedrohung durch Stürme und steigende Fluten suchen.",h="Eine Notiz warnt, dass die Razormane in Tausend Nadeln ein verborgenes Ritual vollziehen.",kw={"elementare zauberei","augen zum himmel","hirzek","prate cloudseer","stacheleber","razormane","steigende fluten","ritual","stürme","tausend nadeln"},sec={{t="Eine wachsende Bedrohung",b="Die Notiz, die Ihr gefunden habt, verweist auf die Razormane in Tausend Nadeln, wo ein verborgenes Ritual im Gange ist. Tobende Stürme und steigende Fluten wecken die Furcht, dass die Schlucht überschwemmt werden könnte. Die Stacheleber nutzen womöglich elementare Macht, deren Gebrauch sie von Hirzek, einem Schamanen, erlernt haben. Kehrt zu Euren Verbündeten zurück und sprecht mit Prate Cloudseer."}},faq={{q="Was steht in der Notiz?",a="Darin steht, dass sich die Razormane für ein verborgenes Ritual in Tausend Nadeln eingegraben haben, während Stürme toben und die Fluten steigen.",al={"notiz in tausend nadeln","welche notiz","notiz der razormane"}},{q="Wer ist Hirzek?",a="Hirzek ist ein Schamane, der die Stacheleber Zauberei gelehrt hat, die die Elemente verdreht.",al={"hirzek","hirzek schamane","wer ist hirzek"}},{q="Welche Bedrohung geht von den Stachelebern aus?",a="Es wird befürchtet, dass die Stacheleber elementare Macht nutzen könnten, um die Schlucht zu überschwemmen.",al={"bedrohung durch stacheleber","ritual der razormane","was machen die stacheleber"}},{q="Mit wem soll ich sprechen?",a="Ihr sollt mit Prate Cloudseer in Tausend Nadeln sprechen.",al={"wohin gehen","wen finden","prate cloudseer"}}},fp="15,160,18.309.0,23.116.0,14.76.0,33.85.0,24.64.0"}
P.entries["quest:79365"] = {n="With Wind Beneath Your Wings",s="Ein Squall-breakers Potion bietet kurzen Schutz vor den Elementen des Sturms. Ihr werdet zu Rau Klippenläufer am Freiwindposten in Tausend Nadeln zurückgeschickt.",h="Ein Squall-breakers Potion bietet kurzen Schutz vor den Elementen des Sturms.",kw={"freiwindposten","rau klippenläufer","squall-breakers potion","sturm","tausend nadeln"},sec={{t="Zurück zum Freiwindposten",b="Der Sturm bedroht Eure Freunde noch immer, und der Schutz des Tranks hält nur kurze Zeit an. Kehrt zu Rau Klippenläufer am Freiwindposten in Tausend Nadeln zurück, wo Eure Freunde dringend Hilfe brauchen."}},faq={{q="Was bewirkt der Trank?",a="Squall-breakers Potion schützt Euch kurze Zeit vor den Elementen des Sturms.",al={"schutz durch trank","squall-breakers potion"}},{q="Zu wem soll ich zurückkehren?",a="Kehrt zu Rau Klippenläufer am Freiwindposten in Tausend Nadeln zurück.",al={"wohin gehen","rau klippenläufer"}},{q="Warum soll ich zurückkehren?",a="Ihr werdet zu Euren Freunden zurückgeschickt, die dringend Hilfe brauchen.",al={"freunde in not","zu freunden zurückkehren"}}},fp="28,152,16.197.0,24.92.0,23.63.0,20.48.0"}
P.entries["quest:79366"] = {n="Heed My Call",s="Ihr setzt die Twisted Totems gegen das Razormane-Ritual ein und kehrt dann zu Rau Klippenläufer zurück. Die verderbten Elementare drohen, das Land unrein zu hinterlassen.",h="Ihr setzt die Twisted Totems gegen das Razormane-Ritual ein und kehrt dann zu Rau Klippenläufer zurück.",kw={"verderbte elementare","der irdene ring","heed my call","quilboar","rau klippenläufer","razormane","ritual","steam pools","twisted totems"},sec={{t="Bei den Steam Pools",b="Mit den Twisted Totems in der Hand seid Ihr bereit, das Razormane-Ritual zu unterbrechen. Man weist Euch an, bei den Dampfteichen im Westen zu beginnen, wo jedes Element reichlich vorhanden ist. Die quilboar werden sich Euren Bemühungen widersetzen. Setzt die Totems gegen das Ritual und seine verderbten Elementare ein."},{t="Raus Dank",b="Rau Klippenläufer fragt, ob Ihr Neuigkeiten vom Sturm habt. Als Ihr zurückkehrt, weiß er, dass das Grollen des Bodens verstummt ist, und dankt Euch dafür, dass Ihr den Irdenen Ring stolz gemacht habt."}},faq={{q="Was möchte Rau Klippenläufer, dass ich tue?",a="Rau Klippenläufer möchte, dass Ihr mit den Twisted Totems das Ritual der quilboar beendet und ihm dann von Eurem Erfolg berichtet.",al={"aufgabe von rau klippenläufer","was möchte rau"}},{q="Wo soll ich anfangen?",a="Beginnt bei den Dampfteichen im Westen, wo jedes Element reichlich vorhanden ist.",al={"wo anfangen","steam pools"}},{q="Wozu dienen die Twisted Totems?",a="Die Twisted Totems sollen die verderbten Elementare herbeirufen, auf die sich die quilboar berufen.",al={"twisted totems","zweck der totems"}},{q="Wer führt das Ritual durch?",a="Die Razormane quilboar führen das Ritual durch und rufen verderbte Elementare herbei.",al={"wer führt das ritual durch","ritual der razormane"}},{q="Warum könnten die quilboar sich widersetzen?",a="Man warnt Euch, dass die quilboar nicht untätig bleiben werden, während Ihr ihre Pläne durchkreuzt.",al={"quilboar widersetzen sich","warum greifen sie mich an"}}},fp="12,155,18.271.0,12.170.1,40.122.0,21.70.0,32.87.0,29.84.0,30.83.0"}
P.entries["quest:794"] = {n="Medaillon der Brennenden Klinge",s="Zureetha Fernblick schickt junge Initianden der Horde in die Höhle im Tal der Prüfungen, wo sich die Burning Blade versammelt hat. Sie stellen sich einem verborgenen Kultisten und suchen das Medaillon der Brennenden Klinge. Seine Gegenwart deutet auf dämonische Verderbnis nahe der Horde hin.",h="Zureetha Fernblick schickt junge Initianden der Horde in die Höhle im Tal der Prüfungen, wo sich die Burning...",kw={"burning blade","koven","durotar","medaillon","the den","das tal der prüfungen","hexenmeister","yarrog baneshadow","zureetha fernblick"},ang={["class:Shaman"]="Als Schamane helft Ihr Zureetha Fernblick durch die Bergung des verderbten Relikts, dämonische Verderbnis aufzudecken, die Durotars Erde entweiht.",["class:Warlock"]="Als Hexenmeister erinnert Euch die Begegnung mit Yarrog an die Gefahren eigenmächtiger Dämonenverehrung jenseits der gebilligten, sorgfältig verborgenen Pakte, die unter Thralls Herrschaft geschlossen wurden.",["faction:Horde"]="Als Mitglied der Horde zeigt diese letzte Prüfung, dass Ihr bereit seid, in Durotars weite Wildnis aufzubrechen und die junge Nation zu verteidigen.",["race:Orc"]="Als Orc zeigt Euch die Jagd auf Yarrog Baneshadow den Kampf der neuen Horde, ihre Ausbildungsstätten vom anhaltenden dämonischen Makel der alten Wege zu reinigen."},sec={{t="Verborgene Bedrohung im Tal",b="Junge Orcs und Trolle stellen sich im Tal der Prüfungen den Prüfungen des Kampfes und des Überlebens. In der Nähe sammelt sich eine Bedrohung. Durch Weissagung spürt die Hexenmeisterin Zureetha Fernblick, dass die üblen Familiare auf den nördlichen Klippen nur die Vorhut einer dunkleren Präsenz sind. Tief in einer nahen Höhle hat der Kult der Burning Blade einen verborgenen Koven gebildet. Seine Anhänger praktizieren dunkle Künste und bewahren gefährliche Relikte dämonischer Macht auf."},{t="Yarrog Baneshadow entgegentreten",b="Yarrog Baneshadow, ein Orc-Hexenmeister und Agent der Burning Blade, besitzt das Medaillon. Er wartet auf einem erhöhten Felsvorsprung tief im unterirdischen Bau, befehligt Teufelsbestien und wirkt dunkle Magie, fernab der wachsamen Blicke der Aufseher des Tals. Ihn zu besiegen und das Medaillon an sich zu nehmen, zerschlägt die örtliche Führung des Kults, bevor sich dessen Rituale weiter in Durotar ausbreiten."},{t="Der bleibende Schatten",b="Das Medaillon bestätigt Zureetha Fernblicks Befürchtungen. Der Koven im Tal der Prüfungen wurde zerschlagen, doch das Relikt zeigt, dass die Burning Blade organisiert und zielgerichtet vorgeht. Ihr Einfluss reicht über das Ausbildungsgelände hinaus. Die junge Horde steht größeren dämonischen Verschwörungen in ganz Durotar gegenüber."}},faq={{q="Wo finde ich den Koven der Brennenden Klinge?",a="Der Koven der Brennenden Klinge liegt in einer Höhle zwischen den Klippen nördlich und westlich des Den im Tal der Prüfungen. Wichtelartige üble Familiare umgeben sie.",al={"standort der kovenhöhle","wo ist die höhle","burning blade höhle tal der prüfungen"}},{q="Wer trägt das Medaillon der Brennenden Klinge?",a="Yarrog Baneshadow trägt das Medaillon. Er befindet sich tief in der Höhle, auf einem erhöhten Felsvorsprung hinter einem flachen Wasserbecken.",al={"wer lässt das medaillon fallen","yarrog baneshadow","medaillon gegner"}},{q="Was ist die Burning Blade?",a="Die Burning Blade ist ein verräterischer Kult aus von Teufelsmagie verderbten Orcs und Hexenmeistern, die dämonischen Mächten dienen. Ihre Mitglieder schmieden in verborgenen Bauen und Lagern Pläne gegen Thralls neue Horde.",al={"wer ist die burning blade","burning blade kult","was ist die burning blade"}},{q="Warum ist das Medaillon für Zureetha Fernblick so wichtig?",a="Durch Weissagung sah Zureetha Fernblick das Medaillon. Der machtvolle Gegenstand nährt die dunklen Rituale des Kults und beweist, dass dämonische Agenten das Tal der Prüfungen unterwandern.",al={"warum will zureetha es","was ist das medaillon","zureetha fernblick medaillon"}},{q="Ist der Kult in Durotar mit Yarrog endgültig besiegt?",a="Nein. Yar rogs Niederlage reinigt die Höhle im Tal der Prüfungen, doch Zureetha warnt, dass dieser Koven nur eine kleine Zelle ist. Die Burning Blade verfolgt größere Ziele in ganz Durotar.",al={"ist die burning blade vernichtet","sind sie verschwunden","nach medaillon der brennenden klinge"}},{q="Was geschieht nach der Abgabe des Medaillons?",a="Nachdem Ihr Yarrog erschlagen und das Relikt geborgen habt, habt Ihr Euch bewiesen und seid bereit, das Tal der Prüfungen zu verlassen. Ihr werdet nach Sen’jin Village an Durotars Südküste geschickt, um dort Bericht zu erstatten.",al={"nächste quest","what comes next","nach dieser quest"}}},fx={["29893710"]={q="Wofür ist das Medaillon der Brennenden Klinge?",a="Durch ihre Weissagungen identifizierte Zureetha Fernblick das Medaillon als ein mächtiges Objekt schwarzer Magie, das tief im Koven der Brennenden Klinge aufbewahrt wird. Es befindet sich im Besitz von Yarrog Baneshadow und dient als Artefakt dämonischer Macht und als Emblem des bleibenden Einflusses des Schattenrates direkt vor der Haustür der Horde.",al={"zweck des medaillons der brennenden klinge","was bewirkt das medaillon der brennenden klinge","warum ist das medaillon mächtig"}}},fp="23,237,29.405.0,29.348.1,20.290.1,40.143.0,44.124.0,26.183.0,54.170.0,53.177.0,44.191.0"}
P.entries["quest:79442"] = {n="The Tempest's Weapons",s="Ein alter Schamane im Alteracgebirge weiß vielleicht, wie man das Eye of the Tempest benutzt. Ihr bringt ihm das Artefakt, damit er mit seiner Sturmmagie etwas daraus fertigen kann.",h="Ein alter Schamane im Alteracgebirge weiß vielleicht, wie man das Eye of the Tempest benutzt.",kw={"alteracgebirge","bath'rah","bath'rah der windbehüter","eye of the tempest","schamane","magie der sturmelementare","the tempest's weapons"},ang={["class:Shaman"]="Als Schamane bringt Ihr Bath'rah, einem alten Schamanen mit einem Gespür für diese Magie, ein mächtiges Artefakt der Sturmelementarmagie."},sec={{t="Ein alter Schamane",b="Nach dem Kampf mit den Elementaren bringt Ihr Bath'rah dem Windbehüter das Eye of the Tempest ins Alteracgebirge. Er hat ein Gespür für die Magie der Sturmelementare und erkennt die Macht des Artefakts. Bath'rah sagt, dass er seit Langem nichts Vergleichbares bearbeitet hat, und mahnt Euch, gut darauf aufzupassen."}},faq={{q="Wer ist Bath'rah?",a="Bath'rah der Windbehüter ist ein alter Schamane im Alteracgebirge mit einem Gespür für die Magie der Sturmelementare.",al={"bath'rah windbehüter","alter schamane","wer ist bath'rah"}},{q="Was ist das Eye of the Tempest?",a="Das Eye of the Tempest ist ein mächtiges Artefakt, das mit der Magie der Sturmelementare verbunden ist.",al={"auge des sturms","augenartefakt","was ist das auge"}},{q="Warum bringt Ihr das Auge zu Bath'rah?",a="Bath'rah kann vielleicht etwas aus dem Eye of the Tempest fertigen, da er die Magie der Sturmelementare versteht.",al={"warum bath'rah","the tempest's weapons quest","wohin das auge bringen"}},{q="Was sagt Bath'rah über das Artefakt?",a="Bath'rah nennt das Eye of the Tempest mächtig und sagt, dass er seit Langem nichts Vergleichbares gefertigt hat.",al={"bath'rahs reaktion","was sagt er","abschluss mit dem auge"}}},fp="21,147,13.305.0,16.105.0,31.84.0,30.113.0,42.112.0"}
P.entries["quest:79535"] = {n="Basilisks: Should Petrification be Feared?",s="Eine Bibliothekarin bittet Euch, magische Werke zu bringen, die den Bestand der Bibliothek bereichern könnten. Eure Entdeckungen helfen, ihr Wissen zu erweitern.",h="Eine Bibliothekarin bittet Euch, magische Werke zu bringen, die den Bestand der Bibliothek bereichern könnten.",kw={"basilisken","sammlung","wissen","library","magische werke","versteinerung"},sec={{t="Eine wachsende Sammlung",b="Die Bibliothekarin dankt Euch dafür, dass Ihr die Sammlung erweitert habt. Eure Mühen bringen neues Wissen in die Bibliothek, und weitere magische Werke könnten dort willkommen sein."}},faq={{q="Was möchte die Bibliothekarin?",a="Die Bibliothekarin freut sich über magische Werke, die der Sammlung zugutekommen könnten.",al={"anfrage der bibliothek","was soll ich bringen"}},{q="Warum werden magische Werke gesucht?",a="Die Bibliothekarin sagt, sie könnten der Bibliothek zugutekommen und ihr Wissen erweitern.",al={"warum bücher","wozu dienen sie"}},{q="Was geschieht, wenn ich etwas bringe?",a="Die Bibliothekarin dankt Euch und sagt, Eure Mühen erweitern das Wissen der Bibliothek.",al={"erweiterung der sammlung","was habe ich hinzugefügt"}}},fp="42,133,20.151.0,29.71.0,29.73.0,36.79.0"}
P.entries["quest:79624"] = {n="Anyone Can Cook",s="Ein unleserliches Rezept scheint ein Fleischgericht zu beschreiben, und Ihr vermutet Ogerschrift. Findet einen Oger, der es lesen kann.",h="Ein unleserliches Rezept scheint ein Fleischgericht zu beschreiben, und Ihr vermutet Ogerschrift.",kw={"jeder kann kochen","unleserliches rezept","fleischgericht","oger","rezept","skonk","übersetzung"},ang={["profession:Cooking"]="Als Koch habt Ihr Grund, Euch zu fragen, welche Art von Fleischgericht das unleserliche Rezept beschreibt."},sec={{t="Ein seltsames Rezept",b="Das Rezept ist in einer Sprache verfasst, die Ihr nicht lesen könnt, und scheint ein Fleischgericht zu beschreiben. Angesichts seiner Herkunft und seines Inhalts vermutet Ihr am ehesten Ogerisch. Ihr hofft, einen Oger zu finden, der es übersetzen kann."}},faq={{q="Wofür ist das Rezept?",a="Es scheint für eine Art Fleischgericht zu sein.",al={"zweck des rezepts","welches gericht","fleischrezept"}},{q="In welcher Sprache ist das Rezept verfasst?",a="Ihr versteht die Sprache nicht. Ihr vermutet am ehesten Ogerisch.",al={"sprache des rezepts","welche schrift","rezept nicht lesbar"}},{q="Wer kann das Rezept lesen?",a="Ihr sucht einen Oger, der es lesen kann.",al={"rezept übersetzen","wer kann es lesen","oger als leser"}},{q="Wer ist Skonk?",a="Skonk ist ein Oger, der nach dem Rezept lauscht.",al={"skonk","wer ist skonk","oger skonk"}}},fp="15,112,16.213.0,23.44.0,39.60.0,24.44.0,13.49.0"}
P.entries["quest:79677"] = {n="A Quick Grocery Run",s="Skonk bittet Euch, im Arathihochland Zutaten für ein Gericht zu sammeln. Er lernte kochen, nachdem andere Oger seine Größe und seine Kampffähigkeiten verspottet hatten.",h="Skonk bittet Euch, im Arathihochland Zutaten für ein Gericht zu sammeln.",kw={"arathihochland","kochen","gericht","zutaten","oger","skonk","hänseleien"},ang={["profession:Cooking"]="Als Koch könnt Ihr Skonk helfen, Zutaten für ein Gericht zu sammeln, das er zubereiten kann."},sec={{t="Skonks Zutaten",b="Skonk, ein Oger im Arathihochland, braucht Zutaten für ein Gericht, das er zubereiten kann. Andere Oger lachten über seine Größe und nannten ihn schwach, also wandte er sich dem Kochen zu. Ihr sammelt die Zutaten und bringt sie ihm."}},faq={{q="Wer ist Skonk?",a="Skonk ist ein Oger, der kochen lernte, nachdem andere Oger seine Größe und seine Kampffähigkeiten verspottet hatten.",al={"skonk","wer ist skonk"}},{q="Warum kocht Skonk?",a="Andere Oger lachten über Skonk, weil er kleiner war, und nannten ihn schwach, also lernte er kochen, statt zu kämpfen.",al={"warum kochen","skonk kochen"}},{q="Was braucht Skonk?",a="Skonk braucht Zutaten für ein Gericht, das er zubereiten kann.",al={"zutaten","welche zutaten"}},{q="Wohin bringe ich die Zutaten?",a="Bringt die Zutaten zu Skonk im Arathihochland.",al={"wo ist skonk","zutaten bringen"}}},fp="19,143,19.214.0,13.92.0,20.107.0,21.47.0,33.51.0"}
P.entries["quest:79678"] = {n="Taste Testing",s="Skonk lädt Euch ein, ein neues Gericht am heißen Feuer zu kosten. So teilt er es mit einem neuen Freund, der ihm geholfen hat.",h="Skonk lädt Euch ein, ein neues Gericht am heißen Feuer zu kosten.",kw={"gericht","feuer","essen","rezept","skonk","verkostung","kosten"},sec={{t="Ein neues Gericht",b="Skonk hat am Feuer ein neues Gericht zubereitet und möchte es mit Euch teilen. Nach all den Gefallen, die Ihr ihm getan habt, findet er, dass auch Ihr es probieren solltet. Das Rezept ist bereit zur Verkostung."}},faq={{q="Wer ist Skonk?",a="Skonk bereitet ein neues Gericht zu und lädt Euch ein, es zu kosten.",al={"skonk","wer ist skonk"}},{q="Was möchte Skonk, dass ich tue?",a="Skonk möchte, dass Ihr das Rezept gemeinsam mit ihm kostet.",al={"kostprobe","was möchte skonk"}},{q="Warum teilt Skonk das Gericht?",a="Skonk sagt, Ihr habt ihm viele Gefallen getan, deshalb möchte er, dass Ihr sein neues Gericht probiert.",al={"warum essen","warum teilen"}},{q="Was hält Skonk vom Rezept?",a="Nach der Verkostung sagt Skonk, dass das Rezept köstlich ist.",al={"schmeckt es","rezept kosten"}}},fp="13,131,10.189.0,13.55.0,30.45.0,30.78.0,36.54.0"}
P.entries["quest:79947"] = {n="Geomancy: The Stone-Cold Truth",s="Ein Bibliothekar sucht magische Werke für die Sammlung der Bibliothek. Euer Beitrag kann ihr Wissen erweitern.",h="Ein Bibliothekar sucht magische Werke für die Sammlung der Bibliothek.",kw={"sammlung","geomantie","library","magische werke","eiskalte wahrheit"},sec={{t="Eine wachsende Sammlung",b="Jedes magische Werk, das Ihr findet, kann einen Platz in den Regalen der Bibliothek erhalten. Durch Eure Bemühungen wächst ihre Sammlung, und der Bibliothekar freut sich über weitere Entdeckungen."}},faq={{q="Was möchte der Bibliothekar?",a="Der Bibliothekar bittet Euch, magische Werke zu bringen, die der Sammlung der Bibliothek zugutekommen könnten.",al={"was möchten sie","bibliotheksanfrage"}},{q="Woher stammt diese Bitte?",a="Der Auftrag stammt von einem Bibliothekar: Garion Wendell in Sturmwind für die Allianz oder Owen Thadd in der Unterstadt für die Horde.",al={"wo ist die bibliothek","bibliothek von eisenschmiede"}},{q="Warum magische Werke bringen?",a="Der Bibliothekar sagt, dass das Wissen der Bibliothek durch Eure Bemühungen wächst.",al={"warum magische bücher","wofür sind sie"}}},fp="30,110,20.159.0,29.90.0,27.118.0,24.72.0"}
P.entries["quest:79948"] = {n="Defensive Magics 101",s="Die Bibliothek sucht magische Werke für ihre Sammlung. Ihr könnt ihr Wissen erweitern, indem Ihr Werke bringt, die den Regalen zugutekommen könnten.",h="Die Bibliothek sucht magische Werke für ihre Sammlung.",kw={"sammlung","defensive magien","wissen","library","magische werke"},sec={{t="Eine wachsende Sammlung",b="Die Sammlung der Library kann durch Eure Bemühungen wachsen. Bringt ihrem Verwalter magische Werke, die den Regalen zugutekommen könnten, und das Wissen der Library wächst."}},faq={{q="Was braucht die Library?",a="Die Library sucht magische Werke, die ihrer Sammlung zugutekommen könnten.",al={"library-bedarf","was bringen","magische bücher"}},{q="Woher stammt diese Bitte?",a="Die Anfrage kommt von einem Bibliothekar. Für die Allianz ist das Garion Wendell in Sturmwind, für die Horde Owen Thadd in Unterstadt.",al={"wer möchte das","library-anfrage","welche bibliothek"}},{q="Warum magische Werke bringen?",a="Magische Werke, die der Library gebracht werden, erweitern ihr Wissen.",al={"warum magie sammeln","wozu dient es","library-sammlung"}}},fp="20,137,20.153.0,27.66.0,27.135.0,24.58.0"}
P.entries["quest:79949"] = {n="A Web of Lies: Debunking Myths and Legends",s="Ein Bibliothekar sucht magische Werke, um die Sammlung der Library zu erweitern. Ihr könnt Schriften bringen, die ihren Bestand bereichern könnten.",h="Ein Bibliothekar sucht magische Werke, um die Sammlung der Library zu erweitern.",kw={"bücher","sammlung","wissen","bibliothekar","library","magische werke"},sec={{t="Eine wachsende Sammlung",b="Jedes neue Buch ist in diesen Regalen willkommen. Magische Schriften können das Wissen der Bibliothek erweitern, und Eure Entdeckungen können dazu beitragen, dass ihr Wissen wächst."}},faq={{q="Was möchte der Bibliothekar?",a="Der Bibliothekar sucht magische Werke, die der Sammlung zugutekommen könnten.",al={"was der bibliothekar braucht","anfrage der bibliothek","was zur bibliothek bringen"}},{q="Wohin soll ich die Bücher bringen?",a="Bringt die magischen Werke dem Bibliothekar Garion Wendell in Sturmwind oder Owen Thadd in der Unterstadt, wenn Ihr der Horde angehört.",al={"wo ist die bibliothek","bibliothek in eisenschmiede","wohin magische werke bringen"}},{q="Warum magische Werke sammeln?",a="Der Bibliothekar sagt, dass die Sammlung das Wissen der Bibliothek erweitert.",al={"warum bücher bringen","wozu dient die sammlung","zweck der bibliothek"}}},fp="42,122,20.145.0,29.68.0,31.117.0,26.68.0"}
P.entries["quest:79950"] = {n="Demons and You",s="Ein Bibliothekar bittet Euch, ein magisches Werk zur Sammlung hinzuzufügen. Eure Bemühungen erweitern das Wissen der Library.",h="Ein Bibliothekar bittet Euch, ein magisches Werk zur Sammlung hinzuzufügen.",kw={"sammlung","demons and you","wissen","library","magische werke"},sec={{t="Eine Sammlung in der Library",b="Jedes magische Werk, das Ihr mitbringt, ist in den Regalen willkommen. Die Sammlung wächst durch Eure Bemühungen, und der Hüter begrüßt weitere Werke, die der Bibliothek zugutekommen könnten."}},faq={{q="Was möchte der Bibliothekar?",a="Der Bibliothekar bittet Euch, ein magisches Werk zu bringen, das der Sammlung der Library hinzugefügt werden soll.",al={"was soll ich bringen","anfrage der library","quest demons and you"}},{q="Wo befindet sich die Sammlung?",a="Der Hüter ist Bibliothekar. Das ist Garion Wendell in Sturmwind für die Allianz oder Owen Thadd in der Unterstadt für die Horde.",al={"wo ist das","standort der library","welche bibliothek"}},{q="Warum sollt Ihr der Library magische Werke bringen?",a="Der Bibliothekar sagt, dass Eure Bemühungen das Wissen der Library erweitern.",al={"warum bücher spenden","wozu dient das","zweck der library"}}},fp="14,118,20.166.0,34.81.0,24.126.0,39.62.0"}
P.entries["quest:79951"] = {n="Mummies: A Guide to the Unsavory Undead",s="Ein Bibliothekar sucht magische Werke über Mumien und widerwärtige Untote für seine Sammlung. Euer Beitrag hilft, das Wissen der Bibliothek zu erweitern.",h="Ein Bibliothekar sucht magische Werke über Mumien und widerwärtige Untote für seine Sammlung.",kw={"bücher","sammlung","library","magische werke","mumien","widerwärtige untote"},sec={{t="Eine wachsende Sammlung",b="Die Sammlung der Bibliothek ist auf Werke angewiesen, die Besucher mitbringen. Ihr werdet gebeten, etwas über Mumien und widerwärtige Untote beizusteuern, und auch weitere magische Bücher können nützlich sein. Jedes solche Werk kann das Wissen der Bibliothek erweitern."}},faq={{q="Was sammelt der Bibliothekar?",a="Der Bibliothekar sucht Werke über Mumien und widerwärtige Untote sowie weitere magische Bücher, die der Bibliothek nützen könnten.",al={"mumienbücher","führer zu untoten","welche bücher werden gesucht"}},{q="Warum soll ich der Bibliothek ein Buch bringen?",a="Die Werke, die Ihr dem Bibliothekar bringt, erweitern das Wissen der Bibliothek.",al={"warum ein buch mitbringen","was gewinnt die bibliothek","der bibliothek helfen"}},{q="Kann ich auch andere magische Bücher mitbringen?",a="Ja. Der Bibliothekar begrüßt andere magische Werke, die der Bibliothek nützen könnten.",al={"andere magische bücher","weitere magische werke","was kann ich noch mitbringen"}}},fp="39,144,20.229.0,33.127.0,32.64.0,32.79.0"}
P.entries["quest:79952"] = {n="RwlRwlRwlRwl!",s="Ein Bibliothekar heißt magische Werke für die Sammlung der Bibliothek willkommen. Eure Beiträge lassen ihr Wissen wachsen.",h="Ein Bibliothekar heißt magische Werke für die Sammlung der Bibliothek willkommen.",kw={"sammlung","wissen","library","magische werke","rwl"},sec={{t="Eine wachsende Sammlung",b="Jeder Neuzugang erweitert das dortige Wissen, und der Bibliothekar dankt Euch dafür. Weitere Werke, die der Sammlung zugutekommen könnten, sind willkommen."}},faq={{q="Was möchte der Hüter der Library?",a="Der Hüter heißt magische Werke willkommen, die der Sammlung der Library zugutekommen können.",al={"librarybücher","magische werke","was mitbringen"}},{q="Wo befindet sich diese Sammlung?",a="Keine Stadt wird genannt. Bücher wie dieses gehen an Garion Wendell in Sturmwind oder Owen Thadd in der Unterstadt.",al={"standort der library","library eisenschmiede","wo ist die library"}},{q="Warum magische Werke mitbringen?",a="Eure Beiträge lassen das Wissen der Library wachsen.",al={"warum bücher","library helfen","was ist der zweck"}}},fp="13,113,20.138.0,34.76.0,25.99.0,24.53.0"}
P.entries["quest:79974"] = {n="Wet Job",s="An einem Berghang schickt Euch Wet Job los, um einen verborgenen Notfallvorrat zu bergen. Jemand hat ihn für eine überstürzte Flucht vorbereitet und nahe einem hoch gelegenen Felsvorsprung versteckt.",h="An einem Berghang schickt Euch Wet Job los, um einen verborgenen Notfallvorrat zu bergen.",kw={"zwergische ingenieurskunst","adlernest","kuriertasche","berghang","pergament","reservevorrat","vorräte","wet job"},ang={["class:Rogue"]="Als Schurke kennt Ihr den Wert verborgener Notfallvorräte, die bereitliegen, falls eine überstürzte Flucht nötig wird.",["profession:Engineering"]="Als Ingenieur könnt Ihr den zwergischen Erfindungsreichtum hinter einem verlässlichen Notfallvorrat bewundern, der in zerklüftetem Gelände verborgen liegt.",["race:Dwarf"]="Als Zwerg könnt Ihr stolz auf die beständige Qualität der Handwerkskunst aus den Bergen sein, die bei der Bergung des Vorrats gelobt wird."},sec={{t="Ein Notfallvorrat",b="In gefährlichen Landstrichen kann ein Reservevorrat eine schnelle Flucht ermöglichen. Ihr durchsucht die zerklüfteten Höhen nach einem Vorrat, den jemand dort zurückgelassen hat, falls die Pläne scheitern sollten. Die Vorräte warten darauf, geborgen zu werden."},{t="Das Adlernest",b="Die Wegbeschreibung führt zu einem hoch gelegenen Bergausguck, der als aus den Wasserfällen der Zeit gehauen beschrieben wird. Dort, am Adlernest, liegt eine verwitterte Kuriertasche, teilweise in der Erde vergraben. Darin haben Proviant und Pergament unter der Erde überdauert, geschützt durch zwergische Handwerkskunst."}},faq={{q="Worum geht es in der Quest Wet Job?",a="Ihr bergt einen verborgenen Notfallvorrat, der für eine überstürzte Flucht angelegt wurde.",al={"was ist wet job","wet job quest","was für eine quest ist wet job"}},{q="Wer hat den Reservevorrat zurückgelassen?",a="Jemand hat den Vorrat als Notreserve zurückgelassen, falls eine überstürzte Flucht nötig werden sollte. Er enthält eine mit zwergischer Handwerkskunst gefertigte Kuriertasche mit Pergament und Vorräten.",al={"wer hat den vorrat zurückgelassen","wem gehören diese vorräte","wer hat den reservevorrat versteckt"}},{q="Wo ist das Versteck, und wo ist das Adlernest?",a="Das Versteck ist die Kuriertasche im Erdhügel im Steinkrallengebirge, wo Wet Job beginnt. Ihr Pergament schickt Euch zum Adlernest: zum Steinwerkdamm in Loch Modan, wo eine geschnitzte Figur wartet.",al={"wo ist der vorrat","wet job fundort","adlernest fundort"}},{q="Was befindet sich in der Kuriertasche?",a="Die vergrabene Kuriertasche im Steinkrallengebirge enthält Vorräte und ein Pergament, geschützt durch zwergische Handwerkskunst.",al={"was enthält der vorrat","wet job gegenstände","was wird gefunden"}},{q="Warum heißt die Aufgabe Wet Job?",a="Der Name passt zu seinem Ziel: Das Adlernest ist der Steinwerkdamm in Loch Modan, zwischen seinen Wasserfällen.",al={"warum heißt es wet job","wet job namensbedeutung"}},{q="Welche Rolle spielt zwergische Ingenieurskunst?",a="Die Bauweise und Verlässlichkeit des Vorratslagers zeugen von zwergischer Ingenieurskunst, darauf ausgelegt, das Vergraben im Freien zu überstehen.",al={"verbindung zur zwergischen ingenieurskunst","ist das zwergisch"}}},fp="7,154,18.194.0,16.273.0,32.80.0,27.162.0,50.214.0,35.112.0,31.107.0,36.101.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="An einem nebligen Aussichtspunkt hält Eagle's Fist einsam Wache über eine verwitterte Barrikade. Ein Brief spricht von Treue zu den Alten Königreichen und zu Adler und Faust, doch sein Verfasser ist in Eile aufgebrochen.",h="An einem nebligen Aussichtspunkt hält Eagle's Fist einsam Wache über eine verwitterte Barrikade.",kw={"barrikade","lagerfeuer","eagle's fist","gefalteter brief","aussichtsposten","alte königreiche","fallschirmgleiter","werkzeugkasten"},ang={["profession:Engineering"]="Die Notiz des Wächters bezeichnet den Ort als idealen Ausgangspunkt für einen Fallschirmgleiter. Ingenieure dürften die Gelegenheit zur Luftaufklärung und zum mechanischen Flug zu schätzen wissen."},sec={{t="Ein verborgener Aussichtsposten",b="Ein gefalteter Brief liegt in einem Werkzeugkasten an einem hoch gelegenen Aussichtspunkt. Von hier aus, schreibt sein Verfasser, könne man das Geschehen lenken oder mit einem Fallschirmgleiter über das Land gleiten. Neblige Gischt befeuchtet diesen einsamen Posten, doch der Blick reicht über geschichtsträchtige Lande."},{t="Treue zu den Alten Königreichen",b="Der Verfasser des Briefes gelobt Adler und Faust dauerhafte Treue. Um dieser Sache gut zu dienen, müsse man gebührenden Abstand halten, schreibt er. Die nahe Barrikade ist verfallen, ebenso wie die Alten Königreiche, die sie einst vor Gefahren schützte. Dennoch schwört der Wächter, den Posten niemals aufzugeben."},{t="Ein eiliger Aufbruch",b="Der Wachposten hat den Aussichtspunkt in Eile verlassen. Das Lagerfeuer wurde erst kürzlich mit frischem Holz geschürt, doch der Wächter ist fort. Werkzeuge, glimmende Glut und ein kryptischer Brief bleiben zurück."}},faq={{q="Was ist Eagle's Fist?",a="Eagle's Fist ist ein einsamer Aussichtsposten über einer verwitterten Barrikade, wo ein gefalteter Brief in einem Werkzeugkasten liegt. Sein Verfasser ist in Eile aufgebrochen.",al={"was ist eagle's fist","eagles fist quest","was ist das für eine quest"}},{q="Wer hat den Brief im Werkzeugkasten geschrieben?",a="Ein unbekannter Späher oder Wachposten hat den Brief geschrieben. Der Verfasser dient den Alten Königreichen sowie Adler und Faust und hält an einer einsamen Barrikade Wache.",al={"wer schrieb die notiz","wer hinterließ den brief","verfasser des briefs im werkzeugkasten"}},{q="Worauf bezieht sich „Adler und Faust“?",a="Adler und Faust ist eine im Brief genannte Sache, der die Treue gilt. Sie verlangt, im Dienst gebührenden Abstand zu halten, und ist mit dem Schutz der Überreste der Alten Königreiche verbunden.",al={"was ist adler und faust","adler und faust bedeutung","wer ist adler und faust"}},{q="Warum ist das Lager verlassen?",a="Der Späher ist in Eile aufgebrochen, obwohl das Lagerfeuer erst kürzlich mit frischem Holz geschürt worden war. Der Verfasser lobte den Aussichtspunkt als einen Ort, von dem aus man mit einem Fallschirmgleiter starten kann.",al={"wohin ging der späher","warum brach der späher auf","wer schürte das lagerfeuer"}},{q="Welche Barrikade wird verteidigt?",a="Der Verfasser des Briefes beschreibt die Barrikade als verfallen, wie die untergegangenen Alten Königreiche der Menschheit, die sie einst verteidigte. Dennoch schwört der Wächter, sie niemals aufzugeben.",al={"welche barrikade","welche alten königreiche","barrikade hintergrundgeschichte"}},{q="Was für ein Aussichtsposten ist das?",a="Der Posten bietet eine unglaubliche Aussicht, und Gischt befeuchtet die Luft. Er liegt möglicherweise auf einer hohen Klippe oder an einem Aussichtspunkt nahe einem großen Wasserfall oder einem über Kaskaden fließenden Fluss.",al={"wo liegt dieser ort","warum gibt es hier gisчht","eagles fist standort"}}},fp="12,190,14.236.0,27.295.0,17.175.1,21.129.0,42.145.0,40.167.0,30.161.0,33.151.0,34.147.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="Bei This Must Be The Place ist ein Reisender verschwunden, kurz bevor ihn jemand einholen konnte. Eine zerrissene Notiz besagt, dass der Verfasser seine Arbeit in den Untergrund verlegt hat, damit sie nicht in die falschen Hände gerät.",h="Bei This Must Be The Place ist ein Reisender verschwunden, kurz bevor ihn jemand einholen konnte.",kw={"verlassenes lager","ausrüstungsrucksack","versteck","schlafsack","this must be the place","zerrissene notiz","untergrund"},sec={{t="Ein hastiger Aufbruch",b="An diesem abgelegenen Ort hat jemand erst vor wenigen Augenblicken sein Lager abgebrochen. Ein unzureichend gesicherter Schlafsack rollt sich unter Euren Füßen aus, während eine schwere Plane gebündelt über allerlei Ausrüstung liegt. Ein kleiner Papierfetzen trägt eine hastige Abschiedsbotschaft, doch wer auch immer hier lagerte, ist verschwunden, bevor ihn jemand einholen konnte."},{t="In den Untergrund",b="Die zerrissene Notiz besagt, dass ihr Verfasser seine Arbeit in den Untergrund verlegt hat, damit sie nicht in die falschen Hände gerät. Ob dies letzte Worte sind oder ein Hinweis auf den nächsten verborgenen Unterschlupf des Forschers, bleibt unbekannt. Die Ausrüstung liegt verlassen da, zurückgelassen für denjenigen, der den Lagerplatz gefunden hat."}},faq={{q="Wer hat die zerrissene Notiz geschrieben?",a="Die Notiz nennt ihren Verfasser nicht. Er schreibt lediglich, dass er seine Arbeit in den Untergrund verlegt hat, damit sie nicht in die falschen Hände gerät, und Lagerplatz und Ausrüstung zurückließ.",al={"wer schrieb die notiz","verfasser der notiz","wer hinterließ die nachricht"}},{q="Welche Arbeit wird in den Untergrund verlegt?",a="Die Notiz verrät nicht, welche Arbeit der Verfasser in den Untergrund verlegt. Er schreibt, dass er sie vor nicht näher benannten Widersachern schützen will.",al={"welche arbeit im untergrund","warum die arbeit in den untergrund verlegen","welche arbeit"}},{q="Wohin ist der Bewohner des Lagers gegangen?",a="Der Bewohner brach wenige Augenblicke vor der Ankunft anderer auf, und sein Ziel ist unbekannt. Die Notiz deutet an, dass er einen anderen verborgenen Unterschlupf aufgesucht haben könnte.",al={"habe ich den bewohner verpasst","wohin ist der bewohner gegangen","wo ist der verfasser"}},{q="Was wurde am Lagerplatz zurückgelassen?",a="Der Reisende hinterließ einen unzureichend gesicherten Schlafsack, der sich auf dem Boden ausrollt, eine schwere, über allerlei Ausrüstung gebündelte Plane und einen weggeworfenen Rucksack mit verschiedener Ausrüstung.",al={"was wurde zurückgelassen","vorräte im lager","was war im rucksack"}},{q="Ist dies ein Hinweis auf ein weiteres Versteck?",a="Die Notiz könnte ein Abschied oder ein Hinweis auf den nächsten Unterschlupf des Verfassers im Untergrund sein. Welche Deutung zutrifft, lässt sie offen.",al={"gibt es ein weiteres versteck","nächstes lager","weitere hinweise"}},{q="Wer sind die in der Notiz erwähnten „falschen Hände“?",a="Die Notiz verrät nicht, wer mit den falschen Händen gemeint ist. Der Verfasser fürchtete Verfolgung oder Diebstahl und brach auf, bevor seine Arbeit gefährdet werden konnte.",al={"wer sind die falschen hände","bedeutung von falschen händen","wer verfolgt den verfasser"}}},fp="22,180,17.289.0,20.253.1,24.175.0,37.140.0,37.143.0,37.175.0,42.106.0,48.127.0"}
P.entries["quest:79980"] = {n="Scramble",s="Die Notiz eines Plünderers schickt Reisende eine steile Klippe hinab, auf der Suche nach Scrambles versteckten Vorräten. Einhundert Schritte weiter nördlich finden sie Proviant und ein schmutziges Pergament.",h="Die Notiz eines Plünderers schickt Reisende eine steile Klippe hinab, auf der Suche nach Scrambles...",kw={"vorratslager","felswand","kuriertasche","pergament","scramble","versteck","vorräte"},sec={{t="Die Spur nach Norden",b="Eine Notiz weist den Weg zu einem versteckten Vorratslager. Ihr Verfasser spricht ein paar lockere Worte der Ermutigung aus und gibt dann genaue Anweisungen: Geht einhundert Schritte genau nach Norden die tückische Felswand hinab. Dort wartet Proviant, der einen Reisenden auf seinem Weg versorgt."},{t="Die vergrabene Kuriertasche",b="Wer den Anweisungen die steile Felswand hinab folgt, gelangt zu einer vergrabenen Kuriertasche. Darin befinden sich praktische Überlebensvorräte und ein weiteres schmutziges Pergament. Die Notiz weist den Weg weiter entlang einer längeren Spur."}},faq={{q="Was ist die Quest Scramble?",a="Scramble schickt Reisende entlang einer Spur aus aufgelesenen Funden zu einem versteckten Vorratslager. Eine Notiz weist ihnen den Weg einhundert Schritte nach Norden, eine tückische Klippe hinab, zu vergrabenen Vorräten.",al={"scramble quest","was ist scramble","scramble versteck"}},{q="Wo liegt das versteckte Lager?",a="Laut der Notiz liegt das Vorratslager etwa einhundert Schritte genau nach Norden, eine steile Felswand hinab. Beim Abstieg ist ein sicherer Tritt nötig.",al={"wo ist das versteck","wie das versteck finden","fundort des verstecks"}},{q="Wer hat die Notiz und die Vorräte hinterlassen?",a="Die Notiz nennt ihren Verfasser nicht. Ihre lockeren, praktischen Anweisungen helfen einem Entdecker, Notvorräte zu finden, und das Lager ist noch unversehrt.",al={"wer schrieb die scramble-notiz","wer hinterließ die vorräte","scramble verfasser"}},{q="Was befindet sich im vergrabenen Lager?",a="Die vergrabene Kuriertasche enthält Überlebensvorräte und ein schmutziges Pergament, das dazwischen verstaut ist.",al={"scramble belohnungen","was ist im scramble-vorratslager","tascheninhalt"}},{q="Was ist das schmutzige Pergament, das bei den Vorräten gefunden wird?",a="Das schmutzige Pergament liegt neben dem Proviant in der vergrabenen Kuriertasche. Es wird gefunden, wenn die Tasche aus dem Boden gezogen wird.",al={"schmutziges pergament scramble","was steht auf dem pergament","scramble notiz"}},{q="Welche Gefahren birgt der Weg zum Vorratslager?",a="Die größte Gefahr ist der steile Abstieg nach Norden. Ein Fehltritt kann gebrochene Knöchel oder einen schweren Sturz bedeuten.",al={"gefahr scramble","klippe scramble","scramble felswand"}}},fp="8,163,19.246.0,28.196.1,27.156.0,34.127.0,32.143.0,32.89.0,52.133.0,48.99.0"}
P.entries["quest:8"] = {n="Ein Schurkenhandel",s="In Todesend bittet Calvin Montague Euch, eine unbeschriftete Botschaft nach Brill zu bringen. Er nennt es eine einfache Zustellung und verspricht reichlich Münzen.",h="In Todesend bittet Calvin Montague Euch, eine unbeschriftete Botschaft nach Brill zu bringen.",kw={"brill","calvin montague","todesend","galgenschlinge","gastwirtin renee","unscheinbarer brief","schurke","tirisfal"},ang={["class:Rogue"]="Als Schurke erhaltet Ihr durch Calvin Montagues privaten Kurierauftrag einen Einblick in die informellen Geschäfte rund um Todesend und Brill.",["faction:Horde"]="Als Mitglied der Horde reist Ihr nach Brill, einem regionalen Verwaltungszentrum der Verlassenen und einem Ort der Erholung in Tirisfal.",["race:Undead"]="Als frisch auferstandener Verlassener verlasst Ihr zum ersten Mal den Friedhof von Todesend und macht Euch auf nach Brill, dem geschäftigen Mittelpunkt der Region."},sec={{t="Ein freundlicher Kurier",b="Calvin Montague faulenzt zwischen den Gräbern und verfallenen Kapellen von Todesend. Er sagt, Geißelzombies und kriechende Spinnen hätten ihn zermürbt, und bittet Euch dann, einen unbeschrifteten Brief nach Brill zu bringen. Er verspricht reichlich Münzen. Für einen frisch erwachten Verlassenen scheint es ein einfacher Weg zu sein, den Hauptort der Region zu erreichen."},{t="Die Taverne Zur Galgenschlinge",b="Die Straße nach Osten führt durch Tirisfal und am Coldhearth-Anwesen vorbei, bevor sie Brill erreicht. In der Taverne Zur Galgenschlinge begrüßt Gastwirtin Renee Neuankömmlinge herzlich und kümmert sich eifrig um ihr Wohl. Doch als sie Montagues Brief erhält, schlägt ihr Verhalten um. Sie gibt vor, er bringe Nachricht von einer geliebten Mutter, schilt Euch dann wegen Eurer Schnüffelei und verlangt, dass Ihr etwas kauft oder geht.\n\nAls Ihr zu Calvin zurückkehrt, fordert er Euch zu einem Duell heraus, statt Euch friedlich den versprochenen Lohn zu zahlen."}},faq={{q="Wer ist Calvin Montague?",a="Calvin Montague ist ein Schurke in Todesend, der frisch erwachte Reisende bittet, Gastwirtin Renee in Brill einen Brief zu bringen. Er nennt es einen einfachen Gefallen und verspricht großzügige Bezahlung.",al={"calvin montague","wer vergibt ein schurkenhandel","questgeber"}},{q="Was steht im Unscheinbaren Brief?",a="Der genaue Inhalt des Briefes ist nicht überliefert. Calvin gibt Euch eine unbeschriftete Botschaft für Gastwirtin Renee in Brill.",al={"inhalt unscheinbarer brief","was steht im brief","calvins brief"}},{q="Warum verhält sich Gastwirtin Renee so seltsam?",a="Gastwirtin Renee führt die Taverne in Brill und besteht darauf, dass ihre Korrespondenz privat ist. Ihr erlebt ihre Reaktion, als Ihr ihr Montagues Brief bringt.",al={"gastwirtin renees verhalten","warum verstellt sich renee","renees ausrede mit der mutter"}},{q="Bezahlt Calvin Montague tatsächlich für die Zustellung?",a="Calvin Montague verspricht großzügige Bezahlung für die Zustellung. Renee bietet Essen oder Wasser an, wenn der Brief sie erreicht. Kehrt danach zu Calvin zurück, um mit ihm weiter über die versprochene Bezahlung zu verhandeln.",al={"hat calvin mich betrogen","wo ist mein geld","montagues belohnung"}},{q="Wo liegt Brill?",a="Brill liegt nordöstlich von Todesend. Folgt der Hauptstraße nach Osten aus dem Tal, in dem Ihr beginnt, haltet Euch am Coldhearth-Anwesen rechts und überquert eine überdachte Brücke in den Ort.",al={"wie nach brill gelangen","straße nach brill","wegbeschreibung nach brill"}},{q="Was geschieht, nachdem Renee den Brief erhalten hat?",a="Nachdem Ihr Renee den Brief gegeben habt, kehrt zu Calvin Montague in Todesend zurück, um weiter mit ihm zu verhandeln.",al={"nächste quest","folgequest von ein schurkenhandel","was nach renee tun"}}},fx={df83fdd9={q="Warum will Calvin Montague, dass der Brief zugestellt wird?",a="Calvin Montague behauptet, er habe mehr als seinen gerechten Anteil an geistlosen Zombies und Spinnen rund um Todesend bekämpft und brauche einfach jemanden, der einen Botengang für ihn erledigt. Anstatt selbst den Weg nach Brill zurückzulegen, bietet er Euch eine hohe Belohnung dafür an, seinen versiegelten, unscheinbaren Brief direkt an Gastwirtin Renee zu übergeben.",al={"calvin montague motiv","warum brief an renee schicken","warum will calvin das erledigt haben"}}},fp="14,136,18.299.0,23.469.1,23.175.0,38.112.0,40.147.0,51.194.0,23.161.0,46.100.1"}
P.entries["quest:80"] = {n="Die Legende von Stalvan",s="In Dunkelhain bringt die Suche nach Stalvan Dunstmantel der Nachtwache eine blutbefleckte Tagebuchseite. Kommandantin Althea Schwarzhaupt schickt Euch zu Amtmann Daltry, um die Handschrift mit den städtischen Unterlagen abzugleichen.",h="In Dunkelhain bringt die Suche nach Stalvan Dunstmantel der Nachtwache eine blutbefleckte Tagebuchseite.",kw={"althea schwarzhaupt","blutbefleckte tagebuchseite","amtmann daltry","dunkelhain","dämmerwald","legende von stalvan","night watch","stalvan dunstmantel"},ang={["faction:Alliance"]="Die Ermittlungen in Dunkelhain zeigen, wie Grenzstädte Recht, Ordnung und amtliche Unterlagen bewahren, während Untote und schattenhafte Bestien sie belagern.",["race:Human"]="Als Mensch aus den südlichen Königreichen könnt Ihr die Tragödien erkennen, die Sturmwinds Adel, die Siedler des Dämmerwalds und Elwynns verstreute Herrensitze verbinden."},sec={{t="Das Netz zieht sich zu",b="Die Nachtwache hat Tagebuchseiten aus dem gesamten Dämmerwald und den umliegenden menschlichen Gebieten zusammengetragen. Zusammen scheinen sie Stalvan Dunstmantel, den schwer zu fassenden Hauslehrer, zu überführen. Kommandantin Althea Schwarzhaupt verdächtigt ihn schon seit einiger Zeit, doch sie braucht Beweise, bevor sie ein Urteil fällt. Die blutbefleckte Seite allein verrät nicht, wer sie geschrieben hat. Ihre Handschrift muss mit Stalvans abgeglichen werden."},{t="Der Blick des Amtmanns",b="Amtmann Daltry führt Dunkelhains städtische Unterlagen und hat im Laufe der Jahre unzählige Geschäftsbücher und Unterschriften geprüft. Ihr bringt ihm die neu entdeckte Tagebuchseite, damit er sie mit Stalvans Unterschriften im Register vergleicht. Sein Urteil kann klären, ob die Seite wirklich von Stalvan stammt, und der Nachtwache die nötige Gewissheit geben."}},faq={{q="Warum braucht Kommandantin Schwarzhaupt die Bestätigung von Amtmann Daltry?",a="Kommandantin Althea Schwarzhaupt braucht Amtmann Daltry, um zu prüfen, ob die blutbefleckte Seite mit Stalvans Handschrift in Dunkelhains Unterlagen übereinstimmt. Daltry führt das Stadtregister und hat langjährige Erfahrung mit der Prüfung von Unterschriften, sodass sein Wort Stalvans Schuld belegen kann, bevor Schwarzhaupt handelt.",al={"warum daltry","warum die handschrift prüfen","aufgabe von amtmann daltry"}},{q="Wo fügt sich dieser Schritt in die Geschichte der Legende von Stalvan ein?",a="Dies ist das elfte Kapitel der Ermittlungen, nachdem die blutbefleckte Tagebuchseite geborgen wurde. Daltrys Vergleich ist die letzte Prüfung der Beweise, bevor die Nachtwache gegen Stalvan vorgeht.",al={"welcher teil ist das","wie weit in der questreihe","reihenfolge der stalvan-questreihe"}},{q="Wo befindet sich Amtmann Daltry in Dunkelhain?",a="Amtmann Daltry befindet sich im Rathaus von Dunkelhain, wo er die örtlichen Unterlagen und Grundbücher der Gemeinde führt.",al={"daltrys standort","wo ist amtmann daltry","daltry finden"}},{q="Welche Beweise hat der Ermittler nach Dunkelhain gebracht?",a="Ihr bringt eine blutbefleckte Tagebuchseite, die während der Suche nach Stalvan geborgen wurde. Sie beschreibt seine düsteren Gedanken und Erlebnisse, doch ihre Handschrift muss noch mit amtlichen Unterlagen abgeglichen werden.",al={"was sind die beweise","was ist das für eine seite","geschichte der blutbefleckten seite"}},{q="Bestätigt Amtmann Daltry, dass die Handschrift von Stalvan stammt?",a="Ja. Daltry vergleicht die blutbefleckte Seite mit Unterschriften im Stadtregister und bestätigt, dass die Handschrift mit Stalvans übereinstimmt. Schwarzhaupt hat nun die Gewissheit, die sie brauchte, bevor sie handelt.",al={"stimmt die handschrift überein","ist es stalvan","hat stalvan es geschrieben"}},{q="Warum ist die Nachtwache so vorsichtig damit, Stalvan zu beschuldigen?",a="Die Nachtwache will überprüfbare Beweise, bevor sie einen ehemaligen Gelehrten entsetzlicher Verbrechen beschuldigt. Selbst im geplagten, abgeschiedenen Dämmerwald bemüht sie sich, die Rechtsordnung zu wahren, statt sich auf Gerüchte oder Vermutungen zu verlassen.",al={"warum sind beweise nötig","warum stalvan nicht einfach töten","schwarzhaupts verdacht"}}},fx={["5aad2c8f"]={q="Warum lässt Euch Kommandantin Althea Schwarzhaupt die Seite zu Amtmann Daltry bringen?",a="Kommandantin Schwarzhaupt ist für die Verteidigung des Dämmerwalds und von Dunkelhain verantwortlich und hält Wache über die Umgebung der Siedlung, während Ihr die Feldforschung zu Stalvan Dunstmantel betrieben habt. Da Ihr ihr die blutbefleckte Tagebuchseite direkt gebracht habt, ist es am schnellsten, wenn Ihr sie zu Amtmann Daltry im Rathaus bringt, um die Schrift zu überprüfen, während sie im Dienst bleibt.",al={"warum ich ebonlocke","warum spricht ebonlocke nicht mit daltry","warum zu daltry geschickt"}}},fp="21,201,15.372.0,15.329.1,62.286.0,62.202.0,43.119.0,54.194.0,55.183.1,58.219.0"}
P.entries["quest:80001"] = {n="Rekindle",s="Eine erloschene Feuerstelle birgt trockenes Holz, das leicht Feuer fängt. Ihr setzt Eure Kundschafterfähigkeiten ein.",h="Eine erloschene Feuerstelle birgt trockenes Holz, das leicht Feuer fängt.",kw={"trockenes holz","erloschenes feuer","feuerstelle","neu entfachen","kundschafterfähigkeiten"},sec={{t="An der Feuerstelle",b="Das Holz ist trocken genug, um Feuer zu fangen. Ihr setzt neben der erloschenen Feuerstelle Eure Kundschafterfähigkeiten ein."}},faq={{q="Worum geht es bei Rekindle?",a="Eine erloschene Feuerstelle birgt trockenes Holz, das leicht Feuer fängt, und Ihr setzt Eure Kundschafterfähigkeiten ein.",al={"quest neu entfachen","feuer neu entfachen","feuerstelle"}},{q="Was stimmt mit der Feuerstelle nicht?",a="Die Feuerstelle ist erloschen, obwohl ihr Holz trocken genug ist, um Feuer zu fangen.",al={"problem mit der feuerstelle","warum kein feuer","erloschenes feuer"}},{q="Was sagt der Abschluss aus?",a="Der Abschluss besagt, dass Ihr Eure Kundschafterfähigkeiten einsetzt.",al={"ende von neu entfachen","was beim abschluss passiert","kundschafterfähigkeiten"}}},fp="8,96,15.107.0,23.98.0,32.75.0,29.54.0"}
P.entries["quest:804"] = {n="Sarkoth",s="Auf den hohen Klippen des Tals der Prüfungen wartet Hana'zua auf Hilfe, nachdem Sarkoths Gift ihn dort festgesetzt hat. Ihr habt den Skorpid erschlagen, der ihn verwundet hat. Nun muss Gornek im Den davon erfahren, damit Hilfe den Späher erreichen kann.",h="Auf den hohen Klippen des Tals der Prüfungen wartet Hana'zua auf Hilfe, nachdem Sarkoths Gift ihn dort...",kw={"dunkelspeer","durotar","gornek","hana'zua","sarkoth","skorpid","the den","das tal der prüfungen"},ang={["faction:Horde"]="Als Mitglied der Horde lernt Ihr, dass das Überleben in einem rauen, unbarmherzigen Land von gegenseitiger Hilfe abhängt. Schon von den ersten Schritten eines Initianten an wird gelehrt, keinen Kameraden zurückzulassen.",["race:Orc"]="Als Orc wisst Ihr, dass persönliche Stärke zählt. Die Ehre eines kampfunfähigen Verbündeten zu verteidigen, zeugt vom Herzen eines wahren Kriegers.",["race:Troll"]="Als Troll könnt Ihr das junge Band zwischen dem Stamm der Dunkelspeer und Thralls Orcs stärken, indem Ihr Hana'zua vor einem langsamen Gifttod rettet."},sec={{t="Die Not eines Spähers",b="Hana'zua, ein Späher der Dunkelspeer, liegt hilflos auf den hohen Klippen des Tals der Prüfungen. Sarkoths Gift hat ihn so geschwächt, dass er die tückischen Pfade nicht allein hinabsteigen kann. Ihr habt ihn gerächt, indem Ihr den Skorpid erschlagen habt, doch ohne Hilfe kann er die kargen Felsen noch immer nicht überwinden. Deshalb muss ein vorbeikommender Initiant die Nachricht hinab zum Ausbildungslager tragen."},{t="Ehre im Den",b="Gornek wartet im Den auf Euren Bericht. Als er von Hana'zuas Notlage hört, erkennt er die Gefahr durch Sarkoth und organisiert Hilfe für den Späher. Die Befehlshaber der Horde ehren jene, die ihre eigene Ausbildung unterbrechen, um einen gefallenen Fremden zu verteidigen und zu retten. Solches Verhalten beweist den Wert eines Initianten, bevor er in das eigentliche Durotar aufbricht."}},faq={{q="Wer ist Hana'zua und warum sitzt er fest?",a="Hana'zua ist ein junger Trollspäher der Dunkelspeer, der in den Höhen des Tals der Prüfungen festsitzt. Sarkoth hat ihn überfallen und vergiftet, sodass er zu schwach ist, um allein hinabzusteigen.",al={"hanazua","wer ist hanazua","warum ist der troll verletzt"}},{q="Wer ist Gornek?",a="Gornek ist ein orkischer Aufseher im Den im Tal der Prüfungen. Er beurteilt neue Rekruten, erteilt Überlebensaufgaben und koordiniert Hilfe, wenn Initianten in der Schlucht tödlichen Bedrohungen gegenüberstehen.",al={"gornek","wo ist gornek","anführer des den"}},{q="Was ist Sarkoth?",a="Oberhalb des Tals der Prüfungen streift Sarkoth als berüchtigter, riesiger Skorpid über die felsigen Klippen. Sein Gift und seine Wildheit machen ihn zu einer legendären Gefahr für junge Orcs und Trolle während ihrer Prüfungen.",al={"sarkoth bestie","was für ein monster ist sarkoth"}},{q="Überlebt Hana'zua seine Verwundungen?",a="Gornek verspricht, Hana'zua Hilfe zu schicken, sobald er Euren Bericht hört. Was danach aus dem Späher wird, bleibt unerzählt.",al={"lebt der troll","geht es hanazua gut","hanazua gerettet"}},{q="Warum lobt Gornek diese Tat so sehr?",a="Es wird erwartet, dass Ihr die Prüfungen überlebt. Eure eigenen Aufgaben zurückzustellen, um die Ehre eines Fremden zu verteidigen und ihm beim Überleben zu helfen, spiegelt die Werte wider, die die neue Horde in ihren Kriegern formen will.",al={"warum kümmert sich gornek","gorneks rede über ehre"}},{q="Wo liegt der Den?",a="Der Den ist die zentrale Ausbildungshöhle und der Sammelplatz im Herzen des Tals der Prüfungen im Südwesten Durotars.",al={"wo ist der den","den standort durotar"}}},fx={["88c1d5d5"]={q="Warum bittet Euch Hana'zua, Gornek Bericht zu erstatten?",a="Obwohl die Rache für seine Niederlage gegen Sarkoth Hana'zuas Entschlossenheit zu überleben gestärkt hat, lassen ihn seine schweren Wunden völlig bewegungsunfähig im Tal zurück. Er kann den Weg zurück nach The Den aus eigener Kraft nicht zurücklegen. Indem er Euch mit der Nachricht über seine missliche Lage schickt, hofft er, dass Gornek Hilfe schickt, bevor er seinen Verletzungen oder den Elementen erliegt.",al={"warum zu gornek geschickt","hanazua motiv","warum gornek informieren"}},["66b1c5a1"]={q="Warum kann Hana'zua nicht selbst zu The Den zurückkehren?",a="Hana'zua wurde während seiner Prüfung von Sarkoth verprügelt und für tot zurückgelassen. Er hat nicht die Kraft zu stehen, geschweige denn, alleine über den sengenden Canyonboden zurück in Sicherheit zu kriechen. Da keine anderen Krieger in der Nähe sind, um ihm zu helfen, seid Ihr seine einzige Rettungsleine, um Gornek zu informieren, bevor es zu spät ist.",al={"warum braucht hanazua hilfe","warum kann hanazua nicht gehen","warum ich hanazua"}}},fp="7,210,16.336.0,16.328.0,39.166.0,14.182.0,16.184.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="Bericht erstatten in Sen'jin",s="Zureetha Fernblick schickt junge Initianden aus dem Tal der Prüfungen, um die Dunkelspeertrolle in Sen'jin zu warnen. Kultisten der Burning Blade waren im Tal aktiv. Meister Gadrin berichtet ihnen, dass dunkle Magie die nahen Echoinseln bedroht.",h="Zureetha Fernblick schickt junge Initianden aus dem Tal der Prüfungen, um die Dunkelspeertrolle in Sen'jin zu...",kw={"burning blade","dunkelspeer","durotar","die echoinseln","meister gadrin","sen'jin","das tal der prüfungen","zureetha fernblick"},ang={["faction:Horde"]="Als Mitglied von Thralls Horde erlebt Ihr, wie ihre Gründungsvölker einander warnen, um ihre jungen Siedlungen gegenseitig zu schützen.",["race:Orc"]="Als junger Orc verlasst Ihr das Tal der Prüfungen, um den Dunkelspeer beizustehen, eine frühe Bewährungsprobe für Ehre und Zusammenhalt mit den Verbündeten, die jenseits des großen Meeres an Thralls Seite standen.",["race:Troll"]="Als Dunkelspeerabenteurer kehrt Ihr nach Sen'jin zurück und stellt Euch der Vertreibung Eures Volkes und seinem Kampf um die Rückeroberung der Echoinseln."},sec={{t="The Den verlassen",b="Nachdem sie ihre Kampfkraft bewiesen und dunkle Medaillons vom Koven der Brennenden Klinge geborgen haben, verlassen junge Initianden das Tal der Prüfungen. Zureetha Fernblick erkennt, dass Dämonen auf dem heiligen Prüfungsgelände kein vereinzeltes Ärgernis sind. Sie deuten auf eine Verderbnis hin, die sich über Durotar ausbreitet. Sie schickt die bewährten Kämpfer nach Osten, am Schluchtausgang vorbei, dann nach Süden zur Küste, um den Stamm der Dunkelspeer zu warnen."},{t="Schatten über der Küste",b="In Sen'jin überbringen Reisende ihre Warnung Meister Gadrin, dem betagten Hexendoktor, der die Dunkelspeer im Exil führt. Gadrin sagt, die Burning Blade sei nicht auf die sandigen Ufer des Dorfes vorgerückt. Doch auf den nahen Echoinseln hat dunkle Magie Wurzeln geschlagen, und Verrat bedroht die dortigen Trolle. Der Halt der jungen Horde bleibt unsicher, während Verbündete einander zu Hilfe eilen und zugleich Stammeszwist und Teufelsverderbnis ihre Flanken treffen."}},faq={{q="Warum schickt Zureetha Fernblick Leute aus dem Tal der Prüfungen fort?",a="Dämonische Aktivitäten im Tal der Prüfungen lassen Zureetha Fernblick fürchten, dass die Burning Blade ganz Durotar bedroht. Sie schickt bewährte Initianden über das Tal hinaus, um verbündete Siedlungen zu warnen und herauszufinden, wie weit sich der Einfluss des Kults ausgebreitet hat.",al={"warum das tal verlassen","warum nach sen'jin gehen","zureetha fernblick befehle"}},{q="Wer ist Meister Gadrin?",a="Meister Gadrin ist ein betagter Hexendoktor und geistiger Anführer der Dunkelspeertrolle in Sen'jin. Er berät Häuptling Vol'jin und kümmert sich um Stammesangelegenheiten, während die Gefahren ihrem Zufluchtsort an der Küste näher rücken.",al={"meister gadrin hintergrundgeschichte","wer ist gadrin"}},{q="Hat die Burning Blade Sen'jin angegriffen?",a="Nein, die Burning Blade hat Sen'jin nicht angegriffen. Meister Gadrin warnt, dass dunkle Magie und Verrat auf den nahen Echoinseln Wurzeln geschlagen haben und die Trolle gefährden.",al={"ist die burning blade in sen'jin","kult in sen'jin"}},{q="Wo liegt Sen'jin?",a="Sen'jin liegt östlich hinter dem Hauptausgang der Schlucht des Tals der Prüfungen und dann südlich an der Weggabelung entlang Durotars südöstlicher Küste.",al={"wie nach sen'jin gelangen","wegbeschreibung nach sen'jin"}},{q="Welche Bedrohung erwähnt Meister Gadrin auf den Echoinseln?",a="Meister Gadrin fürchtet, dass Zalazane, ein anderer Trollhexendoktor, die Dunkelspeer verraten hat. Zalazane versklavte seine Brüder mit heimtückischen Flüchen und riss die Herrschaft über die Echoinseln an sich, wodurch er die überlebenden Dunkelspeer an die Festlandküste vertrieb.",al={"probleme auf den echoinseln","was geschah auf den echoinseln"}},{q="Was geschieht nach dem Bericht an Meister Gadrin?",a="Nachdem Gadrin Euren Bericht gehört und die Notlage der Trolle beschrieben hat, bittet er Euch um Hilfe gegen die Gefahren, die die Küste bedrohen. Weitere Befehle schicken Euch dann nach Nordwesten zu Orgnil Narbenseele in Klingenhügel.",al={"nächste quest nach bericht erstatten in sen'jin","was nach gadrin tun"}}},fx={["54845e0f"]={q="Warum schickt Euch Zureetha Fernblick zu Meister Gadrin anstatt zu einer Wache?",a="Ihr habt die Brennende Klinge persönlich in ihrem Koven im Tal der Prüfungen konfrontiert und Beweise für ihre Anwesenheit geborgen. Nachdem Ihr Eure Loyalität und Stärke durch Eure Prüfungen bewiesen habt, seid Ihr der qualifizierteste Bote, um Meister Gadrin einen Augenzeugenbericht über die Infiltration des Kults zu liefern.",al={"warum schickt sie mich","warum ich zureetha","warum kein läufer nach senjin"}}},fp="25,237,15.395.0,22.434.1,70.235.0,21.202.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="Dunkle Stürme",s="In Durotar verderben Kultisten der Burning Blade vom Donnergrat aus das Land. Orgnil Narbenseele in Klingenhügel hat erfahren, dass Fizzle Darkstorm sie anführt, und bittet Euch, seiner Bedrohung ein Ende zu setzen.",h="In Durotar verderben Kultisten der Burning Blade vom Donnergrat aus das Land.",kw={"burning blade","dunkle stürme","durotar","fizzle darkstorm","zischels klaue","orgnil narbenseele","klingenhügel","donnergrat"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass Fizzles dunkle Riten und Diener die Naturgeister des Donnergrats stören und seine Bestien aufwühlen. Das Gleichgewicht der Elemente muss wiederhergestellt werden.",["class:Warlock"]="Als Hexenmeister erkennt Ihr, wie Fizzles rücksichtslose Hingabe an die Teufelsmacht ihn zur Gefahr und zur Schande für disziplinierte Hexenmeister der Horde macht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, Durotars Herzland vor dämonischer Unterwanderung zu sichern. Dann kann die Horde ihre Verteidigung nach außen richten, ohne von innen heraus zusammenzubrechen.",["race:Orc"]="Als Orc wisst Ihr, dass die Burning Blade die dunkle Vergangenheit verkörpert, die Euer Volk zu überwinden versucht. Eindringlinge wie Fizzle zu vertreiben hilft, Thralls freie Nation zu schützen."},sec={{t="Eine Bedrohung im Donnergrat",b="Orgnil Narbenseele hat erfahren, dass dunkle Magie im Donnergrat nordwestlich von Klingenhügel Fuß gefasst hat. Kultisten der Burning Blade durchstreifen die Schlucht, während junge Verteidiger der Horde Durotars Grenzen bewachen. Die Kultisten bringen Verderben über die Tierwelt und das Land."},{t="Fizzle Dunkelsturm",b="Fizzle Darkstorm ist ein Goblinhexenmeister, der mit der Burning Blade verbündet ist. Er befehligt die Kultisten im Donnergrat und setzt Teufelsmacht für den Kult ein, statt Handels- oder Kartellinteressen zu dienen. Tötet ihn und bringt seine verdrehte Klaue zurück. Dann wird Orgnil wissen, dass die Anführer in der Schlucht niedergestreckt wurden."},{t="Den Kult ausmerzen",b="Die Burning Blade verkörpert dämonische Knechtschaft, Verderbnis und blutrünstigen Wahnsinn. Thralls neue Horde will diese Vergangenheit hinter sich lassen. Fizzles Tod beseitigt einen aktiven Verschwörer im Inneren Durotars. Der Schatten über der Heimat der Orcs reicht über vereinzelte Lager hinaus."}},faq={{q="Wer ist Fizzle Darkstorm?",a="Fizzle Darkstorm ist ein Goblinhexenmeister im Dienste des Kults der Burning Blade. Er und seine Anhänger finden im Donnergrat Unterschlupf und verbreiten dämonisches Chaos in der Schlucht. Orgnil Narbenseele fordert seine Hinrichtung.",al={"wer ist fizzle","fizzle darkstorm hintergrund","fizzle goblin"}},{q="Wo liegt der Donnergrat?",a="Der Donnergrat liegt im Nordwesten Durotars, nördlich von Klingenhügel und südwestlich von Orgrimmar. Von Blitzenergie durchdrungene Bestien und Kultisten der Burning Blade bevölkern seine zerklüftete Schlucht.",al={"wo ist der donnergrat","donnergrat lage","donnergrat finden"}},{q="Warum ist die Burning Blade in Durotar?",a="Die Burning Blade will Thralls Horde untergraben und die dämonische Herrschaft über die Orcs wiederherstellen. Ihre Mitglieder verstecken sich in Schluchten, Höhlen und Canyons in ganz Durotar und säen Verderbnis von innen heraus.",al={"burning blade in durotar","warum sind kultisten in durotar","burning blade beweggründe"}},{q="Warum will Orgnil Narbenseele ausgerechnet Zischels Klaue?",a="Orgnil will Zischels Klaue als eindeutigen Beweis für den Tod des Hexenmeisters. Sie bestätigt, dass der Anführer der Kultisten im Donnergrat ihre Unternehmungen nicht länger lenken kann.",al={"warum zischels klaue","zischels klaue bedeutung","beweis für fizzles tod"}},{q="Was geschieht, nachdem Fizzle getötet wurde?",a="Nachdem Fizzle gefallen ist, erstattet Ihr Orgnil Narbenseele Bericht. Er schickt Euch zu Margoz, einem Schamanen, der mehr über die Verderbnis der Burning Blade weiß, damit Ihr weiteren Verschwörungen nachgehen könnt.",al={"was kommt nach dunkle stürme","dunkle stürme folgequest","nächste quest nach dunkle stürme"}},{q="Warum sollte ein Goblin für die Burning Blade arbeiten?",a="Manche Goblins fühlen sich wegen ihrer Macht, ihres Einflusses und ihrer dunklen Künste zu Shadow Magic hingezogen. Fizzle verschrieb sich der Teufelshexerei und stellte seine skrupellose Verschlagenheit in den Dienst der Kultisten.",al={"goblin bei der burning blade","warum ist fizzle beim kult","fizzle hexenmeister"}}},fx={["18f009de"]={q="Warum will Orgnil Narbenseele, dass Fizzle Darkstorm eliminiert wird?",a="Orgnil befürchtet, dass sich die Verderbnis und der dämonische Einfluss der Brennenden Klinge unkontrolliert ausbreiten werden, wenn man ihnen auch nur einen kleinen Stützpunkt in Durotar zugesteht. Fizzle Darkstorm und sein Koven haben sich auf dem Donnergrat verschanzt und säen aktiv Chaos direkt vor der Haustür der jungen Orc-Heimat. Sie sofort niederzuschlagen verhindert, dass eine umfassende dämonische Infiltration Fuß fasst.",al={"warum fizzle darkstorm töten","orgnil narbenseele motiv","warum die quest dark storms"}}},fp="11,179,21.246.0,16.291.0,20.284.1,24.204.0,31.169.0,36.193.0,57.166.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="Minshinas Schädel",s="In Sen'jin hört Meister Gadrin die verzweifelten Schreie seines toten Bruders Minshina. Zalazane erschlug Minshina auf den Echoinseln und band seinen Geist an seinen abgetrennten Schädel. Ihr könnt ihn von seinen Qualen befreien, indem Ihr den Schädel von Zalazanes Ritualplatz zurückholt.",h="In Sen'jin hört Meister Gadrin die verzweifelten Schreie seines toten Bruders Minshina.",kw={"kreis der macht","dunkelspeer","die echoinseln","gadrin","minshina","sen'jin","schädel","voodoo","zalazane"},ang={["class:Priest"]="Als Priester kennt Ihr die Heiligkeit einer verstorbenen Seele und den Schrecken ritueller Nekromantie, die einem gefallenen Bruder den ewigen Frieden verwehrt.",["class:Shaman"]="Als Schamane verehrt Ihr die Geister der Ahnen. Wenn Ihr Zalazanes Kreis durchbrecht, befreit Ihr eine gequälte Seele und stellt das Gleichgewicht zwischen der Geisterwelt und den Lebenden wieder her.",["faction:Horde"]="Als Mitglied der Horde ehrt Ihr ihren Bund mit dem Stamm der Dunkelspeer, indem Ihr Meister Gadrin helft. Eure Hilfe beweist, dass alle die Trauer eines Verbündeten teilen.",["race:Troll"]="Als Dunkelspeertroll ehrt Ihr Familie und Stamm, indem Ihr Minshinas Schädel zurückholt. Ihr geht gegen Zalazanes Verderbnis der überlieferten Voodoo-Traditionen vor."},sec={{t="Ein Flehen aus den Schatten",b="Meister Gadrin ist einer der spirituellen Anker des Stammes der Dunkelspeer in Sen'jin. Doch dunkle Visionen quälen ihn. Sein Bruder Minshina fiel, als Zalazane den Stamm verriet und die Echoinseln an sich riss. Minshina starb in diesem Konflikt, doch der Tod brachte ihm keinen Frieden. Nach Trolltradition und Voodoo-Mystik kann ein Geist auch nach dem Tod des Körpers gebunden bleiben. Nun erreicht Minshinas gequälte Stimme Gadrin in seinen Träumen und fleht um Rettung vor einem Schicksal, das schlimmer ist als der Tod."},{t="Zalazanes Kreis der Macht",b="Zalazane tötet seine einstigen Brüder nicht nur. Er fängt ihre Seelen ein, um seine dunkle Zauberei zu nähren. Er band Minshinas Geist an dessen eigenen Schädel, der nun in einem Kreis der Macht auf der größten der Echoinseln liegt. Verhexte Trolle bewachen den Kreis, während Kerzen die Riten erhellen. Der Schädel bündelt Zalazanes verdrehtes Mojo. Solange er dort bleibt, ist Minshina dem Willen des Hexendoktors ausgeliefert."},{t="Freiheit im Tod",b="Um Minshina zu befreien, setzt Ihr von Sen'jin nach Osten zu den südlichen Echoinseln über. Ihr dringt in den Ritualkreis ein und entreißt Zalazane den Schädel. Wenn Ihr Minshinas Überreste zu Meister Gadrin zurückbringt, zerbrechen die dunklen Fesseln. Minshinas dankbarer Geist erscheint kurz und verbeugt sich ehrfürchtig. Dann bricht er ins Reich der Ahnen auf."}},faq={{q="Wer war Minshina?",a="Minshina war Meister Gadrins Bruder. Zalazane ermordete ihn während des Aufstands auf den Echoinseln und entweihte dann seine Überreste mit dunkler Zauberei.",al={"minshinas identität","wer ist minshina","gadrins bruder"}},{q="Warum ist Minshinas Geist in seinem Schädel gefangen?",a="Zalazane nutzt dunklen Voodoo und Hexenmeistermagie, um die Geister erschlagener Dunkelspeertrolle zu versklaven. Er band Minshinas Seele an dessen leiblichen Schädel und legte ihn in einen Kreis der Macht. Damit verwehrte er Minshina den Übergang ins Jenseits und konnte dessen Geist für seine Zwecke nutzen.",al={"warum im schädel gefangen","zalazanes seelenfalle","minshinas seele"}},{q="Wo liegt der Kreis der Macht?",a="Der Kreis der Macht liegt auf einem Hügel auf der südlichsten und größten der Echoinseln, vor Durotars Südostküste. Ritualkerzen, tanzende verhexte Trolle und zur Schau gestellte Schädel kennzeichnen den Ort.",al={"wo ist der schädel","kreis der macht fundort","minshinas schädel fundort"}},{q="Was geschieht, wenn der Schädel nach Sen'jin zurückgebracht wird?",a="Wenn Meister Gadrin den Schädel erhält, zerbrechen die nekromantischen Fesseln. Minshinas geisterhafte Gestalt erscheint vor Gadrin und Euch, verbeugt sich dankbar und verschwindet dann, um friedlich bei den Ahnen zu ruhen.",al={"quest abgeben","was geschieht mit minshina","erscheint minshina"}},{q="Wer ist Zalazane und warum hat er das getan?",a="Zalazane war einst ein angesehener Hexendoktor der Dunkelspeer. Von Machtgier in den Wahnsinn getrieben, wandte er sich gegen seinen Stamm und unterwarf den Willen seiner Brüder und Schwestern mit Flüchen. Er vertrieb die übrigen Flüchtlinge der Dunkelspeer auf Durotars Festland.",al={"wer ist zalazane","warum ist zalazane böse","zalazanes geschichte"}},{q="Warum kann Gadrin den Schädel nicht selbst zurückholen?",a="Meister Gadrin kann Sen'jin nicht schutzlos zurücklassen. Er hält die Siedlung zusammen, leitet die junge Führung der Dunkelspeer an, berät Häuptling Vol'jin und wirkt Zalazanes sich ausbreitenden Flüchen entlang der Küste entgegen.",al={"warum geht gadrin nicht selbst","gadrins aufgaben"}}},fx={["5583848b"]={q="Wozu wird Minshinas Schädel benutzt?",a="Minshinas Schädel dient als magisches Gefäß, das die gefangene Essenz von Meister Gadrins ermordetem Bruder enthält. Zalazane platzierte ihn innerhalb eines rituellen Machtkreises auf der größten der Echoinseln und benutzte niederträchtige Zauberei, um Minshinas Geist selbst über den Tod hinaus zu versklaven. Den Schädel vom dunklen Altar zu entfernen, stört die Bindungsmagie des Hexenmeisters und erlaubt es Gadrin, die Seele seines Bruders endlich zu befreien, sobald Ihr ihn sicher nach Sen'jin zurückgebracht habt.",al={"was ist minshinas schädel","zweck von minshinas schädel","minshinas schädel gegenstand"}},["2001e9be"]={q="Warum will Meister Gadrin, dass dies getan wird?",a="Meister Gadrin wird von den Schreien seines Bruders Minshina gequält, der in seinen Träumen nach ihm ruft. Minshina wurde auf den Echoinseln von dem verräterischen Hexendoktor Zalazane getötet, aber der Tod brachte keinen Frieden. Zalazane hat Minshinas Seele direkt an seinen abgetrennten Schädel gebunden und ihn in dunkle Magie verstrickt. Gadrin kann es nicht ertragen, den Geist seines Bruders zur ewigen Sklaverei verdammt zu wissen, und er braucht verzweifelt jemanden, der den Griff des Hexenmeisters bricht und Minshina ewige Ruhe gewährt.",al={"warum braucht gadrin minshinas schädel","meister gadrin motiv","warum minshina befreien"}}},fp="16,254,23.468.0,26.384.0,16.345.1,17.142.0,46.259.0,37.197.0,63.199.1,39.230.0,44.220.0"}
P.entries["quest:809"] = {n="Ak'Zeloth",s="Nahe Orgrimmar schickt Neeru Feuerklinge Euch ins Brachland, als sich dämonische Verderbnis regt. Sein Kontakt wartet nahe der Grenze.",h="Nahe Orgrimmar schickt Neeru Feuerklinge Euch ins Brachland, als sich dämonische Verderbnis regt.",kw={"ak'zeloth","brachland","burning blade","die kluft der schatten","demon seed","glutnebelgipfel","fernwacht","neeru fireblade"},ang={["class:Warlock"]="Als Hexenmeister bemerkt Ihr vielleicht, dass selbst Neeru Fireblades Gehilfe den Befehl hinterfragt, ein dämonisches Relikt zu zerstören.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die jungen Handels- und Reisewege zwischen Durotar und dem Brachland zu schützen, indem Ihr die Fernwacht sichert und den Glutnebelgipfel säubert.",["race:Orc"]="Als Orc kennt Ihr den Preis der Umklammerung durch die Brennende Legion. Der Kult der Burning Blade und dämonische Relikte vor Eurer Haustür bedrohen Eure hart erkämpfte Freiheit."},sec={{t="Eine Spur der Schatten",b="Neeru Feuerklinge sagt, die Burning Blade bedrohe die Horde noch immer mit dämonischer Verderbnis. Ihr habt ihm ein Halsband mit Insignien der Burning Blade aus Durotar gebracht, und nun schickt er Euch ins Brachland. Ein Kult schart sich um den Demon Seed, ein Artefakt von abscheulicher Macht. Neeru möchte, dass Ihr seinen Kontakt nahe der Grenze findet."},{t="Der Kontakt am Außenposten",b="Ak'Zeloth wartet nahe der Fernwacht an der Grenze zwischen Durotar und dem Brachland. Neerus Gehilfe fragt sich laut, ob sein Meister den Demon Seed wirklich zerstört sehen will. Dann erklärt er, wie mit dem Artefakt auf dem Glutnebelgipfel umzugehen ist."}},faq={{q="Wer vergibt diese Quest?",a="Neeru Feuerklinge, ein Hexenmeister in Orgrimmars Kluft der Schatten, bittet Euch um Hilfe, nachdem Ihr ihm ein Halsband der Burning Blade überreicht habt.",al={"questgeber","wo gibt es ak'zeloth","neeru fireblade quest"}},{q="Wo befindet sich Ak'Zeloth?",a="Ak'Zeloth wartet direkt vor der Fernwacht an der östlichen Grenze des Brachlands, wo die Brücke von Durotar herüberführt.",al={"ak'zeloth standort","wo ist ak'zeloth","ak'zeloth finden"}},{q="Was ist der Demon Seed?",a="Der Demon Seed ist ein Artefakt dämonischer Macht, das der Kult der Burning Blade auf dem Glutnebelgipfel im nördlichen Brachland verwahrt.",al={"demon seed hintergrundgeschichte","was ist der samen"}},{q="Warum findet Ak'Zeloth Neerus Befehle seltsam?",a="Ak'Zeloth sagt lediglich, Neerus Wunsch, den Demon Seed zu zerstören, sei seltsam, und erklärt sich dann bereit, zu erläutern, wie er beseitigt werden kann.",al={"warum ist ak'zeloth überrascht","seltsame reaktion ak'zeloth"}},{q="Welche Quest folgt auf diese?",a="Nachdem Ihr mit Ak'Zeloth gesprochen habt, schickt er Euch los, um den Glutnebelgipfel zu erklimmen und das verderbende Relikt unschädlich zu machen.",al={"nächste quest nach ak'zeloth","ak'zeloth folgequest"}},{q="Gehört diese Quest zur Geschichte der Burning Blade?",a="Ja. Die Aktivitäten des Kults der Burning Blade in Durotar führen zu den weitreichenderen, organisierten Kultaktivitäten im Brachland.",al={"burning blade questreihe","orgrimmar kultquest"}}},fx={["91b6b00f"]={q="Warum möchte Neeru Feuerklinge, dass The Demon Seed zerstört wird?",a="Neeru Feuerklinge behauptet, dass er sich seit der Niederlage der Brennenden Legion dem Ausrotten der verbliebenen dämonischen Verderbnis in den Ländern der Orcs widmet. Als Ihr ihm ein Halsband des Kults der Burning Blade brachtet, erklärte er, dass dies seine schlimmsten Befürchtungen bestätigte. Neeru zufolge zieht der Kult seine Stärke aus The Demon Seed auf dem Gipfel des Glutnebelgipfel, und das Zerschlagen dieses dämonischen Relikts ist entscheidend, um ihren dunklen Einfluss auf die Horde zu stoppen.",al={"neeru fireblade motiv","warum the demon seed zerstören","warum schickt neeru euch"}}},fp="9,122,17.313.0,19.224.1,21.126.0,27.120.0,23.122.0,47.116.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="Heilmittel benötigt",s="An Durotars nordwestlichen Klippen ist Rhinag vergiftet und weit von seinem Heilmittel entfernt. Dem Dunkelspeertroll bleibt wenig Zeit, bevor das Gift ihn tötet, also schickt er einen vorbeikommenden Boten nach Orgrimmar, um Kor'ghans Heilmittel zu holen.",h="An Durotars nordwestlichen Klippen ist Rhinag vergiftet und weit von seinem Heilmittel entfernt.",kw={"gegengift","die kluft der schatten","durotar","kor'ghan","heilmittel benötigt","orgrimmar","rhinag","skorpid","giftschwanz"},ang={["faction:Horde"]="Als Mitglied der Horde stellt Ihr Euch Durotars felsigem, unerbittlichem Gelände, einer Prüfung für Verteidiger, die gerade erst in Thralls jungem Reich angekommen sind.",["race:Troll"]="Als Troll könnt Ihr nachvollziehen, wie sehr Rhinag den Spott seiner Verwandten in Sen'jin fürchtet. Bei den Dunkelspeertrollen zieht Unachtsamkeit beim Überleben in der Wildnis harschen Spott nach sich."},sec={{t="Der Stich eines Skorpids",b="Rhinag kämpfte nahe Durotars Grenze gegen Giftschwanzskorpide, als einer ihn stach. Ihr Gift kann in weniger als einer Stunde töten. Das Gift hindert ihn daran, nach Orgrimmar zu gehen, sodass sein Überleben von einem Reisenden abhängt, der sein abgelegenes Lager rechtzeitig erreicht."},{t="Geheimnisse in den Schatten",b="Rhinag schickt Euch unter Orgrimmar in die Kluft der Schatten, wo Kor'ghan weiß, wie man den Giften aus Durotars Ödland entgegenwirkt. Kor'ghan kann ein Heilmittel brauen, doch er hilft nur selten jenen, die sich noch nicht bewährt haben."}},faq={{q="Wer ist Rhinag?",a="Rhinag ist ein Abenteurer der Dunkelspeertrolle, der an Durotars nordwestlichen Klippen um sein Leben ringt. Ein Giftschwanzskorpid hat ihn gestochen, und er fürchtet, seine Verwandten in Sen'jin würden ihn verspotten, wenn er in einem so erbärmlichen Zustand zurückkehrt.",al={"rhinags geschichte","wer ist rhinag","rhinag der troll"}},{q="Warum ist Kor'ghan in der Kluft der Schatten?",a="Kor'ghan lebt in der Kluft der Schatten unter Orgrimmar. Hexenmeister, Schurken und andere, die dunkle Künste ausüben, wirken dort fernab der Blicke von Thralls geehrten Kriegern. Kor'ghans Wissen über giftige Gebräue und zermürbende Prüfungen passt zu diesen Höhlen.",al={"wo ist korgan","wer ist korghan","kor'ghans aufenthaltsort"}},{q="Warum sucht Rhinag nicht einfach einen Schamanen oder Heiler in Sen'jin auf?",a="Rhinag sagt, sein Stolz halte ihn davon ab, in Sen'jin Hilfe zu suchen. Er fürchtet, die anderen Trolle würden ihn verspotten, weil er unachtsam war und vergiftet zurückkehrt, also sucht er diskret ein Heilmittel bei Kor'ghan.",al={"warum nicht nach senjin gehen","warum rhinag senjin meidet"}},{q="Was geschieht, nachdem Rhinag das Gegengift erhält?",a="Rhinag trinkt das Gegengift und erholt sich, doch Kor'ghan verlangt mehr von ihm. Der Heiler erwartet, dass er zermürbende Prüfungen besteht, darunter Eber zu töten und Skorpidschwänze zu sammeln, bevor er Kor'ghans Wohlwollen erneut verdient.",al={"überlebt rhinag","rhinag danach"}},{q="Wo ist Rhinag zu finden?",a="Rhinag ist in den zerklüfteten Höhen im Nordwesten Durotars zu finden, nahe den Grenzpässen, die nach Westen zum Brachland führen.",al={"rhinags aufenthaltsort","wo ist rhinag"}},{q="Warum muss dieses Heilmittel so dringend beschafft werden?",a="Ohne Behandlung kann das Gift des Giftschwanzskorpids die lebenswichtigen Organe eines Opfers in weniger als einer Stunde überwältigen.",al={"warum gibt es ein zeitlimit","rhinags gift zeitlimit"}}},fx={["0710a7b2"]={q="Wozu dient das Siechstachelgegengift?",a="Das Gegengift wirkt dem tödlichen Gift der Siechstachelskorpide entgegen, die im nordwestlichen Durotar lauern. Rhinag wurde während eines unvorsichtigen Scharmützels mit den Bestien tief gestochen und das Toxin durchströmt rasch sein Blut. Ohne diesen speziellen Trank, der von Kor'ghan in Orgrimmar gebraut wird, hat Rhinag weniger als eine Stunde, bevor das Gift sein Leben fordert.",al={"wofür ist das siechstachelgegengift","gebrauch von siechstachelgegengift","warum siechstachelgegengift nötig"}}},fp="15,218,17.239.0,22.216.0,14.215.0,39.260.0,67.197.0,48.222.1,26.121.0,47.113.0"}
P.entries["quest:813"] = {n="Suche nach dem Gegengift",s="Kor'ghan in Orgrimmar eilt, um ein Heilmittel für den vergifteten Jäger Rhinag zu brauen. Ihr sammelt Giftbeutel von Giftschwanzskorpiden jenseits der Stadtmauern, bevor ihr Gift tödlich wirkt. Durotars Wildnis ist unerbittlich, und das Überleben hängt davon ab, sich auf ihre Gefahren vorzubereiten.",h="Kor'ghan in Orgrimmar eilt, um ein Heilmittel für den vergifteten Jäger Rhinag zu brauen.",kw={"gegengift","durotar","kor'ghan","orgrimmar","gift","rhinag","skorpid","giftschwanz"},ang={["class:Hunter"]="Als Jäger hört Ihr Kor'ghans strenge Mahnung: Kennt das Gift eines Wildtiers und führt neben Eurem Bogen und Euren Fährtenkünsten die richtigen Heilmittel mit.",["faction:Horde"]="Als Mitglied der Horde in Durotar kümmert Ihr Euch um die Euren. Abgelegene Waldläufer und Späher an den Grenzen können sich auf Hilfe aus Orgrimmar verlassen.",["race:Orc"]="Als Ork, der sich erst kürzlich in Durotar niedergelassen hat, steht Ihr vor einer Ausdauerprobe. Selbst ein erfahrener Späher kann durch Unachtsamkeit den natürlichen Gefahren des Landes erliegen."},sec={{t="Ein Wettlauf gegen das Gift",b="Rhinag, ein Dunkelspeertroll, war in Durotar auf der Jagd, als Giftschwanzskorpide ihn angriffen. Ihr Gift wirkt schnell, und er braucht sofort Hilfe. Kor'ghan, ein erfahrener Jäger in Orgrimmar, muss einen Trank brauen, bevor das Gift ihn tötet."},{t="Das Heilmittel brauen",b="Ausgewachsene Giftschwanzskorpide vor Orgrimmars Toren tragen die Beutel, die Kor'ghan für ein Gegengift braucht. Er sagt, es bleibe später Zeit, Rhinag für seine mangelnde Vorbereitung zu tadeln, doch jetzt zählt jeder Augenblick. Bringt die Beutel zurück in die Stadt, damit Kor'ghan einen Trank für den sterbenden Jäger brauen kann."}},faq={{q="Wer ist Rhinag?",a="Rhinag ist ein Trolljäger der Dunkelspeer in Durotar. Giftschwänze stachen ihn, während er Wildtieren nachspürte. Ohne Gegengift ist er auf Hilfe aus Orgrimmar angewiesen, bevor das Gift ihn überwältigt.",al={"rhinag hintergrundgeschichte","wer ist vergiftet","wer braucht das gegengift"}},{q="Wer ist Kor'ghan?",a="Kor'ghan ist ein erfahrener Trolljäger der Dunkelspeer in Orgrimmars Kluft der Schatten. Er kennt Durotars Wildtiere und kann aus Giftbeuteln von Giftschwänzen ein Gegengift brauen.",al={"kor'ghan","wer ist korphan","korgan orgrimmar"}},{q="Woher stammen die benötigten Giftbeutel?",a="Die Giftbeutel stammen von Giftschwanzskorpiden außerhalb Orgrimmars, auf dem felsigen, trockenen Boden nahe dem Stadteingang.",al={"wo sind giftschwänze","giftbeutel fundort","giftschwanzskorpid beutel"}},{q="Warum läuft bei dieser Aufgabe eine Zeitbegrenzung?",a="Rhinags Zustand verschlechtert sich draußen in der Wildnis. Das Gift der Giftschwänze wirkt schnell, daher braucht Kor'ghan die Zutaten rechtzeitig, um ein Heilmittel zu brauen, bevor Rhinag an der Vergiftung stirbt.",al={"warum gibt es eine zeitbegrenzung","need for a cure zeitbegrenzung","quest mit zeitbegrenzung"}},{q="Welche Lehre betont Kor'ghan bei dieser Jagd?",a="Kor'ghan mahnt Jäger, ihre Beute und die von ihr ausgehenden Gefahren zu studieren, bevor sie angreifen. Ohne angemessene Vorbereitung oder Gegenmittel in die Wildnis aufzubrechen, kann einen Krieger das Leben kosten.",al={"kor'ghans lehre","lehre über die jagd","kor'ghans rat"}},{q="Wie hängt diese Aufgabe mit „Need for a Cure“ zusammen?",a="„Need for a Cure“ leitet den Notfall ein und setzt die Zeitbegrenzung in Gang. Suche nach dem Gegengift ist der Schritt zwischen diesem Notfall und dem fertigen Gebräu: Ihr sammelt die Grundzutaten, die Kor'ghan zum Brauen braucht.",al={"need for a cure zusammenhang","vorausgesetzte quest","wie hängt es zusammen"}}},fx={["837950c2"]={q="Warum möchte Kor'ghan, dass dies erledigt wird?",a="Kor'ghan erkennt an, dass Rhinag einen törichten Fehler beging, als er ohne Vorbereitung auf die tödlichsten Skorpide in Durotar jagte, doch er weigert sich, einen der Dunkelspeer wegen schlechten Urteilsvermögens sterben zu lassen. Für Kor'ghan steht das Bewahren des Lebens eines der Ihren vor Zurechtweisungen. Er möchte sofort ein Gegengift brauen, damit Rhinag die tödliche Vergiftung überlebt.",al={"warum rhinag helfen","kor'ghan motiv","warum kümmert sich kor'ghan"}},["20540779"]={q="Wozu dient der Giftbeutel eines Siechstachelskorpiden?",a="Kor'ghan benötigt die frischen Giftbeutel, um ein Gegengift für Rhinag zu destillieren. Indem er die toxischen Komponenten direkt aus den Siechstachelskorpionen in Durotar extrahiert, kann er ein Gegenmittel zusammenbrauen, das stark genug ist, um das schnell wirkende Gift zu neutralisieren, das durch das Blut des vergifteten Jägers strömt.",al={"gebrauch von siechstachel giftbeutel","wofür sind giftbeutel eines siechstachelskorpiden","warum giftbeutel sammeln"}},d062d72d={q="Was sind die Siechstachelskorpide in der Nähe von Orgrimmar?",a="Siechstachelskorpide sind räuberische Skorpide, die in den ariden Ödlanden von Durotar heimisch sind und durch die felsigen Klippen außerhalb von Orgrimmar streifen. Unter den Jägern der Orcs als einige der tödlichsten Kreaturen in der Region bekannt, können ihre toxischen Stiche bei ausbleibender Behandlung schnell töten, was sie zu gefährlichen Bestien macht, die Vorsicht und Respekt erfordern.",al={"was sind siechstachelskorpide","siechstachelskorpid","warum siechstachelskorpide töten"}}},fp="20,262,24.232.0,17.282.0,14.180.0,16.164.0,43.114.0,47.160.0,53.181.0,46.202.0"}
P.entries["quest:815"] = {n="Zerbrecht ein paar Eier",s="Cook Torka wartet vor der nächsten Mahlzeit auf frische Eier von den Echoinseln. Ihr bringt sie unversehrt zurück, damit die Küche ihren Zeitplan einhalten kann.",h="Cook Torka wartet vor der nächsten Mahlzeit auf frische Eier von den Echoinseln.",kw={"zerbrecht ein paar eier","frühstück","koch","kochen","eier","küche","mahlzeiten"},ang={["profession:Cooking"]="Als Koch kennt Ihr den Druck, alle satt zu bekommen. Zerbrechliche Zutaten unversehrt zurückzubringen, gehört in jeder Küche zur Arbeit."},sec={{t="Endlose Mahlzeiten",b="In Klingenhügel in Durotar bereitet Cook Torka von morgens bis abends Mahlzeiten zu. Auf das Frühstück folgt das Mittagessen, dann das Abendessen, und es bleibt kaum Zeit, den Herd zu verlassen und Vorräte zu besorgen. Also schickt Torka Euch zu den Echoinseln, um Taillasher-Eier zu holen, bevor sich die nächste Essensausgabe verspätet. Bringt sie unversehrt zurück, damit der Koch die Küche im Zeitplan halten kann."},{t="Der Dank eines Kochs",b="Cook Torka hat wenig Zeit für Lob, solange noch Mahlzeiten zubereitet werden müssen. Eier müssen behutsam behandelt werden, denn eine gesprungene Schale verdirbt eine Zutat, die die Küche braucht. Wenn Ihr die Eier unversehrt zurückbringt, schickt Torka Euch weiter und kehrt an die Arbeit über dem Feuer zurück."}},faq={{q="Was ist die Quest Zerbrecht ein paar Eier?",a="Cook Torka braucht Euch, um Taillasher-Eier unversehrt von den Echoinseln zurückzubringen, damit die Küche ihren Zeitplan einhalten kann.",al={"zerbrecht ein paar eier quest","was ist zerbrecht ein paar eier","eierquest"}},{q="Wer ist der Koch in Zerbrecht ein paar Eier?",a="Cook Torka bereitet in Klingenhügel in Durotar den ganzen Tag über Mahlzeiten zu. Torka spricht unverblümt und hat es eilig und verlässt sich darauf, dass Ihr rechtzeitig zur Essenszeit Taillasher-Eier unversehrt von den Echoinseln bringt.",al={"wer vergibt zerbrecht ein paar eier","eierquest koch","wer kocht"}},{q="Warum braucht der Koch Eier?",a="Cook Torka braucht Eier für die Mahlzeiten, die den ganzen Tag über zubereitet werden, vom Frühstück bis zum Abendessen. Frische Eier halten die Arbeit in der Küche im Zeitplan.",al={"warum eier","wofür sind die eier","warum werden eier gebraucht"}},{q="Warum spricht der Koch davon, nicht ungeschickt zu sein?",a="Eier können auf dem Rückweg zerbrechen. Cook Torka braucht unversehrte Schalen und Eigelbe für die kommende Essensausgabe.",al={"warum vorsichtig mit eiern","eier nicht zerbrechen","warum nicht ungeschickt"}},{q="Worauf bezieht sich der Titel Zerbrecht ein paar Eier?",a="Der Titel spielt auf das Sprichwort an, dass man kein Omelett machen kann, ohne Eier zu zerbrechen. Er passt zur Aufgabe, zerbrechliche Zutaten in eine geschäftige Küche zu tragen.",al={"zerbrecht ein paar eier bedeutung","bedeutung der redewendung","warum heißt es zerbrecht ein paar eier"}},{q="Warum ist der Koch so ungeduldig?",a="Cook Torka ist vom Frühstück bis zum Abendessen mit der Zubereitung von Mahlzeiten beschäftigt. Da noch mehr gekocht werden muss, hat Torka wenig Geduld für Plaudereien und will an den Herd zurück.",al={"verhalten des kochs","warum ist der koch unhöflich","mürrischer koch"}}},fp="16,147,13.350.0,18.256.0,35.121.0,36.209.0,28.139.0,46.105.0,46.139.0,29.163.0"}
P.entries["quest:816"] = {n="Verloren, aber nicht vergessen",s="Misha Tor'kren wartet auf ihrem Gehöft in Durotar auf Nachricht von ihrem Sohn Kron. Er zog nach Westen, um am Südstrom Krokilisken zu jagen, und sie fürchtet das Schlimmste.",h="Misha Tor'kren wartet auf ihrem Gehöft in Durotar auf Nachricht von ihrem Sohn Kron.",kw={"amulett","krokilisk","dreadmaw","kron","misha","klingenhügel","südstrom","tor'kren"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass ein Fährtenleser die Wildheit seiner Beute einschätzen muss. Kron versäumte dies, und die Krokilisken töteten ihn.",["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass das Leben in Durotar hart ist. Familien kämpfen gegen das unbarmherzige Land und die tödlichen Raubtiere an seinen Grenzen.",["race:Orc"]="Als Orc wisst Ihr, dass Stolz und Kriegsruhm in Eurer Kultur von großer Bedeutung sind. Krons Schicksal zeigt den Preis dafür, gefährlichen Bestien ohne Achtung vor ihrer Stärke entgegenzutreten."},sec={{t="Die Angst einer Mutter",b="Misha Tor'kren lebt auf einem Gehöft nordwestlich von Klingenhügel. Vor einigen Tagen zog ihr Sohn Kron nach Westen, um am Südstrom nahe der Grenze zum Brachland wilde Krokilisken zu jagen. Misha warnte ihn, wie tödlich die Bestien waren, doch sein Stolz trieb ihn dazu, seine Stärke zu beweisen. Seitdem hat ihn niemand mehr gesehen."},{t="Eine düstere Bestätigung",b="Misha bittet Euch, die Ufer des Südstroms nach irgendeiner Spur von Kron abzusuchen, sogar im Inneren der Krokilisken. Die Dreadmaw-Krokilisken bergen die Antwort. In ihren Überresten findet Ihr Krons verschlungenes Amulett. Als Ihr es zurückbringt, weiß Misha, dass ihr Sohn nicht überlebt hat. Das Andenken gibt ihr die Gewissheit, die sie braucht, um mit der Trauer zu beginnen."}},faq={{q="Wer ist Misha Tor'kren?",a="Misha Tor'kren ist eine Orcmutter, die auf einem Gehöft nordwestlich von Klingenhügel in Durotar lebt. Sie fürchtet um ihren vermissten Sohn Kron und bittet Reisende, nach irgendeiner Spur von ihm zu suchen.",al={"misha torkren","wer vergibt verloren, aber nicht vergessen","krons mutter"}},{q="Wer war Kron?",a="Kron war Misha Tor'krens eigensinniger Sohn. Er zog aus, um nahe dem Südstrom gefährliche Krokilisken zu jagen und damit seine Stärke zu beweisen, und starb dort.",al={"wer ist kron","was geschah mit kron","mishas sohn"}},{q="Wo verschwand Kron?",a="Kron zog westwärts durch Durotar zur Grenze zum Brachland, um an den Ufern des Südstroms zu jagen.",al={"wo ist kron","wo nach kron suchen","krons aufenthaltsort"}},{q="Wie beweist Ihr Misha Krons Schicksal?",a="Ihr findet Krons verschlungenes Amulett in den Überresten von Dreadmaw-Krokilisken im Südstrom. Als Ihr es Misha bringt, bestätigt sich sein Tod.",al={"krons amulett","hinweis auf krons schicksal","krokiliskenmagen"}},{q="Welche Belohnung gibt Misha Euch?",a="Misha gibt Euch ein Geschenk, das sie für Krons triumphale Rückkehr von der Jagd vorbereitet hatte. Nachdem sie von seinem Tod erfahren hat, erträgt sie seinen Anblick nicht mehr und gibt es Euch, dem Reisenden, der ihr Gewissheit brachte.",al={"verloren, aber nicht vergessen belohnung","mishas geschenk"}},{q="Warum zog Kron überhaupt fort?",a="Kron zog aus Stolz fort und weil er sein Können als Jäger beweisen wollte. Als Misha ihn vor den gefährlichen Krokilisken warnte, wurde er wütend und stürmte davon, um sie trotzdem zu jagen.",al={"warum jagte kron","krons stolz"}}},fx={ad2ab742={q="Warum möchte Misha Tor'kren, dass dies erledigt wird?",a="Misha wird von der Ungewissheit über das Schicksal ihres Sohnes gepeinigt. Kron ist vor Tagen nach einem Streit davongestürmt, entschlossen, sich gegen gefährliche Bestien zu beweisen. Während sie das Schlimmste fürchtet, kann sie nicht beginnen zu trauern oder einen Abschluss zu finden, bevor sie einen definitiven Beweis für sein Schicksal hat.",al={"warum benötigt misha hilfe","misha tor'kren motiv","warum nach kron suchen"}},a54100a0={q="Wozu dient Krons Amulett?",a="Krons Amulett war ein persönlicher Besitz, den Mishas Sohn bei sich trug, als er zur Jagd aufbrach. Aus dem Magen einer Flussbestie geborgen, dient es als düsterer, unbestreitbarer Beweis für seine Mutter, dass Kron entlang des Südstroms erschlagen wurde.",al={"krons amulett hintergrund","was ist das amulett","zweck von krons amulett"}},a107a32d={q="Was sind die Krokolisken entlang des Südstroms?",a="Schreckmaulkrokolisken sind aggressive, mächtige Reptilien, die in den Wasserwegen und schlammigen Ufern heimisch sind, die Durotar vom Brachland trennen. Bösartig und opportunistisch verschlingen sie jede Beute, die töricht genug ist, sich allein in ihre Futtergründe entlang des Flusses zu wagen.",al={"schreckmaulkrokolisken südstrom","warum krokolisken töten","schreckmaulkrokolisken"}}},fp="22,156,16.286.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="Praktische Beute",s="Vel'rin Fang fordert Tigerhäute von den Echoinseln an, um Sen'jin zu versorgen. Die Zahl der Dunkelspeer wächst, und ihre Vorräte schwinden.",h="Vel'rin Fang fordert Tigerhäute von den Echoinseln an, um Sen'jin zu versorgen.",kw={"dunkelspeer","durotar tiger","die echoinseln","jagd","lederverarbeitung","praktische beute","sen'jin","tigerfell","vel'rin fang"},ang={["class:Hunter"]="Als Jäger wisst Ihr, dass Geduld und Präzision zählen. Vel'rin verfolgte seine Beute einst einen ganzen Tag lang schweigend, bevor er seine Falle zuschnappen ließ.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die junge Enklave der Dunkelspeer zu versorgen und die Südflanke der Horde entlang des großen Meeres zu sichern.",["race:Troll"]="Als Troll der Dunkelspeer jagt Ihr auf den Echoinseln und versorgt Euren Klan. Die Inseln erinnern Euch schmerzlich an die Heimat, die Zalazane Eurem Volk genommen hat."},sec={{t="Eine Frage des Überlebens",b="An Durotars rauer Küste nutzen die Dunkelspeer von Sen'jin jede Ressource so lange wie möglich. Aus Tigerfellen werden Zelte, Decken und Rüstungen. Flüchtlinge treffen ein und Späher kehren zurück, wodurch die Vorräte des Dorfes schwinden. Deshalb schickt der Lederverarbeiter Vel'rin Fang Jäger los, um weitere Häute zu beschaffen."},{t="Gleichgewicht und Jagd",b="Die Dunkelspeer jagen Durotars Tiger nur, wenn der Stamm mehr Vorräte braucht. Ihre Jäger überqueren das Wasser zu den Echoinseln und spüren dort die Raubtiere auf. Für die Trolle stellt jede Jagd auch Geduld, Disziplin und Geschick in der Wildnis auf die Probe."}},faq={{q="Wer ist Vel'rin Fang?",a="Vel'rin Fang ist ein Lederverarbeiter der Dunkelspeer in Sen'jin. Er schickt Jäger los, um die Häute zu beschaffen, die der Stamm für Kleidung, Unterkünfte und Ausrüstung braucht.",al={"vel'rin fang","wer vergibt praktische beute","velrin fang"}},{q="Warum braucht Sen'jin Tigerfelle?",a="Sen'jin verwendet Tigerfelle für Zelte, Decken und Rüstungen. Mit der wachsenden Bevölkerung sind die Vorräte des Dorfes knapp geworden.",al={"warum tigerfelle","zweck von praktische beute","wofür werden felle verwendet"}},{q="Wo findet man Durotars Tiger?",a="Durotars Tiger durchstreifen die Echoinseln, die unmittelbar vor der Südostküste der Region liegen.",al={"wo sind die tiger","fundort der tiger","echoinseln tiger"}},{q="Warum jagen die Trolle nicht alle Tiger in der Nähe?",a="Die Dunkelspeer lassen die Tiger in Ruhe, bis sie mehr Vorräte brauchen. Sie nehmen nur, was der Stamm benötigt, damit die Raubtiere gedeihen können.",al={"warum tiger gedeihen lassen","culling the flock"}},{q="Hat die Tigerjagd eine Bedeutung für die Kultur der Dunkelspeer?",a="Ja. Die Dunkelspeer betrachten die Tigerjagd als Prüfung von Geduld und List. Vel'rin wartete einst fast einen Tag auf den Echoinseln, bevor er seinen ersten großen Jagderfolg errang.",al={"tradition der tigerjagd","erste tigerjagd"}},{q="Warum müssen Jäger zu den Echoinseln reisen, wenn Zalazane sie beherrscht?",a="Zalazane und seine verhexten Schergen halten große Teile der Echoinseln besetzt, doch wilde Tiere gibt es dort weiterhin reichlich. Die Jagd und die Suche nach Verwertbarem an den äußeren Küsten bergen weiterhin Risiken, die die Dunkelspeer eingehen müssen.",al={"tiger auf den echoinseln","warum zu den echoinseln reisen"}}},fx={b158745d={q="Wozu wird das Durotartigerfell benutzt?",a="Die Dunkelspeer verarbeiten die Felle zu essenziellen Waren, um ihre wachsende Siedlung zu schützen und zu versorgen. Vel'rin Fang verwendet die Felle, um robuste Lederüstungen, warme Decken und wetterbeständige Zelte zu fertigen, was sicherstellt, dass die Dorfbewohner in Sen'jin geschützt bleiben und nicht erfrieren, wenn die Jahreszeiten wechseln.",al={"gebrauch von durotartigerfell","wofür ist tigerfell","tigerfell practical prey"}}},fp="14,137,20.267.0,20.236.0,20.144.0,41.131.0,35.79.0,48.138.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="Ein geistvolles Getränk",s="In Sen'jin prüft Meister Vornal angehende Schüler, während sein Augenlicht schwindet. Er schickt sie für Makruraaugen und Kriecherschleim an Durotars Küste und misst dabei ihre Geduld und Entschlossenheit.",h="In Sen'jin prüft Meister Vornal angehende Schüler, während sein Augenlicht schwindet.",kw={"alchemie","kriecherschleim","strand der dunkelspeere","durotar","unversehrtes makruraauge","makrura","meister vornal","sen'jin"},ang={["faction:Horde"]="Durotars Küste bleibt für die junge Horde gefährlich. Wer aggressive Makrura und Kriecher aus der Brandung beseitigt, hilft, die Fischgründe an den Ufern um Sen'jin zu sichern.",["race:Orc"]="Vornal bezweifelt offen, dass Orcs die ruhige Disziplin besitzen, die Alchemie verlangt. Diese Arbeit gibt Euch Gelegenheit zu zeigen, dass zum Zusammenhalt der Horde auch die Geduld eines Gelehrten gehört.",["race:Troll"]="Als Dunkelspeer, der in Sen'jin am Wiederaufbau mitwirkt, helft Ihr, die mystischen und alchemistischen Traditionen des Stammes fortzuführen, indem Ihr Euch vor erfahrenen Meistern wie Meister Vornal beweist."},sec={{t="Das schwindende Augenlicht eines Meisters",b="Meister Vornal lebt in Sen'jin, wo das Alter sein Augenlicht getrübt hat. Urtümliche Magie fiel ihm einst leicht, doch nun nutzt er Alchemie, um seine Wahrnehmung zu schärfen und seine Künste zu wirken. Sein Körper wird schwächer, doch der starrsinnige Troll weigert sich, einen Lehrling aufzunehmen. Er sagt, weder die Dunkelspeer noch Durotars Orcs hätten jemanden hervorgebracht, der seiner Unterweisung würdig wäre."},{t="Die Prüfung der Unerprobten",b="Vornal verlangt Rohstoffe von Durotars rauer Küste: unversehrte Makruraaugen und Phiolen mit Kriecherschleim. Unbeschädigte Augen von gepanzerten, schnappenden Makrura zu erbeuten, erfordert bedachte Schläge. Genug Schleim zu sammeln, prüft, ob ein angehender Schüler eintönige Arbeit ertragen kann. Für Vornal geht es bei der Jagd weniger um Reagenzien als darum, herauszufinden, wer konzentriert bleiben kann."},{t="Ein Maß für Willenskraft",b="Für Meister Vornal sind Zeit und Geduld ein Maß für Stärke. Er erwartet, dass ungestüme Jünglinge frustriert werden oder die Arbeit aufgeben. Makellose Zutaten, die nach Sen'jin zurückgebracht werden, bezeugen Überlebensgeschick entlang der gefährlichen Riffe im Kanal der Echoinseln. Sie zeigen auch die Disziplin, die nötig ist, um die feinen Künste der Alchemie zu meistern."}},faq={{q="Wer ist Meister Vornal?",a="Meister Vornal ist ein betagter Troll, Alchemist und Zauberwirker, der in Sen'jin lebt. Das Alter hat sein Augenlicht getrübt, weshalb er alchemistische Lösungsmittel und Gebräue nutzt, um Magie zu wirken, die ihm einst leichtfiel.",al={"meister vornal","wer ist vornal","vornals geschichte"}},{q="Warum braucht Vornal Makruraaugen und Kriecherschleim?",a="Vornal nutzt alchemistische Mischungen, um seine Magie zu unterstützen und sein schwindendes Augenlicht auszugleichen. Er braucht Kriecherschleim und unversehrte Makruraaugen als Reagenzien, und das Sammeln stellt jene auf die Probe, die seine Unterweisung suchen.",al={"warum kriecherschleim","warum makruraaugen","was stellt vornal her"}},{q="Warum zögert Vornal so sehr, einen Lehrling zu unterweisen?",a="Vornal erwartet große Hingabe und Geduld und duldet kaum Überheblichkeit. Er glaubt, kein Troll oder Orc habe die Hingabe gezeigt, die er verlangt, und hält die meisten angehenden Schüler für hochmütig und leicht entmutigt.",al={"vornals lehrling","warum kein lehrling","sucht vornal einen schüler"}},{q="Wo findet man diese Kreaturen in der Umgebung von Sen'jin?",a="Kriecher und Makrura durchstreifen die seichten Gewässer am Strand der Dunkelspeere und die Wasserwege zwischen dem Festland und den nahen Echoinseln.",al={"wo sind makrura","wo sind kriecher","bestien am strand der dunkelspeere"}},{q="Warum müssen die Makruraaugen unversehrt sein?",a="Vornal braucht unbeschädigte Sinnesorgane für Gebräue, die die Wahrnehmung schärfen. Ein wuchtiger Schlag kann die empfindlichen Augen eines Makrura zerquetschen, daher muss der Jäger präzise und behutsam vorgehen.",al={"unversehrtes auge","unversehrte makruraaugen","warum unversehrte augen"}},{q="Welche Lektion will Vornal vermitteln?",a="Vornal glaubt, dass Geduld den Charakter auf die Probe stellt. Eintönige, schmutzige Sammelarbeit an der Brandung zeigt, ob ein Neuling der Hast nachgibt oder die ruhige Konzentration eines Alchemisten bewahrt.",al={"vornals lektion","bedeutung der quest","geduldsprobe"}}},fx={["4926ebef"]={q="Warum benötigt Meister Vornal einen Abenteurer, anstatt die Reagenzien selbst zu sammeln?",a="Meister Vornal gibt zu, dass sein Sehvermögen mit dem Alter nachlässt, was gefährliche Feldarbeit entlang der Küste nicht ratsam macht. Wichtiger ist, dass er die Aufgabe als bewussten Test nutzt. Vornal weigert sich seit Langem, einen Lehrling anzunehmen, da er glaubt, dass ihm noch kein würdiger Troll oder Orc über den Weg gelaufen ist. Indem er Euch aussendet, um empfindliche Reagenzien von feindseliger Küstenfauna zu ernten, misst er Eure Geduld, Stärke und Willenskraft, um zu sehen, ob Eure Taten Eurem Selbstvertrauen entsprechen.",al={"warum ich vornal","warum benötigt vornal mich","warum einen abenteurer schicken"}},cab96330={q="Was sind die Makrura und Brandungskrabbler, die die Küste von Durotar bedrohen?",a="Makrura sind aggressive, krustazee Humanoide, die in den Gewässern und an den Küsten von Durotar heimisch sind, während Brandungskrabbler wilde, territoriale Krabben sind, die an den Stränden und im seichten Wasser in der Nähe der Echoinseln umherhuschen. Beide bewohnen die Gewässer vor dem Strand der Dunkelspeere, was die Küste für lokale Fischer und Sammler gefährlich macht. Für Meister Vornal sind sie jedoch wertvolle Quellen für spezialisierte alchemistische Reagenzien, die benötigt werden, um seine nachlassenden Sinne auszugleichen.",al={"was sind makrura","makrura durotar","brandungskrabbler sen'jin"}}},fp="16,194,23.343.0,20.348.0,17.315.0,21.196.0,52.200.0,50.212.0,55.127.0,42.180.0,38.161.0"}
P.entries["quest:819"] = {n="Chens leeres Fässchen",s="Im Brachland liegt Chen Stormstouts gekennzeichnetes Fässchen verlassen. Sein Fund erinnert an die alten Verbindungen des Braumeisters zu Durotar.",h="Im Brachland liegt Chen Stormstouts gekennzeichnetes Fässchen verlassen.",kw={"brachland","brauen","braumeister drohn","chen stormstout","leeres fässchen","pandaren","ratschet","rexxar"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr Chen Stormstout als geehrten Verbündeten in Erinnerung behalten, der an der Seite von Rexxar und Rokhan kämpfte, um Durotar zu gründen und die Horde in ihren frühesten Tagen zu beschützen.",["profession:Cooking"]="Als Koch könnt Ihr Chens Fässchen als Vermächtnis eines Braukünstlers betrachten. Sein feiner Gaumen und seine Suche nach seltenen Zutaten inspirierten Handwerker in ganz Kalimdor."},sec={{t="Ein Relikt auf Wanderschaft",b="In den trockenen Weiten des Brachlands finden Reisende manchmal ein verlassenes Holzfass. Razormane-Quilboar und Kolkar-Zentauren lassen gewöhnliche Fässer zurück, doch dieses ist sorgfältig gefertigt und trägt eine Plakette: „Chen Stormstout – Möge Euer Geist beflügelt sein und stets Eure Stimmung heben.“ Es ist ein seltsames Relikt unter Kalimdors Sonne. Um zu erfahren, wie es hierherkam, sucht Ihr jemanden auf, der sich auf das Brauen versteht."},{t="Nachhall von Durotars Gründung",b="In Ratschet erkennt Braumeister Drohn die Machart des Fässchens und nennt Chen Stormstout als seinen Besitzer. Chen ist ein wandernder Pandaren, der während der Kämpfe, die Durotar für Thralls Horde sicherten, mit Rexxar reiste. Jahre sind vergangen, seit Chen über Kalimdors rote Erde wanderte. Doch erfahrene Brauer erinnern sich noch immer an seine Rezepte und seinen Wandergeist."}},faq={{q="Was ist Chens leeres Fässchen?",a="Es ist ein verlassenes Braufass, das im Brachland gefunden wird. Seine Inschrift ehrt den wandernden Pandaren-Braumeister Chen Stormstout.",al={"leeres fässchen","chens fässchen","was ist dieses fass"}},{q="Wer ist Chen Stormstout?",a="Chen Stormstout ist ein wandernder Pandaren-Braumeister, der durch Kalimdor reiste. Er ist vor allem dafür bekannt, Rexxar, einem halb ogrischen Bestienmeister, bei der Verteidigung und Gründung Durotars geholfen zu haben.",al={"wer ist chen","chens geschichte","pandaren-braumeister"}},{q="Zu wem soll ich das Fässchen bringen?",a="Bringt das Fässchen zu Braumeister Drohn, einem orkischen Brauer, der an der Straße nahe Ratschet stationiert ist. Er erkennt Chens Zeichen und weiß, wie sich seine Rezepte nachbrauen lassen.",al={"wo fässchen abgeben","wer will chens fässchen","fässchen abgeben"}},{q="Warum liegt Chens Fässchen draußen im Brachland?",a="Chen durchstreifte Kalimdor vor Jahren auf der Suche nach exotischen Brauzutaten. Auf seinen Reisen half er der jungen Horde, ihre Heimat gegen die Truppen von Admiral Proudmoore zu sichern.",al={"warum liegt das fässchen im brachland","wie kam das fässchen hierher"}},{q="Erscheint Chen Stormstout persönlich?",a="Nein. Chen hat die Region verlassen und wurde seit langer Zeit nicht mehr in Kalimdor gesehen. Seine alten Fässer, Rezepte und die liebevollen Erinnerungen von Verbündeten wie Drohn und Rexxar bleiben.",al={"kann ich chen finden","wo ist chen stormstout","ist chen in classic"}},{q="Was macht Braumeister Drohn mit dem Fässchen?",a="Drohn nimmt das Relikt erfreut entgegen und fordert abenteuerlustige Wanderer auf, Zutaten von heimischen Wildtieren zu sammeln. Damit will er Chens starke, legendäre Gebräue nachbrauen.",al={"drohns questreihe","was passiert als nächstes mit dem fässchen"}}},fp="16,124,17.383.0,28.343.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:81924"] = {n="Wisdom of the Guardians",s="In den zerbrochenen Ruinen von Feralas sucht Tyrisius nach alten Kaldorei-Lehren, bevor sie verschwinden. Obwohl die alten Steine zerschmettert daliegen, lebt die spirituelle Essenz dieser verlorenen Weisheit in fernen Schreinen fort.",h="In den zerbrochenen Ruinen von Feralas sucht Tyrisius nach alten Kaldorei-Lehren, bevor sie verschwinden.",kw={"azshara","feralas","wächtergeister","hinterland","kaldorei","schreine","tyrisius","weisheit der wächter"},ang={["race:NightElf"]="Die uralte Kunde der Kaldorei lebt nicht in Stein fort, sondern in den beständigen Geistern der wilden Schreine."},sec={{t="Widerhall uralter Weisheit",b="Tyrisius warnt, dass die steinernen Aufzeichnungen des Kaldorei-Wissens aus Feralas verschwunden sind. Während der Stein zerfällt, lebt das spirituelle Erbe der uralten Nachtelfen an älteren heiligen Orten in Kalimdor und den Östlichen Königreichen fort.\n\nUm wiederzufinden, was als vergessen galt, müsst Ihr zu heiligen Schreinen reisen, die über Feralas, Azshara und das Hinterland verstreut liegen. Tyrisius bittet Euch, vor die Wächtergeister zu treten, die über diese Orte wachen, Euch als würdig zu erweisen und die uralten Lehren zu empfangen, bevor sie für immer verblassen."}},faq={{q="Wer ist Tyrisius?",a="Tyrisius wacht über uralte Kaldorei-Ruinen in Feralas und weist Suchenden den Weg zu erhaltenem uraltem Wissen.",al={"wer ist tyrisius","wo ist tyrisius"}},{q="Wo sind die Wächtergeister zu finden?",a="Die Wächtergeister wachen über Schreine in Feralas, Azshara und dem Hinterland.",al={"wo sind die geister","orte der wächtergeister","welche gebiete besuchen"}},{q="Warum muss man nach den Wächtergeistern suchen?",a="Tyrisius will uralte Kaldorei-Weisheit durch lebendige Erinnerung bewahren, bevor sie für immer aus der Welt verblasst.",al={"warum die schreine besuchen","was ist das ziel"}},{q="Wie findet man die Wächtergeister?",a="Jeder Wächtergeist verweilt an seinem eigenen Schrein in den uralten Landen.",al={"woran erkennt man die geister","die schreine finden"}},{q="Über welche Ruinen wacht Tyrisius?",a="Tyrisius steht zwischen gefallenen Kaldorei-Ruinen, wo die steinernen Aufzeichnungen uralten elfischen Wissens zerfallen sind.",al={"was sind das für ruinen","ruinen von feralas"}},{q="Wohin kehrt man zurück, nachdem man mit den Geistern gesprochen hat?",a="Sobald Ihr Euch jedem Geist als würdig erwiesen habt, erwartet Tyrisius Eure Rückkehr in Feralas.",al={"wohin nach den schreinen","zu wem zurückkehren"}}},fp="23,221,24.533.0,16.110.0,40.81.0,40.112.0,37.70.0,36.117.0,52.85.0"}
P.entries["quest:8193"] = {n="Master Angler",s="Jeden Sonntag werden bei einem Angelwettbewerb die besten Angler gesucht. Bringt als einer der ersten fünfzig Tastyfish aus den Küstenschwärmen des Schlingendorntals, um als Master Angler ausgezeichnet zu werden.",h="Jeden Sonntag werden bei einem Angelwettbewerb die besten Angler gesucht.",kw={"angelwettbewerb","angeln","fischschwärme","master angler","schlingendorntal","sonntag","tastyfish"},sec={{t="Der Sonntagswettbewerb",b="Der Wettbewerb findet jeden Sonntag statt, und Ihr könnt den Titel Master Angler erringen, indem Ihr dem Veranstalter als einer der ersten fünfzig Tastyfish bringt. Die Fische stammen aus Schwärmen entlang der Küsten des Schlingendorntals und verderben schnell."},{t="Ein zweites Angebot",b="Wenn Ihr für die ersten fünfzig Plätze zu spät kommt, bezahlt Euch der Lehrling des Veranstalters dennoch für Tastyfish. Die Fische halten sich nicht bis zum nächsten Sonntag."}},faq={{q="Wann findet der Angelwettbewerb statt?",a="Der Wettbewerb findet jeden Sonntag statt.",al={"master angler tag","an welchem tag ist der angelwettbewerb"}},{q="Wo finde ich Tastyfish?",a="Schwärme von Tastyfish findet man entlang der Küsten des Schlingendorntals.",al={"tastyfish fundort","wo tastyfish angeln"}},{q="Wie werde ich Master Angler?",a="Bringt dem Veranstalter des Wettbewerbs als einer der ersten fünfzig Tastyfish.",al={"master angler voraussetzungen","angelwettbewerb gewinnen"}},{q="Was geschieht, wenn ich zu spät komme?",a="Der Lehrling des Veranstalters bezahlt Euch für Tastyfish, wenn Ihr zu spät kommt, um unter den ersten fünfzig zu sein.",al={"wettbewerb verpasst","zu langsam beim angeln"}},{q="Kann ich Tastyfish für nächste Woche aufbewahren?",a="Nein. Tastyfish verderben schnell, daher können sie nicht bis zum nächsten Sonntag aufbewahrt werden.",al={"verderben tastyfish","fische bis sonntag aufbewahren"}}},fp="13,169,18.231.0,14.157.0,28.37.0,26.62.0,32.70.0,26.104.0,35.73.0"}
P.entries["quest:81947"] = {n="Sanguine Sorcery",s="Ein Bibliothekar sucht magische Werke für die Bibliothek. Euer Beitrag erweitert ihre Sammlung und ihr Wissen.",h="Ein Bibliothekar sucht magische Werke für die Bibliothek.",kw={"sammlung","wissen","library","magische werke","sanguine sorcery"},sec={{t="Eine wachsende Sammlung",b="Der Bibliothekar hat Euch gebeten, etwas Neues für die Regale zu bringen. Euer Beitrag hilft, das Wissen der Bibliothek zu erweitern."}},faq={{q="Was möchte die Bibliothekarin?",a="Die Bibliothekarin bittet Euch, etwas für die Sammlung zu bringen.",al={"was wird gewünscht","bibliotheksanfrage","sanguine sorcery"}},{q="Woher stammt diese Bitte?",a="Es stammt vom Bibliothekar Garion Wendell in Sturmwind oder von Owen Thadd in Unterstadt, wenn Ihr der Horde angehört.",al={"wo ist die bibliothekarin","library in eisenschmiede","standort der library"}},{q="Warum magische Werke in die Bibliothek bringen?",a="Die Bibliothekarin sagt, magische Werke könnten der Bibliothek nützen und ihr Wissen erweitern.",al={"warum magische bücher","wozu dient es","bibliothekssammlung"}}},fp="16,104,20.123.0,29.67.0,27.106.0,39.82.0"}
P.entries["quest:81949"] = {n="Legenden der Gezeitenweisen",s="Ein Foliant mit wenig bekannter Überlieferung hat eine Bibliothekarin oder einen Bibliothekar in Sturmwind oder Unterstadt erreicht. Die Gelehrten dort begrüßen solche Ergänzungen und möchten ihre Sammlung arkanen Wissens erweitern.",h="Ein Foliant mit wenig bekannter Überlieferung hat eine Bibliothekarin oder einen Bibliothekar in Sturmwind...",kw={"sammlung","legends of the tidesages","library","magische werke","sturmwind","tidesages","foliant","unterstadt"},sec={{t="Wissen sammeln",b="Die Bibliothekare in Sturmwind und Unterstadt möchten ihr Wissen über arkane und geschichtliche Überlieferungen erweitern. Jeder Band, der aus der weiten Welt geborgen wird, bewahrt Wissen, das sonst in Vergessenheit geraten könnte."}},faq={{q="Was ist Legends of the Tidesages?",a="Ein magischer Foliant wurde überbracht, um die Bibliothek zu erweitern, die Garion Wendell in Sturmwind oder Owen Thadd in Unterstadt betreut.",al={"was ist legends of the tidesages","was ist dieses buch","tidesages-buch"}},{q="Wer möchte das Buch?",a="Die Bibliothekare nehmen das Werk an, um sein Wissen zu bewahren und ihre Sammlung zu erweitern: Garion Wendell in Sturmwind für die Allianz oder Owen Thadd in Unterstadt für die Horde.",al={"wer möchte legends of the tidesages","wohin mit legends of the tidesages","wer nimmt das buch"}},{q="Können weitere Bücher in die Bibliothek gebracht werden?",a="Die Gelehrten bitten Euch, ihnen weitere magische Schriften zu bringen, die Ihr findet und die der Bibliothek helfen könnten.",al={"was geschieht nach legends of the tidesages","weitere bücher bibliothek","kann ich weitere bücher bringen"}}},fp="24,183,19.210.0,33.120.0,19.180.0,41.105.0"}
P.entries["quest:81952"] = {n="Everyday Etiquette",s="Ein Hüter der Library sucht magische Werke für die Sammlung. Euer Beitrag hilft, das Wissen der Bibliothek zu erweitern.",h="Ein Hüter der Library sucht magische Werke für die Sammlung.",kw={"sammlung","alltagsregeln","wissen","library","magische werke"},sec={{t="Eine wachsende Sammlung",b="Jede magische Arbeit, die Ihr findet, könnte einen Platz in den Regalen der Bibliothek erhalten. Eure Bemühungen lassen das Wissen der Bibliothek wachsen."}},faq={{q="Was möchte der Hüter der Bibliothek?",a="Der Hüter sucht magische Werke, die der Bibliothek zugutekommen könnten.",al={"bücher der bibliothek","magische werke","was mitbringen"}},{q="Wo spielt sich das ab?",a="Es stammt von einem Bibliotheksverwalter: Garion Wendell in Sturmwind für die Allianz oder Owen Thadd in Unterstadt für die Horde.",al={"standort der bibliothek","wo ist die bibliothek","bibliothek in eisenschmiede"}},{q="Warum werden magische Werke gesammelt?",a="Der Hüter sagt, jeder Beitrag erweitert das Wissen der Bibliothek.",al={"warum bücher sammeln","zweck der bibliothekssammlung","wofür"}}},fp="18,120,20.120.0,34.62.0,27.123.0,38.68.0"}
P.entries["quest:82"] = {n="Erkundung des Giftigen Unterschlupfes",s="Im Giftigen Unterschlupf legen die Centipaar-Insekten die Tümpel trocken, die einst dort lagen. Leitender Feldmesser Rutenwünschels möchte erfahren, wer der Feind ist, also bringt Ihr fünf Insektenteile zur Untersuchung zu Alchimist Pestlezugg in Gadgetzan.",h="Im Giftigen Unterschlupf legen die Centipaar-Insekten die Tümpel trocken, die einst dort lagen.",kw={"centipaar","rutenwünschels","gadgetzan","insekten","der giftige unterschlupf","pestlezugg","tanaris"},sec={{t="Teile aus dem Unterschlupf",b="Nach der Gadgetzan Water Survey wendet sich Leitender Feldmesser Rutenwünschels den Berichten über die Insekten zu. Sie legen die Tümpel trocken, die einst dort lagen, wo sich heute der Giftige Unterschlupf befindet. Er weiß wenig über sie und möchte erfahren, wer der Feind ist, also sammelt Ihr fünf Teile von den Centipaar im Giftigen Unterschlupf. Dann bringt Ihr sie zur Untersuchung zu Alchimist Pestlezugg in Gadgetzan."},{t="Was Pestlezugg herausfindet",b="Alchimist Pestlezugg untersucht die Teile sofort. Sie entsprechen keiner Insektenform, die er je zuvor gesehen hat. Es wirkt beinahe, als würde eine äußere Macht die Insekten kontrollieren. Pestlezugg schickt Euch zurück zum Leitenden Feldmesser Rutenwünschels, dessen dringender Hilfebedarf womöglich mit weiteren Insekten in Tanaris zusammenhängt."}},faq={{q="Warum möchte Leitender Feldmesser Rutenwünschels Insektenteile haben?",a="Insekten legen die Tümpel trocken, die einst dort lagen, wo sich der Giftige Unterschlupf befindet, und sonst ist wenig über sie bekannt. Die Teile der Centipaar könnten Alchimist Pestlezugg helfen, herauszufinden, was sie sind.",al={"warum insektenteile sammeln","rutenwünschels insektenteile","giftiger unterschlupf zweck"}},{q="Wo sind die Centipaar zu finden?",a="Die Centipaar sind im Giftigen Unterschlupf zu finden, wo einst Wassertümpel lagen.",al={"wo ist der giftige unterschlupf","centipaar fundort","wo centipaar finden"}},{q="Wer nimmt die Insektenteile in Gadgetzan entgegen?",a="Alchimist Pestlezugg in Gadgetzan nimmt die Insektenteile zur Untersuchung entgegen.",al={"bei wem abgeben","pestlezugg standort","wer möchte die insektenteile"}},{q="Was kommt vor diesem Schritt?",a="Dieser Schritt folgt auf die Gadgetzan Water Survey.",al={"vorherige quest","vorausgesetzte quest","was führt hierzu"}}},fp="26,219,19.364.0,21.280.1,56.176.0,30.72.0,43.76.0,28.38.0"}
P.entries["quest:82084"] = {n="A Lesson in Literacy",s="Eine Bibliothekarin glaubt, dass Ihr bereit seid, Euer eigenes Zauberbuch zu schreiben. Sammelt eine Feder, Tinte und Papyrus für seine Seiten.",h="Eine Bibliothekarin glaubt, dass Ihr bereit seid, Euer eigenes Zauberbuch zu schreiben.",kw={"farraki papyrus","hinterland","tinte","bibliothekarin","lesen und schreiben","eulenbestienfeder","silithidenharz","zauberbuch"},sec={{t="Materialien für das Zauberbuch",b="Eine Bibliothekarin erkennt großes Potenzial in Euren arkanen Studien und bittet Euch, Vorräte für ein Zauberbuch zu sammeln. Sie braucht eine Eulenbestienfeder aus dem Hinterland, Tinte aus Silithidenharz und Farraki Papyrus für die Seiten."}},faq={{q="Was möchte die Bibliothekarin, dass ich sammle?",a="Die Bibliothekarin bittet Euch, eine Eulenbestienfeder aus dem Hinterland, Tinte aus Silithidenharz und Farraki Papyrus zu sammeln.",al={"zauberbuchvorräte","materialien zum lesen und schreiben","welche materialien"}},{q="Warum sammle ich diese Materialien?",a="Die Bibliothekarin glaubt, dass Ihr bereit seid, ein eigenes Zauberbuch zu schreiben.",al={"warum das sammeln","zweck des zauberbuchs","wofür die vorräte sind"}},{q="Woher stammt die Feder?",a="Die Bibliothekarin bittet Euch um eine Feder von den Eulenbestien des Hinterlands.",al={"eulenbestienfeder","herkunft der feder","woher die feder"}},{q="Woraus wird die Tinte hergestellt?",a="Die gewünschte Tinte wird aus Silithidenharz gewonnen.",al={"silithidentinte","tintenzutat","woraus die tinte besteht"}},{q="Woraus bestehen die Seiten des Zauberbuchs?",a="Die Bibliothekarin bittet Euch um Farraki Papyrus für die Seiten.",al={"papyrus für seiten","farraki-papier","seitenmaterial"}}},fp="20,111,19.229.0,43.127.0,35.68.0,31.69.0,26.49.0,37.53.0"}
P.entries["quest:821"] = {n="Chens leeres Fässchen",s="In Ratschet hofft Braumeister Drohn, Chen Stormstouts starken Trunk mit wilden Zutaten aus dem Brachland wiederzubeleben.",h="In Ratschet hofft Braumeister Drohn, Chen Stormstouts starken Trunk mit wilden Zutaten aus dem Brachland...",kw={"braumeister drohn","chen stormstout","fass","ebenenschreiterniere","ratschet","savannenlöwenhauer","brachland","donnerechsenhorn","trogggebräu"},ang={["faction:Horde"]="Chen Stormstout kämpfte an Rexxars Seite, um bei der Gründung Durotars zu helfen. Überbleibsel seiner Reise haben für die Horde eine besondere kulturelle Bedeutung.",["profession:Cooking"]="Für einen Koch verbindet dies die Schlachterei des Grenzlands mit feiner Braukunst bei der Herstellung legendärer Spirituosen Kalimdors.",["race:Orc"]="Als Ork könnt Ihr in Drohn ein Beispiel dafür sehen, wie Orks alte Braumeistertraditionen pflegen, überliefert von Reisenden, die mit der frühen Horde zogen."},sec={{t="Ein Erbe im Fass",b="Ein Fass mit Schriftzeichen erinnert Braumeister Drohn in Ratschet an Chen Stormstout. Chen vertraute die Geheimnisse des nach ihm benannten Gebräus Drohns Mentor an, der sie an Drohn weitergab. Das Rezept verlangt rohe, kraftvolle Bestandteile aus der wilden Tierwelt des Brachlands. Für alle außerhalb des Brauhandwerks ist das eine ungewöhnliche Wahl."},{t="Ernte der Savanne",b="Um Chens starken Trunk wiederzubeleben, sammelt Ihr Ebenenschreiternieren, Savannenlöwenhauer und ein Donnerechsenhorn. Die Zutaten müssen von widerstandsfähigen Bestien stammen, daher führt Euch die Jagd durch die staubigen Ebenen.\n\nWenn Ihr sie Drohn bringt, erinnert er sich gern an frühere Fuhren Trogggebräu. Die Wiederbelebung der alten Rezeptur wärmt seinen Magen fast so sehr wie jene früheren Gebräue."}},faq={{q="Wer ist Braumeister Drohn?",a="Braumeister Drohn ist ein orkischer Braumeister in der Hafenstadt Ratschet. Sein Mentor erhielt Rezepte vom wandernden Chen Stormstout und gab die Braukunst an Drohn weiter.",al={"braumeister drohn","wer ist drohn","drohn ratschet"}},{q="Warum verlangt ein Bierrezept nach Tiernieren und Hörnern?",a="Die Brautraditionen der Pandaren und ihre Anpassungen an das Grenzland nutzen kraftvolle, geheimnisvolle Zutaten aus der heimischen Tierwelt. Sie verleihen starken Trünken Kraft, Wucht und unverwechselbare natürliche Essenzen.",al={"warum tierbestandteile","ebenenschreiternieren gebräu","löwenhauer bier"}},{q="Wo sind die benötigten Zutaten zu finden?",a="Ebenenschreiter und Savannenlöwen durchstreifen die offenen Grasflächen des Brachlands. Donnerechsen grasen in seinen trockeneren oder felsigeren Landstrichen.",al={"wo hauer finden","wo sind donnerechsen","brauzutaten finden"}},{q="Wer war Chen Stormstout?",a="Chen Stormstout ist ein wandernder Pandarenbraumeister, der während der Gründung Durotars durch Kalimdor reiste. Er half der Horde, während er seltene, exotische Zutaten suchte, um seine starken Biere zu vervollkommnen.",al={"wer ist chen","chen stormstout hintergrundgeschichte","chen"}},{q="Was geschieht, nachdem Ihr Drohn die Zutaten gebracht habt?",a="Wenn Ihr Drohn die Löwenhauer, Ebenenschreiternieren und das Donnerechsenhorn bringt, ist er begeistert. Die Zutaten erinnern ihn an seine früheren Brautage und leiten die letzte Phase der Nachbildung des Trunks ein.",al={"nächste quest nach chens leeres fässchen","drohn belohnung","wie geht es weiter"}},{q="Was ist das Trogggebräu, das Drohn erwähnt?",a="Drohn erinnert sich beim Anblick der wilden Zutaten gern an Trogggebräu. Seine Erinnerung offenbart seine eigenwillige Vergangenheit, in der er im Grenzland herbe, ungewöhnliche Mixturen vergor.",al={"trogggebräu","drohn trogggebräu","troggbier"}}},fx={cd71a987={q="Warum möchte Braumeister Drohn diese Zutaten?",a="Braumeister Drohn möchte das legendäre Gebräu von Sturmbräu nachbilden, ein exotisches und starkes Getränk, das von Chen Sturmbräu an Drohns Mentor und schließlich an ihn weitergegeben wurde. Das Zubereiten des Gebräus ist ein Akt der Nostalgie und des Stolzes für Drohn, der schöne Erinnerungen an berühmte frühere Mixturen weckt und die Techniken ehrt, die von dem wandernden Pandarenmeister hinterlassen wurden.",al={"warum möchte drohn dies","drohn motiv","warum das gebräu machen"}}},fp="16,109,17.301.0,23.360.1,24.167.0,56.181.0,44.124.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="Chens leeres Fässchen",s="In Ratschet widmet sich Braumeister Drohn einem weiteren Rezept, das Chen Stormstout mit ihm geteilt hat. Trogg-Bier erfordert seltene Organe und Drüsen von den Bestien des Brachlands.",h="In Ratschet widmet sich Braumeister Drohn einem weiteren Rezept, das Chen Stormstout mit ihm geteilt hat.",kw={"brachland","braumeister drohn","chen stormstout","chens leeres fässchen","kodoleber","ratschet","gewitterhaut","donnerfalke","trogg-bier"},ang={["faction:Horde"]="Als Mitglied der Horde verbindet Euch eine gemeinsame Geschichte mit Chen Stormstout, der an der Seite der Horde für Durotars Verteidigung kämpfte. Seine Zeit dort hinterließ bei Orks wie Drohn einen bleibenden Eindruck.",["profession:Cooking"]="Trogg-Bier mag kulinarische Puristen vor den Kopf stoßen. Doch nahrhafte Innereien und wirkungsvolle Drüsen folgen dem Brauch der Grenzlande, nichts von der Jagdbeute zu verschwenden.",["race:Orc"]="Als Ork mag Euch Drohns Weg ungewöhnlich erscheinen. Er entschied sich für Chens exotische Braumethoden statt für den traditionellen Weg des Kriegers und betreibt sein Geschäft in Ratschet."},sec={{t="Eine zweite Pandarenformel",b="Ihr habt Braumeister Drohn geholfen, Chen Stormstouts erstes Gebräu nachzubrauen. Nun erfahrt Ihr, dass der wandernde Pandare weitere Braugeheimnisse mit ihm geteilt hat. Drohn besitzt die Formel für Trogg-Bier, ein seltsames Gebräu aus wirkungsvollen Körperteilen der wilden Bestien des zentralen Kalimdor, statt aus Getreide."},{t="Die Zutaten des Trogg-Biers",b="Trogg-Bier erfordert Blitzschlagdrüsen von Gewitterhäuten, eine Speicheldrüse von großen Donnerfalken und eine kräftige Leber von den umherstreifenden Kodos der Ebenen. Gemeinsam destilliert ergeben diese Zutaten ein stark belebendes Getränk für das Leben in der Wildnis."},{t="Eine dauerhafte Partnerschaft",b="Braumeister Drohn hält seine Vereinbarung für Reisende und Söldner aufrecht, die durch Ratschet ziehen. Bringt ihm einen weiteren Vorrat an Bestienorganen, und er ist bereit, mehr Trogg-Bier zu brauen."}},faq={{q="Wer ist Chen Stormstout?",a="Chen Stormstout ist ein schwer zu fassender Pandarenbraumeister, der während der Gründung Durotars durch Kalimdor wanderte. Bevor er seine Reisen fortsetzte, teilte er einige seiner wirkungsvollen Braumethoden mit Drohn in Ratschet.",al={"wer ist chen","chens geschichte","pandare chen"}},{q="Wo befindet sich Braumeister Drohn?",a="Braumeister Drohn befindet sich in Ratschet, dem neutralen Hafen an der Ostküste des Brachlands. Er verbringt seine Tage damit, die Gebräue zu verfeinern, die er von Chen gelernt hat.",al={"drohn standort","wo ist braumeister drohn","drohn npc"}},{q="Was ist Trogg-Bier?",a="Trogg-Bier ist ein starkes Gebräu, dessen Herstellung Chen Drohn beigebracht hat. Bestiendrüsen und Innereien ersetzen den gewöhnlichen Brauhopfen und verleihen dem Getränk einen kräftigen Biss für zähe Abenteurer.",al={"trogg-bier","was ist dieses getränk","was braut drohn"}},{q="Wo sammelt Ihr Blitzschlagdrüsen?",a="Ihr könnt Blitzschlagdrüsen von Gewitterhäuten sammeln, die durch die trockenen Gebiete des Brachlands streifen. Ihre Körper tragen natürliche elektrische Ladungen.",al={"blitzschlagdrüse quelle","gewitterhaut standort","woher bekommt man blitzschlagdrüsen"}},{q="Welche Bestien lassen Donnerfalkenspeicheldrüsen fallen?",a="Große Donnerfalken liefern die Speicheldrüsen, die Drohn benötigt. Diese gefiederten Raubtiere jagen am offenen Himmel über dem Brachland.",al={"donnerfalkenspeicheldrüse","wo sind große donnerfalken","donnerfalke standort"}},{q="Kann ich Trogg-Bier mehr als einmal brauen?",a="Ja. Braumeister Drohn braut weiteres Trogg-Bier, wenn Abenteurer ihm frische Drüsen und eine Kodoleber bringen.",al={"ist das wiederholbar","kann man das erneut machen","trogg-bier wiederholen"}}},fx={["72ec56fd"]={q="Warum möchte Braumeister Drohn diese Zutaten?",a="Drohn ist eifrig darauf bedacht, ein weiteres exotisches Rezept zu teilen, das er direkt vom wandernden Braumeister Chen Sturmbräu gelernt hat. Nachdem er Euch bereits durch die Nachbildung von Chens geschätztem Starkbier geführt hat, möchte Drohn eine Charge starkes Troggbier brauen – eine Mixtur mit einem heftigen Kick, die dazu gedacht ist, herzhafte Abenteurer zu stärken und zu unterstützen, die dem gefährlichen Brachland trotzen.",al={"warum möchte drohn dies","braumeister drohn motiv","warum troggbier brauen"}},["63499675"]={q="Wozu dient die Blitzschlagdrüse?",a="Blitzschlagdrüsen sind eine der Zutaten im Rezept für Chens Troggbier. Drohn bittet um fünf, die von Sturmhäuten im Brachland gesammelt werden.",al={"warum blitzschlagdrüse","blitzschlagdrüse gebrauch hintergrund","wofür werden blitzschlagdrüsen benutzt"}},["4ecc81d9"]={q="Wozu dient die Donnerfalkenspeicheldrüse?",a="Drohn benötigt eine Speicheldrüse von einem Großen Donnerfalken, um Chens Troggbier zu brauen. Er erklärt nicht die genaue Rolle der Drüse bei der Zubereitung des Getränks.",al={"warum donnerfalkenspeicheldrüse","gebrauch von donnerfalkenspeicheldrüse","wofür ist donnerfalkenspeichel"}},["315602f6"]={q="Wozu dient die Kodoleber?",a="Eine Kodoleber ist eine der Zutaten, die Drohn für Chens Troggbier benötigt. Er akzeptiert eine Leber von jedem der Kodos im Brachland.",al={"warum kodoleber","kodoleber gebrauch hintergrund","wofür ist die kodoleber"}}},fp="16,154,25.261.0,28.252.0,23.181.1,23.209.0,34.145.0,18.176.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:8225"] = {n="Rare Fish - Brownell's Blue Striped Racer",s="Ein Angelrekord vermerkt Brownell's Blue Striped Racer als identifiziert. Die Identifizierung ist abgeschlossen.",h="Ein Angelrekord vermerkt Brownell's Blue Striped Racer als identifiziert.",kw={"brownell's blue striped racer","brownell's racer","fischidentifizierung","seltener fisch","belohnung"},sec={{t="Der Rekord",b="Nach der Identifizierung von Brownell's Racer folgt ein kurzes Signal. Brownell's Blue Striped Racer ist als abgeschlossen markiert, und eine Belohnung ist verfügbar."}},faq={{q="Was ist Brownell's Blue Striped Racer?",a="Brownell's Blue Striped Racer ist der Fisch, dessen Identifizierung als abgeschlossen markiert ist.",al={"brownell racer","blau gestreifter fisch"}},{q="Ist die Identifizierung abgeschlossen?",a="Ja. Die Identifizierung von Brownell's Racer ist abgeschlossen.",al={"fischidentifizierung","racer identifiziert"}},{q="Ist eine Belohnung verfügbar?",a="Ja. Nach abgeschlossener Identifizierung ist eine Belohnung verfügbar.",al={"fischbelohnung","was bekomme ich"}}},fp="41,99,10.139.0,38.82.0,31.56.0,22.64.0"}
P.entries["quest:8228"] = {n="Could I get a Fishing Flier?",s="Für diesen Sonntag ist in Beutebucht ein Angelwettbewerb angekündigt. Der Flyer erklärt Euch die Regeln, falls Ihr teilnehmen möchtet.",h="Für diesen Sonntag ist in Beutebucht ein Angelwettbewerb angekündigt.",kw={"beutebucht","angelwettbewerb","angelflyer","angelregeln","turnier"},sec={{t="Turnierregeln",b="Der Aushang nennt Euch die Regeln für den Angelwettbewerb in Beutebucht. Das Turnier findet diesen Sonntag statt. Auf dem Flyer erfahrt Ihr, wie es abläuft, bevor Ihr über eine Teilnahme entscheidet."}},faq={{q="Wann findet der Angelwettbewerb statt?",a="Der Angelwettbewerb in Beutebucht findet diesen Sonntag statt.",al={"wann angelwettbewerb","welcher wochentag"}},{q="Wo findet der Angelwettbewerb statt?",a="Der Angelwettbewerb findet in Beutebucht statt.",al={"angelwettbewerb ort","wo wettbewerb"}},{q="Was steht auf dem Angelflyer?",a="Der Flyer nennt Euch die Regeln des Angelwettbewerbs.",al={"angelflyer informationen","was steht auf dem flyer"}},{q="Kann ich am Turnier teilnehmen?",a="Der Aushang bietet Euch die Regeln, falls Ihr am Angelwettbewerb teilnehmen möchtet.",al={"am angelturnier teilnehmen","am wettbewerb teilnehmen"}}},fp="28,124,16.195.0,28.48.0,29.36.0,36.53.0,36.78.0"}
P.entries["quest:823"] = {n="Bericht an Orgnil",s="Meister Gadrin schickt aus Sen'jin eine Warnung vor der Burning Blade nach Klingenhügel. Dämonische Verderbnis breitet sich in Durotar aus.",h="Meister Gadrin schickt aus Sen'jin eine Warnung vor der Burning Blade nach Klingenhügel.",kw={"burning blade","durotar","meister gadrin","orgnil narbenseele","klingenhügel","bericht an orgnil","sen'jin"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf die Zusammenarbeit zwischen den neu verbündeten Dunkelspeertrollen und Durotars Orcs angewiesen, die sich gemeinsamen Bedrohungen stellen.",["race:Orc"]="Als Orc könnt Ihr in Orgnil Narbenseele einen Verteidiger Eurer Heimat sehen. Er setzt sich dafür ein, dass dämonische Verderbnis in Durotar keine Wurzeln schlägt.",["race:Troll"]="Die Dunkelspeer sind in ihren Kampf gegen Zalazane verstrickt. Dennoch zeigt Meister Gadrin die Verbundenheit der Trolle mit der Horde, indem er die Anführer der Orcs vor Gefahren in der ganzen Region warnt."},sec={{t="Eine gemeinsame Verteidigung",b="Sen'jin hat eigene Sorgen, vor allem Zalazanes Verrat auf den Echoinseln. Doch die Burning Blade bedroht mehr als nur das Dorf. Im Tal der Prüfungen wurde dämonische Verderbnis aufgedeckt, und Meister Gadrin weiß, dass sich diese Gefahr nicht allein bekämpfen lässt. Deshalb schickt er Euch die Straße entlang nach Norden nach Klingenhügel, wo die Anführer der Orcs über Durotar wachen."},{t="Orgnil Narbenseele",b="Orgnil Narbenseele befindet sich im Militärlager von Klingenhügel und hat den Auftrag, das Böse in Durotar auszumerzen und dessen zentrale Gebiete zu schützen. Wenn Ihr Gadrins Warnung überbringt, führt Orgnil die Berichte aus Sen'jin und dem Tal der Prüfungen zusammen. Die Burning Blade ist gefährlich nahe. Er zieht rasch Truppen zusammen, um die Kultisten zu zerschlagen, bevor ihre Rituale die junge Nation zu Fall bringen können."}},faq={{q="Wer vergibt die Quest Bericht an Orgnil?",a="Meister Gadrin, der Hexendoktor der Dunkelspeer und geistige Anführer in Sen'jin, schickt Euch los, nachdem Ihr den Trollen bei ihren ersten örtlichen Schwierigkeiten geholfen habt.",al={"wer vergibt bericht an orgnil","wo gibt es bericht an orgnil","questgeber bericht an orgnil"}},{q="Wo befindet sich Orgnil Narbenseele?",a="Orgnil Narbenseele befindet sich in Klingenhügel, der befestigten Siedlung nördlich von Sen'jin im Herzen Durotars.",al={"wo ist orgnil narbenseele","orgnil narbenseele standort","orgnil narbenseele finden"}},{q="Warum schickt Meister Gadrin Euch nach Klingenhügel?",a="Meister Gadrin erkennt, dass die Umtriebe dämonischer Kulte im Tal der Prüfungen und in ganz Durotar alle bedrohen, nicht nur die Trolle. Er schickt Euch zu Orgnil Narbenseele, dem Orc, der die Region vor der Burning Blade schützen soll.",al={"warum bericht an orgnil","warum nach klingenhügel gehen","zweck von bericht an orgnil"}},{q="Was ist die Burning Blade, die in der Quest erwähnt wird?",a="Die Burning Blade ist ein geheimer Kult von Dämonenanbetern, der im Verborgenen in Durotar und darüber hinaus wirkt. Seine verborgene Präsenz in nahe gelegenen Schluchten und Höhlen bedroht die Sicherheit und Stabilität der jungen Horde.",al={"wer sind die burning blade","kult der burning blade","was ist die burning blade"}},{q="Welche Quest folgt auf Bericht an Orgnil?",a="Nachdem Ihr Orgnil Narbenseele in Klingenhügel den Bericht überbracht habt, gibt er Euch Dark Storms. Er schickt Euch los, um die wachsende Bedrohung durch die Kultisten zu untersuchen und zu bekämpfen.",al={"nächste quest nach bericht an orgnil","bericht an orgnil folgequest","was kommt nach bericht an orgnil"}},{q="Welche Voraussetzung muss erfüllt sein, bevor diese Quest verfügbar wird?",a="Diese Quest folgt auf Eure Ankunft in Sen'jin durch Report to Sen'jin Village. Sie verbindet Eure Entdeckungen im Tal der Prüfungen mit dem umfassenderen Feldzug in Durotar.",al={"voraussetzung für bericht an orgnil","bericht an orgnil freischalten","vorherige quest vor bericht an orgnil"}}},fp="16,138,21.361.0,15.375.0,37.151.0,33.103.0,46.230.0,49.194.0,36.156.0,64.158.0"}
P.entries["quest:8234"] = {n="Versiegelte azurblaue Tasche",s="In Azshara sollt Ihr eine versiegelte Tasche von einem Timbermaw-Schamanen zu Erzmagier Xylem bringen. Die Tasche verbindet den Schamanen und den Magier.",h="In Azshara sollt Ihr eine versiegelte Tasche von einem Timbermaw-Schamanen zu Erzmagier Xylem bringen.",kw={"erzmagier xylem","azshara","tasche","versiegelte azurblaue tasche","timbermaw-schamane"},sec={{t="Eine versiegelte Tasche",b="Ein Timbermaw-Schamane in Azshara hat die Versiegelte azurblaue Tasche, und Erzmagier Xylem wartet im selben Land darauf. Ihr sollt die Tasche von einem zum anderen bringen."}},faq={{q="Wer hat die Versiegelte azurblaue Tasche?",a="Ein Timbermaw-Schamane in Azshara hat die Versiegelte azurblaue Tasche.",al={"wer hat die tasche","timbermaw-tasche"}},{q="Wer möchte die Tasche?",a="Erzmagier Xylem in Azshara soll die Versiegelte azurblaue Tasche erhalten.",al={"wer bekommt die tasche","wohin die tasche bringen"}},{q="Wo finde ich die Tasche?",a="Die Versiegelte azurblaue Tasche ist bei einem Timbermaw-Schamanen in Azshara.",al={"taschenfundort","wo ist die versiegelte azurblaue tasche"}},{q="Wo ist Erzmagier Xylem?",a="Erzmagier Xylem ist in Azshara.",al={"xylems aufenthaltsort","wo ist xylem"}}},fp="16,164,12.164.0,29.55.0,18.61.0,24.59.0,24.29.0"}
P.entries["quest:824"] = {n="Je'neu vom Irdenen Ring",s="Am Außenposten von Zoram'gar untersucht Je'neu vom Irdenen Ring eine Verderbnis, die sich in der Region ausbreitet. Reisende der Horde bringen ihm eine verderbte Wasserkugel, die von den Elementaren Eschentals stammt. Er will die Verderbnis am Zoramstrand und in der Tiefschwarzen Grotte verstehen und hofft, das Gift in den Gewässern aufzuhalten.",h="Am Außenposten von Zoram'gar untersucht Je'neu vom Irdenen Ring eine Verderbnis, die sich in der Region...",kw={"beschmutzte wasserkugel","tiefschwarze grotte","der irdene ring","elementare","je'neu sancrea","mastok wutfauch","der zoramstrand","außenposten von zoram'gar"},ang={["class:Shaman"]="Als Schamane helft Ihr, das Gleichgewicht der Elemente zu bewahren. Indem Ihr die verderbte Kugel überbringt, helft Ihr einem anderen Mitglied des Irdenen Rings, eine gefährliche spirituelle Krankheit zu erkennen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die Küste Eschentals zu sichern, indem Ihr die dunklen Ursprünge der Feindseligkeit örtlicher Elementare nahe befestigten Lagern wie dem Außenposten von Zoram'gar aufdeckt.",["race:Troll"]="Als Troll könnt Ihr Je'neu Sancreas tiefe spirituelle Weisheit erkennen. Er stellt seine von den Ahnen überlieferte Verbindung zu den Geistern in den Dienst des Irdenen Rings."},sec={{t="Ein Bote für die Elemente",b="Mastok Wutfauch schickt Euch mit einer verderbten Wasserkugel, die von den Elementaren Eschentals geborgen wurde, zu Je'neu Sancrea. Überall in der Region sind seltsame Elementare aufgetaucht, angetrieben von einer Macht, die sich die Kundschafter nicht erklären können. Unter ihren Überresten pulsiert eine unversehrte Kugel vor verderbter Magie.\n\nMastok weiß, dass Soldaten und Kundschaftern die spirituelle Einsicht fehlt, um sie zu verstehen. Deshalb verweist er Reisende der Horde an jemanden, der sich mit alten Legenden und Elementarkunde auskennt."},{t="Die Augen des Irdenen Rings",b="Je'neu Sancrea dient dem Irdenen Ring, einem Schamanenorden, der sich dem Gleichgewicht zwischen Azeroths Urkräften verschrieben hat. Die Streitkräfte der Horde bewachen die Grenze am Zoramstrand, während er die spirituelle Wunde in den nahen Tempelruinen der Tiefschwarzen Grotte untersucht.\n\nFür Je'neu ist ein Elementar, der Kraft aus einem verderbten Gefäß schöpft, keine vereinzelte Bedrohung. Es ist ein alarmierendes Omen: Unsichtbare, uralte Mächte verkehren die natürliche Ordnung."}},faq={{q="Wer ist Je'neu Sancrea?",a="Je'neu Sancrea ist ein Trollschamane des Irdenen Rings im Norden Kalimdors. Er widmet sein Leben dem Austausch mit den Elementen und ihrer Erforschung und bleibt nahe dem Zoramstrand, um dunkle Störungen aus der Tiefschwarzen Grotte zu untersuchen.",al={"wer ist jeneu","jeneu sancrea hintergrund","was macht jeneu hier"}},{q="Was ist der Irdene Ring?",a="Der Irdene Ring ist ein Schamanenorden, der sich der Harmonie zwischen Azeroths Urelementen verschrieben hat. Seine Mitglieder erforschen uraltes Wissen, vergessene Geister und alte Legenden, um elementares Chaos zu beheben und spirituelle Verderbnis auf der ganzen Welt zu heilen.",al={"was ist der irdene ring","wer gehört zum irdenen ring","ir­dener ring hintergrund"}},{q="Wo ist Je'neu Sancrea zu finden?",a="Je'neu Sancrea ist am Außenposten von Zoram'gar an der Küste des Zoramstrands in Eschental zu finden. Dort untersucht er elementare Störungen, die von der nahen Tiefschwarzen Grotte ausgehen.",al={"wo ist jeneu","jeneu standort","jeneu sancrea finden"}},{q="Was ist die Beschmutzte Wasserkugel?",a="Die Beschmutzte Wasserkugel ist ein magischer Kanal, durch den mächtige Wasserelementare ihre Kraft leiten. Ihr verderbter, aber unversehrter Zustand deutet darauf hin, dass dunkle Mächte die örtlichen Geister gezielt verdrehen und versklaven.",al={"was ist die kugel","beschmutzte kugel hintergrund","wasserkugel"}},{q="Wer schickt Euch zu Je'neu?",a="Mastok Wutfauch, ein in Eschental stationierter Offizier der Horde, weist Reisende an, das verderbte Relikt zu Je'neu zu bringen. Die Armee kann seine seltsame magische Natur nicht entschlüsseln.",al={"wer beginnt diese quest","mastok quest"}},{q="Was wird Je'neu mit der Kugel tun?",a="Je'neu nimmt das Gefäß für den Irdenen Ring in Verwahrung, um seine Verderbnis zu untersuchen. Er hofft, dadurch zu erfahren, wie sich die Gewässer reinigen lassen und die aufgewühlten Elementare der Region wieder Frieden finden können.",al={"was geschieht mit der kugel","verderbnis heilen"}}},fx={["5c718e13"]={q="Warum sendet Euch Mastok Wutfauch zu Je'neu?",a="Mastok erkennt, dass die Beschmutzte Wasserkugel weit über seine Fachkenntnis hinausgeht. Das Verstehen verderbter Magie, alter Legenden und gestörter Elementare fällt eindeutig in den Bereich von Der Irdene Ring. Er sendet Euch zu Je'neu Sancrea, weil Je'neu ein lokaler Schamane des Irdenen Rings ist, der über das tiefe elementare Wissen verfügt, das benötigt wird, um die wahre Bedeutung und Bedrohung der Kugel zu entschlüsseln.",al={"mastok wutfauch motiv","warum zu jeneu schicken","warum möchte mastok dies erledigt haben"}}},fp="26,308,28.440.0,28.407.0,22.235.0,25.234.0,34.173.0,33.220.0,35.168.0,35.188.0"}
P.entries["quest:8241"] = {n="Nachschub an feurigem Fluxus: Eisen",s="In der Sengenden Schlucht wird Feuriger Fluxus knapp, und Meisterschmied Burninate braucht mehr. Nach What the Flux? bittet Burninate um Schuppen, Eisenbarren und Kohle und nimmt alles, was Ihr anbieten könnt.",h="In der Sengenden Schlucht wird Feuriger Fluxus knapp, und Meisterschmied Burninate braucht mehr.",kw={"kohle","feuriger fluxus","incendosaurusschuppe","eisenbarren","meisterschmied burninate","nachschub an feurigem fluxus: eisen","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate braucht mehr Feurigen Fluxus, da der Vorrat zur Neige geht. In der Sengenden Schlucht bittet Burninate Euch um zwei Incendosaurusschuppen, vier Eisenbarren und Kohle. Alles, was Ihr anbieten könnt, wird angenommen."}},faq={{q="Wer bittet um diese Waren?",a="Meisterschmied Burninate bittet um die Waren und nimmt sie in der Sengenden Schlucht persönlich entgegen.",al={"wer gibt diese quest","burninate feuriger fluxus","wo abgeben"}},{q="Welche Materialien möchte Burninate?",a="Burninate möchte zwei Incendosaurusschuppen, vier Eisenbarren und Kohle.",al={"welche gegenstände werden benötigt","materialien für feurigen fluxus","burninate gegenstände abgeben"}},{q="Was ging dieser Bitte voraus?",a="What the Flux? ging dieser Bitte voraus, und Burninate hat Euch diesen Auftrag gegeben.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum möchte Burninate diese Waren?",a="Burninate sagt, der Vorrat an Feurigem Fluxus schwinde, weshalb mehr benötigt wird, um ihn aufzufüllen.",al={"warum feuriger fluxus","burninates beweggrund"}}},fp="38,190,17.196.0,25.91.0,35.65.0,30.70.0,36.88.0"}
P.entries["quest:8242"] = {n="Nachschub an feurigem Fluxus: Schweres Leder",s="In der Sengenden Schlucht braucht Meisterschmied Burninate mehr Feurigen Fluxus. Nach What the Flux? bittet er Euch um zwei Incendosaurusschuppen, zehn Stück Schweres Leder und Kohle. Bringt alles, was Ihr anbieten könnt.",h="In der Sengenden Schlucht braucht Meisterschmied Burninate mehr Feurigen Fluxus.",kw={"burninate","kohle","feuriger fluxus","schweres leder","incendosaurusschuppe","sengende schlucht","thoriumbruderschaft"},sec={{t="Feuriger Fluxus gesucht",b="Meisterschmied Burninate braucht mehr Feurigen Fluxus in der Sengenden Schlucht. Der Vorrat wird knapp, deshalb bittet er Euch um zwei Incendosaurusschuppen, zehn Stück Schweres Leder und Kohle. Bringt alles, was Ihr anbieten könnt."}},faq={{q="Wer bittet um diese Waren?",a="Meisterschmied Burninate bittet in der Sengenden Schlucht um die Waren und nimmt sie persönlich entgegen.",al={"wer vergibt diese quest","burninate feuriger fluxus","wo abgeben"}},{q="Welche Materialien möchte Burninate?",a="Burninate möchte zwei Incendosaurusschuppen, zehn Stück Schweres Leder und Kohle.",al={"welche gegenstände werden benötigt","materialien für feurigen fluxus","burninate gegenstände abgeben"}},{q="Was ging dieser Bitte voraus?",a="Vor dieser Bitte gab Euch Burninate die Quest What the Flux?.",al={"voraussetzung für diese quest","vorherige quest feuriger fluxus","what the flux voraussetzung"}},{q="Warum möchte Burninate diese Waren?",a="Burninate sagt, dass der Vorrat an Feurigem Fluxus knapp wird und aufgefüllt werden muss.",al={"warum feuriger fluxus","burninate beweggrund"}}},fp="47,202,17.200.0,25.91.0,35.78.0,30.55.0,36.75.0"}
P.entries["quest:8249"] = {n="Plunderkisten benötigt",s="Fahrad versorgt Rabenholdt mit verschlossenen Kisten für die Schurkenausbildung. Er tauscht spezielle Wurfmesser gegen echte schwere Plunderkisten, und sein Bedarf nimmt kein Ende.",h="Fahrad versorgt Rabenholdt mit verschlossenen Kisten für die Schurkenausbildung.",kw={"schwere plunderkiste","hillsbrad","plunderkisten","schlossknacken","taschendiebstahl","rabenholdt","fahrad","zan"},ang={["class:Rogue"]="Als Schurke könnt Ihr diese schweren Truhen durch Taschendiebstahl bei erfahrenen Widersachern erbeuten. Rabenholdt bietet Euch einen Ort, an dem diese unerlaubte Fertigkeit von Nutzen ist.",["faction:Alliance"]="Rabenholdt liegt im umkämpften Gebiet von Lordaeron und handelt unabhängig. Als Wanderer der Allianz könnt Ihr ihm Aufträge bringen, ohne auf Fraktionsgrenzen zu achten.",["faction:Horde"]="Als Agent der Horde könnt Ihr den beschwerlichen Weg in die Berge von Hillsbrad wagen. Rabenholdt kümmert sich nicht um Fraktionstreue und schätzt nützliche Hehlerware über alles."},sec={{t="Rabenholdts Krallen schärfen",b="Das Rabenholdtanwesen liegt verborgen in den Bergen über dem Vorgebirge des Hügellands, wo die Ausbildung niemals endet. Meisterdieb Fahrad beaufsichtigt die Agenten der Gilde und schätzt Geschick im Schlossknacken. Zan liefert Übungsvorrichtungen für neue Rekruten. Fahrad hält sie für zu grob für erfahrene Diebe, die im Einsatz widerspenstige Mechanismen öffnen müssen."},{t="Eine erstaunlich offene Abmachung",b="Fahrad bezahlt für schwere Plunderkisten, die gefährlichen Zielpersonen in ganz Azeroth gestohlen wurden, und nimmt sie in größeren Mengen entgegen. Nur geschickte Diebe können ihren Opfern die Kisten in der Wildnis entwenden, doch jeder darf sie zum Anwesen bringen. Selbst Kisten, denen die größeren Wertsachen bereits entnommen wurden, bringen seine Gunst und fein ausbalancierte Wurfmesser aus dem Anwesen ein. Eine symbolische Münze muss darin bleiben, um die Anwärter zu motivieren."}},faq={{q="Warum will Fahrad diese Plunderkisten?",a="Rabenholdts Schurkenlehrlinge brauchen realistische Schlösser zum Üben. Zan, der ansässige Handwerker des Anwesens, fertigt Übungstruhen, die Fahrad für jeden jenseits des Anfängerstadiums zu einfach findet. Deshalb verlangt er echte verschlossene Kisten, die gefährlichen Zielpersonen abgenommen wurden.",al={"warum plunderkisten","zweck der plunderkisten","warum fahrad kisten will"}},{q="Wo findet diese Aufgabe statt?",a="Der Tausch findet im Rabenholdtanwesen statt, einer geheimen Zuflucht der Diebesgilde in den Bergen nördlich des Vorgebirges des Hügellands.",al={"plunderkisten benötigt ort","wo ist fahrad","rabenholdt ort"}},{q="Können nur Schurken diese Quest abgeben?",a="Jeder, der schwere Plunderkisten zum Anwesen bringt, darf sie abliefern. Geschickte Diebe stehlen die Kisten ihren Opfern durch Taschendiebstahl.",al={"nur für schurken","kann jeder plunderkisten benötigt erledigen","andere klassen plunderkisten"}},{q="Warum müssen noch Münzen in den Kisten bleiben?",a="Fahrad verlangt, dass in jeder Truhe einige Münzen bleiben, damit Schurken in der Ausbildung einen praktischen Anreiz haben, das Schlossknacken zu üben.",al={"warum münzen in der kiste lassen","brauchen kisten beute","leere plunderkisten"}},{q="Was bietet Rabenholdt im Gegenzug?",a="Wer Kisten beisteuert, erhält Ansehen bei der Gilde und fein gearbeitete Wurfmesser von Fahrad. Mit beißendem Spott hofft er, dass sie einen Platz im Herzen eines anderen finden.",al={"plunderkisten benötigt belohnung","was gibt fahrad","rabenholdt wurfmesser"}},{q="Wer ist Zan, über den Fahrad sich beschwert?",a="Zan versorgt Rabenholdt mit Schlössern und Übungsmechanismen. Fahrad hält Zans grobe Arbeit nur für blutige Anfänger geeignet, nicht für ernst zu nehmende Agenten.",al={"wer ist zan","zan rabenholdt","zan schlösser"}}},fx={["45d1fe22"]={q="Warum benötigt Rabenholdt einen außenstehenden Schurken, um Ramschkisten zu beschaffen?",a="Rabenholdts derzeitige Lehrlinge machen noch ihre ersten Gehversuche und verfügen schlichtweg nicht über das Geschick, um auf eigene Faust an komplizierte Schlösser zu gelangen. Die Übungsmechanismen, die von ihrem hauseigenen Tüftler Zan gefertigt werden, sind für fortgeschrittenes Training viel zu primitiv. Fahrad verlässt sich auf versierte Agenten wie Euch, die sich in gefährliches Gebiet vorwagen und echte Schließkassetten mit hoher Sicherheitsstufe stibitzen, welche eine echte Herausforderung darstellen.",al={"warum werde ich nach ramschkisten gefragt","warum winstone wolf mich braucht","warum besorgt rabenholdt sich die ramschkisten nicht selbst"}}},fp="16,166,30.335.0,28.382.0,37.257.0,32.131.0,35.136.0,52.128.0,39.138.0,39.148.0"}
P.entries["quest:825"] = {n="Aus den Wrackteilen geborgen...",s="Gar'Thok schickt Späher der Horde zu den Wracks an der Schipperküste, um Gnomenwerkzeuge zu bergen. Die Horde hofft, die Ingenieurskunst der Allianz zu studieren und dieses Wissen zu nutzen.",h="Gar'Thok schickt Späher der Horde zu den Wracks an der Schipperküste, um Gnomenwerkzeuge zu bergen.",kw={"durotar","gar'thok","gnomenwerkzeuge","prachtmeer","klingenhügel","bergung","schipperküste","burg tiragarde","wrackteile"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass Gar'Thok im Metall der Allianz Wissen zur Abwehr künftiger Invasionen und Material für den Aufbau Durotars sieht.",["profession:Engineering"]="Als Tüftler erkennt Ihr in den Gnomenwerkzeugen das frühe Aufeinandertreffen der mechanischen Präzision der Allianz und der wachsenden Handwerksindustrien der Horde.",["race:Gnome"]="Als Gnom hinterlasst Ihr überall Eure Spuren, wohin die Allianz segelt. Die Horde schätzt Eure ausgeklügelte Ausrüstung genug, um Späher zu ihrer Bergung auszusenden."},sec={{t="Echos der Flotte",b="Großadmiral Daelin Prachtmeer brachte die Flotte von Kul Tiras nach Kalimdor. Ihre Schiffe drängten sich am Ufer nahe Burg Tiragarde. Nach seiner Niederlage versanken zerbrochene Schiffsrümpfe entlang der Schipperküste. Die überlebenden Soldaten der Kul Tiraner befestigen die Burg, während die Wracks auf den Untiefen unter dem Wasser verstreut liegen."},{t="Gnomische Apparaturen",b="Der Einfallsreichtum der Allianz kann ihren Feinden einen Vorteil gegenüber orkischer Stärke, Eisen und Blut verschaffen. Gnomische Techniker begleiteten die Expeditionsflotte und statteten ihre Schiffe mit komplexen Maschinen und präzisen Werkzeugen aus. Gar'Thok will, dass die Horde diese Werkzeuge aus den Wracks birgt. Dann können ihre Handwerker lernen, wie sie funktionieren."},{t="Für Orgrimmar bestimmt",b="Gar'Thok schickt die geborgenen Werkzeuge mit einer Karawane von Klingenhügel nach Orgrimmar. Dort hoffen Handwerker und Taktiker der Horde, die gnomischen Instrumente zu studieren. Sie suchen nach Wegen, den Geräten der Allianz in künftigen Konflikten zu begegnen und ihre eigenen Industrien zu stärken."}},faq={{q="Warum birgt die Horde Werkzeuge aus diesen Wracks?",a="Die Horde will die fortschrittliche Technologie der Allianz verstehen. Gnome bauen ausgeklügelte Maschinen für die Streitkräfte der Menschen. Die Untersuchung ihrer Werkzeuge könnte Taktikern der Horde zeigen, wie sie Allianzgeräten begegnen und nützliche Konstruktionen für ihre eigenen Handwerker anpassen können.",al={"warum gnomenwerkzeuge beschaffen","warum wrack bergen","gar'thoks grund für die werkzeuge"}},{q="Wem gehörten die Schiffe, die vor der Schipperküste als Wracks liegen?",a="Die Schiffswracks gehörten zur Flotte von Kul Tiras unter Großadmiral Daelin Prachtmeer. Nach der Landung in Durotar zum Kampf gegen Thralls neu gegründete Nation wurden mehrere Schiffe an der Küste unmittelbar östlich von Burg Tiragarde zerstört.",al={"wem gehören diese schiffe","wer zerstörte die schiffe in durotar","wracks von prachtmeers flotte"}},{q="Wohin gelangen die geborgenen Werkzeuge nach Klingenhügel?",a="Gar'Thok schickt die geborgenen Gnomenwerkzeuge mit einer Karawane von Klingenhügel nach Orgrimmar. Dort können Ingenieure und Handwerker sie studieren, um die Verteidigung und Industrie der Hauptstadt zu stärken.",al={"was geschieht mit den werkzeugen","wohin gelangen gnomenwerkzeuge","wer erhält das bergungsgut"}},{q="Warum findet man gnomische Werkzeuge auf Kriegsschiffen der Menschen?",a="Gnome sind enge Verbündete der Menschen in der Großen Allianz. Sie bringen oft mechanisches Geschick, Belagerungsgerät und Präzisionswerkzeuge mit, um die Kriegsschiffe der Menschen einsatzfähig zu halten.",al={"warum gnome bei menschen","gnome auf prachtmeers schiffen","gnomische technologie der allianz"}},{q="Was ist die Schipperküste?",a="Die Schipperküste ist Durotars östlicher Küstenstreifen, der an Burg Tiragarde vorbeiführt. In ihren seichten Gewässern liegen halb versunkene und gesunkene Schiffe, die nach den Kämpfen gegen Prachtmeers Expedition zurückblieben.",al={"wo liegt die schipperküste","lage der schipperküste","gebiet mit versunkenen schiffen in durotar"}},{q="Wie hängt diese Aufgabe mit der Bedrohung bei Burg Tiragarde zusammen?",a="Nachdem der Angriff auf Burg Tiragarde die Marinesoldaten der Kul Tiraner vertrieben hat, ergreift Gar'Thok die Gelegenheit, die verbliebenen Ressourcen der Allianz zu beanspruchen. Die Horde kann aus der Niederlage Nutzen ziehen, indem sie nahe Wracks ausschlachtet, bevor Plünderer oder die Gezeiten alles forttragen.",al={"verbindung zu burg tiragarde","zusammenhang mit vanquish the betrayers","warum diese aufgabe nach tiragarde"}}},fp="21,158,19.294.0,20.317.0,22.254.0,51.247.0,46.219.0,49.182.0,46.159.0,26.186.0,58.246.0"}
P.entries["quest:826"] = {n="Zalazane",s="Auf den Echoinseln hat dunkle Magie Zalazane in den Wahnsinn getrieben und gegen seinen Stamm gewendet. Meister Gadrin aus Sen'jin ruft Champions der Horde auf, die Herrschaft des Hexendoktors zu beenden. Zalazane versklavte seine Stammesbrüder, riss die rechtmäßige Heimat der Dunkelspeertrolle an sich und trieb sie ins Exil an Durotars Küste.",h="Auf den Echoinseln hat dunkle Magie Zalazane in den Wahnsinn getrieben und gegen seinen Stamm gewendet.",kw={"dunkelspeer","durotar","die echoinseln","verhexter troll","meister gadrin","sen'jin","vol'jin","voodoo-troll","zalazane"},ang={["class:Shaman"]="Als Schamane kennt Ihr die spirituellen Künste und urtümlichen Kräfte, die Trollschamanen und Hexendoktoren praktizieren. Zalazane missbraucht bindende Magie gegen seine eigenen Stammesbrüder.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, die vertriebenen Dunkelspeere zu verteidigen. Verbündete aus ganz Durotar stehen ihnen in einer der ersten großen Bewährungsproben für den Zusammenhalt der jungen Horde bei.",["race:Troll"]="Als Dunkelspeertroll habt Ihr die persönliche Pflicht, den Verräter zu bestrafen, der Eurem Volk die Heimat raubte und Eure Stammesbrüder versklavte."},sec={{t="Verrat auf den Inseln",b="Nach ihrer Flucht von ihrer versunkenen Insel folgten die Dunkelspeere Thrall über das große Meer und siedelten auf den Echoinseln direkt vor Durotars Südostküste. Zalazane war einst ein angesehener und mächtiger Hexendoktor, doch ihn dürstete nach Macht. Seine Flüche versklavten den Geist seiner Stammesbrüder, und Gewalt folgte. Vol'jin führte jene an, die frei geblieben waren, doch sie wurden aus ihren angestammten Lagern vertrieben und mussten in Sen'jin eine vorübergehende Zuflucht errichten."},{t="Die Qual eines Stammes",b="Von seiner Festung auf der Hügelkuppe der größten Echoinsel entsendet Zalazane noch immer Überfalltrupps über den Kanal. Sie verschleppen weitere Dunkelspeere und bringen sie unter seine Kontrolle. Die gefangenen Trolle werden zu geistlosen Voodoo- und verhexten Knechten, die für ihren Stamm verloren sind. Meister Gadrin sieht mehr als nur das Land der Dunkelspeere bedroht: Zalazane gefährdet das Überleben des Stammes. Solange sein abgetrennter Kopf nicht vor die Ältesten gebracht wird, kann kein Dunkelspeer sicher sein."}},faq={{q="Wer ist Zalazane?",a="Zalazane war einst ein bedeutender Hexendoktor unter den Dunkelspeertrollen. Der Hunger nach dunkler Macht verdarb ihn, und er wandte sich gegen seine Stammesbrüder, versklavte sie mit geistesbeherrschendem Voodoo und riss die Echoinseln an sich.",al={"zalazane hintergrundgeschichte","wer ist der boss auf den echoinseln","hexendoktor zalazane"}},{q="Warum flohen die Dunkelspeere von den Echoinseln?",a="Die Dunkelspeere flohen, nachdem Zalazane die Macht auf den Inseln überraschend an sich gerissen und ihre Stammesbrüder durch Zauberei in geistlose Knechte verwandelt hatte. Vol'jin und die freien Dunkelspeere waren zu wenige, um sich ihren verzauberten Stammesbrüdern zu stellen, also zogen sie sich aufs Festland von Durotar zurück und gründeten Sen'jin als vorübergehende Zuflucht.",al={"warum sind trolle in sen'jin","echoinseln vorgeschichte","wie verloren die trolle die echoinseln"}},{q="Was geschieht mit den Trollen unter Zalazanes Kontrolle?",a="Flüche haben die Trolle unter Zalazanes Kontrolle ihres Verstandes beraubt. Sie dienen ihm, patrouillieren auf den Inseln und überfallen das Festland, um weitere Opfer zu fangen. Meister Gadrin betrachtet sie als für den Stamm verloren und ihre Hinrichtung als die einzige Gnade.",al={"verhexte trolle","voodoo-trolle","können zalazanes knechte geheilt werden"}},{q="Wo befindet sich Zalazane?",a="Zalazane hat seinen Unterschlupf auf der größten Echoinsel, direkt östlich von Durotars Südküste. Er patrouilliert vom hohen Gipfel ihres zentralen Hügels bis hinunter zu der Ansammlung von Trollhütten darunter.",al={"zalazane aufenthaltsort","zalazane finden","wo ist zalazane"}},{q="Wer erteilt den Auftrag, Zalazane zu töten?",a="Meister Gadrin, ein Stammesältester in Sen'jin an Durotars Südküste, bittet Euch, Zalazane zu töten. Ihr begegnet ihm, nachdem Ihr örtliche Bedrohungen bewältigt habt und aus dem Tal der Prüfungen angereist seid.",al={"wer startet zalazane","wo gibt es die zalazane-quest"}},{q="Warum führt Vol'jin den Angriff nicht selbst an?",a="Vol'jin regiert den Stamm und koordiniert gemeinsam mit Kriegshäuptling Thrall in Orgrimmar die Verteidigung der Dunkelspeere. In Sen'jin sichern Älteste wie Meister Gadrin das Überleben vor Ort, und Gadrin wirbt fähige Abenteurer an, um gegen Zalazane zurückzuschlagen.",al={"wo ist vol'jin","warum kämpft vol'jin nicht gegen zalazane"}}},fx={a3c2387d={q="Wozu dient Zalazanes Kopf?",a="Meister Gadrin verlangt Zalazanes abgetrennten Kopf als unbestreitbaren Beweis für den Untergang des Hexendoktors. Nur wenn er den Kopf mit eigenen Augen sieht, kann Gadrin sicher sein, dass Zalazanes dunkler Einfluss gebrochen ist und der Stamm der Dunkelspeere endlich in Frieden ruhen kann.",al={"zweck von zalazanes kopf","warum zalazanes kopf bringen","zalazanes kopf questgegenstand"}},ae6e25c2={q="Warum möchte Meister Gadrin, dass Zalazane getötet wird?",a="Zalazane ist nicht zufrieden damit, die Echoinseln gestohlen zu haben; er entsendet kontinuierlich seine unterworfenen Trolle über das Wasser, um das Festland zu überfallen, und versklavt weitere Dunkelspeer, um seine Ränge zu verstärken. Meister Gadrin weiß, dass Sen'jin niemals sicher sein wird, solange der abtrünnige Hexendoktor lebt, um ihr Volk zu quälen und zu entführen.",al={"gadrin zalazane warum","warum zalazane töten","warum möchte meister gadrin das"}}},fp="8,304,21.444.0,17.430.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="Die Knochenhöhle",s="Margoz schickt Euch östlich von Orgrimmar, wo Kultisten der Burning Blade die Knochenhöhle besetzt halten. Sie binden sich mit schmerzhaften dämonischen Vorrichtungen an dunkle Magie. Margoz braucht die verfluchten Artefakte, um den Kult nahe der Hauptstadt zu erforschen.",h="Margoz schickt Euch östlich von Orgrimmar, wo Kultisten der Burning Blade die Knochenhöhle besetzt halten.",kw={"burning blade","kultisten","dämonisch","durotar","teufelsmagie","margoz","orgrimmar","senghalsband","die knochenhöhle"},ang={["class:Warlock"]="Als Hexenmeister erkennt Ihr, wie Senghalsbänder ihre Träger mit Teufelsmagie binden. Ihre groben Verzauberungen zeigen, wie der Kult dämonische Opfer in Macht verwandelt.",["faction:Horde"]="Als Mitglied der Horde steht Ihr einem dämonischen Kult gegenüber, der sich direkt vor Orgrimmars Mauern festgesetzt hat. Er bedroht das Herz und die Sicherheit Eures Volkes.",["race:Orc"]="Als Orc steht Ihr der Burning Blade als Überbleibsel der dunklen Vergangenheit Eures Volkes gegenüber. Den Kult aus Durotars Felsen zu vertreiben, ist eine Frage des Überlebens und der Ehre."},sec={{t="Ein Hort der Schatten",b="Im Nordosten Durotars versammeln sich Kultisten der Burning Blade nahe den Toren Orgrimmars. Ihre Höhle liegt zwischen den Hügeln, abseits der offenen Straßen, doch nahe dem Sitz des Kriegshäuptlings. Der Kult sucht die orcische Gesellschaft schon lange heim, und nun vollziehen seine Anhänger Rituale in den Tunneln. In der Nähe halten die Späher des Kriegshäuptlings Wache."},{t="Dämonische Einstimmung",b="Kultisten der Burning Blade tragen Senghalsbänder um den Hals. Die Metallreifen versengen und brandmarken ihr Fleisch. Margoz glaubt, dass der Schmerz und die Teufelszauberei ihre Träger auf dämonische Macht einstimmen. Er bittet Euch, die Halsreifen zu beschaffen, damit er die Zauber und Bindungen untersuchen kann, die ihnen Macht verleihen."},{t="Die heraufziehende Bedrohung",b="Die Senghalsbänder offenbaren, wie sich die Burning Blade in Durotar organisiert hat. Ihre Zauberei bedroht die neu gegründeten Gebiete der Horde. Margoz untersucht die Halsreifen und stellt dann weitere Nachforschungen in Orgrimmars verborgenen Zirkeln an."}},faq={{q="Wo liegt die Knochenhöhle?",a="Die Knochenhöhle liegt im Nordosten Durotars, östlich von Orgrimmar und nördlich von Sen'jin. Ihr Eingang befindet sich in einer zerklüfteten Felswand entlang der Küste.",al={"knochenhöhle lage","wo ist die knochenhöhle","knochenhöhle höhle durotar"}},{q="Wer ist die Burning Blade?",a="Die Burning Blade ist ein Kult aus Orcs und Teufelsanbetern, die sich Dämonen und dunkler Magie verschrieben haben. Die heutige Horde hat sich aus der Knechtschaft der Dämonen befreit, doch Splittergruppen wie die Burning Blade vollziehen weiterhin verbotene Riten und versuchen, die Horde aus den Schatten heraus zu verderben.",al={"was ist die burning blade","wer sind die kultisten der burning blade","burning blade hintergrundgeschichte"}},{q="Wozu verwenden die Kultisten die Senghalsbänder?",a="Kultisten tragen Senghalsbänder um den Hals, wo das feurige Metall ihr Fleisch verbrennt. Margoz vermutet, dass der Schmerz und die dämonische Verzauberung ihnen helfen, dunkle Teufelsenergien zu kanalisieren und sich auf sie einzustimmen.",al={"senghalsbänder zweck","warum senghalsbänder tragen","was sind senghalsbänder"}},{q="Wer ist Margoz?",a="Margoz ist ein orcischer Einsiedler, der in einem kleinen Lager auf Durotars Klippen nahe der Knochenhöhle lebt. Er beobachtet die Bewegungen der Kultisten entlang der Küste und arbeitet daran, die Machenschaften der Burning Blade zu unterbinden.",al={"wer ist margoz","margoz durotar","margoz questgeber"}},{q="Warum duldet die Horde den Kult so nahe bei Orgrimmar?",a="Die Horde duldet den Kult nahe Orgrimmar nicht wissentlich. Anhänger der Burning Blade verstecken sich in Höhlen und öden Schluchten außerhalb der üblichen Patrouillenwege, und Abenteurer ermitteln, wenn die Rituale des Kults seine Stützpunkte offenbaren.",al={"warum liegt die knochenhöhle nahe orgrimmar","orgrimmar burning blade in der nähe"}},{q="Was geschieht, nachdem Margoz die Halsreifen untersucht hat?",a="Margoz plant, die Senghalsbänder zu untersuchen. Seine Nachforschungen gehen bei Neeru Feuerklinge in Orgrimmar weiter.",al={"nächste quest nach der knochenhöhle","wohin führen die halsreifen","margoz zauber"}}},fx={cfe1a49d={q="Warum will Margoz die Senghalsbänder?",a="Margoz glaubt, dass die Kultisten sich durch das Verbrennen ihrer Haut mit diesen Halsbändern an dämonische Mächte binden. Er benötigt eine Sammlung intakter Halsbänder, um sie mit seiner Magie zu untersuchen und zu prüfen, in der Hoffnung, die dunklen Geheimnisse hinter der Burning Blade aufzudecken und zu enthüllen, wie tief ihre dämonische Verderbnis reicht.",al={"warum braucht margoz die halsbänder","margoz searing collars motiv","warum searing collars sammeln"}},["50396613"]={q="Gegen wen werden Ihr in Die Knochenhöhle ausgesandt?",a="Ihr werdet gegen die Kultisten der Burning Blade ausgesandt, die sich in Die Knochenhöhle verstecken, einer Höhle östlich von Orgrimmar. Sie haben sich dort unter der Nase der Horde versammelt, um abscheuliche Rituale durchzuführen, sich an dämonische Meister zu binden und Pläne gegen die Sicherheit von Durotar zu schmieden.",al={"wer ist in die knochenhöhle","die knochenhöhle gegner","burning blade kultisten die knochenhöhle"}}},fp="10,216,16.308.0,18.283.0,18.239.1,28.145.0,25.257.0,49.201.0,14.192.0,56.219.0,47.107.1"}
P.entries["quest:8273"] = {n="Orans Dankbarkeit",s="Ihr bringt Oran Snakewrithe eine Tafel, und Rin'jis Questreihe findet ihren Abschluss.",h="Ihr bringt Oran Snakewrithe eine Tafel, und Rin'jis Questreihe findet ihren Abschluss.",kw={"dunkle fürstin","hinterlands","oran snakewrithe","klippen des rundblicks","rin'ji","tafel"},sec={{t="Eine Tafel für Oran",b="Nach Rin'ji's Secret bringt Ihr die Tafel zu Oran Snakewrithe. Ihr legt sie ihm in die Hände."},{t="Orans Antwort",b="Ihr erzählt Oran Snakewrithe, dass die Tafel von einer kleinen, verlassenen Insel an den Klippen des Rundblicks stammt. Er findet die Entdeckung sehr interessant und verstaut die Tafel sorgfältig. Dann sagt er, dass die Dunkle Fürstin sehr erfreut sein wird."}},faq={{q="Wer ist Oran Snakewrithe?",a="Oran Snakewrithe nimmt die Tafel am Ende der Questreihe entgegen, die mit „Rin'ji is Trapped!“ begann und mit „Rin'ji's Secret“ weiterging.",al={"oran","wer ist oran","oran snakewrithe geschichte"}},{q="Was kommt davor in der Questreihe?",a="Davor kommt „Rin'ji's Secret“, dem „Rin'ji is Trapped!“ vorausgeht.",al={"vorherige quest","voraussetzung für orans dankbarkeit","wie beginnt orans dankbarkeit"}}},fp="16,72,17.91.0,13.220.1,24.134.0,36.66.0"}
P.entries["quest:828"] = {n="Margoz",s="Im Norden Durotars wacht Margoz über die wachsende Bedrohung durch die Burning Blade. Nach dem Kampf gegen die Teufelsverderbnis am Donnergrat schickt Orgnil Narbenseele Champions zum einsamen Lager des Schamanen, bevor sie eine nahe Kultistenhochburg angreifen. Margoz' Rat enthüllt die Knochenhöhle als verborgenen Höhlenstützpunkt der Burning Blade.",h="Im Norden Durotars wacht Margoz über die wachsende Bedrohung durch die Burning Blade.",kw={"burning blade","staubwindklamm","durotar","margoz","orgnil narbenseele","orgrimmar","schamane","die knochenhöhle"},ang={["class:Shaman"]="Als Schamane erkennt Ihr Margoz' geduldige Weisheit in seiner Wacht am Rande der Wildnis. Er spürt spirituelle Verderbnis, bevor daraus Krieg entsteht.",["faction:Horde"]="Als Mitglied der Horde hört Ihr Margoz' Warnung: Dämonenkulte lauern in Schlagweite von Orgrimmar.",["race:Orc"]="Als Orc erinnert Euch die Begegnung mit Margoz daran, dass Teufelsmacht Euer Volk noch immer in Versuchung führt. Er drängt die neue Generation auf einen reinen, ehrenhaften Pfad."},sec={{t="Die Wacht eines Einsiedlers",b="Nachdem am Donnergrat das Ausmaß der Teufelsverderbnis sichtbar wurde, erkennt Orgnil Narbenseele, dass Stärke allein Durotar nicht reinigen kann. Deshalb schickt er Champions zu Margoz, einem erfahrenen Orcschamanen in einem einsamen Lager in den zerklüfteten Höhen nordöstlich von Klingenhügel. Zwischen der Staubwindklamm und dem östlichen Meer hält Margoz im Norden nach dunklen Omen Ausschau, die Orgrimmars vielbeschäftigten Kriegern oft entgehen."},{t="Die Bedrohung der Knochenhöhle",b="Margoz weiß, wo die Burning Blade ihre Macht im nördlichen Durotar aufgebaut hat: in der Knochenhöhle, einem verborgenen Höhlensystem in den Bergklippen vor Orgrimmars südlichen Toren. Die Kultisten sind Thralls Hauptstadt näher, als die Wachen des Kriegshäuptlings ahnen. Verborgene Gänge dort könnten einen dämonischen Hinterhalt verbergen, deshalb berät Margoz jene, die gegen den Zirkel ausgesandt werden, bevor sie eintreten."}},faq={{q="Wer ist Margoz?",a="Margoz ist ein erfahrener, der Horde treuer Orcschamane, der ein einsames Lager im Nordosten Durotars unterhält. Er erforscht dunkle Magie und beobachtet die dämonische Verderbnis, die sich in der Region ausbreitet.",al={"margoz geschichte","wer ist margoz","margoz npc"}},{q="Wo finde ich Margoz?",a="Ihr findet Margoz in seinem Lager in den zerklüfteten Hügeln im Nordosten Durotars, zwischen der Staubwindklamm und der östlichen Küste, südöstlich von Orgrimmar.",al={"margoz standort","margoz finden","wo ist margoz"}},{q="Warum schickt mich Orgnil Narbenseele zu Margoz?",a="Orgnil Narbenseele schickt Euch zu Margoz, weil der Schamane die örtlichen Kultisten der Burning Blade erforscht hat. Bevor Ihr ihre Hochburg angreift, möchte Orgnil, dass Ihr Margoz' spirituelle Weisheit und praktischen Rat hört.",al={"warum mit margoz sprechen","orgnil narbenseele margoz"}},{q="Was ist die Knochenhöhle?",a="Die Knochenhöhle ist ein verborgenes System von Berghöhlen unmittelbar südlich von Orgrimmars östlichen Mauern. Dort verehren Kultisten der Burning Blade Dämonen und vollziehen Rituale nahe der Hauptstadt der Horde.",al={"knochenhöhle geschichte","was ist die knochenhöhle"}},{q="Was geschieht, nachdem ich Margoz gefunden habe?",a="Wenn Ihr Euch bei Margoz meldet, erkennt er Eure wachsende Stärke an und schickt Euch in die Knochenhöhle, um die Kultisten zu töten und ihre verderbten Insignien zu bergen.",al={"nächste quest nach margoz","margoz folgequest"}},{q="Gehört Margoz zur Burning Blade?",a="Nein. Margoz ist ein ergebener Schamane der Horde, der dämonischen Einfluss zu tilgen und junge Champions auf einen ehrenhaften, unverdorbenen Pfad zu führen sucht.",al={"ist margoz böse","ist margoz ein kultist"}}},fp="6,333,16.370.0,24.392.0,14.189.0,23.151.0,43.211.0,19.186.0,34.153.1,36.137.0"}
P.entries["quest:829"] = {n="Neeru Feuerklinge",s="In Orgrimmar studiert Neeru Feuerklinge dunkle Künste, die angeblich die Horde schützen können. Margoz schickt Euch aus Durotar mit einem Senghalsband, das der Burning Blade abgenommen wurde, und hofft, dass der Hexenmeister dessen dämonische Macht erklären kann.",h="In Orgrimmar studiert Neeru Feuerklinge dunkle Künste, die angeblich die Horde schützen können.",kw={"burning blade","die kluft der schatten","durotar","margoz","neeru feuerklinge","orgrimmar","senghalsband","die knochenhöhle","hexenmeister"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die Elemente bei Teufelsartefakten keine Antwort geben werden. Margoz ist an die Grenzen seiner Künste gestoßen und braucht die Hilfe eines Hexenmeisters.",["class:Warlock"]="Als Hexenmeister begegnet Ihr in der Kluft der Schatten Neeru Feuerklinge, Orgrimmars bekanntestem Hexenmeister. Eure verbotenen Künste können der Horde dienen.",["faction:Horde"]="Als Mitglied der Horde erlebt Ihr einen brüchigen Waffenstillstand in Orgrimmar. Die Schamanen des Kriegshäuptlings verlassen sich bisweilen auf die zwielichtigen Ausgestoßenen der Kluft der Schatten, um Durotar zu schützen."},sec={{t="Die Grenzen eines Schamanen",b="Margoz ist an die Grenzen seiner schamanischen Künste gestoßen. Die Halsbänder, die Kultisten der Burning Blade in der Knochenhöhle abgenommen wurden, tragen dämonische Zauber, die er nicht entschlüsseln kann. Schamanen schöpfen ihre Kraft aus den Elementen und den Geistern der Ahnen. Deshalb schickt Margoz Euch zu einem Hexenmeister in der Hauptstadt, um zu erfahren, was die Halsbänder bewirken."},{t="In die Kluft der Schatten",b="Unter Orgrimmars roten Klippen liegt die Kluft der Schatten. Hexenmeister und andere Anwender verbotener Magie wirken dort unter Thralls wachsamem Blick. Neeru Feuerklinge lebt in der Höhle und behauptet, Teufelskräfte zu erforschen, um dämonische Bedrohungen abzuwehren. Als Ihr ihm das Halsband bringt, lenkt seine Neugier die Ermittlungen in Durotar zur Enklave der Hexenmeister."}},faq={{q="Warum schickt Margoz mich zu einem Hexenmeister?",a="Margoz ist ein Schamane, der seine Kraft aus den Elementen und den Geistern der Ahnen schöpft. Die Senghalsbänder aus der Knochenhöhle tragen dämonische Magie, weshalb er jemanden braucht, der Teufelsmagie und dunkle Künste beherrscht, um ihre Verzauberungen und Herkunft zu verstehen.",al={"warum hexenmeister","warum neeru","margoz hexenmeister"}},{q="Wo finde ich Neeru Feuerklinge?",a="Ihr findet Neeru Feuerklinge in der Kluft der Schatten unter Orgrimmar, wo sich Hexenmeister, Schurken und Schattenzauberer versammeln.",al={"neeru aufenthaltsort","wo ist neeru feuerklinge","kluft der schatten neeru"}},{q="Kann man Neeru Feuerklinge vertrauen?",a="Margoz bezweifelt Neerus Behauptung, seine okkulten Forschungen seien harmlos und dienten dem Kampf gegen Dämonen. Thrall duldet Hexenmeister in Orgrimmar unter strenger Aufsicht, doch ob Neeru vertrauenswürdig ist, bleibt ungewiss.",al={"ist neeru böse","neeru vertrauenswürdig","kann man feuerklinge vertrauen"}},{q="Was ist das Beispielhalsband?",a="Das Beispielhalsband ist eines der Senghalsbänder, die Kultisten der Burning Blade in der Knochenhöhle abgenommen wurden. Margoz gibt es Euch, damit Ihr es Neeru Feuerklinge zur magischen Untersuchung bringt.",al={"beispielhalsband","was ist das halsband","senghalsband questgegenstand"}},{q="Was geschieht, nachdem ich Neeru das Halsband gegeben habe?",a="Neeru untersucht das Halsband eingehend und schickt Euch weiter, um der Präsenz des Kults in Durotar nachzugehen. Die Suche richtet sich auf Ak'Zeloth.",al={"nächste quest nach neeru","was macht neeru","questreihe nach neeru"}},{q="Warum erlaubt die Horde Hexenmeister in Orgrimmar?",a="Thrall erlaubt Hexenmeister in Orgrimmar aus praktischer Notwendigkeit. Er hält sie in der Kluft der Schatten, wo ihre gefährlichen Forschungen überwacht, kontrolliert und bisweilen zum Verständnis dämonischer Feinde genutzt werden können.",al={"warum sind hexenmeister erlaubt","hexenmeister in der kluft der schatten","thrall hexenmeister"}}},fx={["273c9fa7"]={q="Warum schickt Margoz Euch, anstatt selbst zu gehen?",a="Margoz bleibt außerhalb von Klingenhügel stationiert, um über die spirituellen Unruhen in Durotar zu wachen. Ihr seid der Abenteurer, der die Senghalsbänder aus Die Knochenhöhle geborgen hat, was Eure Fähigkeit im Umgang mit den dunklen Artefakten des Kults beweist. Da er ihre dämonischen Machenschaften nicht allein durch Schamanismus ergründen kann, verlässt er sich darauf, dass Ihr schnell ein Exemplar zu Die Kluft bringt.",al={"warum ich margoz","warum zu neeru geschickt","warum geht margoz nicht nach orgrimmar"}}},fp="15,210,17.276.0,24.342.0,37.237.0,33.121.0,31.198.0,27.167.0,46.147.0,47.205.0"}
P.entries["quest:83"] = {n="Feine Leinenwaren",s="Im Holzfällerlager des Osttals braucht Sara Roderwald Leinen für ihre Schneiderei. Sie bittet Euch, Kopftücher von Defias-Banditen zu beschaffen, damit sie weiterhin Waren für Reisende herstellen kann.",h="Im Holzfällerlager des Osttals braucht Sara Roderwald Leinen für ihre Schneiderei.",kw={"sackleinen","bruderschaft der defias","holzfällerlager des osttals","wald von elwynn","rotes leinenkopftuch","feine leinenwaren","sara roderwald","schneiderei"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr die Bruderschaft der Defias in Elwynn schwächen und zugleich nützlichen Stoff nach Eastvale bringen.",["profession:Tailoring"]="Als Schneider wisst Ihr, wie Stoffmangel eine Schneiderin dazu bringen kann, Stoff aus der Kleidung von Banditen zu gewinnen."},sec={{t="Banditen und Sackleinen",b="In ganz Elwynn tragen Defias-Banditen rote Leinenkopftücher. Ihre weniger organisierten Kumpane in Nordhain begnügen sich mit billigen Sackleinenmasken. Das Leinen liefert Sara brauchbaren Stoff für ihre Schneiderei."},{t="Stoffbergung am Lager",b="Im Holzfällerlager des Osttals braucht Sara Roderwald Textilien für ihr Handwerk. Kopftücher aus den über die Wälder verstreuten Lagern der Defias versorgen sie mit Stoff und helfen, das Vordringen der Banditen einzudämmen."}},faq={{q="Wer bietet die Aufgabe Feine Leinenwaren an?",a="Sara Roderwald, eine Schneiderin im Holzfällerlager des Osttals im östlichen Wald von Elwynn, bittet Euch, ihr Stoff zu bringen.",al={"wer vergibt feine leinenwaren","feine leinenwaren auftraggeber","sara roderwald aufgabe"}},{q="Welche Gegenstände werden für Feine Leinenwaren benötigt?",a="Ihr braucht sechs Rote Leinenkopftücher von Mitgliedern der Defias-Bande, die im ganzen Wald von Elwynn verstreut sind.",al={"was für feine leinenwaren sammeln","gegenstände für feine leinenwaren","benötigte kopftücher"}},{q="Wo finde ich Defias-Banditen im Wald von Elwynn?",a="Gesetzlose der Defias lagern im ganzen Wald von Elwynn, darunter bei Brackbrunns Kürbisbeet, beim Hof der Steinfelds und in den Wäldern um Jerods Anlegestelle.",al={"defias fundorte elwynn","wo sind defias-lager","wo rote kopftücher bekommen"}},{q="Warum tragen die Defias in Elwynn Leinen statt Sackleinen?",a="Niederrangige Defias in Nordhain tragen Sackleinenmasken, während besser ausgerüstete Mitglieder in ganz Elwynn rotes Leinen tragen. Die Kopftücher zeugen von der besseren Organisation und Versorgung der Bruderschaft.",al={"warum rotes leinen","sackleinen gegen leinen defias","defias maskenmaterial"}},{q="Warum will Sara Roderwald die Kopftücher der Banditen?",a="Sara Roderwald braucht Stoff für ihre Schneiderei. Sie verwendet das Leinen aus Defias-Masken wieder, um praktische Waren für Waldarbeiter und Reisende im Holzfällerlager zu nähen.",al={"warum kopftücher sammeln","was macht sara mit masken"}},{q="Wo liegt das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt ganz im Osten des Waldes von Elwynn, unmittelbar nördlich der Hauptstraße zur Brücke ins Rotkammgebirge.",al={"eastvale lage","wo liegt eastvale","wie sara roderwald finden"}}},fx={["18a4a024"]={q="Wofür wird das Rotes Leinenkopftuch verwendet?",a="Die Rotes Leinenkopftuch werden als Masken von Banditen der Bruderschaft der Defias getragen, die im gesamten Wald von Elwynn umherstreifen. Während die Schurken in Nordhain sich mit grober Sackleinen behelfen, tragen die Diebe im weiteren Wald besserwertigen Stoff. Sara Timberwald trennt diese erbeuteten Masken auf und webt sie neu, um brauchbare Leinenkleidung herzustellen.",al={"wofür rotes leinenkopftuch","rotes leinenkopftuch verwendung","warum rotes leinenkopftuch"}},["8ac6c8ef"]={q="Warum sind Defias-Banditen im Wald von Elwynn?",a="Die Bruderschaft der Defias hat Lager im gesamten Wald von Elwynn errichtet, um Reisende zu belästigen, Versorgungswege auszurauben und die Autorität von Sturmwind zu untergraben. Ihre wachsende Präsenz bedroht lokale Siedlungen wie das Holzfällerlager des Osttals und nutzt die überlasteten Wachen des Königreichs aus, um ihre gesetzlosen Aktivitäten direkt vor den Toren der Hauptstadt auszuweiten.",al={"defias im wald von elwynn","warum sind defias hier","bruderschaft der defias wald von elwynn"}},fea06053={q="Warum braucht Sara Timberwald Euch anstelle der Wachen?",a="Sara Timberwald ist eine Schneiderin im Holzfällerlager des Osttals, keine Soldatin, und ihr fehlen die Mittel, um selbst gegen Gesetzlose zu kämpfen. Sturmwinds Wachen und die örtliche Garnison sind bereits überlastet damit, die weit verbreiteten Einfälle der Defias und Gnollüberfälle einzudämmen, was die einfachen Handwerker dazu zwingt, sich auf vorbeiziehende Abenteurer für Materialien und Schutz zu verlassen.",al={"warum mich fragen sara","warum nicht elwynn wachen","warum braucht timberwald hilfe"}}},fp="15,169,18.181.0,19.200.0,37.109.0,42.92.0,49.138.0,54.180.0,46.153.0,43.127.0"}
P.entries["quest:830"] = {n="Die Befehle des Admirals",s="An Durotars Küste künden die Befehle des Admirals von einer Bedrohung für die junge Horde. Versiegelt vom verstorbenen Großadmiral Daelin Prachtmeer, zeigen sie, dass die Garnison der Kul Tiraner organisiert und fest verschanzt ist. Gar'Thok in Klingenhügel muss ihren Inhalt erfahren.",h="An Durotars Küste künden die Befehle des Admirals von einer Bedrohung für die junge Horde.",kw={"befehle des admirals","vergilbter umschlag","daelin prachtmeer","gar'thok","kul tiras","lieutenant benedict","klingenhügel","burg tiragarde"},ang={["faction:Horde"]="Prachtmeers Befehle zeigen, dass die Präsenz der Allianz an Durotars Küsten Teil eines organisierten Vernichtungsfeldzugs war. Die Horde muss ihre neue Heimat mit Bedacht verteidigen.",["race:Orc"]="Für Orcs, die sich in Durotar eine Zukunft aufbauen, erinnern diese Papiere an Daelin Prachtmeers Hass und die verbliebenen Truppen, die sie weiterhin vernichten wollen."},sec={{t="Ein versiegeltes Vermächtnis",b="In den oberen Stockwerken von Burg Tiragarde liegt ein vergilbter Umschlag in einer schweren Truhe unter Lieutenant Benedicts Aufsicht. Großadmiral Daelin Prachtmeer versiegelte ihn mit seinem Wappen. Sein Pergament enthält Marinebefehle aus der Zeit von Kul Tiras' blutiger Invasion Durotars. Obwohl der Großadmiral bei Theramore fiel, halten seine Offiziere noch immer ihre Befestigungen und klammern sich an ihren Auftrag gegen die Siedlung der Horde."},{t="Alarm in Klingenhügel",b="Gar'Thok befehligt die örtlichen Verteidigungstruppen von Klingenhügel. Wenn Ihr ihm die geborgenen Papiere bringt, bestätigen sie, dass die Soldaten der Kul Tiraner an der Ostküste eine etablierte Streitmacht sind, die auf Verstärkung wartet. Sie sind keine bloßen Schiffbrüchigen. Gar'Thok erkennt, dass Durotars Überleben davon abhängt, die Befehlsstruktur von Tiragarde zu zerschlagen."}},faq={{q="Wo sind die Befehle des Admirals zu finden?",a="Die Befehle liegen in einem vergilbten Umschlag in einer verschlossenen Truhe im dritten Stock von Burg Tiragarde. Lieutenant Benedict bewacht den zweiten Stock und trägt den Schlüssel bei sich.",al={"fundort der befehle","wo ist der vergilbte umschlag","befehle des admirals finden"}},{q="Wer war Admiral Prachtmeer?",a="Großadmiral Daelin Prachtmeer herrschte über Kul Tiras und befehligte im Zweiten Krieg die Flotte der Allianz. Er weigerte sich zu glauben, dass Orcs in Frieden leben könnten, und segelte deshalb nach Kalimdor, um einen Vernichtungskrieg gegen Durotar zu führen. Er starb bei Theramore.",al={"wer ist der admiral","daelin prachtmeer geschichte","wer erteilte die befehle"}},{q="Warum sind noch immer Soldaten der Kul Tiraner in Burg Tiragarde?",a="Daelin Prachtmeer errichtete während seiner Invasion Durotars befestigte Stützpunkte an der Küste, darunter Burg Tiragarde. Nach seiner Niederlage hielten überlebende Offiziere und Marinesoldaten unter Lieutenant Benedict ihre Stellungen und setzten seinen Feldzug gegen die Horde fort.",al={"warum sind menschen in durotar","soldaten der burg tiragarde","kul tiras in durotar"}},{q="Warum beunruhigen diese Befehle Gar'Thok so sehr?",a="Gar'Thok befehligt Klingenhügel und schützt das zentrale Durotar. Die Befehle zeigen, dass Burg Tiragarde eine aktive, gezielte militärische Bedrohung für die Heimat der Orcs darstellt und keine Bande gestrandeter Überlebender beherbergt.",al={"gar'thoks reaktion","warum ist es gar'thok wichtig"}},{q="Wer hat den Schlüssel zur Truhe des Admirals?",a="Lieutenant Benedict, der Offizier der Kul Tiraner mit dem Kommando im zweiten Stock von Burg Tiragarde, trägt den Schlüssel zur Geldkassette mit dem vergilbten Umschlag.",al={"benedicts schlüssel","wer lässt den schlüssel fallen"}},{q="Was geschieht, nachdem Ihr Gar'Thok die Befehle übergeben habt?",a="Gar'Thok erkennt, dass Prachtmeers Pläne vor dessen Tod entstanden und noch mehr seiner Männer an Durotars Küsten landen könnten. Er schickt die Befehle sofort nach Orgrimmar, damit der Rat des Kriegshäuptlings gewarnt werden kann.",al={"befehle des admirals fortsetzung","nächste quest"}}},fp="20,262,15.398.0,19.327.1,37.156.0,27.252.0,51.244.0,48.191.0,41.146.0,49.204.0"}
P.entries["quest:831"] = {n="The Admiral's Orders",s="Gar'Thok schickt Euch, um Admiral Prachtmeers Befehle zu Nazgrel nach Orgrimmar zu bringen. Die Befehle schüren die Sorge vor einer weiteren Landung der Menschen an den Küsten der Horde.",h="Gar'Thok schickt Euch, um Admiral Prachtmeers Befehle zu Nazgrel nach Orgrimmar zu bringen.",kw={"admiral prachtmeer","gar'thok","horde","landung der menschen","nazgrel","befehle","orgrimmar","thrall"},ang={["faction:Horde"]="Als Mitglied der Horde überbringt Ihr eine Warnung, die Gar'Thok für die Sicherheit der Küsten der Horde als wichtig erachtet."},sec={{t="Eine Warnung für Nazgrel",b="Gar'Thok in Durotar fürchtet, dass Admiral Prachtmeers Pläne die Horde weiterhin bedrohen. Er schickt Euch mit Admiral Prachtmeers Befehlen zu Nazgrel in Thralls Gemach in Orgrimmar."},{t="In Thralls Gemach",b="Nazgrel nimmt die Befehle entgegen und sagt, der Kriegshäuptling müsse sofort davon erfahren. Er dankt Euch dafür, der Horde ehrenhaft gedient zu haben, und wendet sich dann an Thrall, um ihn zu beraten."}},faq={{q="Wer schickt mich nach Orgrimmar?",a="Gar'Thok schickt Euch aus Durotar, um Admiral Prachtmeers Befehle Nazgrel zu überbringen.",al={"wer hat mir das gegeben","befehle von gar'thok"}},{q="Wer soll die Befehle erhalten?",a="Nazgrel soll Admiral Prachtmeers Befehle in Thralls Gemach in Orgrimmar erhalten.",al={"wem überbringen","befehle für nazgrel"}},{q="Warum sind die Befehle dringend?",a="Gar'Thok fürchtet, dass Admiral Prachtmeers Pläne weitere seiner Männer an die Küsten der Horde bringen könnten.",al={"warum dringend","bedrohung durch menschen"}},{q="Was tut Nazgrel mit der Warnung?",a="Nazgrel sagt, er müsse Thrall in dieser Angelegenheit beraten.",al={"was tut nazgrel","thrall beraten"}}},fp="20,145,21.167.0,19.159.1,26.82.0,30.83.0,26.89.0,38.53.0"}
P.entries["quest:8311"] = {n="Schlotternachtssüßigkeiten für Jesper!",s="Während der Schlotternächte liegt Jesper krank in Sturmwind und sehnt sich nach Süßigkeiten und Spaß außerhalb des Waisenhauses. Zu krank, um hinauszugehen, bittet er Abenteurer der Allianz, Süßigkeiten für ihn zu sammeln.",h="Während der Schlotternächte liegt Jesper krank in Sturmwind und sehnt sich nach Süßigkeiten und Spaß...",kw={"darnassus","kaugummikugel","schlotternächte","eisenschmiede","jesper","marzipan","nachtigall","nugat","sturmwind","talvash","süßes oder saures"},ang={["faction:Alliance"]="Für die Allianz bringen die Schlotternächte weit entfernte Hauptstädte zusammen. Ihr reist von Sturmwinds prächtigen Straßen zu Eisenschmiedes Berghallen und den Zweigen von Darnassus, um einem Waisenkind Freude zu bringen.",["race:Gnome"]="Als Gnom habt Ihr Eure Heimat an Troggs und Strahlung verloren. In Eisenschmiede sorgt Talvash del Kissel dafür, dass Kaugummikugeln aus Gnomeregan Teil des Festes bleiben."},sec={{t="Ein behütetes Kind",b="Jesper liegt während der Schlotternächte krank im Waisenhaus von Sturmwind am Kathedralenplatz. Während die Kinder in ganz Azeroth Süßigkeiten sammeln, muss er drinnen bleiben. So hofft er, dass vorbeikommende Abenteurer die Festtagsfreude teilen und ihm Leckereien bringen."},{t="Kunststücke für Süßigkeiten in der Allianz",b="Um Jesper die erhofften Süßigkeiten zu bringen, reist Ihr über den Wald von Elwynn hinaus. Ihr besucht die Gastwirte von Sturmwind, Eisenschmiede und Darnassus, dann den verbannten Gnom Talvash del Kissel. Jeder verlangt eine Darbietung, bevor er Euch eine Leckerei gibt. Ihr gackert wie ein Huhn, tanzt, lasst Eure Muskeln spielen oder tuckert wie eine Eisenbahn und verdient regionale Süßigkeiten wie Nugat aus Sturmwind und Kaugummikugeln aus Gnomeregan."}},faq={{q="Wer ist Jesper?",a="Jesper ist ein kleiner Waisenjunge im Waisenhaus von Sturmwind. Während der Schlotternächte ist er krank und sehnt sich nach Festtagssüßigkeiten, kann sie aber nicht selbst sammeln.",al={"jesper sturmwind","waisenjunge jesper","wer ist jesper"}},{q="Warum kann Jesper nicht selbst Süßigkeiten sammeln gehen?",a="Jesper ist krank und muss im Waisenhaus bleiben, während der Rest der Stadt die Schlotternächte feiert.",al={"warum kann jesper nicht hinaus","ist jesper krank","jesper süßes oder saures"}},{q="Welche Leckereien möchte Jesper?",a="Jesper bittet um vier regionale Süßigkeiten: Nugat aus Sturmwind, Eisenschmiede Mints, Marzipan aus Darnassus und Kaugummikugeln aus Gnomeregan.",al={"jesper leckereien","schlotternächte süßigkeitenliste","jesper benötigte süßigkeiten"}},{q="Wo bekommt Ihr die Kaugummikugel aus Gnomeregan?",a="Talvash del Kissel verteilt Kaugummikugeln aus Gnomeregan, während er sich im Mystic Ward von Eisenschmiede aufhält.",al={"kaugummikugel aus gnomeregan fundort","wer gibt kaugummikugeln","talvash süßigkeiten"}},{q="Welche Kunststücke verlangen die Gastwirte von Euch?",a="Die Gastwirte verlangen, dass Ihr in Sturmwind Eure Muskeln spielen lasst, in Darnassus tanzt, in Eisenschmiede wie ein Huhn gackert und für Talvash eine Eisenbahn nachahmt.",al={"schlotternächte kunststücke","gastwirt kunststücke","kunststücke für süßigkeiten allianz"}},{q="Was gibt Euch Jesper für die Süßigkeiten?",a="Nachdem er alle vier Festtagssüßigkeiten erhalten hat, gibt Euch Jesper einige Kürbisleckereien, die er aufbewahrt hat.",al={"jesper belohnung","leckereien für jesper abschluss"}}},fx={["103fae29"]={q="Warum will Jesper, dass die Leckereien für Schlotternächte gesammelt werden?",a="Jesper ist ein krankes Waisenkind, das im Waisenhaus von Sturmwind unter der wachsamen Aufsicht von Matron Nightingale untergebracht ist, weshalb er nicht an den Feierlichkeiten zu Schlotternächte in den Hauptstädten der Allianz teilnehmen kann. Um das Fest wie jedes andere Kind zu erleben, hofft er, die festlichen Süßigkeiten zu kosten, die für jede Hauptstadt der Allianz einzigartig sind, und bietet im Tausch seine eigenen Kürbisleckereien an, damit er nicht ganz leer ausgeht.",al={"warum will jesper leckereien","jesper motivation süßigkeiten","warum schlotternächte leckereien jesper"}},["423b280b"]={q="Wofür ist das Nugat aus Sturmwind?",a="Nugat aus Sturmwind ist eine traditionelle lokale Süßware, die während Schlotternächte vom Gastwirt im Handelsdistrikt verteilt wird. Es repräsentiert den Beitrag des Menschenkönigreichs zu den Festtagsleckereien, die Jesper von Euch sammeln lässt, und wird verdient, indem Ihr dem Gastwirt Eure Stärke beweist.",al={"nugat aus sturmwind verwendung","was ist nugat aus sturmwind","wer will nugat aus sturmwind"}},["37e1df8a"]={q="Wofür ist die Kaugummikugel aus Gnomeregan?",a="Die Kaugummikugel aus Gnomeregan ist eine typische Süßigkeit, die im Namen der verbannten Gnome von Talvash del Kissel in Eisenschmiede verteilt wird. Sie ist eine der vier einzigartigen Süßigkeiten, die Jesper von Euch sammeln lässt, damit er die Festtagsleckereien aller Völker der Allianz probieren kann.",al={"kaugummikugel aus gnomeregan verwendung","was ist kaugummikugel aus gnomeregan","wer will kaugummikugel aus gnomeregan"}},e8e502ad={q="Wofür ist das Pfefferminzbonbon aus Eisenschmiede?",a="Das Pfefferminzbonbon aus Eisenschmiede ist eine zwergische Süßigkeit, die während des Herbstfestes vom Gastwirt von Eisenschmiede verschenkt wird. Jesper benötigt es als Teil seiner vollständigen Vier-Städte-Sammlung von Schlotternächte-Süßigkeiten, die vergeben wird, nachdem der Gastwirt mit einer schwungvollen Hühnerdarstellung amüsiert wurde.",al={"pfefferminzbonbon aus eisenschmiede verwendung","was ist pfefferminzbonbon aus eisenschmiede","wer will pfefferminzbonbon aus eisenschmiede"}},["61787ad3"]={q="Wofür ist das Marzipan aus Darnassus?",a="Marzipan aus Darnassus ist eine exquisite Nachtelfen-Süßigkeit, die vom Gastwirt der Terrasse der Handwerker in Darnassus verteilt wird. Es vervollständigt das Sortiment regionaler Köstlichkeiten zu Schlotternächte, die Jesper so gerne genießen möchte, während er im Waisenhaus von Sturmwind festsitzt.",al={"marzipan aus darnassus verwendung","was ist marzipan aus darnassus","wer will marzipan aus darnassus"}}},fp="31,175,17.236.0,37.367.0,14.135.0,46.101.0,30.117.0,43.90.0,47.135.0,50.92.0"}
P.entries["quest:8312"] = {n="Schlotternachtssüßigkeiten für Spoops!",s="Bei „Schlotternachtssüßigkeiten für Spoops!“ bittet ein krankes Kind Reisende, festliche Süßigkeiten zu sammeln. Gastwirte in den Städten und Kali Remik in Sen'jin verteilen Leckereien, und Spoops bietet dafür magische Süßigkeiten an.",h="Bei „Schlotternachtssüßigkeiten für Spoops!“ bittet ein krankes Kind Reisende, festliche Süßigkeiten zu...",kw={"süßigkeiten","schlotternächte","gastwirt","kali remik","sen'jin","spoops","leckereien","süßes oder saures"},ang={["faction:Horde"]="Als Reisende der Horde sammelt Ihr für ein krankes Kind Leckereien in den großen Städten und besucht Sen'jin, die Siedlung der Dunkelspeere.",["race:Troll"]="Als Dunkelspeertroll könnt Ihr Kali Remik während der Schlotternächte in Sen'jin finden, wo es festliche Süßigkeiten gibt."},sec={{t="Ein Fest im Krankenbett",b="Spoops ist zu krank, um die Schlotternächte im Freien zu feiern. Während andere feiern, bittet Spoops Reisende, festliche Leckereien zu sammeln. Dafür bietet Spoops Süßigkeiten an, die alle, die sie essen, in seltsame Gestalten verwandeln."},{t="Süßes und Saures im Reich",b="Reisende können in Siedlungen im ganzen Reich festliche Leckereien finden. Gastwirte in großen Städten bitten Besucher, Kunststücke vorzuführen, bevor sie ihre Süßigkeiten verteilen. Auch Kali Remik verteilt Leckereien in Sen'jin an der Küste von Durotar."}},faq={{q="Wer ist Spoops?",a="Spoops ist ein junges, krankes Wesen, das während der Schlotternächte nicht um Süßes oder Saures ziehen kann. Um dennoch teilzuhaben, bittet Spoops Reisende, bei Gastwirten und Händlern auf der ganzen Welt festliche Leckereien zu sammeln.",al={"wer ist spoops","spoops","was ist spoops"}},{q="Warum kann Spoops nicht um Süßes oder Saures ziehen?",a="Spoops ist zu krank, um während der Schlotternächte nach draußen zu gehen. Ans Krankenbett gefesselt, ist Spoops auf Reisende angewiesen, die Gastwirte in den Städten besuchen und festliche Süßigkeiten sammeln.",al={"warum kann spoops nicht um süßes oder saures ziehen","warum bleibt spoops drinnen","spoops krank"}},{q="Welche Süßigkeiten bietet Spoops im Tausch an?",a="Spoops bietet magische Süßigkeiten an, die alle verwandeln, die sie essen. Sie können Euch in Gestalten verwandeln, die zugleich lustig und furchterregend sind.",al={"welche süßigkeiten gibt spoops","spoops belohnung süßigkeiten","besondere süßigkeiten"}},{q="Wo findet Ihr die Leckereien für Spoops?",a="Gastwirte in den Hauptstädten verteilen festliche Süßigkeiten, nachdem Reisende Kunststücke vorgeführt haben. Auch Kali Remik verteilt Süßigkeiten in Sen'jin.",al={"wo gibt es süßigkeiten","wer verteilt leckereien","fundorte für süßigkeiten"}},{q="Wer ist Kali Remik?",a="Kali Remik ist ein Troll in Sen'jin in Durotar. Während der Schlotternächte verteilt Kali Remik festliche Süßigkeiten an Reisende, die vorbeikommen.",al={"wer ist kali remik","kali remik süßigkeiten","sen'jin süßigkeiten"}},{q="Warum verlangen Gastwirte Kunststücke?",a="Während der Schlotternächte bitten Gastwirte in größeren Siedlungen Besucher, mit albernen Kunststücken oder Gesten ihre Festtagsstimmung zu zeigen, bevor sie ihre Süßigkeiten verteilen.",al={"was wollen gastwirte","gastwirt kunststücke","wie bekommt man süßigkeiten vom gastwirt"}}},fp="31,209,19.201.0,34.230.0,14.198.0,38.150.0,41.130.0,40.137.0,18.128.0,33.153.0"}
P.entries["quest:832"] = {n="Brennende Schatten",s="In der Knochenhöhle übermittelt das Auge des brennenden Schatten Warnungen der Burning Blade. Seine Stimme droht Gazz'uz mit Neeru Fireblades Zorn.",h="In der Knochenhöhle übermittelt das Auge des brennenden Schatten Warnungen der Burning Blade.",kw={"burning blade","brennende schatten","die kluft der schatten","durotar","auge des brennenden schatten","gazz'uz","neeru fireblade","orgrimmar","die knochenhöhle"},ang={["class:Warlock"]="Als Hexenmeister in der Ausbildung in der Kluft der Schatten hört Ihr, wie die Burning Blade den Namen eines anderen Praktizierenden anruft. Die Drohung zeigt, wie schmal der Grat zwischen staatlich gebilligtem Studium der Teufelsmagie und offenem Verrat ist.",["faction:Horde"]="Als Mitglied der Horde deckt Ihr Geflüster zwischen Kultisten unmittelbar vor den Toren der Hauptstadt auf. Die dämonische Verderbnis der Old Horde schwelt noch immer beunruhigend nahe am Herzen Durotars.",["race:Orc"]="Als Orc wisst Ihr, dass die Anwesenheit der Burning Blade in Durotar Eure neue Heimat entweiht. Orcs kämpften an Thralls Seite, um den Makel der Legion zu tilgen."},sec={{t="Eine Stimme im Stein",b="Nachdem Gazz'uz tief in der Knochenhöhle fällt, wird das Auge des brennenden Schatten unter seinen Überresten gefunden. Der Stein trägt eine Stimme in den Geist eines jeden, der ihn hält. Der Sprecher verlangt einen Bericht von Gazz'uz. Seine geheime Arbeit östlich von Orgrimmar ist aufgeflogen."},{t="Eine seltsame Drohung",b="Die Stimme stellt Gazz'uz ein Ultimatum. Er soll antworten, sonst wird Neeru Feuerklinge angewiesen, ihn mit rascher Brutalität zur Strecke zu bringen. Neeru lebt offen in Orgrimmars Kluft der Schatten, wo er unter Thralls strenger Aufsicht dunkle Künste praktiziert. Als der Anhänger ihn erreicht, täuscht der Hexenmeister Überraschung vor und fragt sich, warum der Kult seinen Namen benutzte, um Gazz'uz einzuschüchtern."}},faq={{q="Was ist das Auge des brennenden Schatten?",a="Das Auge des brennenden Schatten ist ein verzauberter Anhänger, der unter den Überresten des Burning Blade-Anführers Gazz'uz in der Knochenhöhle gefunden wird. Es übermittelt telepathische Nachrichten in beide Richtungen zwischen Kultagenten und ihren unsichtbaren Meistern.",al={"auge des brennenden schatten","was ist dieser anhänger","gazz'uz auge"}},{q="Wer spricht durch den Anhänger?",a="Ein unbekannter Vorgesetzter aus der Hierarchie von Shadow Council oder Burning Blade versucht, Gazz'uz zu erreichen, ohne zu wissen, dass er bereits in der Knochenhöhle erschlagen wurde.",al={"wer hat zu mir gesprochen","stimme im anhänger","wer spricht durch das auge"}},{q="Warum droht die Stimme Gazz'uz mit Neeru Feuerklinge?",a="Die Stimme sagt, Neeru Feuerklinge werde Gazz'uz mit brutaler Gewalt nachstellen, wenn er keinen Bericht erstattet. Neeru sagt, er sei dafür bekannt, die Feinde des Kriegshäuptlings zu jagen, findet es jedoch seltsam, dass die Stimme ausgerechnet ihn nannte.",al={"warum neeru erwähnen","neeru fireblade drohung","neeru verbindung"}},{q="Wohin bringe ich das Auge des brennenden Schatten?",a="Bringt den Anhänger zu Neeru Feuerklinge in Orgrimmars Kluft der Schatten, wo er sich über Kessel und Folianten beugt.",al={"wo brennende schatten abgeben","wo ist neeru fireblade"}},{q="Wie reagiert Neeru Feuerklinge, wenn er das Auge erhält?",a="Neeru findet es bemerkenswert, dass die Stimme ausgerechnet seinen Namen nannte, und noch seltsamer, dass die Kultisten der Burning Blade einen Namen tragen, der seinem eigenen so ähnelt. Er behält den Anhänger, um ihn zu untersuchen und über seine Botschaft nachzudenken.",al={"neerus reaktion","was sagt neeru"}},{q="Wo befindet sich Gazz'uz?",a="Gazz'uz lauert am tiefsten Punkt der Knochenhöhle, einer Höhle zwischen den Felsen an Durotars Ostküste, unmittelbar östlich von Orgrimmar.",al={"wo ist gazz'uz","gazz'uz aufenthaltsort","knochenhöhle boss"}}},fx={["286b7c01"]={q="Warum will die Stimme im Auge des brennenden Schatten einen Bericht?",a="Die Stimme, die durch den Anhänger flüstert, versucht Kontakt mit Gazz'uz aufzunehmen, einem Anführer der Burning Blade in Die Knochenhöhle. Die Nachricht, dass ihre verborgene Enklave von der Horde entdeckt wurde, hat die Hierarchie des Kults erreicht, und der unsichtbare Befehlshaber drängt darauf, Gazz'uz zu sammeln, um Verteidigungsmaßnahmen vorzubereiten, bevor ein unvermeidlicher Angriff ihren Stützpunkt vernichtet.",al={"warum spricht der anhänger","warum auge des brennenden schatten bericht","auge des brennenden schatten stimme motiv"}}},fp="15,139,20.260.0,16.347.1,34.212.0,36.152.0,57.213.0,42.109.0,50.205.1,25.137.0"}
P.entries["quest:833"] = {n="Eine heilige Bestattung",s="Bei den Teufelsfelsen im östlichen Mulgore ruft Hüter des Wissens Raintotem Abenteurer der Horde dazu auf, die heiligen Begräbnisstätten zu schützen. Bristleback-Stacheleber haben die Gräber jener Taurenkrieger überrannt, die bei der Gründung und Verteidigung von Donnerfels ihr Leben gaben.",h="Bei den Teufelsfelsen im östlichen Mulgore ruft Hüter des Wissens Raintotem Abenteurer der Horde dazu auf...",kw={"eine heilige bestattung","ahnen","bristleback-eindringling","hüter des wissens raintotem","mulgore","stacheleber","teufelsfelsen","donnerfels"},ang={["class:Shaman"]="Als Schamane schreitet Ihr gegen die Schändung heiliger Stätten ein, die die Geister der geehrten Ahnen aufwühlt und Euer Eingreifen nötig macht.",["faction:Horde"]="Als Mitglied der Horde helft Ihr den Taurenältesten, ihre heiligen Denkmäler zu sichern und das Versprechen der Horde einzulösen, Mulgore an der Seite ihrer Verbündeten zu verteidigen.",["race:Tauren"]="Als Tauren helft Ihr, die Ruhe der Teufelsfelsen zu bewahren und die Ahnen zu ehren, die die vereinte Heimat Eures Volkes ermöglichten."},sec={{t="Heiliger Boden der Shu'halo",b="Die Teufelsfelsen zählen zu Mulg ores ehrwürdigsten Heiligtümern und liegen in den zerklüfteten Felsen unterhalb der östlichen Berge. Nur die tapfersten Tauren werden dort zur letzten Ruhe gebettet. Diese legendären Krieger vergossen ihr Blut, um ihre Stämme und Häuptlinge zu schützen und auf den Tafelbergen von Donnerfels eine dauerhafte Heimat zu schaffen. Für die Shu'halo ist jede Störung ihrer Ruhe ein Frevel an der Tradition und an der Erdenmutter."},{t="Die Schändung durch die Bristlebacks",b="Die nomadischen Stacheleber des Bristleback-Stammes machen den Tauren die Herrschaft über das zentrale Kalimdor schon lange streitig. Ihr jüngstes Vordringen in die Teufelsfelsen ist eine ernste Eskalation. Banden von Bristleback-Eindringlingen haben sich auf die heiligen Stätten geschlichen, verwüsten die Erde und stören die Ruhestätten. Hüter des Wissens Raintotem ist zu alt, um sie allein zu vertreiben, weshalb junge Streiter der Horde zu den Waffen greifen und die geehrten Toten verteidigen müssen."}},faq={{q="Was sind die Teufelsfelsen?",a="Die Teufelsfelsen sind ein heiliger Ahnenfriedhof entlang der östlichen Berge Mulg ores. Er ist den tapfersten Taurenkriegern vorbehalten, besonders jenen, die beim Schutz ihrer Stämme und bei der Gründung von Donnerfels starben.",al={"wo sind die teufelsfelsen","teufelsfelsen mulgore","begräbnisstätte der tauren"}},{q="Wer ist Hüter des Wissens Raintotem?",a="Hüter des Wissens Raintotem ist ein Taurenältester, der die Teufelsfelsen pflegt und schützt. Da seine besten Jahre vorüber sind und er die Bristlebacks nicht allein zurückschlagen kann, ruft er fähige Abenteurer dazu auf, die Toten zu verteidigen.",al={"raintotem","hüter des wissens raintotem","wer vergibt eine heilige bestattung"}},{q="Warum sind die Bristleback-Stacheleber bei den Teufelsfelsen?",a="Der Bristleback-Stamm drängt in ganz Mulgore und im Brachland gegen das Gebiet der Tauren vor. Auf der Suche nach Land und Rohstoffen sind Banden von Eindringlingen in die zerklüfteten Teufelsfelsen vorgedrungen und haben die Gräber geschändet.",al={"warum sind stacheleber bei den teufelsfelsen","bristleback-eindringlinge","invasion der stacheleber"}},{q="Warum empfinden die Tauren diese Schändung als so verletzend?",a="Tauren ehren ihre Ahnen und suchen das Gleichgewicht mit den Geistern der Gefallenen. Wenn Stacheleber die Erde verwüsten und die Gebeine der Helden stören, die für Donnerfels starben, trifft dieser Frevel die Tauren tief in ihrem Glauben.",al={"bestattungsbräuche der tauren","warum sind bestattungen den tauren wichtig"}},{q="Wohin führt diese Quest als Nächstes?",a="Eine heilige Bestattung ist eine Verteidigungsaufgabe, die Hüter des Wissens Raintotem vergibt. Sobald die Bristleback-Eindringlinge bezwungen sind, ist die unmittelbare Schändung gestoppt.",al={"eine heilige bestattung folgequest","was kommt nach eine heilige bestattung"}},{q="Wer liegt bei den Teufelsfelsen begraben?",a="Die Teufelsfelsen sind den Helden der Tauren vorbehalten, die für das Überleben ihrer Stämme und Häuptlinge kämpften. Ihre Opfer ermöglichten die Gründung und Verteidigung von Donnerfels.",al={"wer liegt hier begraben","teufelsfelsen gräber"}}},fx={e11b84bd={q="Warum fragt Hüter des Wissens Raintotem Euch, anstatt sie selbst zu vertreiben?",a="Hüter des Wissens Raintotem ist ein Ältester, der einfach zu alt ist und seine besten Jahre hinter sich hat, um zu den Waffen gegen eine gewalttätige Kriegerbande zu greifen. Da er damit betraut ist, die Geister der Teufelsfelsen zu pflegen und zu ehren, anstatt an der Front zu kämpfen, verlässt er sich auf fähige Reisende wie Euch, um mit der körperlichen Gefahr fertig zu werden, die Borstenrücken-Eindringlinge zu vertreiben.",al={"warum kann raintotem das nicht tun","warum braucht raintotem hilfe","warum kämpft raintotem nicht"}}},fp="15,241,31.385.0,27.398.0,18.206.0,28.186.0,46.201.0,51.200.0,32.154.0,27.180.0"}
P.entries["quest:834"] = {n="Wind in der Wüste",s="Rezlak wartet in Durotar auf eine gestohlene Versorgungskarawane. Staubwindharpyien überfielen sie in der Klingenschlucht und verstreuten die Baumaterialien zwischen den Klippen.",h="Rezlak wartet in Durotar auf eine gestohlene Versorgungskarawane.",kw={"karawane","durotar","staubwindharpyien","gazlowe","orgrimmar","ratschet","klingenschlucht","rezlak","vorräte"},ang={["faction:Horde"]="Jede Lieferung, die den Bestien der Schlucht zum Opfer fällt, gefährdet die rasche Expansion der Horde und die Befestigung ihrer Hochburg in Durotar.",["profession:Engineering"]="Als Ingenieur könnt Ihr verstehen, warum Rezlak solide Pläne und pünktliche Lieferungen schätzt, selbst wenn die heimische Tierwelt Schwierigkeiten bereitet.",["race:Orc"]="Als Orc verlasst Ihr Euch auf das Geschick der Goblins und Vorräte aus der Fremde, um Durotars rauen, trockenen Boden zu einer befestigten Heimat zu machen."},sec={{t="Ein Goblin unter Zeitdruck",b="Rezlak kam auf Befehl von Chefingenieur Gazlowe aus Ratschet, um der Horde beim Bauen in ganz Durotar zu helfen. Das raue, karge Land macht den Bau von Befestigungen schon schwer genug. Nun verschwinden Lieferungen, bevor sie die Baustellen erreichen, und ohne die Fracht steht die Arbeit still. Der reizbare Goblin-Bauleiter hat nichts, womit er bauen kann."},{t="Überfall in der Schlucht",b="Staubwindharpyien überfielen den letzten Versorgungstransport in der Klingenschlucht. Sie nisten in den hohen Schluchten neben der Straße von Klingenhügel nach Orgrimmar und stürzen sich auf vorbeifahrende Wagen. Sie fressen die Fracht weder auf noch zerstören sie sie. Stattdessen horten sie Kisten und Säcke nahe ihren Nestern, wo die Vorräte auf jeden warten, der sich durch ihr Gebiet kämpfen will."}},faq={{q="Wer ist Rezlak?",a="Rezlak ist ein Goblinarbeiter im Dienst von Gazlowe, dem Chef von Ratschet. Gazlowe schickte ihn nach Durotar, um den Orcs beim Bauen vor Orgrimmars Toren zu helfen.",al={"rezlak","wer ist rezlak","wer hat diese quest vergeben"}},{q="Warum helfen Goblins beim Bauen in Durotar?",a="Gazlowe und das Steamwheedle Cartel arbeiten in Handel und Ingenieurskunst mit Kriegshäuptling Thrall zusammen. Gobliningenieure und Maschinen halfen dabei, Orgrimmars Fundamente zu legen. Gazlowe stellt der Horde weiterhin vertraglich vereinbarte Arbeitskräfte und Materialien bereit.",al={"warum helfen goblins den orcs","gazlowe durotar","zusammenarbeit goblins horde"}},{q="Woher kamen die Vorräte?",a="Rezlak sagt nicht, wo die Lieferung ihren Ausgang nahm. Er sagt nur, dass eine Karawane Vorräte für seine Arbeit mit den Orcs in Durotar transportierte.",al={"woher stammen die vorräte","herkunft der karawane"}},{q="Was machen die Harpyien in Durotar?",a="Staubwindharpyien sind aggressive, räuberische Aasfresser, die die Klippen und Schluchten im Zentrum Durotars heimsuchen. Sie bedrängen Reisende, überfallen Handelstransporte entlang der Klingenschlucht und sammeln alles Glänzende oder Nützliche für ihre Nester.",al={"warum harpyien in durotar","geschichte der staubwindharpyien","razorwind-harpyien"}},{q="Wo liegt die Klingenschlucht?",a="Die Klingenschlucht zweigt von der südlichen Hauptschlucht zwischen Orgrimmar und Klingenhügel ab. Schluchten durchziehen beide Felswände und bieten Staubwindharpyien hoch gelegene Nistplätze, wo sie gestohlene Fracht verstecken.",al={"lage der klingenschlucht","wo sind die vorräte","fundort der vorratssäcke"}},{q="Warum haben die Orcwachen die Karawane nicht beschützt?",a="Rezlak sagt, dass Karawanen schwer zu schützen sind und dass dieser Lieferung sicheres Geleit versprochen wurde. Er sagt nicht, welche Wachen sie begleiteten oder warum sie die Staubwindharpyien nicht aufhalten konnten.",al={"warum scheiterte die karawane","sicherheit in durotar","orckarawanen"}}},fx={["5ac1923e"]={q="Warum will Rezlak, dass dies erledigt wird?",a="Rezlak wurde direkt von Gazlowe geschickt, um Ingenieurs- und Bauarbeiten für die Horde in Durotar zu überwachen. Ohne diese wesentlichen Materialien sind seine Arbeiten vollständig zum Stillstand gekommen, was ihn mit leeren Händen und frustriert zurücklässt. Er kann seinen Vertrag nicht erfüllen oder seine zugewiesenen Projekte beenden, bis die Fracht geborgen ist.",al={"rezlaks motiv","warum braucht rezlak vorräte","warum kümmert sich rezlak"}},ef031f2c={q="Wozu dient der Sack Vorräte?",a="Diese Säcke enthalten Ingenieurs- und Bauproviant, das für den Bau der Horde in ganz Durotar bestimmt ist. Rezlak und seine Mannschaft benötigen sie, um ihre Bauprojekte für die Orks fertigzustellen, aber das Material wurde in der Klingenschlucht verstreut, als Staubwind-Harpyien die Lieferkarawane abfingen.",al={"sack vorräte verwendung","was sind die säcke vorräte","rezlak versorgungssäcke"}}},fp="19,156,22.315.0,20.349.0,14.145.0,41.237.0,33.129.0,38.220.0,34.190.0,46.182.0"}
P.entries["quest:835"] = {n="Sicherung der Linien",s="Nahe der Klingenschlucht braucht Rezlak sichere Versorgungsrouten für die Goblins durch Durotar. Harpyien in der Staubwindklamm fangen Karawanen ab und plündern sie, also heuert er Hilfe an, um sie zu vertreiben.",h="Nahe der Klingenschlucht braucht Rezlak sichere Versorgungsrouten für die Goblins durch Durotar.",kw={"staubwindklamm","dustwind savage","dustwind storm witch","gazlowe","ratschet","klingenschlucht","rezlak","sicherung der linien"},ang={["faction:Horde"]="Die Beseitigung der Harpyien im Osten der Klingenschlucht hält die Wege für Waren und Verstärkung zwischen Durotars Grenzaußenposten und den Handelszentren an der Küste offen.",["profession:Engineering"]="Der Schutz von Rezlaks Lieferungen hilft dabei, Goblinbauteile von Ratschet zu den örtlichen Tüftlern zu bringen."},sec={{t="Eine Route voller Harpyien",b="Staubwindharpyien machen Reisen durch Durotars trockene Täler gefährlich. Rezlak überwacht die regionale Versorgung für seinen Boss Gazlowe. Von ihrem Nistplatz in der Staubwindklamm aus überfallen die Harpyien Karawanen in der Klingenschlucht und rauben Lieferungen, bevor sie ihr Ziel erreichen."},{t="Geschäfte und Blutvergießen",b="Rezlak glaubt, dass sich für den richtigen Preis alles erledigen lässt. Er heuert Abenteurer an, um den Nistplatz durch das Ausschalten von Dustwind Savages und Dustwind Storm Witches zu zerschlagen, statt selbst die Schlucht zu betreten. Die Beseitigung der Harpyien hält die Handelswege offen und sichert Lieferungen von Ingenieursapparaten. Außerdem weist sie hilfsbereiten Reisenden den Weg zu größeren Möglichkeiten in Ratschet."}},faq={{q="Für wen arbeitet Rezlak?",a="Rezlak arbeitet für Gazlowe, den Chefingenieur und Boss von Ratschet, der neutralen Hafenstadt der Goblins. Gazlowe überwacht umfangreiche Handelsgeschäfte und Infrastrukturprojekte in ganz Durotar und im Brachland.",al={"rezlaks boss","für wen arbeitet rezlak","rezlaks arbeitgeber"}},{q="Warum greifen die Harpyien Karawanen an?",a="Die Staubwindharpyien nisten in der Staubwindklamm, die entlang der Hauptverkehrswege der Klingenschlucht verläuft. Sie greifen Eindringlinge an und plündern Wagen und Waren in der Nähe.",al={"warum greifen harpyien an","motiv der staubwindharpyien","warum staubwindklamm"}},{q="Wo liegt die Staubwindklamm?",a="Die Staubwindklamm liegt tief im Osten der Klingenschlucht im nördlichen Durotar, eingeschnitten in die trockenen, tiefroten Hügel.",al={"lage der staubwindklamm","wo liegt die staubwindklamm","drygulch finden"}},{q="Was geschieht, nachdem man Rezlak geholfen hat?",a="Sobald die Staubwindharpyien dezimiert sind und die Versorgungsroute gesichert ist, schickt Rezlak Abenteurer über die Grenze nach Ratschet im Brachland. Er ermutigt sie, Gazlowe aufzusuchen, um lukrativere Aufträge zu erhalten.",al={"nach sicherung der linien","rezlaks folgeauftrag","was kommt nach rezlak"}},{q="Warum kümmert sich die Horde nicht anstelle der Goblins um die Harpyien?",a="Die Horde hat Außenposten in Durotar, doch Zentauren, Stacheleber und die Bedürfnisse ihrer Siedlungen beanspruchen ihre knappen Ressourcen. Goblinhändler wie Rezlak finden es oft schneller und günstiger, unabhängige Abenteurer zum Schutz ihrer privaten Geschäfte anzuheuern.",al={"warum heuern goblins an","warum kümmert sich orgrimmar nicht darum","horde und harpyien"}},{q="Welche Arten von Harpyien leben in der Staubwindklamm?",a="Am Nistplatz in der Staubwindklamm leben wilde Dustwind Savages, die im Nahkampf angreifen, und Dustwind Storm Witches, die Wind und Blitze gegen eindringende Karawanen einsetzen.",al={"harpyienarten","arten von staubwindharpyien","gegner in drygulch"}}},fx={bafa495b={q="Warum will Rezlak, dass die Harpyien vertrieben werden?",a="Rezlak ist dafür verantwortlich, dass die Fracht durch Durotar transportiert wird, aber die Staubwind-Harpyien in der Staubwindklamm haben seine Versorgungskarawanen überfallen und geplündert. Jeder verlorene Wagen kostet Gold, verzögert lebenswichtige Materialien und gefährdet bevorstehende Lieferungen – einschließlich einiger spezieller Ausrüstungsgegenstände, auf die er persönlich aus Ratschet wartet.",al={"rezlaks motiv","warum staubwind harpyien töten","rezlak karawanen problem"}}},fp="18,182,26.278.0,22.363.0,26.191.0,39.168.0,33.125.0,34.209.0,60.259.0,48.172.0"}
P.entries["quest:8353"] = {n="Hühnchengegacker für ein Pfefferminzbonbon",s="Zu den Schlotternächten bittet Gastwirt Feuerbräu Besucher von Eisenschmiede, für ein Pfefferminzbonbon für Jesper zu gackern, ein junges Waisenkind in Sturmwind. Champions der Allianz sammeln Süßigkeiten aus ihren Hauptstädten, um ihm Freude zu bereiten.",h="Zu den Schlotternächten bittet Gastwirt Feuerbräu Besucher von Eisenschmiede, für ein Pfefferminzbonbon für...",kw={"huhn","gackern","feuerbräu","schlotternächte","gastwirt","pfefferminzbonbon aus eisenschmiede","jesper","leckereien"},ang={["faction:Alliance"]="Als Champion der Allianz tragt Ihr Eisenschmiedes Gastfreundschaft nach Sturmwind, um einem Waisenkind Freude zu bereiten.",["race:Dwarf"]="Als Zwerg wisst Ihr, dass Eisenschmiedes Festbräuche Raum für einen Scherz lassen. Feuerbräus Forderung zeigt, dass kein Gast sich selbst zu ernst nimmt."},sec={{t="Ein Brauch der Schlotternächte",b="Jesper ist krank, lebt als Waisenkind in Sturmwind und sehnt sich nach Süßigkeiten zu den Schlotternächten. Champions der Allianz sammeln bei Gastwirten in ihren Hauptstädten Leckereien für ihn. So haben erfahrene Abenteurer einen Grund, während der Feier zum Übergang von der Ernte zum Winter von Tür zu Tür zu ziehen."},{t="Gastwirt Feuerbräus Preis",b="Gastwirt Feuerbräu verwahrt die Pfefferminzbonbons aus Eisenschmiede in der Stonefire Tavern in den Commons von Eisenschmiede. Eine höfliche Bitte reicht nicht aus. Besucher schlagen mit den Armen und gackern wie Hühner, bevor er eines herausrückt. Die Darbietung bringt die Gäste der Taverne zum Lachen, und das Pfefferminzbonbon hilft, Jesper festliche Freude zu bereiten."}},faq={{q="Warum will Gastwirt Feuerbräu, dass ich wie ein Huhn gackere?",a="Gastwirt Feuerbräu bittet Euch zu gackern, weil zu den Schlotternächten ein wenig spielerisches Theater gehört. Erfahrene Abenteurer sind zu alt, um von Tür zu Tür nach Süßigkeiten zu betteln, also tauscht er ein Pfefferminzbonbon aus Eisenschmiede gegen eine komische Darbietung und das Lachen der Tavernengäste.",al={"warum wie ein huhn gackern","feuerbräu huhn grund","warum muss ich gackern"}},{q="Wer ist Jesper und warum besorge ich Pfefferminzbonbons für ihn?",a="Jesper ist ein junges, krankes Waisenkind in Sturmwind, das sich nach Süßigkeiten zu den Schlotternächten sehnt. Champions der Allianz sammeln vier besondere Süßigkeiten aus den großen Städten der Allianz, darunter das Pfefferminzbonbon aus Eisenschmiede aus Dun Morogh, um ihm festliche Freude zu bereiten.",al={"wer ist jesper","warum pfefferminzbonbons besorgen","jesper waisenkind"}},{q="Wie fügt sich diese Quest in die Schlotternächte ein?",a="Das Pfefferminzbonbon aus Eisenschmiede ist eine von vier regionalen Süßigkeiten, die während der Schlotternächte für Jesper gesammelt werden. Gastwirte in Sturmwind und Darnassus sowie Talvash del Kissel in Eisenschmiede verlangen ebenfalls eine bestimmte theatralische Geste, bevor sie die Süßigkeit ihrer Stadt herausgeben.",al={"schlotternächte questreihe","jesper süßigkeiten questreihe","questreihenfolge"}},{q="Wo finde ich Gastwirt Feuerbräu?",a="Gastwirt Feuerbräu ist in der Stonefire Tavern in den Commons von Eisenschmiede zu finden, wo er Getränke ausschenkt und Reisenden Unterkunft bietet.",al={"wo ist feuerbräu","feuerbräu standort","eisenschmiede gastwirt"}},{q="Was erhalte ich fürs Gackern?",a="Gastwirt Feuerbräu gibt Euch ein Pfefferminzbonbon aus Eisenschmiede, eine Festtagssüßigkeit, die Ihr für Jespers Schlotternächte-Sammlung nach Sturmwind zurückbringt.",al={"questbelohnung","was ist das pfefferminzbonbon","pfefferminzbonbon aus eisenschmiede"}},{q="Können Spieler der Horde diese Aufgabe abschließen?",a="Nein, nur Champions der Allianz können teilnehmen. Abenteurer der Horde sammeln bei Gastwirten in Orgrimmar, Unterstadt und Donnerfels Leckereien für das Waisenkind Spoops.",al={"nur für die allianz","horde hühnerquest","kann die horde das machen"}}},fp="27,193,24.246.0,26.296.0,60.230.0,49.232.0,56.254.0,36.124.0,31.127.0,37.160.0"}
P.entries["quest:8354"] = {n="Hühnchengegacker für ein Pfefferminzbonbon",s="Zu den Schlotternächten bietet Gastwirt Norman aus Unterstadt Reisenden eine Süßigkeit an, wenn sie einem kranken Kind helfen. Verdient Euch das Pfefferminzbonbon aus Unterstadt, indem Ihr Eure Würde ablegt und wie ein Huhn flattert.",h="Zu den Schlotternächten bietet Gastwirt Norman aus Unterstadt Reisenden eine Süßigkeit an, wenn sie einem...",kw={"huhn","gackern","schlotternächte","gastwirt norman","spoops","handwerksviertel","unterstadt","pfefferminzbonbon aus unterstadt"},ang={["faction:Horde"]="Während der Schlotternächte besuchen Reisende der Horde jede Hauptstadt und erdulden alberne Demütigungen, um einem Waisenkind Freude zu bringen.",["race:Undead"]="Lachen ist in den verrottenden Hallen von Unterstadt selten. Normans saisonale Forderung bringt eine seltsame Unterbrechung des alltäglichen nekromantischen Pragmatismus."},sec={{t="Ein seltener Moment der Heiterkeit",b="Lachen ist selten in Unterstadt, das die befreiten Verlassenen unter den Ruinen von Lordaeron errichtet haben. Doch wenn die Schlotternächte kommen, feiern selbst die finsteren Bewohner des Handwerksviertels mit. Gastwirt Norman hält Pfefferminzbonbons aus Unterstadt für Reisende bereit, die Leckereien für Spoops sammeln, ein krankes Waisenkind, das Festtagsfreude braucht."},{t="Die Leckerei verdienen",b="Gastwirt Norman gibt gestandenen Abenteurern keine Leckerei ohne eine Darbietung. Er glaubt, dass erwachsene Krieger und Zauberwirker sich ihre Süßigkeiten verdienen sollten. Also muss der Bittsteller direkt vor seiner Theke ein Huhn vom Bauernhof nachahmen."}},faq={{q="Warum will Gastwirt Norman, dass ich wie ein Huhn gackere?",a="Gastwirt Norman meint, erwachsene Helden sollten etwas vorführen, bevor sie um Süßigkeiten bitten gehen. Um die Stimmung zu den Schlotternächten zu heben, bittet er Euch, wie ein Huhn zu flattern und zu gackern, bevor er die Leckerei herausgibt.",al={"warum huhn-emote","warum für norman gackern","norman hühnertanz"}},{q="Für wen ist die Leckerei bestimmt?",a="Das Pfefferminzbonbon aus Unterstadt ist für Spoops, ein krankes Waisenkind, das sich in Orgrimmar ausruht und zu den Schlotternächten nicht um Süßigkeiten bitten gehen kann.",al={"wer bekommt das pfefferminzbonbon","wofür ist das pfefferminzbonbon","warum pfefferminzbonbon aus unterstadt holen"}},{q="Wo befindet sich Gastwirt Norman?",a="Gastwirt Norman führt die zentrale Taverne im Handwerksviertel von Unterstadt und bewirtet Verlassene sowie Reisende der Horde.",al={"norman standort","wo ist der gastwirt von unterstadt"}},{q="Ist dies eine saisonale Festtagsquest?",a="Ja. Sie gehört zu den Schlotternächten, dem jährlichen Fest, das Horde und Allianz in ganz Azeroth feiern.",al={"gehört das zu den schlotternächten","wann ist diese quest verfügbar"}},{q="Feiern die Verlassenen normalerweise die Schlotternächte?",a="Die Verlassenen feiern die Schlotternächte mit großer Begeisterung. Sie verbrennen einen gewaltigen Weidenmann vor den Ruinen von Lordaeron, um ihre Befreiung und den Bruch mit ihrem früheren sterblichen Leben zu würdigen.",al={"verlassene schlotternächte","feiertag der untoten"}},{q="Was geschieht, nachdem man das Pfefferminzbonbon aus Unterstadt erhalten hat?",a="Das Pfefferminzbonbon aus Unterstadt ergänzt die typischen Leckereien aus den Hauptstädten der Völker der Horde zu einem vollständigen Festtagsgeschenk für den jungen Spoops.",al={"nächste quest","was mit dem pfefferminzbonbon tun"}}},fp="27,181,19.303.0,17.222.0,58.201.0,30.121.0,34.130.0,34.105.0,44.183.0,46.129.0"}
P.entries["quest:8355"] = {n="Kaugummikugelexpress",s="Talvash del Kissel bewahrt in Eisenschmiede eine Kaugummikugel aus Gnomeregan für ein krankes Kind in Sturmwind auf. Um sie zu erhalten, müsst Ihr ihm überzeugend einen Zug nachahmen.",h="Talvash del Kissel bewahrt in Eisenschmiede eine Kaugummikugel aus Gnomeregan für ein krankes Kind in...",kw={"kaugummikugel aus gnomeregan","schlotternächte","kaugummikugelexpress","eisenschmiede","jesper","talvash del kissel","tüftlerstadt","zug emote"},ang={["faction:Alliance"]="Als Held der Allianz reist Ihr für eine Festtagskaugummikugel durch die Königreiche und helft einem kränkelnden Kind in Sturmwind, am Fest teilzuhaben.",["race:Gnome"]="Als Gnom in Tüftlerstadt könnt Ihr mit dem Verschenken einer Kaugummikugel aus Gnomeregan während der Schlotternächte inmitten der Vertreibung Eures Volkes freudig an Heimat und mechanischen Erfindergeist erinnern."},sec={{t="Ein schelmischer Zoll",b="Zu den Schlotternächten besuchen Naschereisammler die Hochburgen der Allianz, um Süßigkeiten zu erhalten. Im Mystic Ward von Eisenschmiede bewahrt Talvash del Kissel die Kaugummikugel aus Gnomeregan auf. Er hat Mitgefühl mit dem jungen Waisenkind, das auf diese Süßigkeit hofft. Doch Talvash bittet Euch, mit einer überzeugenden Zugnachahmung etwas Schabernack ins Fest zu bringen."},{t="Wohltätigkeit zum Fest",b="Jesper ist ein kränkelndes Waisenkind in Sturmwind und hofft auf vier Naschereien aus den Gebieten der Allianz. Er wünscht sich Nougat aus Sturmwind, ein Minzbonbon aus Eisenschmiede, Marzipan aus Darnassus und eine Kaugummikugel aus Gnomeregan. Eure Lokomotivennachahmung unterhält Talvash und bringt Euch die Kaugummikugel ein. Sie bringt Jesper seinem Festtagswunsch näher."}},faq={{q="Was muss ich tun, um Kaugummikugelexpress abzuschließen?",a="Ahmt für Talvash del Kissel überzeugend einen Zug nach. Sobald er das Geräusch hört, überreicht er Euch die Kaugummikugel aus Gnomeregan.",al={"kaugummikugelexpress abschließen","kaugummikugelexpress ziel","talvash kaugummikugel streich"}},{q="Wer ist Talvash del Kissel?",a="Talvash del Kissel ist ein gnomischer Juwelier aus Gnomeregan, der im Mystic Ward von Eisenschmiede lebt. Während der Schlotternächte verteilt er Gnomeregans typische Kaugummikugeln an die Allianz.",al={"wer ist talvash","talvash del kissel hintergrund"}},{q="Wofür wird die Kaugummikugel aus Gnomeregan verwendet?",a="Die Kaugummikugel aus Gnomeregan ist eine von vier Schlotternächte-Naschereien, die für Jesper gesammelt werden, einen Waisenjungen, der im Waisenhaus von Sturmwind ruht.",al={"kaugummikugel aus gnomeregan zweck","wofür ist die kaugummikugel"}},{q="Wo ist Talvash del Kissel zu finden?",a="Talvash del Kissel ist im Mystic Ward von Eisenschmiede zu finden.",al={"wo ist talvash","talvash standort"}},{q="Warum lässt Talvash Euch einen Zug nachahmen?",a="Zu den Schlotternächten gehört das Sammeln von Süßigkeiten, und Talvash verlangt einen harmlosen Streich, bevor er seine Nascherei herausgibt. Er möchte eine Lokomotivennachahmung hören.",al={"warum zuggeräusch","warum für talvash einen zug nachahmen"}},{q="Ist diese Quest das ganze Jahr über verfügbar?",a="Nein. Sie ist nur während der Schlotternächte verfügbar, dem alljährlichen Herbstfest.",al={"kaugummikugelexpress jederzeit abschließbar","ist das saisonal"}}},fp="16,150,16.308.0,15.323.0,50.116.0,26.176.0,40.135.0,38.61.0,42.143.0,35.75.0"}
P.entries["quest:8356"] = {n="Muskelspiel für Nugat",s="In der Taverne „Zur Vergoldeten Rose“ bittet Gastwirtin Allison Euch, die Muskeln spielen zu lassen, bevor sie Euch Nugat aus Sturmwind gibt. Während der Schlotternächte sammelt Ihr festliche Süßigkeiten für Jesper, ein Waisenkind in Sturmwind.",h="In der Taverne „Zur Vergoldeten Rose“ bittet Gastwirtin Allison Euch, die Muskeln spielen zu lassen, bevor...",kw={"muskelspiel für nugat","zur vergoldeten rose","schlotternächte","gastwirtin allison","jesper","sturmwind","nugat aus sturmwind","süßes oder saures"},ang={["class:Warrior"]="Als Krieger kennt Ihr blutige Schlachtfelder gut. Für eine Gastwirtin die Muskeln spielen zu lassen, ist eine harmlose, wenn auch etwas würdelose Kraftdemonstration.",["faction:Alliance"]="Für die Allianz spiegelt dieser spielerische Tausch den heiteren Gemeinschaftssinn Sturmwinds während der Schlotternächte und anderer jahreszeitlicher Feste wider. Er bringt Bürger und umherziehende Helden zum gemeinsamen Lachen zusammen.",["race:Human"]="Als Mensch in Sturmwind wisst Ihr, dass es ein geschätzter jahreszeitlicher Brauch ist, Kinder zu verwöhnen und Kunststücke gegen Süßigkeiten einzutauschen. Er bietet eine kurze Verschnaufpause angesichts der düsteren Gefahren, die das Königreich bedrohen."},sec={{t="Eine Tradition der Schlotternächte",b="Die Schlotternächte bringen eine heitere Stimmung nach Sturmwind. Das Fest markiert den Wechsel der Jahreszeiten und wehrt dunkle Geister ab. Das einfache Volk feiert mit Verkleidungen, ausgelassenem Treiben und Süßem oder Saurem. Gastwirte der Allianz bieten jenen traditionelle Süßigkeiten an, die ein harmloses Kunststück vorführen."},{t="Zur Unterhaltung der Gastwirtin",b="In der Taverne „Zur Vergoldeten Rose“ im Handelsdistrikt verlangt Gastwirtin Allison eine kleine Darbietung, bevor sie festliche Süßigkeiten verteilt. Ihr sammelt Süßigkeiten für Jesper, einen Waisenjungen. Allison kommentiert scherzhaft Euren Körperbau und bittet Euch, Eure Muskeln spielen zu lassen. Wenn Ihr das tut, gibt sie Euch ein Stück zähen Nugat aus Sturmwind."}},faq={{q="Warum lässt Gastwirtin Allison die Leute ihre Muskeln spielen lassen?",a="Bei den Schlotternächten gibt es Süßigkeiten für Kunststücke, deshalb bittet Gastwirtin Allison Euch, Eure Muskeln zu zeigen, bevor sie Euch eine Süßigkeit gibt.",al={"warum muskeln für nugat spielen lassen","was will allison","warum muskelspiel-emote"}},{q="Wo findet diese Quest statt?",a="Ihr trefft Gastwirtin Allison in der Taverne „Zur Vergoldeten Rose“ in Sturmwinds Handelsdistrikt, wo sie hinter dem Tresen steht.",al={"wo ist muskelspiel für nugat","allison standort","zur vergoldeten rose gastwirtin"}},{q="Für wen ist der Nugat aus Sturmwind bestimmt?",a="Der Nugat ist für Jesper, einen Waisenjungen, der sich in Sturmwind aufhält. Er hofft, während der Schlotternächte traditionelle Festtagsleckereien aus jeder großen Stadt der Allianz probieren zu können.",al={"wer bekommt den nugat","wer will nugat aus sturmwind","jesper süßigkeiten"}},{q="Was ist Nugat aus Sturmwind?",a="Nugat aus Sturmwind ist eine regionale Süßigkeit, die Sturmwinds Gastwirte während der Schlotternächte verteilen. Festbesucher kennen ihn als eine der typischen Leckereien des Menschenkönigreichs.",al={"nugat aus sturmwind hintergrundgeschichte","schlotternächte nugat","sturmwind süßigkeiten"}},{q="Können Spieler der Horde diese Leckerei von Allison erhalten?",a="Nein. Gastwirtin Allison lebt im von der Allianz kontrollierten Sturmwind und bedient Mitglieder der Allianz. Abenteurer der Horde führen Gastwirten in ihren eigenen Hauptstädten festliche Kunststücke vor.",al={"kann die horde muskelspiel für nugat machen","hordenversion von nugat"}},{q="Ist diese Quest das ganze Jahr über verfügbar?",a="Nein. Gastwirtin Allison äußert diese Bitte nur während der Schlotternächte, wenn der Brauch von Süßem oder Saurem die Städte erfüllt.",al={"wann ist muskelspiel für nugat verfügbar","ist diese quest saisonal","schlotternächte zeitraum"}}},fp="18,176,24.276.0,26.304.0,44.116.0,33.112.0,38.158.0,25.165.0,49.179.0,34.114.0"}
P.entries["quest:8357"] = {n="Tanzen für Marzipan",s="Zu den Schlotternächten sammeln Reisende in Darnassus Süßigkeiten für Jesper, einen kranken Waisen in Sturmwind. Gastwirtin Saelienne hält den Brauch „Süßes oder Saures“ aufrecht und verlangt einen Tanz, bevor sie ihren Marzipan aus Darnassus hergibt.",h="Zu den Schlotternächten sammeln Reisende in Darnassus Süßigkeiten für Jesper, einen kranken Waisen in...",kw={"tanzen","darnassus","schlotternächte","gastwirt","jesper","marzipan","saelienne","teldrassil"},ang={["faction:Alliance"]="Für die Allianz bringt dieser Brauch der Schlotternächte Süßigkeiten aus dem fernen Teldrassil zu einem jungen Waisen in Sturmwind, geteilt über die Hauptstädte hinweg.",["race:NightElf"]="Als Nachtelf nehmt Ihr an den Bräuchen der Schlotternächte der Allianz teil, bei denen ausgelassenes Feiern auf Eure Lebensweise im Wald trifft."},sec={{t="Eine bewahrte Tradition",b="Zu den Schlotternächten wird die Stimmung in Darnassus heiterer. Es ist die heilige Waldstadt der langlebigen Nachtelfen. Ihr kommt auf der Suche nach Süßigkeiten für Jesper, ein krankes Kind, das sich in Sturmwind erholt. Gastwirtin Saelienne hält den Festtagsbrauch aufrecht, selbst für ein bedürftiges Kind. Zuerst verlangt sie einen Streich."},{t="Der Preis des Marzipans",b="Saelienne verlangt, dass Ihr auf dem Boden des Gasthauses tanzt, bevor sie Euch Marzipan aus Darnassus gibt. Mit Eurer Darbietung verdient Ihr die Süßigkeit für das Festtagspaket, das für Jesper bestimmt ist."}},faq={{q="Wozu dient Tanzen für Marzipan?",a="Ihr verdient Euch Marzipan aus Darnassus bei Gastwirtin Saelienne in Darnassus. Die Süßigkeit kommt zu anderen Leckereien der Schlotternächte, die Jesper, einen kranken Waisen in Sturmwind, aufheitern sollen.",al={"warum für marzipan tanzen","was ist das für eine quest","marzipanquest"}},{q="Wer ist Gastwirtin Saelienne?",a="Gastwirtin Saelienne führt ein Gasthaus in Darnassus. Reisende finden unter Teldrassils Zweigen Schutz und Ruhe, und während der Schlotternächte gibt sie örtliche Süßigkeiten an jene aus, die am Brauch teilnehmen.",al={"wer ist saelienne","saeliennes geschichte"}},{q="Warum besteht Saelienne auf einem Tanz?",a="Saelienne folgt dem Brauch „Süßes oder Saures“ der Schlotternächte. Sie verlangt, dass Ihr tanzt, bevor sie Euch eine Süßigkeit für ein krankes Kind gibt.",al={"warum tanzen","warum verlangt saelienne einen tanz"}},{q="Wohin kommt der Marzipan danach?",a="Der Marzipan aus Darnassus kommt zu Festtagssüßigkeiten aus Gasthäusern in Eisenschmiede und Sturmwind sowie zu Süßigkeiten von Talvash del Kissel in Eisenschmiede. Zusammen sollen sie dem jungen Jesper in Sturmwind Festtagsfreude bringen.",al={"wer bekommt den marzipan","was mit marzipan tun"}},{q="Was ist Marzipan aus Darnassus?",a="Marzipan aus Darnassus ist eine zuckrige Süßware, die in der Hauptstadt der Nachtelfen hergestellt wird. Sie ist die festliche Leckerei der Stadt für Besucher der Schlotternächte.",al={"geschichte des marzipans aus darnassus","was für eine süßigkeit ist das"}},{q="Können Spieler der Horde diese Quest abschließen?",a="Nein. Sie ist für Charaktere der Allianz bestimmt. Darnassus ist eine Hochburg der Allianz, und der Marzipan wird für einen Waisen der Allianz gesammelt, der sich in Sturmwind erholt.",al={"ist diese quest nur für die allianz","marzipanquest der horde"}}},fp="20,206,18.289.0,21.165.0,44.162.0,27.197.0,37.130.0,38.214.0,27.132.0,38.155.0"}
P.entries["quest:8359"] = {n="Muskelspiel für Nugat",s="In Orgrimmar tauscht Gastwirtin Gryshka Nugat gegen eine kleine Vorführung. Während der Schlotternächte lasst Ihr Eure Muskeln für eine Süßigkeit spielen, die Spoops, ein bettlägeriges Kind, aufmuntern soll.",h="In Orgrimmar tauscht Gastwirtin Gryshka Nugat gegen eine kleine Vorführung.",kw={"süßigkeiten","muskelspiel","gryshka","schlotternächte","nugat","orgrimmar","spoops","süßes oder saures"},ang={["class:Warrior"]="Als Krieger mögt Ihr stolz auf Eure vernichtenden Taten an vorderster Front sein. Doch für Festtagssüßigkeiten wie ein Bühnenkünstler zu posieren, kann amüsant sein oder Euren Stolz dämpfen.",["faction:Horde"]="Selbst erfahrene Champions der Horde, die sich tödlichen Kriegsherren stellen, lassen für Gastwirte ihre Bizeps spielen und sammeln Festtagssüßigkeiten für die Kinder.",["race:Orc"]="Als Orc wird Euer Stolz während des Festes auf die Probe gestellt, wenn Orgrimmars Gastwirtin Euch bittet, Eure Muskeln zu zeigen."},sec={{t="Kunststücke für Süßigkeiten",b="Die Schlotternächte erfüllen Azeroths Hauptstädte mit Streichen und dem Sammeln von Süßigkeiten. In Orgrimmars Gasthaus hält Gastwirtin Gryshka Festtagssüßigkeiten für jene bereit, die bei diesem Brauch mitmachen. Auf Euren Reisen mögt Ihr Drachen und finsterer Zauberei begegnen, doch hier ist der Handel einfach: Führt ein Kunststück vor oder geht ohne Süßigkeit."},{t="Muskeln zur Schau",b="Gastwirtin Gryshka bittet Euch, orkische Stärke zu zeigen, bevor sie Euch Nugat aus Orgrimmar für den jungen Spoops gibt. Welche Verkleidung oder Rüstung Ihr auch tragt, nehmt eine muskulöse Pose ein. Selbst die gefürchteten Kämpfer der Horde können das einfache Volk für Süßigkeiten unterhalten."}},faq={{q="Wer verlangt das Muskelspiel?",a="Gastwirtin Gryshka, die die Haupttaverne in Orgrimmars Tal der Stärke führt, bittet Euch um ein Kunststück, bevor sie Festtagssüßigkeiten herausgibt.",al={"wer vergibt die quest","gryshka","gastwirtin gryshka"}},{q="Warum muss ich für Süßigkeiten die Muskeln spielen lassen?",a="Der Brauch der Schlotternächte verlangt ein kleines Kunststück im Tausch gegen eine Süßigkeit. Gryshka neckt Euch mit der Bitte, Eure reine Körperkraft zur Schau zu stellen, bevor sie Euch Süßigkeiten gibt.",al={"warum muskeln spielen lassen","was ist das kunststück","bedingung für nugat"}},{q="Wofür wird das Nugat aus Orgrimmar gebraucht?",a="Das Nugat ist eine von vier Süßigkeiten, die in den Hauptstädten der Horde gesammelt werden, um Spoops aufzumuntern, einen kranken, bettlägerigen Waisenjungen, der nicht selbst auf Süßigkeitensuche gehen kann.",al={"wozu wird nugat gebraucht","verwendung von nugat","spoops süßigkeiten"}},{q="Wo wohnt Gastwirtin Gryshka?",a="Gastwirtin Gryshka steht hinter dem Tresen des Hauptgasthauses in Orgrimmars Tal der Stärke. Dort bedient sie müde Reisende und Einheimische.",al={"wo ist gryshka","orgrimmar gastwirtin standort"}},{q="Kann jedes Mitglied der Horde mitmachen?",a="Ja. Jedes Mitglied der Horde kann Gastwirtin Gryshka während der Schlotternächte besuchen, eine Pose einnehmen und die saisonale Süßigkeit erhalten.",al={"wer kann muskeln spielen lassen","fraktionsbeschränkungen","nur horde"}},{q="Zu welchem Fest gehört das?",a="Es gehört zu den Schlotternächten, einem Herbstfest, das das Ende der Ernte feiert und mit Kostümen, Streichen und Süßigkeiten der Sterblichkeit trotzt.",al={"welches ereignis","welches fest","schlotternächte quest"}}},fp="18,148,17.282.0,17.237.0,27.143.0,32.161.0,38.159.0,36.131.0,41.122.0,31.136.0"}
P.entries["quest:836"] = {n="Rettet OOX-09/HL!",s="Jenseits von Overlook Cliff braucht OOX-09/HL Eure Hilfe, um die Küste zu erreichen. Oglethorpe Obnoticus spricht durch den gestürzten Roboter und bittet Euch, ihn dorthin zu eskortieren. Danach wartet er in Beutebucht.",h="Jenseits von Overlook Cliff braucht OOX-09/HL Eure Hilfe, um die Küste zu erreichen.",kw={"beutebucht","tarnung","peilroboter","oglethorpe obnoticus","overlook cliff","oox-09/hl"},sec={{t="Ein Marsch zur Küste",b="Oglethorpes Stimme knistert erneut aus dem Roboter. OOX-09/HL braucht für seine langwierige Startprozedur einen offenen, sicheren Ort, und die Küste jenseits von Overlook Cliff eignet sich dafür. Seine eingebaute Tarnung kann noch nicht genutzt werden. Oglethorpe braucht Zeit, um sie wieder einsatzbereit zu machen."},{t="Nachricht in Beutebucht",b="Wenn OOX-09/HL die Küste sicher erreicht, bittet Oglethorpe Obnoticus Euch, mit ihm in Beutebucht zu sprechen."}},faq={{q="Wohin muss der Roboter eskortiert werden?",a="Bringt OOX-09/HL zur Küste jenseits von Overlook Cliff. Dort hat er Platz, um seinen Start zu beginnen.",al={"wohin geht oox-09","hinterlands hühnereskorte ziel","overlook cliff küste"}},{q="Wer hat diesen Peilroboter erschaffen?",a="Der Gnom Oglethorpe Obnoticus hat den Roboter erschaffen. Er ist in Beutebucht.",al={"wer hat oox-09 erschaffen","oox erschaffer","wer hat das huhn gebaut"}},{q="Warum kann der Roboter nicht einfach dort starten, wo er gefunden wurde?",a="Der langwierige Start erfordert einen offenen, sicheren Ort. Oglethorpe braucht außerdem Zeit, um die Tarnung des Roboters wieder einsatzbereit zu machen.",al={"warum läuft das huhn","warum oox-09 eskortieren"}},{q="Wohin geht Ihr, sobald die Eskorte die Küste erreicht hat?",a="Sobald OOX-09/HL sicher an der Küste ist, bittet Oglethorpe Obnoticus Euch, ihn in Beutebucht zu treffen.",al={"wo rettet oox-09 abgeben","bei wem bericht erstatten","oglethorpe aufenthaltsort"}},{q="Was ging dieser Eskorte voraus?",a="Dies folgt auf Find OOX-09/HL!, als Ihr das Notsignalfeuer zum abgestürzten Roboter gebracht habt.",al={"oox-09 vorherige quest","voraussetzung für rettet oox-09"}}},fp="17,187,19.257.0,17.102.0,41.96.0,50.69.0,55.115.0,50.94.0,29.88.0"}
P.entries["quest:8360"] = {n="Tanzen für Marzipan",s="Während der Schlotternächte bittet Gastwirtin Pala Besucher, für Marzipan aus Donnerfels zu tanzen. Die Leckerei ist für ein krankes Waisenkind bestimmt, und der Brauch bringt Festtagsfreude auf Mulgোরes hohe Tafelberge.",h="Während der Schlotternächte bittet Gastwirtin Pala Besucher, für Marzipan aus Donnerfels zu tanzen.",kw={"tanzen für marzipan","schlotternächte","gastwirtin pala","marzipan","mulgore","donnerfels","süßes oder saures"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr inmitten der täglichen Kämpfe Eurer Fraktion einen unbeschwerten Moment teilen und einem Waisenkind Festtagsfreude bringen, während Ihr zwischen Hauptstädten reist.",["race:Tauren"]="Als Taure könnt Ihr Gastwirtin Pala dabei erleben, wie sie mit einem Tanz für einen süßen Zweck Festtagsfreude nach Mulgore bringt."},sec={{t="Ein Tanz auf den Höhen",b="Während der Schlotternächte pflegt Gastwirtin Pala in Donnerfels den Brauch von Süßem oder Saurem. Ihr kommt auf der Suche nach einer Süßigkeit für ein krankes Kind, doch Pala bittet zuerst um einen festlichen Tanz. Dann gibt sie Euch Marzipan aus Donnerfels."},{t="Streiche für Süßigkeiten",b="Für Pala ist der Brauch einfach. Tretet vor und tanzt, um Euch eine Süßigkeit zu verdienen. Sobald Ihr sie unterhalten habt, gibt sie Euch das Marzipan und herzliche Wünsche für das kranke Kind, das darauf wartet."}},faq={{q="Worum geht es bei Tanzen für Marzipan?",a="Ihr tanzt für Gastwirtin Pala in Donnerfels und erhaltet ein Stück Marzipan aus Donnerfels. Es kommt zu den festlichen Leckereien, die während der Schlotternächte für ein krankes Waisenkind gesammelt werden.",al={"warum für marzipan tanzen","marzipan questziel","tanzen für marzipan ziel"}},{q="Wer vergibt diese Quest?",a="Gastwirtin Pala, die Tauren-Gastwirtin, die Besucher und Einheimische in Donnerfels bewirtet, bietet während der Schlotternächte den Tanz an.",al={"wer startet tanzen für marzipan","pala quest","gastwirtin pala donnerfels"}},{q="Warum besteht Pala auf einem Tanz, wenn die Süßigkeit für ein krankes Kind ist?",a="Pala hält den Brauch von Süßem oder Saurem in Ehren: Ihr führt einen Streich vor, um Euch eine Süßigkeit zu verdienen. Der Tanz hält die Schlotternächte fröhlich und lebendig.",al={"warum ist tanzen nötig","warum will pala einen tanz"}},{q="Welche Belohnung erhaltet Ihr für den Tanz?",a="Ihr erhaltet ein Stück Marzipan aus Donnerfels, eine örtliche Festtagssüßigkeit für die größere Sammlung von Schlotternachtsleckereien für das kranke Kind.",al={"marzipan belohnung","tanzen für marzipan gegenstand"}},{q="Können Spieler der Allianz diese Quest abschließen?",a="Nein. Gastwirtin Pala lebt in Donnerfels, daher können nur Mitglieder der Horde sie an dieser Station ihrer festlichen Süßigkeitensammlung besuchen.",al={"nur für die horde","allianz tanzen für marzipan"}},{q="Wann ist diese Quest verfügbar?",a="Sie ist während der Schlotternächte verfügbar, dem jährlichen Herbstfest, bei dem Gastwirte in ganz Azeroth besondere Süßigkeiten und festliche Spiele anbieten.",al={"wann gibt es marzipan","schlotternächte marzipan quest"}}},fp="20,185,20.215.0,17.180.0,44.168.0,21.123.0,65.123.0,39.138.0,41.125.0,29.133.0"}
P.entries["quest:8367"] = {n="For Great Honor",s="Ein Warbringer der Horde bittet Euch um Abzeichen aus vier Schlachtfeldern. Die Bitte vereint Ehren aus den Kämpfen der Horde.",h="Ein Warbringer der Horde bittet Euch um Abzeichen aus vier Schlachtfeldern.",kw={"alteractal","arathibecken","darkspear islands","für große ehre","warbringer der horde","marks of honor","kriegshymnenschlucht"},sec={{t="Abzeichen für den Warbringer",b="Ein Warbringer der Horde außerhalb der Schlachtfelder bittet Euch um Marks of Honor aus dem Alteractal, dem Arathibecken, der Kriegshymnenschlucht und von den Darkspear Islands. Ihr bringt drei Marks of Honor von jedem Ort und tragt ihre Ehren zum Warbringer."}},faq={{q="Worum bittet Euch der Warbringer?",a="Der Warbringer der Horde bittet um drei Marks of Honor aus dem Alteractal, dem Arathibecken, der Kriegshymnenschlucht und von den Darkspear Islands.",al={"welche abzeichen brauche ich","abzeichen für den warbringer"}},{q="Wo ist der Warbringer?",a="Der Warbringer der Horde befindet sich außerhalb der Schlachtfelder.",al={"wo finde ich den warbringer","aufenthaltsort des warbringers der horde"}},{q="Wie viele Abzeichen werden von jedem Ort benötigt?",a="Ihr bringt drei Marks of Honor von jedem der vier Orte.",al={"abzeichen pro schlachtfeld","wie viele ehrenabzeichen"}}},fp="15,128,24.229.0,33.127.0,24.50.0,42.60.0"}
P.entries["quest:837"] = {n="Übergriff",s="In Klingenhügel in Durotars Mitte schickt Gar'Thok Euch westwärts gegen die Lager der Razormane. Ihre befestigten Bauten bedrohen noch immer die junge Heimat der Orcs.",h="In Klingenhügel in Durotars Mitte schickt Gar'Thok Euch westwärts gegen die Lager der Razormane.",kw={"dornengestrüpp","durotar","übergriff","gar'thok","stacheleber","klingenhügel","razormane"},ang={["faction:Horde"]="Als Mitglied der Horde müsst Ihr Durotar vor den einheimischen Razormane-Stachelebern sichern, um eine sichere, dauerhafte Heimat zu schaffen.",["race:Orc"]="Als Orc beansprucht Ihr Durotar als Eure neue Heimat. Die Dornengestrüppbauten der Razormane bedrohen noch immer Eure Siedlungen."},sec={{t="Ein Dorn in Durotars Seite",b="Als Thrall die Orcs nach Kalimdor brachte und Durotar gründete, durchstreiften die Razormane bereits weite Teile des kargen, trockenen Landes. Diese aggressiven, eberartigen Stacheleber wurden zu einer ständigen Gefahr für die neue Siedlung. Durch anhaltende militärische Anstrengungen drängte die Horde die meisten von ihnen zurück. Doch westlich von Klingenhügel halten sich noch immer versprengte Gruppen in befestigten Dornenschanzen."},{t="Gar'Thoks Offensive",b="Gar'Thok, ein Offizier in Klingenhügel, leitet die Bemühungen, die verbliebenen Razormane zu vertreiben. Er schickt erfahrene Verteidiger in die westlichen Dornengestrüpplager, um ihre Kundschafter, Krieger und Staubläufer zu töten. Gar'Thok und die Führung der Horde befürchten, dass jeder Stützpunkt der Stacheleber nahe Klingenhügel eine Katastrophe heraufbeschwören könnte. Sie sehen diesen Angriff als ersten Schritt zur Sicherung Kalimdors."},{t="Das Gestrüpp roden",b="Sobald die Verteidiger der Stacheleber beseitigt sind, können die Truppen der Horde die Dornengestrüppbauten niederbrennen und die Razormane daran hindern, die westlichen Ausläufer zurückzuerobern. Das Feuer vernichtet eine anhaltende Bedrohung und sichert Durotars Westgrenze. Es schützt auch die lebenswichtigen Nachschubwege zwischen Klingenhügel und dem übrigen Reich."}},faq={{q="Wer vergibt die Quest Übergriff?",a="Gar'Thok, ein Orc-Offizier, der in Klingenhügel im zentralen Durotar stationiert ist, erteilt den Befehl.",al={"wer vergibt übergriff","wo gibt es übergriff","übergriff questgeber"}},{q="Warum kämpft die Horde gegen die Razormane-Stacheleber in Durotar?",a="Als die Orcs in Durotar ankamen, beherrschten die Razormane-Stacheleber weite Teile der Region. Die Horde drängte die meisten von ihnen zurück, doch westlich von Klingenhügel verbleiben befestigte Stellungen, die die Sicherheit der neuen Heimat der Orcs bedrohen.",al={"warum stacheleber in durotar bekämpfen","warum razormane angreifen","stacheleberkonflikt durotar"}},{q="Wo liegen die Lager der Razormane?",a="Die Lager der Razormane liegen westlich von Klingenhügel, inmitten von dichtem Dornengestrüpp.",al={"wo sind die stacheleberlager","wie razormane-lager finden","übergriff ort"}},{q="Wer sind die Razormane?",a="Die Razormane sind ein feindseliger Stamm von Stachelebern, der in Kalimdors trockenen Ebenen heimisch ist. Sie errichten befestigte Dornengestrüppbauten und widersetzen sich erbittert der Besiedlung Durotars und des Brachlands durch die Horde.",al={"wer sind die razormane","razormane hintergrundgeschichte","was sind razormane"}},{q="Was geschieht, sobald die Stacheleber besiegt sind?",a="Nachdem die Stacheleber besiegt sind, lässt Gar'Thok den Befehl überbringen, ihr geräumtes Dornengestrüpp und ihre Bauten niederzubrennen. Das festigt die Kontrolle der Horde über das Gebiet und sichert Durotars Grenzen.",al={"was geschieht nach übergriff","übergriff abgeben","schicksal der stacheleberlager"}},{q="Welche Rolle spielt Klingenhügel in diesem Konflikt?",a="Klingenhügel ist eine befestigte Siedlung der Orcs im zentralen Durotar. Sie ist ein militärischer und logistischer Knotenpunkt zwischen dem Tal der Prüfungen und Orgrimmar.",al={"wo liegt klingenhügel","was ist klingenhügel"}}},fp="12,142,25.351.0,20.359.0,21.296.0,33.85.0,60.213.0,38.83.0,22.184.0,44.173.0,43.140.0"}
P.entries["quest:8370"] = {n="Conquering Arathi Basin",s="Ein Warbringer der Horde bittet Euch, drei Arathibecken Marks of Honor zu bringen. Sie sind die erforderlichen Marken für diese Bitte.",h="Ein Warbringer der Horde bittet Euch, drei Arathibecken Marks of Honor zu bringen.",kw={"arathibecken","schlachtfeld","arathibecken erobern","warbringer der horde","mark of honor"},faq={{q="Was verlangt der Warbringer der Horde?",a="Der Warbringer der Horde bittet Euch, drei Arathibecken Marks of Honor zu bringen.",al={"was wird benötigt","warbringer bitte"}},{q="Wohin bringe ich die Marken?",a="Bringt die Marken zu einem Warbringer der Horde außerhalb der Schlachtfelder.",al={"wo abgeben","warbringer standort"}},{q="Wie viele Marks of Honor werden benötigt?",a="Ihr benötigt drei Arathibecken Marks of Honor.",al={"wie viele marken","drei marken"}}},fp="23,118,39.73.0,27.64.0,35.43.0"}
P.entries["quest:8372"] = {n="Fight for Warsong Gulch",s="Ein Allianz-Brigadegeneral bittet Euch, Marks of Honor aus der Kriegshymnenschlucht zu bringen. Die Abzeichen werden außerhalb der Schlachtfelder benötigt.",h="Ein Allianz-Brigadegeneral bittet Euch, Marks of Honor aus der Kriegshymnenschlucht zu bringen.",kw={"allianz","schlachtfelder","brigadegeneral","ehrenabzeichen","kriegshymnenschlucht"},ang={["faction:Alliance"]="Als Mitglied der Allianz könnt Ihr einem Allianz-Brigadegeneral Marks of Honor aus der Kriegshymnenschlucht bringen."},sec={{t="Die Abzeichen",b="Nach einem Kampf in der Kriegshymnenschlucht könnt Ihr einem Allianz-Brigadegeneral außerhalb der Schlachtfelder drei Marks of Honor bringen. Der General bittet um die Abzeichen, und Ihr wisst, was Ihr ihm bringen müsst."}},faq={{q="Was möchte der Brigadegeneral?",a="Ein Allianz-Brigadegeneral bittet Euch, drei Marks of Honor aus der Kriegshymnenschlucht zu bringen.",al={"welche abzeichen werden verlangt","bitte des brigadegenerals"}},{q="Wohin bringe ich die Abzeichen?",a="Bringt die Abzeichen einem Allianz-Brigadegeneral außerhalb der Schlachtfelder.",al={"wo abzeichen abgeben","wo ist der general"}},{q="Wie viele Marks of Honor werden benötigt?",a="Der General bittet um drei Marks of Honor aus der Kriegshymnenschlucht.",al={"wie viele abzeichen","anzahl der ehrenabzeichen"}}},fp="23,125,9.202.0,37.83.0,27.75.0,35.56.0"}
P.entries["quest:8373"] = {n="Die Kraft der Pinie",s="Während des Schlotternächtefests bittet Sergeant Hartman Euch, die Stinkbomben der Verlassenen aus Süderstade zu entfernen. Ein nach Kiefer duftender Reiniger hilft, das Dorf sauber zu halten.",h="Während des Schlotternächtefests bittet Sergeant Hartman Euch, die Stinkbomben der Verlassenen aus Süderstade...",kw={"verlassene","schlotternächtefest","kiefernreiniger","sergeant hartman","süderstade","stinkbombenreiniger","stinkbomben"},ang={["faction:Alliance"]="Als Reisender der Allianz könnt Ihr Sergeant Hartman helfen, Süderstade von den Stinkbomben der Verlassenen frei zu halten."},sec={{t="Süderstades Gestank",b="Während des Schlotternächtefests verpesten die Verlassenen Süderstade mit Stinkbomben. Die Bomben trüben die Feier der Befreiung. Sergeant Hartman bittet Euch, mit einem Stinkbombenreiniger alle Bomben zu entfernen, die im Dorf gelandet sind."}},faq={{q="Wer bittet mich, die Stinkbomben zu entfernen?",a="Sergeant Hartman in Süderstade bittet Euch, die Stinkbomben der Verlassenen zu entfernen.",al={"wer hat mir das gegeben","sergeant hartman"}},{q="Wo sind die Stinkbomben?",a="Die Stinkbomben sind in Süderstade.",al={"stinkbomben fundort","wo reinigen"}},{q="Wer setzt Stinkbomben gegen Süderstade ein?",a="Die Verlassenen setzen während des Schlotternächtefests Stinkbomben gegen Süderstade ein.",al={"wer wirft stinkbomben","bomben der verlassenen"}},{q="Was bewirkt der Reiniger?",a="Der Stinkbombenreiniger nutzt Kiefer, um üble Gerüche zu bekämpfen.",al={"kiefernreiniger","stinkbombenreiniger"}},{q="Warum wird Süderstade gereinigt?",a="Die Stinkbomben der Verlassenen sorgen während des Schlotternächtefests in Süderstade für eine stinkende Sauerei.",al={"warum süderstade reinigen","schlotternächtefest gestank"}}},fp="17,148,20.213.0,40.74.0,26.34.0,35.65.0,25.54.0,32.93.0"}
P.entries["quest:8374"] = {n="Claiming Arathi Basin",s="Ein Allianz-Brigadegeneral vor dem Arathibecken bittet Euch, drei Arathi Basin Marks of Honor zu bringen. Der General fordert diese Marken von Euch.",h="Ein Allianz-Brigadegeneral vor dem Arathibecken bittet Euch, drei Arathi Basin Marks of Honor zu bringen.",kw={"allianz","allianz-brigadegeneral","arathibecken","arathibecken beanspruchen","marks of honor"},ang={["faction:Alliance"]="Als Mitglied der Allianz sollt Ihr einem Allianz-Brigadegeneral drei Arathi Basin Marks of Honor bringen."},faq={{q="Wer bittet um die Marken?",a="Ein Allianz-Brigadegeneral außerhalb der Schlachtfelder bittet Euch, drei Arathi Basin Marks of Honor zu bringen.",al={"wer möchte marken","brigadegeneral"}},{q="Wie viele Marks of Honor werden benötigt?",a="Der General bittet Euch, drei Arathi Basin Marks of Honor zu bringen.",al={"wie viele marken","drei marken"}},{q="Wohin soll ich die Marken bringen?",a="Bringt die Marken zu einem Allianz-Brigadegeneral außerhalb der Schlachtfelder.",al={"wohin mit den marken","marken abgeben"}}},fp="21,153,23.108.0,35.64.0,27.75.0"}
P.entries["quest:8386"] = {n="Fight for Warsong Gulch",s="Ein Aufruf zum Kampf um die Kriegshymnenschlucht hilft, Eschentals natürliche Verteidigung zu bewahren. Eure Bemühungen halten sie einen weiteren Tag lang intakt.",h="Ein Aufruf zum Kampf um die Kriegshymnenschlucht hilft, Eschentals natürliche Verteidigung zu bewahren.",kw={"eschental","verteidigung","um die kriegshymnenschlucht kämpfen","natürliche verteidigung","kriegshymnenschlucht"},sec={{t="Eschentals Verteidigung",b="In Eschental werdet Ihr gebeten, um die Kriegshymnenschlucht zu kämpfen. Euer Einsatz hilft, die natürliche Verteidigung des Gebiets einen weiteren Tag lang intakt zu halten."}},faq={{q="Warum um die Kriegshymnenschlucht kämpfen?",a="Eure Bemühungen helfen, Eschentals natürliche Verteidigung einen weiteren Tag lang zu bewahren.",al={"kampf um die kriegshymnenschlucht","warum kriegshymnenschlucht"}},{q="Was wird dadurch geschützt?",a="Der Kampf hilft, Eschentals natürliche Verteidigung einen weiteren Tag lang intakt zu halten.",al={"welche verteidigung","schutz eschentals"}},{q="Wo liegt die Kriegshymnenschlucht?",a="Die Kriegshymnenschlucht ist das Schlachtfeld, das eine natürliche Barriere zwischen Eschental und dem Brachland bildet.",al={"lage der kriegshymnenschlucht","wo liegt die kriegshymnenschlucht"}}},fp="23,125,20.128.0,28.72.0,28.73.0,23.96.0"}
P.entries["quest:8389"] = {n="Battle of Warsong Gulch",s="Die Horde bittet Euch, ihr dabei zu helfen, ihren Besitzanspruch auf die Kriegshymnenschlucht zu sichern. Eure Hilfe ist wichtig für ihren Anspruch auf das Gebiet.",h="Die Horde bittet Euch, ihr dabei zu helfen, ihren Besitzanspruch auf die Kriegshymnenschlucht zu sichern.",kw={"schlacht","anspruch","horde","besitz","kriegshymnenschlucht"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr dabei, ihren Besitzanspruch auf die Kriegshymnenschlucht zu sichern."},sec={{t="Anspruch der Horde",b="Der Besitzanspruch der Horde auf die Kriegshymnenschlucht erfordert Eure Hilfe. Indem Ihr helft, unterstützt Ihr ihren Besitzanspruch auf die Schlucht."}},faq={{q="Was will die Horde hier?",a="Die Horde will ihren Besitzanspruch auf die Kriegshymnenschlucht sichern.",al={"kriegshymnenschlucht horde","anspruch der horde","wem gehört die kriegshymnenschlucht"}},{q="Wie kann ich helfen?",a="Eure Hilfe trägt dazu bei, den Besitzanspruch der Horde auf die Kriegshymnenschlucht zu sichern.",al={"horde helfen","was tue ich","schlacht um die kriegshymnenschlucht"}},{q="Warum will die Horde die Kriegshymnenschlucht?",a="Laut dem vorliegenden Bericht will die Horde ihren Besitzanspruch auf die Kriegshymnenschlucht sichern.",al={"warum kriegshymnenschlucht","warum die horde sie will","grund für die kriegshymnenschlucht"}}},fp="23,112,11.116.0,30.57.0,15.63.0,38.84.0"}
P.entries["quest:8393"] = {n="Claiming Arathi Basin",s="Ein Brigadier General der Allianz vor dem Arathibecken bittet Euch, drei Arathi Basin Marks of Honor zu bringen. Die Marken sind das Einzige, was in dieser Bitte genannt wird.",h="Ein Brigadier General der Allianz vor dem Arathibecken bittet Euch, drei Arathi Basin Marks of Honor zu...",kw={"allianz","arathibecken","brigadier general","arathibecken beanspruchen","marken der ehre"},ang={["faction:Alliance"]="Als Mitglied der Allianz sollt Ihr einem Brigadier General der Allianz drei Arathi Basin Marks of Honor bringen."},faq={{q="Worum bittet der Brigadier General?",a="Der Brigadier General der Allianz bittet Euch, drei Arathi Basin Marks of Honor zu bringen.",al={"arathi-marken","drei marken","was soll ich bringen"}},{q="Wohin soll ich die Marken bringen?",a="Bringt die Marken zu einem Brigadier General der Allianz außerhalb der Schlachtfelder.",al={"wo abgeben","standort des brigadier generals","wo die marken abgeben"}},{q="Wer bittet um die Marken?",a="Ein Brigadier General der Allianz außerhalb der Schlachtfelder bittet um die Marken.",al={"wer will sie","arathi general","wer gibt das"}}},fp="21,155,40.83.0,27.75.0,28.75.0"}
P.entries["quest:83934"] = {n="Show Me the Money!",s="Pix Xizzix bittet Euch, Münzen zurückzuholen, die seine Brüder in Beutebucht an Piraten verloren haben. Das Geld ist wichtig für das Geschäft, das sie auf Kezan beginnen wollten.",h="Pix Xizzix bittet Euch, Münzen zurückzuholen, die seine Brüder in Beutebucht an Piraten verloren haben.",kw={"beutebucht","geschäftsvorhaben","münze","kezan","piraten","pix xizzix","tarnished undermine real","undermine real"},sec={{t="Ein gestohlener Anfang",b="Pix Xizzix in Beutebucht sucht Hilfe, nachdem Piraten das Startkapital gestohlen haben, das er und seine Brüder von Kezan mitgebracht hatten. Ihre Geldgeber in der Heimat erwarten, dass das Geschäft gelingt. Deshalb bietet Pix Euch eine Belohnung für jede Münze, die Ihr zurückholt. Er bittet Euch, ihm einen Tarnished Undermine Real zu bringen."}},faq={{q="Wer ist Pix Xizzix?",a="Pix Xizzix gehört zu einer Gruppe von Brüdern aus Kezan, die gekommen sind, um ein Geschäft zu beginnen.",al={"pix xizzix","wer ist pix","xizzix"}},{q="Warum will Pix die Münzen zurück?",a="Piraten stahlen das Startkapital, das Pix und seine Brüder für ihr Geschäft mitgebracht hatten. Ihre Geldgeber in der Heimat zeigen wenig Verständnis.",al={"warum münzen zurück","gestohlenes geld","pix geld"}},{q="Nach welcher Münze sucht Pix?",a="Pix bittet Euch, ihm einen Tarnished Undermine Real zu bringen.",al={"tarnished real","undermine münze","welche münze"}},{q="Wohin soll ich die Münze bringen?",a="Bringt den Tarnished Undermine Real zu Pix Xizzix nach Beutebucht.",al={"wohin münze bringen","pix ort","beutebucht münze"}},{q="Was bietet Pix für die Münze?",a="Pix sagt, er und seine Brüder würden es Euch lohnen und hätten Waren zum Tausch.",al={"pix belohnung","tauschwaren","was für münze"}}},fp="18,138,14.272.0,18.89.0,32.133.0,29.53.0,30.62.0,33.84.0"}
P.entries["quest:8399"] = {n="Fight for Warsong Gulch",s="Ein Allianz-Brigadegeneral außerhalb der Schlachtfelder bittet Euch, drei Marks of Honor zu bringen. Die Marken werden gebraucht, um dem Ruf zu folgen und dort zu kämpfen.",h="Ein Allianz-Brigadegeneral außerhalb der Schlachtfelder bittet Euch, drei Marks of Honor zu bringen.",kw={"allianz","brigadegeneral","kampf","marks of honor","kriegshymnenschlucht"},ang={["faction:Alliance"]="Als Kämpfer der Allianz sollt Ihr einem Allianz-Brigadegeneral außerhalb der Schlachtfelder Marks of Honor bringen."},sec={{t="Die Bitte des Brigadegenerals",b="Marks of Honor aus der Kriegshymnenschlucht sucht der Brigadegeneral der Allianz vor den Schlachtfeldern von Euch. Bringt dem General drei Marks of Honor, und Euer Kampf um die Kriegshymnenschlucht kann als Teil des Einsatzes der Allianz gelten."}},faq={{q="Was möchte der Brigadegeneral der Allianz?",a="Ein Allianz-Brigadegeneral außerhalb der Schlachtfelder bittet Euch, drei Marks of Honor zu bringen.",al={"abzeichen für den brigadegeneral","welche abzeichen brauche ich"}},{q="Wo soll ich die Marks of Honor abgeben?",a="Bringt die Marks of Honor zu einem Brigadegeneral der Allianz vor den Schlachtfeldern.",al={"wo die abzeichen abgeben","ort der abzeichen aus der kriegshymnenschlucht"}},{q="Wie viele Marks of Honor werden benötigt?",a="Ihr benötigt drei Warsong Gulch Marks of Honor.",al={"wie viele abzeichen","drei abzeichen"}}},fp="23,151,23.219.0,46.96.0,36.84.0,35.44.0"}
P.entries["quest:84"] = {n="Zurück zu Billy",s="Bernice Steinfeld schickt Euch mit einer Schweinebauchpastete über die Straße zu Billy Maclure. Er weiß etwas über ihre verschwundene Halskette, und die Lieferung setzt die Fehde ihrer Familien im zentralen Wald von Elwynn fort.",h="Bernice Steinfeld schickt Euch mit einer Schweinebauchpastete über die Straße zu Billy Maclure.",kw={"zurück zu billy","bernice steinfeld","billy maclure","wald von elwynn","weinberge der maclures","schweinebauchpastete","hof der steinfelds","steinfeld halskette"},ang={["faction:Alliance"]="Als Reisender der Allianz begegnet Ihr selbst im friedlichen Wald von Elwynn Streitigkeiten zwischen menschlichen Gehöften. Den Einheimischen zu helfen bedeutet oft, sich mit diesen Zwistigkeiten auseinanderzusetzen.",["profession:Cooking"]="Als Koch kennt Ihr die Schweinebauchpastete als wohltuendes Bauerngericht aus Elwynn, zubereitet aus dem Fleisch der Wildschweine, die durch den Wald streifen."},sec={{t="Eine bittere Pastete",b="Die Fehde zwischen den Steinfelds und den Maclures lässt wenig Raum für Freundlichkeit. Tantchen Bernice Steinfeld hat eine Schweinebauchpastete gebacken, weil Billy Maclure ohne eine solche nicht verraten wollte, was er über ihr Familienerbstück wusste. Sie überreicht Euch die Pastete mit unverhohlenem Ärger. Bernice hofft, dass Billy an jedem Bissen erstickt."},{t="Bestechung eines Jungen",b="In den Weinbergen der Maclures auf der anderen Straßenseite wartet Billy Maclure hungrig und kann sich nicht erinnern, was mit der Halskette geschehen ist. Die Rivalität zwischen den beiden Gehöften erfasst auch ihre Kinder. Sie tauschen Klatsch und gestohlene Schmuckstücke gegen Leckereien vom Bauernhof. Sobald die Pastete überbracht ist, erinnert sich Billy, und die Suche nach dem wahren Verbleib der Halskette kann beginnen."}},faq={{q="Welchen Zweck hat diese Lieferung?",a="Billy Maclure behauptet, er wisse, wo Tantchen Bernice Steinfelds verlorene Halskette ist, doch er redet erst, wenn Ihr ihm eine selbst gebackene Schweinebauchpastete bringt. Die Lieferung erfüllt seine Forderung, sodass er verrät, wohin das Erbstück gelangt ist.",al={"warum pastete liefern","was will billy","zurück zu billy ziel"}},{q="Warum ist Tantchen Bernice so wütend auf Billy?",a="Die Familien Steinfeld und Maclure liegen seit Jahren in einer erbitterten bäuerlichen Fehde. Bernice ärgert sich, für ein lästiges Maclure-Kind eine Leckerei zubereiten zu müssen, um ein Erbstück wiederzubekommen, das an ihren Grundstücksgrenzen verschwunden ist.",al={"warum hasst bernice billy","steinfeld maclure streit","warum soll er ersticken"}},{q="Wo ist die Halskette laut Billy tatsächlich?",a="Nachdem Billy die Pastete gegessen hat, verrät er, dass er die Halskette nicht behalten hat. Goldtooth, ein berüchtigter Kobold in der Tiefenschachtmine, hat sie bekommen.",al={"wo ist die halskette","wer hat die halskette genommen","goldtooth verbindung"}},{q="Wo befindet sich Billy Maclure?",a="Billy Maclure ist in den Weinbergen der Maclures, direkt südlich der Straße im zentralen Wald von Elwynn und gegenüber dem Hof der Steinfelds.",al={"billy maclure aufenthaltsort","wo ist billy","billy finden"}},{q="Wer hat die Schweinebauchpastete gebacken?",a="Tantchen Bernice Steinfeld hat die Pastete auf dem Hof der Steinfelds gebacken, nachdem Ihr frische Stücke Eberfleisch aus der nahen Wildnis gesammelt habt.",al={"wer hat die pastete gebacken","pastete koch"}},{q="Beendet diese Quest die Fehde zwischen den Familien?",a="Nein. Die Pastete erfüllt Billys persönliche Bestechungsforderung, während die tiefe Feindschaft zwischen den erwachsenen Steinfelds und Maclures bestehen bleibt.",al={"endet die fehde","steinfeld maclure frieden"}}},fx={["6d42dc77"]={q="Warum schickt Tante Bernice einen Außenstehenden, um sich um Billy zu kümmern?",a="Die erbitterte Fehde zwischen den Steinfelds und den Maclures macht einen direkten Kontakt zwischen den Familien fast unmöglich. Tante Bernice kann es nicht ertragen, selbst einen Fuß auf das Land der Maclures zu setzen – geschweige denn persönlich ein nervtötendes Kind zu bedienen, das Essen als Gegenleistung für gestohlenes Eigentum verlangt. Ein durchreisender Wanderer bietet einen neutralen Boten, der über die Straße gehen, den Kuchen abliefern und dem jungen Billy die Wahrheit entlocken kann, ohne einen offenen Streit zwischen den benachbarten Clans zu entfachen.",al={"warum zurück zu billy schicken","warum nicht bernice selbst","warum braucht tante bernice einen abenteurer"}}},fp="13,218,12.304.0,13.343.1,37.224.0,42.209.0,46.131.1,31.124.0,29.135.0,54.122.0"}
P.entries["quest:840"] = {n="Freiwilliger der Horde",s="Auf Durotars westlicher Straße ziehen Rekruten unter dem Namen Freiwilliger der Horde ins Brachland. Takrin Pathseeker hält jenseits von Klingenhügel Wache und gibt ihnen einen Brief für Kargal Schlachtnarbe, dessen Außenposten den Übergang bewacht.",h="Auf Durotars westlicher Straße ziehen Rekruten unter dem Namen Freiwilliger der Horde ins Brachland.",kw={"brachland","freiwilliger der horde","das wegekreuz","kargal schlachtnarbe","klingenhügel","anwerbungsbrief","der südstrom","takrin pathseeker"},ang={["faction:Horde"]="Für Euch als Mitglied der Horde markiert diese Einberufung den Übergang vom Schutz Durotars zur Verteidigung der Ländereien der Horde in ganz Kalimdor.",["race:Orc"]="Als junger Orc, der das Tal der Prüfungen und Klingenhügel verlässt, folgt Ihr Kargal Schlachtnarbes Ruf als Bewährungsprobe im Dienst des Kriegshäuptlings.",["race:Troll"]="Als Troll der Dunkelspeer schließt Ihr Euch Euren verbündeten Orcs bei diesem Einsatz an, um die Ausbreitung der Horde zu unterstützen und die Ländereien am großen Meer zu sichern."},sec={{t="Über den Südstrom",b="Ihr habt Eure Stärke rund um Klingenhügel bewiesen, und nun werdet Ihr nach Westen gerufen, um der gesamten Horde zu dienen. Takrin Pathseeker bewacht die Straße aus Durotar für seinen Freund, den Veteranen Kargal Schlachtnarbe. Er gibt fähigen Reisenden einen Anwerbungsbrief, den sie über den Südstrom bringen sollen. Für einen Rekruten bedeutet das den ersten offiziellen Auftrag jenseits der neuen Heimat der Orcs."},{t="Verteidigung der Grenze",b="Kargal Schlachtnarbe hält den Außenposten jenseits der Brücke, zwischen Durotars roten Schluchten und dem trockenen Brachland. Er sammelt Rekruten zur Grenzwacht, wo Zentauren, Borstennacken und Expeditionen der Allianz die Grenze auf die Probe stellen. Doch die Horde braucht dort mehr als Wachen. Auch für die Siedlung am Wegekreuz werden frische Kräfte gebraucht."}},faq={{q="Wohin bringe ich den Anwerbungsbrief?",a="Folgt der westlichen Straße aus Klingenhügel und überquert die Holzbrücke über den Südstrom. Kargal Schlachtnarbe wartet am Wachturm der Horde direkt hinter der Grenze, auf der Seite des Brachlands.",al={"wohin gehen","kargal schlachtnarbe standort","abgabeort"}},{q="Wer ist Takrin Pathseeker?",a="Takrin Pathseeker ist ein Späher der Horde an der westlichen Straße außerhalb von Klingenhügel. Er bewacht die Straße und schickt fähige Krieger nach Westen zu seinem Kameraden Kargal Schlachtnarbe.",al={"takrins rolle","wer vergibt die quest","questgeber"}},{q="Wer ist Kargal Schlachtnarbe?",a="Kargal Schlachtnarbe ist ein schroffer, kampferfahrener Offizier am Wachposten im östlichen Brachland. Er mustert eintreffende Freiwillige, unterzeichnet ihre Einberufungspapiere und schickt sie westwärts durch die Savanne, um dem Wegekreuz zu helfen.",al={"wer ist kargal","schlachtnarbes geschichte"}},{q="Was geschieht, nachdem Kargal den Brief unterzeichnet hat?",a="Nachdem Kargal den Brief angenommen hat, verpflichtet er Euch zu weiterem Dienst und schickt Euch auf der Hauptstraße nach Westen, um Euch bei Sergra Dunkeldorn am Wegekreuz zu melden.",al={"nächste quest","was kommt nach freiwilliger der horde","wohin als nächstes"}},{q="Warum wirbt die Horde Soldaten für das Brachland an?",a="Das Brachland ist ein offenes Grenzgebiet, das Orgrimmar mit Mulgore verbindet. Wilde Stämme der Borstennacken, marodierende Zentauren und Vorstöße der Allianz bedrohen die Versorgungswege, daher braucht die Horde jede fähige Hand, um die Straßen zu sichern.",al={"warum einberufung","gefahren im brachland","warum rekrutieren"}},{q="Ist diese Quest für Spieler der Allianz verfügbar?",a="Nein. Dieser Dienst steht nur Mitgliedern der Horde offen, die vom Anfang der Geschichte in Durotar ins Brachland weiterziehen.",al={"kann die allianz das machen","nur für die horde"}}},fx={dfa16f64={q="Warum möchte Takrin Pathseeker, dass Ihr den Anwerbungsbrief überbringt?",a="Takrin Pathseeker dient als vorgeschobener Späher, der die Straße von Durotar in die trockenen Ebenen überwacht. Sein alter Kamerad Kargal Schlachtnarbe kommandiert den Grenzposten direkt auf der anderen Seite des Flusses und hat mit einem ständigen Mangel an fähigen Kriegern zu kämpfen. Da er Potenzial in Eurer Stärke sieht, möchte Takrin frisches Blut direkt in die Garnison im Brachland lenken, um die Verteidigung der Horde zu stärken, anstatt fähige Hände in Klingenhügel untätig zu lassen.",al={"warum schickt takrin mich","takrin pathseeker motiv","warum rekrutieren für kargal"}},["788e36ab"]={q="Warum schickt Takrin einen Abenteurer, anstatt selbst Bericht bei Kargal zu erstatten?",a="Takrin ist damit beauftragt, die wichtige Kreuzung zwischen Durotar und der westlichen Grenze zu überwachen und dabei Reisende sowie Bedrohungen auf der Straße im Auge zu behalten. Seinen Posten zu verlassen, um einzelne Nachrichten zu überbringen, würde seine Pflicht verletzen. Noch wichtiger ist, dass er nach potenziellen Soldaten Ausschau hält, die Kargal unterstützen könnten. Wenn Ihr direkt dem Kommandanten des Außenpostens Bericht erstattet, beweist dies Eure Bereitschaft und Initiative, der Horde zu dienen.",al={"warum geht takrin nicht selbst","warum schickt er mich zu kargal","warum ich conscript of the horde"}}},fp="22,229,22.363.0,14.326.0,39.186.0,25.160.0,25.208.0,43.155.0,53.221.0,44.96.0"}
P.entries["quest:8400"] = {n="Fight for Warsong Gulch",s="Die Allianz sucht an der Front in der Kriegshymnenschlucht Beweise für Euren Mut. Ein dort stationierter Brigadiergeneral der Allianz fordert drei Marks of Honor, die Ihr im Kampf gegen die Horde verdient habt.",h="Die Allianz sucht an der Front in der Kriegshymnenschlucht Beweise für Euren Mut.",kw={"allianz","eschental","schlachtfelder","brigadiergeneral","marks of honor","kriegshymnenschlucht"},ang={["faction:Alliance"]="Als Soldat der Allianz beweist Ihr mit Euren Kampfmarken beim Brigadiergeneral Euren Einsatz im andauernden Kampf gegen die Horde in der Kriegshymnenschlucht."},sec={{t="Der Ruf des Generals",b="Ein Brigadiergeneral der Allianz nahe dem Schlachtfeld ruft die von der Front zurückkehrenden Soldaten zu sich. Wenn Ihr in der Kriegshymnenschlucht gekämpft habt, belegen drei Marks of Honor Euren Rang und Eure Taten gegen die Horde. Diese Marken zur obersten Führung zurückzubringen, zeigt, dass die Allianz ihre Stellung in der umkämpften Schlucht hält."}},faq={{q="Wer nimmt die Marks of Honor aus der Kriegshymnenschlucht entgegen?",a="Ein Brigadiergeneral der Allianz außerhalb des Schlachtfelds sammelt die Marken, um den Kriegsverlauf zu verfolgen.",al={"wer will marks of honor","brigadiergeneral marken"}},{q="Wie viele Marken müsst Ihr mitbringen?",a="Drei Marks of Honor aus der Kriegshymnenschlucht sind nötig, um Eure Taten auf dem Schlachtfeld zu belegen.",al={"wie viele marken wsg","benötigte marken kriegshymnenschlucht"}},{q="Wo ist der Brigadiergeneral der Allianz?",a="Der Brigadiergeneral wartet außerhalb der Schlachtfelder, wo die Allianz ihre Truppen koordiniert.",al={"wo ist der brigadiergeneral","standort allianzgeneral"}}},fp="23,198,18.327.0,43.107.0,36.85.0,40.96.0"}
P.entries["quest:841"] = {n="Eine weitere Kraftquelle?",s="In Gadgetzan bietet Euch Chefingenieur Bilgewhizzle für zehn Wastewander Water Pouches eine weitere Energiequelle an.",h="In Gadgetzan bietet Euch Chefingenieur Bilgewhizzle für zehn Wastewander Water Pouches eine weitere...",kw={"bilgewhizzle","gadgetzan","energiequelle","tanaris","wastewander","wasserbeutel"},sec={{t="Ein kostspieliger Ersatz",b="Chefingenieur Bilgewhizzle glaubt, dass die Zeit der ersten Energiequelle abgelaufen ist oder sie im Sand verloren ging. Was auch geschehen ist, er hat eine weitere, die er Euch verkaufen kann. Die Zeiten sind überall hart, also verlangt er zehn Wastewander Water Pouches."}},faq={{q="Warum will Chefingenieur Bilgewhizzle Wastewander water pouches haben?",a="Chefingenieur Bilgewhizzle verlangt zehn Wastewander Water Pouches im Tausch gegen eine weitere Energiequelle. Die Zeiten sind überall hart.",al={"bilgewhizzle wasserbeutel","warum wasserbeutel"}},{q="Wer bietet diesen Tausch an?",a="Chefingenieur Bilgewhizzle bietet den Tausch an und hat weitere Energiequellen zu verkaufen.",al={"wer startet eine weitere kraftquelle","energiequelle questgeber"}},{q="Was geschah, bevor eine weitere Energiequelle nötig wurde?",a="Dies folgt auf Slake That Thirst, als Ihr erstmals eine Energiequelle für Eure Ausrüstung erhalten habt.",al={"voraussetzung eine weitere kraftquelle","vorherige quest energiequelle"}}},fp="21,108,20.225.0,68.132.0,25.83.0,52.84.0"}
P.entries["quest:84147"] = {n="An Earnest Proposition",s="Deliana in Eisenschmiede bietet Euch bessere Wildheart Bracers im Tausch gegen einen Gefallen. Sie bittet Euch um Blut aus Winterquell, Gold und Eure gewöhnlichen Armschienen.",h="Deliana in Eisenschmiede bietet Euch bessere Wildheart Bracers im Tausch gegen einen Gefallen.",kw={"ein ernst gemeintes angebot","rüstung eintauschen","bärenblut","deliana","frostsaberblut","eisenschmiede","wildheart bracers","winterquell"},sec={{t="Delianas Angebot",b="In Eisenschmiede besitzt Deliana feinere Armschienen und bietet Euch an, sie gegen Eure Wildheart Bracers einzutauschen. Sie bittet Euch, ihr Blut von den frostsabers und Bären aus Winterquell sowie Gold zu bringen. Der Tausch gilt für ein Stück, doch Deliana sagt, sie könnte den Rest des Sets für weitere Arbeit herausgeben."}},faq={{q="Wer bittet um die Armschienen?",a="Deliana in Eisenschmiede bietet Euch feinere Armschienen im Tausch gegen Eure Wildheart Bracers an.",al={"wer ist deliana","armschienen eintauschen"}},{q="Was möchte Deliana von mir?",a="Deliana bittet um Blut von frostsabers und Bären aus Winterquell, Eure Wildheart Bracers und Gold.",al={"was braucht sie","delianas gefallen"}},{q="Warum möchte sie Blut aus Winterquell?",a="Deliana sagt, sie braucht das Blut der frostsabers und Bären aus Winterquell.",al={"frostsaberblut","bärenblut"}},{q="Welche Rüstung bietet Deliana an?",a="Sie bietet Armschienen an, wie sie von Eurem Beruf getragen werden, aber von höherer Qualität.",al={"welche armschienen","bessere rüstung"}},{q="Kann Deliana weitere Rüstungsteile eintauschen?",a="Deliana sagt, sie könnte den Rest der Rüstungsteile hergeben, wenn Ihr Interesse habt, weitere Arbeit für sie zu erledigen.",al={"rest des sets","weitere arbeit"}}},fp="22,145,15.305.0,30.82.0,31.97.0,37.73.0,31.92.0,36.107.0"}
P.entries["quest:842"] = {n="Wegekreuzwehrpflicht",s="Kargal Schlachtnarbe schickt Rekruten von der Fernwacht nach Westen, um sich zur Wegekreuzwehrpflicht zu melden. Mit seinem unterzeichneten Brief macht Ihr Euch zu Sergra Dunkeldorn am zentralen Knotenpunkt des Brachlands auf.",h="Kargal Schlachtnarbe schickt Rekruten von der Fernwacht nach Westen, um sich zur Wegekreuzwehrpflicht zu...",kw={"brachland","schlachtnarbe","wehrpflicht","das wegekreuz","darkthorn","fernwacht","kargal","sergra","thrall"},ang={["class:Shaman"]="Als Schamane erlebt Ihr, wie Sergra Dunkeldorn an einem strategischen Außenposten als spirituelle Beraterin, militärische Befehlshaberin und Verwalterin führt.",["faction:Horde"]="Als Mitglied der Horde verlasst Ihr die Sicherheit Eurer Heimat, um in der umkämpften Wildnis des Brachlands zu dienen.",["race:Orc"]="Als Orc könnt Ihr sehen, wie sich Thralls Horde wandelt, während Verdienst und spirituelle Einsicht die alten Clanbräuche des traditionellen Grunzerdienstes infrage stellen."},sec={{t="Zum Dienst melden",b="Nachdem Ihr Euch bewiesen habt, schickt Kargal Schlachtnarbe Euch von der Fernwacht nach Westen. Er gibt Euch einen unterzeichneten Rekrutierungsbrief für die Reise auf dem festgetretenen Feldweg durch das dürre Gestrüpp des Brachlands. Die Straße erreicht eine zentrale Kreuzung, an der das Wegekreuz das nördliche Kalimdor mit der südlichen Wildnis verbindet."},{t="Die Schamanin des Wegekreuzes",b="Am Wegekreuz empfängt Sergra Dunkeldorn Neuankömmlinge. Kriegshäuptling Thrall hat die scharfzüngige Orcschamanin ausgewählt, um die dortigen Einsätze zu leiten. Kargal Schlachtnarbe murrt, sie sei schwierig und rede zu viel, doch Thrall schätzt sie sehr.\n\nSergra ist grimmig und unnachgiebig. Sie erinnert Rekruten, besonders arrogante Männer, daran, dass Kriegerinnen und Anführerinnen in Thralls Horde gleichberechtigt sind. Unverschämtheit hat hier keinen Platz."}},faq={{q="Wer gibt mir diese Quest?",a="Kargal Schlachtnarbe, ein Orcveteran an der Fernwacht gleich westlich der Brücke zwischen Durotar und dem Brachland, schickt Euch mit einem Brief für Sergra nach Westen.",al={"wer vergibt wegekreuzwehrpflicht","questgeber wegekreuzwehrpflicht","kargals quest"}},{q="Wo befindet sich Sergra Dunkeldorn?",a="Sergra Dunkeldorn steht nahe der Straßenkreuzung im Zentrum des Wegekreuzes, wo Karawanen und Boten zusammentreffen.",al={"sergra darkthorn standort","wo ist sergra","sergra darkthorn finden"}},{q="Warum beschwert sich Kargal über Sergra?",a="Kargal findet Sergra anstrengend. Er nennt sie eine widerliche Schamanin, die um den heißen Brei herumredet, bevor jemand praktisch arbeiten kann, doch er respektiert Thralls Befehl, ihr Rekruten zu schicken.",al={"warum mag kargal sergra nicht","kargal gegen sergra","verflucht sei ihr fell"}},{q="Warum spricht Sergra unterschiedlich mit männlichen und weiblichen Charakteren?",a="Sergra ist stolz auf Thralls Gebot der Gleichberechtigung für Kriegerinnen in der Horde. Sie ermutigt weibliche Rekruten und warnt männliche Rekruten, dass sie weder Respektlosigkeit noch Unverschämtheit duldet.",al={"sergra dialog männlich weiblich","sergra darkthorn dialog","sergra gleichberechtigung"}},{q="Welchen Weg sollte ich zum Wegekreuz nehmen?",a="Folgt der Hauptstraße von der Fernwacht nach Westen bis zu einer T-Kreuzung. Biegt links ab und folgt der Straße nach Süden ins Wegekreuz.",al={"wie zum wegekreuz gelangen","wegbeschreibung zum wegekreuz","weg zum wegekreuz"}},{q="Was geschieht, nachdem ich mich bei Sergra Dunkeldorn gemeldet habe?",a="Sergra nimmt Eure Hilfe am Wegekreuz an und schickt Euch los, um im gesamten zentralen Brachland bei örtlichen Bedrohungen, der Jagd und der Sicherung der Außenposten zu helfen.",al={"was kommt nach wegekreuzwehrpflicht","nächste quest sergra","brachland rekruten danach"}}},fx={["3243ab88"]={q="Warum schickt mich Kargal Schlachtnarbe zum Wegekreuz?",a="Als Kommandant der Fernwacht verarbeitet Kargal frische Wehrpflichtige, die aus Durotar ins Brachland kommen. Anstatt jeden kampffähigen Kämpfer an einem Eingangsposten zu behalten, ist es seine Pflicht gegenüber der Horde, neue Rekruten tiefer in die Grenzgebiete zu schicken. Das Wegekreuz dient als zentraler Knotenpunkt der Autorität der Horde und der militärischen Mobilisierung im Brachland, wo Arbeitskräfte dringend benötigt werden, um die umliegenden Ländereien unter der Aufsicht von Sergra Dunkeldorn zu sichern.",al={"warum zum das wegekreuz schicken","kargal motiv crossroads conscription","warum bei sergra melden"}},["07e83289"]={q="Warum schickt Kargal mich anstelle eines seiner Wachen?",a="Ihr seid ein ankommender Wehrpflichtiger, der sich beweisen und seinen Unterhalt innerhalb der Horde verdienen will. Kargals Wachen am Außenposten sind bereits damit beauftragt, den Grenzwachtposten gegen lokale Bedrohungen zu besetzen. Euch zusammen mit einem unterschriebenen Anwerbungsbrief loszuschicken, verstärkt sowohl den Außenposten am Wegekreuz als auch testet es, ob ein neuer Rekrut die Disziplin besitzt, allein durch die wilden Ebenen zu navigieren und Befehle zu befolgen.",al={"warum braucht kargal mich","warum keine wache zum das wegekreuz schicken","warum ich kargal"}}},fp="23,184,18.318.0,28.425.0,27.153.0,34.111.0,38.185.0,64.193.0,49.130.0,49.145.0"}
P.entries["quest:8426"] = {n="Battle of Warsong Gulch",s="Ein Warbringer der Horde bittet Euch, drei Marks of Honor der Kriegshymnenschlucht zu bringen. Die Marken sind der für diesen Aufruf verlangte Nachweis.",h="Ein Warbringer der Horde bittet Euch, drei Marks of Honor der Kriegshymnenschlucht zu bringen.",kw={"schlachtfelder","horde","marks of honor","warbringer","kriegshymnenschlucht"},ang={["faction:Horde"]="Als Mitglied der Horde könnt Ihr die Marks of Honor der Kriegshymnenschlucht zu einem Warbringer der Horde bringen."},sec={{t="Eine zurückgebrachte Marke",b="Ihr bringt die drei Marks of Honor der Kriegshymnenschlucht zu einem Warbringer der Horde außerhalb der Schlachtfelder. Der Warbringer verlangt diese Marken, und mehr erfordert dieser Aufruf nicht."}},faq={{q="Was verlangt der Warbringer?",a="Der Warbringer der Horde bittet Euch, drei Marks of Honor der Kriegshymnenschlucht zu bringen.",al={"welche marken","warbringer will","was bringen"}},{q="Wohin bringe ich die Marken?",a="Bringt die Marken zu einem Warbringer der Horde außerhalb der Schlachtfelder.",al={"wo warbringer","marken abgeben","wohin bringen"}},{q="Wie viele Marken werden benötigt?",a="Der Warbringer verlangt drei Marks of Honor der Kriegshymnenschlucht.",al={"wie viele marken","anzahl der marken","drei marken"}}},fp="23,121,15.170.0,33.74.0,27.64.0,26.59.0"}
P.entries["quest:8427"] = {n="Battle of Warsong Gulch",s="Ein Warbringer der Horde außerhalb der Kriegshymnenschlucht bittet Euch, drei Warsong Gulch Marks of Honor zu bringen. Die Marken werden für diesen Tausch benötigt.",h="Ein Warbringer der Horde außerhalb der Kriegshymnenschlucht bittet Euch, drei Warsong Gulch Marks of Honor zu...",kw={"schlacht","schlachtfeld","horde","ehrenmarken","warbringer","kriegshymnenschlucht"},faq={{q="Was verlangt der Warbringer?",a="Der Warbringer der Horde bittet Euch, drei Warsong Gulch Marks of Honor zu bringen.",al={"marken aus der kriegshymnenschlucht","ehrenmarken","was bringen"}},{q="Wohin soll ich die Marken bringen?",a="Bringt die Marken zu einem Warbringer der Horde außerhalb der Schlachtfelder.",al={"wo ist der warbringer","marken abgeben","warbringer der kriegshymnenschlucht"}},{q="Wie viele Marken werden benötigt?",a="Der Warbringer verlangt drei Warsong Gulch Marks of Honor.",al={"wie viele marken","drei marken","anzahl der marken"}}},fp="23,136,33.74.0,27.64.0,26.59.0"}
P.entries["quest:843"] = {n="Ganns Rekultivierung",s="Im südlichen Brachland richtet sich Ganns Rekultivierung gegen Bael Modan. Gann Steinkeil, ein verbannter Taure, bittet Euch, die Ausgrabung anzugreifen, nachdem sie ihn aus der angestammten Heimat und den Jagdgründen seines Clans vertrieben hat.",h="Im südlichen Brachland richtet sich Ganns Rekultivierung gegen Bael Modan.",kw={"bael modan","bael'dun","ausgrabungsstätte der zwerge","gann steinkeil","khazgorm","südliches brachland"},ang={["class:Shaman"]="Als Schamane wisst Ihr, dass die Sprengungen und tiefen Gräben von Bael Modan die Erdgeister der Umgebung verletzen. Ganns Feldzug ist eine notwendige Reinigung von dieser elementaren Störung.",["faction:Horde"]="Als Mitglied der Horde seht Ihr in Bael Modan einen befestigten Stützpunkt der Allianz tief in Kalimdor. Ganns Anspruch zu verteidigen, ist eine Frage der Ehre und eine Möglichkeit, diesen Stützpunkt einzudämmen.",["race:Tauren"]="Als Shu'halo könnt Ihr Ganns Notlage als empörende Erinnerung daran sehen, wie wenig Respekt die Allianz der Earth Mother entgegenbringt. Dynamit und eiserne Zahnräder reißen die Grabstätten der Ahnen auf."},sec={{t="Ein vertriebener Stamm",b="Gann Steinkeil wandert allein die südliche Straße entlang und sucht Gerechtigkeit für seine gefallenen Angehörigen. Sein Clan lebte zwischen den roten Klippen südlich des Brachlands. Zwerge aus Eisenschmiede errichteten dort Bael Modan und vertrieben oder töteten die Tauren, um Platz für Steinbrüche und Gräben zu schaffen. Gann sagt, friedliche Proteste und Diplomatie seien gescheitert. Nun sucht er Rache für seinen vertriebenen und erschlagenen Clan."},{t="Die Ruinen von Bael Modan",b="Bei Bael Modan reißen zwergische Ausgräber mit Dampfmaschinen und Sprengstoff die Hügel auf. Prospektor Khazgorm leitet die Ausgrabung tief unter der Erde. Gann bittet Euch, die Reihen der Ausgräber und Vorarbeiter der Bael'dun zu lichten, Khazgorm zu töten und die persönlichen Ausgrabungsnotizen des Prospektors zurückzubringen. Er will erfahren, wonach die Expedition der Allianz im heiligen Boden sucht."}},faq={{q="Wer ist Gann Steinkeil?",a="Gann Steinkeil ist ein einsamer überlebender Taure, dessen Stamm einst im südlichen Brachland lebte. Zwergische Ausgräber vertrieben sein Volk von seinem Land und töteten jene, die Widerstand leisteten. Nun wandert er die südliche Landstraße entlang und sucht Gerechtigkeit und Rache an der Ausgrabungsstätte der Allianz.",al={"gann","wer vergibt ganns rekultivierung","gann steinkeil hintergrundgeschichte"}},{q="Warum sind die Zwerge im Brachland?",a="Die Zwerge gehören zu einer Expedition aus Eisenschmiede namens Bael'dun. Sie errichteten eine Festung und eine Ausgrabungsstätte bei Bael Modan im südlichen Brachland, wo ihre Sprengungen und lärmenden Maschinen ungeachtet der einheimischen Tauren die Hügel zerreißen.",al={"warum sind zwerge bei bael modan","zweck von bael modan","eisenschmiede im brachland"}},{q="Wer ist Prospektor Khazgorm?",a="Prospektor Khazgorm leitet die zwergische Ausgrabung südlich der Festung Bael Modan. Gann macht ihn für die Entweihung seines angestammten Landes verantwortlich und verlangt sein Tagebuch als Beweis für seinen Tod.",al={"khazgorm","prospektor khazgorm","anführer von bael modan"}},{q="Wo ist Gann Steinkeil zu finden?",a="Gann Steinkeil wandert die Straße im äußersten Süden des Brachlands entlang, westlich der Festung Bael Modan und nördlich der Straße zum Großen Aufzug und nach Tausend Nadeln.",al={"gann aufenthaltsort","gann finden","wo ist gann"}},{q="Hat Gann versucht, dies friedlich zu lösen?",a="Ja. Gann sagt, er habe es mit Diplomatie und anderen friedlichen Mitteln versucht, um die Zerstörung seines angestammten Landes aufzuhalten. Die Zwerge wiesen seine Bemühungen zurück und sprengten weiter die Hügel, also griff er zur Gewalt.",al={"haben tauren diplomatie versucht","gann diplomatie"}},{q="Was geschieht nach dieser Quest?",a="Nachdem Gann Khazgorms Tagebuch erhalten hat, studiert er die Notizen, um die Technik und die Pläne der Zwerge zu verstehen. Dann will er ihre schweren Maschinen sabotieren.",al={"nächste quest nach ganns rekultivierung","gann folgequest"}}},fx={["5ecef431"]={q="Warum will Gann Steinkeil die Zwerge vertreiben?",a="Bael Modan liegt direkt auf dem angestammten Land von Ganns Stamm. Als die Zwerge ankamen, vertrieben ihr unerbittliches Graben, laute Maschinen und Sprengungen die Tauren aus ihrem Zuhause und kosteten viele unschuldige Leben. Nachdem er alle friedlichen Ansätze ausgeschöpft hat, sucht Gann Vergeltung und will die heilige Heimat seines Volkes mit Gewalt zurückfordern.",al={"gann motiv","warum bael modan zwerge töten","warum will gann rache"}},fd3e714a={q="Wozu dient Khazgorms Tagebuch?",a="Das Tagebuch gehört Prospektor Khazgorm, dem Anführer, der die zerstörerische Ausgrabungsstätte Bael Modan beaufsichtigt. Gann möchte die Seiten studieren, um Einblicke in die Operationen der Zwerge, ihre Motive in der Region und die beste Art und Weise zu gewinnen, ihre anhaltende Zerstörung seines angestammten Territoriums zu stoppen.",al={"verwendung khazgorms tagebuch","warum khazgorms tagebuch sammeln","was will gann mit dem tagebuch"}},["4442e883"]={q="Warum bittet Gann Euch, anstatt die Ausgrabung selbst zu erledigen?",a="Gann wandert völlig allein durch das Südliches Brachland, ein Exilant, dessen Stamm durch die Ankunft der Zwerge abgeschlachtet oder vertrieben wurde. Da er vor einer befestigten Siedlung steht, die von Dutzenden bewaffneter Ausgräber, Vorarbeiter und deren Anführer besetzt ist, kann er nicht hoffen, die Eindringlinge ohne einen fähigen Champion zu vertreiben, der in seinem Namen kämpft.",al={"warum kann gann es nicht selbst tun","warum braucht gann hilfe","warum ich gann"}}},fp="18,202,17.379.0,23.355.0,23.270.0,35.238.0,27.190.0,35.163.0,40.195.0,30.158.1"}
P.entries["quest:8431"] = {n="Battle of Warsong Gulch",s="Die Horde will ihren Besitzanspruch auf die Kriegshymnenschlucht sichern. Eure Hilfe stärkt diesen Anspruch.",h="Die Horde will ihren Besitzanspruch auf die Kriegshymnenschlucht sichern.",kw={"schlacht","schlucht","horde","besitz","kriegshymnenschlucht"},ang={["faction:Horde"]="Ihr helft der Horde, ihren Besitz der Kriegshymnenschlucht zu sichern."},sec={{t="Ein Anspruch in der Schlucht",b="Der Anspruch der Horde auf die Kriegshymnenschlucht steht auf dem Spiel, und Ihr helft mit Eurer Stärke, ihn zu sichern. Eure Bemühungen tragen dazu bei, dass die Horde die Schlucht behält."}},faq={{q="Was geschieht in der Kriegshymnenschlucht?",a="Die Horde will sich ihren Besitz der Kriegshymnenschlucht sichern.",al={"schlacht um die kriegshymnenschlucht","was geschieht in der schlucht"}},{q="Wem helfe ich?",a="Ihr helft der Horde, ihren Besitz der Kriegshymnenschlucht zu sichern.",al={"wer bittet um hilfe","für welche seite ist das"}},{q="Was will die Horde?",a="Die Horde will die Kriegshymnenschlucht behalten.",al={"ziel der horde","warum in der kriegshymnenschlucht kämpfen"}}},fp="23,88,20.153.0,35.62.0,17.64.0,25.55.0"}
P.entries["quest:8436"] = {n="Conquering Arathi Basin",s="Ein Horde-Kriegshetzer bittet Euch um drei Arathibecken Marks of Honor. Bringt sie vom Schlachtfeld zum Kriegshetzer vor dessen Toren.",h="Ein Horde-Kriegshetzer bittet Euch um drei Arathibecken Marks of Honor.",kw={"arathibecken","schlachtfeld","horde-kriegshetzer","mark of honor","marks of honor"},sec={{t="Die Bitte eines Kriegshetzers",b="Der Kriegshetzer wartet außerhalb der Schlachtfelder, wohin Ihr die Marken bringen könnt. Die Horde bittet Euch, drei Arathibecken Marks of Honor zu bringen."}},faq={{q="Was möchte der Horde-Kriegshetzer?",a="Der Horde-Kriegshetzer bittet Euch, drei Arathibecken Marks of Honor zu bringen.",al={"was der kriegshetzer möchte","was bringen","arathibecken-marken"}},{q="Wohin soll ich die Marken bringen?",a="Bringt die Marken zu einem Horde-Kriegshetzer außerhalb der Schlachtfelder.",al={"wohin die marken bringen","standort des kriegshetzers","außerhalb des schlachtfelds"}},{q="Wie viele Marks of Honor werden benötigt?",a="Ihr sollt drei Arathibecken Marks of Honor bringen.",al={"wie viele marken","drei marken","anzahl der marken"}},{q="Nach welchen Marken fragt der Kriegshetzer?",a="Verlangt werden Arathibecken Marks of Honor.",al={"welche marken","arathibecken-marke","marks of honor"}}},fp="23,129,22.149.0,36.73.0,27.64.0,35.57.0,40.47.0"}
P.entries["quest:8437"] = {n="Conquering Arathi Basin",s="Ein Horde Warbringer außerhalb der Schlachtfelder bittet Euch, drei Arathibecken Marks of Honor zu bringen.",h="Ein Horde Warbringer außerhalb der Schlachtfelder bittet Euch, drei Arathibecken Marks of Honor zu bringen.",kw={"arathibecken","schlachtfeld","arathibecken erobern","horde warbringer","marke der ehre"},faq={{q="Was möchte der Horde Warbringer?",a="Der Horde Warbringer bittet Euch, drei Arathibecken Marks of Honor zu bringen.",al={"bitte des warbringers","was bringen"}},{q="Wo soll ich die Marken abgeben?",a="Bringt die Marken zu einem Horde Warbringer außerhalb der Schlachtfelder.",al={"wohin mit den marken","standort des warbringers"}},{q="Wie viele Marks of Honor werden benötigt?",a="Ihr benötigt drei Arathibecken Marks of Honor.",al={"wie viele marken","drei marken"}}},fp="23,97,36.73.0,27.64.0,35.43.0"}
P.entries["quest:84396"] = {n="Magma or Lava?",s="Jennea Haubitz sucht magische Schriften, um die Bibliothek im Mage Quarter von Sturmwind zu erweitern. Neue Schriften bereichern den Vorrat der Stadt an arkanem Wissen.",h="Jennea Haubitz sucht magische Schriften, um die Bibliothek im Mage Quarter von Sturmwind zu erweitern.",kw={"arkan","sammlung","jennea haubitz","library","mage quarter","magische werke","magma oder lava","sturmwind"},sec={{t="Seiten für die Regale",b="Im Magiersanktum im Mage Quarter von Sturmwind baut Jennea Haubitz ein wachsendes Archiv arkaner Studien auf. Wenn Eure Reisen Euch magische Schriften bescheren, bittet sie Euch, diese für die Bibliothek zu ihr zu bringen. Jeder neue Text erweitert das Wissen der Gelehrten im Magiersanktum über die Welt."}},faq={{q="Wer möchte magische Schriften für die Bibliothek?",a="Jennea Haubitz sammelt im Mage Quarter von Sturmwind magische Schriften, um die Sammlung der Bibliothek zu erweitern.",al={"magma oder lava in der bibliothek","wohin magische werke bringen","buch für die bibliothek von sturmwind"}},{q="Was wird für die Sammlung zusammengetragen?",a="Die Sammlung wächst, wann immer Reisende magische Schriften und Aufzeichnungen zur Library bringen.",al={"was braucht die library","was sammeln sie"}},{q="Warum sucht die Library nach diesen Schriften?",a="Jennea Haubitz freut sich über magische Schriften von Reisenden, damit das Wissen des Sanktums weiter wächst.",al={"warum bücher zur library bringen","zweck von magma oder lava"}}},fp="14,171,21.280.0,39.99.0,42.92.0,41.100.0"}
P.entries["quest:84399"] = {n="Ka-Boom!",s="Jennea Haubitz bittet Euch, ihr magische Werke zu bringen, die Ihr auf Euren Reisen entdeckt. Jeder Beitrag erweitert die Sammlung der Bibliothek im Mage Quarter von Sturmwind.",h="Jennea Haubitz bittet Euch, ihr magische Werke zu bringen, die Ihr auf Euren Reisen entdeckt.",kw={"sammlung","jennea haubitz","ka-boom!","library","mage quarter","magische werke","sturmwind"},sec={{t="Die Sammlung erweitern",b="Im Magiersanktum in Sturmwind arbeitet Jennea Haubitz daran, den Bestand der Bibliothek an arkanem Wissen zu erweitern. Wenn Ihr auf Euren Reisen magische Werke entdeckt, bittet sie Euch, ihr diese Schriften zu bringen, damit die Sammlung wachsen kann."}},faq={{q="Wonach sucht die Bibliothek?",a="Jennea Haubitz sucht magische Werke, um die Wissenssammlung der Bibliothek zu erweitern.",al={"was möchte die bibliothek","was zur bibliothek bringen","welche werke sammelt die bibliothek"}},{q="Wer bittet um diese magischen Werke?",a="Jennea Haubitz im Mage Quarter von Sturmwind freut sich über Ergänzungen für die Bibliothek und bittet Reisende, magische Schriften abzuliefern, die sie entdecken.",al={"wer möchte magische werke","wohin mit magischen werken","wer sammelt wissen in sturmwind"}},{q="Könnt Ihr später weitere magische Werke bringen?",a="Jennea bittet Euch, alle weiteren magischen Werke, die Ihr entdeckt, zu ihr ins Mage Quarter zu bringen, damit die Sammlung der Bibliothek weiter wächst.",al={"soll ich magische bücher behalten","kann ich weitere bücher bringen","was tun mit gefundenen magischen werken"}}},fp="8,166,24.232.0,32.82.0,33.136.0,39.141.0"}
P.entries["quest:844"] = {n="Ebenenschreiterbedrohung",s="Östlich vom Wegekreuz bedrohen Ebenenschreiter die Nahrungsvorräte des Außenpostens. Sergra Dunkeldorn schickt neu eingetroffene Mitglieder der Horde auf die Jagd nach ihnen und lässt sie so das Brachland erstmals kennenlernen.",h="Östlich vom Wegekreuz bedrohen Ebenenschreiter die Nahrungsvorräte des Außenpostens.",kw={"brachland","schnabel","das wegekreuz","darkthorn","jagd","ebenenschreiter","sergra","vorräte"},ang={["class:Hunter"]="Als junger Jäger lernt Ihr, Euch in der weitläufigen Savanne an Wild heranzupirschen, seine Fährte zu lesen und es zu erlegen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr, das Wegekreuz, einen wichtigen Versorgungsknotenpunkt, zu schützen und seine Nahrungsvorräte zu sichern, damit die Horde sich in ganz Kalimdor behaupten kann.",["race:Orc"]="Als Ork ehrt Ihr die Disziplin der Jagd. Sergra erwartet, dass Ihr Euch gegen die heimischen Bestien bewährt, bevor Ihr gewichtigere Pflichten übernehmt."},sec={{t="Das Wegekreuz sichern",b="Das Wegekreuz koordiniert die Versorgung in ganz Kalimdor. Nun picken Ebenenschreiter östlich des Außenpostens an seinen Nahrungskisten. Sergra Dunkeldorn, eine Orkschamanin, schickt frisch eingetroffene Abenteurer der Horde auf die Jagd nach den Vögeln, bevor sie die Vorräte beschädigen. Die Siedlung ist auf diese Vorräte angewiesen."},{t="Die erste Jagd",b="Sergra Dunkeldorn nutzt die Jagd, um Neuankömmlinge zu prüfen und die Vorräte der Siedlung zu schützen. Für sie sind Ebenenschreiter leichte Beute, an der junge Jäger lernen können, den Elementen zu trotzen und Wild durch die sonnenverbrannten Ebenen zu verfolgen. Ihre scharfen Schnäbel zurückzubringen beweist Geduld und das grundlegende Kampfgeschick, das nötig ist, um sich gefährlicheren Bestien des Brachlands zu stellen."}},faq={{q="Warum werden die Ebenenschreiter gejagt?",a="Die Ebenenschreiter östlich vom Wegekreuz sind dreist geworden, plündern Nahrungsvorräte und stören den Nachschub auf den vorbeiführenden Versorgungswegen. Sergra Dunkeldorn ordnet die Jagd an, um die Vorräte der Siedlung zu schützen.",al={"warum ebenenschreiter töten","ebenenschreiterproblem","was haben ebenenschreiter getan"}},{q="Wer ist Sergra Dunkeldorn?",a="Sergra Dunkeldorn ist eine erfahrene Orkschamanin, die im Wegekreuz stationiert ist. Sie beaufsichtigt Jagdprüfungen, bildet neu eintreffende Abenteurer aus und schickt sie gegen wilde Bestien aus, die die Unternehmungen der Horde bedrohen.",al={"wer ist sergra","sergra darkthorns rolle","questgeber im wegekreuz"}},{q="Warum will Sergra gerade ihre Schnäbel?",a="Ein Ebenenschreiter nutzt seinen harten, scharfen Schnabel als Hauptwaffe und als Werkzeug zur Nahrungssuche. Den Schnabel zurückzubringen beweist, dass der Vogel erlegt wurde.",al={"warum ebenenschreiterschnäbel","ebenenschreiterschnabel als beweis"}},{q="Was folgt auf diese Jagd?",a="Nach den Ebenenschreitern schickt Sergra Euch auf die Jagd nach zhevra, schnellerer und temperamentvollerer Beute, die durch die Ebenen streift.",al={"was kommt als nächstes","nächste quest nach ebenenschreitern","jagdreihenfolge"}},{q="Wo befinden sich diese Ebenenschreiter?",a="Ebenenschreiter durchstreifen das Grasland der Savanne östlich und südöstlich vom Wegekreuz und suchen entlang der Handelsstraßen nach Nahrung.",al={"wo sind ebenenschreiter","fundorte von ebenenschreitern","jagdgebiete"}},{q="Ist dies Teil einer größeren Jagdreihe?",a="Ja. Damit beginnen Sergra Darkthorns Jagdprüfungen im Brachland. Die Prüfungen werden gefährlicher, wenn es gegen wildere Bestien in der gesamten Savanne geht.",al={"jagdquestreihe im brachland","sergras questreihe"}}},fx={["416dd73a"]={q="Warum braucht Sergra Dunkeldorn einen Abenteurer statt der Wachen des Wegekreuzes?",a="Die Wachen am Wegekreuz haben alle Hände voll damit zu tun, die äußeren Verteidigungsanlagen gegen Stacheleberüberfälle zu halten und die örtlichen Wege zu sichern. Die Jagd auf lästige Aasfresser draußen in den Ebenen erfüllt für Sergra einen doppelten Zweck: Sie entlastet die Nahrungsversorgung der Siedlung und prüft zugleich, ob Neuankömmlinge die nötigen Fähigkeiten im Spurenlesen und Kampf besitzen, um im Brachland zu überleben.",al={"warum wird man selbst geschickt","warum töten die wachen die ebenenschreiter nicht","warum abenteurer für ebenenschreiter"}}},fp="19,188,23.286.0,14.345.0,35.186.0,24.201.0,46.142.0,27.107.0,38.111.0,40.150.0"}
P.entries["quest:84400"] = {n="The Knight and the Lady",s="Ein Hüter in Eisenschmiede bittet Euch, magische Werke zu bringen, die der Library nützen könnten. So helft Ihr ihrer Sammlung zu wachsen.",h="Ein Hüter in Eisenschmiede bittet Euch, magische Werke zu bringen, die der Library nützen könnten.",kw={"sammlung","eisenschmiede","hüter","wissen","library","magische werke"},sec={{t="Eine wachsende Sammlung",b="Ein Hüter in der Library von Eisenschmiede sucht magische Werke für seine Sammlung. Ihr könnt Werke bringen, die der Library nützen könnten, und der Hüter freut sich über weitere Ergänzungen, während sein Wissen wächst."}},faq={{q="Was möchte der Hüter?",a="Der Hüter bittet Euch, magische Werke zu bringen, die der Sammlung der Library nützen könnten.",al={"was möchten sie","anfrage der library","was bringen"}},{q="Wo befindet sich die Sammlung?",a="Die Sammlung befindet sich in der Library von Eisenschmiede.",al={"wo ist die library","standort der library","library von eisenschmiede"}},{q="Warum magische Werke bringen?",a="Der Hüter sagt, Eure Bemühungen erweitern das Wissen der Library.",al={"warum bücher","wozu","der library helfen"}}},fp="23,122,20.192.0,26.87.0,24.46.0,24.60.0"}
P.entries["quest:845"] = {n="Die Zhevras",s="Am Wegekreuz schickt Sergra Dunkeldorn junge Krieger der Horde auf Zhevrajagd. Ihre Prüfung bereitet sie auf die gefährlicheren Tiere des Brachlands vor.",h="Am Wegekreuz schickt Sergra Dunkeldorn junge Krieger der Horde auf Zhevrajagd.",kw={"brachland","das wegekreuz","hufe","jagdprüfung","sergra darkthorn","zhevra","zhevraläufer"},ang={["class:Hunter"]="Als Jäger, der das Brachland kennenlernt, könnt Ihr beim Anschleichen an flinke Zhevraherden Eure Fährtenlesekunst und Treffsicherheit schulen.",["faction:Horde"]="Als Mitglied der Horde helft Ihr dem Wegekreuz, die Tierbestände der Umgebung zu regulieren und seine Versorgungswege freizuhalten.",["race:Tauren"]="Als Tauren wisst Ihr, wie wuchtig der Tritt einer Zhevra sein kann. Sergra warnt, dass er einen ausgewachsenen Tauren von den Hufen reißen kann."},sec={{t="Anspruchsvollere Beute der Savanne",b="Nach den Ebenenschreitern schickt Sergra Dunkeldorn Euch auf die Jagd nach stärkerer Beute. Zhevras ziehen in Herden durch das nördliche und südliche Brachland. Sie sind flink und eigensinnig, gehören aber nicht zu den wildesten Tieren der Savanne. Ihre Tritte können Knochen brechen."},{t="Darkthorns Prüfungen",b="Sergra prüft mit der Jagd Euer wachsendes Können. Sie verlangt vier unversehrte Hufe als Beweis für die erlegte Beute. Der Tritt einer Zhevra mit den Hinterbeinen kann einen ausgewachsenen Tauren auf die Hinterbacken werfen. Besteht Ihr diese Prüfung, rückt die Begegnung mit den räuberischen Streunern der Ebenen näher."}},faq={{q="Wer erteilt diesen Jagdauftrag?",a="Sergra Dunkeldorn, eine erfahrene Orkschamanin am Wegekreuz im zentralen Brachland, stellt aufstrebenden Kriegern der Horde diese Prüfung.",al={"wer vergibt die quest die zhevras","questgeber zhevras","sergra darkthorn quest"}},{q="Wo sind die Zhevras zu finden?",a="Zhevraläufer durchstreifen die offenen Ebenen nördlich und südlich des Wegekreuzes im zentralen Brachland.",al={"wo sind zhevraläufer","zhevra fundort","brachland zhevras karte"}},{q="Warum will Sergra Zhevrahufe?",a="Die Zhevrahufe beweisen, dass Ihr das Tier getötet habt. Bringt Ihr vier zurück, zeigt Ihr, dass Ihr ein Tier bezwungen habt, dessen kräftige Beine selbst einen mächtigen Tauren umwerfen können.",al={"warum zhevrahufe","zhevrahuf beweis","warum zhevras jagen"}},{q="Was folgt auf diese Quest?",a="Nachdem Ihr Euch gegen Zhevras bewiesen habt, prüft Sergra Euch in „Streuner des Brachlandes“ im Kampf gegen die Raubtiere des Brachlands.",al={"nächste quest nach den zhevras","zhevras folgequest","darkthorn nächste quest"}},{q="Sind Zhevras gefährlich?",a="Zhevras sind gewöhnlich friedliche Grasfresser, doch ihre Beine sind kräftig. Sergra warnt, dass ein erschreckter oder in die Enge getriebener Läufer selbst einen stämmigen Tauren mit einem einzigen Tritt zu Boden werfen kann.",al={"wie gefährlich sind zhevras","zhevra gefahr","zhevra tritt"}},{q="Warum wurden zuvor Ebenenschreiter gejagt?",a="Sergra macht ihre Prüfungen Schritt für Schritt schwieriger. Ebenenschreiter sind das erste Ziel; Zhevras sind schnellere und stärkere Beute und bereiten Euch auf den Kampf gegen aggressive Savannenstreuner vor.",al={"vorherige quest","plainstrider menace zusammenhang"}}},fx={["6d2e3590"]={q="Warum will Sergra Dunkeldorn, dass The Zhevra gejagt werden?",a="Sergra Dunkeldorn testet Euer Jagdgeschick und stählt Euch für die brutale Wildnis des Brachlands. Während Steppenläufer grundlegende Zielübungen bieten, sind The Zhevra robustere Bestien, deren kraftvolle Tritte Eure Reflexe und Ausdauer auf die Probe stellen. Indem sie Euch auf sie ansetzt, stellt Sergra sicher, dass Ihr mit gefährlichen Wildtieren umgehen könnt, bevor sie Euch gegen die Spitzenprädatoren des Gebiets aussendet.",al={"warum the zhevra jagen","sergra motiv","sergra darkthorn grund"}},["1cbbdcd0"]={q="Was sind die Zhevra-Läufer?",a="The Zhevra sind schnelle, gestreifte Equiden, die in den trockenen Savannen des Brachlands heimisch sind. Wenn sie in Herden durch die Ebenen nördlich und südlich von Das Wegekreuz ziehen, verlassen sie sich auf Geschwindigkeit und beeindruckende Hinterbeine, um unter Streunern und Raptoren zu überleben. Obwohl sie von Natur aus keine aggressiven Raubtiere sind, können ihre Tritte einen ausgewachsenen Tauren von den Beinen holen.",al={"was sind the zhevra","zhevra-läufer","wen jagen wir"}}},fp="10,144,24.232.0,23.248.0,22.129.0,27.93.0,35.145.0,28.116.0,22.164.0,42.169.0"}
P.entries["quest:846"] = {n="Ganns Rache",s="Im südlichen Brachland bereitet Gann Steinkeil einen Gegenschlag gegen die Zwerge von Bael Modan vor. Nach dem Tod von Prospector Khazgorm schickt er Verbündete der Horde in die Festung, um hochexplosive Munition für seinen Angriff zu erbeuten.",h="Im südlichen Brachland bereitet Gann Steinkeil einen Gegenschlag gegen die Zwerge von Bael Modan vor.",kw={"bael modan","brachland","dynamit","sprengstoffe","gann steinkeil","eisenschmiede","khazgorm","nitroglyzerin","natriumnitrat","holzbrei"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr dabei, die Allianz daran zu hindern, einen militärischen Brückenkopf im südlichen Brachland zu errichten. Ein solcher Brückenkopf könnte die Reisewege zwischen Mulgore, dem Wegekreuz und dem südlichen Grenzgebiet abschneiden.",["profession:Engineering"]="Als Ingenieur erkennt Ihr die klassische Industrieformel der Zwerge: mit Holzbrei stabilisiertes Nitroglyzerin, vermischt mit Natriumnitrat. Gann passt sie für einen ungleichen Kampf an.",["race:Tauren"]="Als Tauren könnt Ihr Bael Modan als schwere Wunde der Earth Mother betrachten. Die Maschinen der Zwerge zu sabotieren, ist eine Pflicht gegenüber Eurem Geist und Eurer Heimat."},sec={{t="Mit ihren eigenen Waffen",b="Gann Steinkeil weiß, dass der Tod von Prospector Khazgorm die Ausgrabungen von Bael Modan nur verlangsamt hat. Die Zwerge werden ihre Arbeit wieder aufnehmen, und bald wird ein anderer Vorarbeiter die Maschinen lenken, die sich durch Ganns angestammtes Land graben. Er wird nicht zusehen, wie die Erde unter weiteren Ausgrabungen leidet. Deshalb will Gann die Sprengausrüstung der Eindringlinge gegen sie wenden und ihre Festung von innen heraus sprengen."},{t="Überfall auf die Festung",b="Die Festung von Bael Modan schützt eine Ausgrabungsbasis und eine Garnison aus Soldaten, Scharfschützen und Offizieren, die die Interessen der Zwerge im Brachland verteidigen. Ihre Verteidiger tragen Nitroglyzerin, Holzbrei und Natriumnitrat für industrielle Sprengungen bei sich. Gann schickt Verbündete der Horde hinter die äußeren Verteidigungslinien, um diese hochexplosiven Vorräte zu erbeuten. Mit genügend Material kann er eine mächtige Sprengtasche zusammenstellen."}},faq={{q="Warum sinnt Gann Steinkeil auf Rache?",a="Die Zwerge aus Eisenschmiede haben bei Bael Modan Ganns angestammte Heimat überrannt, ihren Boden entweiht und sein Volk vertrieben, um ihre Ausgrabungsstätte zu errichten. Nachdem der oberste Ausgrabungsleiter getötet und sein Tagebuch geborgen wurde, will Gann der Zerstörung endgültig ein Ende setzen.",al={"warum ist gann wütend","gann steinkeils beweggrund","was haben die zwerge gann angetan"}},{q="Wo sind die Sprengstoffe zu finden?",a="Die Verteidiger von Bael Modan tragen die Zutaten bei sich. Scharfschützen, Soldaten und Offiziere in und um die befestigte Ausgrabungsstätte im südlichen Brachland haben Nitroglyzerinphiolen, Holzbreibündel und Natriumnitratproben.",al={"wo gibt es nitroglyzerin","wie bekommt man holzbrei","wo ist natriumnitrat"}},{q="Warum braucht Gann Holzbrei und Chemikalien?",a="Die Ausgrabungspläne der Zwerge zeigen, dass Holzbrei das instabile Nitroglyzerin stabilisiert, während Natriumnitrat zur Herstellung eines zuverlässigen industriellen Sprengstoffs beiträgt. Gann will aus der Mischung eine Sprengladung formen, die wichtige Bauwerke der Zwerge zum Einsturz bringen kann.",al={"warum holzbrei","was stellt gann her","zutaten für ganns bombe"}},{q="Was geschieht nach dem Sammeln der Vorräte?",a="Wenn Ihr die Rohstoffe zurückbringt, setzt Gann eine Sprengladung zusammen und schickt Euch los, um die Flugmaschine der Zwerge bei den Ausgrabungen von Bael Modan zu zerstören. Sie ist ein wichtiger Teil der Infrastruktur der Ausgrabungsstätte.",al={"wie geht ganns rache weiter","nach dem sammeln der zutaten"}},{q="Warum beendet Khazgorms Tod die Bedrohung durch die Zwerge nicht?",a="Khazgorm war nur der leitende Ausgrabungsleiter. Die Zwergentruppen von Bael Modan haben sich hinter Verteidigungsmauern und Versorgungslinien verschanzt. Eisenschmiede kann einen anderen Vorarbeiter schicken, um die Ausgrabungen fortzusetzen, sofern die Basis keinen vernichtenden Schlag erleidet.",al={"warum hat khazgorms tod nichts bewirkt","ist bael modan aufgehalten"}},{q="Welche strategische Bedrohung stellt Bael Modan für die Horde dar?",a="Bael Modan war anfangs eine Festung zum Schutz der Ausgrabungsstätte, ist aber zu einem stark besetzten Stützpunkt der Allianz angewachsen. Seine Lage an den Handelsrouten im südlichen Brachland macht es zu einer militärischen Bedrohung für nahe gelegene Siedlungen der Horde in Kalimdor.",al={"warum ist bael modan für die horde wichtig","bedrohung durch bael modan"}}},fx={["410ab5f4"]={q="Wer trägt die für den Sprengstoff benötigten Vorräte?",a="Die Vorräte befinden sich in der Zwergengarnison, die in Bael Modan stationiert ist. Die Schützen, Soldaten und Offiziere innerhalb der Ausgrabung und der Festung nutzen häufig Sprengpulver und Maschinen, um das Land aufzureißen, was bedeutet, dass sie reichlich Vorräte an flüchtigen Chemikalien und Stabilisatoren griffbereit halten.",al={"wer hat die sprengstoffmaterialien","bael modan zwerge","revenge of gann ziele"}},["5f27d24f"]={q="Warum braucht Gann Euch, anstatt Bael Modan selbst anzugreifen?",a="Gann Steinkeil ist ein ausgestoßener Überlebender eines zerschlagenen Stammes, der auf eigene Faust handelt, ohne die Unterstützung einer großen Kriegspartei. Eine ganze befestigte Garnison der Eisenschmiede-Zwerge im Alleingang zu erschlagen, liegt weit außerhalb seiner Reichweite, also verlässt er sich auf einen fähigen Champion der Horde, um in die Festung einzudringen und das zu beschaffen, was er braucht.",al={"warum braucht gann mich","warum kann gann es nicht selbst erledigen","warum ich revenge of gann"}}},fp="15,210,29.372.0,16.376.0,39.259.0,40.216.0,43.251.0,42.200.1,52.222.0,51.231.0"}
P.entries["quest:8462"] = {n="Speak to Nafien",s="Nafien hält außerhalb der Holzschlundfeste im Teufelswald Wache. Ihr sollt die Hauptstraße nach Norden entlangreisen und mit ihm sprechen.",h="Nafien hält außerhalb der Holzschlundfeste im Teufelswald Wache.",kw={"teufelswald","furbolg","hauptstraße","nafien","holzschlundfeste"},sec={{t="Straße nach Norden",b="Im Teufelswald hält Nafien außerhalb des Eingangs zur Holzschlundfeste Wache. Ihr sollt ihn finden, indem Ihr die Hauptstraße nach Norden entlangreist."}},faq={{q="Wer ist Nafien?",a="Nafien ist ein Furbolg, der außerhalb des Eingangs zur Holzschlundfeste Wache hält.",al={"nafien","wer ist nafien"}},{q="Wo finde ich Nafien?",a="Nafien steht außerhalb des Eingangs zur Holzschlundfeste im Teufelswald, an der Hauptstraße nach Norden.",al={"nafien standort","wo ist nafien"}},{q="Was soll ich tun?",a="Reist die Hauptstraße des Teufelswalds nach Norden entlang und sprecht mit Nafien.",al={"mit nafien sprechen","nafien quest"}}},fp="15,124,10.136.0,14.76.0,24.98.0,22.61.0"}
P.entries["quest:8465"] = {n="Speak to Salfa",s="Salfa hält vor der Holzschlundfeste Wache. Ihr sollt die Feste durchqueren und in Winterquell mit ihm sprechen.",h="Salfa hält vor der Holzschlundfeste Wache.",kw={"eingang","wache","salfa","sprechen","holzschlundfeste","winterquell"},sec={{t="An der Feste",b="Vor der Holzschlundfeste wartet Salfa auf Wache. Ihr sollt die Feste durchqueren, in Winterquell wieder herauskommen und dort mit ihm sprechen."}},faq={{q="Wer ist Salfa?",a="Salfa bewacht den Eingang zur Holzschlundfeste.",al={"wer ist salfa"}},{q="Wo finde ich Salfa?",a="Salfa bewacht in Winterquell den Eingang zur Holzschlundfeste.",al={"salfa standort","wo ist salfa"}},{q="Was möchte Salfa, dass ich tue?",a="Ihr sollt die Holzschlundfeste durchqueren, nach Winterquell hinausgehen und mit Salfa sprechen.",al={"aufgabe salfa ansprechen","was tun bei salfa"}}},fp="14,116,11.139.0,13.58.0,23.75.0,30.93.0"}
P.entries["quest:8467"] = {n="Feathers for Nafien",s="Nafien sammelt Federn und freut sich über jede Feder, die Ihr auftreiben könnt. Für Eure Hilfe verspricht er, Euren Einsatz unter seinen Verwandten bekannt zu machen.",h="Nafien sammelt Federn und freut sich über jede Feder, die Ihr auftreiben könnt.",kw={"taten","federn","nafien","opfergaben","ansehen"},sec={{t="Federopfer",b="Nafien sucht Federn in der Wildnis und bietet Euch im Gegenzug Ansehen unter seinen Verwandten. Wann immer Ihr auf diese Federn stoßt, nimmt er sie gerne an und verspricht, dass sich die Kunde von Eurer Hilfe schnell in seiner Gemeinschaft verbreiten wird."}},faq={{q="Wer ist Nafien?",a="Nafien ist ein Wesen, das verspricht, im Austausch gegen Federn bei seinen Verwandten gut von Euren Taten zu sprechen.",al={"wer ist nafien","nafien identität"}},{q="Warum möchte Nafien Federn?",a="Nafien sucht Federn und verspricht, für jedes Bündel, das Ihr ihm bringt, die Kunde von Eurer Hilfe unter seinem Volk zu verbreiten.",al={"warum federn sammeln","zweck der federn","wofür sind federn"}},{q="Nimmt Nafien weitere Federn an?",a="Nafien nimmt so viele Federn an, wie Ihr sammeln könnt, solange sein Volk sie braucht.",al={"mehr federn","kann ich mehr federn bringen","federn wiederholt abgeben"}}},fp="19,177,20.220.0,14.101.0,30.117.0,39.88.0"}
P.entries["quest:847"] = {n="Arglist des Raptors",s="Tor'gans Kugel hat Gor'mul mit der Essenz eines Raptors erfüllt. Die Macht lässt ihn über Schamanenmagie nachdenken, und er wird Tor'gan fürs Erste anhören.",h="Tor'gans Kugel hat Gor'mul mit der Essenz eines Raptors erfüllt.",kw={"arathihochland","gor'mul","arglist des raptors","hammerfall","schamane","tor'gan"},sec={{t="Ein überzeugter Krieger",b="Macht durchströmt Gor'mul, und er fragt sich, ob es die Macht der Schamanen ist, die Tor'gan ihm zu zeigen versuchte. Der Gedanke interessiert ihn. Also bittet er Euch, Tor'gan auszurichten, dass er fürs Erste überzeugt ist und sich anhören wird, was Tor'gan zu sagen hat."},{t="Tor'gans Antwort",b="Tor'gan wird mit Gor'mul sprechen, sobald die Verzauberung nachlässt. Er dankt Euch dafür, dass Ihr geholfen habt, Gor'mul wieder unter die Lebenden zu bringen. Gor'mul ist ebenfalls dankbar, glaubt Tor'gan."}},faq={{q="Wer schickt Euch zu Tor'gan?",a="Gor'mul schickt Euch zu Tor'gan. Nachdem er die Macht der Kugel gespürt hat, bittet er Euch auszurichten, dass er fürs Erste überzeugt ist.",al={"wer startet arglist des raptors drei","wer gibt diese quest","wo beginnt das"}},{q="Warum ändert Gor'mul seine Meinung über Tor'gan?",a="Gor'mul fragt sich, ob die Macht, die er gespürt hat, von den Schamanen stammt, wie Tor'gan ihm zu zeigen versuchte. Der Gedanke interessiert ihn, also ist er fürs Erste überzeugt und wird Tor'gan zuhören.",al={"warum hat gormul seine meinung geändert","gormul schamanenmagie","ist gormul überzeugt"}},{q="Was geschah vor diesem Schritt?",a="Ihr habt Gor'mul im vorherigen Schritt Tor'gans Kugel gebracht.",al={"vorherige quest","voraussetzung arglist des raptors"}}},fp="19,142,19.218.0,15.169.1,36.115.0,47.176.0,27.57.0"}
P.entries["quest:848"] = {n="Pilzsporen",s="An den Oasen des Brachlandes sammeln Abenteurer der Horde Pilzsporen für Apotheker Helbrim von der Königlichen Apothekervereinigung. Seltsame, mutationsfördernde Energien durchströmen die Quellen und verwandeln die örtlichen Pflanzen in wirkungsvolle Reagenzien. Helbrim sucht diese Exemplare, um Gebräue für seine Kollegin in Donnerfels herzustellen.",h="An den Oasen des Brachlandes sammeln Abenteurer der Horde Pilzsporen für Apotheker Helbrim von der...",kw={"apotheker helbrim","apothecary zamah","brachland","das wegekreuz","die vergessenen teiche","pilzsporen","die blühende oase","königliche apothekervereinigung","die brackige oase"},ang={["class:Druid"]="In den Oasen wogt ein unnatürlich aufgewühlter Schwall von Naturmagie, der aggressive Mutationen im umliegenden Ökosystem verursacht.",["faction:Horde"]="Die Untersuchung der gestörten Gewässer des Brachlandes hilft, die lebenswichtigen Wege zwischen Orgrimmar, dem Wegekreuz und Donnerfels zu schützen.",["profession:Herbalism"]="Beladene Pilze rund um die Oasen des Brachlandes zeigen, wie plötzliche Energiezufuhr aus der Umgebung gewöhnliche Pflanzen in wirkungsvolle Reagenzien verwandeln kann.",["race:Undead"]="Fern von Lordaeron setzen Forscher der Verlassenen ihre alchemistische Arbeit fort und nutzen Kalimdors natürliche Anomalien für die Ziele der Königlichen Apothekervereinigung."},sec={{t="Üppige und mutierte Flora",b="Das Brachland ist eine trockene Savanne, doch die Vergessenen Teiche, die Blühende Oase und die Brackige Oase strotzen vor unnatürlichem Leben. Ein seltsamer Schwall von Lebensenergie strömt aus ihren Gewässern, verformt und belebt Pflanzen und Tiere, die dort trinken. Beladene Pilze wachsen an den schlammigen Ufern und nehmen diese Strömungen auf. Ihre Sporen besitzen seltene Eigenschaften, die vorbeiziehende Alchemisten anlocken."},{t="Die Königliche Apothekervereinigung in Kalimdor",b="Apotheker Helbrim arbeitet im Wegekreuz, fern von Unterstadt, bleibt jedoch der Forschung der Königlichen Apothekervereinigung treu. Er sammelt die veränderten Sporen, weil Kalimdors einheimische Reagenzien eine seltsame Wirkkraft besitzen, und stellt daraus mächtige Mixturen her. Die Exemplare sind für Apothekerin Zamah in Donnerfels bestimmt, als Teil der wissenschaftlichen Arbeit der Verlassenen in verbündeten Ländern."}},faq={{q="Wo wachsen diese Pilzsporen?",a="Beladene Pilze wachsen am Wasserrand der Oasen des Brachlandes, darunter die Vergessenen Teiche, die Blühende Oase und die Brackige Oase.",al={"wo pilzsporen finden","pilzsporen fundort","beladene pilze fundort"}},{q="Warum sind die Pilze nahe den Oasen verändert?",a="Ein mächtiger Schwall von Lebensenergie durchströmt die Gewässer der Oasen des Brachlandes. Er verändert die umliegende Tier- und Pflanzenwelt stark, statt lediglich gewöhnliches Pflanzenwachstum zu fördern.",al={"warum sind die pilze mutiert","lebensenergie der oasen","was stimmt mit den oasen nicht"}},{q="Wer ist Apotheker Helbrim?",a="Apotheker Helbrim ist ein verlassener Angehöriger der Königlichen Apothekervereinigung und im Wegekreuz im Brachland stationiert. Er erforscht die ungewöhnliche Biologie der Region und sammelt örtliche Materialien für alchemistische Studien.",al={"helbrims geschichte","wer ist helbrim","apotheker im wegekreuz"}},{q="Was hat Helbrim mit den Sporen vor?",a="Helbrim verwendet die wirkungsvollen Sporen, um ein bestimmtes Gebräu für seine Forschungskollegin Apothekerin Zamah in Donnerfels herzustellen.",al={"wofür sind die sporen","pilzsporen verwendungszweck"}},{q="Warum sind Apotheker der Verlassenen im Brachland tätig?",a="Als Verbündete der Horde erforschen die Verlassenen Kalimdors fremdartige Lebensräume und ungewöhnliche Flora und suchen neue Reagenzien für Arzneien, Gifte und Gebräue.",al={"warum sind untote im brachland","königliche apothekervereinigung in kalimdor"}},{q="In welcher Oase lassen sich die Sporen am sichersten sammeln?",a="An den Vergessenen Teichen nordwestlich vom Wegekreuz leben Wildtiere mit niedrigerer Stufe als an der Blühenden Oase oder der Brackigen Oase im Süden, weshalb sich dort am sichersten Pilze sammeln lassen.",al={"einfachste oase für sporen","sicherste oase im brachland"}}},fx={f81deb18={q="Warum will Apotheker Helbrim, dass die Pilzsporen gesammelt werden?",a="Apotheker Helbrim untersucht die seltsamen Lebensenergien, die durch die Oasen des Brachlands strömen und die umgebende Flora und Fauna mutieren lassen. Die Königliche Apothekervereinigung hält die potenten Eigenschaften dieser veränderten Pilze für ihre Forschung für einzigartig wertvoll. Helbrim benötigt die Exemplare dringend, um ein spezielles Gebräu vorzubereiten, das an seine Mitarbeiterin Apothekerin Zamah weitergeleitet werden muss, die in Donnerfels stationiert ist.",al={"warum will helbrim pilzsporen","helbrim motiv","warum pilzsporen sammeln"}}},fp="13,297,25.365.0,40.385.0,34.129.0,45.170.0,26.205.0,45.124.0,55.155.0,49.175.0"}
P.entries["quest:849"] = {n="Ganns Rache",s="In Bael Modan wendet Gann Steinkeil die Pläne der Zwerge gegen ihre Flugmaschine. Der Agent der Horde sinnt auf Rache für seinen gefallenen Stamm.",h="In Bael Modan wendet Gann Steinkeil die Pläne der Zwerge gegen ihre Flugmaschine.",kw={"bael modan","dynamitstange von gann","flugmaschine","gann steinkeil","khazgorm","stonespire-stamm","brachland","donnerfels"},ang={["faction:Horde"]="Für die Horde schwächt die Ausschaltung der Flugmaschine von Bael Modan eine Waffe der Allianz, die tief im Südlichen Brachland aufklären und zuschlagen kann.",["profession:Engineering"]="Für einen Ingenieur wendet der Sprengsatz Baupläne aus Eisenschmiede in einem geschickten Akt der Sabotage vor Ort gegen einen Gyrokopter.",["race:Tauren"]="Für einen Tauren steht die Zerstörung zwergischer Kriegsmaschinen aus Rache für den Stonespire-Klan im Zeichen der Verteidigung angestammten Landes gegen Entweihung."},sec={{t="Ein Symbol der Vorherrschaft",b="Die zwergische Ausgrabung von Bael Modan erstreckt sich über das angestammte Land der vertriebenen Stonespire-Tauren. Die Prospektoren sind für ihre Reichweite und militärische Stärke auf einen Gyrokopter angewiesen. Er steht auf einem Wachturm über der Ausgrabung, überblickt das Brachland und sichert die Nachschublinien der Zwerge. Für Gann steht die Maschine auch für das Eindringen der Allianz auf kalimdorischen Boden."},{t="Gegen ihre Erbauer gewendet",b="Nachdem Gann Steinkeil die Pläne von Prospector Khazgorm beschafft hat, fertigt er eine spezielle Sprengladung namens Dynamitstange von Gann an. Er bringt sie an der Flugmaschine an und wendet die Erfindung der Zwerge gegen sie selbst. Die Explosion zerstört ein wichtiges militärisches Gerät und demütigt das Kontingent von Bael'dun. Sie ehrt auch die Geister von Ganns verlorenem Stamm."}},faq={{q="Warum will Gann ausgerechnet die Flugmaschine zerstören?",a="Die Flugmaschine stützt die Infrastruktur von Bael Modan und ermöglicht den Zwergen die Luftaufklärung. Für Gann verkörpert sie die Macht der Zwerge und ragt über dem Land auf, das sein abgeschlachteter Stamm einst Heimat nannte.",al={"warum gyrokopter zerstören","zweck der flugmaschine","warum flugmaschine angreifen"}},{q="Wo befindet sich die Flugmaschine in Bael Modan?",a="Die Flugmaschine steht auf einer hölzernen Turmplattform auf halbem Weg die Rampe zur Hauptausgrabungsgrube hinab, abseits der Hauptfestung der Zwerge.",al={"wo ist die flugmaschine","standort der flugmaschine","gyrokopterstandort bael modan"}},{q="Wie hat Gann den Sprengsatz hergestellt?",a="Gann fertigte die Dynamitstange von Gann nach technischen Zeichnungen und Konstruktionsplänen an, die von Prospector Khazgorm erbeutet wurden. Er wandte die Entwürfe der Zwerge gegen sie selbst.",al={"wie wurde die bombe gebaut","herkunft der dynamitstange","khazgorm pläne sprengsatz"}},{q="Welchem Stamm gehört Gann an?",a="Gann gehört zum Stamm der Stonespire, einem Taurenklan, der einst im Südlichen Brachland lebte. Die Zwerge aus Eisenschmiede vertrieben sie für ihre Ausgrabung mit Gewalt und zerstörten ihre Siedlung.",al={"ganns stamm","was ist der stonespire-stamm","wer sind die stonespire-tauren"}},{q="Bringt die Zerstörung der Maschine die Ausgrabung dauerhaft zum Stillstand?",a="Die Zerstörung der Maschine lähmt die Luftstreitkräfte und die Infrastruktur von Bael Modan und verschafft Gann persönliche Rache. Die fest verschanzten zwergischen Ausgräber und die Festung bleiben ein aktiver Stützpunkt der Allianz in der Region.",al={"wird bael modan aufgehalten","fällt bael modan","hat gann gewonnen"}},{q="Welche Anerkennung verspricht Gann nach Abschluss dieser Mission?",a="Gann sagt, der Held, der die Maschine zerstört hat, werde in Donnerfels als Verteidiger heiligen Taurenlandes und bleibender Streiter seines verlorenen Stammes verehrt.",al={"gann abschluss","gann questende","was sagt gann"}}},fx={["947c7a95"]={q="Was ist die Flugmaschine in Bael Modan?",a="Das Ziel ist ein Zwergen-Gyrokopter, der in Bael Modan stationiert ist. Diese Flugmaschine wurde von der Zwergenexpedition gebaut und gewartet und fungiert als lebenswichtige Infrastruktur für ihre Ausgrabung, dient als luftgestützte Kriegswaffe und steht als drohendes Symbol für das Eindringen der Zwerge, das Ganns Volk aus seiner angestammten Heimat vertrieben hat.",al={"bael modan flugmaschine","was ist das ziel in revenge of gann","zwergenflugmaschine bael modan"}}},fp="15,139,22.352.0,22.343.1,62.197.0,50.143.0,41.172.0,31.181.0,60.216.0,61.156.1"}
P.entries["quest:85"] = {n="Die verlorene Halskette",s="Im südlichen Wald von Elwynn sucht Bernice Steinfeld nach ihrer verschwundenen Halskette. Sie verdächtigt Billy Maclure, den jungen Sohn der Familie auf der anderen Straßenseite, und bittet Euch, ihn zu finden.",h="Im südlichen Wald von Elwynn sucht Bernice Steinfeld nach ihrer verschwundenen Halskette.",kw={"bernice","billy","elwynn","hof","maclure","halskette","steinfeld","weinberge"},ang={["faction:Alliance"]="Als Neuling der Allianz im Wald von Elwynn bekommt Ihr einen Vorgeschmack auf das Leben im Grenzland, indem Ihr einen kleinlichen Streit zwischen den zerstrittenen Familien Steinfeld und Maclure schlichtet.",["race:Human"]="Als Mensch seht Ihr, dass die Zwietracht im Königreich Sturmwind nicht nur von Gesetzlosen der Defias und Gnollkriegsbanden ausgeht. Auch alte Streitigkeiten zwischen ländlichen Nachbarn sitzen tief."},sec={{t="Eine nachbarliche Anschuldigung",b="Die Familien Steinfeld und Maclure leben auf benachbarten Ländereien im südlichen Wald von Elwynn, doch zwischen ihnen herrscht wenig Wohlwollen. Als „Tantchen“ Bernice Steinfeld bemerkt, dass ihre geliebte Halskette fehlt, beschuldigt sie den jüngsten Maclure. Überzeugt, dass Billy Maclure auf ihren Hof gekommen ist und sie genommen hat, bittet die verbitterte Witwe Euch, die Straße zu den Weinbergen zu überqueren, den Jungen zu finden und die Rückgabe zu verlangen."},{t="Ein hungriger Junge",b="Auf dem benachbarten Weinberg bestreitet Billy Maclure, die Halskette genommen zu haben, und erklärt, er sei kein Dieb. Mit einem wissenden Grinsen deutet er an, dass er vielleicht weiß, wo sie geblieben ist. Zuerst soll jemand seinen Hunger mit einer frischen Schweinefleischpastete stillen."}},faq={{q="Wer ist Tantchen Bernice Steinfeld?",a="Tantchen Bernice Steinfeld ist eine betagte Witwe, die auf dem Hof der Steinfelds im südlichen Wald von Elwynn lebt. Sie misstraut der benachbarten Familie Maclure, besonders deren jungem Unruhestifter Billy.",al={"wer ist tantchen bernice","bernice steinfeld","wer vergibt die verlorene halskette"}},{q="Hat Billy Maclure die Halskette wirklich gestohlen?",a="Billy Maclure bestreitet entschieden, die Halskette gestohlen zu haben. Er deutet an, dass er weiß, wer sie genommen hat, will sein Wissen aber erst preisgeben, wenn ihm jemand zu essen gibt.",al={"ist billy ein dieb","hat billy sie gestohlen","hat billy die halskette genommen"}},{q="Wo kann ich Billy Maclure finden?",a="Ihr findet Billy Maclure zwischen den Reben in den Weinbergen der Maclures, gleich östlich auf der anderen Straßenseite gegenüber dem Hof der Steinfelds.",al={"billy maclure fundort","wo ist billy","billy maclure finden"}},{q="Warum mögen die Familien Steinfeld und Maclure einander nicht?",a="Die benachbarten Bauernfamilien Steinfeld und Maclure sind seit Jahren in eine erbitterte Fehde verstrickt. Landbesitz, Stolz und alte persönliche Kränkungen halten die Spannungen aufrecht, sodass jede Seite der anderen das Schlimmste zutraut.",al={"familienfehde","fehde steinfeld maclure","warum hassen sie einander"}},{q="Was geschieht nach dem Gespräch mit Billy Maclure?",a="Billy sagt, er sei zu hungrig, um sich zu erinnern, wo die Halskette geblieben ist. Er schickt Euch zurück zu Tantchen Bernice, damit sie ihm im Austausch für die Auskunft eine Schweinefleischpastete backt.",al={"wie geht es weiter","nach der verlorenen halskette","nächste quest"}},{q="Wo spielt diese Quest?",a="Ihr reist durch den südlichen Wald von Elwynn zwischen dem Hof der Steinfelds und den angrenzenden Weinbergen der Maclures.",al={"questgebiet","wo ist die verlorene halskette"}}},fx={b7900c48={q="Warum will Tante Bernice ihre Halskette zurück?",a="Tante Bernice ist eine ältere Witwe, und die Halskette ist ein zutiefst geschätzter persönlicher Besitz. Der Verlust belastet sie sehr, und sie verdächtigt sofort die rivalisierende Familie von nebenan – speziell den jungen Billy Maclure –, sie gestohlen zu haben. Das Wiedererlangen des Erbstücks würde ihr Seelenfrieden bringen und das Herz einer alten Witwe erwärmen.",al={"warum will bernice die halskette","bernice halskettenmotiv","bedeutung stonefield halskette"}},["27b02d6f"]={q="Warum stellt Tante Bernice Billy Maclure nicht selbst zur Rede?",a="Die erbitterte Fehde zwischen den Steinfelds und den Maclures macht es für beide Seiten fast unmöglich, zivilisiert miteinander zu sprechen, ohne einen Streit vom Zaun zu brechen. Bernice kann nicht einfach selbst zu den Weinberge der Maclures hinübergehen, und die Wachen von Sturmwind sind viel zu sehr damit beschäftigt, sich mit Gnollen und Defias-Banditen auseinanderzusetzen, um kleine Streitigkeiten zwischen benachbarten Bauern zu schlichten. Ein vorbeikommender Abenteurer bietet eine neutrale Partei, die den Jungen direkt befragen kann.",al={"warum braucht bernice mich","warum einen abenteurer zu billy schicken","warum nicht die wachen von sturmwind fragen"}}},fp="13,169,23.376.0,22.225.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.102.0"}
P.entries["quest:850"] = {n="Anführer der Kolkar",s="Regthar Totenfurt geht gegen Anführer der Kolkar vor, die im Brachland an Stärke gewinnen. Die nomadischen Zentauren plagen die Tauren seit Generationen. Nun vereinen neue Häuptlinge verstreute Banden zu einer militärischen Bedrohung, und Regthar schickt Streiter der Horde gegen Barak Kodobane bei den Vergessenen Teichen, bevor dessen Einfluss wächst.",h="Regthar Totenfurt geht gegen Anführer der Kolkar vor, die im Brachland an Stärke gewinnen.",kw={"barak","brachland","zentauren","das wegekreuz","deathgate","die vergessenen teiche","kodobane","kolkar","regthar"},ang={["faction:Horde"]="Als Mitglied der Horde seid Ihr auf die Wegkreuzungen des Brachlands angewiesen, die Mulgore, Durotar und entlegene Vorposten der Horde verbinden. Die Führung der Kolkar zu zerschlagen schützt verwundbare Versorgungskarawanen vor verheerenden Hinterhalten.",["race:Orc"]="Als Orc wisst Ihr, dass Thrall die Horde zum Schutz der Tauren verpflichtet hat. Veteranen wie Regthar Totenfurt ehren diesen Blutschwur und betrachten die Kriegstreiber der Zentauren als unmittelbare Bedrohung für die orkische Herrschaft im Brachland.",["race:Tauren"]="Als Tauren bedeutet es für Euch Überleben und Vergeltung, die Befehlshaber der Kolkar niederzustrecken. Jahrzehntelang schlachteten Zentaurenklans Stämme ab und vertrieben die Shu'halo von ihren angestammten Weidegründen, bevor die Horde in Kalimdor Fuß fasste."},sec={{t="Wachsende Gefahr im Ödland",b="Zentauren terrorisieren Kalimdor seit zahllosen Jahren. Bevor Thralls Horde eintraf und das Blatt wendete, trieben sie die nomadischen Tauren beinahe in die Ausrottung. Im Brachland zieht der vorherrschende Stamm der Kolkar gewöhnlich in verstreuten plündernden Banden umher. Nun vereinen angriffslustige Häuptlinge diese Banden und machen die Plünderer stark genug, um die befestigten Vorposten der Horde herauszufordern."},{t="Die Bestie enthaupten",b="Regthar Totenfurt, ein Orc-Krieger, ist in einem Lager westlich vom Wegekreuz stationiert. Er weiß, dass Kühnheit und rohe Gewalt die Kolkar zusammenhalten. Ohne starke Befehlshaber zerfallen ihre Plünderer in innere Streitigkeiten. Deshalb schickt Regthar Streiter der Horde gegen die Anführer, um ihren Vormarsch zu bremsen. Barak Kodobane, ein ehrgeiziger Häuptling, ist das erste Ziel. Er lagert nahe den Gewässern der Vergessenen Teiche."},{t="Der Erste von vielen",b="Barak Kodobanes Tod schwächt die nördlichen Lager der Kolkar. Regthar weiß, dass Barak nur der Erste einer größeren Bewegung ist. Sein Tod eröffnet einen Feldzug gegen die oberste Führung der Kolkar. Als Nächstes folgen die Häuptlinge Verog the Dervish und Hezrul Bloodmark, die verstreut im Brachland lagern."}},faq={{q="Wer ist Barak Kodobane?",a="Barak Kodobane ist ein grimmiger Anführer der Kolkar-Zentauren, der Plünderer um die Vergessenen Teiche nördlich vom Wegekreuz scharte. Seine Gerissenheit und Grausamkeit machten ihn gefährlicher als gewöhnliche nomadische Plünderer. Er vereinte verstreute Klans zu einer Angriffsmacht, die die Horde bedrohte.",al={"barak","wer ist barak","barak kodobane geschichte"}},{q="Wo kann ich Barak Kodobane finden?",a="Barak Kodobane lagert bei den Vergessenen Teichen, einer Oase nördlich vom Wegekreuz im zentralen Brachland. Meist umgeben ihn treue Wachen der Kolkar.",al={"barak aufenthaltsort","wo ist barak","vergessene teiche barak"}},{q="Wer ist Regthar Totenfurt?",a="Regthar Totenfurt ist ein Orc-Veteran in einem kleinen Bunkerlager direkt westlich vom Wegekreuz. Er beobachtet die Bewegungen der Zentauren im Brachland und plant vorbeugende Schläge, um Siedlungen der Horde vor organisierten Überfällen zu schützen.",al={"regthar","wer vergibt anführer der kolkar","regthar deathgate geschichte"}},{q="Warum sind die Kolkar ein solches Problem für die Horde?",a="Die Zentauren führen seit Generationen einen erbarmungslosen Krieg gegen die Tauren und haben sie beinahe ausgerottet. Als Mitglieder der Horde verlassen sich die Tauren auf ihre Verbündeten, um angestammte Jagdgründe und Handelswege im Brachland vor der anhaltenden Ausbreitung der Zentauren zu schützen.",al={"warum kolkar bekämpfen","kolkar bedrohung","zentauren horde feindschaft"}},{q="Was geschieht nach Baraks Tod?",a="Barak Kodobanes Niederlage offenbart, dass andere Häuptlinge andernorts im Brachland Streitkräfte sammeln. Regthar schickt Euch gegen Verog the Dervish bei der Brackigen Oase, dann gegen Hezrul Bloodmark bei der Blühenden Oase. Anschließend muss ein direkter Angriff der Kolkar abgewehrt werden.",al={"nächste quest nach barak","anführer der kolkar folgequest","what comes next"}},{q="Warum sammeln sich die Kolkar um die Oasen?",a="Die Kolkar sammeln sich um Oasen, weil Wasser und fruchtbarer Boden im trockenen Klima des Brachlands kostbar sind. Indem sie Quellen wie die Vergessenen Teiche besetzen, sichern sie sich Wasser und verwehren Reisenden und taurenischen Jägern Rastplätze.",al={"warum sind zentauren bei oasen","kolkar wasser","vergessene teiche zentauren"}}},fx={["55ee765d"]={q="Warum will Regthar Totenfurt, dass die Kolkar Leaders getötet werden?",a="Zentaurenstämme schikanieren die Tauren seit Generationen, aber die Kolkar im Brachland sind normalerweise zersplittert und unorganisiert. Kürzlich haben charismatische Häuptlinge begonnen, die verstreuten Kriegstrupps zu einer vereinten Bedrohung gegen die Siedlungen der Horde zu sammeln. Regthar weiß, dass, wenn man diesen aufstrebenden Kommandeuren erlaubt, sich zu organisieren, der Stützpunkt der Horde im gesamten Brachland zusammenbrechen könnte. Das Eliminieren von Figuren wie Barak Kodobane schlägt den Kopf des Aufstands ab, bevor er die regionalen Verteidigungsanlagen überwältigen kann.",al={"warum kolkar leaders töten","regthar deathgate motiv","warum will regthar dass dies erledigt wird"}},["4347847a"]={q="Wozu dient Kodobanns Kopf?",a="Regthar benötigt einen unbestreitbaren Beweis, dass der Zentaurenkommandeur gefallen ist. An der rauen Grenze des Brachlands reichen Gerüchte und Behauptungen nicht aus, um die Sicherheit zu garantieren. Das Zurückbringen des abgetrennten Kopfes von Barak bestätigt, dass der bei The Forgotten Pools lagernde Kolkar-Kriegstrupp seinen Anführer verloren hat und nicht mehr den Willen besitzt, weitere Angriffe zu koordinieren.",al={"warum baraks kopf","zweck baraks kopf","was mache ich mit baraks kopf"}}},fp="14,323,31.376.0,22.400.0,17.282.1,22.270.0,32.143.0,25.212.0,48.271.0,35.253.1,42.224.0"}
P.entries["quest:851"] = {n="Verog der Derwisch",s="Verog der Derwisch zieht durch das südliche Brachland, während Regthar Totenfurt versucht, ihn hervorzulocken. Der Ork schickt Champions der Horde aus, um das Kommandozelt der Kolkar an der Brackigen Oase anzugreifen und den nomadischen Anführer ins Freie zu locken.",h="Verog der Derwisch zieht durch das südliche Brachland, während Regthar Totenfurt versucht, ihn hervorzulocken.",kw={"brachland","zentauren","das wegekreuz","derwisch","kolkar","regthar deathgate","die brackige oase","verog"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Oasen für das Überleben im trockenen Brachland lebenswichtig sind. Der Sieg über Zentaurenkommandanten hilft, die Wege zu den Wasserquellen für Versorgungskarawanen offen zu halten.",["race:Orc"]="Als Ork wisst Ihr, dass Regthar Totenfurt den Sieg über die Kriegsfürsten der Kolkar für unerlässlich hält, um die Straße zwischen dem Wegekreuz und dem Steinkrallengebirge für Reisende aus Durotar zu sichern.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Kolkar Euer nomadisches Volk seit Generationen auf diesen Ebenen jagten und drangsalierten. Verogs Hinrichtung bringt die lang ersehnte Vergeltung."},sec={{t="Den Derwisch hervorlocken",b="Nachdem Barak Kodobane gefallen war, wandte sich Regthar Totenfurt den verbliebenen Kriegsfürsten der Kolkar zu. Barak hatte sich nahe den nördlichen Gewässern der Vergessenen Teiche aufgehalten, doch Verog durchstreift die sonnenverbrannten Ebenen und bleibt selten lange in einem Lager. Den Spähern der Horde fällt es schwer, ihm durch dieses weite Land zu folgen. Also müssen sie den Kommandanten dazu bringen, zu ihnen zu kommen."},{t="Die Brackige Oase",b="Verog operiert vom Kommandoposten der Kolkar an der Brackigen Oase aus, südöstlich vom Wegekreuz. Regthar schickt Euch gegen das Lager, um die Kolkarkrieger nahe ihrem Kommandozelt anzugreifen. Ihr Alarm ruft Verog zurück, um den Außenposten zu verteidigen. Dort können ihn die Klingen der Horde erreichen."}},faq={{q="Wer ist Verog der Derwisch?",a="Verog der Derwisch führt die Kolkarzentauren im Brachland an. Er befehligt sie von der Brackigen Oase aus, durchstreift aber die südlichen Ödlande und lässt sich nur schwer in die Enge treiben.",al={"wer ist verog","verogs geschichte","verog der derwisch"}},{q="Warum bleibt Verog nicht in seinem Lager?",a="Verog durchstreift das Brachland, statt in einem Lager zu bleiben. Seine Wanderungen erschweren es den Kriegstrupps der Horde, ihn zu finden, also müssen seine Feinde ihn zur Rückkehr reizen.",al={"wo ist verog","warum zieht verog umher","verog verschwunden"}},{q="Wie ruft Ihr Verog herbei?",a="Bedroht Verogs Stamm am Kommandoposten an der Brackigen Oase. Greift die Kolkar nahe ihrem Kommandozelt an, und der Alarm bringt Verog zurück, um es zu verteidigen.",al={"verog erscheinen lassen","verog finden","verog erscheint nicht"}},{q="Wer befiehlt Verogs Tod?",a="Regthar Totenfurt befiehlt Verogs Tod. Der Orkveteran lagert westlich vom Wegekreuz an der Hauptstraße ins Steinkrallengebirge. Er jagt die regionalen Kommandanten der Kolkar einen nach dem anderen.",al={"wer gibt die quest","regthar deathgate"}},{q="Was geschieht, nachdem Verog gefallen ist?",a="Nachdem Verog gefallen ist, bringt Ihr seinen abgeschlagenen Kopf zu Regthar, der ihn neben den von Barak Kodobane legt. Dann wendet sich Regthar Hezrul Bloodmark zu, dem Zentaurenkriegsfürsten an der Blühenden Oase im Süden.",al={"what comes next","nach verog"}},{q="Warum sind die Kolkarzentauren ein so großes Problem im Brachland?",a="Die Kolkar bedrohen das Brachland, indem sie lebenswichtige Wasserquellen beanspruchen und Karawanen, Außenposten sowie die Herden der einheimischen Tauren überfallen. Ihre Angriffe gefährden die noch junge Präsenz der Horde im zentralen Kalimdor.",al={"warum gegen kolkar kämpfen","bedrohung durch kolkar"}}},fx={["42943e7a"]={q="Warum will Regthar Totenfurt, dass Verog getötet wird?",a="Regthar Totenfurt zerschlägt systematisch die Führung der Kolkar-Zentauren, die das nördliche Brachland und Das Wegekreuz bedrohen. Verog the Dervish befehligt den Zentauren-Kriegstrupp, der bei The Stagnant Oasis stationiert ist. Indem er ihn zusammen mit den anderen Kolkar-Häuptlingen eliminiert, will Regthar deren Befehlskette zerschlagen und ihren Griff auf die lebenswichtigen Oasen schwächen, bevor ihre Streitkräfte die Siedlungen der Horde überwältigen können.",al={"warum verog töten","regthar deathgate motiv","warum will regthar verog tot sehen"}},f05e98a6={q="Wozu wird Verogs Kopf verwendet?",a="Regthar Totenfurt nimmt den abgetrennten Kopf von Verog als unbestreitbaren Beweis für den Tod des Derwischs. Er beabsichtigt, ihn zusammen mit Kodobanns Kopf an seinem Außenposten auf einen Pfahl zu spießen, was sowohl als Abrechnung gefallener feindlicher Kommandeure dient als auch als grimmige Warnung an jeden Kolkar, der sich entlang der Straße westlich von Das Wegekreuz nähert.",al={"zweck verogs kopf","was macht regthar mit verogs kopf","warum verogs kopf mitnehmen"}}},fp="17,236,23.334.0,18.273.0,25.141.0,35.159.0,24.147.0,25.187.0,31.193.1,57.195.0"}
P.entries["quest:852"] = {n="Hezrul Blutmal",s="An der Blühenden Oase lenkt Hezrul Blutmal die Vorstöße der Kolkar im gesamten Brachland. Regthar Totenfurt schickt Euch aus, um seiner Herrschaft ein Ende zu setzen und die Macht der Zentauren in der Region zu brechen.",h="An der Blühenden Oase lenkt Hezrul Blutmal die Vorstöße der Kolkar im gesamten Brachland.",kw={"blutmal","zentaur","das wegekreuz","deathgate","hezrul","kolkar","blühende","oase","regthar"},ang={["faction:Horde"]="Als Mitglied der Horde wisst Ihr, dass die Sicherung des Wegekreuzes und des Brachlands bedeutet, die Macht der Zentauren über die drei großen Oasen zu brechen, die Reisen durch die Region ermöglichen.",["race:Orc"]="Als Orc hört Ihr, wie Regthar Totenfurt die Kolkar an der orkischen Kriegskunst misst. Die Zentauren sind wild, doch ihrem ungestümen Zorn fehlt die eiserne Disziplin, die die Horde geschmiedet hat.",["race:Tauren"]="Als Tauren kennt Ihr Generationen brutaler Vertreibung und Blutvergießens durch die Zentauren. Der Sieg über Kriegsherren wie Hezrul bringt hart erkämpfte Vergeltung."},sec={{t="Die Kolkar enthaupten",b="Barak Kodobane und Verog the Dervish sind gefallen. Hezrul Blutmal bleibt der oberste Häuptling der Kolkar im Brachland. Regthar Totenfurt nennt ihn brutal und gerissen, die Speerspitze der Zentaurenvorstöße in der gesamten Savanne. Die Horde hofft, dass sein Tod Chaos stiftet und die Reihen der Kolkar unwiderruflich zerschlägt, bevor sie die Siedlungen der Horde überrennen."},{t="Die Festung der Blühenden Oase",b="Hezrul befehligt seine Kriegstrupps von der Blühenden Oase aus, südlich vom Wegekreuz. Wasserlöcher sind im Brachland selten, daher ist diese Oase überlebenswichtig. Sie ist auch ein strategischer Knotenpunkt und ein Aufmarschgebiet für die Plünderer der Kolkar. Auf Hezruls eigenem Boden entreißt Ihr den Zentauren ihre wichtigste Bastion und brecht ihre Herrschaft über die südlichen Pfade."},{t="Ein gefährliches Nachspiel",b="Regthar lobt Euren Sieg über Hezrul und bemerkt, dass den Zentauren die zielgerichtete Disziplin der Orcs fehlt. Doch die Kolkar zerstreuen sich nicht stillschweigend. Erzürnt sammeln sie ihre verbliebenen Streitkräfte und beginnen einen verzweifelten Großangriff auf Regthars Lager, um blutige Rache zu nehmen."}},faq={{q="Wer ist Hezrul Blutmal?",a="Hezrul Blutmal führt die Kolkarzentauren im gesamten Brachland an. Wild, gerissen und brutal lenkt er ihre Clans und Plünderer von der Blühenden Oase aus.",al={"wer ist hezrul","hezrul blutmal geschichte","zentaurenanführer brachland"}},{q="Wo ist Hezrul Blutmal zu finden?",a="Hezrul patrouilliert mit Leibwächtern der Kolkar an seiner Seite im südlichen Brachland am Ufer der Blühenden Oase, südlich vom Wegekreuz.",al={"wo ist hezrul","hezrul aufenthaltsort","wo hezrul finden"}},{q="Wer vergibt die Quest, Hezrul zu töten?",a="Regthar Totenfurt, ein Orckrieger, erteilt den Befehl in einem kleinen Lager westlich vom Wegekreuz, an der Straße zum Steinkrallengebirge.",al={"wer vergibt hezrul blutmal","regthar deathgate quest","questgeber hezrul"}},{q="Warum will die Horde Hezruls Tod?",a="Die Kolkar bedrohen Handelswege und Siedlungen der Horde. Regthar glaubt, dass der Tod ihres obersten Häuptlings die Einheit des Clans zerbrechen und seine Fähigkeit zur koordinierten Kriegsführung stark schwächen wird.",al={"warum hezrul töten","hezrul blutmal zweck","kolkar bedrohung brachland"}},{q="Was geschieht nach Hezruls Tod?",a="Die überlebenden Kolkar weigern sich, aufzugeben. Sie vereinen sich voller Zorn und beginnen sofort einen Gegenangriff auf Regthar Deathgates Außenposten westlich vom Wegekreuz.",al={"gegenangriff nach hezrul","was geschieht danach","folgen von hezruls tod"}},{q="Wie steht Hezrul zu Barak und Verog?",a="Barak Kodobane und Verog the Dervish führten als untergeordnete Anführer der Kolkar einzelne Oasen und Kriegstrupps. Hezrul Blutmal befehligte den gesamten Clan im Brachland.",al={"barak verog hezrul","kolkar häuptlinge","drei zentaurenanführer"}}},fx={ca31e908={q="Wozu dient Hezruls Kopf?",a="Regthar Totenfurt benötigt Hezruls Kopf als unwiderlegbaren Beweis dafür, dass der oberste Anführer der Kolkar im Brachland gefallen ist. Genau wie bei Barak Kodobane und Verog the Dervish vor ihm, bestätigt das Zurückbringen des abgetrennten Kopfes der Horde, dass die Zentaurenführung gebrochen und die Bedrohung beseitigt wurde.",al={"verwendung hezruls kopf","warum hezruls kopf mitnehmen","hezrul kopf"}}},fp="16,177,23.354.0,24.339.0,21.276.1,24.147.0,36.133.0,35.135.0,36.193.0,35.158.1,42.157.0"}
P.entries["quest:853"] = {n="Apothekerin Zamah",s="In Donnerfels erwartet Apothekerin Zamah ein empfindliches Gebräu aus dem Brachland. Es muss ihr Labor unter der Anhöhe der Geister erreichen, bevor es seine Wirksamkeit verliert.",h="In Donnerfels erwartet Apothekerin Zamah ein empfindliches Gebräu aus dem Brachland.",kw={"apotheker helbrim","apothekerin zamah","pilzsporen","die teiche der visionen","weiterverarbeitete sporen","königliche apothekervereinigung","die anhöhe der geister","brachland","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde helft Ihr, den Nachrichtenfluss und die Versorgung zwischen den Außenposten des Brachlands und dem hohen Tafelberg von Donnerfels aufrechtzuerhalten.",["race:Tauren"]="Als Tauren mögt Ihr die Verlassenen als Verbündete willkommen heißen und zugleich ihre seltsamen Gebräue in den heiligen Teichen der Visionen misstrauisch beäugen.",["race:Undead"]="Als Untoter bringt Ihr Helbrims Arbeit zu Zamah und stärkt das verborgene Forschungsnetz der Königlichen Apothekervereinigung im Grenzland Zentralkalimdors."},sec={{t="Eine empfindliche Fracht",b="Apotheker Helbrim hat Pilzblüten aus den Oasen des Brachlands zu einer empfindlichen Emulsion verarbeitet. Das Gebräu verliert schon bald nach seiner Herstellung an Wirksamkeit. Helbrim kann Mulgore nicht rechtzeitig erreichen, also vertraut er die Phiole einem zuverlässigen Läufer an, der nach Donnerfels aufbricht."},{t="Unter den Blicken der Schamanen",b="Apothekerin Zamah arbeitet in den Teichen der Visionen, einer Höhle unter den heiligen Höhen der Anhöhe der Geister. Magier und Priester der Verlassenen teilen diesen unterirdischen Zufluchtsort. Unter dem Heiligtum der Tauren untersucht die Königliche Apothekervereinigung im Stillen Rohstoffe, die auf dem gesamten Kontinent gesammelt wurden."}},faq={{q="Warum gibt es für diese Lieferung eine Zeitbegrenzung?",a="Helbrims Pilzemulsion ist chemisch instabil. Bleibt sie zu lange ungeschützt oder unbehandelt, zerfallen ihre Verbindungen und verlieren ihre Wirksamkeit, wodurch sie für Zamahs Arbeit unbrauchbar wird.",al={"warum zeitbegrenzung","quest zeitlimit","weiterverarbeitete sporen zeitlimit"}},{q="Wo kann ich Apothekerin Zamah finden?",a="Apothekerin Zamah ist in den Teichen der Visionen in Donnerfels zu finden. Der Höhleneingang liegt verborgen auf der Anhöhe der Geister, unter den Zelten der Schamanen.",al={"wo ist zamah","zamah standort","zamah finden"}},{q="Wer ist Apotheker Helbrim?",a="Apotheker Helbrim ist ein Alchemist der Königlichen Apothekervereinigung, der am Wegekreuz im Brachland stationiert ist. Er untersucht die örtlichen Pflanzen und Tiere, um herauszufinden, wie Kalimdors heimische Lebewesen den Verlassenen dienen könnten.",al={"wer ist helbrim","helbrim wegekreuz"}},{q="Was tut die Königliche Apothekervereinigung in Donnerfels?",a="Die Königliche Apothekervereinigung untersucht in den Teichen der Visionen in Donnerfels im Stillen Proben, die in ganz Kalimdor gesammelt wurden. Die Verlassenen, Verbündete innerhalb der Horde, unterhalten dort Vertreter wie Zamah und pflegen Versorgungsverbindungen zu anderen Außenposten.",al={"warum verlassene in donnerfels","apotheker in den teichen der visionen"}},{q="Wofür wurden die Pilzsporen ursprünglich verwendet?",a="Pilzsporen wachsen rings um die üppigen Oasen des Brachlands und gedeihen in der Wüste. Helbrim kochte sie ein, um ihre biologischen Eigenschaften und alchemistischen Verwendungsmöglichkeiten zu untersuchen, bevor er sie an Zamah schickte.",al={"warum sporen","brachland pilze verwendung"}},{q="Was geschieht, wenn die Zeit abläuft?",a="Wenn die Zeit abläuft, verdirbt die Emulsion und verliert ihre Wirksamkeit. Ihr müsst zu Apotheker Helbrim am Wegekreuz zurückkehren, um eine frische Portion nach Donnerfels zu bringen.",al={"zeitlimit überschritten","sporen abgelaufen"}}},fx={f0da41d1={q="Warum will Apotheker Helbrim, dass die Weiterverarbeitete Sporen so schnell geliefert werden?",a="Apotheker Helbrim hat die seltsamen Pilzsporen, die aus dem Brachland geerntet wurden, erfolgreich zu einer instabilen Emulsion verarbeitet. Das Gemisch zersetzt sich schnell, und nur seine Mitarbeiterin Apothekerin Zamah verfügt in Die Teiche der Visionen über die spezialisierten Reagenzien und Einrichtungen, die erforderlich sind, um es ordnungsgemäß zu stabilisieren, neu zu versiegeln und zu analysieren, bevor seine Potenz für immer verloren geht.",al={"warum sporen an zamah schicken","helbrim motiv","warum will helbrim dass dies geliefert wird"}}},fp="16,153,15.241.0,30.269.0,43.165.0,34.139.0,26.209.0,60.238.0,48.184.0,35.165.0"}
P.entries["quest:854"] = {n="Reise zum Wegekreuz",s="In Camp Taurajo schickt Kirge Sternhorn Reisende nach Norden, um Thork am Wegekreuz zu helfen. Ihr Weg führt von Mulgore ins Brachland, wo sich die Kämpfe der Horde ausweiten.",h="In Camp Taurajo schickt Kirge Sternhorn Reisende nach Norden, um Thork am Wegekreuz zu helfen.",kw={"brachland","camp taurajo","das wegekreuz","earthmother","kirge sternhorn","thork","donnerfels"},ang={["faction:Horde"]="Als Mitglied der Horde seht Ihr, wie die Zusammenarbeit zwischen den Stämmen von Donnerfels und der Vorhut des Kriegshäuptlings im zentralen Kalimdor wächst.",["race:Orc"]="Als Ork wisst Ihr, dass Thork Verstärkung aus dem Süden braucht, um das Gebiet zu halten, das Thralls Späher im ganzen Brachland gesichert haben.",["race:Tauren"]="Als Tauren verlasst Ihr den Schutz der heiligen Hochebene der Earthmother und tretet in die größeren Kämpfe der Horde ein."},sec={{t="Die Wiege verlassen",b="In Camp Taurajo begegnen viele Tauren zum ersten Mal dem Brachland jenseits von Mulgore. Gleich hinter dem Gebirgspass beobachtet der Mystiker Kirge Sternhorn, wie Reisende ins trockene Grasland hinabsteigen. Wenn Kirge jemanden sieht, der bereit ist, weiterzuziehen, weist Kirge nach Norden, die staubige Handelsstraße entlang zum Wegekreuz."},{t="Ein gemeinsames Band",b="Die Tauren von Donnerfels und Thralls neue Horde teilen nun ihr Los. Kirge sagt, ihre Schicksale seien miteinander verbunden, und die Orks am Wegekreuz brauchen Verstärkung, während sie darum kämpfen, einen Außenposten zu errichten. In der Siedlung begrüßt Thork Reisende, die sogar von den hohen Klippen kommen. Er ist bereit, ihre Stärke gegen die Gefahren der Savanne auf die Probe zu stellen."}},faq={{q="Bei wem beginnt Reise zum Wegekreuz?",a="Kirge Sternhorn, ein Taurenmystiker in Camp Taurajo, schickt Reisende nach Norden. Das Lager liegt im südlichen Brachland, gleich östlich des Gebirgspasses von Mulgore.",al={"wer vergibt diese quest","questgeber","kirge sternhorn quest"}},{q="Wo befindet sich Thork?",a="Thork befindet sich innerhalb der Palisaden am Wegekreuz, der Hordensiedlung im zentralen Brachland. Sie liegt nördlich von Camp Taurajo an der Hauptstraße.",al={"wo ist thork","thorks standort","thork finden"}},{q="Warum schickt Kirge Sternhorn Reisende zum Wegekreuz?",a="Kirge Sternhorn sieht einen Reisenden, der für größere Prüfungen bereit ist, und weiß, dass die Schicksale von Tauren und Orks nun miteinander verflochten sind. Die orkische Garnison am Wegekreuz steht durch örtliche Bedrohungen ständig unter Druck und braucht fähige Verbündete.",al={"warum zum wegekreuz","zweck des wegekreuzes","warum zu den orks geschickt"}},{q="Was ist das Wegekreuz?",a="Das Wegekreuz ist der wichtigste strategische Knotenpunkt und Handelsposten der Horde im zentralen Kalimdor. Dort treffen Wege aus Norden und Süden sowie aus Osten und Westen zusammen, und die Siedlung dient als Stützpunkt, um Ordnung ins wilde Grenzland zu bringen.",al={"was ist das wegekreuz","siedlung am wegekreuz","knotenpunkt im brachland"}},{q="Erhalten nur Tauren diese Aufgabe?",a="Ja. Kirge Sternhorn schickt nur Tauren auf diese Reise, heißt Stammesgenossen selbst aus dem fernen Donnerfels willkommen und weist sie an, sich bei Thork zu melden.",al={"ist diese quest nur für tauren","hinführungsquest der horde"}},{q="Welche Gefahren lauern auf dem Weg zum Wegekreuz?",a="Die Straße nach Norden führt durch trockene Ebenen, in denen aggressive Ebenenschreiter, umherstreifende Savannenlöwen und wandernde Gruppen von Razormane-Stachelebern umherziehen. Wer auf dem ausgetretenen Weg bleibt, kann den Raubtieren der zentralen Savanne ausweichen, die ihr Revier besonders erbittert verteidigen.",al={"ist die straße gefährlich","weg von taurajo zum wegekreuz"}}},fx={fc69c860={q="Warum wählt Kirge Sternhorn Euch für diese Reise aus?",a="Kirge Sternhorn sieht Eure Ankunft voraus und erkennt, dass Ihr über lokale Prüfungen hinausgewachsen seid. Da er spürt, dass Ihr für größere Taten in den Ländern der Horde bestimmt seid, sieht er Euch als den richtigen Gesandten, um einen Schritt nach vorne zu machen und Euren Orc-Verbündeten zu helfen.",al={"warum ich journey to the crossroads","warum wählt kirge mich aus","warum mich zum wegekreuz schicken"}}},fp="25,171,18.279.0,13.352.0,37.156.0,23.149.0,58.220.0,23.203.0,33.137.0,52.239.0"}
P.entries["quest:855"] = {n="Zentaurenarmschienen",s="Westlich des Wegekreuzes sucht Regthar Totenfurt Beweise gegen die Kolkar. Ihre Überfälle bedrohen die Kontrolle der Horde über das zentrale Brachland.",h="Westlich des Wegekreuzes sucht Regthar Totenfurt Beweise gegen die Kolkar.",kw={"brachland","kopfgeld","armschienen","zentaur","das wegekreuz","horde","kolkar","regthar deathgate"},ang={["faction:Horde"]="Die Vertreibung der Kolkar schützt die Nachschubverbindungen zwischen Orgrimmar und Donnerfels.",["race:Orc"]="Als Orc helft Ihr, Durotars Grenzen gegen nomadische Angreifer zu sichern und eine dauerhafte, stabile Heimat zu schaffen.",["race:Tauren"]="Als Tauren wisst Ihr, dass die Zentauren seit Jahrhunderten Taurenstämme verheeren und Völkermord an ihnen begehen. Ihre Reihen im Brachland auszudünnen, ist persönliche Vergeltung."},sec={{t="Die Ebenen sichern",b="Die junge Horde sichert noch immer ihre Ländereien in ganz Kalimdor. Das Brachland erstreckt sich zwischen Durotar und Mulgore, wo Kolkarzentauren um Wasserlöcher und offene Ebenen kämpfen. Ihre Angriffe treffen Nachschubzüge und Spähtrupps. Von seinem Bunker westlich des Wegekreuzes aus leitet der Orc-Krieger Regthar Totenfurt die Verteidigung."},{t="Eine grausige Abrechnung",b="Regthar verlangt Beweise dafür, dass Krieger der Kolkar gefallen sind. Soldaten, die das Gebiet der Kolkar betreten, kehren mit Armschienen zurück, die sie getöteten Zentauren abgenommen haben. Diese Trophäen belegen Ansprüche auf Kopfgelder der Horde, und Regthar hofft, dass sie die überlebenden Angreifer einschüchtern."}},faq={{q="Wer ist Regthar Totenfurt?",a="Regthar Totenfurt ist ein Orc-Kommandant in einem befestigten Bunker westlich des Wegekreuzes. Er leitet die Bemühungen der Horde, plündernde Zentauren im gesamten Brachland zurückzudrängen.",al={"wer ist regthar","regthar deathgate hintergrundgeschichte","wer vergibt zentaurenarmschienen"}},{q="Warum will die Horde Zentaurenarmschienen?",a="Zentaurenarmschienen beweisen, dass feindliche Krieger auf dem Schlachtfeld gefallen sind. Regthar stellt damit sicher, dass nur jene Kopfgelder erhalten, die den feindlichen Kolkarstämmen tatsächlich Verluste zufügen.",al={"warum armschienen","wozu dienen zentaurenarmschienen","warum armschienen sammeln"}},{q="Warum greifen die Kolkar die Horde an?",a="Die Kolkar sind ein brutaler Zentaurenklan aus dem zentralen Kalimdor und wollen sich ausbreiten. Sie beanspruchen das Brachland als Jagdgebiet und bekämpfen die neuen Siedlungen, Lager und Bündnisse der Orcs und Tauren.",al={"warum hassen zentauren die horde","zentaurenkonflikt","aggression der kolkar"}},{q="Wo befinden sich die Kolkarzentauren im Brachland?",a="Die Lager der plündernden Kolkar liegen bei Oasen und zerklüfteten Höhenzügen im zentralen und südlichen Brachland. Die Zentauren machen anderen oft den Zugang zu Wasser und den Wegen durch die Region streitig.",al={"wo zentauren finden","standorte der kolkar","zentaurenlager"}},{q="Beendet das Sammeln dieser Armschienen die Angriffe der Kolkar?",a="Nein. Regthar hofft, dass die Verluste die überlebenden Angreifer einschüchtern, doch er bezweifelt, dass die Kolkar ihre Angriffe freiwillig einstellen werden.",al={"haben zentaurenarmschienen gewirkt","hören die zentauren auf"}},{q="Welchen strategischen Wert hat das Wegekreuz?",a="Das Wegekreuz verbindet Durotar, die Taurenebenen von Mulgore und die nördlichen Wege ins Eschental. Siege über Zentaurenkriegstrupps in der Nähe helfen, die Nachschubwege der Horde zu sichern.",al={"warum das wegekreuz verteidigen","bedeutung des wegekreuzes"}}},fx={["566bd14b"]={q="Wer sind die Kolkar-Zentauren, gegen die Ihr kämpfen sollt?",a="Ihr werdet gegen den Kolkar-Clan entsandt, eine brutale Zentaurenrasse, die wichtige Oasen im zentralen und südlichen Brachland beherrscht. Sie sind erbittert territorial und blutrünstig und führen Krieg gegen die Tauren sowie die neu angekommenen Orcs, um die Horde vollständig von den Ebenen Kalimdors zu vertreiben.",al={"wer sind die kolkar","welche zentauren sind im brachland","wer ist das ziel der zentaurenarmschienen"}},["5627e76a"]={q="Warum will Regthar Totenfurt, dass Zentaurenarmschienen gesammelt werden?",a="Regthar Totenfurt betrachtet die Kolkar-Zentauren als direkte Bedrohung für den Stützpunkt der Horde im gesamten Brachland. Indem er ein Kopfgeld auf ihre Armschienen aussetzt, zielt er darauf ab, ihre Kampfreihen durch bloße Zermürbung zu verringern, in der Hoffnung, dass die schweren Verluste Angst in die überlebenden Clans säen und ihre anhaltenden Angriffe abschwächen werden.",al={"warum will regthar armschienen","regthar deathgate motiv","warum zentaurenarmschienen"}}},fp="15,132,19.328.0,21.249.0,25.157.0,40.169.0,39.210.0,53.170.0,54.125.0,46.170.0"}
P.entries["quest:8551"] = {n="Die Truhe des Kapitäns",s="Smotts' verlorene Truhe ist nach einem Schiffbruch nahe Beutebucht bei einem Meerriesen. Kapitän Hecklebury Smotts segelte einst zwischen Beutebucht und Ratschet in Kalimdor. Meerriesen zerstörten sein Schiff und töteten die Besatzung, dann schickten sie ihn in einem Rettungsboot in Richtung Beutebucht. Gorlash nahm seine Captain's Chest an sich, und nun will Smotts sie zurück.",h="Smotts' verlorene Truhe ist nach einem Schiffbruch nahe Beutebucht bei einem Meerriesen.",kw={"beutebucht","gorlash","ratschet","meerriese","smotts","schnupftabakdose","schlingendorntal"},sec={{t="Ein ruinierter Kapitän",b="Kapitän Hecklebury Smotts segelte einst zwischen Beutebucht und Ratschet in Kalimdor und erwarb sich einen guten Ruf. Dann zerschmetterten Meerriesen sein Schiff und töteten die Besatzung. Sie schickten Smotts in einem Rettungsboot in Richtung Beutebucht, und er ließ seine Seereisen und seinen guten Namen hinter sich."},{t="Die gestohlene Truhe",b="Gorlash nahm Smotts' Captain's Chest an sich und sagte, er wolle sie als Schnupftabakdose verwenden. Die Truhe war Smotts' Lieblingstruhe, und ein Geheimfach barg seine größten Schätze. Smotts hat gehört, dass Gorlash an der Küste östlich von Beutebucht umherstreift."},{t="Smotts' Dank",b="Smotts ist überglücklich, seine Truhe zurückzuhaben, und ihre Rückkehr nimmt seinem Zorn etwas von seinem Feuer. Seine Rache ist noch immer nicht vollendet."}},faq={{q="Wer ist Kapitän Hecklebury Smotts?",a="Kapitän Hecklebury Smotts ist ein Schiffskapitän in Beutebucht. Er segelte einst zwischen Beutebucht und Ratschet in Kalimdor, bis Meerriesen sein Schiff zerschmetterten und die Besatzung töteten.",al={"kapitän smotts","wer ist smotts","hecklebury smotts"}},{q="Wer hat die Truhe genommen?",a="Gorlash, einer der Meerriesen, nahm Smotts' Truhe an sich und sagte, er wolle sie als Schnupftabakdose verwenden.",al={"wer hat die truhe gestohlen","wer hat smotts' truhe","gorlash"}},{q="Wo ist Gorlash zu finden?",a="Laut Smotts an der Küste östlich von Beutebucht.",al={"wo ist gorlash","gorlash fundort","gorlash finden"}},{q="Warum will Smotts die Truhe zurück?",a="Smotts will seine Truhe zurück, weil sie seine Lieblingstruhe war und ihr Geheimfach seine größten Schätze barg.",al={"was ist in der truhe","warum will smotts die truhe"}}},fp="19,310,16.259.0,16.224.0,14.125.1,33.170.0,19.87.0,27.55.0,36.112.0"}
P.entries["quest:8552"] = {n="Die Schärpe mit Monogramm",s="Im Schlingendorntal trägt eine verlorene Schärpe Initialen, die zu ihrem Besitzer führen könnten. Die Suche nach dem Seefahrer, der sie verloren hat, führt weiter zu The Captain's Cutlass.",h="Im Schlingendorntal trägt eine verlorene Schärpe Initialen, die zu ihrem Besitzer führen könnten.",kw={"hecklebury smotts","hs","mok'rash","schärpe mit monogramm","meerriese","schlingendorntal"},sec={{t="Ein gekennzeichnetes Kleidungsstück",b="Ihr findet eine feine Schärpe, auf deren Saum die Initialen HS gestickt sind. Diese beiden Buchstaben sind der einzige Hinweis darauf, wer sie verloren hat."},{t="Die Verbindung zu Smotts",b="Als Ihr die Schärpe Kapitän Hecklebury Smotts zurückgebt, bestätigt sich, dass sie ihm gehört. Ihre Rückkehr bringt die Nachricht, dass der Meerriese Mok'rash erschlagen wurde, was dem Kapitän noch unbekannt war. Der Unhold hatte mehr als einmal geholfen, seine Schiffe und seine Mannschaft zu vernichten, und die Nachricht verschafft ihm Erleichterung."}},faq={{q="Welche Buchstaben sind in die Schärpe gestickt?",a="Der Saum der Schärpe trägt die gestickten Initialen HS.",al={"welche initialen stehen auf der schärpe","initialen auf der schärpe mit monogramm","buchstaben auf der schärpe"}},{q="Wohin führt das als Nächstes?",a="Nachdem Ihr die Schärpe ihrem Besitzer zurückgegeben habt, führt der nächste Schritt zu The Captain's Cutlass.",al={"welche quest folgt auf die schärpe mit monogramm","schärpe mit monogramm nächste quest","nächster schritt"}}},fp="20,145,16.120.0,21.255.1,40.49.0,26.85.0"}
P.entries["quest:8553"] = {n="Der Entersäbel des Kapitäns",s="An Bord von Smotts' Revenge erleidet Kapitän Hecklebury Smotts erneut eine Niederlage auf See. Meerriesen zerschmettern sein zweites Schiff, töten die Besatzung und nehmen seinen Entersäbel an sich. Er schickt Euch zu Sprogger, seinem ehemaligen Koch, um das Ungetüm zu finden.",h="An Bord von Smotts' Revenge erleidet Kapitän Hecklebury Smotts erneut eine Niederlage auf See.",kw={"entersäbel","hecklebury smotts","negolash","meerriesen","smotts revenge","sprogger","schlingendorntal"},sec={{t="Ein zweites Unglück",b="Nachdem er sein erstes Schiff verloren hatte, kaufte Kapitän Hecklebury Smotts ein weiteres und nannte es Smotts' Revenge. Er sammelte eine neue Besatzung und Vorräte, um die Meerriesen zu jagen, die sein erstes Schiff erbeutet hatten. Die Riesen zerschmetterten das Schiff und töteten die Besatzung. Wieder trieb Smotts allein in einem Rettungsboot umher, und Negolash nahm bei dem Angriff seinen Entersäbel an sich."},{t="Den Koch befragen",b="Kapitän Hecklebury Smotts will seinen gestohlenen Entersäbel zurück und wendet sich deshalb an Sprogger. Sprogger war der Koch an Bord von Smotts' Revenge und überlebte den Angriff. Er kann Euch helfen, Negolash aufzuspüren."}},faq={{q="Welches Schiff verlor Kapitän Hecklebury Smotts bei diesem Angriff?",a="Kapitän Hecklebury Smotts kaufte Smotts' Revenge und rüstete sie aus, um die Meerriesen zu jagen, die sein erstes Schiff erbeutet hatten. Die Riesen zerstörten auch dieses Schiff.",al={"wie hieß das zweite schiff","smotts zweites schiff","welches schiff wurde zerschmettert"}},{q="Wer stahl den Entersäbel des Kapitäns?",a="Negolash, einer der Meerriesen, nahm den Entersäbel des Kapitäns an sich, als die Riesen Smotts' Revenge zerschmetterten und ihre Besatzung töteten.",al={"wer hat den entersäbel","welcher riese nahm den entersäbel","wer nahm smotts entersäbel"}},{q="Wer ist Sprogger?",a="Sprogger war der Koch an Bord von Smotts' Revenge und überlebte den Angriff, der das Schiff zerstörte. Kapitän Smotts schickt Euch zu ihm, damit er Euch hilft, Negolash aufzuspüren.",al={"wer ist sprogger","sproggers rolle","wer war der koch"}},{q="Wo gehört dieser Schritt in die Jagd auf die Meerriesen?",a="Dieser Schritt folgt auf The Monogrammed Sash und führt direkt zu Facing Negolash.",al={"welche quest kommt davor","was ist die nächste quest","entersäbel questreihe"}}},fp="21,216,17.330.0,19.188.0,60.148.0,32.120.0,16.170.0,58.77.0"}
P.entries["quest:8555"] = {n="Der Bund der Drachenschwärme",s="In Tanaris trifft Anachronos Euch, als der erste Teil des Szepters der Sandstürme zu Ende geht. Die Reihe führt zur Öffnung der Tore von Ahn'Qiraj.",h="In Tanaris trifft Anachronos Euch, als der erste Teil des Szepters der Sandstürme zu Ende geht.",kw={"anachronos","azuregos","eranikus","tore von ahn'qiraj","szepter der sandstürme","tanaris","vaelastrasz"},sec={{t="Das Ende des Anfangs",b="Anachronos trifft Euch in Tanaris, um den ersten Teil des Szepters der Sandstürme abzuschließen. Die Reihe führt zur Öffnung der Tore von Ahn'Qiraj."},{t="Die drei Wächter",b="Anachronos nennt Eranikus, Vaelastrasz und Azuregos als drei Drachen, die über die Welt wachten. Jeder hat durch Diener der Alten Götter oder durch den Verrat jener, die sie Freunde nannten, eine Tragödie erlitten.\n\nAnachronos gesteht, dass seine eigene Naivität ihm eine Mitschuld gab. Diese Ereignisse haben sein Misstrauen gegenüber Sterblichen genährt, weshalb er Euch ausschickt, die drei Drachen zu suchen und Euch auf das Schlimmste vorzubereiten."}},faq={{q="Wer ist Anachronos?",a="Anachronos ist ein Drache des bronzenen Drachenschwarms, dem Ihr in Tanaris begegnet.",al={"wer ist anachronos","anachronos tanaris","bronzener drache"}},{q="Was ist das Szepter der Sandstürme?",a="Das Szepter der Sandstürme ist eine lange Reihe, die zur Öffnung der Tore von Ahn'Qiraj führt. Euer Treffen mit Anachronos schließt ihren ersten Teil ab.",al={"szepter-questreihe","szepter der sandstürme","tore von ahn'qiraj questreihe"}}},fp="31,167,24.155.0,18.387.1,18.75.0,42.155.0"}
P.entries["quest:8569"] = {n="Vergangene Bemühungen in der Kriegshymnenschlucht",s="In der Kriegshymnenschlucht halten Soldaten Eschentals Südgrenze, während Befehlshaber ihre Opfer ehren. Das Ribbon of Sacrifice würdigt standhaften Dienst, selbst wenn die Schlacht keinen klaren Sieg bringt.",h="In der Kriegshymnenschlucht halten Soldaten Eschentals Südgrenze, während Befehlshaber ihre Opfer ehren.",kw={"eschental","brigadier general","orgrimmar","vergangene bemühungen","ribbon of sacrifice","sturmwind","warbringer","kriegshymnenschlucht"},ang={["class:Warrior"]="Als Krieger kennt Ihr den brutalen Nahkampf in der Schlucht. Disziplin bedeutet, erbittert zu kämpfen, selbst wenn der Sieg auf der Kippe steht.",["faction:Alliance"]="Als Soldat der Allianz bekräftigt Ihr mit der Übergabe eines Bandes an einen Brigadier General Euer Versprechen, die uralten Wälder zu verteidigen und Eure nachtelfischen Verbündeten gegen die Aggression von Warsong zu unterstützen.",["faction:Horde"]="Als Mitglied der Horde bekräftigt Ihr mit der Übergabe eines Zeichens an einen Warbringer, dass das für Holz und Überleben in Eschental vergossene Blut nicht umsonst war."},sec={{t="Ehre den Gefallenen und Tapferen",b="An Eschentals Südgrenze liefern sich die Schildwachen der Silberschwingen und die Vorhut des Kriegshymnenklans brutale Scharmützel. Viele Schlachten enden ohne klaren Sieg. Sturmwind, Orgrimmar und andere Hauptstädte ehren jene, die allen Widrigkeiten zum Trotz ihre Stellung halten. Das Ribbon of Sacrifice zeichnet Kämpfer aus, die sich ganz dem Kampf verschrieben haben."},{t="Der Kriegseinsatz in der Heimat",b="Fern der Front beaufsichtigen die Brigadier Generals der Allianz und die Warbringers der Horde ihre Truppen. Rekrutierer schicken neue Kämpfer in die Kriegshymnenschlucht, während Quartiermeister und Taktiker die aus harten Feldzügen heimkehrenden Veteranen erfassen. Indem die Anführer Mut bei einem Patt oder einer Niederlage ehren, stärken sie die Entschlossenheit der Soldaten, Eschental zu halten."}},faq={{q="Welchen Zweck hat diese Auszeichnung?",a="Das Ribbon of Sacrifice ehrt Kämpfer, die in der Kriegshymnenschlucht alles gegeben haben. Befehlshaber in den Hauptstädten nehmen es entgegen, um ihre Ausdauer anzuerkennen und die Moral aufrechtzuerhalten.",al={"warum vergangene bemühungen erledigen","zweck vergangener bemühungen","was bedeutet vergangene bemühungen"}},{q="Wer nimmt diese Zeichen der Opferbereitschaft entgegen?",a="Die Brigadier Generals der Allianz und die Warbringers der Horde nehmen die Zeichen in großen Städten entgegen, darunter Sturmwind und Orgrimmar.",al={"wer nimmt vergangene bemühungen an","wo vergangene bemühungen abgeben","wer ist der brigadier general"}},{q="Warum belohnt das Militär Bemühungen, die nicht zum Sieg geführt haben?",a="Die Kämpfe in Eschentals Wäldern fordern einen hohen Tribut. Die Hingabe der Soldaten zu ehren zeigt, dass ihr Opfer zählt, selbst wenn sie nicht siegen.",al={"warum ribbon of sacrifice belohnen","warum niederlagen belohnen","bedeutung heldenhafter bemühungen"}},{q="Wo spielt sich der Konflikt um die Kriegshymnenschlucht ab?",a="Die Kriegshymnenschlucht liegt an Eschentals Südgrenze. Die Vorhut des Kriegshymnenklans schlägt dort Holz, während die Schildwachen der Silberschwingen ihr Widerstand leisten.",al={"wo liegt die kriegshymnenschlucht","lage der kriegshymnenschlucht","was ist die kriegshymnenschlucht"}},{q="Können Angehörige sowohl der Allianz als auch der Horde dies angehen?",a="Ja. Beide Fraktionen ehren heimkehrende Soldaten durch ihre militärischen Anführer in ihren jeweiligen Hauptstädten.",al={"gilt dies für beide fraktionen","horde oder allianz vergangene bemühungen","kann die horde dies abgeben"}},{q="Wofür steht das Ribbon of Sacrifice?",a="Das Ribbon of Sacrifice ehrt Kämpfer, die heftige Gefechte in der Kriegshymnenschlucht überstanden und weiterhin bereit waren, für ihr Volk zu kämpfen.",al={"hintergrundgeschichte des ribbon of sacrifice","was ist das ribbon of sacrifice","band der opferbereitschaft"}}},fp="29,193,35.318.0,22.329.0,41.158.0,38.119.0,66.147.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="Die Träne der Monde",s="In Bael Modan fleht Feegly der Verbannte noch immer um die Träne der Monde, das Relikt, das ihn in den Wahnsinn trieb.",h="In Bael Modan fleht Feegly der Verbannte noch immer um die Träne der Monde, das Relikt, das ihn in den...",kw={"bael modan","brachland","zwergenfluch","feegly","feegly der verbannte","general twinbraid","träne der monde"},ang={["faction:Horde"]="Ein Angriff auf Bael Modan zur Rückholung des Relikts bietet der Horde die Gelegenheit, die zwergischen Unternehmungen zu stören, die ins Brachland vordringen."},sec={{t="In Bael Modan ausgegraben",b="Zwerge fanden die Träne der Monde, als sie für Bael Modan in den Hügeln des südlichen Kalimdor gruben. Sie war die erste bedeutende Entdeckung der Expedition. Ihr seltsamer Einfluss erfasste sofort Feegly, einen der Arbeiter."},{t="Twinbraids Quarantäne",b="Feegly behauptete, die Träne verleihe ihm gewaltige Macht. Er wandte sich gewaltsam gegen seine Kameraden, um sie zu schützen. General Twinbraid erkannte den verderblichen Einfluss des Relikts, nannte es verflucht, nahm es Feegly ab und schloss es in der Feste ein. Aus dem Ausgrabungslager verbannt, suchte Feegly zwischen den Klippen Zuflucht. Verbittert und besessen fleht er vorbeiziehende Reisende an, die Träne zurückzustehlen."},{t="Der schreckliche Preis",b="General Twinbraids Warnungen bewahrheiten sich, als Feegly die Träne der Monde zurückerlangt. Ihre verborgene Verwandlungsmagie verzehrt ihn und verwandelt den Zwerg in einen wilden Trogg. Nur Sekunden, nachdem er seinen Schatz zurückerlangt hat, stirbt Feegly."}},faq={{q="Was ist die Träne der Monde?",a="Die Träne der Monde ist ein mächtiges Relikt, das zwergische Ausgräber bei ihren frühen Grabungen in Bael Modan im Südlichen Brachland fanden. Sie verdirbt jene, die mit ihr umgehen, und erfüllt sie mit einem berauschenden Verlangen nach Macht.",al={"was ist die träne der monde","träne der monde relikt","bael modan artefakt"}},{q="Wer ist Feegly der Verbannte?",a="Feegly der Verbannte war ein Ausgräber in General Twinbraids Expedition in Bael Modan. Nachdem die Träne der Monde gefunden worden war, wurde er besessen und gewalttätig. Twinbraid verstieß ihn aus der Feste.",al={"wer ist feegly","feegly geschichte","feegly zwerg"}},{q="Warum schließt General Twinbraid die Träne weg?",a="General Twinbraid schloss die Träne weg, weil er sie als gefährlichen Fluch erkannte. Nachdem Feegly sich gegen seine Mitausgräber gewandt hatte, sicherte Twinbraid das Relikt in der Feste von Bael Modan.",al={"warum twinbraid die träne wegschloss","twinbraid fluch","bael modan feste relikt"}},{q="Was geschieht, wenn Ihr Feegly die Träne zurückbringt?",a="Die Rückgabe der Träne erfüllt Feeglys Forderung, doch was darauf folgt, ist noch unbekannt.",al={"was geschieht mit feegly","feeglys ende","die träne zurückbringen"}},{q="Ist die Magie der Träne vollständig verstanden?",a="General Twinbraid nennt die Träne verflucht, während Feegly nach der Macht giert, die sie seiner Überzeugung nach verleiht. Ihre Magie bleibt unerklärt.",al={"magie der träne","träne der monde fluch","wie wirkt die träne"}},{q="Warum ist dies eine Quest der Horde, wenn Feegly ein Zwerg ist?",a="Feegly ist ein Ausgestoßener, der sich im Brachland versteckt und die Streitkräfte der Allianz verachtet, die Bael Modan besetzen. Er bittet Abenteurer der Horde, die Twinbraids Ausgrabung feindlich gegenüberstehen, die Feste zu überfallen und das Relikt zurückzuholen.",al={"warum quest der horde","gehört feegly zur horde","bael modan horde"}}},fx={["76d5a92c"]={q="Warum will Feegly der Verbannte, dass The Tear of the Moons zurückgegeben wird?",a="Feegly ist vollkommen besessen von The Tear of the Moons. Das Artefakt wurde bei Bael Modan ausgegraben und verlieh ihm eine seltsame, berauschende Macht, bevor General Twinbraid es für verflucht erklärte und an sich nahm. Twinbraid verbannte Feegly vollständig von der Ausgrabungsstätte, nachdem es zu gewaltsamen Auseinandersetzungen wegen des Relikts gekommen war. Von Paranoia verzehrt und süchtig nach der Macht, die er kurzzeitig innehatte, ist Feegly verzweifelt darauf aus, das zurückzufordern, was seiner Meinung nach ihm gehört.",al={"warum will feegly the tear","feeglys motiv","warum will feegly der verbannte the tear"}},["7effe162"]={q="Warum bittet Feegly Euch, anstatt The Tear of the Moons selbst zurückzuholen?",a="General Twinbraid hat Feegly gewaltsam aus Bael Modan verbannt und das Artefakt tief im Inneren der Festung weggesperrt. Feegly ist ein Ausgestoßener und bei seinen zwergischen Artgenossen eine unerwünschte Person; sobald er einen Fuß zurück in die Festung setzen würde, würden Twinbraids Wachen ihn verhaften oder niederschlagen. Da er unfähig ist, sein ehemaliges Zuhause allein zu infiltrieren, wendet er sich an einen außenstehenden Abenteurer, der einschleichen und es für ihn stehlen soll.",al={"warum braucht feegly mich","warum kann feegly the tear nicht selbst holen","warum braucht feegly meine hilfe"}}},fp="21,100,23.213.0,22.360.0,17.221.1,30.216.0,25.192.0,46.187.0,48.82.1,37.124.1,47.213.0"}
P.entries["quest:8576"] = {n="Übersetzung des Buchs",s="Ihr bringt Azuregos' Buchführung zu Narain Pfauentraum, der ihre Schrift entziffern muss. Was er herausfindet, könnte Euch der Öffnung der Tore von Ahn'Qiraj näherbringen.",h="Ihr bringt Azuregos' Buchführung zu Narain Pfauentraum, der ihre Schrift entziffern muss.",kw={"arcanite buoy","azuregos","draconic","buchführung","narain pfauentraum","tanaris"},sec={{t="Die Buchführung erreicht Narain",b="Azuregos' Buchführung ist in Euren Händen, und Narain Pfauentraum muss sie entziffern. Ihr bringt ihm die Buchführung, damit er herausfinden kann, was Azuregos geschrieben hat."},{t="Was Narain herausfindet",b="Narain Pfauentraum erfährt, dass Azuregos Euch beauftragt hat, eine arcanite buoy zu bauen, und dass ihr Bauplan in der Buchführung steht. Der Text ist auf Draconic verfasst, was Narain nicht lesen kann. Um ihn zu verstehen, benötigt er die scrying goggles, a chicken of five hundred pounds und den zweiten Band von Draconic for Dummies. Er kann sie in beliebiger Reihenfolge beschaffen."}},faq={{q="Wem gehört die Buchführung?",a="Die Buchführung gehört Azuregos, und Ihr bringt sie zu Narain Pfauentraum.",al={"wem gehört die buchführung","azuregos' buchführung","wer hat die buchführung geschrieben"}},{q="Wer liest die Buchführung?",a="Narain Pfauentraum muss herausfinden, was Azuregos in der Buchführung geschrieben hat.",al={"wer übersetzt die buchführung","narain pfauentraum","wohin die buchführung bringen"}}},fp="22,150,26.140.0,23.326.1,19.64.0,21.66.0"}
P.entries["quest:8577"] = {n="Stewvul, ehemals allerbester Freund",s="Narain kann ohne die scrying goggles nichts übersetzen. Stewvul, sein ehemals allerbester Freund, hat sie, und Ihr müsst sie zurückbringen.",h="Narain kann ohne die scrying goggles nichts übersetzen.",kw={"der greymane-wall","inconspicuous crate","hauptbuch","narain pfauentraum","scrying goggles","silberwald","stewvul","tanaris"},sec={{t="Die gestohlene Brille",b="Narain Pfauentraum kann ohne die scrying goggles nichts übersetzen. Stewvul war einst Narains allerbester Freund, hat sie aber vor einer Weile gestohlen. Dann brach Stewvul Narain das Herz an fünf Stellen und ließ Narain hier zurück."},{t="Wo Ihr suchen müsst",b="Narains Kristallkugel weist auf zwei Orte hin, an denen Stewvul sein könnte. Einer ist der Greymane-Wall im Silberwald. Der andere liegt jenseits eines Portals. Ihr müsst Stewvul finden und die Brille zurückbringen."},{t="Was Stewvul sagt",b="Stewvul kann nicht glauben, dass Narain ihn gefunden hat. Stewvul weigert sich zurückzukehren, weil er es leid ist, nur zeitweise ein Freund und den Rest der Zeit ein Sklave zu sein."}},faq={{q="Warum braucht Narain die scrying goggles?",a="Narain sagt, dass ohne die scrying goggles nichts übersetzt werden kann.",al={"warum brille nötig","narain brille zweck","scrying goggles verwendung"}},{q="Wer ist Stewvul?",a="Stewvul ist Narain Pfauentraums ehemals allerbester Freund. Stewvul stahl die scrying goggles, brach Narain das Herz an fünf Stellen und ließ Narain dann hier zurück.",al={"wer ist stewvul","stewvul geschichte","narain freund"}},{q="Wo vermutet Narain Stewvul?",a="Narains Kristallkugel weist auf zwei mögliche Orte hin: den Greymane-Wall im Silberwald oder eine Welt jenseits eines Portals.",al={"wo ist stewvul","stewvul aufenthaltsorte","der greymane-wall"}},{q="Was kommt davor?",a="Zuvor habt Ihr in Translating the Ledger Azuregos' Hauptbuch zu Narain gebracht.",al={"vorherige quest","voraussetzung","was führt hierzu"}}},fp="18,124,18.223.0,13.191.0,17.140.1,41.66.0,15.154.0,35.112.0,23.79.0"}
P.entries["quest:858"] = {n="Zündung",s="In einem Lager der Venture Company im nördlichen Brachland braucht ein gefangener Pilot den Schlüssel zur Flucht. Der Spion hat einen Schredder ohne dessen Zündschlüssel gekapert und schickt Euch los, um einen vom Aufseher des Geländes zu holen.",h="In einem Lager der Venture Company im nördlichen Brachland braucht ein gefangener Pilot den Schlüssel zur...",kw={"bohrturm","ignition","zündschlüssel","ratschet","schredder","stotterspritter","brachland","venture company","wizzlecrank"},ang={["faction:Horde"]="Die rücksichtslose Abholzung durch die Venture Company bedroht das nördliche Brachland. Ihre schweren Maschinen zu sabotieren oder zu stehlen, behindert diese Arbeiten.",["profession:Engineering"]="Der Schredder der Venture Company verfügt über eine präzise Armsteuerung und schnell ansprechende Rotationsregler, die über die üblichen Tüfteleien in Ratschet hinausgehen."},sec={{t="Ein missglückter Raubzug",b="Stotterspritter schickte einen Spion in einen Schredder der Venture Company auf dem Bohrgelände im nördlichen Brachland. Der Agent will die Maschine stehlen und ihre Funktionsweise studieren. Doch ihre Lenk- und Bewegungssäule bleibt ohne den Zündschlüssel verriegelt."},{t="Bluffen unter Druck",b="Ein Goblinarbeiter hat den regungslosen Schredder bemerkt, also behauptet der Entführer, der Motor sei ausgefallen. Unter der Glaskuppel gefangen und mit Arbeitern in der Nähe weist der Agent Euch zum zentralen Bohrturm. Der Aufseher bewahrt Ersatzzündschlüssel im oberen Kontrollbüro auf. Einer dieser Schlüssel ist der einzige Ausweg für den Piloten, bevor der Bluff auffliegt."},{t="Neid unter Unternehmen",b="Sobald der Schlüssel umgedreht ist, studiert der Dieb die Steuerung des Schredders. Seine Armhebel, Rotationsregler und Stabilitätsdämpfer sind präziser als die der schwerfälligen Maschinen, die von Ratschet aus eingesetzt werden. Die Maschine ist nun eine Beute der Industriespionage und sichert dem Piloten das Überleben."}},faq={{q="Wer sitzt im Schredder?",a="Im Schredder sitzt ein Agent, der mit Stotterspritter, einem Ingenieur in Ratschet, in Verbindung steht. Der Pilot hat sich in den Betrieb der Venture Company eingeschlichen, um eine ihrer fortschrittlichen Rodungsmaschinen zu stehlen.",al={"schredderpilot","wer sitzt in wizzlecranks schredder","wizzlecrank"}},{q="Warum kann der Schredder nicht einfach wegfahren?",a="Die Bewegungssäule des Schredders ist ohne seinen Zündschlüssel verriegelt. Der Entführer hat das Cockpit erreicht, doch die Maschine kann sich erst bewegen, wenn der Schlüssel ihre Fahrsteuerung entriegelt.",al={"warum schlüssel nötig","warum gefangen","schredder verriegelt"}},{q="Wo ist der Zündschlüssel zu finden?",a="Der Aufseher der Venture Company hat den Zündschlüssel. Der Aufseher befindet sich im Kontrollraum oben auf dem nahe gelegenen hölzernen Bohrturm.",al={"fundort zündschlüssel","wo ist der aufseher","wie schlüssel finden"}},{q="Warum will Ratschet einen Schredder der Venture Company?",a="Ratschet will einen Schredder der Venture Company, weil seine Technik die dort üblichen Modelle übertrifft. An einer intakten Maschine könnten die örtlichen Tüftler ihre Armsteuerung, Geschwindigkeitsregler und Stabilitätssysteme studieren.",al={"warum schredder stehlen","ratschet schredder","stotterspritter schredder"}},{q="Wer ist Stotterspritter?",a="Stotterspritter ist ein Gobliningenieur und Agent in Ratschet. Stotterspritter beobachtet die Expansion der Venture Company und ist hinter ihren mechanischen Neuerungen her.",al={"stotterspritter identität","wer hat wizzlecrank geschickt","stotterspritter ratschet"}},{q="Was geschieht, nachdem der Schredder gestartet wurde?",a="Das Umdrehen des Schlüssels entriegelt die Bewegungssysteme des Schredders. Der Pilot versucht dann, die gekaperte Maschine aus dem feindlichen Bohrlager zurück in Sicherheit zu fahren, während ein Geleiteinsatz läuft.",al={"was kommt nach zündung","nach dem zündschlüssel","zündung folgequest"}}},fx={["52fc6a42"]={q="Warum muss Wizzlecrank dies sofort erledigt haben?",a="Wizzlecrank schlich sich in die Bohrstelle der Venture Company, um einen ihrer fortschrittlichen Schredder für Ratschet zu requirieren, nur um festzustellen, dass er ohne den Zündschlüssel im Cockpit gefangen war. Schlimmer noch, als sich ihm ein anderer Arbeiter näherte, geriet er in Panik und behauptete dreist, die Maschine habe einen mechanischen Defekt erlitten. Es ist nur eine Frage der Zeit, bis die Mannschaft zurückkehrt oder seine Lüge durchschaut, was einen stillen Raubüberfall in eine Hinrichtung verwandeln würde, sollte er den Motor nicht starten können und sofort fliehen.",al={"wizzlecranks motiv","warum eilt ignition","warum braucht wizzlecrank den schlüssel"}},edef521b={q="Wer hat den Schlüssel für den Schredder?",a="Der Schlüssel wird vom Aufseher der Venture Company verwahrt, der sich hoch oben im Kontrollraum auf dem Bohrturm befindet. Die Venture Company übt eine rücksichtslose Aufsicht über ihre Holzfäll- und Bohrarbeiten im Brachland aus und hält kritische Kontrollen von gewöhnlichen Arbeitern fern, um Diebstahl und Sabotage zu verhindern. Den Schlüssel zu nehmen bedeutet, ihren Kommandoposten zu infiltrieren und den Aufseher zu konfrontieren, der die gesamte Anlage verwaltet.",al={"wer hat den zündschlüssel","schlüssel des venture co aufsehers"}},e6f51bdb={q="Warum braucht Wizzlecrank Euch, um den Schlüssel zu besorgen, anstatt ihn selbst zu holen?",a="Wizzlecrank sitzt im Cockpit fest, umgeben von misstrauischen Arbeitern der Venture Company. Wenn er aussteigen und über das Lager zum Kommandoturm huschen würde, würde er sofort seine Tarnung auffliegen lassen und das gesamte Arbeitsgelände alarmieren. Er muss drinnen bleiben und so tun, als würde er die defekten Kontrollen überprüfen, während er sich auf einen Außenstehenden verlässt, der in der Lage ist, sich einen Weg zum Sitz des Aufsehers zu bahnen.",al={"warum kann wizzlecrank den schlüssel nicht holen","warum braucht wizzlecrank hilfe","warum ich wizzlecrank"}}},fp="8,200,21.239.0,23.341.0,18.277.1,27.188.0,41.172.0,32.122.0,49.215.0,20.152.0,43.201.1"}
P.entries["quest:8584"] = {n="Fragt mich nie nach meinen Angelegenheiten",s="Narain Pfauentraum schickt Euch nach Gadgetzan, um ein fünfhundert Pfund schweres Huhn zu finden. Im Gasthaus kann Dirge Schnetzelhack Euch den Weg zu einem solchen weisen.",h="Narain Pfauentraum schickt Euch nach Gadgetzan, um ein fünfhundert Pfund schweres Huhn zu finden.",kw={"fünfhundert pfund schweres huhn","black chicken of death","dirge schnetzelhack","gadgetzan","narain pfauentraum","tanaris"},sec={{t="Planen und Beschaffen",b="Narain Pfauentraum will keine weiteren Fragen zu seinen Angelegenheiten hören. Dabei geht es um Dinge jenseits Eures Verständnisses, also behält er den Plan für sich und überlässt Euch das Beschaffen. Er braucht ein fünfhundert Pfund schweres Huhn. Dirge Schnetzelhack im Gasthaus von Gadgetzan kann Euch den Weg zu einem solchen weisen."},{t="Dirges Antwort",b="Dirge Schnetzelhack sagt, dass sich heute kein so schweres Huhn mehr finden lässt. Einst wusste er vom Black Chicken of Death, doch niemand, der diesen Vogel sah, überlebte, um davon zu berichten. Dann schlägt Dirge etwas vor, das für Euch beide gut sein könnte."}},faq={{q="Warum braucht Narain Pfauentraum ein fünfhundert Pfund schweres Huhn?",a="Narain will es nicht sagen. Seine Angelegenheiten betreffen Dinge, die Ihr nicht verstehen könntet, etwa einen psychotronischen Muzzledorf. Er behält die Planung für sich und überlässt Euch das Beschaffen.",al={"warum fünfhundert pfund schweres huhn","narain huhn angelegenheiten","warum will narain ein huhn"}},{q="Mit wem müsst Ihr in Gadgetzan sprechen?",a="Narain schickt Euch zu Dirge Schnetzelhack im Gasthaus von Gadgetzan, um mit der Suche nach einem geeigneten Huhn zu beginnen.",al={"wohin gehen","wen in gadgetzan aufsuchen","wo ist dirge schnetzelhack"}},{q="Was kommt vor dieser Quest?",a="Translating the Ledger kommt zuerst. Narain Pfauentraum spricht danach das Huhn an.",al={"vorausgesetzte quest","welche quest kommt zuerst","vorheriger schritt"}},{q="Wo befindet sich Narain Pfauentraum?",a="Narain Pfauentraum befindet sich in Tanaris.",al={"wo ist narain","narain standort","narain pfauentraum tanaris standort"}}},fp="30,143,21.284.0,14.214.1,61.175.0,40.98.0,29.86.0,35.32.0"}
P.entries["quest:8586"] = {n="Dirges abgefahrene Chimaerokkoteletts",s="In Gadgetzan hat Dirge Schnetzelhack sein Rezept fertig, doch das Fleisch muss bald verarbeitet werden. Er bittet Euch um zwanzigmal Goblin-Raketentreibstoff und zwanzigmal Tiefsteinsalz, bevor es verdirbt.",h="In Gadgetzan hat Dirge Schnetzelhack sein Rezept fertig, doch das Fleisch muss bald verarbeitet werden.",kw={"chimaerok","koteletts","tiefsteinsalz","dirge","gadgetzan","narain","schnetzelhack","raketentreibstoff"},sec={{t="Was Dirge noch braucht",b="Dirge Schnetzelhack kümmert sich selbst um die Gewürze, während das Fleisch, das Ihr ihm gebracht habt, den Rest des Gerichts ausmacht. Er braucht noch zwanzigmal Goblin-Raketentreibstoff und zwanzigmal Tiefsteinsalz. Sobald er beides hat, kann das Huhn zurück zu Narain Pfauentraum. Dirge drängt Euch zur Eile, bevor das Fleisch verdirbt."}},faq={{q="Wer bittet um diese Vorräte?",a="Dirge Schnetzelhack in Gadgetzan bittet Euch um die Vorräte, um sein Rezept zu vollenden.",al={"wer startet diese quest","wer vergibt dirges abgefahrene chimaerokkoteletts","dirge schnetzelhack quest"}},{q="Welche Zutaten braucht Dirge Schnetzelhack?",a="Dirge braucht zwanzigmal Goblin-Raketentreibstoff und zwanzigmal Tiefsteinsalz. Er kümmert sich um die Gewürze, und das Fleisch, das Ihr ihm gebracht habt, deckt den Rest ab.",al={"welche gegenstände werden benötigt","zutaten für dirges koteletts","dirges koteletts gegenstände"}},{q="Für wen ist das fertige Gericht bestimmt?",a="Dirge sagt, das fertige Huhn sei bereit, zu Narain Pfauentraum zurückgebracht zu werden.",al={"wer isst die koteletts","wer bekommt das huhn","für wen ist das essen"}},{q="Was kommt nach der Lieferung dieser Zutaten?",a="Nachdem Ihr die Zutaten abgeliefert habt, kehrt zu Narain Pfauentraum zurück.",al={"nächste quest","was kommt nach dirges koteletts","was folgt auf diese quest"}}},fp="31,172,22.289.0,28.77.0,44.132.0,38.78.0,46.63.0"}
P.entries["quest:8587"] = {n="Rückkehr zu Narain",s="Dirge Schnetzelhack hält sein Wort, und Ihr bringt sein fünfhundert Pfund schweres Huhn zu Narain Pfauentraum in Tanaris. Dirge's Kickin' Chimaerok Chops ging dieser Lieferung voraus.",h="Dirge Schnetzelhack hält sein Wort, und Ihr bringt sein fünfhundert Pfund schweres Huhn zu Narain Pfauentraum...",kw={"fünfhundert pfund schweres huhn","chimaerok","dirge schnetzelhack","narain pfauentraum","tanaris"},sec={{t="Ein Handel wird erfüllt",b="Dirge Schnetzelhack übergibt das versprochene Huhn. Ein Goblin hält sein Wort, sagt er. Er kann sich nicht vorstellen, wozu ein Gnom einen so großen Vogel braucht, und murrt, dass er wohl darin schlafen will. Von dort bringt Ihr das Huhn zu Narain Pfauentraum in Tanaris."},{t="Narains Begrüßung",b="Narain Pfauentraum nimmt den Duft von Dirges Huhn wahr. Er rammt beide Fäuste in den Vogel und stopft sich dann mit Dirges Kochkunst voll. Es ist das beste Huhn, das er je gegessen hat, sagt Narain."}},faq={{q="Was ging dieser Lieferung voraus?",a="Dirge's Kickin' Chimaerok Chops kam zuerst. Dirge Schnetzelhack bat um Raketentreibstoff und Salz, um sein Rezept zu vollenden.",al={"vorherige quest","was habe ich davor gemacht","voraussetzung"}},{q="Wer erhält das riesige Huhn?",a="Narain Pfauentraum erhält das riesige Huhn in Tanaris.",al={"wer bekommt das huhn","zu wem muss das gebracht werden","abgabeort"}},{q="Warum hat Dirge ein fünfhundert Pfund schweres Huhn zubereitet?",a="Dirge hat das fünfhundert Pfund schwere Huhn zubereitet, um sein Wort zu halten und es zu übergeben. Er sagt, er könne sich nicht vorstellen, was ein Gnom mit einem so großen Vogel anfangen will.",al={"warum fünfhundert pfund schweres huhn","wofür ist das huhn","dirges huhn"}},{q="Was folgt nach der Lieferung des Huhns?",a="Danach folgt The Good News and The Bad News. Narain bietet diese Quest erst an, wenn Narains Wahrsagebrille und Drachisch für Dummies: Band 2 abgeschlossen sind.",al={"nächste quest","was folgt danach","wohin als nächstes"}}},fp="16,169,14.251.0,16.190.1,31.113.0,33.58.0,51.148.0,40.142.0"}
P.entries["quest:8597"] = {n="Drachisch für Dummies",s="Narain Pfauentraum will, dass Ihr das Buch findet, das er auf einer Insel in den südlichen Meeren versteckt hat. Findet zuerst seinen abgestürzten Gyrokopter am Landendestrand und schwimmt dann nach Süden. Dies folgt auf Translating the Ledger.",h="Narain Pfauentraum will, dass Ihr das Buch findet, das er auf einer Insel in den südlichen Meeren versteckt...",kw={"drachisch für dummies","frisch ausgehobene erde","gyrokopter","landendestrand","narain pfauentraum","die südlichen meere","tanaris"},sec={{t="Ein verstautes Buch",b="Narain Pfauentraum sagt, das Buch werde sich als nützlich erweisen, und er habe es dort versteckt, wo niemand hoffen könnte, es zu finden. Er nahm einen Gyrokopter, um das Versteck zu erreichen, und stürzte dann auf dem Rückweg am Strand ab. Narain sagt, der Absturz habe ihm seine supergnomischen psychischen Kräfte verliehen.\n\nDas Wrack liegt irgendwo am Landendestrand. Schwimmt von dort aus nach Süden. Narain ist sich sicher, dass Ihr den Ort auf einen Blick erkennen werdet. Das Buch liegt auf einer Insel in den südlichen Meeren vergraben."},{t="Auf der Insel",b="Auf der Insel findet Ihr einen Erdhaufen, doch das Buch ist verschwunden. An seiner Stelle liegt eine Notiz auf dem Haufen."}},faq={{q="Wer schickt Euch los, dieses Buch zu finden?",a="Narain Pfauentraum schickt Euch auf die Suche nach dem Buch, sobald Ihr Translating the Ledger für ihn abgeschlossen habt.",al={"wer vergibt drachisch für dummies","narain questgeber","wer vergibt diese quest"}},{q="Wo ist Narain mit seinem Gyrokopter abgestürzt?",a="Narain sagt, er sei auf dem Rückweg vom Verstecken des Buches an einem Strand abgestürzt. Sein Wrack liegt irgendwo am Landendestrand.",al={"wo ist der gyrokopter","abgestürzter gyrokopter fundort","landendestrand absturz"}},{q="Wo soll das Buch versteckt sein?",a="Narain Pfauentraum sagt, das Buch liege auf einer Insel in den südlichen Meeren vergraben. Schwimmt von seinem Wrack am Landendestrand aus nach Süden; er sagt, Ihr werdet den Ort auf einen Blick erkennen.",al={"buch fundort","wo ist die insel","wohin schwimmen"}},{q="Wie hat Narain seine psychischen Kräfte erhalten?",a="Narain sagt, der Gyrokopterabsturz am Strand habe ihm seine psychischen Kräfte verliehen.",al={"narain psychische kräfte","wie erhielt narain psychische kräfte"}}},fp="20,193,18.441.0,13.101.1,32.90.0,38.120.0,40.172.0,38.74.0"}
P.entries["quest:8598"] = {n="lÖsEGeLd",s="Bei der frisch umgegrabenen Erde in Tanaris fehlt Narain Pfauentraums Buch, und an seiner Stelle wartet ein Erpresserbrief. Ihr bringt den Brief zu Narain zurück, nachdem Ihr in Draconic for Dummies nach dem Buch gesucht habt.",h="Bei der frisch umgegrabenen Erde in Tanaris fehlt Narain Pfauentraums Buch, und an seiner Stelle wartet ein...",kw={"draconic for dummies","frisch umgegrabene erde","narain pfauentraum","lösegeld","erpresserbrief","tanaris"},sec={{t="Eine Nachricht aus Schnipseln",b="Der aus Schriftzeichenschnipseln zusammengesetzte Erpresserbrief teilt Narain Pfauentraum mit, dass seine Verfasser sein kostbares Buch haben. Sie nennen ihn einen Gnom und versprechen, dass er es nur wiedersieht, wenn er ihre Anweisungen genau befolgt. Drei Seiten enthalten ausführliche Anweisungen und enden mit der Forderung, das Geld zu bringen und allein zu kommen. Ihr bringt den Brief zu Narain in Tanaris."},{t="Narains Antwort",b="Narain Pfauentraum fragt, was los ist, und liest dann den Brief. Sein Gesicht läuft knallrot an. Empört darüber, dass jemand sein Buch genommen hat, schwört er, den Schuldigen zu zeigen, was es bedeutet, sich mit einem hellseherischen Gnom anzulegen."}},faq={{q="Was wird im Erpresserbrief gefordert?",a="Die Verfasser behaupten, Narain Pfauentraums Buch zu haben, und versprechen, dass er es nur wiedersieht, wenn er ihre Anweisungen befolgt. Drei Seiten mit Anweisungen enden mit der Forderung nach Geld und danach, dass er allein kommt. Der Brief nennt seine Verfasser nicht.",al={"was steht im brief","text des erpresserbriefs","wer hat das buch genommen"}},{q="Wohin führt dieser Schritt als Nächstes?",a="Nachdem Ihr den Brief zu Narain Pfauentraum in Tanaris gebracht habt, geht die Questreihe mit Decoy! weiter.",al={"was kommt nach lösegeld","fortsetzung von lösegeld","nächste quest nach lösegeld"}},{q="Was geschah vor dem Fund des Erpresserbriefs?",a="Draconic for Dummies kommt zuerst. Ihr sucht nach Narains vergrabenem Buch und erreicht die frisch umgegrabene Erde.",al={"vorherige quest","voraussetzung für lösegeld"}}},fp="6,199,21.346.0,15.198.1,34.234.0,31.91.0,41.103.0"}
P.entries["quest:8599"] = {n="Liebesbrief für Narain",s="Meridith sendet Narain Pfauentraum ihre Liebe, und Ihr bringt ihm ihren Brief nach Tanaris. Sie hat den Gnom aus einer abgestürzten Flugmaschine gerettet und bittet Euch, sein Buch Draconic for Dummies zu suchen.",h="Meridith sendet Narain Pfauentraum ihre Liebe, und Ihr bringt ihm ihren Brief nach Tanaris.",kw={"flugmaschine","liebesbrief","meridith","meerjungfrau","narain pfauentraum","tanaris","trümmer"},sec={{t="Eine Botschaft ans Ufer",b="Meridith die Meerjungfrau hat selten Besucher. Ihr letzter Besucher war der Gnom, den sie aus einer abgestürzten Flugmaschine gerettet hat. Bei der Erinnerung schweift ihr Blick für einen Moment in die Ferne. Dann fragt sie, ob Ihr Narain Pfauentraum kennt. Sie muss ihm sagen, was sie empfindet, und sie ist sicher, dass es Liebe ist. Meridith fleht Euch an, ihm ihre Botschaft zu überbringen, und verspricht, für immer in Eurer Schuld zu stehen."},{t="Narains Antwort",b="Narain Pfauentraum sagt, dass Ihr nach Fisch riecht. Als er erfährt, was in Meridiths Brief steht, wird er unruhig. Sie sei ein Fisch, wendet er ein, und er sei ein Gnom. Er beharrt darauf, dass ihre Liebe niemals funktionieren könne."}},faq={{q="Wer ist Meridith?",a="Meridith ist eine Meerjungfrau, die selten Besucher hat. Ihr letzter Besucher war Narain Pfauentraum, der Gnom, den sie aus einer abgestürzten Flugmaschine gerettet hat.",al={"wer ist meridith","meridith die meerjungfrau","geschichte der meerjungfrau"}},{q="Woher kennt Meridith Narain Pfauentraum?",a="Meridith hat Narain Pfauentraum aus seiner abgestürzten Flugmaschine gerettet. Sie glaubt, in ihn verliebt zu sein.",al={"wie lernte meridith narain kennen","beziehung zwischen narain und meridith","narains flugzeugabsturz"}},{q="Was ist der Liebesbrief?",a="Der Liebesbrief ist Meridiths Botschaft an Narain Pfauentraum, in der sie ihm ihre Gefühle mitteilt. Sie möchte, dass Ihr ihn zu ihm nach Tanaris bringt.",al={"meridiths liebesbrief","liebesbrief an narain","was steht in der botschaft"}},{q="Was ging dieser Bitte voraus?",a="Draconic for Dummies kommt zuerst. Meridith bittet Euch, ihren Brief zu überbringen, während Ihr nach Narains vergrabenem Buch sucht.",al={"vorherige quest","voraussetzung für liebesbrief für narain"}}},fp="20,194,23.355.0,15.188.1,16.141.0,41.105.0,24.133.0,30.108.0"}
